OBSERVATION = {'U': [0, 0, 0, 0], 'D': [3, 2, 0, 0], 'L': [0, 0, 0, 0], 'R': [3, 3, 0, 2]}

from itertools import permutations


def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    nums = tuple(range(1, N + 1))
    all_perms = list(permutations(nums))

    # Precompute visibility for each permutation from both sides.
    perm_vis = {}
    for p in all_perms:
        perm_vis[p] = (visible_count(p), visible_count(p[::-1]))

    # Candidate rows filtered by immediate side clues.
    row_cands = []
    for r in range(N):
        lc = L[r]
        rc = R[r]
        cands = []
        for p in all_perms:
            lv, rv = perm_vis[p]
            if (lc == 0 or lv == lc) and (rc == 0 or rv == rc):
                cands.append(p)
        if not cands:
            return "No Solution"
        row_cands.append(cands)

    # Column clue helpers.
    def prefix_visible_possible(prefix, clue):
        # Human-style forward scan feasibility:
        # with current fixed prefix, current visible count is a lower bound,
        # and adding remaining cells can increase it by at most remaining_len.
        if clue == 0:
            return True
        seen = 0
        mx = 0
        for v in prefix:
            if v is not None and v > mx:
                mx = v
                seen += 1
        rem = sum(v is None for v in prefix)
        return seen <= clue <= seen + rem

    def suffix_visible_possible(prefix, clue):
        # Same test from the opposite side.
        if clue == 0:
            return True
        seq = list(reversed(prefix))
        seen = 0
        mx = 0
        for v in seq:
            if v is not None and v > mx:
                mx = v
                seen += 1
        rem = sum(v is None for v in seq)
        return seen <= clue <= seen + rem

    def exact_column_ok(col_vals, top_clue, bot_clue):
        if len(set(col_vals)) != N:
            return False
        if top_clue and visible_count(col_vals) != top_clue:
            return False
        if bot_clue and visible_count(col_vals[::-1]) != bot_clue:
            return False
        return True

    # Aggressive propagation on row candidates using column-wise deductions.
    def propagate(row_cands_local):
        row_cands_local = [list(c) for c in row_cands_local]

        while True:
            changed = False

            # Cell domains induced by remaining row candidates.
            cell_domains = []
            for r in range(N):
                domains_row = []
                rcands = row_cands_local[r]
                for c in range(N):
                    domains_row.append({p[c] for p in rcands})
                cell_domains.append(domains_row)

            # Naked singles in columns: if a height can only appear in one row of a column.
            forced = {}
            for c in range(N):
                for val in nums:
                    rows_possible = [r for r in range(N) if val in cell_domains[r][c]]
                    if not rows_possible:
                        return None
                    if len(rows_possible) == 1:
                        r = rows_possible[0]
                        forced[(r, c)] = val

            # Filter rows by forced cells, column uniqueness, and clue feasibility.
            for r in range(N):
                old = row_cands_local[r]
                new = []
                for p in old:
                    ok = True

                    # Forced cell placements.
                    for c in range(N):
                        fv = forced.get((r, c))
                        if fv is not None and p[c] != fv:
                            ok = False
                            break
                    if not ok:
                        continue

                    # Column uniqueness feasibility and prefix clue feasibility.
                    for c in range(N):
                        v = p[c]

                        # Another row fixed to same value in same column => impossible.
                        for rr in range(N):
                            if rr == r:
                                continue
                            d = cell_domains[rr][c]
                            if len(d) == 1 and v in d:
                                ok = False
                                break
                        if not ok:
                            break

                        # Build partial column after choosing row r as p.
                        partial = []
                        for rr in range(N):
                            if rr == r:
                                partial.append(v)
                            else:
                                d = cell_domains[rr][c]
                                if len(d) == 1:
                                    partial.append(next(iter(d)))
                                else:
                                    partial.append(None)

                        # Duplicate among fixed values in partial column.
                        fixed = [x for x in partial if x is not None]
                        if len(fixed) != len(set(fixed)):
                            ok = False
                            break

                        if not prefix_visible_possible(partial, U[c]):
                            ok = False
                            break
                        if not suffix_visible_possible(partial, D[c]):
                            ok = False
                            break

                    if ok:
                        new.append(p)

                if not new:
                    return None
                if len(new) != len(old):
                    row_cands_local[r] = new
                    changed = True

            # Hidden singles per cell inside each row candidate set.
            for r in range(N):
                rcands = row_cands_local[r]
                for c in range(N):
                    vals = {p[c] for p in rcands}
                    if not vals:
                        return None
                    if len(vals) == 1:
                        v = next(iter(vals))
                        if any(p[c] != v for p in rcands):
                            row_cands_local[r] = [p for p in rcands if p[c] == v]
                            changed = True

            if not changed:
                break

        # Final consistency check.
        for r in range(N):
            if not row_cands_local[r]:
                return None
        return row_cands_local

    row_cands = propagate(row_cands)
    if row_cands is None:
        return "No Solution"

    # Search with MRV on rows; each branch is still heavily filtered by propagation.
    def search(row_cands_local):
        row_cands_local = propagate(row_cands_local)
        if row_cands_local is None:
            return None

        # Solved when every row is fixed; verify columns exactly.
        if all(len(cands) == 1 for cands in row_cands_local):
            grid = [list(cands[0]) for cands in row_cands_local]
            for c in range(N):
                col = [grid[r][c] for r in range(N)]
                if not exact_column_ok(col, U[c], D[c]):
                    return None
            return grid

        # MRV: choose row with fewest candidates > 1.
        r = min((i for i in range(N) if len(row_cands_local[i]) > 1), key=lambda i: len(row_cands_local[i]))

        # Least-constraining-ish ordering: prefer rows that fit current column domains tightly.
        current_domains = []
        for rr in range(N):
            row_domains = []
            for c in range(N):
                row_domains.append({p[c] for p in row_cands_local[rr]})
            current_domains.append(row_domains)

        def score(p):
            s = 0
            for c, v in enumerate(p):
                s += len(current_domains[r][c])
                # Favor values rarer in the column among this row position.
                freq = sum(1 for rr in range(N) if v in current_domains[rr][c])
                s += freq
            return s

        for p in sorted(row_cands_local[r], key=score):
            nxt = [list(cands) for cands in row_cands_local]
            nxt[r] = [p]
            ans = search(nxt)
            if ans is not None:
                return ans
        return None

    ans = search(row_cands)
    return str(ans) if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

