from functools import lru_cache

# This solver handles the weighted black-cell puzzle:
# - Row i has weight (i+1)
# - Column j has weight (j+1)
# - If cell (i,j) is black, it contributes (j+1) to row i's target
#   and contributes (i+1) to column j's target.
#
# We model each row as a bitmask over columns, and each column as a bitmask over rows.
# Domains are all subset-patterns matching the corresponding weighted target.
# Then we perform aggressive bidirectional propagation between row and column domains,
# plus branch on the most constrained line when needed.


def bit_is_set(mask, idx):
    return (mask >> idx) & 1


@lru_cache(maxsize=None)
def subset_masks_for_sum(weights, target):
    weights = tuple(weights)
    n = len(weights)
    out = []

    def dfs(i, total, mask):
        if total == target:
            out.append(mask)
            return
        if total > target or i == n:
            return
        rem = 0
        for k in range(i, n):
            rem += weights[k]
        if total + rem < target:
            return
        dfs(i + 1, total, mask)
        dfs(i + 1, total + weights[i], mask | (1 << i))

    dfs(0, 0, 0)
    return tuple(out)


def line_support_masks(domain, width):
    any1 = 0
    any0 = 0
    full = (1 << width) - 1
    for m in domain:
        any1 |= m
        any0 |= (~m) & full
        if any1 == full and any0 == full:
            break
    return any0, any1


def filter_domain_by_cell_constraints(domain, must0_mask, must1_mask):
    if must0_mask & must1_mask:
        return None
    new_domain = [m for m in domain if (m & must1_mask) == must1_mask and (m & must0_mask) == 0]
    return new_domain if new_domain else None


def propagate(row_domains, col_domains, n_rows, n_cols):
    # Repeatedly enforce:
    # - each row domain determines cells that must be 0/1 or can be 0/1
    # - each column domain must agree, and vice versa
    while True:
        changed = False

        row_can0 = [0] * n_rows
        row_can1 = [0] * n_rows
        for r in range(n_rows):
            if not row_domains[r]:
                return None
            a0, a1 = line_support_masks(row_domains[r], n_cols)
            row_can0[r], row_can1[r] = a0, a1

        col_can0 = [0] * n_cols
        col_can1 = [0] * n_cols
        for c in range(n_cols):
            if not col_domains[c]:
                return None
            a0, a1 = line_support_masks(col_domains[c], n_rows)
            col_can0[c], col_can1[c] = a0, a1

        # Build per-row must0/must1 from columns.
        for r in range(n_rows):
            must1 = 0
            must0 = 0
            bit_r = 1 << r
            for c in range(n_cols):
                if col_can1[c] & bit_r and not (col_can0[c] & bit_r):
                    must1 |= (1 << c)
                elif col_can0[c] & bit_r and not (col_can1[c] & bit_r):
                    must0 |= (1 << c)
                elif not (col_can0[c] & bit_r) and not (col_can1[c] & bit_r):
                    return None
            nd = filter_domain_by_cell_constraints(row_domains[r], must0, must1)
            if nd is None:
                return None
            if len(nd) != len(row_domains[r]):
                row_domains[r] = nd
                changed = True

        # Recompute row supports after possible row filtering.
        row_can0 = [0] * n_rows
        row_can1 = [0] * n_rows
        for r in range(n_rows):
            if not row_domains[r]:
                return None
            a0, a1 = line_support_masks(row_domains[r], n_cols)
            row_can0[r], row_can1[r] = a0, a1

        # Build per-column must0/must1 from rows.
        for c in range(n_cols):
            must1 = 0
            must0 = 0
            bit_c = 1 << c
            for r in range(n_rows):
                if row_can1[r] & bit_c and not (row_can0[r] & bit_c):
                    must1 |= (1 << r)
                elif row_can0[r] & bit_c and not (row_can1[r] & bit_c):
                    must0 |= (1 << r)
                elif not (row_can0[r] & bit_c) and not (row_can1[r] & bit_c):
                    return None
            nd = filter_domain_by_cell_constraints(col_domains[c], must0, must1)
            if nd is None:
                return None
            if len(nd) != len(col_domains[c]):
                col_domains[c] = nd
                changed = True

        if not changed:
            return row_domains, col_domains


def is_solved(row_domains, col_domains):
    return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)


def choose_branch_line(row_domains, col_domains):
    # Most constrained unresolved line.
    best_kind = None
    best_idx = None
    best_size = None

    for i, d in enumerate(row_domains):
        s = len(d)
        if s > 1 and (best_size is None or s < best_size):
            best_kind, best_idx, best_size = "row", i, s

    for i, d in enumerate(col_domains):
        s = len(d)
        if s > 1 and (best_size is None or s < best_size):
            best_kind, best_idx, best_size = "col", i, s

    return best_kind, best_idx


def domain_value_order(domain, line_len):
    # Prefer patterns with more forced interaction potential:
    # sort by imbalance then popcount, heuristic only.
    vals = list(domain)
    vals.sort(key=lambda m: (abs((m.bit_count() * 2) - line_len), m.bit_count()))
    return vals


def search(row_domains, col_domains, n_rows, n_cols):
    propagated = propagate(row_domains, col_domains, n_rows, n_cols)
    if propagated is None:
        return None
    row_domains, col_domains = propagated

    if is_solved(row_domains, col_domains):
        return row_domains, col_domains

    kind, idx = choose_branch_line(row_domains, col_domains)
    if kind is None:
        return row_domains, col_domains

    if kind == "row":
        values = domain_value_order(row_domains[idx], n_cols)
        for v in values:
            new_rows = [d[:] if i != idx else [v] for i, d in enumerate(row_domains)]
            new_cols = [d[:] for d in col_domains]
            ans = search(new_rows, new_cols, n_rows, n_cols)
            if ans is not None:
                return ans
    else:
        values = domain_value_order(col_domains[idx], n_rows)
        for v in values:
            new_rows = [d[:] for d in row_domains]
            new_cols = [d[:] if i != idx else [v] for i, d in enumerate(col_domains)]
            ans = search(new_rows, new_cols, n_rows, n_cols)
            if ans is not None:
                return ans

    return None


def build_domains(row_sum, col_sum):
    n_rows = len(row_sum)
    n_cols = len(col_sum)
    col_weights = tuple(range(1, n_cols + 1))
    row_weights = tuple(range(1, n_rows + 1))

    row_domains = []
    for tgt in row_sum:
        masks = list(subset_masks_for_sum(col_weights, tgt))
        if not masks:
            return None
        row_domains.append(masks)

    col_domains = []
    for tgt in col_sum:
        masks = list(subset_masks_for_sum(row_weights, tgt))
        if not masks:
            return None
        col_domains.append(masks)

    return row_domains, col_domains


def verify_solution(grid, row_sum, col_sum):
    n_rows = len(grid)
    n_cols = len(grid[0]) if n_rows else 0
    for r in range(n_rows):
        s = 0
        for c in range(n_cols):
            if grid[r][c] == 'B':
                s += c + 1
        if s != row_sum[r]:
            return False
    for c in range(n_cols):
        s = 0
        for r in range(n_rows):
            if grid[r][c] == 'B':
                s += r + 1
        if s != col_sum[c]:
            return False
    return True


def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    n_rows = len(row_sum)
    n_cols = len(col_sum)

    domains = build_domains(row_sum, col_sum)
    if domains is None:
        return "No Solution"

    row_domains, col_domains = domains
    ans = search(row_domains, col_domains, n_rows, n_cols)
    if ans is None:
        return "No Solution"

    solved_rows, solved_cols = ans

    grid = []
    for r in range(n_rows):
        mask = solved_rows[r][0]
        row = []
        for c in range(n_cols):
            row.append('B' if bit_is_set(mask, c) else None)
        grid.append(row)

    if not verify_solution(grid, row_sum, col_sum):
        return "No Solution"

    return repr(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[2, None, 2, 2, None], [None, 3, None, None, None], [3, None, None, 3, None], [None, None, None, 1, None], [3, None, None, 1, 1]]}

from itertools import combinations

def solve(observation):
    data = observation["data"]
    rows = len(data)
    cols = len(data[0]) if rows else 0

    def neighbors(r, c):
        for dr in (-1, 0, 1):
            nr = r + dr
            if nr < 0 or nr >= rows:
                continue
            for dc in (-1, 0, 1):
                nc = c + dc
                if dc == 0 and dr == 0:
                    continue
                if 0 <= nc < cols:
                    yield nr, nc

    clue_cells = []
    all_unknown = set()
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is not None:
                clue_cells.append((r, c, data[r][c]))
            else:
                all_unknown.add((r, c))

    # Variables only matter if adjacent to at least one clue.
    frontier = set()
    clue_to_vars = {}
    var_to_clues = {}
    for r, c, val in clue_cells:
        vs = set()
        for nr, nc in neighbors(r, c):
            if data[nr][nc] is None:
                vs.add((nr, nc))
                frontier.add((nr, nc))
                var_to_clues.setdefault((nr, nc), []).append((r, c))
        clue_to_vars[(r, c)] = vs

    # Cells not touching any clue can safely be non-mines in any valid completion.
    unconstrained = all_unknown - frontier

    # Constraint representation: each clue imposes sum(vars in set) == target.
    constraints = []
    for r, c, val in clue_cells:
        vars_set = frozenset(clue_to_vars[(r, c)])
        constraints.append([set(vars_set), val, (r, c)])

    def propagate(assignments, constraints_local):
        # assignments: dict cell -> 0/1
        changed = True
        while changed:
            changed = False

            # Normalize constraints by removing assigned vars and checking bounds.
            new_constraints = []
            seen_exact = {}
            for vars_set, target, origin in constraints_local:
                rem = set()
                t = target
                for v in vars_set:
                    if v in assignments:
                        t -= assignments[v]
                    else:
                        rem.add(v)

                if t < 0 or t > len(rem):
                    return None, None

                if not rem:
                    if t != 0:
                        return None, None
                    continue

                key = frozenset(rem)
                if key in seen_exact:
                    if seen_exact[key] != t:
                        return None, None
                else:
                    seen_exact[key] = t
                    new_constraints.append([set(rem), t, origin])

            constraints_local = new_constraints

            # Direct single-constraint deductions.
            for vars_set, target, origin in constraints_local:
                if target == 0:
                    for v in list(vars_set):
                        if v in assignments:
                            if assignments[v] != 0:
                                return None, None
                        else:
                            assignments[v] = 0
                            changed = True
                elif target == len(vars_set):
                    for v in list(vars_set):
                        if v in assignments:
                            if assignments[v] != 1:
                                return None, None
                        else:
                            assignments[v] = 1
                            changed = True

            if changed:
                continue

            # Subset-difference deductions: if A subset B, then B-A has target difference.
            # This mirrors common human reasoning on overlapping clue neighborhoods.
            made_subset_progress = False
            n = len(constraints_local)
            for i in range(n):
                Ai, ti, _ = constraints_local[i]
                for j in range(n):
                    if i == j:
                        continue
                    Aj, tj, _ = constraints_local[j]
                    if Ai == Aj:
                        if ti != tj:
                            return None, None
                        continue
                    if Ai.issubset(Aj):
                        diff = Aj - Ai
                        td = tj - ti
                        if td < 0 or td > len(diff):
                            return None, None
                        if not diff:
                            continue
                        if td == 0:
                            for v in diff:
                                if v in assignments:
                                    if assignments[v] != 0:
                                        return None, None
                                else:
                                    assignments[v] = 0
                                    made_subset_progress = True
                        elif td == len(diff):
                            for v in diff:
                                if v in assignments:
                                    if assignments[v] != 1:
                                        return None, None
                                else:
                                    assignments[v] = 1
                                    made_subset_progress = True

            if made_subset_progress:
                changed = True

        return assignments, constraints_local

    # Build connected components of frontier variables via shared constraints.
    frontier_list = sorted(frontier)
    visited = set()
    components = []

    for start in frontier_list:
        if start in visited:
            continue
        stack = [start]
        comp_vars = set()
        comp_clues = set()
        visited.add(start)
        while stack:
            v = stack.pop()
            comp_vars.add(v)
            for clue_pos in var_to_clues.get(v, []):
                if clue_pos not in comp_clues:
                    comp_clues.add(clue_pos)
                    for nv in clue_to_vars[clue_pos]:
                        if nv not in visited:
                            visited.add(nv)
                            stack.append(nv)
        components.append((comp_vars, comp_clues))

    clue_value = {(r, c): val for r, c, val in clue_cells}

    def component_constraints(comp_vars, comp_clues):
        cons = []
        for clue_pos in comp_clues:
            vars_set = set(v for v in clue_to_vars[clue_pos] if v in comp_vars)
            cons.append([vars_set, clue_value[clue_pos], clue_pos])
        return cons

    def choose_branch_var(assignments, constraints_local):
        score = {}
        for vars_set, target, _ in constraints_local:
            span = len(vars_set)
            tightness = min(target, span - target)
            weight = (10 - tightness, span)
            for v in vars_set:
                if v not in assignments:
                    score[v] = score.get(v, 0) + 1_000 - 20 * span + 5 * tightness
        if not score:
            return None
        return max(score, key=score.get)

    def search_component(comp_vars, comp_cons):
        initial_assignments = {}
        pr = propagate(initial_assignments, [[set(vs), t, o] for vs, t, o in comp_cons])
        if pr == (None, None):
            return None
        assignments, constraints_local = pr

        memo = {}

        def state_key(assignments, constraints_local):
            akey = tuple(sorted(assignments.items()))
            ckey = tuple(sorted((tuple(sorted(vs)), t) for vs, t, _ in constraints_local))
            return (akey, ckey)

        def dfs(assignments, constraints_local):
            key = state_key(assignments, constraints_local)
            if key in memo:
                return memo[key]

            if not constraints_local:
                result = dict(assignments)
                memo[key] = result
                return result

            var = choose_branch_var(assignments, constraints_local)
            if var is None:
                result = dict(assignments)
                memo[key] = result
                return result

            # Prefer the more constrained value first based on local clues.
            pref = [1, 0]
            mine_bias = 0
            clear_bias = 0
            for vars_set, target, _ in constraints_local:
                if var in vars_set:
                    rem_assigned = sum(assignments.get(v, 0) for v in vars_set if v in assignments)
                    rem_unknown = sum(1 for v in vars_set if v not in assignments)
                    need = target - rem_assigned
                    if rem_unknown > 0:
                        mine_bias += need / rem_unknown
                        clear_bias += (rem_unknown - need) / rem_unknown
            if clear_bias > mine_bias:
                pref = [0, 1]

            for val in pref:
                new_assign = dict(assignments)
                new_assign[var] = val
                pr2 = propagate(new_assign, [[set(vs), t, o] for vs, t, o in constraints_local])
                if pr2 == (None, None):
                    continue
                res = dfs(*pr2)
                if res is not None:
                    memo[key] = res
                    return res

            memo[key] = None
            return None

        return dfs(assignments, constraints_local)

    final_assignments = {}

    for comp_vars, comp_clues in components:
        cons = component_constraints(comp_vars, comp_clues)
        res = search_component(comp_vars, cons)
        if res is None:
            return "No Solution"
        final_assignments.update(res)

    # Any unconstrained unknown cells are guaranteed safe in a clue-consistent completion.
    for v in unconstrained:
        final_assignments[v] = 0

    # Final verification against all clues.
    for r, c, val in clue_cells:
        count = 0
        for nr, nc in neighbors(r, c):
            if data[nr][nc] is None and final_assignments.get((nr, nc), 0) == 1:
                count += 1
        if count != val:
            return "No Solution"

    answer = []
    for r in range(rows):
        row = []
        for c in range(cols):
            if data[r][c] is None and final_assignments.get((r, c), 0) == 1:
                row.append('F')
            else:
                row.append(None)
        answer.append(row)

    return str(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [0, 0, 0, 0], 'D': [0, 0, 0, 0], 'L': [0, 0, 2, 0], 'R': [0, 1, 0, 3]}

from itertools import permutations


def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c


def clue_ok(seq, left_clue=0, right_clue=0):
    if left_clue and visible_count(seq) != left_clue:
        return False
    if right_clue and visible_count(seq[::-1]) != right_clue:
        return False
    return True


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    nums = tuple(range(1, N + 1))
    all_perms = list(permutations(nums))

    # Precompute permutation buckets by (left,right) visibility.
    by_lr = {}
    for p in all_perms:
        key = (visible_count(p), visible_count(p[::-1]))
        by_lr.setdefault(key, []).append(p)

    def perms_for_row(lc, rc):
        if lc == 0 and rc == 0:
            return all_perms[:]
        out = []
        for p in all_perms:
            if clue_ok(p, lc, rc):
                out.append(p)
        return out

    row_cands = [perms_for_row(L[r], R[r]) for r in range(N)]
    if any(not c for c in row_cands):
        return "No Solution"

    # Column clue feasibility cache.
    col_prefix_cache = {}

    def col_prefix_feasible(col, prefix):
        key = (col, prefix)
        if key in col_prefix_cache:
            return col_prefix_cache[key]

        used = set(prefix)
        if len(used) != len(prefix):
            col_prefix_cache[key] = False
            return False

        up = U[col]
        down = D[col]
        rem_vals = [v for v in nums if v not in used]
        k = len(prefix)

        # Quick lower/upper checks for top clue using the current prefix only.
        seen = 0
        mx = 0
        for x in prefix:
            if x > mx:
                mx = x
                seen += 1
        max_extra = len(rem_vals)
        if up:
            if seen > up:
                col_prefix_cache[key] = False
                return False
            if seen + max_extra < up:
                col_prefix_cache[key] = False
                return False

        # If no clue on either side, Latin uniqueness is enough.
        if not up and not down:
            col_prefix_cache[key] = True
            return True

        # Exact feasibility on the remaining values; N is small in these puzzles.
        feasible = False
        for tail in permutations(rem_vals):
            full = prefix + tail
            if clue_ok(full, up, down):
                feasible = True
                break

        col_prefix_cache[key] = feasible
        return feasible

    def propagate(cands):
        changed = True
        while changed:
            changed = False

            # Cell-wise support pruning from row candidates.
            cell_vals = [[set() for _ in range(N)] for _ in range(N)]
            for r in range(N):
                for p in cands[r]:
                    for c in range(N):
                        cell_vals[r][c].add(p[c])

            # Remove row permutations that place unsupported values anywhere.
            for r in range(N):
                new_list = []
                for p in cands[r]:
                    ok = True
                    for c in range(N):
                        if p[c] not in cell_vals[r][c]:
                            ok = False
                            break
                    if ok:
                        new_list.append(p)
                if not new_list:
                    return None
                if len(new_list) != len(cands[r]):
                    cands[r] = new_list
                    changed = True

            # Column uniqueness support: each value must be placeable in some row.
            for c in range(N):
                val_rows = {v: [] for v in nums}
                for r in range(N):
                    vals = set(p[c] for p in cands[r])
                    for v in vals:
                        val_rows[v].append(r)
                for v in nums:
                    if not val_rows[v]:
                        return None

            # If a row is fixed, remove its column values from other fixed-impossible positions
            # via direct permutation filtering.
            fixed_rows = [cands[r][0] if len(cands[r]) == 1 else None for r in range(N)]
            for r in range(N):
                new_list = []
                for p in cands[r]:
                    ok = True
                    for rr in range(N):
                        if rr != r and fixed_rows[rr] is not None:
                            for c in range(N):
                                if p[c] == fixed_rows[rr][c]:
                                    # same value in same column forbidden
                                    ok = False
                                    break
                            if not ok:
                                break
                    if ok:
                        new_list.append(p)
                if not new_list:
                    return None
                if len(new_list) != len(cands[r]):
                    cands[r] = new_list
                    changed = True

            # Prefix-based column clue pruning using fixed rows only.
            order_fixed = [r for r in range(N) if len(cands[r]) == 1]
            if order_fixed:
                prefixes = [[] for _ in range(N)]
                for r in order_fixed:
                    p = cands[r][0]
                    for c in range(N):
                        prefixes[c].append(p[c])

                for c in range(N):
                    prefix = tuple(prefixes[c])
                    if len(set(prefix)) != len(prefix):
                        return None
                    if not col_prefix_feasible(c, prefix):
                        return None

            # Column-based support pruning from exact row candidate interactions.
            for c in range(N):
                possible_by_row = [set(p[c] for p in cands[r]) for r in range(N)]
                for r in range(N):
                    new_list = []
                    for p in cands[r]:
                        v = p[c]
                        # Check Hall-lite support: value v cannot already be forced in another fixed row at same column.
                        bad = False
                        for rr in range(N):
                            if rr != r and len(cands[rr]) == 1 and cands[rr][0][c] == v:
                                bad = True
                                break
                        if not bad:
                            new_list.append(p)
                    if not new_list:
                        return None
                    if len(new_list) != len(cands[r]):
                        cands[r] = new_list
                        changed = True

        return cands

    def choose_row(cands):
        best_r = None
        best_n = 10**9
        for r in range(N):
            k = len(cands[r])
            if 1 < k < best_n:
                best_n = k
                best_r = r
        return best_r

    def partial_columns_ok(assignments):
        rows_done = sorted(assignments)
        for c in range(N):
            prefix = tuple(assignments[r][c] for r in rows_done)
            if len(set(prefix)) != len(prefix):
                return False
            if not col_prefix_feasible(c, prefix):
                return False
        return True

    def final_grid_ok(grid):
        for r in range(N):
            if sorted(grid[r]) != list(nums):
                return False
            if not clue_ok(grid[r], L[r], R[r]):
                return False
        for c in range(N):
            col = [grid[r][c] for r in range(N)]
            if sorted(col) != list(nums):
                return False
            if not clue_ok(col, U[c], D[c]):
                return False
        return True

    row_cands = propagate(row_cands)
    if row_cands is None:
        return "No Solution"

    def dfs(cands, assignments):
        cands = [lst[:] for lst in cands]
        cands = propagate(cands)
        if cands is None:
            return None

        complete = all(len(lst) == 1 for lst in cands)
        if complete:
            grid = [list(lst[0]) for lst in cands]
            return grid if final_grid_ok(grid) else None

        r = choose_row(cands)
        if r is None:
            return None

        # Value ordering: prefer permutations that are most column-compatible.
        scored = []
        for p in cands[r]:
            score = 0
            for c in range(N):
                for rr in range(N):
                    if rr != r:
                        score += sum(1 for q in cands[rr] if q[c] != p[c])
            scored.append((score, p))
        scored.sort(reverse=True)

        for _, p in scored:
            new_cands = [lst[:] for lst in cands]
            new_cands[r] = [p]
            new_assignments = dict(assignments)
            new_assignments[r] = p
            if not partial_columns_ok(new_assignments):
                continue
            res = dfs(new_cands, new_assignments)
            if res is not None:
                return res
        return None

    result = dfs(row_cands, {})
    if result is None:
        return "No Solution"
    return repr(result)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'U': [1, 2, 4, 2, 3], 'D': [2, 2, 1, 4, 3], 'L': [1, 3, 3, 2, 2], 'R': [4, 2, 1, 3, 2]}

from itertools import permutations


def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    n = len(U)

    if not (len(D) == len(L) == len(R) == n):
        return "No Solution"

    nums = tuple(range(1, n + 1))
    all_perms = list(permutations(nums))

    def visible_count(seq):
        seen = 0
        mx = 0
        for v in seq:
            if v > mx:
                mx = v
                seen += 1
        return seen

    def clue_ok(seq, left, right):
        if left and visible_count(seq) != left:
            return False
        if right and visible_count(seq[::-1]) != right:
            return False
        return True

    # Precompute row and column candidate permutations from side clues.
    row_domains = []
    for r in range(n):
        dom = [p for p in all_perms if clue_ok(p, L[r], R[r])]
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for c in range(n):
        dom = [p for p in all_perms if clue_ok(p, U[c], D[c])]
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    # Bit helpers for fast cell-domain intersection.
    value_bit = {v: 1 << (v - 1) for v in nums}
    full_mask = (1 << n) - 1

    def position_masks(domain):
        masks = [0] * n
        for perm in domain:
            for i, v in enumerate(perm):
                masks[i] |= value_bit[v]
        return masks

    def filter_domain_by_allowed(domain, allowed_masks, index_mode=True):
        # index_mode=True: allowed_masks[pos] applies to perm[pos]
        out = []
        if index_mode:
            for perm in domain:
                ok = True
                for i, v in enumerate(perm):
                    if not (allowed_masks[i] & value_bit[v]):
                        ok = False
                        break
                if ok:
                    out.append(perm)
        else:
            for perm in domain:
                ok = True
                for i, v in enumerate(perm):
                    if not (allowed_masks[i] & value_bit[v]):
                        ok = False
                        break
                if ok:
                    out.append(perm)
        return out

    def propagate(r_domains, c_domains):
        # AC-like propagation between row-permutation vars and column-permutation vars.
        changed = True
        while changed:
            changed = False

            row_masks = [position_masks(dom) for dom in r_domains]
            col_masks = [position_masks(dom) for dom in c_domains]

            # Cell-wise allowed values are intersections of row and column supports.
            cell_allowed_rows = [[0] * n for _ in range(n)]
            for r in range(n):
                for c in range(n):
                    m = row_masks[r][c] & col_masks[c][r]
                    if m == 0:
                        return None
                    cell_allowed_rows[r][c] = m

            # Filter row domains using per-cell allowed sets.
            for r in range(n):
                new_dom = filter_domain_by_allowed(r_domains[r], cell_allowed_rows[r])
                if not new_dom:
                    return None
                if len(new_dom) != len(r_domains[r]):
                    r_domains[r] = new_dom
                    changed = True

            # Recompute row masks if row domains changed.
            if changed:
                row_masks = [position_masks(dom) for dom in r_domains]
                cell_allowed_cols = [[0] * n for _ in range(n)]
                for c in range(n):
                    for r in range(n):
                        m = row_masks[r][c] & col_masks[c][r]
                        if m == 0:
                            return None
                        cell_allowed_cols[c][r] = m
            else:
                cell_allowed_cols = [[cell_allowed_rows[r][c] for r in range(n)] for c in range(n)]

            # Filter column domains using per-cell allowed sets.
            any_col_change = False
            for c in range(n):
                new_dom = filter_domain_by_allowed(c_domains[c], cell_allowed_cols[c])
                if not new_dom:
                    return None
                if len(new_dom) != len(c_domains[c]):
                    c_domains[c] = new_dom
                    any_col_change = True
            if any_col_change:
                changed = True

            # Human-like "forced placement" effect:
            # if a row/column is fixed, all crossing domains will be reduced on next loop.
            # Also catch direct inconsistency between fixed rows and fixed columns early.
            for r in range(n):
                if len(r_domains[r]) == 1:
                    row = r_domains[r][0]
                    for c in range(n):
                        v = row[c]
                        if not any(colp[r] == v for colp in c_domains[c]):
                            return None
            for c in range(n):
                if len(c_domains[c]) == 1:
                    col = c_domains[c][0]
                    for r in range(n):
                        v = col[r]
                        if not any(rowp[c] == v for rowp in r_domains[r]):
                            return None

        return r_domains, c_domains

    def solved(r_domains, c_domains):
        return all(len(dom) == 1 for dom in r_domains) and all(len(dom) == 1 for dom in c_domains)

    def extract_grid(r_domains):
        return [list(dom[0]) for dom in r_domains]

    def choose_var(r_domains, c_domains):
        # Minimum remaining values, prefer rows then columns.
        best_kind = None
        best_idx = -1
        best_size = 10**9

        for i, dom in enumerate(r_domains):
            s = len(dom)
            if 1 < s < best_size:
                best_kind = "row"
                best_idx = i
                best_size = s

        for i, dom in enumerate(c_domains):
            s = len(dom)
            if 1 < s < best_size:
                best_kind = "col"
                best_idx = i
                best_size = s

        return best_kind, best_idx

    def clone_domains(domains):
        return [list(dom) for dom in domains]

    def search(r_domains, c_domains):
        propagated = propagate(r_domains, c_domains)
        if propagated is None:
            return None
        r_domains, c_domains = propagated

        if solved(r_domains, c_domains):
            grid = extract_grid(r_domains)
            # Final safety check.
            for r in range(n):
                if tuple(grid[r]) != r_domains[r][0]:
                    return None
            for c in range(n):
                col = tuple(grid[r][c] for r in range(n))
                if col != c_domains[c][0]:
                    return None
            return grid

        kind, idx = choose_var(r_domains, c_domains)
        if kind is None:
            return None

        if kind == "row":
            domain = r_domains[idx]
            # Prefer candidates that agree with current column supports most strongly.
            col_masks = [position_masks(c_domains[c])[idx] for c in range(n)]
            scored = []
            for perm in domain:
                score = 0
                for c, v in enumerate(perm):
                    if col_masks[c] & value_bit[v]:
                        score += 1
                scored.append((score, perm))
            scored.sort(reverse=True)

            for _, perm in scored:
                nr = clone_domains(r_domains)
                nc = clone_domains(c_domains)
                nr[idx] = [perm]
                res = search(nr, nc)
                if res is not None:
                    return res
        else:
            domain = c_domains[idx]
            row_masks = [position_masks(r_domains[r])[idx] for r in range(n)]
            scored = []
            for perm in domain:
                score = 0
                for r, v in enumerate(perm):
                    if row_masks[r] & value_bit[v]:
                        score += 1
                scored.append((score, perm))
            scored.sort(reverse=True)

            for _, perm in scored:
                nr = clone_domains(r_domains)
                nc = clone_domains(c_domains)
                nc[idx] = [perm]
                res = search(nr, nc)
                if res is not None:
                    return res

        return None

    result = search(row_domains, col_domains)
    return str(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'W', None, None, None, None], [None, None, None, 'W', None, None], [None, None, 'B', 'B', 'B', 'B'], [None, 'B', None, None, 'B', None], [None, None, 'W', None, None, None], [None, None, None, None, None, None]]}

from collections import deque, defaultdict

B = 'B'
W = 'W'
U = None


def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)

    peers_2x2 = [[[] for _ in range(n)] for _ in range(n)]
    for r in range(n - 1):
        for c in range(n - 1):
            cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
            for rr, cc in cells:
                peers_2x2[rr][cc].append(cells)

    def neighbors(r, c):
        if r > 0:
            yield r - 1, c
        if r + 1 < n:
            yield r + 1, c
        if c > 0:
            yield r, c - 1
        if c + 1 < n:
            yield r, c + 1

    def copy_grid(g):
        return [row[:] for row in g]

    def all_cells():
        for r in range(n):
            for c in range(n):
                yield r, c

    def is_complete(g):
        return all(g[r][c] is not None for r in range(n) for c in range(n))

    def opposite(color):
        return W if color == B else B

    def find_components_allowed(g, color):
        # Components among cells that are either color or undecided.
        seen = [[False] * n for _ in range(n)]
        comps = []
        for r in range(n):
            for c in range(n):
                if not seen[r][c] and g[r][c] != opposite(color):
                    q = deque([(r, c)])
                    seen[r][c] = True
                    comp = []
                    has_known = False
                    while q:
                        x, y = q.popleft()
                        comp.append((x, y))
                        if g[x][y] == color:
                            has_known = True
                        for nx, ny in neighbors(x, y):
                            if not seen[nx][ny] and g[nx][ny] != opposite(color):
                                seen[nx][ny] = True
                                q.append((nx, ny))
                    comps.append((comp, has_known))
        return comps

    def connectivity_possible(g, color):
        # All known color cells must lie within a single connected component
        # of cells that are not forced to opposite(color).
        known = [(r, c) for r, c in all_cells() if g[r][c] == color]
        if not known:
            return True
        start = known[0]
        q = deque([start])
        seen = {start}
        while q:
            x, y = q.popleft()
            for nx, ny in neighbors(x, y):
                if (nx, ny) not in seen and g[nx][ny] != opposite(color):
                    seen.add((nx, ny))
                    q.append((nx, ny))
        return all(cell in seen for cell in known)

    def connectivity_final(g, color):
        cells = [(r, c) for r, c in all_cells() if g[r][c] == color]
        if not cells:
            return False
        start = cells[0]
        q = deque([start])
        seen = {start}
        while q:
            x, y = q.popleft()
            for nx, ny in neighbors(x, y):
                if (nx, ny) not in seen and g[nx][ny] == color:
                    seen.add((nx, ny))
                    q.append((nx, ny))
        return len(seen) == len(cells)

    def no_monochrome_2x2_final(g):
        for r in range(n - 1):
            for c in range(n - 1):
                vals = {g[r][c], g[r + 1][c], g[r][c + 1], g[r + 1][c + 1]}
                if len(vals) == 1:
                    return False
        return True

    def partial_2x2_ok(g):
        for r in range(n - 1):
            for c in range(n - 1):
                vals = [g[r][c], g[r + 1][c], g[r][c + 1], g[r + 1][c + 1]]
                if vals.count(U) == 0 and len(set(vals)) == 1:
                    return False
        return True

    def local_forces(g, queue):
        while queue:
            r, c = queue.pop()
            for block in peers_2x2[r][c]:
                vals = [g[x][y] for x, y in block]
                for color in (B, W):
                    if vals.count(color) == 4:
                        return False
                    if vals.count(color) == 3 and vals.count(U) == 1:
                        idx = vals.index(U)
                        x, y = block[idx]
                        forced = opposite(color)
                        if g[x][y] is None:
                            g[x][y] = forced
                            queue.append((x, y))
                        elif g[x][y] != forced:
                            return False
            # Human-like line deduction:
            # If two same colors with one between them in a row/col,
            # the middle cannot be opposite if that would isolate 2x2/pool patterns around edges.
            # We use a safe subset: x ? x in a line forces ? = opposite(x) when all three are consecutive.
            # This is valid in Yin-Yang because x x x consecutively would split local shape and create a pool risk
            # only in some contexts, so we do NOT use that unsafe rule globally.
            # Instead apply corner/edge forcing from 2x2 only.

            # Degree-0 impossibility for decided cells:
            # A decided cell must have at least one neighbor that can still be same color,
            # unless it is the only cell of that color (ruled out later by connectivity/finality).
            color = g[r][c]
            if color is not None:
                same_possible = 0
                same_known = 0
                for nr, nc in neighbors(r, c):
                    if g[nr][nc] != opposite(color):
                        same_possible += 1
                    if g[nr][nc] == color:
                        same_known += 1
                if same_possible == 0:
                    return False

                # If all but one neighbors are opposite and one undecided remains, it must match to avoid isolation.
                undec = []
                for nr, nc in neighbors(r, c):
                    if g[nr][nc] is None:
                        undec.append((nr, nc))
                opp_cnt = sum(1 for nr, nc in neighbors(r, c) if g[nr][nc] == opposite(color))
                deg = sum(1 for _ in neighbors(r, c))
                if same_known == 0 and len(undec) == 1 and opp_cnt == deg - 1:
                    x, y = undec[0]
                    if g[x][y] is None:
                        g[x][y] = color
                        queue.append((x, y))
                    elif g[x][y] != color:
                        return False

        return True

    def articulation_forces(g):
        # Safe connectivity-based forcing:
        # If assigning a cell to opposite(color) would separate existing known color cells
        # into multiple impossible regions, then it must be color.
        changed = True
        while changed:
            changed = False
            unknowns = [(r, c) for r, c in all_cells() if g[r][c] is None]
            for r, c in unknowns:
                forced_to = None
                for color in (B, W):
                    test = copy_grid(g)
                    test[r][c] = opposite(color)
                    if not connectivity_possible(test, color):
                        if forced_to is None:
                            forced_to = color
                        elif forced_to != color:
                            return False
                if forced_to is not None:
                    if g[r][c] is None:
                        g[r][c] = forced_to
                        if not propagate(g):
                            return False
                        changed = True
                        break
                    elif g[r][c] != forced_to:
                        return False
        return True

    def impossible_color_regions(g, color):
        # If there are multiple allowed components containing known color cells, impossible.
        comps = find_components_allowed(g, color)
        cnt = sum(1 for _, has_known in comps if has_known)
        return cnt > 1

    def propagate(g):
        queue = [(r, c) for r, c in all_cells() if g[r][c] is not None]
        if not local_forces(g, queue):
            return False

        if not partial_2x2_ok(g):
            return False

        if impossible_color_regions(g, B) or impossible_color_regions(g, W):
            return False

        if not connectivity_possible(g, B) or not connectivity_possible(g, W):
            return False

        if not articulation_forces(g):
            return False

        if not partial_2x2_ok(g):
            return False
        if not connectivity_possible(g, B) or not connectivity_possible(g, W):
            return False

        return True

    def final_valid(g):
        return (
            is_complete(g)
            and no_monochrome_2x2_final(g)
            and connectivity_final(g, B)
            and connectivity_final(g, W)
        )

    def score_cell(g, r, c):
        # Higher score => branch here first.
        score = 0
        for block in peers_2x2[r][c]:
            vals = [g[x][y] for x, y in block]
            if vals.count(U) <= 2:
                score += 4
            score += vals.count(B) + vals.count(W)
        for nr, nc in neighbors(r, c):
            if g[nr][nc] is not None:
                score += 2
        if 0 < r < n - 1 and 0 < c < n - 1:
            score += 1
        return score

    def candidate_order(g, r, c):
        # Prefer colors suggested by neighbors / local consistency.
        counts = {B: 0, W: 0}
        for nr, nc in neighbors(r, c):
            if g[nr][nc] in (B, W):
                counts[g[nr][nc]] += 1
        if counts[B] > counts[W]:
            return [B, W]
        if counts[W] > counts[B]:
            return [W, B]
        return [B, W]

    def search(g):
        if not propagate(g):
            return None
        if is_complete(g):
            return g if final_valid(g) else None

        unknowns = [(r, c) for r, c in all_cells() if g[r][c] is None]
        r, c = max(unknowns, key=lambda rc: score_cell(g, rc[0], rc[1]))

        for val in candidate_order(g, r, c):
            ng = copy_grid(g)
            ng[r][c] = val
            res = search(ng)
            if res is not None:
                return res
        return None

    result = search(grid)
    return result if result is not None else "No Solution"


