OBSERVATION = {'U': [2, 1, 2, 2], 'D': [3, 4, 1, 2], 'L': [2, 1, 2, 2], 'R': [3, 4, 1, 2]}

from itertools import permutations


def visible_count(seq):
    m = 0
    cnt = 0
    for x in seq:
        if x > m:
            m = x
            cnt += 1
    return cnt


def clue_key(a, b):
    return (a if a is not None else 0, b if b is not None else 0)


def build_perm_cache(n):
    perms = list(permutations(range(1, n + 1)))
    by_lr = {}
    by_ud = {}
    for p in perms:
        l = visible_count(p)
        r = visible_count(reversed(p))
        by_lr.setdefault((l, r), []).append(p)
        by_ud.setdefault((l, r), []).append(p)
    return perms, by_lr, by_ud


def get_line_candidates(n, cache, clue_a, clue_b):
    a = clue_a or 0
    b = clue_b or 0
    if a == 0 and b == 0:
        return list(cache["all"])
    if a == 0:
        out = []
        for k, v in cache["map"].items():
            if k[1] == b:
                out.extend(v)
        return out
    if b == 0:
        out = []
        for k, v in cache["map"].items():
            if k[0] == a:
                out.extend(v)
        return out
    return list(cache["map"].get((a, b), []))


def initial_state(observation):
    n = len(observation["U"])
    all_perms, by_lr, by_ud = build_perm_cache(n)
    row_cache = {"all": all_perms, "map": by_lr}
    col_cache = {"all": all_perms, "map": by_ud}

    rows = []
    cols = []

    for r in range(n):
        rows.append(get_line_candidates(n, row_cache, observation["L"][r], observation["R"][r]))
    for c in range(n):
        cols.append(get_line_candidates(n, col_cache, observation["U"][c], observation["D"][c]))

    return {
        "n": n,
        "rows": rows,
        "cols": cols,
    }


def copy_state(state):
    return {
        "n": state["n"],
        "rows": [list(x) for x in state["rows"]],
        "cols": [list(x) for x in state["cols"]],
    }


def compute_domains(state):
    n = state["n"]
    domains = [[None] * n for _ in range(n)]

    row_support = []
    for r in range(n):
        support = [set() for _ in range(n)]
        for cand in state["rows"][r]:
            for c, v in enumerate(cand):
                support[c].add(v)
        row_support.append(support)

    col_support = []
    for c in range(n):
        support = [set() for _ in range(n)]
        for cand in state["cols"][c]:
            for r, v in enumerate(cand):
                support[r].add(v)
        col_support.append(support)

    for r in range(n):
        for c in range(n):
            d = row_support[r][c] & col_support[c][r]
            if not d:
                return None
            domains[r][c] = d
    return domains


def filter_lines_by_domains(state, domains):
    n = state["n"]
    changed = False

    for r in range(n):
        old = state["rows"][r]
        new = [cand for cand in old if all(cand[c] in domains[r][c] for c in range(n))]
        if not new:
            return None, True
        if len(new) != len(old):
            state["rows"][r] = new
            changed = True

    for c in range(n):
        old = state["cols"][c]
        new = [cand for cand in old if all(cand[r] in domains[r][c] for r in range(n))]
        if not new:
            return None, True
        if len(new) != len(old):
            state["cols"][c] = new
            changed = True

    return state, changed


def apply_hidden_singles(state, domains):
    n = state["n"]
    changed = False

    # Row-based hidden singles from row candidates
    for r in range(n):
        pos_by_val = {v: set() for v in range(1, n + 1)}
        for cand in state["rows"][r]:
            for c, v in enumerate(cand):
                pos_by_val[v].add(c)
        for v, posset in pos_by_val.items():
            if len(posset) == 1:
                c = next(iter(posset))
                if domains[r][c] != {v}:
                    domains[r][c] &= {v}
                    if not domains[r][c]:
                        return None, True
                    changed = True

    # Column-based hidden singles from column candidates
    for c in range(n):
        pos_by_val = {v: set() for v in range(1, n + 1)}
        for cand in state["cols"][c]:
            for r, v in enumerate(cand):
                pos_by_val[v].add(r)
        for v, posset in pos_by_val.items():
            if len(posset) == 1:
                r = next(iter(posset))
                if domains[r][c] != {v}:
                    domains[r][c] &= {v}
                    if not domains[r][c]:
                        return None, True
                    changed = True

    return domains, changed


def propagate(state):
    while True:
        # Basic impossible check
        if any(len(x) == 0 for x in state["rows"]) or any(len(x) == 0 for x in state["cols"]):
            return None

        domains = compute_domains(state)
        if domains is None:
            return None

        changed_any = False

        # Hidden singles / forced cells from line structure
        domains, changed = apply_hidden_singles(state, domains)
        if domains is None:
            return None
        changed_any |= changed

        # Re-filter after hidden singles
        state, changed = filter_lines_by_domains(state, domains)
        if state is None:
            return None
        changed_any |= changed

        # Recompute and re-filter one more time if domains changed
        if changed_any:
            continue

        # Stronger consistency: each cell's domain must be exactly intersection of current line supports,
        # and each line must still cover every digit somewhere.
        n = state["n"]
        for r in range(n):
            digit_union = set()
            for c in range(n):
                digit_union |= domains[r][c]
            if len(digit_union) < n:
                return None

        for c in range(n):
            digit_union = set()
            for r in range(n):
                digit_union |= domains[r][c]
            if len(digit_union) < n:
                return None

        return state


def is_solved(state):
    return all(len(cands) == 1 for cands in state["rows"]) and all(len(cands) == 1 for cands in state["cols"])


def extract_grid(state):
    return [list(state["rows"][r][0]) for r in range(state["n"])]


def choose_branch(state):
    best_kind = None
    best_idx = None
    best_len = 10**9

    for r, cands in enumerate(state["rows"]):
        m = len(cands)
        if 1 < m < best_len:
            best_len = m
            best_kind = "row"
            best_idx = r

    for c, cands in enumerate(state["cols"]):
        m = len(cands)
        if 1 < m < best_len:
            best_len = m
            best_kind = "col"
            best_idx = c

    return best_kind, best_idx


def search(state):
    state = propagate(state)
    if state is None:
        return None
    if is_solved(state):
        return extract_grid(state)

    kind, idx = choose_branch(state)
    if kind is None:
        return None

    if kind == "row":
        candidates = list(state["rows"][idx])
        # Prefer candidates that are more column-compatible
        scored = []
        for cand in candidates:
            score = 0
            for c, v in enumerate(cand):
                score += sum(1 for colcand in state["cols"][c] if colcand[idx] == v)
            scored.append((score, cand))
        scored.sort(reverse=True)
        for _, cand in scored:
            nxt = copy_state(state)
            nxt["rows"][idx] = [cand]
            ans = search(nxt)
            if ans is not None:
                return ans
    else:
        candidates = list(state["cols"][idx])
        # Prefer candidates that are more row-compatible
        scored = []
        for cand in candidates:
            score = 0
            for r, v in enumerate(cand):
                score += sum(1 for rowcand in state["rows"][r] if rowcand[idx] == v)
            scored.append((score, cand))
        scored.sort(reverse=True)
        for _, cand in scored:
            nxt = copy_state(state)
            nxt["cols"][idx] = [cand]
            ans = search(nxt)
            if ans is not None:
                return ans

    return None


def validate_solution(grid, observation):
    n = len(grid)
    target = set(range(1, n + 1))

    for r in range(n):
        if set(grid[r]) != target:
            return False
        if observation["L"][r] and visible_count(grid[r]) != observation["L"][r]:
            return False
        if observation["R"][r] and visible_count(reversed(grid[r])) != observation["R"][r]:
            return False

    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if set(col) != target:
            return False
        if observation["U"][c] and visible_count(col) != observation["U"][c]:
            return False
        if observation["D"][c] and visible_count(reversed(col)) != observation["D"][c]:
            return False

    return True


def solve(observation):
    state = initial_state(observation)
    grid = search(state)
    if grid is None:
        return "No Solution"
    if not validate_solution(grid, observation):
        return "No Solution"
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 1, None], [None, 1, 2, 3, 3], [None, 2, None, None, None], [None, None, None, None, None], [1, None, 2, None, 0]]}

from collections import deque, defaultdict

# Generalized Minesweeper solver:
# - Uses direct human-like deductions:
#   * if clue remainder == 0 => all unknown neighbors safe
#   * if clue remainder == number of unknown neighbors => all unknown neighbors are mines
#   * subset/superset rule on neighboring unknown sets
# - Then decomposes unresolved frontier into independent components
# - Solves each component with heavily-pruned backtracking using local clue bounds
# - Merges component results; cells mine in all valid assignments are flagged
# - Returns a Python-literal string grid with 'F' for mines and None otherwise

MINE = 1
SAFE = 0
UNKNOWN = -1


def neighbors(r, c, h, w):
    for dr in (-1, 0, 1):
        nr = r + dr
        if nr < 0 or nr >= h:
            continue
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            nc = c + dc
            if 0 <= nc < w:
                yield nr, nc


def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0

    state = [[UNKNOWN if data[r][c] is None else SAFE for c in range(w)] for r in range(h)]
    numbered = [(r, c) for r in range(h) for c in range(w) if data[r][c] is not None]
    clue_neighbors = {}
    cell_to_clues = defaultdict(list)

    for r, c in numbered:
        nbrs = [(nr, nc) for nr, nc in neighbors(r, c, h, w) if data[nr][nc] is None]
        clue_neighbors[(r, c)] = nbrs
        for cell in nbrs:
            cell_to_clues[cell].append((r, c))

    def clue_status(rc):
        r, c = rc
        clue = data[r][c]
        unknowns = []
        flagged = 0
        for nr, nc in clue_neighbors[rc]:
            if state[nr][nc] == MINE:
                flagged += 1
            elif state[nr][nc] == UNKNOWN:
                unknowns.append((nr, nc))
        need = clue - flagged
        return need, unknowns

    def assign(cell, val, queue):
        r, c = cell
        cur = state[r][c]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False
        state[r][c] = val
        for clue in cell_to_clues.get(cell, ()):
            queue.append(clue)
        return True

    def basic_propagate():
        queue = deque(numbered)
        while queue:
            rc = queue.popleft()
            need, unknowns = clue_status(rc)
            if need < 0 or need > len(unknowns):
                return False
            if need == 0 and unknowns:
                for cell in unknowns:
                    if not assign(cell, SAFE, queue):
                        return False
            elif need == len(unknowns) and unknowns:
                for cell in unknowns:
                    if not assign(cell, MINE, queue):
                        return False
        return True

    def subset_propagate():
        changed = True
        while changed:
            changed = False
            if not basic_propagate():
                return False
            active = []
            for rc in numbered:
                need, unknowns = clue_status(rc)
                if unknowns:
                    active.append((rc, need, frozenset(unknowns)))

            # Human-like set comparison:
            # If A subset B, then:
            #   mines(B\A) = needB - needA when exact
            #   if needB==needA => B\A safe
            #   if len(B)-len(A)==needB-needA => B\A mines
            n = len(active)
            for i in range(n):
                _, need_a, set_a = active[i]
                for j in range(n):
                    if i == j:
                        continue
                    _, need_b, set_b = active[j]
                    if not set_a or not set_b:
                        continue
                    if set_a.issubset(set_b) and set_a != set_b:
                        diff = list(set_b - set_a)
                        delta = need_b - need_a
                        if delta < 0 or delta > len(diff):
                            return False
                        if delta == 0:
                            q = deque()
                            local = False
                            for cell in diff:
                                if state[cell[0]][cell[1]] == UNKNOWN:
                                    if not assign(cell, SAFE, q):
                                        return False
                                    local = True
                            if local:
                                while q:
                                    pass
                                changed = True
                        elif delta == len(diff):
                            q = deque()
                            local = False
                            for cell in diff:
                                if state[cell[0]][cell[1]] == UNKNOWN:
                                    if not assign(cell, MINE, q):
                                        return False
                                    local = True
                            if local:
                                while q:
                                    pass
                                changed = True
            if changed:
                continue
        return basic_propagate()

    if not subset_propagate():
        return "No Solution"

    frontier = [cell for cell in cell_to_clues if state[cell[0]][cell[1]] == UNKNOWN]
    if not frontier:
        if not validate_full(data, state, h, w):
            return "No Solution"
        return grid_to_string(state, h, w)

    components = build_components(frontier, cell_to_clues)
    overall_forced_mines = set()
    overall_forced_safe = set()

    for comp_cells in components:
        comp_clues = set()
        for cell in comp_cells:
            comp_clues.update(cell_to_clues[cell])

        sols = solve_component(comp_cells, comp_clues, data, state, clue_neighbors, cell_to_clues)
        if not sols:
            return "No Solution"

        cells_list = list(comp_cells)
        for cell in cells_list:
            vals = {sol[cell] for sol in sols}
            if vals == {MINE}:
                overall_forced_mines.add(cell)
            elif vals == {SAFE}:
                overall_forced_safe.add(cell)

    q = deque()
    for cell in overall_forced_mines:
        if state[cell[0]][cell[1]] == UNKNOWN:
            if not assign(cell, MINE, q):
                return "No Solution"
    for cell in overall_forced_safe:
        if state[cell[0]][cell[1]] == UNKNOWN:
            if not assign(cell, SAFE, q):
                return "No Solution"

    if not subset_propagate():
        return "No Solution"

    # Any still-unknown cells disconnected from all clues are unconstrained.
    # For a final concrete answer, choose them safe.
    for r in range(h):
        for c in range(w):
            if state[r][c] == UNKNOWN:
                state[r][c] = SAFE

    if not validate_full(data, state, h, w):
        return "No Solution"

    return grid_to_string(state, h, w)


def build_components(frontier, cell_to_clues):
    frontier = set(frontier)
    seen = set()
    components = []
    clue_to_cells = defaultdict(set)
    for cell, clues in cell_to_clues.items():
        for clue in clues:
            clue_to_cells[clue].add(cell)

    for start in frontier:
        if start in seen:
            continue
        comp_cells = set()
        dq = deque([start])
        seen.add(start)
        while dq:
            cell = dq.popleft()
            comp_cells.add(cell)
            for clue in cell_to_clues[cell]:
                for nxt in clue_to_cells[clue]:
                    if nxt in frontier and nxt not in seen:
                        seen.add(nxt)
                        dq.append(nxt)
        components.append(comp_cells)
    return components


def solve_component(comp_cells, comp_clues, data, global_state, clue_neighbors, cell_to_clues):
    comp_cells = list(comp_cells)
    comp_index = {cell: i for i, cell in enumerate(comp_cells)}

    clue_infos = []
    for clue in comp_clues:
        fixed_mines = 0
        undecided = []
        for cell in clue_neighbors[clue]:
            sr, sc = cell
            st = global_state[sr][sc]
            if st == MINE:
                fixed_mines += 1
            elif st == UNKNOWN:
                if cell in comp_index:
                    undecided.append(comp_index[cell])
                else:
                    # Outside this component, unresolved should not happen if components cover frontier.
                    pass
        need = data[clue[0]][clue[1]] - fixed_mines
        if need < 0 or need > len(undecided):
            return []
        clue_infos.append([need, undecided])

    var_to_clues = [[] for _ in range(len(comp_cells))]
    for ci, (_, undecided) in enumerate(clue_infos):
        for v in undecided:
            var_to_clues[v].append(ci)

    remain_unknown = [len(undecided) for _, undecided in clue_infos]
    remain_need = [need for need, _ in clue_infos]

    order = choose_variable_order(len(comp_cells), var_to_clues, clue_infos)
    assignment = [UNKNOWN] * len(comp_cells)
    solutions = []

    def feasible_after(var, val, touched):
        for ci in var_to_clues[var]:
            if ci not in touched:
                touched.append(ci)
            remain_unknown[ci] -= 1
            if val == MINE:
                remain_need[ci] -= 1
            if remain_need[ci] < 0 or remain_need[ci] > remain_unknown[ci]:
                return False
        return True

    def rollback(var, val, touched):
        for ci in touched:
            remain_unknown[ci] += 1
            if val == MINE:
                remain_need[ci] += 1

    def deduce_forced(unassigned_vars):
        forced = {}
        changed = True
        while changed:
            changed = False
            for ci, (_, vars0) in enumerate(clue_infos):
                need = remain_need[ci]
                avail = [v for v in vars0 if assignment[v] == UNKNOWN and v in unassigned_vars and v not in forced]
                if need < 0 or need > len([v for v in vars0 if assignment[v] == UNKNOWN]):
                    return None
                if not avail:
                    continue
                total_unassigned_here = [v for v in vars0 if assignment[v] == UNKNOWN]
                if need == 0:
                    for v in avail:
                        if v in forced and forced[v] != SAFE:
                            return None
                        if v not in forced:
                            forced[v] = SAFE
                            changed = True
                elif need == len(total_unassigned_here):
                    for v in avail:
                        if v in forced and forced[v] != MINE:
                            return None
                        if v not in forced:
                            forced[v] = MINE
                            changed = True
        return forced

    def backtrack(pos):
        if pos == len(order):
            if all(x == 0 for x in remain_need):
                solutions.append({comp_cells[i]: assignment[i] for i in range(len(comp_cells))})
            return

        unassigned = set(order[pos:])
        forced = deduce_forced(unassigned)
        if forced is None:
            return

        applied = []
        for v, val in forced.items():
            if assignment[v] != UNKNOWN:
                if assignment[v] != val:
                    for av, aval, touched in reversed(applied):
                        assignment[av] = UNKNOWN
                        rollback(av, aval, touched)
                    return
                continue
            touched = []
            assignment[v] = val
            if not feasible_after(v, val, touched):
                assignment[v] = UNKNOWN
                rollback(v, val, touched)
                for av, aval, tt in reversed(applied):
                    assignment[av] = UNKNOWN
                    rollback(av, aval, tt)
                return
            applied.append((v, val, touched))

        while pos < len(order) and assignment[order[pos]] != UNKNOWN:
            pos += 1
        if pos == len(order):
            if all(x == 0 for x in remain_need):
                solutions.append({comp_cells[i]: assignment[i] for i in range(len(comp_cells))})
            for av, aval, touched in reversed(applied):
                assignment[av] = UNKNOWN
                rollback(av, aval, touched)
            return

        v = order[pos]

        # Value ordering heuristic: prefer value satisfying tighter clues first
        score_mine = 0
        score_safe = 0
        for ci in var_to_clues[v]:
            score_mine += remain_need[ci]
            score_safe += remain_unknown[ci] - remain_need[ci]
        trial_vals = [MINE, SAFE] if score_mine <= score_safe else [SAFE, MINE]

        for val in trial_vals:
            touched = []
            assignment[v] = val
            if feasible_after(v, val, touched):
                backtrack(pos + 1)
            assignment[v] = UNKNOWN
            rollback(v, val, touched)

        for av, aval, touched in reversed(applied):
            assignment[av] = UNKNOWN
            rollback(av, aval, touched)

    backtrack(0)
    return solutions


def choose_variable_order(nvars, var_to_clues, clue_infos):
    weights = []
    for v in range(nvars):
        deg = len(var_to_clues[v])
        tight = 0
        for ci in var_to_clues[v]:
            need, undecided = clue_infos[ci]
            size = max(1, len(undecided))
            tight += min(need, size - need) / size
        weights.append((-deg, -tight, v))
    weights.sort()
    return [v for _, _, v in weights]


def validate_full(data, state, h, w):
    for r in range(h):
        for c in range(w):
            if data[r][c] is None:
                continue
            cnt = 0
            for nr, nc in neighbors(r, c, h, w):
                if state[nr][nc] == MINE:
                    cnt += 1
            if cnt != data[r][c]:
                return False
    return True


def grid_to_string(state, h, w):
    ans = [['F' if state[r][c] == MINE else None for c in range(w)] for r in range(h)]
    return repr(ans)


