# Weighted black-cell puzzle solver.
# General rule assumed from the puzzle format:
# - Row i has weight (i+1) for use in column totals.
# - Column j has weight (j+1) for use in row totals.
# - A black cell at (i, j) contributes:
#     * (j+1) to row_sum[i]
#     * (i+1) to col_sum[j]
#
# The solver is generalized and uses:
# 1) exact subset-pattern generation for each row/column target,
# 2) aggressive domain filtering,
# 3) cell-wise propagation by row/column consensus,
# 4) branching only when deduction stalls.

from functools import lru_cache

def bit_positions(mask, n):
    while mask:
        lsb = mask & -mask
        yield lsb.bit_length() - 1
        mask ^= lsb

def format_grid(grid):
    return repr(grid)

def solve(observation):
    row_targets = observation['row_sum']
    col_targets = observation['col_sum']
    R = len(row_targets)
    C = len(col_targets)

    row_weights = list(range(1, R + 1))
    col_weights = list(range(1, C + 1))

    # Quick necessary condition: total weighted contribution counted from rows == counted from columns.
    if sum(row_targets) != sum(col_targets):
        return "No Solution"

    @lru_cache(maxsize=None)
    def subset_masks_for_target(n, target):
        # All subsets of weights 1..n whose sum is target, represented as bitmasks.
        # Uses DFS with strong bounds.
        weights = tuple(range(1, n + 1))
        suffix = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suffix[i] = suffix[i + 1] + weights[i]

        out = []

        def dfs(idx, rem, mask):
            if rem == 0:
                out.append(mask)
                return
            if idx == n or rem < 0:
                return
            if suffix[idx] < rem:
                return

            w = weights[idx]

            # Option 1: include current weight if possible.
            if w <= rem:
                dfs(idx + 1, rem - w, mask | (1 << idx))

            # Option 2: exclude current weight, but only if remaining max can still reach rem.
            if suffix[idx + 1] >= rem:
                dfs(idx + 1, rem, mask)

        dfs(0, target, 0)
        return tuple(out)

    row_domains = [set(subset_masks_for_target(C, t)) for t in row_targets]
    col_domains = [set(subset_masks_for_target(R, t)) for t in col_targets]

    if any(not d for d in row_domains) or any(not d for d in col_domains):
        return "No Solution"

    full_row_mask = (1 << C) - 1
    full_col_mask = (1 << R) - 1

    def domain_consensus(domains, bit_count, full_mask):
        # For a set of masks, return:
        # must1 = bits that are 1 in all masks
        # must0 = bits that are 0 in all masks
        it = iter(domains)
        first = next(it)
        and_all = first
        or_all = first
        for m in it:
            and_all &= m
            or_all |= m
        must1 = and_all
        must0 = full_mask ^ or_all
        return must1, must0

    def filter_by_forced(domains, forced1, forced0):
        # Keep masks that respect all forced bits.
        changed = False
        for idx in range(len(domains)):
            if not domains[idx]:
                return None
            f1 = forced1[idx]
            f0 = forced0[idx]
            new_dom = {m for m in domains[idx] if (m & f1) == f1 and (m & f0) == 0}
            if not new_dom:
                return None
            if len(new_dom) != len(domains[idx]):
                domains[idx] = new_dom
                changed = True
        return changed

    def propagate(row_domains, col_domains):
        # Repeatedly:
        # - derive forced cells from row domains and column domains,
        # - cross-apply these forced cells,
        # - filter inconsistent patterns.
        while True:
            changed_any = False

            row_must1 = [0] * R
            row_must0 = [0] * R
            for i in range(R):
                must1, must0 = domain_consensus(row_domains[i], C, full_row_mask)
                row_must1[i] = must1
                row_must0[i] = must0

            col_must1 = [0] * C
            col_must0 = [0] * C
            for j in range(C):
                must1, must0 = domain_consensus(col_domains[j], R, full_col_mask)
                col_must1[j] = must1
                col_must0[j] = must0

            # Cross-check direct contradiction from forced cells.
            for i in range(R):
                for j in range(C):
                    rb = (row_must1[i] >> j) & 1
                    rz = (row_must0[i] >> j) & 1
                    cb = (col_must1[j] >> i) & 1
                    cz = (col_must0[j] >> i) & 1
                    if (rb and cz) or (cb and rz):
                        return False
                    if rb and cb:
                        continue
                    if rz and cz:
                        continue

            # Convert row forced cells into per-column bit constraints.
            forced1_for_cols = [0] * C
            forced0_for_cols = [0] * C
            for i in range(R):
                m1 = row_must1[i]
                m0 = row_must0[i]
                for j in bit_positions(m1, C):
                    forced1_for_cols[j] |= (1 << i)
                for j in bit_positions(m0, C):
                    forced0_for_cols[j] |= (1 << i)

            res = filter_by_forced(col_domains, forced1_for_cols, forced0_for_cols)
            if res is None:
                return False
            changed_any |= res

            # Recompute column consensus after possible filtering.
            col_must1 = [0] * C
            col_must0 = [0] * C
            for j in range(C):
                must1, must0 = domain_consensus(col_domains[j], R, full_col_mask)
                col_must1[j] = must1
                col_must0[j] = must0

            # Convert column forced cells into per-row bit constraints.
            forced1_for_rows = [0] * R
            forced0_for_rows = [0] * R
            for j in range(C):
                m1 = col_must1[j]
                m0 = col_must0[j]
                for i in bit_positions(m1, R):
                    forced1_for_rows[i] |= (1 << j)
                for i in bit_positions(m0, R):
                    forced0_for_rows[i] |= (1 << j)

            res = filter_by_forced(row_domains, forced1_for_rows, forced0_for_rows)
            if res is None:
                return False
            changed_any |= res

            # Additional support-based pruning:
            # For each undecided cell, both row and column domains must allow at least one compatible value.
            # We prune masks unsupported by the opposite side's possible bits.
            row_possible1 = [0] * R
            row_possible0 = [0] * R
            for i in range(R):
                _, must0 = domain_consensus(row_domains[i], C, full_row_mask)
                must1, _ = domain_consensus(row_domains[i], C, full_row_mask)
                row_possible1[i] = full_row_mask ^ must0
                row_possible0[i] = full_row_mask ^ must1

            col_possible1 = [0] * C
            col_possible0 = [0] * C
            for j in range(C):
                _, must0 = domain_consensus(col_domains[j], R, full_col_mask)
                must1, _ = domain_consensus(col_domains[j], R, full_col_mask)
                col_possible1[j] = full_col_mask ^ must0
                col_possible0[j] = full_col_mask ^ must1

            # Enforce per-cell possibility agreement.
            for i in range(R):
                allowed1_mask = 0
                allowed0_mask = 0
                for j in range(C):
                    col_can1 = (col_possible1[j] >> i) & 1
                    col_can0 = (col_possible0[j] >> i) & 1
                    if col_can1:
                        allowed1_mask |= (1 << j)
                    if col_can0:
                        allowed0_mask |= (1 << j)
                new_dom = {m for m in row_domains[i] if ((m & ~allowed1_mask) == 0) and (((~m) & full_row_mask & ~allowed0_mask) == 0)}
                if not new_dom:
                    return False
                if len(new_dom) != len(row_domains[i]):
                    row_domains[i] = new_dom
                    changed_any = True

            for j in range(C):
                allowed1_mask = 0
                allowed0_mask = 0
                for i in range(R):
                    row_can1 = (row_possible1[i] >> j) & 1
                    row_can0 = (row_possible0[i] >> j) & 1
                    if row_can1:
                        allowed1_mask |= (1 << i)
                    if row_can0:
                        allowed0_mask |= (1 << i)
                new_dom = {m for m in col_domains[j] if ((m & ~allowed1_mask) == 0) and (((~m) & full_col_mask & ~allowed0_mask) == 0)}
                if not new_dom:
                    return False
                if len(new_dom) != len(col_domains[j]):
                    col_domains[j] = new_dom
                    changed_any = True

            if not changed_any:
                return True

    def is_solved(row_domains, col_domains):
        return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)

    def choose_branch(row_domains, col_domains):
        # Human-like heuristic: branch on the most constrained row/column.
        best = None

        for i, d in enumerate(row_domains):
            if 1 < len(d) and (best is None or len(d) < best[0]):
                best = (len(d), 'row', i)

        for j, d in enumerate(col_domains):
            if 1 < len(d) and (best is None or len(d) < best[0]):
                best = (len(d), 'col', j)

        return best

    def copy_domains(domains):
        return [set(d) for d in domains]

    def search(row_domains, col_domains):
        if not propagate(row_domains, col_domains):
            return None

        if is_solved(row_domains, col_domains):
            # Validate exact matrix consistency.
            row_masks = [next(iter(d)) for d in row_domains]
            col_masks = [next(iter(d)) for d in col_domains]
            for i in range(R):
                for j in range(C):
                    a = (row_masks[i] >> j) & 1
                    b = (col_masks[j] >> i) & 1
                    if a != b:
                        return None
            return row_masks

        choice = choose_branch(row_domains, col_domains)
        if choice is None:
            return None

        _, kind, idx = choice

        if kind == 'row':
            # Try patterns in a useful order: more constrained-looking first by compatibility score.
            candidates = list(row_domains[idx])

            def score(mask):
                s = 0
                for j in range(C):
                    bit = (mask >> j) & 1
                    compatible = 0
                    for cm in col_domains[j]:
                        if ((cm >> idx) & 1) == bit:
                            compatible += 1
                    s += compatible
                return s

            candidates.sort(key=score)

            for m in candidates:
                rd = copy_domains(row_domains)
                cd = copy_domains(col_domains)
                rd[idx] = {m}
                ans = search(rd, cd)
                if ans is not None:
                    return ans
        else:
            candidates = list(col_domains[idx])

            def score(mask):
                s = 0
                for i in range(R):
                    bit = (mask >> i) & 1
                    compatible = 0
                    for rm in row_domains[i]:
                        if ((rm >> idx) & 1) == bit:
                            compatible += 1
                    s += compatible
                return s

            candidates.sort(key=score)

            for m in candidates:
                rd = copy_domains(row_domains)
                cd = copy_domains(col_domains)
                cd[idx] = {m}
                ans = search(rd, cd)
                if ans is not None:
                    return ans

        return None

    row_masks = search(copy_domains(row_domains), copy_domains(col_domains))
    if row_masks is None:
        return "No Solution"

    grid = []
    for i in range(R):
        row = []
        mask = row_masks[i]
        for j in range(C):
            row.append('B' if (mask >> j) & 1 else None)
        grid.append(row)
    return format_grid(grid)

