from itertools import combinations

# Futoshiki / Latin-square solver with strong propagation and limited search.
# Conventions used:
# - Horizontal '<' at (r, c+0.5): cell(r,c) < cell(r,c+1)
# - Horizontal '>' at (r, c+0.5): cell(r,c) > cell(r,c+1)
# - Vertical '^' at (r+0.5, c): cell(r,c) < cell(r+1,c)
# - Vertical 'v' at (r+0.5, c): cell(r,c) > cell(r+1,c)

def solve(observation):
    data = observation['data']
    n = len(data)
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    def vals(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    def mask_le(k):
        if k <= 0:
            return 0
        if k >= n:
            return full
        return (1 << k) - 1

    def mask_ge(k):
        if k <= 1:
            return full
        if k > n:
            return 0
        return full ^ ((1 << (k - 1)) - 1)

    def parse_key(s):
        s = s.strip()[1:-1]
        a, b = s.split(',')
        x = float(a.strip())
        y = float(b.strip())
        return x, y

    # Build inequality edges as directed constraints a < b.
    less_edges = []
    neighbors = [[] for _ in range(n * n)]

    def idx(r, c):
        return r * n + c

    for k, sym in observation.get('horizontal', {}).items():
        r, c_half = parse_key(k)
        r = int(r)
        c = int(c_half - 0.5)
        a = idx(r, c)
        b = idx(r, c + 1)
        if sym == '<':
            less_edges.append((a, b))
        elif sym == '>':
            less_edges.append((b, a))

    for k, sym in observation.get('vertical', {}).items():
        r_half, c = parse_key(k)
        r = int(r_half - 0.5)
        c = int(c)
        a = idx(r, c)
        b = idx(r + 1, c)
        if sym == '^':
            less_edges.append((a, b))
        elif sym == 'v':
            less_edges.append((b, a))

    for a, b in less_edges:
        neighbors[a].append(b)
        neighbors[b].append(a)

    rows = [[idx(r, c) for c in range(n)] for r in range(n)]
    cols = [[idx(r, c) for r in range(n)] for c in range(n)]

    peers = [set() for _ in range(n * n)]
    for unit in rows + cols:
        for i in unit:
            peers[i].update(unit)
            peers[i].discard(i)
    for i in range(n * n):
        peers[i].update(neighbors[i])

    domains = [full] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                domains[idx(r, c)] = bit(v)

    def assign(dom, i, m):
        old = dom[i]
        new = old & m
        if new == 0:
            return False, False
        if new == old:
            return True, False
        dom[i] = new
        return True, True

    def propagate_inequalities(dom):
        changed = False
        for a, b in less_edges:
            ma = dom[a]
            mb = dom[b]
            mina = min_val(ma)
            maxa = max_val(ma)
            minb = min_val(mb)
            maxb = max_val(mb)

            # a < b
            new_a = ma & mask_le(maxb - 1)
            if new_a == 0:
                return False, changed
            if new_a != ma:
                dom[a] = new_a
                changed = True
                ma = new_a
                mina = min_val(ma)
                maxa = max_val(ma)

            new_b = mb & mask_ge(mina + 1)
            if new_b == 0:
                return False, changed
            if new_b != mb:
                dom[b] = new_b
                changed = True
                mb = new_b
                minb = min_val(mb)
                maxb = max_val(mb)

            if max_val(dom[a]) >= max_val(dom[b]) and popcount(dom[a]) == 1 and popcount(dom[b]) == 1:
                return False, changed
            if min_val(dom[a]) >= max_val(dom[b]):
                return False, changed
        return True, changed

    def propagate_unit_basic(dom, unit):
        changed = False

        # Remove fixed values from peers.
        fixed_mask = 0
        seen = 0
        for i in unit:
            m = dom[i]
            if popcount(m) == 1:
                if seen & m:
                    return False, changed
                seen |= m
                fixed_mask |= m

        if fixed_mask:
            for i in unit:
                m = dom[i]
                if popcount(m) > 1:
                    nm = m & ~fixed_mask
                    if nm == 0:
                        return False, changed
                    if nm != m:
                        dom[i] = nm
                        changed = True

        # Hidden singles.
        for v in range(1, n + 1):
            b = bit(v)
            places = [i for i in unit if dom[i] & b]
            if not places:
                return False, changed
            if len(places) == 1:
                i = places[0]
                if dom[i] != b:
                    dom[i] = b
                    changed = True

        # Naked subsets, limited to size 2..4 for efficiency.
        candidates = [i for i in unit if 1 < popcount(dom[i]) <= min(4, n - 1)]
        by_mask = {}
        for i in candidates:
            by_mask.setdefault(dom[i], []).append(i)
        for m, cells in by_mask.items():
            k = popcount(m)
            if 2 <= k <= min(4, n) and len(cells) == k:
                for i in unit:
                    if i not in cells:
                        nm = dom[i] & ~m
                        if nm == 0:
                            return False, changed
                        if nm != dom[i]:
                            dom[i] = nm
                            changed = True

        return True, changed

    def propagate(dom):
        # Repeatedly apply human-like deductions until saturation.
        while True:
            any_change = False

            ok, ch = propagate_inequalities(dom)
            if not ok:
                return False
            any_change |= ch

            for unit in rows:
                ok, ch = propagate_unit_basic(dom, unit)
                if not ok:
                    return False
                any_change |= ch

            for unit in cols:
                ok, ch = propagate_unit_basic(dom, unit)
                if not ok:
                    return False
                any_change |= ch

            # Additional inequality filtering after unit reductions.
            ok, ch = propagate_inequalities(dom)
            if not ok:
                return False
            any_change |= ch

            # If a row/col is one value short, place it directly.
            for unit in rows + cols:
                used = 0
                unsolved = []
                for i in unit:
                    if popcount(dom[i]) == 1:
                        used |= dom[i]
                    else:
                        unsolved.append(i)
                if len(unsolved) == 1:
                    missing = full & ~used
                    if missing == 0 or popcount(missing) != 1:
                        return False
                    i = unsolved[0]
                    nm = dom[i] & missing
                    if nm == 0:
                        return False
                    if nm != dom[i]:
                        dom[i] = nm
                        any_change = True

            # Sanity checks.
            for i in range(n * n):
                if dom[i] == 0:
                    return False

            if not any_change:
                break
        return True

    def solved(dom):
        return all(popcount(m) == 1 for m in dom)

    def choose_cell(dom):
        best_i = -1
        best_score = None
        for i, m in enumerate(dom):
            pc = popcount(m)
            if pc > 1:
                # MRV + degree heuristic
                score = (pc, -len(peers[i]))
                if best_score is None or score < best_score:
                    best_score = score
                    best_i = i
        return best_i

    def order_values(dom, i):
        # Least-constraining-value heuristic.
        options = []
        for v in vals(dom[i]):
            b = bit(v)
            impact = 0
            for j in peers[i]:
                if dom[j] & b:
                    impact += 1
            # Inequality-sensitive impact.
            for a, bidx in less_edges:
                if a == i:
                    for w in vals(dom[bidx]):
                        if v >= w:
                            impact += 1
                elif bidx == i:
                    for u in vals(dom[a]):
                        if u >= v:
                            impact += 1
            options.append((impact, v))
        options.sort()
        return [v for _, v in options]

    def search(dom):
        if not propagate(dom):
            return None
        if solved(dom):
            return dom

        i = choose_cell(dom)
        if i < 0:
            return None

        for v in order_values(dom, i):
            nd = dom[:]
            nd[i] = bit(v)
            res = search(nd)
            if res is not None:
                return res
        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(min_val(result[idx(r, c)]))
        grid.append(row)
    return grid


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'B', None, None, None, None], [None, None, None, 'B', None, None], [None, None, 'B', None, None, None], [None, None, 'B', 'B', None, None], [None, None, None, None, 'B', None], [None, 'B', None, None, None, None]]}

# Yin-Yang solver:
# - all black cells connected
# - all white cells connected
# - no 2x2 monochrome blocks
#
# The solver emphasizes deduction first:
# 1) direct clue placement
# 2) 2x2 completion rules
# 3) connectivity feasibility checks
# 4) component frontier forcing
# 5) one-step contradiction probing
# Then only limited backtracking remains.

from collections import deque

B = 1
W = 0
U = -1

def solve(observation):
    data = observation['data']
    n = len(data)
    grid = [[U] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                grid[r][c] = B
            elif v == 'W':
                grid[r][c] = W

    solver = YinYangSolver(grid)
    ans = solver.run()
    if ans is None:
        return "No Solution"
    return [[('B' if ans[r][c] == B else 'W') for c in range(n)] for r in range(n)]


class YinYangSolver:
    def __init__(self, grid):
        self.n = len(grid)
        self.blocks = {}
        self.neis = {}
        for r in range(self.n):
            for c in range(self.n):
                b = []
                for br in (r - 1, r):
                    for bc in (c - 1, c):
                        if 0 <= br < self.n - 1 and 0 <= bc < self.n - 1:
                            b.append((br, bc))
                self.blocks[(r, c)] = b
                ns = []
                if r > 0:
                    ns.append((r - 1, c))
                if r + 1 < self.n:
                    ns.append((r + 1, c))
                if c > 0:
                    ns.append((r, c - 1))
                if c + 1 < self.n:
                    ns.append((r, c + 1))
                self.neis[(r, c)] = ns
        self.initial = [row[:] for row in grid]

    def run(self):
        g = [row[:] for row in self.initial]
        g = self.propagate(g)
        if g is None:
            return None
        return self.search(g)

    def copy_grid(self, g):
        return [row[:] for row in g]

    def assign(self, g, r, c, val):
        cur = g[r][c]
        if cur == val:
            return True
        if cur != U and cur != val:
            return False
        g[r][c] = val
        return True

    def block_cells(self, br, bc):
        return [(br, bc), (br + 1, bc), (br, bc + 1), (br + 1, bc + 1)]

    def apply_2x2_rules(self, g):
        changed = False
        for br in range(self.n - 1):
            for bc in range(self.n - 1):
                cells = self.block_cells(br, bc)
                vals = [g[r][c] for r, c in cells]
                for color in (B, W):
                    cnt = sum(v == color for v in vals)
                    unk = [i for i, v in enumerate(vals) if v == U]
                    if cnt == 4:
                        return None, False
                    if cnt == 3:
                        if not unk:
                            return None, False
                        i = unk[0]
                        r, c = cells[i]
                        if not self.assign(g, r, c, 1 - color):
                            return None, False
                        changed = True
        return g, changed

    def assigned_positions(self, g, color):
        out = []
        for r in range(self.n):
            for c in range(self.n):
                if g[r][c] == color:
                    out.append((r, c))
        return out

    def allowed_reachability_ok(self, g, color):
        assigned = self.assigned_positions(g, color)
        if not assigned:
            return True
        opp = 1 - color
        start = assigned[0]
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for nr, nc in self.neis[(r, c)]:
                if (nr, nc) not in seen and g[nr][nc] != opp:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        for pos in assigned:
            if pos not in seen:
                return False
        return True

    def get_components(self, g, color):
        seen = set()
        comps = []
        for r in range(self.n):
            for c in range(self.n):
                if g[r][c] == color and (r, c) not in seen:
                    comp = []
                    q = deque([(r, c)])
                    seen.add((r, c))
                    while q:
                        x, y = q.popleft()
                        comp.append((x, y))
                        for nx, ny in self.neis[(x, y)]:
                            if g[nx][ny] == color and (nx, ny) not in seen:
                                seen.add((nx, ny))
                                q.append((nx, ny))
                    comps.append(comp)
        return comps

    def component_frontier_forcing(self, g):
        changed = False
        for color in (B, W):
            comps = self.get_components(g, color)
            if len(comps) <= 1:
                continue
            for comp in comps:
                frontier = set()
                for r, c in comp:
                    for nr, nc in self.neis[(r, c)]:
                        if g[nr][nc] == U:
                            frontier.add((nr, nc))
                if not frontier:
                    return None, False
                if len(frontier) == 1:
                    rr, cc = next(iter(frontier))
                    if not self.assign(g, rr, cc, color):
                        return None, False
                    changed = True
        return g, changed

    def final_check(self, g):
        for r in range(self.n):
            for c in range(self.n):
                if g[r][c] == U:
                    return False
        for br in range(self.n - 1):
            for bc in range(self.n - 1):
                vals = [g[r][c] for r, c in self.block_cells(br, bc)]
                if vals.count(vals[0]) == 4:
                    return False
        for color in (B, W):
            cells = self.assigned_positions(g, color)
            if not cells:
                return False
            q = deque([cells[0]])
            seen = {cells[0]}
            while q:
                r, c = q.popleft()
                for nr, nc in self.neis[(r, c)]:
                    if g[nr][nc] == color and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if len(seen) != len(cells):
                return False
        return True

    def local_contradiction(self, g, r, c, val):
        h = self.copy_grid(g)
        if not self.assign(h, r, c, val):
            return True
        h = self.propagate(h, probe=True)
        return h is None

    def propagate(self, g, probe=False):
        while True:
            changed_any = False

            out = self.apply_2x2_rules(g)
            if out[0] is None:
                return None
            g, changed = out
            changed_any |= changed

            if not self.allowed_reachability_ok(g, B):
                return None
            if not self.allowed_reachability_ok(g, W):
                return None

            out = self.component_frontier_forcing(g)
            if out[0] is None:
                return None
            g, changed = out
            changed_any |= changed

            if not self.allowed_reachability_ok(g, B):
                return None
            if not self.allowed_reachability_ok(g, W):
                return None

            # One-step contradiction probing:
            # if placing one color immediately breaks rules/feasibility, force the other.
            unknowns = [(r, c) for r in range(self.n) for c in range(self.n) if g[r][c] == U]
            forced = []
            for r, c in unknowns:
                bad_b = self.local_contradiction_shallow(g, r, c, B)
                bad_w = self.local_contradiction_shallow(g, r, c, W)
                if bad_b and bad_w:
                    return None
                if bad_b and not bad_w:
                    forced.append((r, c, W))
                elif bad_w and not bad_b:
                    forced.append((r, c, B))
            if forced:
                for r, c, v in forced:
                    if not self.assign(g, r, c, v):
                        return None
                changed_any = True

            if not changed_any:
                break

        return g

    def local_contradiction_shallow(self, g, r, c, val):
        h = self.copy_grid(g)
        if not self.assign(h, r, c, val):
            return True

        # Cheap local 2x2 implications around the changed cell.
        for br, bc in self.blocks[(r, c)]:
            cells = self.block_cells(br, bc)
            vals = [h[x][y] for x, y in cells]
            for color in (B, W):
                cnt = sum(v == color for v in vals)
                unk = [i for i, v in enumerate(vals) if v == U]
                if cnt == 4:
                    return True
                if cnt == 3 and not unk:
                    return True
                if cnt == 3 and len(unk) == 1:
                    x, y = cells[unk[0]]
                    if h[x][y] == color:
                        return True
                    h[x][y] = 1 - color

        if not self.allowed_reachability_ok(h, B):
            return True
        if not self.allowed_reachability_ok(h, W):
            return True

        for color in (B, W):
            comps = self.get_components(h, color)
            if len(comps) > 1:
                for comp in comps:
                    frontier = set()
                    for x, y in comp:
                        for nx, ny in self.neis[(x, y)]:
                            if h[nx][ny] == U:
                                frontier.add((nx, ny))
                    if not frontier:
                        return True
        return False

    def choose_cell(self, g):
        best = None
        best_score = None
        for r in range(self.n):
            for c in range(self.n):
                if g[r][c] != U:
                    continue
                score = 0
                for br, bc in self.blocks[(r, c)]:
                    vals = [g[x][y] for x, y in self.block_cells(br, bc)]
                    score += sum(v != U for v in vals)
                score += sum(g[nr][nc] != U for nr, nc in self.neis[(r, c)])
                # Prefer cells where one color is already contradicted.
                bad_b = self.local_contradiction_shallow(g, r, c, B)
                bad_w = self.local_contradiction_shallow(g, r, c, W)
                score += 10 * (bad_b + bad_w)
                if best is None or score > best_score:
                    best = (r, c, bad_b, bad_w)
                    best_score = score
        return best

    def search(self, g):
        if all(g[r][c] != U for r in range(self.n) for c in range(self.n)):
            return g if self.final_check(g) else None

        choice = self.choose_cell(g)
        if choice is None:
            return g if self.final_check(g) else None
        r, c, bad_b, bad_w = choice

        if bad_b and bad_w:
            return None
        if bad_b:
            order = [W]
        elif bad_w:
            order = [B]
        else:
            # Slightly prefer the color that matches more assigned neighbors,
            # because it often preserves connectivity and reduces fragmentation.
            nb_b = sum(g[nr][nc] == B for nr, nc in self.neis[(r, c)])
            nb_w = sum(g[nr][nc] == W for nr, nc in self.neis[(r, c)])
            order = [B, W] if nb_b >= nb_w else [W, B]

        for val in order:
            h = self.copy_grid(g)
            if not self.assign(h, r, c, val):
                continue
            h = self.propagate(h)
            if h is None:
                continue
            ans = self.search(h)
            if ans is not None:
                return ans
        return None


if __name__ == "__main__":
    print(solve(OBSERVATION))

