# General Futoshiki solver with strong constraint propagation and limited search.
# Conventions:
# - Horizontal at (r, c+0.5): '<' means cell(r,c) < cell(r,c+1), '>' means >
# - Vertical at (r+0.5, c): '^' means cell(r,c) < cell(r+1,c), 'v' means >
#   Some image parsers may accidentally emit '>' or '<' in vertical slots; those are normalized below.

from itertools import combinations

def solve(observation):
    data = observation['data']
    n = len(data)
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    def values(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    # Parse inequalities into normalized directed constraints (a < b)
    less_edges = []

    for k, sym in observation.get('horizontal', {}).items():
        r, c = eval(k)
        r = int(r)
        c_left = int(c - 0.5)
        a = (r, c_left)
        b = (r, c_left + 1)
        if sym == '<':
            less_edges.append((a, b))
        elif sym == '>':
            less_edges.append((b, a))

    for k, sym in observation.get('vertical', {}).items():
        r, c = eval(k)
        r_top = int(r - 0.5)
        c = int(c)
        a = (r_top, c)
        b = (r_top + 1, c)
        if sym == '^':
            less_edges.append((a, b))
        elif sym == 'v':
            less_edges.append((b, a))
        elif sym == '<':
            less_edges.append((a, b))
        elif sym == '>':
            less_edges.append((b, a))

    # Precompute neighbors for fast impact scoring
    peers = {(r, c): set() for r in range(n) for c in range(n)}
    for r in range(n):
        for c1 in range(n):
            for c2 in range(n):
                if c1 != c2:
                    peers[(r, c1)].add((r, c2))
    for c in range(n):
        for r1 in range(n):
            for r2 in range(n):
                if r1 != r2:
                    peers[(r1, c)].add((r2, c))
    for a, b in less_edges:
        peers[a].add(b)
        peers[b].add(a)

    def copy_domains(dom):
        return [row[:] for row in dom]

    def init_domains():
        dom = [[full for _ in range(n)] for _ in range(n)]
        for r in range(n):
            for c in range(n):
                if data[r][c] is not None:
                    v = data[r][c]
                    dom[r][c] = bit(v)
        return dom

    def assign(dom, r, c, vmask):
        cur = dom[r][c]
        if cur == vmask:
            return True
        if (cur & vmask) == 0:
            return False
        dom[r][c] = vmask
        return True

    def eliminate_mask(dom, r, c, rem):
        newm = dom[r][c] & ~rem
        if newm == 0:
            return False
        dom[r][c] = newm
        return True

    def propagate(dom):
        changed = True
        while changed:
            changed = False

            # Row and column Latin constraints: remove assigned values from peers, detect duplicates
            for r in range(n):
                assigned = 0
                for c in range(n):
                    m = dom[r][c]
                    if popcount(m) == 1:
                        if assigned & m:
                            return False
                        assigned |= m
                for c in range(n):
                    m = dom[r][c]
                    if popcount(m) > 1:
                        nm = m & ~assigned
                        if nm == 0:
                            return False
                        if nm != m:
                            dom[r][c] = nm
                            changed = True
                # Hidden singles in row
                pos = [0] * (n + 1)
                cnt = [0] * (n + 1)
                for c in range(n):
                    m = dom[r][c]
                    mm = m
                    while mm:
                        b = mm & -mm
                        v = b.bit_length()
                        cnt[v] += 1
                        pos[v] = c
                        mm ^= b
                for v in range(1, n + 1):
                    if cnt[v] == 0:
                        return False
                    if cnt[v] == 1:
                        c = pos[v]
                        vm = bit(v)
                        if dom[r][c] != vm:
                            dom[r][c] = vm
                            changed = True
                # Naked subsets by identical masks
                freq = {}
                for c in range(n):
                    m = dom[r][c]
                    if popcount(m) > 1:
                        freq[m] = freq.get(m, 0) + 1
                for m, k in freq.items():
                    if popcount(m) == k:
                        for c in range(n):
                            if dom[r][c] != m and (dom[r][c] & m):
                                nm = dom[r][c] & ~m
                                if nm == 0:
                                    return False
                                if nm != dom[r][c]:
                                    dom[r][c] = nm
                                    changed = True

            for c in range(n):
                assigned = 0
                for r in range(n):
                    m = dom[r][c]
                    if popcount(m) == 1:
                        if assigned & m:
                            return False
                        assigned |= m
                for r in range(n):
                    m = dom[r][c]
                    if popcount(m) > 1:
                        nm = m & ~assigned
                        if nm == 0:
                            return False
                        if nm != m:
                            dom[r][c] = nm
                            changed = True
                # Hidden singles in column
                pos = [0] * (n + 1)
                cnt = [0] * (n + 1)
                for r in range(n):
                    m = dom[r][c]
                    mm = m
                    while mm:
                        b = mm & -mm
                        v = b.bit_length()
                        cnt[v] += 1
                        pos[v] = r
                        mm ^= b
                for v in range(1, n + 1):
                    if cnt[v] == 0:
                        return False
                    if cnt[v] == 1:
                        r = pos[v]
                        vm = bit(v)
                        if dom[r][c] != vm:
                            dom[r][c] = vm
                            changed = True
                # Naked subsets by identical masks
                freq = {}
                for r in range(n):
                    m = dom[r][c]
                    if popcount(m) > 1:
                        freq[m] = freq.get(m, 0) + 1
                for m, k in freq.items():
                    if popcount(m) == k:
                        for r in range(n):
                            if dom[r][c] != m and (dom[r][c] & m):
                                nm = dom[r][c] & ~m
                                if nm == 0:
                                    return False
                                if nm != dom[r][c]:
                                    dom[r][c] = nm
                                    changed = True

            # Inequality propagation on min/max bounds
            for (ar, ac), (br, bc) in less_edges:
                ma = dom[ar][ac]
                mb = dom[br][bc]
                mina = min_val(ma)
                maxa = max_val(ma)
                minb = min_val(mb)
                maxb = max_val(mb)

                # A < B implies:
                # A cannot be >= max(B), B cannot be <= min(A)
                allow_a = (1 << (maxb - 1)) - 1 if maxb > 1 else 0
                allow_b = full & ~((1 << mina) - 1)
                nma = ma & allow_a
                nmb = mb & allow_b
                if nma == 0 or nmb == 0:
                    return False
                if nma != ma:
                    dom[ar][ac] = nma
                    changed = True
                    ma = nma
                if nmb != mb:
                    dom[br][bc] = nmb
                    changed = True
                    mb = nmb

                # Stronger support check: remove values with no supporting larger/smaller value
                maxb_cur = max_val(mb)
                mina_cur = min_val(ma)
                sup_a = 0
                mm = ma
                while mm:
                    b = mm & -mm
                    v = b.bit_length()
                    if v < maxb_cur:
                        sup_a |= b
                    mm ^= b
                sup_b = 0
                mm = mb
                while mm:
                    b = mm & -mm
                    v = b.bit_length()
                    if v > mina_cur:
                        sup_b |= b
                    mm ^= b
                if sup_a == 0 or sup_b == 0:
                    return False
                if sup_a != ma:
                    dom[ar][ac] = sup_a
                    changed = True
                if sup_b != mb:
                    dom[br][bc] = sup_b
                    changed = True

            # Optional stronger Hall-subset checks for small domains (pairs/triples) in each unit
            # This mirrors human "naked pair/triple" logic but only for compact candidates.
            for is_row in (True, False):
                for idx in range(n):
                    cells = [(idx, j) if is_row else (j, idx) for j in range(n)]
                    cand_cells = [(r, c, dom[r][c]) for r, c in cells if 1 < popcount(dom[r][c]) <= 4]
                    L = len(cand_cells)
                    for k in (2, 3, 4):
                        if L < k:
                            continue
                        for comb in combinations(cand_cells, k):
                            union = 0
                            coords = []
                            for r, c, m in comb:
                                union |= m
                                coords.append((r, c))
                            if popcount(union) == k:
                                coordset = set(coords)
                                for r, c in cells:
                                    if (r, c) not in coordset and (dom[r][c] & union):
                                        nm = dom[r][c] & ~union
                                        if nm == 0:
                                            return False
                                        if nm != dom[r][c]:
                                            dom[r][c] = nm
                                            changed = True

            # Final zero/contradiction sanity
            for r in range(n):
                for c in range(n):
                    if dom[r][c] == 0:
                        return False

        return True

    def solved(dom):
        return all(popcount(dom[r][c]) == 1 for r in range(n) for c in range(n))

    def extract(dom):
        return [[min_val(dom[r][c]) for c in range(n)] for r in range(n)]

    def choose_cell(dom):
        # MRV + degree heuristic: smallest domain, then most constrained by peers.
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                m = dom[r][c]
                pc = popcount(m)
                if pc > 1:
                    key = (pc, -len(peers[(r, c)]))
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def order_values(dom, r, c):
        # Least-constraining value: keep values that eliminate fewer peer options first.
        scores = []
        for v in values(dom[r][c]):
            b = bit(v)
            impact = 0
            for rr, cc in peers[(r, c)]:
                m = dom[rr][cc]
                if popcount(m) > 1:
                    if rr == r or cc == c:
                        if m & b:
                            impact += 1
                    # inequality impact estimate
                    for a, bcell in less_edges:
                        if (r, c) == a and (rr, cc) == bcell:
                            # assigned A=v => B must be > v
                            impact += popcount(m & ((1 << v) - 1))
                        elif (r, c) == bcell and (rr, cc) == a:
                            # assigned B=v => A must be < v
                            impact += popcount(m & ~((1 << (v - 1)) - 1))
            scores.append((impact, v))
        scores.sort()
        return [v for _, v in scores]

    def dfs(dom):
        if not propagate(dom):
            return None
        if solved(dom):
            return extract(dom)

        r, c = choose_cell(dom)
        for v in order_values(dom, r, c):
            nd = copy_domains(dom)
            if assign(nd, r, c, bit(v)):
                ans = dfs(nd)
                if ans is not None:
                    return ans
        return None

    result = dfs(init_domains())
    return str(result) if result is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, 4, None, None]], 'horizontal': {'(0,1.5)': '>', '(0,3.5)': '>', '(0,5.5)': '>', '(1,0.5)': '>', '(1,2.5)': '>', '(1,3.5)': '>', '(2,3.5)': '>', '(3,3.5)': '>', '(3,5.5)': '>', '(4,0.5)': '>', '(4,1.5)': '<', '(4,3.5)': '>', '(4,4.5)': '>', '(5,2.5)': '>', '(6,1.5)': '<'}, 'vertical': {'(0.5,0)': 'v', '(0.5,1)': '^', '(0.5,4)': 'v', '(1.5,6)': 'v', '(2.5,1)': 'v', '(2.5,2)': 'v', '(3.5,0)': 'v', '(3.5,1)': 'v', '(4.5,1)': 'v', '(4.5,5)': 'v', '(5.5,5)': '^', '(5.5,6)': '^'}}

# General Futoshiki solver with strong propagation and light search.
# Conventions used for inequalities:
# Horizontal at (r, c+0.5):
#   '<' means cell(r,c) < cell(r,c+1)
#   '>' means cell(r,c) > cell(r,c+1)
# Vertical at (r+0.5, c):
#   '^' means cell(r,c) < cell(r+1,c)
#   'v' means cell(r,c) > cell(r+1,c)

ALL = 0

def bit(v):
    return 1 << (v - 1)

def popcount(x):
    return x.bit_count()

def min_val(mask):
    return (mask & -mask).bit_length()

def max_val(mask):
    return mask.bit_length()

def mask_to_values(mask, n):
    vals = []
    while mask:
        b = mask & -mask
        vals.append(b.bit_length())
        mask ^= b
    return vals

def parse_key(s):
    s = s.strip()
    if s[0] == '(' and s[-1] == ')':
        s = s[1:-1]
    a, b = s.split(',')
    return float(a), float(b)

def build_constraints(observation):
    n = len(observation['data'])
    global ALL
    ALL = (1 << n) - 1

    horiz = []
    for k, sym in observation.get('horizontal', {}).items():
        r, c = parse_key(k)
        r = int(r)
        c_left = int(c - 0.5)
        if sym == '<':
            horiz.append((r, c_left, r, c_left + 1, '<'))
        else:
            horiz.append((r, c_left, r, c_left + 1, '>'))

    vert = []
    for k, sym in observation.get('vertical', {}).items():
        r, c = parse_key(k)
        r_top = int(r - 0.5)
        c = int(c)
        if sym == '^':
            vert.append((r_top, c, r_top + 1, c, '<'))
        else:
            vert.append((r_top, c, r_top + 1, c, '>'))

    ineq = horiz + vert

    neighbors = [[set() for _ in range(n)] for _ in range(n)]
    rels = [[[] for _ in range(n)] for _ in range(n)]
    for r1, c1, r2, c2, op in ineq:
        neighbors[r1][c1].add((r2, c2))
        neighbors[r2][c2].add((r1, c1))
        rels[r1][c1].append((r2, c2, op))
        rels[r2][c2].append((r1, c1, '<' if op == '>' else '>'))

    return n, ineq, neighbors, rels

def init_domains(observation):
    n = len(observation['data'])
    dom = [[ALL for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = observation['data'][r][c]
            if v is not None:
                dom[r][c] = bit(v)
    return dom

def remove_used_from_units(dom, n):
    changed = False
    for r in range(n):
        used = 0
        for c in range(n):
            if dom[r][c] and dom[r][c] & (dom[r][c] - 1) == 0:
                used |= dom[r][c]
        for c in range(n):
            if popcount(dom[r][c]) > 1:
                newm = dom[r][c] & ~used
                if newm != dom[r][c]:
                    if newm == 0:
                        return None, True
                    dom[r][c] = newm
                    changed = True

    for c in range(n):
        used = 0
        for r in range(n):
            if dom[r][c] and dom[r][c] & (dom[r][c] - 1) == 0:
                used |= dom[r][c]
        for r in range(n):
            if popcount(dom[r][c]) > 1:
                newm = dom[r][c] & ~used
                if newm != dom[r][c]:
                    if newm == 0:
                        return None, True
                    dom[r][c] = newm
                    changed = True
    return dom, changed

def enforce_hidden_singles(dom, n):
    changed = False
    for r in range(n):
        pos = [0] * (n + 1)
        cnt = [0] * (n + 1)
        for c in range(n):
            m = dom[r][c]
            while m:
                b = m & -m
                v = b.bit_length()
                cnt[v] += 1
                pos[v] = c
                m ^= b
        for v in range(1, n + 1):
            if cnt[v] == 0:
                return None, True
            if cnt[v] == 1:
                c = pos[v]
                nm = bit(v)
                if dom[r][c] != nm:
                    dom[r][c] = nm
                    changed = True

    for c in range(n):
        pos = [0] * (n + 1)
        cnt = [0] * (n + 1)
        for r in range(n):
            m = dom[r][c]
            while m:
                b = m & -m
                v = b.bit_length()
                cnt[v] += 1
                pos[v] = r
                m ^= b
        for v in range(1, n + 1):
            if cnt[v] == 0:
                return None, True
            if cnt[v] == 1:
                r = pos[v]
                nm = bit(v)
                if dom[r][c] != nm:
                    dom[r][c] = nm
                    changed = True
    return dom, changed

def enforce_inequalities(dom, n, ineq):
    changed = False
    for r1, c1, r2, c2, op in ineq:
        a = dom[r1][c1]
        b = dom[r2][c2]
        if op == '<':
            max_b = max_val(b)
            min_a = min_val(a)
            new_a = a & ((1 << (max_b - 1)) - 1 if max_b > 1 else 0)
            new_b = b & ~((1 << min_a) - 1)
        else:
            min_b = min_val(b)
            max_a = max_val(a)
            new_a = a & ~((1 << min_b) - 1)
            new_b = b & ((1 << (max_a - 1)) - 1 if max_a > 1 else 0)

        if new_a != a:
            if new_a == 0:
                return None, True
            dom[r1][c1] = new_a
            changed = True
        if new_b != b:
            if new_b == 0:
                return None, True
            dom[r2][c2] = new_b
            changed = True
    return dom, changed

def enforce_unit_bounds(dom, n, rels):
    # Human-like range tightening:
    # in each row/col, if k cells already force <= t values, others cannot all also be <= t.
    # Implement via Hall-style prefix/suffix counting on candidate intervals.
    changed = False

    def process_cells(cells):
        nonlocal changed
        # Prefix constraints for values 1..t
        for t in range(1, n):
            allowed_subset = (1 << t) - 1
            forced = []
            possible = []
            for r, c in cells:
                m = dom[r][c]
                if m & ~allowed_subset == 0:
                    forced.append((r, c))
                if m & allowed_subset:
                    possible.append((r, c))
            if len(forced) > t:
                return False
            if len(possible) == t:
                for r, c in possible:
                    nm = dom[r][c] & allowed_subset
                    if nm == 0:
                        return False
                    if nm != dom[r][c]:
                        dom[r][c] = nm
                        changed = True
                poss_set = set(possible)
                for r, c in cells:
                    if (r, c) not in poss_set:
                        nm = dom[r][c] & ~allowed_subset
                        if nm == 0:
                            return False
                        if nm != dom[r][c]:
                            dom[r][c] = nm
                            changed = True
            if len(forced) == t:
                forced_set = set(forced)
                for r, c in cells:
                    if (r, c) not in forced_set:
                        nm = dom[r][c] & ~allowed_subset
                        if nm == 0:
                            return False
                        if nm != dom[r][c]:
                            dom[r][c] = nm
                            changed = True

        # Suffix constraints for values t..n
        for t in range(2, n + 1):
            lower_mask = (1 << (t - 1)) - 1
            upper_mask = ALL & ~lower_mask
            forced = []
            possible = []
            cap = n - t + 1
            for r, c in cells:
                m = dom[r][c]
                if m & lower_mask == 0:
                    forced.append((r, c))
                if m & upper_mask:
                    possible.append((r, c))
            if len(forced) > cap:
                return False
            if len(possible) == cap:
                for r, c in possible:
                    nm = dom[r][c] & upper_mask
                    if nm == 0:
                        return False
                    if nm != dom[r][c]:
                        dom[r][c] = nm
                        changed = True
                poss_set = set(possible)
                for r, c in cells:
                    if (r, c) not in poss_set:
                        nm = dom[r][c] & lower_mask
                        if nm == 0:
                            return False
                        if nm != dom[r][c]:
                            dom[r][c] = nm
                            changed = True
            if len(forced) == cap:
                forced_set = set(forced)
                for r, c in cells:
                    if (r, c) not in forced_set:
                        nm = dom[r][c] & lower_mask
                        if nm == 0:
                            return False
                        if nm != dom[r][c]:
                            dom[r][c] = nm
                            changed = True
        return True

    for r in range(n):
        if not process_cells([(r, c) for c in range(n)]):
            return None, True
    for c in range(n):
        if not process_cells([(r, c) for r in range(n)]):
            return None, True
    return dom, changed

def check_contradiction(dom, n):
    for r in range(n):
        row_singles = 0
        for c in range(n):
            m = dom[r][c]
            if m == 0:
                return True
            if m & (m - 1) == 0:
                if row_singles & m:
                    return True
                row_singles |= m
    for c in range(n):
        col_singles = 0
        for r in range(n):
            m = dom[r][c]
            if m & (m - 1) == 0:
                if col_singles & m:
                    return True
                col_singles |= m
    return False

def propagate(dom, n, ineq, rels):
    while True:
        if check_contradiction(dom, n):
            return None

        any_change = False

        dom, ch = remove_used_from_units(dom, n)
        if dom is None:
            return None
        any_change |= ch

        dom, ch = enforce_inequalities(dom, n, ineq)
        if dom is None:
            return None
        any_change |= ch

        dom, ch = enforce_hidden_singles(dom, n)
        if dom is None:
            return None
        any_change |= ch

        dom, ch = enforce_unit_bounds(dom, n, rels)
        if dom is None:
            return None
        any_change |= ch

        dom, ch = enforce_inequalities(dom, n, ineq)
        if dom is None:
            return None
        any_change |= ch

        if not any_change:
            break
    return dom

def solved(dom, n):
    return all(dom[r][c] & (dom[r][c] - 1) == 0 for r in range(n) for c in range(n))

def choose_var(dom, n, rels):
    best = None
    best_key = None
    for r in range(n):
        for c in range(n):
            m = dom[r][c]
            pc = popcount(m)
            if pc > 1:
                degree = len(rels[r][c])
                # Prefer smallest domain, then more constrained by inequalities, then central-ish
                key = (pc, -degree, abs(r - (n - 1) / 2) + abs(c - (n - 1) / 2))
                if best_key is None or key < best_key:
                    best_key = key
                    best = (r, c)
    return best

def order_values(mask, r, c, dom, n, rels):
    vals = mask_to_values(mask, n)
    scored = []
    for v in vals:
        score = 0
        for nr, nc, op in rels[r][c]:
            nm = dom[nr][nc]
            if op == '<':
                # current < neighbor
                allowed = nm & ~((1 << v) - 1)
            else:
                allowed = nm & ((1 << (v - 1)) - 1 if v > 1 else 0)
            score += popcount(allowed)
        scored.append((-score, v))
    scored.sort()
    return [v for _, v in scored]

def domains_to_grid(dom, n):
    return [[min_val(dom[r][c]) for c in range(n)] for r in range(n)]

def search(dom, n, ineq, rels):
    dom = propagate(dom, n, ineq, rels)
    if dom is None:
        return None
    if solved(dom, n):
        return dom

    r, c = choose_var(dom, n, rels)
    for v in order_values(dom[r][c], r, c, dom, n, rels):
        new_dom = [row[:] for row in dom]
        new_dom[r][c] = bit(v)
        res = search(new_dom, n, ineq, rels)
        if res is not None:
            return res
    return None

def solve(observation):
    n, ineq, neighbors, rels = build_constraints(observation)
    dom = init_domains(observation)
    res = search(dom, n, ineq, rels)
    if res is None:
        return "No Solution"
    return str(domains_to_grid(res, n))

if __name__ == "__main__":
    print(solve(OBSERVATION))

