from collections import deque
from copy import deepcopy

# State encoding:
# -1 = unknown
#  0 = white
#  1 = black

def solve(observation):
    data = observation["data"]
    n = len(data)
    clues = {}
    clue_cells = set()
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]
                clue_cells.add((r, c))

    rays = {}
    cell_to_clues = {}
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for pos in clues:
        r, c = pos
        rr = []
        for dr, dc in dirs:
            line = []
            nr, nc = r + dr, c + dc
            while 0 <= nr < n and 0 <= nc < n:
                line.append((nr, nc))
                cell_to_clues.setdefault((nr, nc), set()).add(pos)
                nr += dr
                nc += dc
            rr.append(line)
        rays[pos] = rr

    impact = {}
    for r in range(n):
        for c in range(n):
            impact[(r, c)] = len(cell_to_clues.get((r, c), ()))

    def make_state():
        st = [[-1] * n for _ in range(n)]
        for r, c in clue_cells:
            st[r][c] = 0
        return st

    def copy_state(st):
        return [row[:] for row in st]

    def neighbors(r, c):
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                yield nr, nc

    def visible_count(st, r, c):
        total = 1
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            while 0 <= nr < n and 0 <= nc < n and st[nr][nc] != 1:
                total += 1
                nr += dr
                nc += dc
        return total

    def feasible_k_for_ray(ray, st):
        # k = number of visible white cells in this ray
        # first k cells must be non-black; if k < len(ray), the next cell must be non-white (i.e. black/unknown -> can be black)
        res = []
        L = len(ray)
        for k in range(L + 1):
            ok = True
            for i in range(k):
                r, c = ray[i]
                if st[r][c] == 1:
                    ok = False
                    break
            if not ok:
                continue
            if k < L:
                r, c = ray[k]
                if st[r][c] == 0:
                    continue
            res.append(k)
        return res

    def clue_models(pos, st):
        target = clues[pos] - 1
        ray_list = rays[pos]
        per_ray = [feasible_k_for_ray(ray, st) for ray in ray_list]
        if any(len(x) == 0 for x in per_ray):
            return []

        models = []

        # small fixed branching: 4 directions only
        for a in per_ray[0]:
            if a > target:
                continue
            for b in per_ray[1]:
                if a + b > target:
                    continue
                for c in per_ray[2]:
                    if a + b + c > target:
                        continue
                    d = target - a - b - c
                    if d in per_ray[3]:
                        models.append((a, b, c, d))
        return models

    def check_white_connectivity_possible(st):
        forced = [(r, c) for r in range(n) for c in range(n) if st[r][c] == 0]
        if not forced:
            return True
        start = forced[0]
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for nr, nc in neighbors(r, c):
                if st[nr][nc] != 1 and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return all((r, c) in seen for r, c in forced)

    def forced_whites_connected_if_block(st, block):
        forced = [(r, c) for r in range(n) for c in range(n) if st[r][c] == 0 and (r, c) != block]
        if not forced:
            return True
        start = forced[0]
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for nr, nc in neighbors(r, c):
                if (nr, nc) == block:
                    continue
                if st[nr][nc] != 1 and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        return all((r, c) in seen for r, c in forced)

    def assign(st, r, c, val):
        cur = st[r][c]
        if cur == val:
            return True
        if cur != -1:
            return False
        if (r, c) in clue_cells and val == 1:
            return False
        st[r][c] = val
        return True

    def propagate(st):
        changed = True
        while changed:
            changed = False

            # Clues are always white.
            for r, c in clue_cells:
                if st[r][c] == 1:
                    return None
                if st[r][c] == -1:
                    st[r][c] = 0
                    changed = True

            # Black adjacency forbids orthogonally touching black cells.
            for r in range(n):
                for c in range(n):
                    if st[r][c] == 1:
                        for nr, nc in neighbors(r, c):
                            if st[nr][nc] == 1:
                                return None
                            if st[nr][nc] == -1:
                                if not assign(st, nr, nc, 0):
                                    return None
                                changed = True

            # Strong clue-based local reasoning from all feasible visibility patterns.
            for pos in clues:
                models = clue_models(pos, st)
                if not models:
                    return None
                ray_list = rays[pos]

                # Deductions common to all models.
                for d_idx, ray in enumerate(ray_list):
                    for i, cell in enumerate(ray):
                        must_white = True
                        must_black = True
                        for model in models:
                            k = model[d_idx]
                            if i < k:
                                must_black = False
                            elif i == k and k < len(ray):
                                must_white = False
                            else:
                                must_white = False
                                must_black = False
                        r, c = cell
                        if must_white:
                            if not assign(st, r, c, 0):
                                return None
                            changed = True
                        elif must_black:
                            if not assign(st, r, c, 1):
                                return None
                            changed = True

            # Cheap min/max clue consistency check.
            for pos, clue in clues.items():
                total_min = 1
                total_max = 1
                for ray in rays[pos]:
                    # min: forced white prefix until first non-white
                    mn = 0
                    for r, c in ray:
                        if st[r][c] == 0:
                            mn += 1
                        else:
                            break
                    # max: until first fixed black
                    mx = 0
                    for r, c in ray:
                        if st[r][c] == 1:
                            break
                        mx += 1
                    total_min += mn
                    total_max += mx
                if total_min > clue or total_max < clue:
                    return None
                if total_min == clue:
                    for ray in rays[pos]:
                        idx = 0
                        while idx < len(ray) and st[ray[idx][0]][ray[idx][1]] == 0:
                            idx += 1
                        if idx < len(ray):
                            r, c = ray[idx]
                            if not assign(st, r, c, 1):
                                return None
                            changed = True
                if total_max == clue:
                    for ray in rays[pos]:
                        for r, c in ray:
                            if st[r][c] == 1:
                                break
                            if not assign(st, r, c, 0):
                                return None
                            changed = True

            # White connectivity must remain possible.
            if not check_white_connectivity_possible(st):
                return None

            # If making an unknown black would disconnect forced whites, it must be white.
            forced = [(r, c) for r in range(n) for c in range(n) if st[r][c] == 0]
            if len(forced) >= 2:
                for r in range(n):
                    for c in range(n):
                        if st[r][c] == -1:
                            if not forced_whites_connected_if_block(st, (r, c)):
                                if not assign(st, r, c, 0):
                                    return None
                                changed = True

        return st

    def is_complete(st):
        return all(st[r][c] != -1 for r in range(n) for c in range(n))

    def final_check(st):
        # Clues exact
        for (r, c), clue in clues.items():
            if st[r][c] != 0:
                return False
            if visible_count(st, r, c) != clue:
                return False

        # Black non-touching
        for r in range(n):
            for c in range(n):
                if st[r][c] == 1:
                    for nr, nc in neighbors(r, c):
                        if st[nr][nc] == 1:
                            return False

        # White connected
        whites = [(r, c) for r in range(n) for c in range(n) if st[r][c] == 0]
        if whites:
            start = whites[0]
            q = deque([start])
            seen = {start}
            while q:
                r, c = q.popleft()
                for nr, nc in neighbors(r, c):
                    if st[nr][nc] == 0 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if len(seen) != len(whites):
                return False

        return True

    def choose_cell(st):
        # Prefer cells with strongest clue interaction and local restriction.
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                if st[r][c] != -1:
                    continue
                clue_score = impact[(r, c)]
                adj_black = sum(1 for nr, nc in neighbors(r, c) if st[nr][nc] == 1)
                adj_white = sum(1 for nr, nc in neighbors(r, c) if st[nr][nc] == 0)
                key = (-clue_score, -adj_black, -adj_white)
                if best is None or key < best_key:
                    best = (r, c)
                    best_key = key
        return best

    def branch_order(st, cell):
        r, c = cell
        # Test both quickly; keep only feasible branches, prefer the one causing more propagation.
        options = []
        for val in (1, 0):
            if (r, c) in clue_cells and val == 1:
                continue
            ns = copy_state(st)
            if not assign(ns, r, c, val):
                continue
            ns = propagate(ns)
            if ns is not None:
                undec = sum(1 for rr in range(n) for cc in range(n) if ns[rr][cc] == -1)
                options.append((undec, val, ns))
        options.sort()
        return options

    def dfs(st):
        st = propagate(st)
        if st is None:
            return None
        if is_complete(st):
            return st if final_check(st) else None

        cell = choose_cell(st)
        if cell is None:
            return st if final_check(st) else None

        for _, _, ns in branch_order(st, cell):
            ans = dfs(ns)
            if ans is not None:
                return ans
        return None

    state = make_state()
    solved = dfs(state)
    if solved is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            if data[r][c] is not None:
                row.append(data[r][c])
            elif solved[r][c] == 1:
                row.append('B')
            else:
                row.append(None)
        out.append(row)
    return repr(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None], [None, None, None, 5, None], [None, None, None, None, 1], [None, None, None, None, None], [1, None, 3, None, None]]}

from collections import deque
from copy import deepcopy

# Nurikabe solver using strong propagation + limited backtracking.
# Domain per cell: {'B'} union clue ids that the cell may belong to.

def solve(observation):
    data = observation['data']
    h = len(data)
    w = len(data[0]) if h else 0

    clues = []
    clue_at = {}
    for r in range(h):
        for c in range(w):
            if data[r][c] is not None:
                idx = len(clues)
                clues.append((r, c, data[r][c]))
                clue_at[(r, c)] = idx

    if not clues:
        return "No Solution"

    B = 'B'
    cells = [(r, c) for r in range(h) for c in range(w)]

    nbrs = {}
    for r, c in cells:
        ns = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                ns.append((rr, cc))
        nbrs[(r, c)] = ns

    # Initial geometric pruning: a cell can belong to clue i only if Manhattan distance <= size-1.
    # This is necessary (not sufficient), so safe.
    domains = {}
    for r, c in cells:
        if (r, c) in clue_at:
            domains[(r, c)] = {clue_at[(r, c)]}
        else:
            d = {B}
            for i, (cr, cc, size) in enumerate(clues):
                if abs(r - cr) + abs(c - cc) <= size - 1:
                    d.add(i)
            domains[(r, c)] = d

    def copy_domains(dom):
        return {k: set(v) for k, v in dom.items()}

    def is_fixed(dom, cell):
        return len(dom[cell]) == 1

    def fixed_value(dom, cell):
        return next(iter(dom[cell])) if len(dom[cell]) == 1 else None

    def remove_value(dom, cell, val):
        if val not in dom[cell]:
            return True, False
        if len(dom[cell]) == 1:
            return False, False
        dom[cell].remove(val)
        if not dom[cell]:
            return False, False
        return True, True

    def set_value(dom, cell, val):
        if dom[cell] == {val}:
            return True, False
        if val not in dom[cell]:
            return False, False
        dom[cell].clear()
        dom[cell].add(val)
        return True, True

    def region_cells_for_clue(dom, i):
        cr, cc, _ = clues[i]
        start = (cr, cc)
        q = deque([start])
        seen = {start}
        while q:
            x = q.popleft()
            for y in nbrs[x]:
                if y not in seen and i in dom[y]:
                    seen.add(y)
                    q.append(y)
        return seen

    def fixed_cells_for_clue(dom, i):
        return {cell for cell in cells if dom[cell] == {i}}

    def possible_black_cells(dom):
        return {cell for cell in cells if B in dom[cell]}

    def fixed_black_cells(dom):
        return {cell for cell in cells if dom[cell] == {B}}

    def black_connectivity_possible(dom):
        blacks = list(fixed_black_cells(dom))
        if not blacks:
            return True
        canb = possible_black_cells(dom)
        start = blacks[0]
        q = deque([start])
        seen = {start}
        while q:
            x = q.popleft()
            for y in nbrs[x]:
                if y in canb and y not in seen:
                    seen.add(y)
                    q.append(y)
        return all(b in seen for b in blacks)

    def black_connected_final(dom):
        blacks = list(fixed_black_cells(dom))
        if not blacks:
            return True
        q = deque([blacks[0]])
        seen = {blacks[0]}
        while q:
            x = q.popleft()
            for y in nbrs[x]:
                if dom[y] == {B} and y not in seen:
                    seen.add(y)
                    q.append(y)
        return len(seen) == len(blacks)

    def no_2x2_final_black(dom):
        for r in range(h - 1):
            for c in range(w - 1):
                block = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                if all(dom[x] == {B} for x in block):
                    return False
        return True

    def island_final_ok(dom, i):
        cr, cc, size = clues[i]
        island = [cell for cell in cells if dom[cell] == {i}]
        if len(island) != size:
            return False
        q = deque([(cr, cc)])
        seen = {(cr, cc)}
        while q:
            x = q.popleft()
            for y in nbrs[x]:
                if dom[y] == {i} and y not in seen:
                    seen.add(y)
                    q.append(y)
        return len(seen) == size

    def final_check(dom):
        for cell in cells:
            if len(dom[cell]) != 1:
                return False
        if not no_2x2_final_black(dom):
            return False
        if not black_connected_final(dom):
            return False
        for i in range(len(clues)):
            if not island_final_ok(dom, i):
                return False
        return True

    def propagate(dom):
        changed = True
        while changed:
            changed = False

            # Domain emptiness / fixed clue sanity.
            for cell in cells:
                if not dom[cell]:
                    return None

            # Rule: numbered cells fixed to their clue already; also clue cells cannot appear elsewhere as clue ownership conflicts.
            for i, (cr, cc, size) in enumerate(clues):
                if dom[(cr, cc)] != {i}:
                    return None

            # Rule: adjacent different islands cannot touch orthogonally.
            for cell in cells:
                if len(dom[cell]) == 1:
                    v = next(iter(dom[cell]))
                    if v != B:
                        for nb in nbrs[cell]:
                            for x in list(dom[nb]):
                                if x != B and x != v:
                                    ok, ch = remove_value(dom, nb, x)
                                    if not ok:
                                        return None
                                    changed |= ch

            # Rule: for any candidate island assignment, if neighbor is fixed to another island, remove that candidate.
            for cell in cells:
                if dom[cell] != {B}:
                    for i in [x for x in dom[cell] if x != B]:
                        bad = False
                        for nb in nbrs[cell]:
                            fv = fixed_value(dom, nb)
                            if fv is not None and fv != B and fv != i:
                                bad = True
                                break
                        if bad:
                            ok, ch = remove_value(dom, cell, i)
                            if not ok:
                                return None
                            changed |= ch

            # Rule: no 2x2 all black; if 3 are black, 4th cannot be black.
            for r in range(h - 1):
                for c in range(w - 1):
                    block = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                    fixed_b = [x for x in block if dom[x] == {B}]
                    possible_b = [x for x in block if B in dom[x]]
                    if len(possible_b) == 4 and len(fixed_b) == 4:
                        return None
                    if len(fixed_b) == 3:
                        for x in block:
                            if dom[x] != {B} and B in dom[x]:
                                ok, ch = remove_value(dom, x, B)
                                if not ok:
                                    return None
                                changed |= ch

            # Per-island reachability, size, and forced growth/fill rules.
            for i, (cr, cc, size) in enumerate(clues):
                region = region_cells_for_clue(dom, i)
                fixed_i = fixed_cells_for_clue(dom, i)

                # Any fixed i must be connected to clue through cells that can still be i.
                if not fixed_i.issubset(region):
                    return None

                if len(region) < size:
                    return None
                if len(fixed_i) > size:
                    return None

                # If island already full, all other possible cells for it are forbidden.
                if len(fixed_i) == size:
                    for cell in list(region):
                        if cell not in fixed_i and i in dom[cell]:
                            ok, ch = remove_value(dom, cell, i)
                            if not ok:
                                return None
                            changed |= ch

                # If all reachable cells are needed, force them.
                region = region_cells_for_clue(dom, i)
                fixed_i = fixed_cells_for_clue(dom, i)
                if len(region) == size:
                    for cell in region:
                        ok, ch = set_value(dom, cell, i)
                        if not ok:
                            return None
                        changed |= ch

                # If a cell can be i but is no longer connected to clue through i-possible cells, remove i.
                for cell in cells:
                    if i in dom[cell] and cell not in region:
                        ok, ch = remove_value(dom, cell, i)
                        if not ok:
                            return None
                        changed |= ch

                # If exactly remaining_needed frontier cells are the only expansion path, force them.
                fixed_i = fixed_cells_for_clue(dom, i)
                need = size - len(fixed_i)
                if need < 0:
                    return None
                if need > 0:
                    frontier = set()
                    for cell in fixed_i:
                        for nb in nbrs[cell]:
                            if i in dom[nb] and dom[nb] != {i}:
                                frontier.add(nb)
                    if len(frontier) == need:
                        for cell in frontier:
                            ok, ch = set_value(dom, cell, i)
                            if not ok:
                                return None
                            changed |= ch

            # Any non-clue cell that cannot belong to any island must be black.
            for cell in cells:
                if cell in clue_at:
                    continue
                if dom[cell] != {B} and all(x == B for x in dom[cell]):
                    ok, ch = set_value(dom, cell, B)
                    if not ok:
                        return None
                    changed |= ch

            # White cells with no black option and only one island candidate can be fixed.
            for cell in cells:
                if len(dom[cell]) > 1:
                    nonb = [x for x in dom[cell] if x != B]
                    if B not in dom[cell] and len(nonb) == 1:
                        ok, ch = set_value(dom, cell, nonb[0])
                        if not ok:
                            return None
                        changed |= ch
                    elif len(nonb) == 0:
                        ok, ch = set_value(dom, cell, B)
                        if not ok:
                            return None
                        changed |= ch

            # Global black connectivity feasibility.
            if not black_connectivity_possible(dom):
                return None

            # White component sanity:
            # a fixed white component may contain at most one clue-id type;
            # if it contains one type i, size cannot exceed clue size.
            seen = set()
            for cell in cells:
                if cell in seen:
                    continue
                if len(dom[cell]) == 1 and next(iter(dom[cell])) != B:
                    val = next(iter(dom[cell]))
                    q = deque([cell])
                    comp = {cell}
                    seen.add(cell)
                    while q:
                        x = q.popleft()
                        for y in nbrs[x]:
                            if y not in seen and dom[y] == {val}:
                                seen.add(y)
                                comp.add(y)
                                q.append(y)
                    if len(comp) > clues[val][2]:
                        return None

        return dom

    def choose_branch_cell(dom):
        best = None
        best_key = None

        # Prefer cells with smallest domain; prefer fewer non-black candidates and more local constraints.
        for cell in cells:
            if len(dom[cell]) > 1:
                nonb = [x for x in dom[cell] if x != B]
                fixed_neighbors = sum(1 for nb in nbrs[cell] if len(dom[nb]) == 1)
                key = (len(dom[cell]), len(nonb), -fixed_neighbors)
                if best_key is None or key < best_key:
                    best_key = key
                    best = cell
        return best

    def value_order(dom, cell):
        vals = list(dom[cell])
        # Heuristic: try forced-looking island assignments before black if there are few options.
        scores = []
        for v in vals:
            score = 0
            if v == B:
                # Discourage black if it risks 2x2 quickly.
                r, c = cell
                risk = 0
                for rr in range(max(0, r - 1), min(h - 1, r) + 1):
                    for cc in range(max(0, c - 1), min(w - 1, c) + 1):
                        block = [(rr, cc), (rr + 1, cc), (rr, cc + 1), (rr + 1, cc + 1)]
                        risk += sum(1 for x in block if dom[x] == {B})
                score = (1, risk)
            else:
                fixed_i = len(fixed_cells_for_clue(dom, v))
                need = clues[v][2] - fixed_i
                adjacent_fixed_same = sum(1 for nb in nbrs[cell] if dom[nb] == {v})
                score = (0, need, -adjacent_fixed_same)
            scores.append((score, v))
        scores.sort()
        return [v for _, v in scores]

    def dfs(dom):
        dom = propagate(dom)
        if dom is None:
            return None
        if final_check(dom):
            return dom

        cell = choose_branch_cell(dom)
        if cell is None:
            return None

        for v in value_order(dom, cell):
            nd = copy_domains(dom)
            ok, _ = set_value(nd, cell, v)
            if not ok:
                continue
            ans = dfs(nd)
            if ans is not None:
                return ans
        return None

    result = dfs(copy_domains(domains))
    if result is None:
        return "No Solution"

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append('B' if result[(r, c)] == {B} else None)
        out.append(row)
    return repr(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, None, None, None, None, 2, None], [None, None, 4, None, None, None, None], [None, 1, None, None, None, 4, None], [None, None, None, None, 4, None, None], [None, 1, None, None, None, None, None], [None, None, None, None, None, None, None]]}

from collections import deque, defaultdict

DIRS = [(1, 0), (-1, 0), (0, 1), (0, -1)]


def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0
    cells = [(r, c) for r in range(h) for c in range(w)]

    clues = []
    clue_pos_to_id = {}
    for r in range(h):
        for c in range(w):
            if data[r][c] is not None:
                clue_pos_to_id[(r, c)] = len(clues)
                clues.append(((r, c), data[r][c]))

    if not clues:
        return "No Solution"

    other_clue_positions = set(pos for pos, _ in clues)

    def inb(r, c):
        return 0 <= r < h and 0 <= c < w

    nbrs = {}
    for r, c in cells:
        ns = []
        for dr, dc in DIRS:
            rr, cc = r + dr, c + dc
            if inb(rr, cc):
                ns.append((rr, cc))
        nbrs[(r, c)] = ns

    # Human-like static restriction:
    # a white island cell cannot be another clue, and cannot touch a different clue orthogonally.
    forbidden_by_island = []
    for i, (root, size) in enumerate(clues):
        forb = set()
        for j, (p, _) in enumerate(clues):
            if i == j:
                continue
            forb.add(p)
            for q in nbrs[p]:
                forb.add(q)
        if root in forb:
            forb.remove(root)
        forbidden_by_island.append(forb)

    def generate_shapes(root, size, forbidden):
        # Enumerate connected cell sets of exact size containing root.
        # DFS with frontier expansion; deduplicate by frozenset.
        if size == 1:
            return [frozenset([root])]

        results = set()

        def rec(chosen, frontier):
            if len(chosen) == size:
                results.add(frozenset(chosen))
                return

            remaining = size - len(chosen)
            if len(chosen) + len(frontier) < size:
                return

            cand_list = sorted(frontier)
            for cell in cand_list:
                new_chosen = set(chosen)
                new_chosen.add(cell)
                new_frontier = set(frontier)
                new_frontier.discard(cell)
                for nb in nbrs[cell]:
                    if nb not in new_chosen and nb not in forbidden:
                        new_frontier.add(nb)

                # Connectivity reachability prune on available graph near current component.
                # Count cells reachable from current chosen through not-forbidden cells.
                # Limited but useful.
                seen = set(new_chosen)
                dq = deque(new_chosen)
                while dq and len(seen) < size:
                    x = dq.popleft()
                    for y in nbrs[x]:
                        if y in seen or y in forbidden:
                            continue
                        seen.add(y)
                        dq.append(y)
                if len(seen) < size:
                    continue

                rec(new_chosen, new_frontier)

        start_frontier = set()
        for nb in nbrs[root]:
            if nb not in forbidden:
                start_frontier.add(nb)
        rec({root}, start_frontier)
        return sorted(results, key=lambda s: (tuple(sorted(s))))

    island_shapes = []
    for i, (root, size) in enumerate(clues):
        shapes = generate_shapes(root, size, forbidden_by_island[i])
        if not shapes:
            return "No Solution"
        island_shapes.append(shapes)

    # Precompute coverage and pair compatibility.
    shape_cells = []
    for shapes in island_shapes:
        shape_cells.append([set(s) for s in shapes])

    cell_to_covering = defaultdict(list)
    for i, shapes in enumerate(shape_cells):
        for si, s in enumerate(shapes):
            for cell in s:
                cell_to_covering[cell].append((i, si))

    compat = []
    for i in range(len(clues)):
        row = []
        for si, s1 in enumerate(shape_cells[i]):
            comp_sets = []
            for j in range(len(clues)):
                if i == j:
                    comp_sets.append(set())
                    continue
                ok = set()
                for sj, s2 in enumerate(shape_cells[j]):
                    if s1 & s2:
                        continue
                    bad = False
                    for cell in s1:
                        for nb in nbrs[cell]:
                            if nb in s2:
                                bad = True
                                break
                        if bad:
                            break
                    if not bad:
                        ok.add(sj)
                comp_sets.append(ok)
            row.append(comp_sets)
        compat.append(row)

    all_domain_sets = [set(range(len(shapes))) for shapes in island_shapes]

    clue_cells = {pos for pos, _ in clues}

    def domain_intersection(i, domain):
        it = iter(domain)
        first = next(it)
        inter = set(shape_cells[i][first])
        for si in it:
            inter &= shape_cells[i][si]
        return inter

    def domain_union(i, domain):
        uni = set()
        for si in domain:
            uni |= shape_cells[i][si]
        return uni

    def propagate(domains):
        domains = [set(d) for d in domains]
        changed = True
        while changed:
            changed = False

            # Forward-check singleton choices.
            queue = deque(i for i, d in enumerate(domains) if len(d) == 1)
            seen_single = set()
            while queue:
                i = queue.popleft()
                if i in seen_single:
                    continue
                seen_single.add(i)
                si = next(iter(domains[i]))
                for j in range(len(domains)):
                    if i == j:
                        continue
                    nd = domains[j] & compat[i][si][j]
                    if not nd:
                        return None
                    if nd != domains[j]:
                        domains[j] = nd
                        changed = True
                        if len(nd) == 1:
                            queue.append(j)

            # Cell overlap impossibility:
            # if a cell is forced in multiple islands by intersections, impossible.
            forced_white = set(clue_cells)
            forced_owner = {}
            for i, d in enumerate(domains):
                if not d:
                    return None
                inter = domain_intersection(i, d)
                for cell in inter:
                    prev = forced_owner.get(cell)
                    if prev is None:
                        forced_owner[cell] = i
                    elif prev != i:
                        return None
                forced_white |= inter

            # Remove shapes that violate current forced whites of other islands by overlap/touch.
            for i in range(len(domains)):
                inter_others = forced_white - domain_intersection(i, domains[i])
                nd = set()
                for si in domains[i]:
                    s = shape_cells[i][si]
                    bad = False
                    if s & inter_others:
                        bad = True
                    else:
                        for cell in s:
                            for nb in nbrs[cell]:
                                if nb in inter_others and nb not in s:
                                    bad = True
                                    break
                            if bad:
                                break
                    if not bad:
                        nd.add(si)
                if not nd:
                    return None
                if nd != domains[i]:
                    domains[i] = nd
                    changed = True

            # Compute coverability by remaining domains.
            cover_count = {}
            for cell in cells:
                count = 0
                for i in range(len(domains)):
                    for si in domains[i]:
                        if cell in shape_cells[i][si]:
                            count += 1
                cover_count[cell] = count

            # Clue cells must remain coverable.
            for pos in clue_cells:
                if cover_count[pos] == 0:
                    return None

            # 2x2 forced-black rule.
            for r in range(h - 1):
                for c in range(w - 1):
                    block = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                    if all(cover_count[x] == 0 for x in block):
                        return None

            # Black connectivity feasibility:
            # forced black = not coverable by any island
            # possible black = cells not guaranteed white
            forced_black = {cell for cell in cells if cover_count[cell] == 0}
            guaranteed_white = set(clue_cells)
            for i, d in enumerate(domains):
                guaranteed_white |= domain_intersection(i, d)
            possible_black = [cell for cell in cells if cell not in guaranteed_white]
            if forced_black:
                start = next(iter(forced_black))
                dq = deque([start])
                seen = {start}
                pb_set = set(possible_black)
                while dq:
                    x = dq.popleft()
                    for y in nbrs[x]:
                        if y in pb_set and y not in seen:
                            seen.add(y)
                            dq.append(y)
                if not forced_black <= seen:
                    return None

            # If a non-clue cell can only be covered by one island and every remaining shape
            # of that island includes it, force incompatibilities via singleton-style narrowing.
            for cell in cells:
                owners = []
                for i in range(len(domains)):
                    hits = [si for si in domains[i] if cell in shape_cells[i][si]]
                    if hits:
                        owners.append((i, hits))
                if len(owners) == 1:
                    i, hits = owners[0]
                    nd = set(hits)
                    if not nd:
                        return None
                    if nd != domains[i]:
                        domains[i] = nd
                        changed = True

        return domains

    def choose_branch(domains):
        # MRV with secondary heuristic: total covered ambiguity.
        best_i = None
        best_key = None
        for i, d in enumerate(domains):
            if len(d) > 1:
                union_sz = len(domain_union(i, d))
                key = (len(d), union_sz)
                if best_key is None or key < best_key:
                    best_key = key
                    best_i = i
        return best_i

    def validate_complete(chosen):
        white = set()
        for i, si in enumerate(chosen):
            white |= shape_cells[i][si]

        # White islands exactly the chosen shapes; ensure clues match sizes.
        for i, (root, size) in enumerate(clues):
            s = shape_cells[i][chosen[i]]
            if root not in s or len(s) != size:
                return None

        # Islands disjoint and non-touching orthogonally.
        for i in range(len(chosen)):
            s1 = shape_cells[i][chosen[i]]
            for j in range(i + 1, len(chosen)):
                s2 = shape_cells[j][chosen[j]]
                if s1 & s2:
                    return None
                for cell in s1:
                    for nb in nbrs[cell]:
                        if nb in s2:
                            return None

        black = set(cells) - white

        # No 2x2 all-black.
        for r in range(h - 1):
            for c in range(w - 1):
                block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
                if block <= black:
                    return None

        # Black connected.
        if black:
            start = next(iter(black))
            dq = deque([start])
            seen = {start}
            while dq:
                x = dq.popleft()
                for y in nbrs[x]:
                    if y in black and y not in seen:
                        seen.add(y)
                        dq.append(y)
            if seen != black:
                return None

        ans = [[None for _ in range(w)] for _ in range(h)]
        for r, c in black:
            ans[r][c] = "B"
        return ans

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        if all(len(d) == 1 for d in domains):
            chosen = [next(iter(d)) for d in domains]
            return validate_complete(chosen)

        i = choose_branch(domains)
        # Least-constraining first: shapes compatible with more opponent choices.
        ordering = []
        for si in domains[i]:
            score = 0
            for j in range(len(domains)):
                if i != j:
                    score += len(domains[j] & compat[i][si][j])
            ordering.append((-score, si))
        ordering.sort()

        for _, si in ordering:
            nd = [set(d) for d in domains]
            nd[i] = {si}
            res = search(nd)
            if res is not None:
                return res
        return None

    result = search(all_domain_sets)
    if result is None:
        return "No Solution"
    return repr(result)


