from collections import deque

def solve(observation):
    data = observation["data"]
    R, C = len(data), len(data[0])

    clues = []
    clue_at = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                idx = len(clues)
                clues.append((r, c, data[r][c]))
                clue_at[(r, c)] = idx

    all_cells = [(r, c) for r in range(R) for c in range(C)]
    all_cell_set = set(all_cells)

    def nbrs(cell):
        r, c = cell
        if r > 0:
            yield (r - 1, c)
        if r + 1 < R:
            yield (r + 1, c)
        if c > 0:
            yield (r, c - 1)
        if c + 1 < C:
            yield (r, c + 1)

    other_clue_cells = set(clue_at.keys())

    # Enumerate all connected island shapes for each clue.
    shapes = []
    for i, (sr, sc, size) in enumerate(clues):
        root = (sr, sc)
        banned = other_clue_cells - {root}
        results = set()

        def rec(cells, frontier):
            if len(cells) == size:
                fs = frozenset(cells)
                results.add(fs)
                return
            # Simple canonical ordering reduces duplicates a bit before final set dedup.
            for cell in sorted(frontier):
                new_cells = set(cells)
                new_cells.add(cell)
                new_frontier = set(frontier)
                new_frontier.discard(cell)
                for nb in nbrs(cell):
                    if nb not in new_cells and nb not in banned:
                        new_frontier.add(nb)
                rec(new_cells, new_frontier)

        init_cells = {root}
        init_frontier = set(nb for nb in nbrs(root) if nb not in banned)
        rec(init_cells, init_frontier)

        shape_list = []
        for fs in results:
            touch = set()
            for cell in fs:
                for nb in nbrs(cell):
                    if nb not in fs:
                        touch.add(nb)
            shape_list.append({
                "cells": fs,
                "touch": frozenset(touch),
            })

        if not shape_list:
            return "No Solution"

        shapes.append(shape_list)

    n = len(clues)

    # Pairwise compatibility: no overlap and no orthogonal touching.
    compat = [[None] * n for _ in range(n)]
    for i in range(n):
        compat[i][i] = [set() for _ in range(len(shapes[i]))]
    for i in range(n):
        for j in range(i + 1, n):
            a_to_b = [set() for _ in range(len(shapes[i]))]
            b_to_a = [set() for _ in range(len(shapes[j]))]
            for a_idx, a in enumerate(shapes[i]):
                acells = a["cells"]
                atouch = a["touch"]
                for b_idx, b in enumerate(shapes[j]):
                    bcells = b["cells"]
                    if acells & bcells:
                        continue
                    if atouch & bcells:
                        continue
                    if b["touch"] & acells:
                        continue
                    a_to_b[a_idx].add(b_idx)
                    b_to_a[b_idx].add(a_idx)
            compat[i][j] = a_to_b
            compat[j][i] = b_to_a

    # Precompute per-clue union/intersection helpers on demand.
    def domain_possible_cells(i, domain):
        u = set()
        for sidx in domain:
            u |= shapes[i][sidx]["cells"]
        return u

    def domain_forced_cells(i, domain):
        it = iter(domain)
        first = next(it)
        inter = set(shapes[i][first]["cells"])
        for sidx in it:
            inter &= shapes[i][sidx]["cells"]
        return inter

    def ac3(domains):
        domains = [set(d) for d in domains]
        q = deque((i, j) for i in range(n) for j in range(n) if i != j)
        while q:
            i, j = q.popleft()
            dj = domains[j]
            changed = False
            rem = []
            table = compat[i][j]
            for a in domains[i]:
                if not (table[a] & dj):
                    rem.append(a)
            if rem:
                for a in rem:
                    domains[i].remove(a)
                if not domains[i]:
                    return None
                changed = True
            if changed:
                for k in range(n):
                    if k != i and k != j:
                        q.append((k, i))
        return domains

    def forced_sets(domains):
        possible_white = set()
        forced_white = set()
        for i in range(n):
            d = domains[i]
            possible_white |= domain_possible_cells(i, d)
            forced_white |= domain_forced_cells(i, d)
        forced_black = all_cell_set - possible_white
        return forced_white, forced_black, possible_white

    def no_black_2x2_violation(forced_black):
        for r in range(R - 1):
            for c in range(C - 1):
                block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
                if block <= forced_black:
                    return False
        return True

    def black_connectivity_feasible(forced_white, forced_black):
        blackable = all_cell_set - forced_white
        if not forced_black:
            return True
        start = next(iter(forced_black))
        dq = deque([start])
        seen = {start}
        while dq:
            cur = dq.popleft()
            for nb in nbrs(cur):
                if nb in blackable and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)
        return forced_black <= seen

    def local_feasible(domains):
        fw, fb, _ = forced_sets(domains)
        if not no_black_2x2_violation(fb):
            return False
        if not black_connectivity_feasible(fw, fb):
            return False
        return True

    def complete_check(domains):
        white = set()
        for i in range(n):
            sidx = next(iter(domains[i]))
            white |= shapes[i][sidx]["cells"]
        black = all_cell_set - white

        for r in range(R - 1):
            for c in range(C - 1):
                if {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)} <= black:
                    return None

        if black:
            start = next(iter(black))
            dq = deque([start])
            seen = {start}
            while dq:
                cur = dq.popleft()
                for nb in nbrs(cur):
                    if nb in black and nb not in seen:
                        seen.add(nb)
                        dq.append(nb)
            if seen != black:
                return None

        ans = []
        for r in range(R):
            row = []
            for c in range(C):
                row.append('B' if (r, c) in black else None)
            ans.append(row)
        return repr(ans)

    def choose_var(domains):
        best_i = None
        best_key = None
        for i in range(n):
            d = domains[i]
            if len(d) <= 1:
                continue
            # Secondary heuristic: smaller union means more constrained.
            union_size = len(domain_possible_cells(i, d))
            key = (len(d), union_size, -clues[i][2])
            if best_key is None or key < best_key:
                best_key = key
                best_i = i
        return best_i

    dead = set()

    def search(domains):
        domains = ac3(domains)
        if domains is None:
            return None
        if not local_feasible(domains):
            return None

        sig = tuple(tuple(sorted(d)) for d in domains)
        if sig in dead:
            return None

        if all(len(d) == 1 for d in domains):
            res = complete_check(domains)
            if res is not None:
                return res
            dead.add(sig)
            return None

        i = choose_var(domains)
        if i is None:
            dead.add(sig)
            return None

        # Try shapes with most overlap to forced cells first (human-like: commit to constrained cores).
        forced_white, _, _ = forced_sets(domains)
        order = sorted(
            domains[i],
            key=lambda sidx: (
                -len(shapes[i][sidx]["cells"] & forced_white),
                len(shapes[i][sidx]["touch"]),
            )
        )

        for sidx in order:
            new_domains = [set(d) for d in domains]
            new_domains[i] = {sidx}
            res = search(new_domains)
            if res is not None:
                return res

        dead.add(sig)
        return None

    initial_domains = [set(range(len(shapes[i]))) for i in range(n)]
    result = search(initial_domains)
    return result if result is not None else "No Solution"


