    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, 4, 3, 2, 3], [4, 3, 2, 3, 5], [1, 2, 3, 1, 4], [5, 3, 1, 4, 2], [2, 4, 4, 3, 3]]}

from collections import defaultdict, deque

UNKNOWN = -1
WHITE = 0
BLACK = 1


def solve(observation):
    board = observation["data"]
    n = len(board)
    if n == 0:
        return []

    row_groups, col_groups, peers = build_groups(board)
    state = [[UNKNOWN] * n for _ in range(n)]

    # Initial forced whites: cells that can never help resolve any duplicate.
    initial_queue = deque()
    for r in range(n):
        for c in range(n):
            if not peers[(r, c)]:
                initial_queue.append((r, c, WHITE))

    ok = propagate(board, state, row_groups, col_groups, peers, initial_queue)
    if not ok:
        return "No Solution"

    ans = search(board, state, row_groups, col_groups, peers)
    if ans is None:
        return "No Solution"

    return [[('B' if ans[r][c] == BLACK else None) for c in range(n)] for r in range(n)]


def build_groups(board):
    n = len(board)
    row_groups = [defaultdict(list) for _ in range(n)]
    col_groups = [defaultdict(list) for _ in range(n)]

    for r in range(n):
        for c in range(n):
            v = board[r][c]
            row_groups[r][v].append((r, c))
            col_groups[c][v].append((r, c))

    peers = {}
    for r in range(n):
        for c in range(n):
            v = board[r][c]
            ps = set(row_groups[r][v]) | set(col_groups[c][v])
            ps.discard((r, c))
            peers[(r, c)] = tuple(ps)

    return row_groups, col_groups, peers


def neighbors(n, r, c):
    if r > 0:
        yield r - 1, c
    if r + 1 < n:
        yield r + 1, c
    if c > 0:
        yield r, c - 1
    if c + 1 < n:
        yield r, c + 1


def assign(state, r, c, value, queue):
    cur = state[r][c]
    if cur == value:
        return True
    if cur != UNKNOWN and cur != value:
        return False
    state[r][c] = value
    queue.append((r, c, value))
    return True


def group_iter_for_cell(board, row_groups, col_groups, r, c):
    v = board[r][c]
    yield row_groups[r][v]
    yield col_groups[c][v]


def propagate(board, state, row_groups, col_groups, peers, initial_queue):
    n = len(board)
    queue = deque(initial_queue)

    while True:
        while queue:
            r, c, value = queue.popleft()

            if value == BLACK:
                for nr, nc in neighbors(n, r, c):
                    if not assign(state, nr, nc, WHITE, queue):
                        return False

            else:  # WHITE
                for pr, pc in peers[(r, c)]:
                    if not assign(state, pr, pc, BLACK, queue):
                        return False

        changed = False

        # Global consistency and deterministic deductions from groups.
        for r in range(n):
            for cells in row_groups[r].values():
                if not process_group(state, cells, queue):
                    return False
        for c in range(n):
            for cells in col_groups[c].values():
                if not process_group(state, cells, queue):
                    return False

        # Cell-wise deductions.
        for r in range(n):
            for c in range(n):
                s = state[r][c]

                if s == BLACK:
                    for nr, nc in neighbors(n, r, c):
                        if state[nr][nc] == BLACK:
                            return False
                    continue

                if s == WHITE:
                    for pr, pc in peers[(r, c)]:
                        if state[pr][pc] == WHITE:
                            return False
                    continue

                # UNKNOWN deductions.

                # Adjacent to black => must be white.
                forced_white = False
                for nr, nc in neighbors(n, r, c):
                    if state[nr][nc] == BLACK:
                        forced_white = True
                        break

                # If every peer is already black, blacking this cell cannot help anything.
                if not forced_white:
                    all_peers_black = True
                    for pr, pc in peers[(r, c)]:
                        if state[pr][pc] != BLACK:
                            all_peers_black = False
                            break
                    if all_peers_black:
                        forced_white = True

                if forced_white:
                    if not assign(state, r, c, WHITE, queue):
                        return False
                    changed = True
                    continue

                # If any peer is white => this must be black.
                peer_white = False
                for pr, pc in peers[(r, c)]:
                    if state[pr][pc] == WHITE:
                        peer_white = True
                        break
                if peer_white:
                    if not assign(state, r, c, BLACK, queue):
                        return False
                    changed = True
                    continue

        # Connectivity feasibility: all currently forced white cells must still be connectable
        # through cells that are not fixed black.
        if not white_connectivity_possible(state):
            return False

        if queue:
            continue
        if not changed:
            break

    return True


def process_group(state, cells, queue):
    white_count = 0
    white_cell = None
    for r, c in cells:
        if state[r][c] == WHITE:
            white_count += 1
            white_cell = (r, c)

    if white_count > 1:
        return False

    if white_count == 1:
        for r, c in cells:
            if (r, c) != white_cell:
                if not assign(state, r, c, BLACK, queue):
                    return False

    return True


def white_connectivity_possible(state):
    n = len(state)
    whites = [(r, c) for r in range(n) for c in range(n) if state[r][c] == WHITE]
    if not whites:
        return True

    start = whites[0]
    seen = {start}
    q = deque([start])

    while q:
        r, c = q.popleft()
        for nr, nc in neighbors(n, r, c):
            if state[nr][nc] == BLACK:
                continue
            if (nr, nc) not in seen:
                seen.add((nr, nc))
                q.append((nr, nc))

    for cell in whites:
        if cell not in seen:
            return False
    return True


def final_white_connected(state):
    n = len(state)
    whites = [(r, c) for r in range(n) for c in range(n) if state[r][c] != BLACK]
    if not whites:
        return False

    start = whites[0]
    seen = {start}
    q = deque([start])

    while q:
        r, c = q.popleft()
        for nr, nc in neighbors(n, r, c):
            if state[nr][nc] == BLACK:
                continue
            if (nr, nc) not in seen:
                seen.add((nr, nc))
                q.append((nr, nc))

    return len(seen) == len(whites)


def is_complete(state):
    return all(v != UNKNOWN for row in state for v in row)


def clone_state(state):
    return [row[:] for row in state]


def unresolved_conflict_score(board, state, peers, r, c):
    if state[r][c] != UNKNOWN:
        return -1
    score = 0
    for pr, pc in peers[(r, c)]:
        if state[pr][pc] != BLACK:
            score += 2
        if state[pr][pc] == UNKNOWN:
            score += 1
    n = len(state)
    for nr, nc in neighbors(n, r, c):
        if state[nr][nc] == UNKNOWN:
            score += 1
    return score


def choose_branch_cell(board, state, peers):
    n = len(state)
    best = None
    best_score = -1

    for r in range(n):
        for c in range(n):
            if state[r][c] != UNKNOWN:
                continue
            score = unresolved_conflict_score(board, state, peers, r, c)
            if score > best_score:
                best_score = score
                best = (r, c)

    return best


def branch_order(board, state, peers, r, c):
    # Prefer WHITE first when it immediately resolves duplicate conflicts.
    active_peers = sum(1 for pr, pc in peers[(r, c)] if state[pr][pc] != BLACK)
    has_black_neighbor = any(state[nr][nc] == BLACK for nr, nc in neighbors(len(state), r, c))

    if has_black_neighbor:
        return [WHITE]
    if active_peers >= 2:
        return [WHITE, BLACK]
    if active_peers == 1:
        return [WHITE, BLACK]
    return [WHITE]


def search(board, state, row_groups, col_groups, peers):
    if is_complete(state):
        if final_white_connected(state):
            return state
        return None

    cell = choose_branch_cell(board, state, peers)
    if cell is None:
        return None

    r, c = cell
    for value in branch_order(board, state, peers, r, c):
        new_state = clone_state(state)
        q = deque()
        if not assign(new_state, r, c, value, q):
            continue
        if not propagate(board, new_state, row_groups, col_groups, peers, q):
            continue
        ans = search(board, new_state, row_groups, col_groups, peers)
        if ans is not None:
            return ans

    return None


