from collections import defaultdict, deque

UNKNOWN = 0
WHITE = 1
BLACK = 2

def solve(observation):
    board = observation["data"]
    n = len(board)
    m = len(board[0]) if n else 0
    cells = [(r, c) for r in range(n) for c in range(m)]

    def idx(r, c):
        return r * m + c

    def rc(i):
        return divmod(i, m)

    neighbors = [[] for _ in range(n * m)]
    for r in range(n):
        for c in range(m):
            i = idx(r, c)
            if r > 0:
                neighbors[i].append(idx(r - 1, c))
            if r + 1 < n:
                neighbors[i].append(idx(r + 1, c))
            if c > 0:
                neighbors[i].append(idx(r, c - 1))
            if c + 1 < m:
                neighbors[i].append(idx(r, c + 1))

    # Duplicate peers in row/column.
    peers = [set() for _ in range(n * m)]
    row_groups = []
    col_groups = []

    for r in range(n):
        mp = defaultdict(list)
        for c in range(m):
            mp[board[r][c]].append(idx(r, c))
        for group in mp.values():
            if len(group) > 1:
                row_groups.append(tuple(group))
                for i in group:
                    peers[i].update(j for j in group if j != i)

    for c in range(m):
        mp = defaultdict(list)
        for r in range(n):
            mp[board[r][c]].append(idx(r, c))
        for group in mp.values():
            if len(group) > 1:
                col_groups.append(tuple(group))
                for i in group:
                    peers[i].update(j for j in group if j != i)

    all_groups = row_groups + col_groups

    # Adjacent equal pairs in same row/col => exactly one black, one white.
    xor_pairs = []
    for r in range(n):
        for c in range(m - 1):
            if board[r][c] == board[r][c + 1]:
                xor_pairs.append((idx(r, c), idx(r, c + 1)))
    for c in range(m):
        for r in range(n - 1):
            if board[r][c] == board[r + 1][c]:
                xor_pairs.append((idx(r, c), idx(r + 1, c)))

    # Immediate impossibility: run of 3 adjacent equal in row/col.
    for r in range(n):
        for c in range(m - 2):
            if board[r][c] == board[r][c + 1] == board[r][c + 2]:
                return "No Solution"
    for c in range(m):
        for r in range(n - 2):
            if board[r][c] == board[r + 1][c] == board[r + 2][c]:
                return "No Solution"

    def assign(state, i, val, q):
        cur = state[i]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False
        state[i] = val
        q.append(i)
        return True

    def check_white_connectivity(state):
        # All assigned white cells must be connected through non-black cells.
        white_nodes = [i for i, s in enumerate(state) if s == WHITE]
        if not white_nodes:
            return True
        start = white_nodes[0]
        seen = {start}
        dq = deque([start])
        while dq:
            u = dq.popleft()
            for v in neighbors[u]:
                if state[v] != BLACK and v not in seen:
                    seen.add(v)
                    dq.append(v)
        return all(w in seen for w in white_nodes)

    def articulation_forced_whites(state):
        # If blacking a cell would separate already-white cells in the current non-black graph,
        # then that cell must be white.
        white_nodes = [i for i, s in enumerate(state) if s == WHITE]
        if len(white_nodes) <= 1:
            return []
        nonblack = [i for i, s in enumerate(state) if s != BLACK]
        if not nonblack:
            return []

        forced = []
        nonblack_set = set(nonblack)

        # Build one connected component containing all whites if possible.
        start = white_nodes[0]
        seen = {start}
        dq = deque([start])
        while dq:
            u = dq.popleft()
            for v in neighbors[u]:
                if v in nonblack_set and v not in seen:
                    seen.add(v)
                    dq.append(v)
        # If some whites are already disconnected, caller will reject separately.
        white_set = set(white_nodes)
        if not white_set.issubset(seen):
            return []

        # Check unknown vertices only.
        for cut in list(seen):
            if state[cut] != UNKNOWN:
                continue
            # Remove cut and see if all whites remain mutually reachable.
            others = [w for w in white_nodes if w != cut]
            if len(others) <= 1:
                continue
            s0 = others[0]
            vis = {s0}
            qq = deque([s0])
            while qq:
                u = qq.popleft()
                for v in neighbors[u]:
                    if v == cut or state[v] == BLACK or v in vis:
                        continue
                    vis.add(v)
                    qq.append(v)
            if any(w not in vis for w in others):
                forced.append(cut)
        return forced

    def propagate(state):
        q = deque(i for i, s in enumerate(state) if s != UNKNOWN)

        # Seed from exact-one-black adjacent duplicate pairs.
        for a, b in xor_pairs:
            sa, sb = state[a], state[b]
            if sa == BLACK and sb == BLACK:
                return None
            if sa == WHITE and sb == WHITE:
                return None
            if sa == UNKNOWN and sb == UNKNOWN:
                continue
            if sa != UNKNOWN and sb == UNKNOWN:
                if not assign(state, b, WHITE if sa == BLACK else BLACK, q):
                    return None
            elif sb != UNKNOWN and sa == UNKNOWN:
                if not assign(state, a, WHITE if sb == BLACK else BLACK, q):
                    return None

        changed = True
        while changed:
            changed = False

            while q:
                i = q.popleft()
                s = state[i]

                if s == BLACK:
                    for nb in neighbors[i]:
                        if state[nb] == BLACK:
                            return None
                        if state[nb] == UNKNOWN:
                            if not assign(state, nb, WHITE, q):
                                return None

                elif s == WHITE:
                    # Same value in same row/col cannot stay white too.
                    for p in peers[i]:
                        if state[p] == WHITE:
                            return None
                        if state[p] == UNKNOWN:
                            if not assign(state, p, BLACK, q):
                                return None

                # Exact-one-black adjacent duplicate pair propagation.
                for nb in neighbors[i]:
                    if board[rc(i)[0]][rc(i)[1]] != board[rc(nb)[0]][rc(nb)[1]]:
                        continue
                    si, sn = state[i], state[nb]
                    if si == BLACK and sn == BLACK:
                        return None
                    if si == WHITE and sn == WHITE:
                        return None
                    if si != UNKNOWN and sn == UNKNOWN:
                        if not assign(state, nb, WHITE if si == BLACK else BLACK, q):
                            return None
                    elif sn != UNKNOWN and si == UNKNOWN:
                        if not assign(state, i, WHITE if sn == BLACK else BLACK, q):
                            return None

            # Group-based deductions.
            for group in all_groups:
                white_count = 0
                unknowns = []
                for i in group:
                    if state[i] == WHITE:
                        white_count += 1
                    elif state[i] == UNKNOWN:
                        unknowns.append(i)
                if white_count > 1:
                    return None
                if white_count == 1:
                    for i in unknowns:
                        if not assign(state, i, BLACK, q):
                            return None
                    if unknowns:
                        changed = True

            # White connectivity consistency.
            if not check_white_connectivity(state):
                return None

            # If a non-black component contains whites, articulation unknowns that must stay white.
            forced = articulation_forced_whites(state)
            if forced:
                for i in forced:
                    if not assign(state, i, WHITE, q):
                        return None
                changed = True
                continue

            # If an unknown cell cannot be black because it would disconnect assigned whites, force white.
            # This is a cheap local test built atop global connectivity.
            for i, s in enumerate(state):
                if s != UNKNOWN:
                    continue
                state[i] = BLACK
                ok = True
                for nb in neighbors[i]:
                    if state[nb] == BLACK:
                        ok = False
                        break
                if ok and not check_white_connectivity(state):
                    ok = False
                state[i] = UNKNOWN
                if not ok:
                    if not assign(state, i, WHITE, q):
                        return None
                    changed = True

            # If an unknown cell cannot be white due to duplicate clash chain, force black.
            while q:
                changed = True

        # Final consistency checks after stabilization.
        if not check_white_connectivity(state):
            return None
        for a, b in xor_pairs:
            sa, sb = state[a], state[b]
            if sa == BLACK and sb == BLACK:
                return None
            if sa == WHITE and sb == WHITE:
                return None
        for i, s in enumerate(state):
            if s == BLACK:
                for nb in neighbors[i]:
                    if state[nb] == BLACK:
                        return None
            if s == WHITE:
                for p in peers[i]:
                    if state[p] == WHITE:
                        return None
        return state

    def is_solved(state):
        return all(s != UNKNOWN for s in state) and check_white_connectivity(state)

    def score_cell(state, i):
        # Human-like branching: focus on cells constrained by many duplicate peers and adjacency.
        dup_pressure = sum(1 for p in peers[i] if state[p] == UNKNOWN) + sum(3 for p in peers[i] if state[p] == WHITE)
        adj_pressure = sum(1 for nb in neighbors[i] if state[nb] == UNKNOWN) + sum(2 for nb in neighbors[i] if state[nb] == BLACK)
        return dup_pressure * 4 + adj_pressure

    memo = set()

    def canonical(state):
        return tuple(state)

    def search(state):
        state = propagate(state[:])
        if state is None:
            return None
        key = canonical(state)
        if key in memo:
            return None
        memo.add(key)

        if is_solved(state):
            return state

        unknowns = [i for i, s in enumerate(state) if s == UNKNOWN]
        if not unknowns:
            return None

        # Prefer cells with duplicate involvement.
        unknowns.sort(key=lambda i: (len(peers[i]) == 0, -score_cell(state, i)))
        i = unknowns[0]

        # Branch order: try the more forced-looking value first.
        # Estimate impact of WHITE vs BLACK.
        white_impact = len(peers[i])
        black_impact = len(neighbors[i])
        order = [WHITE, BLACK] if white_impact >= black_impact else [BLACK, WHITE]

        for val in order:
            nxt = state[:]
            q = deque()
            if not assign(nxt, i, val, q):
                continue
            # Pre-propagate immediate effects before deep recursion.
            res = search(nxt)
            if res is not None:
                return res
        return None

    initial = [UNKNOWN] * (n * m)
    result = search(initial)
    if result is None:
        return "No Solution"

    mask = []
    for r in range(n):
        row = []
        for c in range(m):
            row.append('B' if result[idx(r, c)] == BLACK else None)
        mask.append(row)
    return repr(mask)

