from itertools import permutations

# General Skyscrapers solver using:
# - permutation precomputation
# - line clue filtering
# - cell-domain propagation
# - hidden-single deductions
# - constrained backtracking on the most restricted line

def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    n = len(U)

    full_mask = (1 << n) - 1
    val_to_bit = [0] + [1 << (v - 1) for v in range(1, n + 1)]

    def vis_count(seq):
        mx = 0
        seen = 0
        for x in seq:
            if x > mx:
                mx = x
                seen += 1
        return seen

    perms = list(permutations(range(1, n + 1)))
    perm_masks = []
    left_vis = []
    right_vis = []
    for p in perms:
        perm_masks.append(tuple(val_to_bit[x] for x in p))
        left_vis.append(vis_count(p))
        right_vis.append(vis_count(p[::-1]))

    # Fast clue-based line candidate filtering
    def filter_by_clues(a, b):
        out = []
        for i, p in enumerate(perms):
            if a and left_vis[i] != a:
                continue
            if b and right_vis[i] != b:
                continue
            out.append(i)
        return out

    row_cands = [filter_by_clues(L[r], R[r]) for r in range(n)]
    col_cands = [filter_by_clues(U[c], D[c]) for c in range(n)]

    if any(not x for x in row_cands) or any(not x for x in col_cands):
        return "No Solution"

    # Domains[r][c] is a bitmask over values 1..n
    domains = [[full_mask for _ in range(n)] for _ in range(n)]

    # Initial clue-implied domain shrink from row/col candidates
    for r in range(n):
        for c in range(n):
            m = 0
            for pi in row_cands[r]:
                m |= perm_masks[pi][c]
            domains[r][c] &= m
    for c in range(n):
        for r in range(n):
            m = 0
            for pi in col_cands[c]:
                m |= perm_masks[pi][r]
            domains[r][c] &= m

    if any(domains[r][c] == 0 for r in range(n) for c in range(n)):
        return "No Solution"

    bit_count = int.bit_count

    def singleton_value(mask):
        return mask.bit_length()

    def candidate_mask_union_for_row(cands, col):
        m = 0
        for pi in cands:
            m |= perm_masks[pi][col]
        return m

    def candidate_mask_union_for_col(cands, row):
        m = 0
        for pi in cands:
            m |= perm_masks[pi][row]
        return m

    def propagate(row_cands, col_cands, domains):
        changed = True
        while changed:
            changed = False

            # Filter row candidates by current domains
            for r in range(n):
                old_len = len(row_cands[r])
                new = []
                for pi in row_cands[r]:
                    pm = perm_masks[pi]
                    ok = True
                    for c in range(n):
                        if not (pm[c] & domains[r][c]):
                            ok = False
                            break
                    if ok:
                        new.append(pi)
                if not new:
                    return None
                if len(new) != old_len:
                    row_cands[r] = new
                    changed = True

            # Filter col candidates by current domains
            for c in range(n):
                old_len = len(col_cands[c])
                new = []
                for pi in col_cands[c]:
                    pm = perm_masks[pi]
                    ok = True
                    for r in range(n):
                        if not (pm[r] & domains[r][c]):
                            ok = False
                            break
                    if ok:
                        new.append(pi)
                if not new:
                    return None
                if len(new) != old_len:
                    col_cands[c] = new
                    changed = True

            # Tighten domains from row candidate unions
            for r in range(n):
                for c in range(n):
                    m = candidate_mask_union_for_row(row_cands[r], c)
                    nm = domains[r][c] & m
                    if nm == 0:
                        return None
                    if nm != domains[r][c]:
                        domains[r][c] = nm
                        changed = True

            # Tighten domains from col candidate unions
            for c in range(n):
                for r in range(n):
                    m = candidate_mask_union_for_col(col_cands[c], r)
                    nm = domains[r][c] & m
                    if nm == 0:
                        return None
                    if nm != domains[r][c]:
                        domains[r][c] = nm
                        changed = True

            # Hidden singles in rows
            for r in range(n):
                poss = [0] * (n + 1)
                for c in range(n):
                    mask = domains[r][c]
                    mm = mask
                    while mm:
                        b = mm & -mm
                        v = b.bit_length()
                        poss[v] += 1
                        mm ^= b
                for v in range(1, n + 1):
                    if poss[v] == 0:
                        return None
                    if poss[v] == 1:
                        bit = val_to_bit[v]
                        for c in range(n):
                            if domains[r][c] & bit:
                                if domains[r][c] != bit:
                                    domains[r][c] = bit
                                    changed = True
                                break

            # Hidden singles in cols
            for c in range(n):
                poss = [0] * (n + 1)
                for r in range(n):
                    mask = domains[r][c]
                    mm = mask
                    while mm:
                        b = mm & -mm
                        v = b.bit_length()
                        poss[v] += 1
                        mm ^= b
                for v in range(1, n + 1):
                    if poss[v] == 0:
                        return None
                    if poss[v] == 1:
                        bit = val_to_bit[v]
                        for r in range(n):
                            if domains[r][c] & bit:
                                if domains[r][c] != bit:
                                    domains[r][c] = bit
                                    changed = True
                                break

            # Naked singles imply row/col uniqueness elimination
            for r in range(n):
                fixed_mask = 0
                fixed_vals = 0
                for c in range(n):
                    m = domains[r][c]
                    if m & (m - 1) == 0:
                        if fixed_vals & m:
                            return None
                        fixed_vals |= m
                        fixed_mask |= m
                if fixed_mask:
                    for c in range(n):
                        m = domains[r][c]
                        if m & (m - 1):
                            nm = m & ~fixed_mask
                            # Keep own singleton if already fixed; only remove from non-singletons
                            if nm == 0:
                                return None
                            if nm != m:
                                domains[r][c] = nm
                                changed = True

            for c in range(n):
                fixed_mask = 0
                fixed_vals = 0
                for r in range(n):
                    m = domains[r][c]
                    if m & (m - 1) == 0:
                        if fixed_vals & m:
                            return None
                        fixed_vals |= m
                        fixed_mask |= m
                if fixed_mask:
                    for r in range(n):
                        m = domains[r][c]
                        if m & (m - 1):
                            nm = m & ~fixed_mask
                            if nm == 0:
                                return None
                            if nm != m:
                                domains[r][c] = nm
                                changed = True

        return row_cands, col_cands, domains

    def solved(row_cands, domains):
        if not all(len(rc) == 1 for rc in row_cands):
            return False
        for r in range(n):
            p = perms[row_cands[r][0]]
            for c in range(n):
                if domains[r][c] != val_to_bit[p[c]]:
                    return False
        return True

    def extract_grid(row_cands):
        return [list(perms[row_cands[r][0]]) for r in range(n)]

    def copy_state(row_cands, col_cands, domains):
        return ([x[:] for x in row_cands],
                [x[:] for x in col_cands],
                [row[:] for row in domains])

    def choose_branch(row_cands, col_cands, domains):
        best = None

        # Prefer the most restricted line candidate set
        for r in range(n):
            k = len(row_cands[r])
            if 1 < k and (best is None or k < best[0]):
                best = (k, 'row', r)
        for c in range(n):
            k = len(col_cands[c])
            if 1 < k and (best is None or k < best[0]):
                best = (k, 'col', c)

        # If all lines are singleton but not solved, branch on smallest cell domain
        if best is None:
            cell_best = None
            for r in range(n):
                for c in range(n):
                    k = bit_count(domains[r][c])
                    if 1 < k and (cell_best is None or k < cell_best[0]):
                        cell_best = (k, r, c)
            if cell_best is not None:
                return ('cell', cell_best[1], cell_best[2])
            return None
        return (best[1], best[2], None)

    def dfs(row_cands, col_cands, domains):
        state = propagate(row_cands, col_cands, domains)
        if state is None:
            return None
        row_cands, col_cands, domains = state

        if solved(row_cands, domains):
            return extract_grid(row_cands)

        choice = choose_branch(row_cands, col_cands, domains)
        if choice is None:
            return None

        kind, a, b = choice

        if kind == 'row':
            r = a
            # Try candidates in a value-constraining order: more singleton agreement first
            order = sorted(
                row_cands[r],
                key=lambda pi: sum(1 for c in range(n) if domains[r][c] == perm_masks[pi][c]),
                reverse=True
            )
            for pi in order:
                nr, nc, nd = copy_state(row_cands, col_cands, domains)
                nr[r] = [pi]
                pm = perm_masks[pi]
                for c in range(n):
                    nd[r][c] &= pm[c]
                    if nd[r][c] == 0:
                        break
                else:
                    ans = dfs(nr, nc, nd)
                    if ans is not None:
                        return ans
            return None

        if kind == 'col':
            c = a
            order = sorted(
                col_cands[c],
                key=lambda pi: sum(1 for r in range(n) if domains[r][c] == perm_masks[pi][r]),
                reverse=True
            )
            for pi in order:
                nr, nc, nd = copy_state(row_cands, col_cands, domains)
                nc[c] = [pi]
                pm = perm_masks[pi]
                for r in range(n):
                    nd[r][c] &= pm[r]
                    if nd[r][c] == 0:
                        break
                else:
                    ans = dfs(nr, nc, nd)
                    if ans is not None:
                        return ans
            return None

        # Branch on a cell domain only if needed
        r, c = a, b
        mask = domains[r][c]
        vals = []
        mm = mask
        while mm:
            bit = mm & -mm
            vals.append(bit)
            mm ^= bit

        # Prefer values that appear in fewer row/col candidates
        def score(bit):
            row_freq = sum(1 for pi in row_cands[r] if perm_masks[pi][c] == bit)
            col_freq = sum(1 for pi in col_cands[c] if perm_masks[pi][r] == bit)
            return row_freq + col_freq

        vals.sort(key=score)
        for bit in vals:
            nr, nc, nd = copy_state(row_cands, col_cands, domains)
            nd[r][c] = bit
            ans = dfs(nr, nc, nd)
            if ans is not None:
                return ans
        return None

    ans = dfs(row_cands, col_cands, domains)
    return str(ans) if ans is not None else "No Solution"


