from collections import defaultdict, deque

# State encoding:
# -1 = unknown
#  0 = white
#  1 = black

def solve(observation):
    board = observation["data"]
    n = len(board)
    m = len(board[0])

    neighbors = {}
    for r in range(n):
        for c in range(m):
            ns = []
            if r > 0:
                ns.append((r - 1, c))
            if r + 1 < n:
                ns.append((r + 1, c))
            if c > 0:
                ns.append((r, c - 1))
            if c + 1 < m:
                ns.append((r, c + 1))
            neighbors[(r, c)] = ns

    # Duplicate groups by row/value and col/value.
    groups = []
    cell_groups = [[[] for _ in range(m)] for _ in range(n)]

    for r in range(n):
        d = defaultdict(list)
        for c in range(m):
            d[board[r][c]].append((r, c))
        for _, cells in d.items():
            if len(cells) > 1:
                gid = len(groups)
                groups.append(cells)
                for rr, cc in cells:
                    cell_groups[rr][cc].append(gid)

    for c in range(m):
        d = defaultdict(list)
        for r in range(n):
            d[board[r][c]].append((r, c))
        for _, cells in d.items():
            if len(cells) > 1:
                gid = len(groups)
                groups.append(cells)
                for rr, cc in cells:
                    cell_groups[rr][cc].append(gid)

    def clone_state(state):
        return [row[:] for row in state]

    def assign(state, r, c, val, queue):
        cur = state[r][c]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        state[r][c] = val
        queue.append((r, c))
        return True

    def can_be_black(state, r, c):
        if state[r][c] == 0:
            return False
        for nr, nc in neighbors[(r, c)]:
            if state[nr][nc] == 1:
                return False
        return True

    def can_be_white(state, r, c):
        if state[r][c] == 1:
            return False
        v = board[r][c]
        # If same value already white in row or col duplicate groups, cannot be white.
        for gid in cell_groups[r][c]:
            cells = groups[gid]
            for rr, cc in cells:
                if (rr, cc) != (r, c) and state[rr][cc] == 0:
                    return False
        return True

    def white_components_info(state):
        white_cells = [(r, c) for r in range(n) for c in range(m) if state[r][c] == 0]
        if not white_cells:
            return 0, []
        seen = set()
        comps = []
        for s in white_cells:
            if s in seen:
                continue
            q = [s]
            seen.add(s)
            comp = [s]
            while q:
                x = q.pop()
                for y in neighbors[x]:
                    rr, cc = y
                    if state[rr][cc] != 1 and y not in seen and state[rr][cc] == 0:
                        seen.add(y)
                        q.append(y)
                        comp.append(y)
            comps.append(comp)
        return len(comps), comps

    def components_of_nonblack(state):
        seen = set()
        comps = []
        for r in range(n):
            for c in range(m):
                if state[r][c] == 1 or (r, c) in seen:
                    continue
                q = [(r, c)]
                seen.add((r, c))
                comp = [(r, c)]
                has_white = (state[r][c] == 0)
                while q:
                    x = q.pop()
                    for y in neighbors[x]:
                        rr, cc = y
                        if state[rr][cc] != 1 and y not in seen:
                            seen.add(y)
                            q.append(y)
                            comp.append(y)
                            if state[rr][cc] == 0:
                                has_white = True
                comps.append((comp, has_white))
        return comps

    def connectivity_prune(state, queue):
        # If multiple non-black components already contain white, impossible.
        comps = components_of_nonblack(state)
        white_comp_count = sum(1 for _, has_white in comps if has_white)
        if white_comp_count > 1:
            return False

        # If a cell is the only possible bridge joining two already-white regions, it must be white.
        # Conservative version: for each unknown articulation-by-test, if blacking it creates >=2
        # non-black components containing white, force it white.
        white_exists = any(state[r][c] == 0 for r in range(n) for c in range(m))
        if not white_exists:
            return True

        for r in range(n):
            for c in range(m):
                if state[r][c] != -1:
                    continue
                if not can_be_black(state, r, c):
                    continue
                state[r][c] = 1
                comps2 = components_of_nonblack(state)
                white_comp_count2 = sum(1 for _, has_white in comps2 if has_white)
                state[r][c] = -1
                if white_comp_count2 > 1:
                    if not assign(state, r, c, 0, queue):
                        return False
        return True

    def propagate(state):
        queue = deque((r, c) for r in range(n) for c in range(m) if state[r][c] != -1)

        while True:
            progressed = False

            while queue:
                r, c = queue.popleft()
                vstate = state[r][c]

                if vstate == 1:
                    # Adjacent cells of black are white.
                    for nr, nc in neighbors[(r, c)]:
                        if not assign(state, nr, nc, 0, queue):
                            return None
                elif vstate == 0:
                    # Same-number duplicates in row/col must be black.
                    for gid in cell_groups[r][c]:
                        for rr, cc in groups[gid]:
                            if (rr, cc) != (r, c):
                                if not assign(state, rr, cc, 1, queue):
                                    return None

            # Domain filtering for unknowns.
            local_changes = deque()
            for r in range(n):
                for c in range(m):
                    if state[r][c] != -1:
                        continue
                    cb = can_be_black(state, r, c)
                    cw = can_be_white(state, r, c)
                    if not cb and not cw:
                        return None
                    if not cb:
                        if not assign(state, r, c, 0, local_changes):
                            return None
                    elif not cw:
                        if not assign(state, r, c, 1, local_changes):
                            return None

            if local_changes:
                queue.extend(local_changes)
                progressed = True

            # Group-level logic.
            local_changes = deque()
            for cells in groups:
                white_count = 0
                white_cell = None
                unknowns = []
                white_capable = []
                for r, c in cells:
                    if state[r][c] == 0:
                        white_count += 1
                        white_cell = (r, c)
                    elif state[r][c] == -1:
                        unknowns.append((r, c))
                        if can_be_white(state, r, c):
                            white_capable.append((r, c))
                if white_count > 1:
                    return None
                if white_count == 1:
                    for r, c in unknowns:
                        if not assign(state, r, c, 1, local_changes):
                            return None
                else:
                    if not white_capable:
                        # All cells in this duplicate set would be black -> allowed in principle.
                        # No forced move here.
                        pass
                    elif len(white_capable) == 1:
                        r, c = white_capable[0]
                        if not assign(state, r, c, 0, local_changes):
                            return None

            if local_changes:
                queue.extend(local_changes)
                progressed = True

            # Connectivity-based pruning/forcing.
            local_changes = deque()
            if not connectivity_prune(state, local_changes):
                return None
            if local_changes:
                queue.extend(local_changes)
                progressed = True

            if not progressed and not queue:
                break

        # Final consistency checks after fixpoint.
        for r in range(n):
            for c in range(m):
                if state[r][c] == 1:
                    for nr, nc in neighbors[(r, c)]:
                        if state[nr][nc] == 1:
                            return None
                elif state[r][c] == 0:
                    for gid in cell_groups[r][c]:
                        for rr, cc in groups[gid]:
                            if (rr, cc) != (r, c) and state[rr][cc] == 0:
                                return None

        # If there are multiple current white components, impossible.
        white_comp_count, _ = white_components_info(state)
        if white_comp_count > 1:
            return None

        return state

    def solved(state):
        return all(state[r][c] != -1 for r in range(n) for c in range(m))

    def final_check(state):
        # No adjacent blacks.
        for r in range(n):
            for c in range(m):
                if state[r][c] == 1:
                    for nr, nc in neighbors[(r, c)]:
                        if state[nr][nc] == 1:
                            return False

        # Row and column uniqueness among whites.
        for r in range(n):
            seen = set()
            for c in range(m):
                if state[r][c] == 0:
                    v = board[r][c]
                    if v in seen:
                        return False
                    seen.add(v)
        for c in range(m):
            seen = set()
            for r in range(n):
                if state[r][c] == 0:
                    v = board[r][c]
                    if v in seen:
                        return False
                    seen.add(v)

        # White connectivity.
        whites = [(r, c) for r in range(n) for c in range(m) if state[r][c] == 0]
        if not whites:
            return False
        seen = set([whites[0]])
        q = [whites[0]]
        while q:
            x = q.pop()
            for y in neighbors[x]:
                rr, cc = y
                if state[rr][cc] == 0 and y not in seen:
                    seen.add(y)
                    q.append(y)
        return len(seen) == len(whites)

    def choose_branch_cell(state):
        best = None
        best_key = None

        # Prefer high-conflict cells and forced-connectivity candidates.
        white_exists = any(state[r][c] == 0 for r in range(n) for c in range(m))

        for r in range(n):
            for c in range(m):
                if state[r][c] != -1:
                    continue
                cb = can_be_black(state, r, c)
                cw = can_be_white(state, r, c)
                if not cb and not cw:
                    return (r, c, cb, cw)
                conflict = 0
                peer_unknown = 0
                for gid in cell_groups[r][c]:
                    cells = groups[gid]
                    active = 0
                    for rr, cc in cells:
                        if state[rr][cc] != 1:
                            active += 1
                            if state[rr][cc] == -1 and (rr, cc) != (r, c):
                                peer_unknown += 1
                    if active > 1:
                        conflict += active - 1

                black_neighbors = sum(1 for nr, nc in neighbors[(r, c)] if state[nr][nc] == 1)
                unknown_neighbors = sum(1 for nr, nc in neighbors[(r, c)] if state[nr][nc] == -1)
                white_neighbors = sum(1 for nr, nc in neighbors[(r, c)] if state[nr][nc] == 0)

                key = (
                    conflict,
                    peer_unknown,
                    1 if (cb and cw) else 0,
                    white_neighbors,
                    unknown_neighbors,
                    -black_neighbors,
                )
                if best_key is None or key > best_key:
                    best_key = key
                    best = (r, c, cb, cw)

        return best

    def branch_order(state, r, c, cb, cw):
        # Try the more constraining / more plausible move first.
        if cb and not cw:
            return [1]
        if cw and not cb:
            return [0]

        # Estimate which assignment triggers more propagation:
        white_force = 0
        for gid in cell_groups[r][c]:
            for rr, cc in groups[gid]:
                if (rr, cc) != (r, c) and state[rr][cc] == -1:
                    white_force += 1
        black_force = sum(1 for nr, nc in neighbors[(r, c)] if state[nr][nc] == -1)

        # If there are many duplicate peers, white is strong. If surrounded by unknowns, black is strong.
        if white_force >= black_force:
            return [0, 1]
        return [1, 0]

    def dfs(state):
        state = propagate(state)
        if state is None:
            return None
        if solved(state):
            return state if final_check(state) else None

        choice = choose_branch_cell(state)
        if choice is None:
            return None
        r, c, cb, cw = choice

        for val in branch_order(state, r, c, cb, cw):
            if val == 1 and not cb:
                continue
            if val == 0 and not cw:
                continue
            new_state = clone_state(state)
            q = deque()
            if not assign(new_state, r, c, val, q):
                continue
            result = dfs(new_state)
            if result is not None:
                return result
        return None

    initial = [[-1] * m for _ in range(n)]
    result = dfs(initial)
    if result is None:
        return "No Solution"
    return [[('B' if result[r][c] == 1 else None) for c in range(m)] for r in range(n)]


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None], [None, 2, None, None, None, 2, None], [2, None, None, None, None, None, None], [None, None, None, None, None, None, None], [None, None, None, None, None, None, 6], [None, 1, None, None, None, 3, None], [None, None, None, None, None, None, None]]}

from collections import deque

UNKNOWN = -3
BLACK = -2

def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0

    islands = []
    seed_to_island = {}
    for r in range(h):
        for c in range(w):
            if data[r][c] is not None:
                idx = len(islands)
                islands.append({
                    "seed": (r, c),
                    "size": data[r][c],
                })
                seed_to_island[(r, c)] = idx

    neighbors = {}
    for r in range(h):
        for c in range(w):
            nbs = []
            if r > 0: nbs.append((r - 1, c))
            if r + 1 < h: nbs.append((r + 1, c))
            if c > 0: nbs.append((r, c - 1))
            if c + 1 < w: nbs.append((r, c + 1))
            neighbors[(r, c)] = nbs

    squares = []
    cell_to_squares = {(r, c): [] for r in range(h) for c in range(w)}
    for r in range(h - 1):
        for c in range(w - 1):
            sq = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
            si = len(squares)
            squares.append(sq)
            for cell in sq:
                cell_to_squares[cell].append(si)

    class State:
        __slots__ = ("owner", "island_cells", "unknown_count")
        def __init__(self):
            self.owner = [[UNKNOWN] * w for _ in range(h)]
            self.island_cells = [set() for _ in islands]
            self.unknown_count = h * w
            for i, isl in enumerate(islands):
                r, c = isl["seed"]
                self.owner[r][c] = i
                self.island_cells[i].add((r, c))
                self.unknown_count -= 1

        def clone(self):
            s = State.__new__(State)
            s.owner = [row[:] for row in self.owner]
            s.island_cells = [set(cells) for cells in self.island_cells]
            s.unknown_count = self.unknown_count
            return s

    def get_owner(state, cell):
        r, c = cell
        return state.owner[r][c]

    def set_owner(state, cell, val):
        r, c = cell
        old = state.owner[r][c]
        if old == val:
            return True
        if old != UNKNOWN:
            return False
        state.owner[r][c] = val
        state.unknown_count -= 1
        if val >= 0:
            state.island_cells[val].add(cell)
        return True

    def is_black(state, cell):
        return get_owner(state, cell) == BLACK

    def is_unknown(state, cell):
        return get_owner(state, cell) == UNKNOWN

    def is_white(state, cell):
        return get_owner(state, cell) >= 0

    def adjacent_foreign_islands(state, cell, island_id=None):
        foreign = set()
        for nb in neighbors[cell]:
            v = get_owner(state, nb)
            if v >= 0 and v != island_id:
                foreign.add(v)
        return foreign

    def can_be_black(state, cell):
        if not is_unknown(state, cell):
            return False
        for si in cell_to_squares[cell]:
            sq = squares[si]
            blacks = 0
            unknowns = 0
            for x in sq:
                v = get_owner(state, x)
                if x == cell:
                    v = BLACK
                if v == BLACK:
                    blacks += 1
                elif v == UNKNOWN:
                    unknowns += 1
            if blacks == 4:
                return False
        return True

    def can_be_island(state, cell, island_id):
        if not is_unknown(state, cell):
            return False
        if len(state.island_cells[island_id]) >= islands[island_id]["size"]:
            return False
        if any(get_owner(state, nb) == island_id for nb in neighbors[cell]) is False:
            return False
        for nb in neighbors[cell]:
            v = get_owner(state, nb)
            if v >= 0 and v != island_id:
                return False
        return True

    def assign_black(state, cell):
        if not can_be_black(state, cell):
            return False
        return set_owner(state, cell, BLACK)

    def assign_island(state, cell, island_id):
        if not can_be_island(state, cell, island_id):
            return False
        return set_owner(state, cell, island_id)

    def reachable_unknowns_for_island(state, island_id):
        if len(state.island_cells[island_id]) >= islands[island_id]["size"]:
            return set()
        seen = set(state.island_cells[island_id])
        q = deque(state.island_cells[island_id])
        reach = set()
        while q:
            cur = q.popleft()
            for nb in neighbors[cur]:
                if nb in seen:
                    continue
                v = get_owner(state, nb)
                if v == BLACK:
                    continue
                if v >= 0 and v != island_id:
                    continue
                if v == UNKNOWN:
                    bad = False
                    for x in neighbors[nb]:
                        vx = get_owner(state, x)
                        if vx >= 0 and vx != island_id:
                            bad = True
                            break
                    if bad:
                        continue
                    reach.add(nb)
                    seen.add(nb)
                    q.append(nb)
                elif v == island_id:
                    seen.add(nb)
                    q.append(nb)
        return reach

    def black_connectivity_possible(state):
        nodes = [(r, c) for r in range(h) for c in range(w) if get_owner(state, (r, c)) != UNKNOWN and get_owner(state, (r, c)) != BLACK]
        white_block = set(nodes)
        starts = [(r, c) for r in range(h) for c in range(w) if get_owner(state, (r, c)) == BLACK]
        if not starts:
            return True
        allowed = {(r, c) for r in range(h) for c in range(w) if (r, c) not in white_block}
        start = starts[0]
        q = deque([start])
        seen = {start}
        while q:
            cur = q.popleft()
            for nb in neighbors[cur]:
                if nb in allowed and nb not in seen:
                    seen.add(nb)
                    q.append(nb)
        return all(cell in seen for cell in starts)

    def final_black_connected(state):
        blacks = [(r, c) for r in range(h) for c in range(w) if get_owner(state, (r, c)) == BLACK]
        if not blacks:
            return True
        q = deque([blacks[0]])
        seen = {blacks[0]}
        while q:
            cur = q.popleft()
            for nb in neighbors[cur]:
                if get_owner(state, nb) == BLACK and nb not in seen:
                    seen.add(nb)
                    q.append(nb)
        return len(seen) == len(blacks)

    def propagate(state):
        changed = True
        while changed:
            changed = False

            # Different islands cannot touch through an unknown cell.
            for r in range(h):
                for c in range(w):
                    cell = (r, c)
                    if not is_unknown(state, cell):
                        continue
                    foreign = adjacent_foreign_islands(state, cell, None)
                    if len(foreign) >= 2:
                        if not assign_black(state, cell):
                            return None
                        changed = True

            # Complete islands surround with black.
            for i, isl in enumerate(islands):
                if len(state.island_cells[i]) == isl["size"]:
                    for cell in list(state.island_cells[i]):
                        for nb in neighbors[cell]:
                            if is_unknown(state, nb):
                                if not assign_black(state, nb):
                                    return None
                                changed = True
                elif len(state.island_cells[i]) > isl["size"]:
                    return None

            # Reachability analysis for islands.
            all_reach = [set() for _ in islands]
            for i, isl in enumerate(islands):
                reach = reachable_unknowns_for_island(state, i)
                all_reach[i] = reach
                need = isl["size"] - len(state.island_cells[i])
                if need < 0:
                    return None
                if len(reach) < need:
                    return None
                if need > 0 and len(reach) == need:
                    # All reachable cells must belong to this island.
                    # Apply in frontier waves to maintain connectivity.
                    local_changed = True
                    while local_changed:
                        local_changed = False
                        for cell in list(reach):
                            if is_unknown(state, cell) and can_be_island(state, cell, i):
                                if not assign_island(state, cell, i):
                                    return None
                                changed = True
                                local_changed = True
                    # Recompute if not all were assigned due to connectivity ordering.
                    reach2 = reachable_unknowns_for_island(state, i)
                    need2 = isl["size"] - len(state.island_cells[i])
                    if len(reach2) < need2:
                        return None
                    if need2 == 0:
                        pass

            # Unknown cells unreachable by any island must be black.
            for r in range(h):
                for c in range(w):
                    cell = (r, c)
                    if not is_unknown(state, cell):
                        continue
                    possible_islands = [i for i in range(len(islands)) if cell in all_reach[i]]
                    if not possible_islands:
                        if not assign_black(state, cell):
                            return None
                        changed = True

            # If an island has exactly one frontier choice, force it.
            for i, isl in enumerate(islands):
                need = isl["size"] - len(state.island_cells[i])
                if need <= 0:
                    continue
                frontier = []
                for cell in state.island_cells[i]:
                    for nb in neighbors[cell]:
                        if can_be_island(state, nb, i):
                            frontier.append(nb)
                frontier = list(dict.fromkeys(frontier))
                if not frontier:
                    return None
                if len(frontier) == 1:
                    if not assign_island(state, frontier[0], i):
                        return None
                    changed = True

            # 2x2 black prevention: if three are black and one unknown, that unknown cannot be black.
            # If exactly one island can take it, force that white assignment.
            for sq in squares:
                blacks = []
                unknowns = []
                for cell in sq:
                    v = get_owner(state, cell)
                    if v == BLACK:
                        blacks.append(cell)
                    elif v == UNKNOWN:
                        unknowns.append(cell)
                if len(blacks) == 4:
                    return None
                if len(blacks) == 3 and len(unknowns) == 1:
                    cell = unknowns[0]
                    opts = []
                    for i in range(len(islands)):
                        if can_be_island(state, cell, i):
                            opts.append(i)
                    if not opts:
                        return None
                    if len(opts) == 1:
                        if not assign_island(state, cell, opts[0]):
                            return None
                        changed = True

            # Size-1 islands force adjacent black.
            for i, isl in enumerate(islands):
                if isl["size"] == 1:
                    seed = isl["seed"]
                    for nb in neighbors[seed]:
                        if is_unknown(state, nb):
                            if not assign_black(state, nb):
                                return None
                            changed = True

            # Global black connectivity feasibility.
            if not black_connectivity_possible(state):
                return None

        # White islands must remain separated and connected by construction; final size checked elsewhere.
        return state

    def options_for_cell(state, cell, all_reach=None):
        opts = []
        if can_be_black(state, cell):
            opts.append(("B", None))
        for i in range(len(islands)):
            if can_be_island(state, cell, i):
                opts.append(("W", i))
        return opts

    def choose_branch(state):
        # Prefer frontier/forced-interface cells with fewest options.
        best = None
        best_opts = None

        candidate_cells = set()

        for i in range(len(islands)):
            if len(state.island_cells[i]) < islands[i]["size"]:
                for cell in state.island_cells[i]:
                    for nb in neighbors[cell]:
                        if is_unknown(state, nb):
                            candidate_cells.add(nb)

        # Also include unknown cells near black and any globally constrained unknowns.
        for r in range(h):
            for c in range(w):
                cell = (r, c)
                if is_unknown(state, cell):
                    for nb in neighbors[cell]:
                        if get_owner(state, nb) == BLACK:
                            candidate_cells.add(cell)
                            break

        if not candidate_cells:
            for r in range(h):
                for c in range(w):
                    if is_unknown(state, (r, c)):
                        candidate_cells.add((r, c))

        for cell in candidate_cells:
            if not is_unknown(state, cell):
                continue
            opts = options_for_cell(state, cell)
            if not opts:
                return cell, []
            score = (len(opts), 0 if any(k == "W" for k, _ in opts) else 1)
            if best is None or score < best:
                best = score
                best_opts = (cell, opts)

        return best_opts

    def solved(state):
        if state.unknown_count != 0:
            return False
        for i, isl in enumerate(islands):
            if len(state.island_cells[i]) != isl["size"]:
                return False
        for sq in squares:
            if all(get_owner(state, cell) == BLACK for cell in sq):
                return False
        return final_black_connected(state)

    def finish_unknowns_as_black(state):
        s = state.clone()
        progress = True
        while progress:
            progress = False
            for r in range(h):
                for c in range(w):
                    cell = (r, c)
                    if is_unknown(s, cell):
                        if not assign_black(s, cell):
                            return None
                        progress = True
            s = propagate(s)
            if s is None:
                return None
            if s.unknown_count == 0:
                break
        return s

    def dfs(state):
        state = propagate(state)
        if state is None:
            return None

        if state.unknown_count == 0:
            return state if solved(state) else None

        # If all islands are complete, remaining unknowns must be black.
        if all(len(state.island_cells[i]) == islands[i]["size"] for i in range(len(islands))):
            finished = finish_unknowns_as_black(state)
            if finished is not None and solved(finished):
                return finished
            return None

        branch = choose_branch(state)
        if branch is None:
            return None
        cell, opts = branch
        if not opts:
            return None

        # Try white growth before black to mimic typical deduction.
        opts.sort(key=lambda x: 0 if x[0] == "W" else 1)

        for kind, island_id in opts:
            s2 = state.clone()
            ok = assign_island(s2, cell, island_id) if kind == "W" else assign_black(s2, cell)
            if not ok:
                continue
            ans = dfs(s2)
            if ans is not None:
                return ans
        return None

    result = dfs(State())
    if result is None:
        return "No Solution"

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            v = result.owner[r][c]
            row.append('B' if v == BLACK else None)
        out.append(row)
    return repr(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 9, None, None, None], [None, 5, None, None, None, None, 8], [None, None, None, 8, None, None, 10], [None, None, None, 9, None, None, None], [7, None, None, 9, None, None, None], [3, None, None, None, None, 3, None], [None, None, None, 4, None, None, None]]}

from collections import deque

# Cell states
U = -1  # unknown
W = 0   # white
B = 1   # black

DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def solve(observation):
    data = observation["data"]
    n = len(data)

    clues = {}
    clue_cells = set()
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                clues[(r, c)] = data[r][c]
                clue_cells.add((r, c))

    rays = {}
    cell_to_rays = {}
    for (r, c), val in clues.items():
        drays = []
        for d, (dr, dc) in enumerate(DIRS):
            ray = []
            rr, cc = r + dr, c + dc
            while 0 <= rr < n and 0 <= cc < n:
                ray.append((rr, cc))
                rr += dr
                cc += dc
            drays.append(ray)
            for idx, cell in enumerate(ray):
                cell_to_rays.setdefault(cell, []).append(((r, c), d, idx))
        rays[(r, c)] = drays

    # Initial grid
    grid = [[U] * n for _ in range(n)]
    for r, c in clue_cells:
        grid[r][c] = W

    # Precompute neighbors
    neighbors = {}
    for r in range(n):
        for c in range(n):
            ns = []
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    ns.append((rr, cc))
            neighbors[(r, c)] = ns

    def clone_grid(g):
        return [row[:] for row in g]

    def ray_possible_lengths(ray, g):
        # k visible cells on this ray; must be prefix white and then black or border
        L = len(ray)
        poss = []
        for k in range(L + 1):
            ok = True
            for i in range(k):
                r, c = ray[i]
                if g[r][c] == B:
                    ok = False
                    break
            if not ok:
                continue
            if k < L:
                r, c = ray[k]
                if g[r][c] == W:
                    continue
            poss.append(k)
        return poss

    def clue_feasible_info(clue, g):
        target = clues[clue]
        drays = rays[clue]
        poss_lists = [ray_possible_lengths(ray, g) for ray in drays]
        if any(len(pl) == 0 for pl in poss_lists):
            return None

        suffix_sets = [None] * 5
        suffix_sets[4] = {0}
        for i in range(3, -1, -1):
            s = set()
            for x in poss_lists[i]:
                for y in suffix_sets[i + 1]:
                    s.add(x + y)
            suffix_sets[i] = s

        feasible = []
        prefix = {0}
        for i in range(4):
            next_prefix = set()
            ray_feas = set()
            for p in prefix:
                for x in poss_lists[i]:
                    need = target - 1 - (p + x)
                    if need in suffix_sets[i + 1]:
                        ray_feas.add(x)
                        next_prefix.add(p + x)
            if not ray_feas:
                return None
            feasible.append(ray_feas)
            prefix = next_prefix

        if (target - 1) not in prefix:
            return None

        return feasible

    def apply_clue_forcing(clue, feasible, g, queue):
        changed = False
        drays = rays[clue]
        for d in range(4):
            ray = drays[d]
            feas = feasible[d]
            if not feas:
                return None
            min_k = min(feas)
            max_k = max(feas)

            # cells before min_k must be white
            for i in range(min_k):
                r, c = ray[i]
                if (r, c) in clue_cells:
                    if g[r][c] == B:
                        return None
                if g[r][c] == B:
                    return None
                if g[r][c] == U:
                    g[r][c] = W
                    queue.append((r, c))
                    changed = True

            # if all feasible lengths stop before position i, then cell i must be black
            for i in range(max_k, len(ray)):
                if i not in feas:
                    # Not enough by itself; only the first non-visible cell after a chosen k is black.
                    # So we can force black only if every feasible k equals i.
                    continue

            if len(feas) == 1:
                k = next(iter(feas))
                if k < len(ray):
                    r, c = ray[k]
                    if (r, c) in clue_cells:
                        return None
                    if g[r][c] == W:
                        return None
                    if g[r][c] == U:
                        g[r][c] = B
                        queue.append((r, c))
                        changed = True

        return changed

    def apply_black_adjacency(g, queue):
        changed = False
        while queue:
            r, c = queue.popleft()
            st = g[r][c]
            if st == B:
                for rr, cc in neighbors[(r, c)]:
                    if (rr, cc) in clue_cells:
                        if g[rr][cc] == B:
                            return None
                        continue
                    if g[rr][cc] == B:
                        return None
                    if g[rr][cc] == U:
                        g[rr][cc] = W
                        queue.append((rr, cc))
                        changed = True
            elif st == W:
                pass
        return changed

    def consistency_no_adjacent_black(g):
        for r in range(n):
            for c in range(n):
                if g[r][c] == B:
                    for rr, cc in neighbors[(r, c)]:
                        if g[rr][cc] == B:
                            return False
        return True

    def consistency_clues(g):
        for clue in clues:
            info = clue_feasible_info(clue, g)
            if info is None:
                return False
        return True

    def consistency_connectivity(g):
        # Forced whites must lie in one connected component of non-black cells.
        whites = [(r, c) for r in range(n) for c in range(n) if g[r][c] == W]
        if not whites:
            return True

        allowed = {(r, c) for r in range(n) for c in range(n) if g[r][c] != B}
        start = whites[0]
        dq = deque([start])
        seen = {start}
        while dq:
            r, c = dq.popleft()
            for rr, cc in neighbors[(r, c)]:
                if (rr, cc) in allowed and (rr, cc) not in seen:
                    seen.add((rr, cc))
                    dq.append((rr, cc))
        for cell in whites:
            if cell not in seen:
                return False

        # Every non-black connected component must contain at least one white,
        # otherwise that component would need to become all black, impossible if it contains clues/forced whites.
        # Stronger practical pruning: any unknown-only component separated from whites is impossible because
        # all white cells must be connected in the final state.
        for cell in allowed:
            if cell not in seen:
                return False

        return True

    def hidden_single_on_cell(cell, g):
        r, c = cell
        if g[r][c] != U:
            return False

        # Try black then white quickly.
        possible_states = []
        for st in (B, W):
            if st == B and cell in clue_cells:
                continue
            gg = clone_grid(g)
            gg[r][c] = st
            q = deque([cell])
            if apply_black_adjacency(gg, q) is None:
                continue
            ok = True
            for clue in clues:
                info = clue_feasible_info(clue, gg)
                if info is None:
                    ok = False
                    break
            if ok and consistency_connectivity(gg):
                possible_states.append(st)

        if not possible_states:
            return None
        if len(possible_states) == 1:
            g[r][c] = possible_states[0]
            return True
        return False

    def propagate(g):
        queue = deque()
        for r in range(n):
            for c in range(n):
                if g[r][c] != U:
                    queue.append((r, c))

        changed_any = True
        while changed_any:
            changed_any = False

            res = apply_black_adjacency(g, queue)
            if res is None:
                return None
            if res:
                changed_any = True

            for clue in clues:
                info = clue_feasible_info(clue, g)
                if info is None:
                    return None
                res = apply_clue_forcing(clue, info, g, queue)
                if res is None:
                    return None
                if res:
                    changed_any = True

            # Simple local contradiction checks
            if not consistency_no_adjacent_black(g):
                return None
            if not consistency_connectivity(g):
                return None

            # Human-like trial on highly constrained cells only
            candidates = []
            for r in range(n):
                for c in range(n):
                    if g[r][c] == U:
                        score = 0
                        score += len(cell_to_rays.get((r, c), [])) * 4
                        score += sum(1 for rr, cc in neighbors[(r, c)] if g[rr][cc] != U)
                        if score:
                            candidates.append((score, (r, c)))
            candidates.sort(reverse=True)

            local_progress = False
            for _, cell in candidates[:8]:
                res = hidden_single_on_cell(cell, g)
                if res is None:
                    return None
                if res:
                    queue.append(cell)
                    changed_any = True
                    local_progress = True
                    break
            if local_progress:
                continue

        return g

    def is_solved(g):
        for r in range(n):
            for c in range(n):
                if g[r][c] == U:
                    return False
        if not consistency_no_adjacent_black(g):
            return False
        if not consistency_clues(g):
            return False

        # Final white connectivity on white cells only
        whites = [(r, c) for r in range(n) for c in range(n) if g[r][c] == W]
        if whites:
            dq = deque([whites[0]])
            seen = {whites[0]}
            while dq:
                r, c = dq.popleft()
                for rr, cc in neighbors[(r, c)]:
                    if g[rr][cc] == W and (rr, cc) not in seen:
                        seen.add((rr, cc))
                        dq.append((rr, cc))
            if len(seen) != len(whites):
                return False
        return True

    def choose_branch_cell(g):
        best = None
        best_score = -1
        for r in range(n):
            for c in range(n):
                if g[r][c] != U:
                    continue
                score = 0
                score += len(cell_to_rays.get((r, c), [])) * 5
                score += sum(1 for rr, cc in neighbors[(r, c)] if g[rr][cc] != U) * 2

                # State preference heuristic
                can_black = True
                if (r, c) in clue_cells:
                    can_black = False
                else:
                    for rr, cc in neighbors[(r, c)]:
                        if g[rr][cc] == B:
                            can_black = False
                            break
                if not can_black:
                    score += 3

                if score > best_score:
                    best_score = score
                    best = (r, c)
        return best

    def search(g):
        g = clone_grid(g)
        g = propagate(g)
        if g is None:
            return None
        if is_solved(g):
            return g

        cell = choose_branch_cell(g)
        if cell is None:
            return None
        r, c = cell

        # Heuristic branch order
        orders = []
        can_black = (cell not in clue_cells) and all(g[rr][cc] != B for rr, cc in neighbors[cell])
        if can_black:
            # Prefer black first when many clue rays cross and local neighborhood is constrained
            black_score = len(cell_to_rays.get(cell, [])) + sum(1 for rr, cc in neighbors[cell] if g[rr][cc] == U)
            if black_score >= 3:
                orders = [B, W]
            else:
                orders = [W, B]
        else:
            orders = [W]

        for st in orders:
            gg = clone_grid(g)
            gg[r][c] = st
            res = search(gg)
            if res is not None:
                return res
        return None

    sol = search(grid)
    if sol is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            if (r, c) in clue_cells:
                row.append(clues[(r, c)])
            elif sol[r][c] == B:
                row.append('B')
            else:
                row.append(None)
        out.append(row)
    return repr(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, None, None, 3, None, 3, None], [None, None, 2, 3, None, None, None], [None, None, None, None, 1, None, 1], [1, None, None, 1, None, 2, None], [1, None, None, None, 1, None, 2], [None, None, None, 2, None, None, None], [None, 1, 0, None, None, None, 1]]}

# Generalized Minesweeper solver using human-like deduction plus tightly-pruned search.
# Output format: string representation of a grid of same shape with 'F' for mines and None otherwise.

from collections import defaultdict, deque

def neighbors(r, c, h, w):
    for dr in (-1, 0, 1):
        nr = r + dr
        if nr < 0 or nr >= h:
            continue
        for dc in (-1, 0, 1):
            nc = c + dc
            if dc == 0 and dr == 0:
                continue
            if 0 <= nc < w:
                yield nr, nc

def build_problem(data):
    h = len(data)
    w = len(data[0]) if h else 0

    var_cells = []
    var_index = {}
    for r in range(h):
        for c in range(w):
            if data[r][c] is None:
                var_index[(r, c)] = len(var_cells)
                var_cells.append((r, c))

    constraints = []
    var_to_constraints = defaultdict(list)

    for r in range(h):
        for c in range(w):
            clue = data[r][c]
            if clue is None:
                continue
            vars_here = []
            for nr, nc in neighbors(r, c, h, w):
                if data[nr][nc] is None:
                    vars_here.append(var_index[(nr, nc)])
            fs = frozenset(vars_here)
            constraints.append((fs, clue))
            idx = len(constraints) - 1
            for v in fs:
                var_to_constraints[v].append(idx)

    constrained_vars = set()
    for vs, _ in constraints:
        constrained_vars |= set(vs)

    unconstrained_vars = [v for v in range(len(var_cells)) if v not in constrained_vars]

    return {
        'h': h,
        'w': w,
        'data': data,
        'var_cells': var_cells,
        'constraints': constraints,
        'var_to_constraints': var_to_constraints,
        'constrained_vars': constrained_vars,
        'unconstrained_vars': unconstrained_vars,
    }

def split_components(num_vars, constraints):
    # Build bipartite connectivity through constraints, then project to variable components.
    var_adj_constraints = defaultdict(list)
    for i, (vs, _) in enumerate(constraints):
        for v in vs:
            var_adj_constraints[v].append(i)

    seen_vars = set()
    components = []

    constrained_vars = set()
    for vs, _ in constraints:
        constrained_vars |= set(vs)

    for start in constrained_vars:
        if start in seen_vars:
            continue
        qv = deque([start])
        seen_vars.add(start)
        comp_vars = set()
        comp_cons = set()

        while qv:
            v = qv.popleft()
            comp_vars.add(v)
            for ci in var_adj_constraints[v]:
                if ci in comp_cons:
                    continue
                comp_cons.add(ci)
                vs, _ = constraints[ci]
                for u in vs:
                    if u not in seen_vars:
                        seen_vars.add(u)
                        qv.append(u)

        local_constraints = [constraints[i] for i in comp_cons]
        components.append((comp_vars, local_constraints))

    return components

def reduce_constraints(constraints, assignment):
    reduced = []
    for vs, total in constraints:
        rem = total
        unassigned = []
        for v in vs:
            if v in assignment:
                rem -= assignment[v]
            else:
                unassigned.append(v)
        if rem < 0 or rem > len(unassigned):
            return None
        f = frozenset(unassigned)
        if not f:
            if rem != 0:
                return None
        else:
            reduced.append((f, rem))
    return reduced

def merge_constraints(reduced):
    merged = {}
    for vs, total in reduced:
        if vs in merged:
            if merged[vs] != total:
                return None
        else:
            merged[vs] = total
    return [(vs, merged[vs]) for vs in merged]

def propagate(constraints, assignment):
    # constraints is local to this search node and may be augmented with derived constraints
    constraints = list(constraints)
    assignment = dict(assignment)

    while True:
        reduced = reduce_constraints(constraints, assignment)
        if reduced is None:
            return None, None

        reduced = merge_constraints(reduced)
        if reduced is None:
            return None, None

        changed = False

        # Direct human rules: all-safe / all-mine
        forced = {}
        for vs, total in reduced:
            if total == 0:
                for v in vs:
                    prev = assignment.get(v)
                    if prev is not None:
                        if prev != 0:
                            return None, None
                    else:
                        forced[v] = 0
            elif total == len(vs):
                for v in vs:
                    prev = assignment.get(v)
                    if prev is not None:
                        if prev != 1:
                            return None, None
                    else:
                        forced[v] = 1

        if forced:
            for v, val in forced.items():
                prev = assignment.get(v)
                if prev is not None and prev != val:
                    return None, None
                if prev is None:
                    assignment[v] = val
                    changed = True
            if changed:
                continue

        # Subset rule: if A subset B then B-A has sum total(B)-total(A)
        current = reduced
        current.sort(key=lambda x: (len(x[0]), tuple(sorted(x[0])), x[1]))
        existing = {(vs, total) for vs, total in constraints}
        new_constraints = []

        n = len(current)
        for i in range(n):
            a_vars, a_total = current[i]
            for j in range(i + 1, n):
                b_vars, b_total = current[j]
                if len(a_vars) > len(b_vars):
                    continue
                if a_vars.issubset(b_vars):
                    diff = b_vars - a_vars
                    dt = b_total - a_total
                    if dt < 0 or dt > len(diff):
                        return None, None
                    if diff:
                        item = (frozenset(diff), dt)
                        if item not in existing:
                            existing.add(item)
                            new_constraints.append(item)
                elif b_vars.issubset(a_vars):
                    diff = a_vars - b_vars
                    dt = a_total - b_total
                    if dt < 0 or dt > len(diff):
                        return None, None
                    if diff:
                        item = (frozenset(diff), dt)
                        if item not in existing:
                            existing.add(item)
                            new_constraints.append(item)

        if new_constraints:
            constraints.extend(new_constraints)
            changed = True

        if not changed:
            # Final consistency check on reduced set.
            return constraints, assignment

def choose_branch_var(constraints, assignment):
    reduced = reduce_constraints(constraints, assignment)
    if reduced is None:
        return None, None

    score = defaultdict(float)
    mine_bias = defaultdict(float)

    for vs, total in reduced:
        size = len(vs)
        if size == 0:
            continue
        density = total / size
        weight = 1.0 + 3.0 / size
        for v in vs:
            score[v] += weight
            mine_bias[v] += density * weight

    candidates = [v for v in score if v not in assignment]
    if not candidates:
        return None, None

    candidates.sort(key=lambda v: (-score[v], -abs(mine_bias[v] - score[v] / 2), v))
    v = candidates[0]
    prefer_one = mine_bias[v] >= score[v] / 2
    order = (1, 0) if prefer_one else (0, 1)
    return v, order

def solve_component(component_vars, component_constraints):
    constraints, assignment = propagate(component_constraints, {})
    if constraints is None:
        return None

    target_vars = set(component_vars)

    def dfs(constraints, assignment):
        constraints, assignment = propagate(constraints, assignment)
        if constraints is None:
            return None

        if all(v in assignment for v in target_vars):
            return assignment

        v, order = choose_branch_var(constraints, assignment)
        if v is None:
            # Remaining vars in target_vars but not present in constraints can be safely set to 0.
            res = dict(assignment)
            for u in target_vars:
                res.setdefault(u, 0)
            return res

        for val in order:
            nxt = dict(assignment)
            nxt[v] = val
            ans = dfs(constraints, nxt)
            if ans is not None:
                return ans
        return None

    return dfs(constraints, assignment)

def solve(observation):
    data = observation['data']
    prob = build_problem(data)

    h = prob['h']
    w = prob['w']
    var_cells = prob['var_cells']
    constraints = prob['constraints']

    # Early inconsistency check from clue-only constraints
    for vs, total in constraints:
        if total < 0 or total > len(vs):
            return "No Solution"

    components = split_components(len(var_cells), constraints)

    final_assignment = {}

    # Any unconstrained hidden cells can be non-mines without affecting clues.
    for v in prob['unconstrained_vars']:
        final_assignment[v] = 0

    for comp_vars, comp_constraints in components:
        comp_solution = solve_component(comp_vars, comp_constraints)
        if comp_solution is None:
            return "No Solution"
        for v in comp_vars:
            final_assignment[v] = comp_solution.get(v, 0)

    answer = [[None for _ in range(w)] for _ in range(h)]
    for v, (r, c) in enumerate(var_cells):
        if final_assignment.get(v, 0) == 1:
            answer[r][c] = 'F'

    # Validate complete solution against all clues.
    for r in range(h):
        for c in range(w):
            clue = data[r][c]
            if clue is None:
                continue
            cnt = 0
            for nr, nc in neighbors(r, c, h, w):
                if answer[nr][nc] == 'F':
                    cnt += 1
            if cnt != clue:
                return "No Solution"

    return str(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 1, 1, 1, 1, 1, 2], [0, 0, 3, 3, 3, 1, 1, 2], [0, 4, 3, 5, 3, 3, 2, 2], [0, 4, 6, 5, 3, 7, 7, 2], [4, 4, 6, 5, 3, 3, 3, 2], [4, 6, 6, 5, 2, 2, 2, 2], [4, 6, 6, 5, 7, 7, 2, 7], [4, 4, 4, 4, 4, 4, 7, 7]]}

from collections import defaultdict

# 1-star Star Battle solver with aggressive propagation and lightweight search.
# The implementation is generalized for any N x N observation using region ids.

def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    region_cells = defaultdict(list)
    cell_region = {}
    for r in range(n):
        for c in range(n):
            reg = data[r][c]
            region_cells[reg].append((r, c))
            cell_region[(r, c)] = reg

    regions = sorted(region_cells)
    if len(regions) != n:
        # Standard 1-star puzzles use exactly N regions.
        # Keep solving anyway if possible, but reject malformed extreme cases.
        pass

    cells = [(r, c) for r in range(n) for c in range(n)]
    idx_of = {cell: i for i, cell in enumerate(cells)}
    bit_of = [1 << i for i in range(n * n)]

    row_mask = [0] * n
    col_mask = [0] * n
    reg_index = {reg: i for i, reg in enumerate(regions)}
    reg_mask = [0] * len(regions)
    adj_mask = [0] * (n * n)

    for r in range(n):
        for c in range(n):
            i = idx_of[(r, c)]
            row_mask[r] |= bit_of[i]
            col_mask[c] |= bit_of[i]
            reg_mask[reg_index[data[r][c]]] |= bit_of[i]

            m = 0
            for rr in range(max(0, r - 1), min(n, r + 2)):
                for cc in range(max(0, c - 1), min(n, c + 2)):
                    if rr == r and cc == c:
                        continue
                    m |= bit_of[idx_of[(rr, cc)]]
            adj_mask[i] = m

    all_mask = (1 << (n * n)) - 1

    # Fast helpers
    def bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb
            mask ^= lsb

    def bit_index(lsb):
        return lsb.bit_length() - 1

    def rc_from_bit(lsb):
        i = bit_index(lsb)
        return cells[i]

    # State
    candidates = [row_mask[r] for r in range(n)]  # legal cells currently available in each row
    row_star = [None] * n
    col_star = [None] * n
    reg_star = [None] * len(regions)

    # Eliminate a single cell from availability.
    def remove_cell(state_candidates, lsb):
        changed = False
        inv = ~lsb
        for r in range(n):
            old = state_candidates[r]
            new = old & inv
            if new != old:
                state_candidates[r] = new
                changed = True
        return changed

    # Place a star at one cell; enforce row/col/region exactness and non-touching.
    def place(state_candidates, state_row_star, state_col_star, state_reg_star, lsb):
        r, c = rc_from_bit(lsb)
        reg = reg_index[data[r][c]]

        if state_row_star[r] is not None and state_row_star[r] != lsb:
            return None
        if state_col_star[c] is not None and state_col_star[c] != lsb:
            return None
        if state_reg_star[reg] is not None and state_reg_star[reg] != lsb:
            return None

        # Must still be available in this row.
        if not (state_candidates[r] & lsb):
            return None

        new_candidates = state_candidates[:]
        new_row_star = state_row_star[:]
        new_col_star = state_col_star[:]
        new_reg_star = state_reg_star[:]

        new_row_star[r] = lsb
        new_col_star[c] = lsb
        new_reg_star[reg] = lsb

        forbidden = (row_mask[r] ^ lsb) | col_mask[c] | reg_mask[reg] | adj_mask[bit_index(lsb)]
        allowed_r = lsb

        # Keep only the chosen cell in its row.
        if new_candidates[r] != allowed_r:
            new_candidates[r] = allowed_r

        # Remove forbidden cells from all other rows.
        inv_forbidden = ~forbidden
        for rr in range(n):
            if rr == r:
                continue
            new_candidates[rr] &= inv_forbidden

        return new_candidates, new_row_star, new_col_star, new_reg_star

    # Feasibility checks and propagation.
    def max_matching_possible(unit_masks_a, unit_masks_b):
        # Lightweight Hall-style pruning by bipartite maximum matching.
        # unit_masks_a: list of masks for left units over cells
        # unit_masks_b: list of masks for right units over cells
        # Edge exists if mask intersection != 0.
        m = len(unit_masks_a)
        k = len(unit_masks_b)
        adj = [[] for _ in range(m)]
        for i in range(m):
            ai = unit_masks_a[i]
            if ai == 0:
                return False
            for j in range(k):
                if ai & unit_masks_b[j]:
                    adj[i].append(j)
            if not adj[i]:
                return False

        match_r = [-1] * k

        def dfs(u, seen):
            for v in adj[u]:
                if seen[v]:
                    continue
                seen[v] = True
                if match_r[v] == -1 or dfs(match_r[v], seen):
                    match_r[v] = u
                    return True
            return False

        for u in range(m):
            seen = [False] * k
            if not dfs(u, seen):
                return False
        return True

    def propagate(state_candidates, state_row_star, state_col_star, state_reg_star):
        while True:
            changed = False

            # Basic impossibility: every row must retain at least one candidate.
            for r in range(n):
                if state_candidates[r] == 0:
                    return None

            # Columns and regions must each still have at least one possible cell if unassigned.
            for c in range(n):
                if state_col_star[c] is None:
                    possible = 0
                    for r in range(n):
                        possible |= (state_candidates[r] & col_mask[c])
                    if possible == 0:
                        return None

            for reg_i in range(len(regions)):
                if state_reg_star[reg_i] is None:
                    possible = 0
                    rm = reg_mask[reg_i]
                    for r in range(n):
                        possible |= (state_candidates[r] & rm)
                    if possible == 0:
                        return None

            # Forced rows.
            for r in range(n):
                mask = state_candidates[r]
                if mask & (mask - 1) == 0:
                    lsb = mask
                    if state_row_star[r] != lsb:
                        placed = place(state_candidates, state_row_star, state_col_star, state_reg_star, lsb)
                        if placed is None:
                            return None
                        state_candidates, state_row_star, state_col_star, state_reg_star = placed
                        changed = True

            # Forced columns.
            for c in range(n):
                if state_col_star[c] is not None:
                    continue
                possible = 0
                for r in range(n):
                    possible |= (state_candidates[r] & col_mask[c])
                if possible & (possible - 1) == 0:
                    lsb = possible
                    placed = place(state_candidates, state_row_star, state_col_star, state_reg_star, lsb)
                    if placed is None:
                        return None
                    state_candidates, state_row_star, state_col_star, state_reg_star = placed
                    changed = True

            # Forced regions.
            for reg_i in range(len(regions)):
                if state_reg_star[reg_i] is not None:
                    continue
                possible = 0
                rm = reg_mask[reg_i]
                for r in range(n):
                    possible |= (state_candidates[r] & rm)
                if possible & (possible - 1) == 0:
                    lsb = possible
                    placed = place(state_candidates, state_row_star, state_col_star, state_reg_star, lsb)
                    if placed is None:
                        return None
                    state_candidates, state_row_star, state_col_star, state_reg_star = placed
                    changed = True

            # If a row has candidates only in one column or one region, place when singular.
            for r in range(n):
                if state_row_star[r] is not None:
                    continue
                mask = state_candidates[r]

                # Unique available column within this row candidate set.
                col_hits = []
                for c in range(n):
                    cm = mask & col_mask[c]
                    if cm:
                        col_hits.append((c, cm))
                if len(col_hits) == 1 and col_hits[0][1] & (col_hits[0][1] - 1) == 0:
                    lsb = col_hits[0][1]
                    placed = place(state_candidates, state_row_star, state_col_star, state_reg_star, lsb)
                    if placed is None:
                        return None
                    state_candidates, state_row_star, state_col_star, state_reg_star = placed
                    changed = True

            # Hidden singles by interaction:
            # If in a region, all candidates lie in one row, then that row's star must be in the region.
            for reg_i in range(len(regions)):
                if state_reg_star[reg_i] is not None:
                    continue
                rm = reg_mask[reg_i]
                rows_with = []
                union = 0
                for r in range(n):
                    hit = state_candidates[r] & rm
                    if hit:
                        rows_with.append((r, hit))
                        union |= hit
                if not rows_with:
                    return None
                if len(rows_with) == 1 and union & (union - 1) == 0:
                    lsb = union
                    placed = place(state_candidates, state_row_star, state_col_star, state_reg_star, lsb)
                    if placed is None:
                        return None
                    state_candidates, state_row_star, state_col_star, state_reg_star = placed
                    changed = True

            # Matching feasibility: rows->columns, rows->regions, regions->columns.
            open_rows = [r for r in range(n) if state_row_star[r] is None]
            open_cols = [c for c in range(n) if state_col_star[c] is None]
            open_regs = [i for i in range(len(regions)) if state_reg_star[i] is None]

            row_masks_open = [state_candidates[r] for r in open_rows]
            col_masks_open = [col_mask[c] for c in open_cols]
            reg_masks_open = [reg_mask[i] for i in open_regs]

            if not max_matching_possible(row_masks_open, col_masks_open):
                return None
            if open_regs and not max_matching_possible(row_masks_open, reg_masks_open):
                return None
            if open_regs and not max_matching_possible(reg_masks_open, col_masks_open):
                return None

            # Completion check.
            complete = all(state_row_star[r] is not None for r in range(n))
            if complete:
                return state_candidates, state_row_star, state_col_star, state_reg_star

            if not changed:
                return state_candidates, state_row_star, state_col_star, state_reg_star

    def choose_branch_cell(state_candidates, state_row_star, state_col_star, state_reg_star):
        # Choose the most constrained unresolved row first.
        best_row = None
        best_count = 10**9
        for r in range(n):
            if state_row_star[r] is None:
                cnt = state_candidates[r].bit_count()
                if cnt < best_count:
                    best_count = cnt
                    best_row = r

        if best_row is None:
            return None, []

        # Order candidate cells by how constraining they are:
        # fewer future row/col/region options after placement is tried first.
        opts = []
        mask = state_candidates[best_row]
        for lsb in bits(mask):
            r, c = rc_from_bit(lsb)
            reg_i = reg_index[data[r][c]]
            score = 0

            # Prefer cells that constrain neighbors and tight units.
            score += (state_candidates[max(0, r - 1)] & (col_mask[c] | (col_mask[c - 1] if c > 0 else 0) | (col_mask[c + 1] if c + 1 < n else 0))).bit_count() if r > 0 else 0
            score += (state_candidates[min(n - 1, r + 1)] & (col_mask[c] | (col_mask[c - 1] if c > 0 else 0) | (col_mask[c + 1] if c + 1 < n else 0))).bit_count() if r + 1 < n else 0

            col_poss = 0
            reg_poss = 0
            for rr in range(n):
                col_poss |= state_candidates[rr] & col_mask[c]
                reg_poss |= state_candidates[rr] & reg_mask[reg_i]
            score += col_poss.bit_count() + reg_poss.bit_count()

            opts.append((score, lsb))
        opts.sort()
        return best_row, [lsb for _, lsb in opts]

    def search(state_candidates, state_row_star, state_col_star, state_reg_star):
        propagated = propagate(state_candidates, state_row_star, state_col_star, state_reg_star)
        if propagated is None:
            return None
        state_candidates, state_row_star, state_col_star, state_reg_star = propagated

        if all(s is not None for s in state_row_star):
            return state_row_star

        _, options = choose_branch_cell(state_candidates, state_row_star, state_col_star, state_reg_star)
        for lsb in options:
            placed = place(state_candidates, state_row_star, state_col_star, state_reg_star, lsb)
            if placed is None:
                continue
            result = search(*placed)
            if result is not None:
                return result

        return None

    result = search(candidates, row_star, col_star, reg_star)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for lsb in result:
        r, c = rc_from_bit(lsb)
        answer[r][c] = 'S'
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 1, 2, 3, 3, 4], [5, 6, 2, 7, 7, 4], [5, 2, 2, 8, 7, 9], [10, 10, 11, 12, 13, 9], [14, 14, 11, 12, 13, 15], [16, 17, 17, 13, 13, 15]], 'row_water_counts': [1, 1, 4, 2, 4, 2], 'col_water_counts': [3, 5, 2, 2, 1, 1]}

# General solver for "water level per region" puzzles.
# A region may be empty, or filled to a single horizontal water level:
# if a cell in a region is water, then all cells of that region in lower rows are also water.

from collections import defaultdict

def solve(observation):
    region_grid = observation["region"]
    row_target = observation["row_water_counts"]
    col_target = observation["col_water_counts"]

    h = len(region_grid)
    if h == 0:
        return "No Solution"
    w = len(region_grid[0])

    # Validate rectangular grid.
    if any(len(row) != w for row in region_grid):
        return "No Solution"
    if len(row_target) != h or len(col_target) != w:
        return "No Solution"

    # Collect cells per region.
    cells_by_region = defaultdict(list)
    for r in range(h):
        for c in range(w):
            cells_by_region[region_grid[r][c]].append((r, c))

    region_ids = sorted(cells_by_region)
    rid_to_idx = {rid: i for i, rid in enumerate(region_ids)}
    n_regions = len(region_ids)

    # Enumerate all valid water configurations for each region.
    # Valid choices are: empty, or choose a threshold among the distinct rows occupied by the region;
    # all cells in rows >= threshold become water.
    options = []
    region_rows = []
    region_cols = []
    region_cells = []

    for rid in region_ids:
        cells = cells_by_region[rid]
        region_cells.append(cells)
        rows_present = sorted({r for r, _ in cells})
        cols_present = sorted({c for _, c in cells})
        region_rows.append(rows_present)
        region_cols.append(cols_present)

        reg_opts = []
        seen = set()

        # Empty option.
        empty_cells = frozenset()
        row_counts = [0] * h
        col_counts = [0] * w
        key = (empty_cells, tuple(row_counts), tuple(col_counts))
        seen.add(key)
        reg_opts.append({
            "cells": empty_cells,
            "row_counts": row_counts,
            "col_counts": col_counts,
            "total": 0,
        })

        # Threshold options.
        for thr in rows_present:
            wcells = frozenset((r, c) for (r, c) in cells if r >= thr)
            row_counts = [0] * h
            col_counts = [0] * w
            for r, c in wcells:
                row_counts[r] += 1
                col_counts[c] += 1
            key = (wcells, tuple(row_counts), tuple(col_counts))
            if key in seen:
                continue
            seen.add(key)
            reg_opts.append({
                "cells": wcells,
                "row_counts": row_counts,
                "col_counts": col_counts,
                "total": len(wcells),
            })

        # Sort smaller water totals first; often useful for branching.
        reg_opts.sort(key=lambda o: (o["total"], tuple(o["row_counts"]), tuple(o["col_counts"])))
        options.append(reg_opts)

    # Precompute row/col contributors.
    row_regions = [[] for _ in range(h)]
    col_regions = [[] for _ in range(w)]
    for i, reg_opts in enumerate(options):
        row_nonzero = set()
        col_nonzero = set()
        for opt in reg_opts:
            for r, v in enumerate(opt["row_counts"]):
                if v:
                    row_nonzero.add(r)
            for c, v in enumerate(opt["col_counts"]):
                if v:
                    col_nonzero.add(c)
        for r in row_nonzero:
            row_regions[r].append(i)
        for c in col_nonzero:
            col_regions[c].append(i)

    # Domain is a list of lists of allowed option indices per region.
    domains = [list(range(len(opts))) for opts in options]

    def row_bounds(domains):
        mins = [0] * h
        maxs = [0] * h
        for i, dom in enumerate(domains):
            opts_i = options[i]
            for r in range(h):
                vals = [opts_i[k]["row_counts"][r] for k in dom]
                mins[r] += min(vals)
                maxs[r] += max(vals)
        return mins, maxs

    def col_bounds(domains):
        mins = [0] * w
        maxs = [0] * w
        for i, dom in enumerate(domains):
            opts_i = options[i]
            for c in range(w):
                vals = [opts_i[k]["col_counts"][c] for k in dom]
                mins[c] += min(vals)
                maxs[c] += max(vals)
        return mins, maxs

    def feasible_totals(domains):
        rmin, rmax = row_bounds(domains)
        cmin, cmax = col_bounds(domains)
        for r in range(h):
            if not (rmin[r] <= row_target[r] <= rmax[r]):
                return False
        for c in range(w):
            if not (cmin[c] <= col_target[c] <= cmax[c]):
                return False
        return True

    def propagate(domains):
        # Repeatedly prune impossible options using row/col residual bounds.
        changed = True
        while changed:
            changed = False

            # Global bound check.
            rmin, rmax = row_bounds(domains)
            cmin, cmax = col_bounds(domains)
            for r in range(h):
                if not (rmin[r] <= row_target[r] <= rmax[r]):
                    return None
            for c in range(w):
                if not (cmin[c] <= col_target[c] <= cmax[c]):
                    return None

            # If some row/col exact bound is forced, prune options inconsistent with that.
            for i in range(n_regions):
                dom = domains[i]
                if len(dom) == 1:
                    continue

                kept = []
                opts_i = options[i]

                for k in dom:
                    opt = opts_i[k]
                    ok = True

                    # Check rows.
                    for r in range(h):
                        val = opt["row_counts"][r]
                        other_min = rmin[r] - min(opts_i[t]["row_counts"][r] for t in dom)
                        other_max = rmax[r] - max(opts_i[t]["row_counts"][r] for t in dom)
                        if not (other_min + val <= row_target[r] <= other_max + val):
                            ok = False
                            break
                    if not ok:
                        continue

                    # Check cols.
                    for c in range(w):
                        val = opt["col_counts"][c]
                        other_min = cmin[c] - min(opts_i[t]["col_counts"][c] for t in dom)
                        other_max = cmax[c] - max(opts_i[t]["col_counts"][c] for t in dom)
                        if not (other_min + val <= col_target[c] <= other_max + val):
                            ok = False
                            break

                    if ok:
                        kept.append(k)

                if not kept:
                    return None
                if len(kept) != len(dom):
                    domains[i] = kept
                    changed = True

            # Recompute after domain changes, then use stronger row/col exact pruning.
            rmin, rmax = row_bounds(domains)
            cmin, cmax = col_bounds(domains)

            for r in range(h):
                if row_target[r] == rmin[r] == rmax[r]:
                    continue
                # nothing extra beyond per-option residual check for now

            for c in range(w):
                if col_target[c] == cmin[c] == cmax[c]:
                    continue

        return domains

    def pick_region(domains):
        best = None
        best_key = None
        for i, dom in enumerate(domains):
            if len(dom) <= 1:
                continue
            # Heuristic: smallest domain, then largest variability.
            row_var = 0
            col_var = 0
            for r in range(h):
                vals = {options[i][k]["row_counts"][r] for k in dom}
                row_var += len(vals) - 1
            for c in range(w):
                vals = {options[i][k]["col_counts"][c] for k in dom}
                col_var += len(vals) - 1
            key = (len(dom), -(row_var + col_var))
            if best is None or key < best_key:
                best = i
                best_key = key
        return best

    def build_answer(domains):
        grid = [[None for _ in range(w)] for _ in range(h)]
        for i, dom in enumerate(domains):
            if len(dom) != 1:
                return None
            opt = options[i][dom[0]]
            for r, c in opt["cells"]:
                grid[r][c] = 'W'
        return grid

    def search(domains):
        domains = [d[:] for d in domains]
        domains = propagate(domains)
        if domains is None:
            return None

        if not feasible_totals(domains):
            return None

        if all(len(d) == 1 for d in domains):
            grid = build_answer(domains)
            if grid is None:
                return None

            # Final exact validation.
            if [sum(1 for c in row if c == 'W') for row in grid] != row_target:
                return None
            if [sum(1 for r in range(h) if grid[r][c] == 'W') for c in range(w)] != col_target:
                return None
            return grid

        i = pick_region(domains)
        if i is None:
            return None

        # Try more constrained options first: those whose counts are closer to residual needs.
        dom = domains[i]
        scored = []
        rmin, rmax = row_bounds(domains)
        cmin, cmax = col_bounds(domains)
        opts_i = options[i]
        base_row_min = [min(opts_i[t]["row_counts"][r] for t in dom) for r in range(h)]
        base_row_max = [max(opts_i[t]["row_counts"][r] for t in dom) for r in range(h)]
        base_col_min = [min(opts_i[t]["col_counts"][c] for t in dom) for c in range(w)]
        base_col_max = [max(opts_i[t]["col_counts"][c] for t in dom) for c in range(w)]

        for k in dom:
            opt = opts_i[k]
            score = 0
            for r in range(h):
                other_min = rmin[r] - base_row_min[r]
                other_max = rmax[r] - base_row_max[r]
                low = other_min + opt["row_counts"][r]
                high = other_max + opt["row_counts"][r]
                score += (high - low)
            for c in range(w):
                other_min = cmin[c] - base_col_min[c]
                other_max = cmax[c] - base_col_max[c]
                low = other_min + opt["col_counts"][c]
                high = other_max + opt["col_counts"][c]
                score += (high - low)
            scored.append((score, k))
        scored.sort()

        for _, k in scored:
            new_domains = [d[:] for d in domains]
            new_domains[i] = [k]
            res = search(new_domains)
            if res is not None:
                return res
        return None

    result = search(domains)
    if result is None:
        return "No Solution"
    return repr(result)


