# General Futoshiki / Latin-square-with-inequalities solver.
# Uses aggressive propagation:
# - row/column singleton elimination
# - inequality arc consistency
# - hidden singles in rows/columns
# - naked subsets in rows/columns
# Then branches only on the most constrained cell.

def solve(observation):
    data = observation['data']
    n = len(data)
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    def values(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    def parse_key(s):
        a, b = s.strip()[1:-1].split(',')
        x = float(a)
        y = float(b)
        if x.is_integer():
            x = int(x)
        if y.is_integer():
            y = int(y)
        return x, y

    # Build inequality arcs as directed constraints a < b.
    lt_arcs = []
    for k, sym in observation.get('horizontal', {}).items():
        r, c05 = parse_key(k)
        c = int(c05 - 0.5)
        if sym == '<':
            lt_arcs.append((r, c, r, c + 1))
        else:
            lt_arcs.append((r, c + 1, r, c))
    for k, sym in observation.get('vertical', {}).items():
        r05, c = parse_key(k)
        r = int(r05 - 0.5)
        # '^' means upper cell < lower cell, 'v' means upper cell > lower cell.
        if sym == '^':
            lt_arcs.append((r, c, r + 1, c))
        else:
            lt_arcs.append((r + 1, c, r, c))

    row_units = [[(r, c) for c in range(n)] for r in range(n)]
    col_units = [[(r, c) for r in range(n)] for c in range(n)]
    units = row_units + col_units

    # Precompute cell -> inequalities touching it.
    lt_from = [[[] for _ in range(n)] for _ in range(n)]  # cell < others
    lt_to = [[[] for _ in range(n)] for _ in range(n)]    # others < cell
    for r1, c1, r2, c2 in lt_arcs:
        lt_from[r1][c1].append((r2, c2))
        lt_to[r2][c2].append((r1, c1))

    def init_domains():
        dom = [[full for _ in range(n)] for _ in range(n)]
        for r in range(n):
            for c in range(n):
                if data[r][c] is not None:
                    dom[r][c] = bit(data[r][c])
        return dom

    def apply_singleton_elimination(dom):
        changed = False
        # For each row and column, fixed values cannot appear elsewhere.
        for r in range(n):
            fixed_mask = 0
            for c in range(n):
                m = dom[r][c]
                if m == 0:
                    return None
                if m & (m - 1) == 0:
                    if fixed_mask & m:
                        return None
                    fixed_mask |= m
            if fixed_mask:
                inv = ~fixed_mask
                for c in range(n):
                    m = dom[r][c]
                    if m & (m - 1):
                        nm = m & inv
                        if nm == 0:
                            return None
                        if nm != m:
                            dom[r][c] = nm
                            changed = True

        for c in range(n):
            fixed_mask = 0
            for r in range(n):
                m = dom[r][c]
                if m == 0:
                    return None
                if m & (m - 1) == 0:
                    if fixed_mask & m:
                        return None
                    fixed_mask |= m
            if fixed_mask:
                inv = ~fixed_mask
                for r in range(n):
                    m = dom[r][c]
                    if m & (m - 1):
                        nm = m & inv
                        if nm == 0:
                            return None
                        if nm != m:
                            dom[r][c] = nm
                            changed = True
        return changed

    def revise_lt_mask(ma, mb):
        # Keep a-values that have some b-value with a < b, and vice versa.
        if ma == 0 or mb == 0:
            return 0, 0
        allowed_a = 0
        allowed_b = 0
        b_prefix = 0
        cur = 0
        # prefix[i] = bits <= i; here use iterative accumulation.
        for v in range(1, n + 1):
            if mb & bit(v):
                cur |= bit(v)
        # Use min/max fast cut first.
        max_b = max_val(mb)
        min_a = min_val(ma)
        na = ma & (bit(max_b) - 1)
        nb = mb & ~((1 << min_a) - 1)
        # Exact arc consistency on arbitrary masks.
        if na == 0 or nb == 0:
            return 0, 0
        greater_seen = 0
        for v in range(n, 0, -1):
            if nb & bit(v):
                greater_seen |= bit(v)
            if na & bit(v):
                if greater_seen & ~((1 << v) - 1):
                    allowed_a |= bit(v)
        smaller_seen = 0
        for v in range(1, n + 1):
            if na & bit(v):
                smaller_seen |= bit(v)
            if nb & bit(v):
                if smaller_seen & ((1 << (v - 1)) - 1):
                    allowed_b |= bit(v)
        return allowed_a, allowed_b

    def apply_inequalities(dom):
        changed = False
        for r1, c1, r2, c2 in lt_arcs:
            a = dom[r1][c1]
            b = dom[r2][c2]
            na, nb = revise_lt_mask(a, b)
            if na == 0 or nb == 0:
                return None
            if na != a:
                dom[r1][c1] = na
                changed = True
            if nb != b:
                dom[r2][c2] = nb
                changed = True
        return changed

    def apply_hidden_singles(dom):
        changed = False
        for unit in units:
            pos = [0] * (n + 1)
            cnt = [0] * (n + 1)
            for idx, (r, c) in enumerate(unit):
                m = dom[r][c]
                if m == 0:
                    return None
                for v in values(m):
                    cnt[v] += 1
                    pos[v] = idx
            for v in range(1, n + 1):
                if cnt[v] == 0:
                    return None
                if cnt[v] == 1:
                    r, c = unit[pos[v]]
                    bv = bit(v)
                    if dom[r][c] != bv:
                        dom[r][c] = bv
                        changed = True
        return changed

    def apply_naked_subsets(dom):
        changed = False
        for unit in units:
            groups = {}
            for r, c in unit:
                m = dom[r][c]
                pc = popcount(m)
                if 2 <= pc <= 4:
                    groups.setdefault(m, []).append((r, c))
            for m, cells in groups.items():
                k = popcount(m)
                if len(cells) == k:
                    for r, c in unit:
                        if (r, c) not in cells:
                            old = dom[r][c]
                            nm = old & ~m
                            if nm == 0:
                                return None
                            if nm != old:
                                dom[r][c] = nm
                                changed = True

            # Hidden subsets up to size 4 via digit pattern.
            digit_places = {}
            for d in range(1, n + 1):
                place_mask = 0
                for i, (r, c) in enumerate(unit):
                    if dom[r][c] & bit(d):
                        place_mask |= 1 << i
                if place_mask == 0:
                    return None
                pc = popcount(place_mask)
                if 2 <= pc <= 4:
                    digit_places.setdefault(place_mask, []).append(d)
            for place_mask, digs in digit_places.items():
                k = popcount(place_mask)
                if len(digs) == k:
                    keep = 0
                    for d in digs:
                        keep |= bit(d)
                    for i, (r, c) in enumerate(unit):
                        if place_mask & (1 << i):
                            old = dom[r][c]
                            nm = old & keep
                            if nm == 0:
                                return None
                            if nm != old:
                                dom[r][c] = nm
                                changed = True
        return changed

    def bounded_by_ineq(dom):
        # Quick bounds from chains touching fixed-ish domains.
        changed = False
        for r in range(n):
            for c in range(n):
                m = dom[r][c]
                if m == 0:
                    return None
                # If x < y, then x cannot be >= max(y). Already handled by arc consistency.
                # If z < x, then x cannot be <= min(z). Also handled.
                # Keep for possible further immediate contradictions from count of neighbors.
                if lt_from[r][c]:
                    max_upper = n
                    for rr, cc in lt_from[r][c]:
                        max_upper = min(max_upper, max_val(dom[rr][cc]) - 1)
                    nm = m & ((1 << max_upper) - 1) if max_upper > 0 else 0
                    if nm == 0:
                        return None
                    if nm != m:
                        dom[r][c] = nm
                        m = nm
                        changed = True
                if lt_to[r][c]:
                    min_lower = 1
                    for rr, cc in lt_to[r][c]:
                        min_lower = max(min_lower, min_val(dom[rr][cc]) + 1)
                    nm = m & ~((1 << (min_lower - 1)) - 1)
                    if nm == 0:
                        return None
                    if nm != m:
                        dom[r][c] = nm
                        changed = True
        return changed

    def propagate(dom):
        while True:
            any_change = False
            for fn in (apply_singleton_elimination, apply_inequalities, bounded_by_ineq, apply_hidden_singles, apply_naked_subsets):
                res = fn(dom)
                if res is None:
                    return None
                if res:
                    any_change = True
            if not any_change:
                return dom

    def solved(dom):
        return all(dom[r][c] & (dom[r][c] - 1) == 0 for r in range(n) for c in range(n))

    def select_branch_cell(dom):
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                m = dom[r][c]
                pc = popcount(m)
                if pc > 1:
                    degree = (n - 1) * 2 + len(lt_from[r][c]) + len(lt_to[r][c])
                    score = (pc, -degree)
                    if best is None or score < best_score:
                        best = (r, c)
                        best_score = score
        return best

    def order_values(dom, r, c):
        m = dom[r][c]
        vals = []
        for v in values(m):
            impact = 0
            bv = bit(v)
            for cc in range(n):
                if cc != c and (dom[r][cc] & bv):
                    impact += 1
            for rr in range(n):
                if rr != r and (dom[rr][c] & bv):
                    impact += 1
            # Prefer values that satisfy inequalities tightly and eliminate more.
            for rr, cc in lt_from[r][c]:
                for w in values(dom[rr][cc]):
                    if not (v < w):
                        impact += 1
            for rr, cc in lt_to[r][c]:
                for w in values(dom[rr][cc]):
                    if not (w < v):
                        impact += 1
            vals.append((impact, v))
        vals.sort(reverse=True)
        return [v for _, v in vals]

    def clone(dom):
        return [row[:] for row in dom]

    def search(dom):
        dom = propagate(dom)
        if dom is None:
            return None
        if solved(dom):
            return [[min_val(dom[r][c]) for c in range(n)] for r in range(n)]

        r, c = select_branch_cell(dom)
        for v in order_values(dom, r, c):
            nd = clone(dom)
            nd[r][c] = bit(v)
            ans = search(nd)
            if ans is not None:
                return ans
        return None

    result = search(init_domains())
    return result if result is not None else "No Solution"


