# General Masyu solver on a dot-grid.
# The solver uses human-like local pattern domains for each dot:
#   empty, horizontal, vertical, or one of four turns.
# It then applies aggressive constraint propagation from:
#   - ordinary loop degree logic,
#   - black circle continuation rules,
#   - white circle straight+adjacent-turn rules,
#   - edge consistency between neighboring dots.
# Only after propagation stalls does it branch on the most constrained vertex.

U, R, D, L = 1, 2, 4, 8

STATE_MASKS = {
    "E": 0,
    "H": L | R,
    "V": U | D,
    "UR": U | R,
    "UL": U | L,
    "DR": D | R,
    "DL": D | L,
}
STATE_NAMES = list(STATE_MASKS.keys())
MASK_TO_NAME = {v: k for k, v in STATE_MASKS.items()}
ALL_STATES = list(STATE_MASKS.values())

EMPTY = STATE_MASKS["E"]
H = STATE_MASKS["H"]
V = STATE_MASKS["V"]
UR = STATE_MASKS["UR"]
UL = STATE_MASKS["UL"]
DR = STATE_MASKS["DR"]
DL = STATE_MASKS["DL"]

DIRS = [U, R, D, L]
DRC = {
    U: (-1, 0),
    R: (0, 1),
    D: (1, 0),
    L: (0, -1),
}
OPP = {U: D, D: U, L: R, R: L}

TURN_FROM_SIDE = {
    U: {DR, DL},  # neighbor above must connect down and turn left/right
    D: {UR, UL},
    L: {UR, DR},
    R: {UL, DL},
}

STRAIGHT_FROM_SIDE = {
    U: V,
    D: V,
    L: H,
    R: H,
}

def inside(n, r, c):
    return 0 <= r < n and 0 <= c < n

def allowed_initial_states(clue):
    if clue == 'W':
        return {H, V}
    if clue == 'B':
        return {UR, UL, DR, DL}
    return {EMPTY, H, V, UR, UL, DR, DL}

def bitcount(x):
    return x.bit_count()

def state_uses(mask, d):
    return (mask & d) != 0

def domain_str(dom):
    return "{" + ",".join(MASK_TO_NAME[s] for s in sorted(dom)) + "}"

def revise_domains(domains, clues):
    n = len(clues)
    changed = True
    while changed:
        changed = False

        # Boundary filtering and plain neighbor edge consistency support
        for r in range(n):
            for c in range(n):
                dom = domains[r][c]
                new_dom = set()
                for s in dom:
                    ok = True

                    # Boundary: no edge can leave the board
                    for d in DIRS:
                        rr, cc = r + DRC[d][0], c + DRC[d][1]
                        if not inside(n, rr, cc) and state_uses(s, d):
                            ok = False
                            break
                    if not ok:
                        continue

                    # Every edge presence/absence must be supported by neighbor
                    for d in DIRS:
                        rr, cc = r + DRC[d][0], c + DRC[d][1]
                        if not inside(n, rr, cc):
                            continue
                        need = state_uses(s, d)
                        opp = OPP[d]
                        ndom = domains[rr][cc]
                        if need:
                            if not any(state_uses(t, opp) for t in ndom):
                                ok = False
                                break
                        else:
                            if not any(not state_uses(t, opp) for t in ndom):
                                ok = False
                                break
                    if not ok:
                        continue

                    # Black circle: must turn here, and both adjacent next vertices are straight-through
                    if clues[r][c] == 'B':
                        reqs = []
                        if s == UR:
                            reqs = [(U, V), (R, H)]
                        elif s == UL:
                            reqs = [(U, V), (L, H)]
                        elif s == DR:
                            reqs = [(D, V), (R, H)]
                        elif s == DL:
                            reqs = [(D, V), (L, H)]
                        else:
                            ok = False
                        if ok:
                            for d, forced_state in reqs:
                                rr, cc = r + DRC[d][0], c + DRC[d][1]
                                if not inside(n, rr, cc) or forced_state not in domains[rr][cc]:
                                    ok = False
                                    break
                    if not ok:
                        continue

                    # White circle: must go straight here, and at least one adjacent vertex along the path turns
                    if clues[r][c] == 'W':
                        if s == V:
                            up_ok = False
                            dn_ok = False
                            rr, cc = r - 1, c
                            if inside(n, rr, cc):
                                up_ok = any(t in TURN_FROM_SIDE[D] for t in domains[rr][cc])
                            rr, cc = r + 1, c
                            if inside(n, rr, cc):
                                dn_ok = any(t in TURN_FROM_SIDE[U] for t in domains[rr][cc])
                            if not (up_ok or dn_ok):
                                ok = False
                        elif s == H:
                            lf_ok = False
                            rt_ok = False
                            rr, cc = r, c - 1
                            if inside(n, rr, cc):
                                lf_ok = any(t in TURN_FROM_SIDE[R] for t in domains[rr][cc])
                            rr, cc = r, c + 1
                            if inside(n, rr, cc):
                                rt_ok = any(t in TURN_FROM_SIDE[L] for t in domains[rr][cc])
                            if not (lf_ok or rt_ok):
                                ok = False
                        else:
                            ok = False

                    if ok:
                        new_dom.add(s)

                if not new_dom:
                    return False
                if new_dom != dom:
                    domains[r][c] = new_dom
                    changed = True

        # Strong forward forcing from singleton black states
        for r in range(n):
            for c in range(n):
                if clues[r][c] != 'B' or len(domains[r][c]) != 1:
                    continue
                s = next(iter(domains[r][c]))
                reqs = []
                if s == UR:
                    reqs = [(U, {V}), (R, {H}), (D, {t for t in domains[r+1][c] if not state_uses(t, U)} if inside(n, r+1, c) else set()), (L, {t for t in domains[r][c-1] if not state_uses(t, R)} if inside(n, r, c-1) else set())]
                elif s == UL:
                    reqs = [(U, {V}), (L, {H}), (D, {t for t in domains[r+1][c] if not state_uses(t, U)} if inside(n, r+1, c) else set()), (R, {t for t in domains[r][c+1] if not state_uses(t, L)} if inside(n, r, c+1) else set())]
                elif s == DR:
                    reqs = [(D, {V}), (R, {H}), (U, {t for t in domains[r-1][c] if not state_uses(t, D)} if inside(n, r-1, c) else set()), (L, {t for t in domains[r][c-1] if not state_uses(t, R)} if inside(n, r, c-1) else set())]
                elif s == DL:
                    reqs = [(D, {V}), (L, {H}), (U, {t for t in domains[r-1][c] if not state_uses(t, D)} if inside(n, r-1, c) else set()), (R, {t for t in domains[r][c+1] if not state_uses(t, L)} if inside(n, r, c+1) else set())]
                else:
                    return False

                for d, force_set in reqs:
                    rr, cc = r + DRC[d][0], c + DRC[d][1]
                    if not inside(n, rr, cc):
                        return False
                    nd = domains[rr][cc] & force_set
                    if not nd:
                        return False
                    if nd != domains[rr][cc]:
                        domains[rr][cc] = nd
                        changed = True

        # Strong forward forcing from singleton white states when one side cannot turn
        for r in range(n):
            for c in range(n):
                if clues[r][c] != 'W' or len(domains[r][c]) != 1:
                    continue
                s = next(iter(domains[r][c]))
                if s == V:
                    if not (inside(n, r-1, c) and inside(n, r+1, c)):
                        return False
                    up_turn = domains[r-1][c] & TURN_FROM_SIDE[D]
                    dn_turn = domains[r+1][c] & TURN_FROM_SIDE[U]
                    if not up_turn and not dn_turn:
                        return False
                    if not up_turn:
                        nd = domains[r+1][c] & TURN_FROM_SIDE[U]
                        if not nd:
                            return False
                        if nd != domains[r+1][c]:
                            domains[r+1][c] = nd
                            changed = True
                    if not dn_turn:
                        nd = domains[r-1][c] & TURN_FROM_SIDE[D]
                        if not nd:
                            return False
                        if nd != domains[r-1][c]:
                            domains[r-1][c] = nd
                            changed = True
                elif s == H:
                    if not (inside(n, r, c-1) and inside(n, r, c+1)):
                        return False
                    lf_turn = domains[r][c-1] & TURN_FROM_SIDE[R]
                    rt_turn = domains[r][c+1] & TURN_FROM_SIDE[L]
                    if not lf_turn and not rt_turn:
                        return False
                    if not lf_turn:
                        nd = domains[r][c+1] & TURN_FROM_SIDE[L]
                        if not nd:
                            return False
                        if nd != domains[r][c+1]:
                            domains[r][c+1] = nd
                            changed = True
                    if not rt_turn:
                        nd = domains[r][c-1] & TURN_FROM_SIDE[R]
                        if not nd:
                            return False
                        if nd != domains[r][c-1]:
                            domains[r][c-1] = nd
                            changed = True
                else:
                    return False
    return True

def fully_assigned(domains):
    return all(len(domains[r][c]) == 1 for r in range(len(domains)) for c in range(len(domains)))

def domains_copy(domains):
    return [[set(domains[r][c]) for c in range(len(domains))] for r in range(len(domains))]

def build_edge_graph(domains):
    n = len(domains)
    graph = {}
    for r in range(n):
        for c in range(n):
            s = next(iter(domains[r][c]))
            if s == EMPTY:
                continue
            graph.setdefault((r, c), set())
            for d in DIRS:
                if state_uses(s, d):
                    rr, cc = r + DRC[d][0], c + DRC[d][1]
                    if inside(n, rr, cc):
                        graph[(r, c)].add((rr, cc))
    return graph

def check_final_solution(domains, clues):
    n = len(domains)

    # Exact mutual edge agreement and clue semantics are already mostly enforced,
    # but re-check rigidly.
    for r in range(n):
        for c in range(n):
            if len(domains[r][c]) != 1:
                return False
            s = next(iter(domains[r][c]))

            # Mutual agreement
            for d in DIRS:
                rr, cc = r + DRC[d][0], c + DRC[d][1]
                if not inside(n, rr, cc):
                    if state_uses(s, d):
                        return False
                    continue
                t = next(iter(domains[rr][cc]))
                if state_uses(s, d) != state_uses(t, OPP[d]):
                    return False

            clue = clues[r][c]
            if clue == 'W':
                if s not in {H, V}:
                    return False
                if s == V:
                    up = next(iter(domains[r-1][c])) if r-1 >= 0 else None
                    dn = next(iter(domains[r+1][c])) if r+1 < n else None
                    if up not in TURN_FROM_SIDE[D] and dn not in TURN_FROM_SIDE[U]:
                        return False
                else:
                    lf = next(iter(domains[r][c-1])) if c-1 >= 0 else None
                    rt = next(iter(domains[r][c+1])) if c+1 < n else None
                    if lf not in TURN_FROM_SIDE[R] and rt not in TURN_FROM_SIDE[L]:
                        return False
            elif clue == 'B':
                if s not in {UR, UL, DR, DL}:
                    return False
                if s == UR:
                    if next(iter(domains[r-1][c])) != V or next(iter(domains[r][c+1])) != H:
                        return False
                elif s == UL:
                    if next(iter(domains[r-1][c])) != V or next(iter(domains[r][c-1])) != H:
                        return False
                elif s == DR:
                    if next(iter(domains[r+1][c])) != V or next(iter(domains[r][c+1])) != H:
                        return False
                elif s == DL:
                    if next(iter(domains[r+1][c])) != V or next(iter(domains[r][c-1])) != H:
                        return False

    graph = build_edge_graph(domains)
    if not graph:
        return False

    # Every used vertex must have degree 2
    for v, nbrs in graph.items():
        if len(nbrs) != 2:
            return False

    # All clues must lie on loop (i.e., non-empty by construction)
    for r in range(n):
        for c in range(n):
            if clues[r][c] is not None and next(iter(domains[r][c])) == EMPTY:
                return False

    # Single closed loop
    start = next(iter(graph))
    seen = set()
    stack = [start]
    while stack:
        v = stack.pop()
        if v in seen:
            continue
        seen.add(v)
        for w in graph[v]:
            if w not in seen:
                stack.append(w)
    if len(seen) != len(graph):
        return False

    return True

def extract_loop(domains):
    graph = build_edge_graph(domains)
    start = min(graph)
    path = [start]
    prev = None
    cur = start
    while True:
        nbrs = sorted(graph[cur])
        nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
    return path

def select_branch_vertex(domains):
    n = len(domains)
    best = None
    best_key = None
    for r in range(n):
        for c in range(n):
            m = len(domains[r][c])
            if m <= 1:
                continue
            # Prefer clue vertices, then smaller domains, then more non-empty states
            clue_bias = 0
            key = (m, clue_bias, -(sum(1 for s in domains[r][c] if s != EMPTY)), r, c)
            if best is None or key < best_key:
                best = (r, c)
                best_key = key
    return best

def search(domains, clues):
    if not revise_domains(domains, clues):
        return None
    if fully_assigned(domains):
        if check_final_solution(domains, clues):
            return domains
        return None

    r, c = select_branch_vertex(domains)
    # Branch value ordering:
    # For clues, keep natural remaining order.
    # For non-clues, prefer non-empty before empty to complete the loop structure sooner.
    vals = sorted(domains[r][c], key=lambda s: (s == EMPTY, bitcount(s)))
    for s in vals:
        nd = domains_copy(domains)
        nd[r][c] = {s}
        res = search(nd, clues)
        if res is not None:
            return res
    return None

def solve(observation):
    clues = observation['data']
    n = len(clues)

    domains = [[allowed_initial_states(clues[r][c]) for c in range(n)] for r in range(n)]

    res = search(domains, clues)
    if res is None:
        return "No Solution"
    return extract_loop(res)

