from collections import deque

B = 'B'
W = 'W'
COLORS = (B, W)


def solve(observation):
    data = observation['data']
    n = len(data)
    grid = [row[:] for row in data]

    neigh = {}
    for r in range(n):
        for c in range(n):
            a = []
            if r > 0:
                a.append((r - 1, c))
            if r + 1 < n:
                a.append((r + 1, c))
            if c > 0:
                a.append((r, c - 1))
            if c + 1 < n:
                a.append((r, c + 1))
            neigh[(r, c)] = a

    boxes_of = {}
    for r in range(n):
        for c in range(n):
            lst = []
            for br in (r - 1, r):
                for bc in (c - 1, c):
                    if 0 <= br < n - 1 and 0 <= bc < n - 1:
                        lst.append((br, bc))
            boxes_of[(r, c)] = lst

    def opposite(x):
        return W if x == B else B

    def clone(g):
        return [row[:] for row in g]

    def set_cell(g, r, c, color, queue):
        cur = g[r][c]
        if cur is None:
            g[r][c] = color
            queue.append((r, c))
            return True
        return cur == color

    def apply_2x2_box(g, br, bc, queue):
        cells = [(br, bc), (br + 1, bc), (br, bc + 1), (br + 1, bc + 1)]
        vals = [g[r][c] for r, c in cells]
        for color in COLORS:
            cnt = sum(v == color for v in vals)
            unk = [cells[i] for i, v in enumerate(vals) if v is None]
            if cnt == 4:
                return False
            if cnt == 3 and len(unk) == 1:
                ur, uc = unk[0]
                if not set_cell(g, ur, uc, opposite(color), queue):
                    return False
        return True

    def apply_local_patterns(g, r, c, queue):
        # 2x2 completion
        for br, bc in boxes_of[(r, c)]:
            if not apply_2x2_box(g, br, bc, queue):
                return False

        # Straight triple rule:
        # If x ? x in a line, middle must be opposite x (otherwise xxx creates a 2x2 extension risk with connectivity).
        # This is a safe local deduction for Yin-Yang when combined with 2x2 avoidance in orthogonal extensions:
        # we use only the stricter form on exact same-color ends with unknown middle in length 3.
        for dc in (-2,):
            pass

        # Checker forcing in 2x3 / 3x2 windows derived from 2x2 rule:
        # If a row segment has three same colors consecutively, cells directly above/below the middle pair cannot both be same.
        # Instead of weak deductions, keep only guaranteed 2x2-based implications:
        # For pattern:
        # a a
        # a ?
        # => ? must be opposite a, already covered by 2x2.
        return True

    def components_and_reach(g, color):
        allowed = [[g[r][c] != opposite(color) for c in range(n)] for r in range(n)]
        fixed = [(r, c) for r in range(n) for c in range(n) if g[r][c] == color]
        if not fixed:
            return 0, True

        seen = set()
        comps = 0
        for cell in fixed:
            if cell in seen:
                continue
            comps += 1
            dq = deque([cell])
            seen.add(cell)
            while dq:
                x, y = dq.popleft()
                for nx, ny in neigh[(x, y)]:
                    if allowed[nx][ny] and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        dq.append((nx, ny))

        # Strong necessary condition:
        # all fixed cells of this color must lie in one connected component of the graph excluding opposite cells
        # otherwise impossible to ever connect them.
        return comps, comps == 1

    def all_assigned(g):
        return all(g[r][c] is not None for r in range(n) for c in range(n))

    def final_connected(g):
        for color in COLORS:
            cells = [(r, c) for r in range(n) for c in range(n) if g[r][c] == color]
            if not cells:
                return False
            seen = {cells[0]}
            dq = deque([cells[0]])
            while dq:
                x, y = dq.popleft()
                for nx, ny in neigh[(x, y)]:
                    if g[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        dq.append((nx, ny))
            if len(seen) != len(cells):
                return False
        return True

    def no_mono_2x2(g):
        for r in range(n - 1):
            for c in range(n - 1):
                vals = {g[r][c], g[r + 1][c], g[r][c + 1], g[r + 1][c + 1]}
                if len(vals) == 1:
                    return False
        return True

    def parity_pressure_score(g, r, c):
        score = 0
        for br, bc in boxes_of[(r, c)]:
            vals = [g[br][bc], g[br + 1][bc], g[br][bc + 1], g[br + 1][bc + 1]]
            assigned = sum(v is not None for v in vals)
            score += assigned * 3
            if vals.count(B) == 2 or vals.count(W) == 2:
                score += 1
        for nr, nc in neigh[(r, c)]:
            if g[nr][nc] is not None:
                score += 2
        return score

    def forced_connectivity_cuts(g, queue):
        # Human-like articulation check:
        # A cell cannot be colored X if that would split the potential region of opposite(X)
        # into multiple fixed components with no path.
        unknowns = [(r, c) for r in range(n) for c in range(n) if g[r][c] is None]
        for r, c in unknowns:
            forced = None
            for color in COLORS:
                gg = clone(g)
                gg[r][c] = color
                ok = True
                for br, bc in boxes_of[(r, c)]:
                    vals = [gg[br][bc], gg[br + 1][bc], gg[br][bc + 1], gg[br + 1][bc + 1]]
                    for cc in COLORS:
                        if vals.count(cc) == 4:
                            ok = False
                            break
                    if not ok:
                        break
                if ok:
                    _, canB = components_and_reach(gg, B)
                    _, canW = components_and_reach(gg, W)
                    ok = canB and canW
                if not ok:
                    if forced is None:
                        forced = opposite(color)
                    elif forced != opposite(color):
                        return False
            if forced is not None:
                if not set_cell(g, r, c, forced, queue):
                    return False
        return True

    def propagate(g):
        queue = deque()
        for r in range(n):
            for c in range(n):
                if g[r][c] is not None:
                    queue.append((r, c))

        processed = set()
        while queue:
            r, c = queue.popleft()
            if (r, c, g[r][c]) in processed:
                continue
            processed.add((r, c, g[r][c]))

            if not apply_local_patterns(g, r, c, queue):
                return None

        changed = True
        while changed:
            changed = False
            # Global pass: 2x2
            before_snapshot = tuple(tuple(row) for row in g)
            q2 = deque()
            for br in range(n - 1):
                for bc in range(n - 1):
                    if not apply_2x2_box(g, br, bc, q2):
                        return None
            while q2:
                rr, cc = q2.popleft()
                if not apply_local_patterns(g, rr, cc, q2):
                    return None

            # Connectivity feasibility
            _, canB = components_and_reach(g, B)
            if not canB:
                return None
            _, canW = components_and_reach(g, W)
            if not canW:
                return None

            # Single-cell cut forcing
            q3 = deque()
            if not forced_connectivity_cuts(g, q3):
                return None
            while q3:
                rr, cc = q3.popleft()
                if not apply_local_patterns(g, rr, cc, q3):
                    return None

            after_snapshot = tuple(tuple(row) for row in g)
            changed = after_snapshot != before_snapshot

        if all_assigned(g):
            if no_mono_2x2(g) and final_connected(g):
                return g
            return None

        return g

    def choose_cell(g):
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                if g[r][c] is not None:
                    continue

                # Test both colors quickly for viability.
                viable = []
                for color in COLORS:
                    gg = clone(g)
                    gg[r][c] = color
                    ok = True
                    for br, bc in boxes_of[(r, c)]:
                        vals = [gg[br][bc], gg[br + 1][bc], gg[br][bc + 1], gg[br + 1][bc + 1]]
                        for cc in COLORS:
                            if vals.count(cc) == 4:
                                ok = False
                                break
                        if not ok:
                            break
                    if ok:
                        _, canB = components_and_reach(gg, B)
                        _, canW = components_and_reach(gg, W)
                        ok = canB and canW
                    if ok:
                        viable.append(color)

                if not viable:
                    return (r, c, [])
                score = parity_pressure_score(g, r, c)
                key = (len(viable), -score, r, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (r, c, viable)
                    if len(viable) == 1:
                        return best
        return best

    def search(g):
        g = propagate(g)
        if g is None:
            return None
        if all_assigned(g):
            return g

        choice = choose_cell(g)
        if choice is None:
            return None
        r, c, viable = choice
        if not viable:
            return None

        # Mildly prefer color matching more neighbors.
        neighbor_colors = [g[nr][nc] for nr, nc in neigh[(r, c)] if g[nr][nc] is not None]
        viable = sorted(
            viable,
            key=lambda color: (
                -sum(x == color for x in neighbor_colors),
                -sum(
                    1
                    for br, bc in boxes_of[(r, c)]
                    if [g[br][bc], g[br + 1][bc], g[br][bc + 1], g[br + 1][bc + 1]].count(opposite(color)) == 2
                ),
            ),
        )

        for color in viable:
            gg = clone(g)
            gg[r][c] = color
            ans = search(gg)
            if ans is not None:
                return ans
        return None

    ans = search(grid)
    return ans if ans is not None else "No Solution"


