from itertools import permutations

# Skyscraper solver using:
# - row candidate generation from side clues
# - Latin-square column uniqueness propagation
# - top/bottom visibility range pruning during incremental row placement
# - depth-first search with aggressive feasibility checks


def visible_count(seq):
    mx = 0
    seen = 0
    for x in seq:
        if x > mx:
            mx = x
            seen += 1
    return seen


def clue_ok(seq, left_clue=0, right_clue=0):
    if left_clue and visible_count(seq) != left_clue:
        return False
    if right_clue and visible_count(reversed(seq)) != right_clue:
        return False
    return True


def top_range(prefix, remaining_values):
    # Visible count from top for: prefix + some permutation(remaining_values)
    cur_vis = visible_count(prefix)
    cur_max = max(prefix) if prefix else 0
    greater = [x for x in remaining_values if x > cur_max]
    if not greater:
        return cur_vis, cur_vis
    return cur_vis + 1, cur_vis + len(greater)


def bottom_range(prefix, remaining_values):
    # Column values are prefix(top assigned) + unknown suffix(remaining_values).
    # From bottom we see: permutation(remaining_values) + reversed(prefix).
    tail = list(reversed(prefix))
    if remaining_values:
        rem_max = max(remaining_values)
        extra = 0
        mx = rem_max
        for x in tail:
            if x > mx:
                mx = x
                extra += 1
        min_vis = 1 + extra
        max_vis = len(remaining_values) + extra
        return min_vis, max_vis
    return visible_count(tail), visible_count(tail)


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    N = len(U)

    nums = tuple(range(1, N + 1))
    full_mask = (1 << (N + 1)) - 2  # bits 1..N set

    all_rows = list(permutations(nums))

    # Generate row candidates from row clues only.
    row_candidates = []
    for r in range(N):
        lc = L[r] if r < len(L) else 0
        rc = R[r] if r < len(R) else 0
        cand = [row for row in all_rows if clue_ok(row, lc, rc)]
        if not cand:
            return "No Solution"
        row_candidates.append(cand)

    # Useful direct pruning from extreme row clues.
    # If left clue == 1 => first is N. If left clue == N => strictly increasing.
    # Likewise for right.
    for r in range(N):
        lc = L[r]
        rc = R[r]
        filtered = []
        for row in row_candidates[r]:
            if lc == 1 and row[0] != N:
                continue
            if rc == 1 and row[-1] != N:
                continue
            if lc == N and list(row) != list(nums):
                continue
            if rc == N and list(row) != list(reversed(nums)):
                continue
            filtered.append(row)
        if not filtered:
            return "No Solution"
        row_candidates[r] = filtered

    # Prefix state per column.
    grid = [None] * N
    col_used = [0] * N
    col_prefix = [[] for _ in range(N)]

    # Precompute candidate ordering heuristic per row:
    # rows with fewer candidates first would be nice, but row order must stay top->bottom
    # for strong top/bottom incremental pruning. So we keep top-down.

    def row_fits_columns(row):
        for c, v in enumerate(row):
            if col_used[c] & (1 << v):
                return False
        return True

    def column_bounds_ok_after_place():
        # Check every column against top/bottom clue ranges.
        for c in range(N):
            prefix = col_prefix[c]
            used_mask = col_used[c]
            remaining = [v for v in nums if not (used_mask & (1 << v))]

            tc = U[c]
            if tc:
                lo, hi = top_range(prefix, remaining)
                if not (lo <= tc <= hi):
                    return False

            bc = D[c]
            if bc:
                lo, hi = bottom_range(prefix, remaining)
                if not (lo <= bc <= hi):
                    return False
        return True

    def final_columns_ok():
        for c in range(N):
            col = [grid[r][c] for r in range(N)]
            if len(set(col)) != N:
                return False
            if U[c] and visible_count(col) != U[c]:
                return False
            if D[c] and visible_count(reversed(col)) != D[c]:
                return False
        return True

    # Additional forward filtering:
    # Given current column-used masks, estimate whether every future row still has some candidate.
    def future_rows_feasible(start_row):
        for r in range(start_row, N):
            ok_any = False
            for row in row_candidates[r]:
                good = True
                for c, v in enumerate(row):
                    if col_used[c] & (1 << v):
                        good = False
                        break
                if good:
                    ok_any = True
                    break
            if not ok_any:
                return False
        return True

    def ordered_candidates_for_row(r):
        # Heuristic:
        # prefer rows that satisfy more constrained columns with top clues early.
        cands = []
        for row in row_candidates[r]:
            if not row_fits_columns(row):
                continue
            score = 0
            for c, v in enumerate(row):
                # fewer remaining options in column => more constrained
                used_count = col_used[c].bit_count()
                score += used_count * 10
                if U[c]:
                    prefix = col_prefix[c]
                    mx = max(prefix) if prefix else 0
                    if v > mx:
                        score += 2
                if D[c]:
                    score += 1
            cands.append((score, row))
        cands.sort()
        return [row for _, row in cands]

    def dfs(r):
        if r == N:
            if final_columns_ok():
                return [list(row) for row in grid]
            return None

        for row in ordered_candidates_for_row(r):
            # Place row.
            for c, v in enumerate(row):
                col_used[c] |= 1 << v
                col_prefix[c].append(v)
            grid[r] = row

            if column_bounds_ok_after_place() and future_rows_feasible(r + 1):
                ans = dfs(r + 1)
                if ans is not None:
                    return ans

            # Undo.
            grid[r] = None
            for c, v in enumerate(row):
                col_prefix[c].pop()
                col_used[c] &= ~(1 << v)

        return None

    ans = dfs(0)
    return str(ans) if ans is not None else "No Solution"


