# Yin-Yang solver:
# - Colors: 'B' and 'W'
# - Constraints:
#   1) Both colors orthogonally connected.
#   2) No 2x2 monochromatic blocks.
#   3) Respect clues.
#
# The implementation emphasizes strong propagation before search:
# - 2x2 completion rules
# - anti-isolation rules
# - connectivity feasibility checks
# - disconnected possible-area elimination
# - articulation-like mandatory connector detection
# - speculative branching with fail-fast propagation

from collections import deque

B = 1
W = 2
BW = 3

def solve(observation):
    data = observation["data"]
    n = len(data)
    board = [[BW] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                board[r][c] = B
            elif v == 'W':
                board[r][c] = W

    res = _search(board)
    if res is None:
        return "No Solution"
    out = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append('B' if res[r][c] == B else 'W')
        out.append(row)
    return repr(out)

def _search(board):
    board = _copy_board(board)
    if not _propagate(board):
        return None
    if _is_solved(board):
        return board

    r, c = _choose_cell(board)
    if r is None:
        return None

    # Try the more constrained branch order first using local impact.
    options = _branch_order(board, r, c)
    for color in options:
        nb = _copy_board(board)
        nb[r][c] = color
        ans = _search(nb)
        if ans is not None:
            return ans
    return None

def _branch_order(board, r, c):
    scores = []
    for color in (B, W):
        nb = _copy_board(board)
        nb[r][c] = color
        ok = _propagate(nb)
        if not ok:
            scores.append((-10**9, color))
        else:
            forced = sum(1 for row in nb for v in row if v != BW) - sum(1 for row in board for v in row if v != BW)
            scores.append((forced, color))
    scores.sort(reverse=True)
    return [color for _, color in scores]

def _copy_board(board):
    return [row[:] for row in board]

def _is_solved(board):
    n = len(board)
    for r in range(n):
        for c in range(n):
            if board[r][c] == BW:
                return False
    return _final_check(board)

def _final_check(board):
    n = len(board)

    # No monochromatic 2x2
    for r in range(n - 1):
        for c in range(n - 1):
            vals = {board[r][c], board[r+1][c], board[r][c+1], board[r+1][c+1]}
            if len(vals) == 1:
                return False

    # Both colors connected
    for color in (B, W):
        cells = [(r, c) for r in range(n) for c in range(n) if board[r][c] == color]
        if not cells:
            return False
        seen = set()
        dq = deque([cells[0]])
        seen.add(cells[0])
        while dq:
            r, c = dq.popleft()
            for nr, nc in _neighbors(n, r, c):
                if board[nr][nc] == color and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    dq.append((nr, nc))
        if len(seen) != len(cells):
            return False

    return True

def _choose_cell(board):
    n = len(board)
    best = None
    best_score = None
    for r in range(n):
        for c in range(n):
            if board[r][c] != BW:
                continue
            score = 0
            # Prefer cells in many 2x2s / near fixed cells / near connectivity tension
            for nr, nc in _neighbors(n, r, c):
                if board[nr][nc] != BW:
                    score += 3
            if 0 < r < n - 1:
                score += 1
            if 0 < c < n - 1:
                score += 1
            # More surrounding 2x2 blocks = more constraining
            if r > 0 and c > 0:
                score += 1
            if r > 0 and c < n - 1:
                score += 1
            if r < n - 1 and c > 0:
                score += 1
            if r < n - 1 and c < n - 1:
                score += 1
            if best_score is None or score > best_score:
                best_score = score
                best = (r, c)
    return best if best is not None else (None, None)

def _propagate(board):
    n = len(board)
    changed = True
    while changed:
        changed = False

        # Basic contradiction on clues already embedded in board.

        # Rule group 1: 2x2 constraints and forced fourth cell.
        for r in range(n - 1):
            for c in range(n - 1):
                cells = [(r, c), (r+1, c), (r, c+1), (r+1, c+1)]
                vals = [board[x][y] for x, y in cells]
                if vals.count(B) == 4 or vals.count(W) == 4:
                    return False
                if vals.count(B) == 3 and vals.count(BW) == 1:
                    i = vals.index(BW)
                    x, y = cells[i]
                    if not _assign(board, x, y, W):
                        return False
                    changed = True
                if vals.count(W) == 3 and vals.count(BW) == 1:
                    i = vals.index(BW)
                    x, y = cells[i]
                    if not _assign(board, x, y, B):
                        return False
                    changed = True

        # Rule group 2: anti-isolation for fixed cells.
        for color in (B, W):
            opp = W if color == B else B
            for r in range(n):
                for c in range(n):
                    if board[r][c] != color:
                        continue
                    same_fixed = 0
                    possible_same_unknown = []
                    for nr, nc in _neighbors(n, r, c):
                        if board[nr][nc] == color:
                            same_fixed += 1
                        elif board[nr][nc] == BW:
                            possible_same_unknown.append((nr, nc))
                    if same_fixed == 0:
                        if not possible_same_unknown:
                            # A singleton color-cell cannot connect to the rest.
                            # Exception only if the entire board of that color were one cell, impossible unless n=1.
                            return False
                        if len(possible_same_unknown) == 1:
                            nr, nc = possible_same_unknown[0]
                            if not _assign(board, nr, nc, color):
                                return False
                            changed = True

        # Rule group 3: pattern-based local forcing to avoid creating isolated unknowns in 2x2 corridors.
        if not _line_rules(board):
            return False

        # Rule group 4: connectivity feasibility and disconnected-possible-area elimination.
        if not _connectivity_prune(board):
            return False

        # Rule group 5: mandatory connector detection.
        if not _mandatory_connectors(board):
            return False

        # If any change occurred inside helper routines, detect by stamps:
        # helpers modify board directly; we compare via scan count.
        # Instead of expensive snapshots, we run additional deterministic forced checks:
        # if helper made changes, the next loop iteration will continue due to returned markers.
        helper_changed = _drain_pending_flags(board)
        if helper_changed:
            changed = True

    return _final_feasibility(board)

def _line_rules(board):
    n = len(board)
    changed = False

    # If two same-colored cells are separated by one unknown in a row/column,
    # the middle cannot be opposite, otherwise that color risks local split and opposite may create 2x2 issues.
    # This is a mild, safe rule only when endpoints are fixed and span length 2.
    for r in range(n):
        for c in range(n - 2):
            a, b, d = board[r][c], board[r][c+1], board[r][c+2]
            if a in (B, W) and a == d and b == BW:
                # Middle often needed to preserve local non-fragmentation when all orth alternatives are blocked.
                if _must_match_bridge(board, [(r, c), (r, c+2)], (r, c+1), a):
                    if not _assign(board, r, c+1, a):
                        return False
                    changed = True

    for c in range(n):
        for r in range(n - 2):
            a, b, d = board[r][c], board[r+1][c], board[r+2][c]
            if a in (B, W) and a == d and b == BW:
                if _must_match_bridge(board, [(r, c), (r+2, c)], (r+1, c), a):
                    if not _assign(board, r+1, c, a):
                        return False
                    changed = True

    if changed:
        _set_pending_flag(board)
    return True

def _must_match_bridge(board, endpoints, mid, color):
    n = len(board)
    mr, mc = mid
    # Only force if endpoints have very restricted connectivity excluding the middle.
    restricted = 0
    for er, ec in endpoints:
        alt = 0
        for nr, nc in _neighbors(n, er, ec):
            if (nr, nc) == mid:
                continue
            if board[nr][nc] != (W if color == B else B):
                alt += 1
        if alt <= 1:
            restricted += 1
    return restricted == len(endpoints)

def _connectivity_prune(board):
    n = len(board)
    changed = False
    for color in (B, W):
        opp = W if color == B else B

        # Possible graph for this color = all cells not fixed opposite.
        possible = [(r, c) for r in range(n) for c in range(n) if board[r][c] != opp]
        if not possible:
            return False

        fixed = [(r, c) for r in range(n) for c in range(n) if board[r][c] == color]

        # Components in possible graph.
        comp_id = {}
        comps = []
        for cell in possible:
            if cell in comp_id:
                continue
            idx = len(comps)
            comps.append([])
            dq = deque([cell])
            comp_id[cell] = idx
            while dq:
                cr, cc = dq.popleft()
                comps[idx].append((cr, cc))
                for nr, nc in _neighbors(n, cr, cc):
                    if board[nr][nc] != opp and (nr, nc) not in comp_id:
                        comp_id[(nr, nc)] = idx
                        dq.append((nr, nc))

        if fixed:
            root = comp_id[fixed[0]]
            for cell in fixed[1:]:
                if comp_id[cell] != root:
                    return False

            # Any possible component not containing fixed cells cannot be this color.
            fixed_comp = root
            for idx, comp in enumerate(comps):
                if idx == fixed_comp:
                    continue
                for r, c in comp:
                    if board[r][c] == BW:
                        if not _assign(board, r, c, opp):
                            return False
                        changed = True
        else:
            # No fixed cell of this color yet: color must fit somewhere; no pruning here.
            pass

        # Every fixed color cell needs at least one possible same-color route outward unless all fixed color cells already connected cluster >1.
        # The stronger contradiction check is below.
        if fixed:
            # Build graph of possible cells; if removing all unknowns adjacent to a fixed cell would isolate it entirely, impossible.
            for r, c in fixed:
                deg = 0
                for nr, nc in _neighbors(n, r, c):
                    if board[nr][nc] != opp:
                        deg += 1
                if deg == 0:
                    return False

    if changed:
        _set_pending_flag(board)
    return True

def _mandatory_connectors(board):
    n = len(board)
    changed = False
    for color in (B, W):
        opp = W if color == B else B
        fixed = [(r, c) for r in range(n) for c in range(n) if board[r][c] == color]
        if len(fixed) <= 1:
            continue

        possible_cells = {(r, c) for r in range(n) for c in range(n) if board[r][c] != opp}
        root = fixed[0]

        for r in range(n):
            for c in range(n):
                if board[r][c] != BW or (r, c) not in possible_cells:
                    continue

                # If removing this cell disconnects fixed color cells in the possible graph,
                # then it is a mandatory connector and must be this color.
                if _disconnects_fixed(possible_cells, fixed, (r, c), n):
                    if not _assign(board, r, c, color):
                        return False
                    changed = True

    if changed:
        _set_pending_flag(board)
    return True

def _disconnects_fixed(possible_cells, fixed, blocked, n):
    fixed_remaining = [cell for cell in fixed if cell != blocked]
    if not fixed_remaining:
        return False
    start = fixed_remaining[0]
    if start == blocked:
        return False
    seen = {start}
    dq = deque([start])
    while dq:
        r, c = dq.popleft()
        for nr, nc in _neighbors(n, r, c):
            if (nr, nc) == blocked:
                continue
            if (nr, nc) in possible_cells and (nr, nc) not in seen:
                seen.add((nr, nc))
                dq.append((nr, nc))
    for cell in fixed_remaining[1:]:
        if cell not in seen:
            return True
    return False

def _final_feasibility(board):
    n = len(board)

    # No completed 2x2 monochromatic.
    for r in range(n - 1):
        for c in range(n - 1):
            vals = [board[r][c], board[r+1][c], board[r][c+1], board[r+1][c+1]]
            if vals.count(B) == 4 or vals.count(W) == 4:
                return False

    # Possible connectivity for both colors.
    for color in (B, W):
        opp = W if color == B else B
        fixed = [(r, c) for r in range(n) for c in range(n) if board[r][c] == color]
        possible = [(r, c) for r in range(n) for c in range(n) if board[r][c] != opp]
        if fixed and possible:
            seen = set()
            dq = deque([fixed[0]])
            seen.add(fixed[0])
            while dq:
                r, c = dq.popleft()
                for nr, nc in _neighbors(n, r, c):
                    if board[nr][nc] != opp and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        dq.append((nr, nc))
            for cell in fixed[1:]:
                if cell not in seen:
                    return False

    # Unknown cell should remain assignable in principle.
    for r in range(n):
        for c in range(n):
            if board[r][c] != BW:
                continue
            possible_any = False
            for color in (B, W):
                nb = _copy_board(board)
                nb[r][c] = color
                if _quick_local_ok(nb, r, c):
                    possible_any = True
                    break
            if not possible_any:
                return False

    return True

def _quick_local_ok(board, r, c):
    n = len(board)
    # Check only nearby 2x2s and anti-isolation around (r,c)
    for rr in range(max(0, r - 1), min(n - 1, r) + 1):
        for cc in range(max(0, c - 1), min(n - 1, c) + 1):
            vals = [board[rr][cc], board[rr+1][cc], board[rr][cc+1], board[rr+1][cc+1]]
            if vals.count(B) == 4 or vals.count(W) == 4:
                return False
    return True

def _assign(board, r, c, color):
    v = board[r][c]
    if v == color:
        return True
    if v != BW:
        return False
    board[r][c] = color
    _set_pending_flag(board)
    return True

def _neighbors(n, r, c):
    if r > 0:
        yield r - 1, c
    if r + 1 < n:
        yield r + 1, c
    if c > 0:
        yield r, c - 1
    if c + 1 < n:
        yield r, c + 1

def _set_pending_flag(board):
    # Store mutation marker on board object indirectly by attaching a hidden attribute to a wrapper list is not possible.
    # Use a dedicated sentinel row suffix avoided by solver logic.
    if not board or not isinstance(board[-1], list):
        return
    marker = board[-1]
    if marker and marker[-1] not in (B, W, BW):
        marker[-1] = 99

def _drain_pending_flags(board):
    if board and board[-1] and board[-1][-1] not in (B, W, BW):
        board[-1][-1] = BW
        return True
    return False

# Initialize hidden marker slot by replacing final cell temporarily if needed would corrupt puzzle;
# instead, we avoid special storage and patch with an external-safe convention:
# use impossible integer 99 only transiently in bottom-right unknown/fixed position is unsafe.
# So override helpers: keep a global stackless marker dictionary keyed by id(board).
_PENDING = set()

def _set_pending_flag(board):
    _PENDING.add(id(board))

def _drain_pending_flags(board):
    key = id(board)
    if key in _PENDING:
        _PENDING.remove(key)
        return True
    return False

