from collections import defaultdict, deque

def solve(observation):
    data = observation["data"]
    R = len(data)
    C = len(data[0]) if R else 0

    def nbrs(rc):
        r, c = rc
        if r > 0:
            yield (r - 1, c)
        if r + 1 < R:
            yield (r + 1, c)
        if c > 0:
            yield (r, c - 1)
        if c + 1 < C:
            yield (r, c + 1)

    all_cells = [(r, c) for r in range(R) for c in range(C)]
    clue_cells = []
    clue_index_of = {}
    for r in range(R):
        for c in range(C):
            if data[r][c] is not None:
                clue_index_of[(r, c)] = len(clue_cells)
                clue_cells.append(((r, c), data[r][c]))

    if not clue_cells:
        return "No Solution"

    clue_pos = [p for p, _ in clue_cells]
    clue_size = [n for _, n in clue_cells]
    clue_set = set(clue_pos)

    # Precompute cells disallowed for each island:
    # - other clues
    # - cells orthogonally adjacent to other clues
    banned_for = []
    for i, (p, _) in enumerate(clue_cells):
        banned = set()
        for j, q in enumerate(clue_pos):
            if i == j:
                continue
            banned.add(q)
            banned.update(nbrs(q))
        if p in banned:
            banned.remove(p)
        banned_for.append(banned)

    # Generate all connected island shapes for each clue.
    # Human-like abstraction:
    # - islands are connected,
    # - cannot contain or touch another clue,
    # - fixed size.
    def generate_candidates(i):
        root = clue_pos[i]
        target = clue_size[i]
        banned = banned_for[i]
        allowed = set(all_cells) - banned

        if root not in allowed:
            return []

        # Special case size 1
        if target == 1:
            return [frozenset([root])]

        results = set()
        seen = set()

        # Optional distance pruning: cell must be within target-1 steps from root
        allowed2 = set()
        rr, cc = root
        for r, c in allowed:
            if abs(r - rr) + abs(c - cc) <= target - 1:
                allowed2.add((r, c))
        allowed = allowed2

        if root not in allowed:
            return []

        start = frozenset([root])
        start_frontier = frozenset(x for x in nbrs(root) if x in allowed and x not in start)

        def rec(shape, frontier):
            key = (shape, frontier)
            if key in seen:
                return
            seen.add(key)

            if len(shape) == target:
                results.add(shape)
                return

            # Lower bound: need enough reachable cells from current shape/frontier
            needed = target - len(shape)
            if len(frontier) == 0:
                return

            # Simple reachability over allowed cells from current shape
            # to ensure enough cells exist.
            reachable = set(shape)
            q = deque(shape)
            while q:
                u = q.popleft()
                for v in nbrs(u):
                    if v in allowed and v not in reachable:
                        reachable.add(v)
                        q.append(v)
            if len(reachable) < target:
                return

            # Try frontier additions
            # Small human-like preference: expand cells with fewer onward options first
            cand_list = list(frontier)
            cand_list.sort(key=lambda x: sum(1 for y in nbrs(x) if y in allowed and y not in shape))

            for cell in cand_list:
                new_shape = frozenset(set(shape) | {cell})
                new_frontier = set(frontier)
                new_frontier.discard(cell)
                for v in nbrs(cell):
                    if v in allowed and v not in new_shape:
                        new_frontier.add(v)

                # Connectivity-to-completion pruning:
                # maximum possible connected expansion from new_shape must reach target
                # via allowed cells.
                if len(new_shape) < target:
                    vis = set(new_shape)
                    qq = deque(new_shape)
                    while qq:
                        u = qq.popleft()
                        for v in nbrs(u):
                            if v in allowed and v not in vis:
                                vis.add(v)
                                qq.append(v)
                    if len(vis) < target:
                        continue

                rec(new_shape, frozenset(new_frontier))

        rec(start, start_frontier)
        return list(results)

    candidates = [generate_candidates(i) for i in range(len(clue_cells))]
    if any(len(dom) == 0 for dom in candidates):
        return "No Solution"

    # Build incompatibility between candidates of different clues:
    # overlap or orthogonal touching is forbidden.
    touching_cache = {}

    def are_incompatible(a, b):
        key = (a, b) if id(a) < id(b) else (b, a)
        if key in touching_cache:
            return touching_cache[key]
        sa, sb = a, b
        if sa & sb:
            touching_cache[key] = True
            return True
        for cell in sa:
            for v in nbrs(cell):
                if v in sb:
                    touching_cache[key] = True
                    return True
        touching_cache[key] = False
        return False

    # Convert to indexed domains for lighter recursion
    cand_lists = candidates
    domains = [list(range(len(cand_lists[i]))) for i in range(len(cand_lists))]

    incompat = {}
    for i in range(len(clue_cells)):
        for j in range(i + 1, len(clue_cells)):
            bad = defaultdict(set)
            for ai, ca in enumerate(cand_lists[i]):
                for bj, cb in enumerate(cand_lists[j]):
                    if are_incompatible(ca, cb):
                        bad[ai].add(bj)
            incompat[(i, j)] = bad

    # Utility functions for propagation/pruning
    def filter_domains(domains, assigned):
        changed = True
        while changed:
            changed = False
            for i in range(len(domains)):
                if i in assigned:
                    chosen = assigned[i]
                    if domains[i] != [chosen]:
                        domains[i] = [chosen]
                        changed = True

            for i in range(len(domains)):
                if not domains[i]:
                    return None
                for j in range(i + 1, len(domains)):
                    if not domains[j]:
                        return None

                    badmap = incompat[(i, j)]
                    new_di = []
                    dj_set = set(domains[j])
                    for ai in domains[i]:
                        if len(dj_set - badmap.get(ai, set())) > 0:
                            new_di.append(ai)
                    if len(new_di) != len(domains[i]):
                        domains[i] = new_di
                        changed = True
                    if not domains[i]:
                        return None

                    new_dj = []
                    di_set = set(domains[i])
                    rev_needed = True
                    if rev_needed:
                        for bj in domains[j]:
                            ok = False
                            for ai in domains[i]:
                                if bj not in badmap.get(ai, set()):
                                    ok = True
                                    break
                            if ok:
                                new_dj.append(bj)
                    if len(new_dj) != len(domains[j]):
                        domains[j] = new_dj
                        changed = True
                    if not domains[j]:
                        return None
        return domains

    def possible_white_cells(domains):
        s = set()
        for i, dom in enumerate(domains):
            for k in dom:
                s |= cand_lists[i][k]
        return s

    def forced_white_cells(domains):
        fw = set()
        for i, dom in enumerate(domains):
            inter = None
            for k in dom:
                cs = cand_lists[i][k]
                inter = set(cs) if inter is None else (inter & cs)
                if not inter:
                    break
            if inter:
                fw |= inter
        return fw

    def partial_prune(domains):
        # Cells impossible to be white become forced black
        pwhite = possible_white_cells(domains)
        fwhite = forced_white_cells(domains)
        fblack = set(all_cells) - pwhite

        # White and black contradiction
        if fwhite & fblack:
            return False

        # No 2x2 all forced black
        for r in range(R - 1):
            for c in range(C - 1):
                block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
                if block <= fblack:
                    return False

        # Forced black cells must remain connectable through cells not forced white
        if fblack:
            allowed_black_graph = set(all_cells) - fwhite
            start = next(iter(fblack))
            vis = {start}
            dq = deque([start])
            while dq:
                u = dq.popleft()
                for v in nbrs(u):
                    if v in allowed_black_graph and v not in vis:
                        vis.add(v)
                        dq.append(v)
            if not fblack <= vis:
                return False

        # Each clue's remaining candidates should still have at least one cell set
        # and every clue cell stays inside every candidate by construction.
        return True

    def final_check(chosen_sets):
        white = set()
        for s in chosen_sets:
            white |= s
        black = set(all_cells) - white

        # No 2x2 black
        for r in range(R - 1):
            for c in range(C - 1):
                if {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)} <= black:
                    return False

        # Black connected
        if black:
            start = next(iter(black))
            vis = {start}
            dq = deque([start])
            while dq:
                u = dq.popleft()
                for v in nbrs(u):
                    if v in black and v not in vis:
                        vis.add(v)
                        dq.append(v)
            if vis != black:
                return False

        # White islands exactly the chosen candidates, one clue each
        # Since candidates are pairwise disjoint and non-touching, this is guaranteed,
        # but verify connectivity and clue count defensively.
        seen = set()
        for cell in white:
            if cell in seen:
                continue
            comp = set()
            dq = deque([cell])
            seen.add(cell)
            while dq:
                u = dq.popleft()
                comp.add(u)
                for v in nbrs(u):
                    if v in white and v not in seen:
                        seen.add(v)
                        dq.append(v)
            clues_in = [p for p in clue_set if p in comp]
            if len(clues_in) != 1:
                return False
            size = data[clues_in[0][0]][clues_in[0][1]]
            if len(comp) != size:
                return False

        return True

    # Initial propagation
    domains = filter_domains([d[:] for d in domains], {})
    if domains is None or not partial_prune(domains):
        return "No Solution"

    def choose_var(domains):
        best = None
        best_key = None
        for i, dom in enumerate(domains):
            if len(dom) > 1:
                # heuristic: smallest domain, then smaller average island size
                key = (len(dom), clue_size[i])
                if best is None or key < best_key:
                    best = i
                    best_key = key
        return best

    def search(domains, assigned):
        domains = filter_domains([d[:] for d in domains], dict(assigned))
        if domains is None:
            return None
        if not partial_prune(domains):
            return None

        var = choose_var(domains)
        if var is None:
            chosen_sets = [cand_lists[i][domains[i][0]] for i in range(len(domains))]
            if final_check(chosen_sets):
                ans = [[None for _ in range(C)] for _ in range(R)]
                white = set()
                for s in chosen_sets:
                    white |= s
                for r in range(R):
                    for c in range(C):
                        if (r, c) not in white:
                            ans[r][c] = 'B'
                return ans
            return None

        # Value ordering: prefer candidates that force more cells / reduce ambiguity
        dom = domains[var][:]
        dom.sort(key=lambda k: (-len(cand_lists[var][k]), k))
        for k in dom:
            new_assigned = dict(assigned)
            new_assigned[var] = k
            res = search(domains, new_assigned)
            if res is not None:
                return res
        return None

    result = search(domains, {})
    return repr(result) if result is not None else "No Solution"


