# Generalized Futoshiki solver using strong propagation + guided search.
# Vertical symbols are interpreted as:
#   '^' : top < bottom
#   'v' : top > bottom

def solve(observation):
    data = observation['data']
    n = len(data)
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def values_from_mask(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    def mask_le(k):
        if k <= 0:
            return 0
        if k >= n:
            return full
        return (1 << k) - 1

    def mask_ge(k):
        if k <= 1:
            return full
        if k > n:
            return 0
        return full ^ ((1 << (k - 1)) - 1)

    # Parse inequalities into normalized relations a < b.
    less_edges = []

    for key, sym in observation.get('horizontal', {}).items():
        row_s, col_s = key.strip('()').split(',')
        r = int(float(row_s))
        c_left = int(float(col_s) - 0.5)
        a = (r, c_left)
        b = (r, c_left + 1)
        if sym == '<':
            less_edges.append((a, b))
        elif sym == '>':
            less_edges.append((b, a))

    for key, sym in observation.get('vertical', {}).items():
        row_s, col_s = key.strip('()').split(',')
        r_top = int(float(row_s) - 0.5)
        c = int(float(col_s))
        top = (r_top, c)
        bot = (r_top + 1, c)
        if sym == '^':
            less_edges.append((top, bot))
        elif sym == 'v':
            less_edges.append((bot, top))

    row_cells = [[(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[(r, c) for r in range(n)] for c in range(n)]

    # Neighbors for degree / heuristic purposes
    neighbors = [[set() for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c1 in range(n):
            for c2 in range(n):
                if c1 != c2:
                    neighbors[r][c1].add((r, c2))
    for c in range(n):
        for r1 in range(n):
            for r2 in range(n):
                if r1 != r2:
                    neighbors[r1][c].add((r2, c))
    for a, b in less_edges:
        neighbors[a[0]][a[1]].add(b)
        neighbors[b[0]][b[1]].add(a)

    initial_domains = [[full for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                v = data[r][c]
                if not (1 <= v <= n):
                    return "No Solution"
                initial_domains[r][c] = bit(v)

    def clone_domains(domains):
        return [row[:] for row in domains]

    def apply_naked_subsets(unit, domains):
        changed = False
        counts = {}
        for r, c in unit:
            m = domains[r][c]
            pc = popcount(m)
            if 2 <= pc <= 4:
                counts.setdefault(m, []).append((r, c))
        for m, cells in counts.items():
            k = popcount(m)
            if len(cells) == k:
                for r, c in unit:
                    if (r, c) not in cells:
                        nm = domains[r][c] & ~m
                        if nm != domains[r][c]:
                            if nm == 0:
                                return None
                            domains[r][c] = nm
                            changed = True
        return changed

    def propagate(domains):
        while True:
            changed = False

            # Row/column used-value pruning and duplicate checks for fixed cells.
            row_fixed = [0] * n
            col_fixed = [0] * n

            for r in range(n):
                seen = 0
                for c in range(n):
                    m = domains[r][c]
                    if m == 0:
                        return None
                    if m & (m - 1) == 0:
                        if seen & m:
                            return None
                        seen |= m
                row_fixed[r] = seen

            for c in range(n):
                seen = 0
                for r in range(n):
                    m = domains[r][c]
                    if m & (m - 1) == 0:
                        if seen & m:
                            return None
                        seen |= m
                col_fixed[c] = seen

            for r in range(n):
                used = row_fixed[r]
                for c in range(n):
                    m = domains[r][c]
                    if m & (m - 1):
                        nm = m & ~used
                        if nm == 0:
                            return None
                        if nm != m:
                            domains[r][c] = nm
                            changed = True

            for c in range(n):
                used = col_fixed[c]
                for r in range(n):
                    m = domains[r][c]
                    if m & (m - 1):
                        nm = m & ~col_fixed[c]
                        if nm == 0:
                            return None
                        if nm != m:
                            domains[r][c] = nm
                            changed = True

            # Inequality propagation: if A < B then
            #   A <= max(B)-1
            #   B >= min(A)+1
            for (ar, ac), (br, bc) in less_edges:
                ma = domains[ar][ac]
                mb = domains[br][bc]

                max_b = max_val(mb)
                nm_a = ma & mask_le(max_b - 1)
                if nm_a == 0:
                    return None
                if nm_a != ma:
                    domains[ar][ac] = nm_a
                    ma = nm_a
                    changed = True

                min_a = min_val(ma)
                nm_b = mb & mask_ge(min_a + 1)
                if nm_b == 0:
                    return None
                if nm_b != mb:
                    domains[br][bc] = nm_b
                    changed = True

                # Re-tighten after B changed.
                max_b = max_val(nm_b)
                nm_a2 = nm_a & mask_le(max_b - 1)
                if nm_a2 == 0:
                    return None
                if nm_a2 != nm_a:
                    domains[ar][ac] = nm_a2
                    changed = True

            # Hidden singles in rows.
            for r in range(n):
                positions = [0] * (n + 1)
                counts = [0] * (n + 1)
                for c in range(n):
                    m = domains[r][c]
                    mm = m
                    while mm:
                        b = mm & -mm
                        v = b.bit_length()
                        counts[v] += 1
                        positions[v] = c
                        mm ^= b
                for v in range(1, n + 1):
                    if counts[v] == 0:
                        return None
                    if counts[v] == 1:
                        c = positions[v]
                        m = domains[r][c]
                        bv = bit(v)
                        if m != bv:
                            if not (m & bv):
                                return None
                            domains[r][c] = bv
                            changed = True

            # Hidden singles in columns.
            for c in range(n):
                positions = [0] * (n + 1)
                counts = [0] * (n + 1)
                for r in range(n):
                    m = domains[r][c]
                    mm = m
                    while mm:
                        b = mm & -mm
                        v = b.bit_length()
                        counts[v] += 1
                        positions[v] = r
                        mm ^= b
                for v in range(1, n + 1):
                    if counts[v] == 0:
                        return None
                    if counts[v] == 1:
                        r = positions[v]
                        m = domains[r][c]
                        bv = bit(v)
                        if m != bv:
                            if not (m & bv):
                                return None
                            domains[r][c] = bv
                            changed = True

            # Human-like subset eliminations.
            for r in range(n):
                res = apply_naked_subsets(row_cells[r], domains)
                if res is None:
                    return None
                changed |= res

            for c in range(n):
                res = apply_naked_subsets(col_cells[c], domains)
                if res is None:
                    return None
                changed |= res

            # Final contradiction checks on row/col support.
            for r in range(n):
                support = 0
                for c in range(n):
                    support |= domains[r][c]
                if support != full:
                    return None

            for c in range(n):
                support = 0
                for r in range(n):
                    support |= domains[r][c]
                if support != full:
                    return None

            if not changed:
                return domains

    def solved(domains):
        for r in range(n):
            for c in range(n):
                if domains[r][c] & (domains[r][c] - 1):
                    return False
        return True

    def select_cell(domains):
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                m = domains[r][c]
                pc = popcount(m)
                if pc > 1:
                    deg = len(neighbors[r][c])
                    key = (pc, -deg)
                    if best is None or key < best_key:
                        best = (r, c)
                        best_key = key
        return best

    def order_values(domains, r, c):
        # Least-constraining-value ordering.
        vals = []
        for v in values_from_mask(domains[r][c]):
            score = 0
            bv = bit(v)

            # Row/column impact.
            for cc in range(n):
                if cc != c and (domains[r][cc] & bv):
                    score += 1
            for rr in range(n):
                if rr != r and (domains[rr][c] & bv):
                    score += 1

            # Inequality impact.
            for (ar, ac), (br, bc) in less_edges:
                if (ar, ac) == (r, c):
                    mb = domains[br][bc]
                    score += popcount(mb & mask_le(v))
                elif (br, bc) == (r, c):
                    ma = domains[ar][ac]
                    score += popcount(ma & mask_ge(v))

            vals.append((score, v))
        vals.sort()
        return [v for _, v in vals]

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if solved(domains):
            return domains

        r, c = select_cell(domains)
        for v in order_values(domains, r, c):
            new_domains = clone_domains(domains)
            new_domains[r][c] = bit(v)
            result = search(new_domains)
            if result is not None:
                return result
        return None

    result = search(initial_domains)
    if result is None:
        return "No Solution"

    solved_grid = [[min_val(result[r][c]) for c in range(n)] for r in range(n)]
    return str(solved_grid)


