from itertools import permutations

# Consecutive-dot Latin puzzle solver using strong line-based propagation.
# Each row/column is treated as a permutation constraint filtered by:
# - current cell domains
# - consecutive / non-consecutive adjacency relations along that line
# This mirrors human deduction on rows and columns before any search.

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    all_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def is_single(mask):
        return mask and (mask & (mask - 1)) == 0

    def mask_to_value(mask):
        return mask.bit_length()

    def values_from_mask(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length()
            mask ^= lsb

    def consecutive(a, b):
        return abs(a - b) == 1

    # Parse dotted adjacencies.
    dots = set()
    for rc in observation['adjacent']:
        r, c = rc
        dots.add((float(r), float(c)))

    # For every row/column adjacency, a missing dot means NOT consecutive.
    row_rels = []
    for r in range(n):
        rel = []
        for c in range(n - 1):
            rel.append((float(r), float(c) + 0.5) in dots)
        row_rels.append(tuple(rel))

    col_rels = []
    for c in range(n):
        rel = []
        for r in range(n - 1):
            rel.append((float(r) + 0.5, float(c)) in dots)
        col_rels.append(tuple(rel))

    # Initial domains.
    domains = [[all_mask for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                domains[r][c] = bit(v)

    # Precompute all permutations once.
    perms = list(permutations(range(1, n + 1)))

    # Cache filtered line results by (domains_tuple, rels_tuple).
    line_cache = {}

    def filter_line(line_masks, rels):
        key = (tuple(line_masks), tuple(rels))
        if key in line_cache:
            return line_cache[key]

        viable = []
        for p in perms:
            ok = True
            for i, v in enumerate(p):
                if not (line_masks[i] & bit(v)):
                    ok = False
                    break
            if ok:
                for i, need_consec in enumerate(rels):
                    if consecutive(p[i], p[i + 1]) != need_consec:
                        ok = False
                        break
            if ok:
                viable.append(p)

        if not viable:
            line_cache[key] = None
            return None

        pos_masks = [0] * n
        digit_positions = [0] * (n + 1)
        for p in viable:
            for i, v in enumerate(p):
                pos_masks[i] |= bit(v)
                digit_positions[v] |= (1 << i)

        # Hidden singles within the line:
        # if a digit appears in only one position across all viable permutations,
        # that position must take that digit.
        for v in range(1, n + 1):
            pos_bits = digit_positions[v]
            if pos_bits and (pos_bits & (pos_bits - 1)) == 0:
                idx = pos_bits.bit_length() - 1
                pos_masks[idx] &= bit(v)

        line_cache[key] = pos_masks
        return pos_masks

    def propagate(dom):
        dom = [row[:] for row in dom]
        changed = True
        while changed:
            changed = False

            # Row propagation
            for r in range(n):
                line = dom[r]
                filtered = filter_line(line, row_rels[r])
                if filtered is None:
                    return None
                for c in range(n):
                    new_mask = dom[r][c] & filtered[c]
                    if new_mask == 0:
                        return None
                    if new_mask != dom[r][c]:
                        dom[r][c] = new_mask
                        changed = True

            # Column propagation
            for c in range(n):
                line = [dom[r][c] for r in range(n)]
                filtered = filter_line(line, col_rels[c])
                if filtered is None:
                    return None
                for r in range(n):
                    new_mask = dom[r][c] & filtered[r]
                    if new_mask == 0:
                        return None
                    if new_mask != dom[r][c]:
                        dom[r][c] = new_mask
                        changed = True

        return dom

    def solved(dom):
        return all(is_single(dom[r][c]) for r in range(n) for c in range(n))

    def extract_grid(dom):
        return [[mask_to_value(dom[r][c]) for c in range(n)] for r in range(n)]

    def choose_cell(dom):
        best = None
        best_count = n + 1
        for r in range(n):
            for c in range(n):
                m = dom[r][c]
                pc = m.bit_count()
                if 1 < pc < best_count:
                    best_count = pc
                    best = (r, c)
        return best

    def search(dom):
        dom = propagate(dom)
        if dom is None:
            return None
        if solved(dom):
            return dom

        r, c = choose_cell(dom)
        mask = dom[r][c]

        # Value ordering: try values that are currently possible, low to high.
        for v in values_from_mask(mask):
            new_dom = [row[:] for row in dom]
            new_dom[r][c] = bit(v)
            ans = search(new_dom)
            if ans is not None:
                return ans
        return None

    result = search(domains)
    if result is None:
        return "No Solution"
    return str(extract_grid(result))


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 2, 2], [0, 3, 1, 1, 4, 4], [3, 3, 1, 1, 5, 4], [6, 6, 5, 5, 5, 4], [6, 7, 8, 8, 5, 5], [7, 7, 9, 9, 9, 9]], 'row_water_counts': [4, 2, 2, 5, 5, 4], 'col_water_counts': [5, 4, 3, 3, 4, 3]}

from collections import defaultdict

def solve(observation):
    region_grid = observation["region"]
    row_targets = observation["row_water_counts"]
    col_targets = observation["col_water_counts"]

    R = len(region_grid)
    C = len(region_grid[0]) if R else 0

    # Collect region cells
    region_cells = defaultdict(list)
    for r in range(R):
        for c in range(C):
            region_cells[region_grid[r][c]].append((r, c))

    region_ids = sorted(region_cells)
    rid_to_idx = {rid: i for i, rid in enumerate(region_ids)}
    n_regions = len(region_ids)

    # Enumerate legal options for each region:
    # choose an absolute waterline, filling every cell in the region with row >= waterline.
    options = []
    option_water_sets = []
    region_rows = []
    cell_region = {}
    for rid in region_ids:
        cells = region_cells[rid]
        for cell in cells:
            cell_region[cell] = rid_to_idx[rid]
        rows = sorted({r for r, _ in cells})
        region_rows.append(rows)
        seen = set()
        reg_opts = []

        # Empty option
        ws = frozenset()
        seen.add(ws)
        reg_opts.append(ws)

        # One option per distinct row cutoff
        for cutoff in rows:
            w = frozenset((r, c) for (r, c) in cells if r >= cutoff)
            if w not in seen:
                seen.add(w)
                reg_opts.append(w)

        # Sort options by water amount for stability / human-like low-to-high levels
        reg_opts.sort(key=lambda s: (len(s), sorted(s)))
        options.append(reg_opts)
        option_water_sets.append([set(x) for x in reg_opts])

    # Precompute row/col contributions for every region option
    row_contrib = []
    col_contrib = []
    for i in range(n_regions):
        rc = []
        cc = []
        for wset in option_water_sets[i]:
            row_count = [0] * R
            col_count = [0] * C
            for r, c in wset:
                row_count[r] += 1
                col_count[c] += 1
            rc.append(row_count)
            cc.append(col_count)
        row_contrib.append(rc)
        col_contrib.append(cc)

    # Cells per line
    row_cells = [[(r, c) for c in range(C)] for r in range(R)]
    col_cells = [[(r, c) for r in range(R)] for c in range(C)]

    # Regions touching each row/col
    row_regions = [[] for _ in range(R)]
    col_regions = [[] for _ in range(C)]
    for i, rid in enumerate(region_ids):
        touched_rows = sorted({r for r, _ in region_cells[rid]})
        touched_cols = sorted({c for _, c in region_cells[rid]})
        for r in touched_rows:
            row_regions[r].append(i)
        for c in touched_cols:
            col_regions[c].append(i)

    full_masks = [(1 << len(options[i])) - 1 for i in range(n_regions)]

    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def cell_status(domains, cell):
        i = cell_region[cell]
        water_any = False
        land_any = False
        for oi in iter_bits(domains[i]):
            if cell in option_water_sets[i][oi]:
                water_any = True
            else:
                land_any = True
            if water_any and land_any:
                return None
        if water_any:
            return True
        return False

    def force_cell(domains, cell, want_water):
        i = cell_region[cell]
        old = domains[i]
        new = 0
        for oi in iter_bits(old):
            is_water = cell in option_water_sets[i][oi]
            if is_water == want_water:
                new |= 1 << oi
        if new == 0:
            return None
        changed = new != old
        domains[i] = new
        return changed

    def line_feasible_and_prune(domains, target, region_list, contrib_table, line_idx):
        # Exact-sum DP on region contributions; prune options that cannot participate in any exact line sum.
        contrib_lists = []
        for i in region_list:
            vals = {}
            for oi in iter_bits(domains[i]):
                v = contrib_table[i][oi][line_idx]
                vals.setdefault(v, 0)
                vals[v] |= (1 << oi)
            contrib_lists.append((i, vals))

        # Prefix reachable sums
        pref = [set() for _ in range(len(contrib_lists) + 1)]
        pref[0].add(0)
        for k, (_, vals) in enumerate(contrib_lists, 1):
            out = pref[k]
            for s in pref[k - 1]:
                for v in vals:
                    nv = s + v
                    if nv <= target:
                        out.add(nv)

        if target not in pref[-1]:
            return None

        # Suffix reachable sums
        suff = [set() for _ in range(len(contrib_lists) + 1)]
        suff[len(contrib_lists)].add(0)
        for k in range(len(contrib_lists) - 1, -1, -1):
            _, vals = contrib_lists[k]
            out = suff[k]
            for s in suff[k + 1]:
                for v in vals:
                    nv = s + v
                    if nv <= target:
                        out.add(nv)

        changed = False
        for k, (i, vals) in enumerate(contrib_lists):
            old = domains[i]
            keep = 0
            before = pref[k]
            after = suff[k + 1]
            for v, omask in vals.items():
                ok = False
                for s in before:
                    rem = target - s - v
                    if rem in after:
                        ok = True
                        break
                if ok:
                    keep |= omask
            new = old & keep
            if new == 0:
                return None
            if new != old:
                domains[i] = new
                changed = True
        return changed

    def propagate(domains):
        while True:
            any_change = False

            # Basic line bounds + exact-sum pruning
            for r in range(R):
                fixed = 0
                possible = 0
                for cell in row_cells[r]:
                    st = cell_status(domains, cell)
                    if st is True:
                        fixed += 1
                        possible += 1
                    elif st is None:
                        possible += 1
                if fixed > row_targets[r] or possible < row_targets[r]:
                    return None

                res = line_feasible_and_prune(domains, row_targets[r], row_regions[r], row_contrib, r)
                if res is None:
                    return None
                any_change |= res

            for c in range(C):
                fixed = 0
                possible = 0
                for cell in col_cells[c]:
                    st = cell_status(domains, cell)
                    if st is True:
                        fixed += 1
                        possible += 1
                    elif st is None:
                        possible += 1
                if fixed > col_targets[c] or possible < col_targets[c]:
                    return None

                res = line_feasible_and_prune(domains, col_targets[c], col_regions[c], col_contrib, c)
                if res is None:
                    return None
                any_change |= res

            # Human-style forced cells from line saturation
            for r in range(R):
                fixed = []
                undec = []
                for cell in row_cells[r]:
                    st = cell_status(domains, cell)
                    if st is True:
                        fixed.append(cell)
                    elif st is None:
                        undec.append(cell)
                need = row_targets[r] - len(fixed)
                if need < 0 or need > len(undec):
                    return None
                if need == 0:
                    for cell in undec:
                        res = force_cell(domains, cell, False)
                        if res is None:
                            return None
                        any_change |= res
                elif need == len(undec):
                    for cell in undec:
                        res = force_cell(domains, cell, True)
                        if res is None:
                            return None
                        any_change |= res

            for c in range(C):
                fixed = []
                undec = []
                for cell in col_cells[c]:
                    st = cell_status(domains, cell)
                    if st is True:
                        fixed.append(cell)
                    elif st is None:
                        undec.append(cell)
                need = col_targets[c] - len(fixed)
                if need < 0 or need > len(undec):
                    return None
                if need == 0:
                    for cell in undec:
                        res = force_cell(domains, cell, False)
                        if res is None:
                            return None
                        any_change |= res
                elif need == len(undec):
                    for cell in undec:
                        res = force_cell(domains, cell, True)
                        if res is None:
                            return None
                        any_change |= res

            # Region internal monotonicity is already encoded by option domains.
            # Re-check nonempty domains.
            for i in range(n_regions):
                if domains[i] == 0:
                    return None

            if not any_change:
                return domains

    def is_solved(domains):
        return all(mask and (mask & (mask - 1) == 0) for mask in domains)

    def choose_branch_region(domains):
        # Branch on the most constrained region (fewest options > 1), tie-break by total cells.
        best = None
        for i in range(n_regions):
            cnt = domains[i].bit_count()
            if cnt > 1:
                key = (cnt, len(region_cells[region_ids[i]]))
                if best is None or key < best[0]:
                    best = (key, i)
        return None if best is None else best[1]

    def dfs(domains):
        domains = domains[:]
        domains = propagate(domains)
        if domains is None:
            return None
        if is_solved(domains):
            return domains

        i = choose_branch_region(domains)
        if i is None:
            return None

        # Try options in a human-like order: extremes first often trigger stronger deductions.
        opts = list(iter_bits(domains[i]))
        opts.sort(key=lambda oi: (abs(len(option_water_sets[i][oi]) - len(region_cells[region_ids[i]]) / 2), len(option_water_sets[i][oi])))

        for oi in opts:
            new_domains = domains[:]
            new_domains[i] = 1 << oi
            ans = dfs(new_domains)
            if ans is not None:
                return ans
        return None

    final_domains = dfs(full_masks[:])
    if final_domains is None:
        return "No Solution"

    answer = [[None for _ in range(C)] for _ in range(R)]
    for i in range(n_regions):
        oi = next(iter_bits(final_domains[i]))
        wset = option_water_sets[i][oi]
        for r, c in region_cells[region_ids[i]]:
            answer[r][c] = 'W' if (r, c) in wset else None
    return str(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

