# Kuromasu solver with strong propagation and limited search.
# Cell states: -1 unknown, 0 white, 1 black.

from collections import deque

DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def solve(observation):
    data = observation["data"]
    n = len(data)

    clues = []
    clue_set = set()
    state = [[-1] * n for _ in range(n)]

    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                clues.append((r, c, data[r][c]))
                clue_set.add((r, c))
                state[r][c] = 0

    # Precompute runs from each clue in 4 directions.
    clue_runs = {}
    cell_to_clues = [[[] for _ in range(n)] for _ in range(n)]
    for r, c, v in clues:
        runs = []
        for dr, dc in DIRS:
            run = []
            rr, cc = r + dr, c + dc
            while 0 <= rr < n and 0 <= cc < n:
                run.append((rr, cc))
                cell_to_clues[rr][cc].append((r, c))
                rr += dr
                cc += dc
            runs.append(run)
        clue_runs[(r, c)] = runs

    # Immediate static sanity on clue sizes.
    for r, c, v in clues:
        max_vis = 1 + sum(len(run) for run in clue_runs[(r, c)])
        if not (1 <= v <= max_vis):
            return "No Solution"

    def clone(st):
        return [row[:] for row in st]

    def set_white(st, r, c, forced_queue=None):
        if st[r][c] == 1:
            return False
        if st[r][c] == 0:
            return True
        st[r][c] = 0
        if forced_queue is not None:
            forced_queue.append((r, c))
        return True

    def set_black(st, r, c, forced_queue=None):
        if (r, c) in clue_set:
            return False
        if st[r][c] == 0:
            return False
        if st[r][c] == 1:
            return True
        # No orthogonal touching black cells.
        for dr, dc in DIRS:
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < n and st[rr][cc] == 1:
                return False
        st[r][c] = 1
        if forced_queue is not None:
            forced_queue.append((r, c))
        return True

    def feasible_k_for_run(run, st):
        # k = number of visible cells in this direction.
        # Conditions:
        # - first k cells are white (thus not black)
        # - if k < len(run), run[k] is black
        # - later cells unrestricted
        L = len(run)
        vals = []
        for k in range(L + 1):
            ok = True
            for i in range(k):
                r, c = run[i]
                if st[r][c] == 1:
                    ok = False
                    break
            if not ok:
                continue
            if k < L:
                r, c = run[k]
                if st[r][c] == 0:
                    continue
            vals.append(k)
        return vals

    def clue_patterns(st, rc):
        r, c = rc
        target = data[r][c] - 1
        runs = clue_runs[rc]
        options = [feasible_k_for_run(run, st) for run in runs]
        if any(len(x) == 0 for x in options):
            return None

        res = []
        # Small fixed branching (4 directions), so explicit nested generation is efficient.
        a0, a1, a2, a3 = options
        min1, max1 = (min(a1), max(a1))
        min2, max2 = (min(a2), max(a2))
        min3, max3 = (min(a3), max(a3))
        for k0 in a0:
            rem0 = target - k0
            if rem0 < min1 + min2 + min3 or rem0 > max1 + max2 + max3:
                continue
            for k1 in a1:
                rem1 = rem0 - k1
                if rem1 < min2 + min3 or rem1 > max2 + max3:
                    continue
                for k2 in a2:
                    k3 = rem1 - k2
                    if k3 in a3:
                        res.append((k0, k1, k2, k3))
        return res

    def apply_clue_deductions(st, rc, pats, forced_queue):
        runs = clue_runs[rc]
        changed = False
        # Deduce per direction and per position.
        for d in range(4):
            run = runs[d]
            L = len(run)
            for i in range(L):
                vis_all = True
                blk_all = True
                for ks in pats:
                    k = ks[d]
                    if not (i < k):
                        vis_all = False
                    if not (k < L and i == k):
                        blk_all = False
                    if not vis_all and not blk_all:
                        break
                r, c = run[i]
                if vis_all:
                    if st[r][c] == -1:
                        if not set_white(st, r, c, forced_queue):
                            return None
                        changed = True
                elif blk_all:
                    if st[r][c] == -1:
                        if not set_black(st, r, c, forced_queue):
                            return None
                        changed = True
        return changed

    def connectivity_contradiction(st):
        whites = [(r, c) for r in range(n) for c in range(n) if st[r][c] == 0]
        if not whites:
            return False
        passable = {(r, c) for r in range(n) for c in range(n) if st[r][c] != 1}
        start = whites[0]
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                if (rr, cc) in passable and (rr, cc) not in seen:
                    seen.add((rr, cc))
                    q.append((rr, cc))
        # If fixed whites are split even through unknowns, impossible.
        for cell in whites:
            if cell not in seen:
                return True
        return False

    def force_connectivity_cells(st, forced_queue):
        # If removing an unknown cell splits currently white cells in the graph of non-black cells,
        # that cell must be white.
        whites = [(r, c) for r in range(n) for c in range(n) if st[r][c] == 0]
        if len(whites) <= 1:
            return False
        passable = [(r, c) for r in range(n) for c in range(n) if st[r][c] != 1]
        passable_set = set(passable)
        changed = False

        for r, c in passable:
            if st[r][c] != -1:
                continue
            remaining_whites = [w for w in whites if w != (r, c)]
            if len(remaining_whites) <= 1:
                continue
            start = remaining_whites[0]
            q = deque([start])
            seen = {start}
            while q:
                rr, cc = q.popleft()
                for dr, dc in DIRS:
                    nr, nc = rr + dr, cc + dc
                    if (nr, nc) == (r, c):
                        continue
                    if (nr, nc) in passable_set and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            bad = False
            for w in remaining_whites:
                if w not in seen:
                    bad = True
                    break
            if bad:
                if not set_white(st, r, c, forced_queue):
                    return None
                changed = True
        return changed

    def propagate(st):
        forced_queue = deque()

        # Initial closure from current assignments.
        for r in range(n):
            for c in range(n):
                if st[r][c] != -1:
                    forced_queue.append((r, c))

        while True:
            progressed = False

            # Local consequences of black cells: neighbors white.
            while forced_queue:
                r, c = forced_queue.popleft()
                if st[r][c] == 1:
                    for dr, dc in DIRS:
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < n and 0 <= cc < n:
                            if st[rr][cc] == 1:
                                return None
                            if st[rr][cc] == -1:
                                if not set_white(st, rr, cc, forced_queue):
                                    return None
                                progressed = True

            # Clue-based propagation.
            for r, c, _ in clues:
                pats = clue_patterns(st, (r, c))
                if not pats:
                    return None
                ch = apply_clue_deductions(st, (r, c), pats, forced_queue)
                if ch is None:
                    return None
                if ch:
                    progressed = True

            # Global connectivity checks.
            if connectivity_contradiction(st):
                return None

            ch = force_connectivity_cells(st, forced_queue)
            if ch is None:
                return None
            if ch:
                progressed = True

            if not progressed and not forced_queue:
                break

        # Final consistency checks on fully assigned neighborhoods and clue feasibility.
        for r in range(n):
            for c in range(n):
                if st[r][c] == 1:
                    for dr, dc in DIRS:
                        rr, cc = r + dr, c + dc
                        if 0 <= rr < n and 0 <= cc < n and st[rr][cc] == 1:
                            return None
        for r, c, _ in clues:
            pats = clue_patterns(st, (r, c))
            if not pats:
                return None

        return st

    def is_solved(st):
        for r in range(n):
            for c in range(n):
                if st[r][c] == -1:
                    return False
        # All whites connected.
        whites = [(r, c) for r in range(n) for c in range(n) if st[r][c] == 0]
        if whites:
            q = deque([whites[0]])
            seen = {whites[0]}
            while q:
                r, c = q.popleft()
                for dr, dc in DIRS:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n and st[rr][cc] == 0 and (rr, cc) not in seen:
                        seen.add((rr, cc))
                        q.append((rr, cc))
            if len(seen) != len(whites):
                return False
        # Exact clue validation.
        for r, c, v in clues:
            cnt = 1
            for dr, dc in DIRS:
                rr, cc = r + dr, c + dc
                while 0 <= rr < n and 0 <= cc < n and st[rr][cc] == 0:
                    cnt += 1
                    rr += dr
                    cc += dc
            if cnt != v:
                return False
        return True

    def choose_branch_cell(st):
        # Heuristic 1: unknown cell appearing in many clue lines and with constrained clue patterns nearby.
        best = None
        best_score = None

        clue_pat_cache = {}
        for r, c, _ in clues:
            clue_pat_cache[(r, c)] = clue_patterns(st, (r, c))

        for r in range(n):
            for c in range(n):
                if st[r][c] != -1:
                    continue
                score = 0
                related = cell_to_clues[r][c]
                score += 10 * len(related)
                for rc in related:
                    pats = clue_pat_cache[rc]
                    if pats:
                        score += 20 - min(20, len(pats))
                # Prefer cells next to black-forbidden zones as they propagate more.
                for dr, dc in DIRS:
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n:
                        if st[rr][cc] == 1:
                            score += 8
                        elif st[rr][cc] == 0:
                            score += 1
                if best is None or score > best_score:
                    best = (r, c)
                    best_score = score
        return best

    def search(st):
        st = propagate(st)
        if st is None:
            return None
        if is_solved(st):
            return st

        cell = choose_branch_cell(st)
        if cell is None:
            return None
        r, c = cell

        # Try black first when legal; often sharper due to adjacency and clue stopping.
        for val in (1, 0):
            nxt = clone(st)
            ok = set_black(nxt, r, c) if val == 1 else set_white(nxt, r, c)
            if not ok:
                continue
            ans = search(nxt)
            if ans is not None:
                return ans
        return None

    ans = search(state)
    if ans is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(n):
            if data[r][c] is not None:
                row.append(data[r][c])
            elif ans[r][c] == 1:
                row.append('B')
            else:
                row.append(None)
        out.append(row)
    return repr(out)


