from collections import defaultdict

def solve(observation):
    region_grid = observation["region"]
    row_target = observation["row_water_counts"]
    col_target = observation["col_water_counts"]

    n = len(region_grid)
    m = len(region_grid[0]) if n else 0

    # Build region -> cells
    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[region_grid[r][c]].append((r, c))

    region_ids = sorted(regions)
    ridx = {rid: i for i, rid in enumerate(region_ids)}
    R = len(region_ids)

    # For each region, enumerate all legal "water levels":
    # choose threshold t from unique row indices in region plus one above all rows.
    # Water cells are exactly those region cells with row >= t.
    region_options = []
    option_row_add = []
    option_col_add = []

    for rid in region_ids:
        cells = regions[rid]
        rows = sorted({r for r, _ in cells})
        thresholds = rows + [max(rows) + 1]
        seen = set()
        opts = []
        rowadds = []
        coladds = []
        for t in thresholds:
            water = tuple(sorted((r, c) for r, c in cells if r >= t))
            if water in seen:
                continue
            seen.add(water)
            opts.append(water)
            ra = [0] * n
            ca = [0] * m
            for r, c in water:
                ra[r] += 1
                ca[c] += 1
            rowadds.append(tuple(ra))
            coladds.append(tuple(ca))
        region_options.append(opts)
        option_row_add.append(rowadds)
        option_col_add.append(coladds)

    # Domain per region: indices into region_options[i]
    domains = [set(range(len(region_options[i]))) for i in range(R)]

    def compute_bounds(domains):
        row_min = [0] * n
        row_max = [0] * n
        col_min = [0] * m
        col_max = [0] * m
        for i in range(R):
            d = domains[i]
            if not d:
                return None
            first = next(iter(d))
            rmin = list(option_row_add[i][first])
            rmax = list(option_row_add[i][first])
            cmin = list(option_col_add[i][first])
            cmax = list(option_col_add[i][first])
            for o in d:
                ra = option_row_add[i][o]
                ca = option_col_add[i][o]
                for r in range(n):
                    v = ra[r]
                    if v < rmin[r]:
                        rmin[r] = v
                    if v > rmax[r]:
                        rmax[r] = v
                for c in range(m):
                    v = ca[c]
                    if v < cmin[c]:
                        cmin[c] = v
                    if v > cmax[c]:
                        cmax[c] = v
            for r in range(n):
                row_min[r] += rmin[r]
                row_max[r] += rmax[r]
            for c in range(m):
                col_min[c] += cmin[c]
                col_max[c] += cmax[c]
        return row_min, row_max, col_min, col_max

    def propagate(domains):
        # Human-like repeated constraint propagation:
        # 1) row/column interval feasibility
        # 2) remove region options that can no longer fit row/column totals
        while True:
            bounds = compute_bounds(domains)
            if bounds is None:
                return None
            row_min, row_max, col_min, col_max = bounds

            for r in range(n):
                if row_target[r] < row_min[r] or row_target[r] > row_max[r]:
                    return None
            for c in range(m):
                if col_target[c] < col_min[c] or col_target[c] > col_max[c]:
                    return None

            changed = False

            # Precompute per-region min/max excluding that region.
            excl_row_min = []
            excl_row_max = []
            excl_col_min = []
            excl_col_max = []

            for i in range(R):
                d = domains[i]
                first = next(iter(d))
                rmin = list(option_row_add[i][first])
                rmax = list(option_row_add[i][first])
                cmin = list(option_col_add[i][first])
                cmax = list(option_col_add[i][first])
                for o in d:
                    ra = option_row_add[i][o]
                    ca = option_col_add[i][o]
                    for r in range(n):
                        v = ra[r]
                        if v < rmin[r]:
                            rmin[r] = v
                        if v > rmax[r]:
                            rmax[r] = v
                    for c in range(m):
                        v = ca[c]
                        if v < cmin[c]:
                            cmin[c] = v
                        if v > cmax[c]:
                            cmax[c] = v
                excl_row_min.append([row_min[r] - rmin[r] for r in range(n)])
                excl_row_max.append([row_max[r] - rmax[r] for r in range(n)])
                excl_col_min.append([col_min[c] - cmin[c] for c in range(m)])
                excl_col_max.append([col_max[c] - cmax[c] for c in range(m)])

            for i in range(R):
                d = domains[i]
                if len(d) == 1:
                    continue
                remove = []
                for o in d:
                    ra = option_row_add[i][o]
                    ca = option_col_add[i][o]
                    ok = True

                    for r in range(n):
                        v = ra[r]
                        if row_target[r] < excl_row_min[i][r] + v:
                            ok = False
                            break
                        if row_target[r] > excl_row_max[i][r] + v:
                            ok = False
                            break
                    if ok:
                        for c in range(m):
                            v = ca[c]
                            if col_target[c] < excl_col_min[i][c] + v:
                                ok = False
                                break
                            if col_target[c] > excl_col_max[i][c] + v:
                                ok = False
                                break

                    if not ok:
                        remove.append(o)

                if remove:
                    for o in remove:
                        d.remove(o)
                    if not d:
                        return None
                    changed = True

            if not changed:
                return domains

    def choose_region(domains):
        best_i = None
        best_key = None
        for i, d in enumerate(domains):
            if len(d) <= 1:
                continue
            # Smallest domain first; tie-break by largest region.
            key = (len(d), -len(regions[region_ids[i]]))
            if best_key is None or key < best_key:
                best_key = key
                best_i = i
        return best_i

    def search(domains):
        domains = [set(d) for d in domains]
        domains = propagate(domains)
        if domains is None:
            return None

        if all(len(d) == 1 for d in domains):
            return domains

        i = choose_region(domains)
        if i is None:
            return domains

        # Least-water / most-constrained ordering often works well with row/col totals.
        opts = sorted(
            domains[i],
            key=lambda o: (
                sum(option_row_add[i][o]),
                sum(1 for x in option_row_add[i][o] if x),
                sum(1 for x in option_col_add[i][o] if x),
            ),
        )

        for o in opts:
            new_domains = [set(d) for d in domains]
            new_domains[i] = {o}
            res = search(new_domains)
            if res is not None:
                return res
        return None

    res = search(domains)
    if res is None:
        return "No Solution"

    ans = [[None for _ in range(m)] for _ in range(n)]
    for i in range(R):
        o = next(iter(res[i]))
        for r, c in region_options[i][o]:
            ans[r][c] = 'W'
    return str(ans)

