from functools import lru_cache

# Shapeless 1-star solver:
# - exactly 1 star per row
# - exactly 1 star per column
# - stars cannot touch, including diagonally
# - black cells are forbidden
#
# With exactly one star per row/column, the non-touch rule reduces to:
# consecutive rows cannot place stars in adjacent columns.
# Same-column touching is already prevented by the column rule.

def solve(observation):
    data = observation['data']
    n = len(data)
    if any(len(row) != n for row in data):
        return "No Solution"

    full_mask = (1 << n) - 1

    # Allowed cells per row as bitmasks.
    row_allowed = []
    for r in range(n):
        mask = 0
        for c in range(n):
            if data[r][c] != 'B':
                mask |= 1 << c
        if mask == 0:
            return "No Solution"
        row_allowed.append(mask)

    # Precompute "not adjacent to column c" masks.
    safe_from_prev = [full_mask for _ in range(n)]
    for c in range(n):
        banned = 0
        if c - 1 >= 0:
            banned |= 1 << (c - 1)
        banned |= 1 << c
        if c + 1 < n:
            banned |= 1 << (c + 1)
        safe_from_prev[c] = full_mask ^ banned

    # Human-like feasibility check:
    # ignore diagonal-order interactions temporarily and only ask whether
    # remaining rows can still be matched injectively to remaining columns.
    def matching_possible(start_row, used_mask, prev_col):
        rows = list(range(start_row, n))
        rem_cols_mask = full_mask ^ used_mask

        candidate_masks = []
        for r in rows:
            mask = row_allowed[r] & rem_cols_mask
            if r == start_row and prev_col != -1:
                mask &= safe_from_prev[prev_col]
            if mask == 0:
                return False
            candidate_masks.append(mask)

        # Quick Hall-style necessary checks on small unions by greedy ordering.
        ordered = sorted(candidate_masks, key=int.bit_count)
        union = 0
        for i, m in enumerate(ordered, 1):
            union |= m
            if union.bit_count() < i:
                return False

        # Exact bipartite matching on the reduced row/column graph.
        cols = [c for c in range(n) if (rem_cols_mask >> c) & 1]
        col_index = {c: i for i, c in enumerate(cols)}
        adj = []
        for m in candidate_masks:
            lst = []
            mm = m
            while mm:
                bit = mm & -mm
                c = bit.bit_length() - 1
                lst.append(col_index[c])
                mm ^= bit
            adj.append(lst)

        match_to_row = [-1] * len(cols)

        def aug(i, seen):
            for j in adj[i]:
                if seen[j]:
                    continue
                seen[j] = True
                if match_to_row[j] == -1 or aug(match_to_row[j], seen):
                    match_to_row[j] = i
                    return True
            return False

        for i in range(len(adj)):
            seen = [False] * len(cols)
            if not aug(i, seen):
                return False
        return True

    @lru_cache(maxsize=None)
    def search(row, used_mask, prev_col):
        if row == n:
            return ()

        # Candidate columns for this row.
        mask = row_allowed[row] & (full_mask ^ used_mask)
        if prev_col != -1:
            mask &= safe_from_prev[prev_col]
        if mask == 0:
            return None

        # Strong forward pruning:
        # every remaining row must keep at least one available column;
        # plus a matching check on the suffix.
        if not matching_possible(row, used_mask, prev_col):
            return None

        # Value ordering:
        # prefer columns that constrain future rows the most (human-style forcing).
        choices = []
        mm = mask
        while mm:
            bit = mm & -mm
            c = bit.bit_length() - 1
            next_used = used_mask | bit

            # Immediate lookahead for next row.
            next_count = 0
            if row + 1 < n:
                next_mask = row_allowed[row + 1] & (full_mask ^ next_used) & safe_from_prev[c]
                next_count = next_mask.bit_count()
                if next_count == 0:
                    mm ^= bit
                    continue

            # Count total future flexibility: smaller first.
            future_score = 0
            feasible = True
            for r2 in range(row + 1, n):
                m2 = row_allowed[r2] & (full_mask ^ next_used)
                if r2 == row + 1:
                    m2 &= safe_from_prev[c]
                cnt = m2.bit_count()
                if cnt == 0:
                    feasible = False
                    break
                future_score += cnt
            if feasible:
                choices.append((next_count, future_score, c))
            mm ^= bit

        if not choices:
            return None

        choices.sort()

        for _, _, c in choices:
            bit = 1 << c
            next_used = used_mask | bit

            # Deeper matching prune before recursing.
            if row + 1 < n and not matching_possible(row + 1, next_used, c):
                continue

            tail = search(row + 1, next_used, c)
            if tail is not None:
                return (c,) + tail

        return None

    cols = search(0, 0, -1)
    if cols is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for r, c in enumerate(cols):
        answer[r][c] = 'S'
    return str(answer)


