    print(solve(OBSERVATION))

OBSERVATION = {'U': [1, 5, 4, 3, 2, 2], 'D': [3, 1, 2, 3, 2, 4], 'L': [1, 3, 4, 2, 3, 2], 'R': [3, 1, 2, 3, 2, 4]}

from itertools import permutations


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    n = len(U)

    if not (len(D) == len(L) == len(R) == n):
        return "No Solution"

    all_mask = (1 << n) - 1
    bit = lambda v: 1 << (v - 1)

    def mask_to_values(m):
        return [i + 1 for i in range(n) if (m >> i) & 1]

    def single_value(m):
        return m.bit_length() if m and (m & (m - 1)) == 0 else None

    def visibility(seq):
        seen = 0
        mx = 0
        for x in seq:
            if x > mx:
                mx = x
                seen += 1
        return seen

    def clue_ok(clue, seen):
        return clue == 0 or clue == seen

    # Precompute all valid line permutations by (left_clue, right_clue).
    perms = list(permutations(range(1, n + 1)))
    by_clue = {}
    for p in perms:
        lc = visibility(p)
        rc = visibility(reversed(p))
        by_clue.setdefault((lc, rc), []).append(p)

    def clue_filtered(cl1, cl2):
        if cl1 == 0 and cl2 == 0:
            return perms[:]
        out = []
        for p in perms:
            if clue_ok(cl1, visibility(p)) and clue_ok(cl2, visibility(reversed(p))):
                out.append(p)
        return out

    row_cands = [clue_filtered(L[r], R[r]) for r in range(n)]
    col_cands = [clue_filtered(U[c], D[c]) for c in range(n)]

    domains = [[all_mask for _ in range(n)] for _ in range(n)]

    def apply_edge_pruning():
        # Human-style immediate deductions from extreme clues.
        # For clue 1, first building must be tallest.
        # For clue N, the line is strictly increasing from that side.
        # General bound: at offset p from a side with clue c, value cannot exceed N-c+1+p.
        for c in range(n):
            clue = U[c]
            if clue == 1:
                domains[0][c] &= bit(n)
            elif clue == n:
                for r in range(n):
                    domains[r][c] &= bit(r + 1)
            elif clue > 1:
                for r in range(n):
                    mx = min(n, n - clue + 1 + r)
                    domains[r][c] &= (1 << mx) - 1

            clue = D[c]
            if clue == 1:
                domains[n - 1][c] &= bit(n)
            elif clue == n:
                for r in range(n):
                    domains[n - 1 - r][c] &= bit(r + 1)
            elif clue > 1:
                for off in range(n):
                    mx = min(n, n - clue + 1 + off)
                    domains[n - 1 - off][c] &= (1 << mx) - 1

        for r in range(n):
            clue = L[r]
            if clue == 1:
                domains[r][0] &= bit(n)
            elif clue == n:
                for c in range(n):
                    domains[r][c] &= bit(c + 1)
            elif clue > 1:
                for c in range(n):
                    mx = min(n, n - clue + 1 + c)
                    domains[r][c] &= (1 << mx) - 1

            clue = R[r]
            if clue == 1:
                domains[r][n - 1] &= bit(n)
            elif clue == n:
                for c in range(n):
                    domains[r][n - 1 - c] &= bit(c + 1)
            elif clue > 1:
                for off in range(n):
                    mx = min(n, n - clue + 1 + off)
                    domains[r][n - 1 - off] &= (1 << mx) - 1

        for r in range(n):
            for c in range(n):
                if domains[r][c] == 0:
                    return False
        return True

    if not apply_edge_pruning():
        return "No Solution"

    def copy_state(domains, row_cands, col_cands):
        return (
            [row[:] for row in domains],
            [lst[:] for lst in row_cands],
            [lst[:] for lst in col_cands],
        )

    def filter_line_candidates(line_cands, getter):
        changed = False
        for idx in range(n):
            old = line_cands[idx]
            new = [p for p in old if all(bit(p[k]) & getter(idx, k) for k in range(n))]
            if not new:
                return None, None
            if len(new) != len(old):
                line_cands[idx] = new
                changed = True
        return line_cands, changed

    def propagate(domains, row_cands, col_cands):
        while True:
            changed_any = False

            row_cands, changed = filter_line_candidates(row_cands, lambda r, c: domains[r][c])
            if row_cands is None:
                return None
            changed_any |= changed

            col_cands, changed = filter_line_candidates(col_cands, lambda c, r: domains[r][c])
            if col_cands is None:
                return None
            changed_any |= changed

            # Intersect cell domains with what row and column candidates still allow.
            for r in range(n):
                row_unions = [0] * n
                for p in row_cands[r]:
                    for c, v in enumerate(p):
                        row_unions[c] |= bit(v)
                for c in range(n):
                    nd = domains[r][c] & row_unions[c]
                    if nd == 0:
                        return None
                    if nd != domains[r][c]:
                        domains[r][c] = nd
                        changed_any = True

            for c in range(n):
                col_unions = [0] * n
                for p in col_cands[c]:
                    for r, v in enumerate(p):
                        col_unions[r] |= bit(v)
                for r in range(n):
                    nd = domains[r][c] & col_unions[r]
                    if nd == 0:
                        return None
                    if nd != domains[r][c]:
                        domains[r][c] = nd
                        changed_any = True

            # Human-like Latin uniqueness:
            # in a row/column, if a value can go in only one place, fix it there.
            for r in range(n):
                for v in range(1, n + 1):
                    b = bit(v)
                    spots = [c for c in range(n) if domains[r][c] & b]
                    if not spots:
                        return None
                    if len(spots) == 1 and domains[r][spots[0]] != b:
                        domains[r][spots[0]] = b
                        changed_any = True

            for c in range(n):
                for v in range(1, n + 1):
                    b = bit(v)
                    spots = [r for r in range(n) if domains[r][c] & b]
                    if not spots:
                        return None
                    if len(spots) == 1 and domains[spots[0]][c] != b:
                        domains[spots[0]][c] = b
                        changed_any = True

            # If a whole row/column is fixed, keep only matching candidate.
            for r in range(n):
                if all((domains[r][c] & (domains[r][c] - 1)) == 0 for c in range(n)):
                    fixed = tuple(single_value(domains[r][c]) for c in range(n))
                    if len(set(fixed)) < n:
                        return None
                    if fixed not in row_cands[r]:
                        return None
                    if len(row_cands[r]) != 1 or row_cands[r][0] != fixed:
                        row_cands[r] = [fixed]
                        changed_any = True

            for c in range(n):
                if all((domains[r][c] & (domains[r][c] - 1)) == 0 for r in range(n)):
                    fixed = tuple(single_value(domains[r][c]) for r in range(n))
                    if len(set(fixed)) < n:
                        return None
                    if fixed not in col_cands[c]:
                        return None
                    if len(col_cands[c]) != 1 or col_cands[c][0] != fixed:
                        col_cands[c] = [fixed]
                        changed_any = True

            if not changed_any:
                break

        # Final quick consistency checks.
        for r in range(n):
            for c in range(n):
                if domains[r][c] == 0:
                    return None

        return domains, row_cands, col_cands

    def solved(domains):
        return all((domains[r][c] & (domains[r][c] - 1)) == 0 for r in range(n) for c in range(n))

    def extract_solution(domains):
        grid = [[single_value(domains[r][c]) for c in range(n)] for r in range(n)]
        # Validate fully.
        target = set(range(1, n + 1))
        for r in range(n):
            if set(grid[r]) != target:
                return None
            if not clue_ok(L[r], visibility(grid[r])):
                return None
            if not clue_ok(R[r], visibility(reversed(grid[r]))):
                return None
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            if set(col) != target:
                return None
            if not clue_ok(U[c], visibility(col)):
                return None
            if not clue_ok(D[c], visibility(reversed(col))):
                return None
        return grid

    def choose_branch(row_cands, col_cands):
        best = None
        for r in range(n):
            k = len(row_cands[r])
            if 1 < k and (best is None or k < best[0]):
                best = (k, 'row', r)
        for c in range(n):
            k = len(col_cands[c])
            if 1 < k and (best is None or k < best[0]):
                best = (k, 'col', c)
        return best

    def search(domains, row_cands, col_cands):
        state = propagate(domains, row_cands, col_cands)
        if state is None:
            return None
        domains, row_cands, col_cands = state

        if solved(domains):
            return extract_solution(domains)

        branch = choose_branch(row_cands, col_cands)
        if branch is None:
            return extract_solution(domains)

        _, kind, idx = branch

        if kind == 'row':
            # Least-ambiguity branching on an entire row permutation.
            for p in row_cands[idx]:
                d2, r2, c2 = copy_state(domains, row_cands, col_cands)
                r2[idx] = [p]
                ok = True
                for c, v in enumerate(p):
                    m = bit(v)
                    if not (d2[idx][c] & m):
                        ok = False
                        break
                    d2[idx][c] = m
                if ok:
                    ans = search(d2, r2, c2)
                    if ans is not None:
                        return ans
        else:
            # Or branch on a whole column permutation.
            for p in col_cands[idx]:
                d2, r2, c2 = copy_state(domains, row_cands, col_cands)
                c2[idx] = [p]
                ok = True
                for r, v in enumerate(p):
                    m = bit(v)
                    if not (d2[r][idx] & m):
                        ok = False
                        break
                    d2[r][idx] = m
                if ok:
                    ans = search(d2, r2, c2)
                    if ans is not None:
                        return ans

        return None

    result = search(domains, row_cands, col_cands)
    return result if result is not None else "No Solution"


