# Generalized solver for a Latin-square-with-consecutive-adjacency puzzle.
# Human-like logic implemented:
# - immediate clue placement
# - row/column elimination
# - adjacency propagation:
#   * dotted edge => values must be consecutive
#   * absent edge => values must not be consecutive
# - hidden singles in rows/columns
# - strong propagation loop until fixpoint
# - backtracking only after deduction stalls
# - branching on most constrained cell with least-impact value ordering

FULL_MASK_CACHE = {}

def bit(v):
    return 1 << (v - 1)

def popcount(x):
    return x.bit_count()

def mask_values(mask, n):
    return [v for v in range(1, n + 1) if mask & bit(v)]

def single_value(mask):
    if mask and mask & (mask - 1) == 0:
        return mask.bit_length()
    return None

def full_mask(n):
    if n not in FULL_MASK_CACHE:
        FULL_MASK_CACHE[n] = (1 << n) - 1
    return FULL_MASK_CACHE[n]

def consecutive_mask_from_domain(mask, n):
    # Values allowed in neighbor if it must be consecutive to one of current domain values.
    out = 0
    m = mask
    while m:
        lsb = m & -m
        v = lsb.bit_length()
        if v > 1:
            out |= bit(v - 1)
        if v < n:
            out |= bit(v + 1)
        m ^= lsb
    return out

def nonconsecutive_mask_from_domain(mask, n):
    # Values allowed in neighbor if it must NOT be consecutive to any value current might take.
    bad = consecutive_mask_from_domain(mask, n)
    return full_mask(n) & ~bad

def parse_edges(n, adjacent_list):
    dotted = set()
    for a, b in adjacent_list:
        dotted.add((float(a), float(b)))
    edge_type = {}
    neighbors = { (r, c): [] for r in range(n) for c in range(n) }
    for r in range(n):
        for c in range(n):
            if c + 1 < n:
                mid = (float(r), c + 0.5)
                pos = (r, c)
                qos = (r, c + 1)
                t = mid in dotted
                edge_type[(pos, qos)] = t
                edge_type[(qos, pos)] = t
                neighbors[pos].append((qos, t))
                neighbors[qos].append((pos, t))
            if r + 1 < n:
                mid = (r + 0.5, float(c))
                pos = (r, c)
                qos = (r + 1, c)
                t = mid in dotted
                edge_type[(pos, qos)] = t
                edge_type[(qos, pos)] = t
                neighbors[pos].append((qos, t))
                neighbors[qos].append((pos, t))
    return neighbors, edge_type

def clone_domains(domains):
    return [row[:] for row in domains]

def initialize(observation):
    data = observation['data']
    n = len(data)
    fm = full_mask(n)
    domains = [[fm for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                domains[r][c] = bit(v)
    neighbors, edge_type = parse_edges(n, observation['adjacent'])
    return n, domains, neighbors, edge_type

def assign(domains, r, c, valmask):
    old = domains[r][c]
    new = old & valmask
    if new == 0:
        return False, False
    if new == old:
        return True, False
    domains[r][c] = new
    return True, True

def propagate_row_col_basic(domains, n):
    changed = False

    # Remove fixed values from peers.
    for r in range(n):
        fixed_mask = 0
        for c in range(n):
            if domains[r][c] & (domains[r][c] - 1) == 0:
                if fixed_mask & domains[r][c]:
                    return False, changed
                fixed_mask |= domains[r][c]
        for c in range(n):
            if domains[r][c] & (domains[r][c] - 1):
                new = domains[r][c] & ~fixed_mask
                if new == 0:
                    return False, changed
                if new != domains[r][c]:
                    domains[r][c] = new
                    changed = True

    for c in range(n):
        fixed_mask = 0
        for r in range(n):
            if domains[r][c] & (domains[r][c] - 1) == 0:
                if fixed_mask & domains[r][c]:
                    return False, changed
                fixed_mask |= domains[r][c]
        for r in range(n):
            if domains[r][c] & (domains[r][c] - 1):
                new = domains[r][c] & ~fixed_mask
                if new == 0:
                    return False, changed
                if new != domains[r][c]:
                    domains[r][c] = new
                    changed = True

    # Hidden singles in rows.
    for r in range(n):
        where = [0] * (n + 1)
        count = [0] * (n + 1)
        for c in range(n):
            m = domains[r][c]
            mm = m
            while mm:
                lsb = mm & -mm
                v = lsb.bit_length()
                where[v] = c
                count[v] += 1
                mm ^= lsb
        for v in range(1, n + 1):
            if count[v] == 0:
                return False, changed
            if count[v] == 1:
                c = where[v]
                ok, ch = assign(domains, r, c, bit(v))
                if not ok:
                    return False, changed
                changed |= ch

    # Hidden singles in columns.
    for c in range(n):
        where = [0] * (n + 1)
        count = [0] * (n + 1)
        for r in range(n):
            m = domains[r][c]
            mm = m
            while mm:
                lsb = mm & -mm
                v = lsb.bit_length()
                where[v] = r
                count[v] += 1
                mm ^= lsb
        for v in range(1, n + 1):
            if count[v] == 0:
                return False, changed
            if count[v] == 1:
                r = where[v]
                ok, ch = assign(domains, r, c, bit(v))
                if not ok:
                    return False, changed
                changed |= ch

    return True, changed

def propagate_adjacency(domains, n, neighbors):
    changed = False
    for r in range(n):
        for c in range(n):
            cur = domains[r][c]
            for (rr, cc), dotted in neighbors[(r, c)]:
                other = domains[rr][cc]
                allowed = consecutive_mask_from_domain(cur, n) if dotted else nonconsecutive_mask_from_domain(cur, n)
                new_other = other & allowed
                if new_other == 0:
                    return False, changed
                if new_other != other:
                    domains[rr][cc] = new_other
                    changed = True
    return True, changed

def hall_pairs_unit(domains, cells):
    # Human-style naked pairs only; cheap and effective.
    changed = False
    pairs = {}
    for r, c in cells:
        m = domains[r][c]
        if popcount(m) == 2:
            pairs.setdefault(m, []).append((r, c))
    for m, locs in pairs.items():
        if len(locs) == 2:
            for r, c in cells:
                if (r, c) not in locs:
                    new = domains[r][c] & ~m
                    if new == 0:
                        return False, changed
                    if new != domains[r][c]:
                        domains[r][c] = new
                        changed = True
    return True, changed

def propagate_naked_pairs(domains, n):
    changed = False
    for r in range(n):
        ok, ch = hall_pairs_unit(domains, [(r, c) for c in range(n)])
        if not ok:
            return False, changed
        changed |= ch
    for c in range(n):
        ok, ch = hall_pairs_unit(domains, [(r, c) for r in range(n)])
        if not ok:
            return False, changed
        changed |= ch
    return True, changed

def consistency_check(domains, n, neighbors):
    # Quick feasibility checks.
    # Row/column each value must still have at least one place.
    for r in range(n):
        union = 0
        for c in range(n):
            if domains[r][c] == 0:
                return False
            union |= domains[r][c]
        if union != full_mask(n):
            return False
    for c in range(n):
        union = 0
        for r in range(n):
            if domains[r][c] == 0:
                return False
            union |= domains[r][c]
        if union != full_mask(n):
            return False

    # Every edge must retain support both ways.
    seen = set()
    for r in range(n):
        for c in range(n):
            for (rr, cc), dotted in neighbors[(r, c)]:
                key = tuple(sorted(((r, c), (rr, cc))))
                if key in seen:
                    continue
                seen.add(key)
                a = domains[r][c]
                b = domains[rr][cc]
                if dotted:
                    if (consecutive_mask_from_domain(a, n) & b) == 0:
                        return False
                    if (consecutive_mask_from_domain(b, n) & a) == 0:
                        return False
                else:
                    if (nonconsecutive_mask_from_domain(a, n) & b) == 0:
                        return False
                    if (nonconsecutive_mask_from_domain(b, n) & a) == 0:
                        return False
    return True

def propagate(domains, n, neighbors):
    while True:
        any_changed = False

        ok, changed = propagate_row_col_basic(domains, n)
        if not ok:
            return False
        any_changed |= changed

        ok, changed = propagate_adjacency(domains, n, neighbors)
        if not ok:
            return False
        any_changed |= changed

        ok, changed = propagate_naked_pairs(domains, n)
        if not ok:
            return False
        any_changed |= changed

        if not consistency_check(domains, n, neighbors):
            return False

        if not any_changed:
            return True

def is_solved(domains, n):
    for r in range(n):
        for c in range(n):
            if domains[r][c] & (domains[r][c] - 1):
                return False
    return True

def choose_cell(domains, n, neighbors):
    # MRV + degree heuristic.
    best = None
    best_key = None
    for r in range(n):
        for c in range(n):
            m = domains[r][c]
            pc = popcount(m)
            if pc > 1:
                deg = 0
                for (rr, cc), _ in neighbors[(r, c)]:
                    deg += popcount(domains[rr][cc]) > 1
                key = (pc, -deg, r, c)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (r, c)
    return best

def order_values(domains, n, neighbors, r, c):
    # Least-constraining value.
    vals = mask_values(domains[r][c], n)
    scored = []
    for v in vals:
        score = 0
        vm = bit(v)
        for (rr, cc), dotted in neighbors[(r, c)]:
            other = domains[rr][cc]
            allowed = consecutive_mask_from_domain(vm, n) if dotted else nonconsecutive_mask_from_domain(vm, n)
            score += popcount(other & allowed)
        # higher score = less constraining
        scored.append((-score, v))
    scored.sort()
    return [v for _, v in scored]

def extract_solution(domains, n):
    return [[single_value(domains[r][c]) for c in range(n)] for r in range(n)]

def search(domains, n, neighbors):
    if not propagate(domains, n, neighbors):
        return None
    if is_solved(domains, n):
        return extract_solution(domains, n)

    r, c = choose_cell(domains, n, neighbors)
    for v in order_values(domains, n, neighbors, r, c):
        new_domains = clone_domains(domains)
        new_domains[r][c] = bit(v)
        ans = search(new_domains, n, neighbors)
        if ans is not None:
            return ans
    return None

def solve(observation):
    n, domains, neighbors, edge_type = initialize(observation)
    ans = search(domains, n, neighbors)
    return str(ans) if ans is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 0, 1, 1], [0, 0, 1, 1, 3], [2, 2, 2, 1, 3], [2, 2, 3, 3, 3], [4, 4, 4, 4, 4]], 'data': [[None, 5, None, None, 1], [None, None, None, 4, None], [None, None, None, None, None], [None, 2, None, None, None], [1, None, None, 2, None]]}

# Generalized Latin/irregular Sudoku solver using aggressive propagation:
# - row/column/region constraints
# - naked singles
# - hidden singles in every unit
# - contradiction-driven DFS with MRV branching

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(data)

    if n == 0 or any(len(row) != n for row in data) or any(len(row) != n for row in region):
        return "No Solution"

    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def first_value(mask):
        return (mask & -mask).bit_length()

    # Build region -> cells and validate region sizes
    region_cells = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            region_cells.setdefault(rid, []).append((r, c))

    if len(region_cells) != n:
        return "No Solution"
    if any(len(cells) != n for cells in region_cells.values()):
        return "No Solution"

    region_ids = sorted(region_cells)
    rid_to_index = {rid: i for i, rid in enumerate(region_ids)}
    cell_region_index = [[rid_to_index[region[r][c]] for c in range(n)] for r in range(n)]
    regions_by_index = [region_cells[rid] for rid in region_ids]

    # Units for hidden singles
    units = []
    for r in range(n):
        units.append([(r, c) for c in range(n)])
    for c in range(n):
        units.append([(r, c) for r in range(n)])
    for cells in regions_by_index:
        units.append(cells)

    values = [[0] * n for _ in range(n)]
    cand = [[full_mask] * n for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n

    # Initial givens
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= n):
                return "No Solution"
            m = bit(v)
            g = cell_region_index[r][c]
            if (row_used[r] & m) or (col_used[c] & m) or (reg_used[g] & m):
                return "No Solution"
            values[r][c] = v
            row_used[r] |= m
            col_used[c] |= m
            reg_used[g] |= m

    # Initialize candidates for empty cells
    for r in range(n):
        for c in range(n):
            if values[r][c]:
                cand[r][c] = bit(values[r][c])
            else:
                g = cell_region_index[r][c]
                m = full_mask & ~(row_used[r] | col_used[c] | reg_used[g])
                if m == 0:
                    return "No Solution"
                cand[r][c] = m

    def clone_state(values, cand, row_used, col_used, reg_used):
        return (
            [row[:] for row in values],
            [row[:] for row in cand],
            row_used[:],
            col_used[:],
            reg_used[:],
        )

    def assign(state, r, c, v, queue):
        values, cand, row_used, col_used, reg_used = state
        current = values[r][c]
        if current == v:
            return True
        if current != 0:
            return False
        m = bit(v)
        if not (cand[r][c] & m):
            return False

        g = cell_region_index[r][c]
        if (row_used[r] & m) or (col_used[c] & m) or (reg_used[g] & m):
            return False

        values[r][c] = v
        cand[r][c] = m
        row_used[r] |= m
        col_used[c] |= m
        reg_used[g] |= m
        queue.append((r, c))
        return True

    def eliminate_mask(state, r, c, rem_mask, queue):
        values, cand, row_used, col_used, reg_used = state
        if values[r][c] != 0:
            return True
        old = cand[r][c]
        new = old & ~rem_mask
        if new == old:
            return True
        if new == 0:
            return False
        cand[r][c] = new
        if new & (new - 1) == 0:
            v = first_value(new)
            return assign(state, r, c, v, queue)
        return True

    def propagate(state):
        values, cand, row_used, col_used, reg_used = state
        queue = []

        # Seed queue with all fixed cells
        for r in range(n):
            for c in range(n):
                if values[r][c] != 0:
                    queue.append((r, c))
                elif cand[r][c] & (cand[r][c] - 1) == 0:
                    v = first_value(cand[r][c])
                    if not assign(state, r, c, v, queue):
                        return False

        # Constraint propagation from assignments
        qpos = 0
        while qpos < len(queue):
            r, c = queue[qpos]
            qpos += 1
            v = values[r][c]
            m = bit(v)
            g = cell_region_index[r][c]

            for cc in range(n):
                if cc != c and not eliminate_mask(state, r, cc, m, queue):
                    return False
            for rr in range(n):
                if rr != r and not eliminate_mask(state, rr, c, m, queue):
                    return False
            for rr, cc in regions_by_index[g]:
                if (rr != r or cc != c) and not eliminate_mask(state, rr, cc, m, queue):
                    return False

        # Repeat hidden singles / consistency until stable
        changed = True
        while changed:
            changed = False

            # Basic consistency refresh
            for r in range(n):
                for c in range(n):
                    if values[r][c] == 0:
                        g = cell_region_index[r][c]
                        allowed = full_mask & ~(row_used[r] | col_used[c] | reg_used[g])
                        new = cand[r][c] & allowed
                        if new == 0:
                            return False
                        if new != cand[r][c]:
                            cand[r][c] = new
                            changed = True
                        if new & (new - 1) == 0:
                            v = first_value(new)
                            if not assign(state, r, c, v, queue):
                                return False

            while qpos < len(queue):
                r, c = queue[qpos]
                qpos += 1
                v = values[r][c]
                m = bit(v)
                g = cell_region_index[r][c]

                for cc in range(n):
                    if cc != c and not eliminate_mask(state, r, cc, m, queue):
                        return False
                for rr in range(n):
                    if rr != r and not eliminate_mask(state, rr, c, m, queue):
                        return False
                for rr, cc in regions_by_index[g]:
                    if (rr != r or cc != c) and not eliminate_mask(state, rr, cc, m, queue):
                        return False
                changed = True

            # Hidden singles in rows, columns, regions
            for unit in units:
                pos_by_digit = [None] * (n + 1)
                count_by_digit = [0] * (n + 1)

                for r, c in unit:
                    if values[r][c] == 0:
                        m = cand[r][c]
                        x = m
                        while x:
                            lsb = x & -x
                            d = lsb.bit_length()
                            count_by_digit[d] += 1
                            pos_by_digit[d] = (r, c)
                            x ^= lsb

                for d in range(1, n + 1):
                    m = bit(d)
                    fixed_count = 0
                    for r, c in unit:
                        if values[r][c] == d:
                            fixed_count += 1
                    if fixed_count > 1:
                        return False
                    if fixed_count == 0:
                        if count_by_digit[d] == 0:
                            return False
                        if count_by_digit[d] == 1:
                            r, c = pos_by_digit[d]
                            if not assign(state, r, c, d, queue):
                                return False
                            changed = True

            while qpos < len(queue):
                r, c = queue[qpos]
                qpos += 1
                v = values[r][c]
                m = bit(v)
                g = cell_region_index[r][c]

                for cc in range(n):
                    if cc != c and not eliminate_mask(state, r, cc, m, queue):
                        return False
                for rr in range(n):
                    if rr != r and not eliminate_mask(state, rr, c, m, queue):
                        return False
                for rr, cc in regions_by_index[g]:
                    if (rr != r or cc != c) and not eliminate_mask(state, rr, cc, m, queue):
                        return False

        return True

    def solved(values):
        for r in range(n):
            for c in range(n):
                if values[r][c] == 0:
                    return False
        return True

    def choose_branch_cell(values, cand):
        best = None
        best_len = n + 1
        best_score = -1

        for r in range(n):
            for c in range(n):
                if values[r][c] == 0:
                    m = cand[r][c]
                    k = popcount(m)
                    if k < best_len:
                        peer_score = 0
                        g = cell_region_index[r][c]
                        for cc in range(n):
                            if cc != c and values[r][cc] == 0:
                                peer_score += 1
                        for rr in range(n):
                            if rr != r and values[rr][c] == 0:
                                peer_score += 1
                        for rr, cc in regions_by_index[g]:
                            if (rr != r or cc != c) and values[rr][cc] == 0:
                                peer_score += 1
                        best = (r, c)
                        best_len = k
                        best_score = peer_score
                    elif k == best_len:
                        peer_score = 0
                        g = cell_region_index[r][c]
                        for cc in range(n):
                            if cc != c and values[r][cc] == 0:
                                peer_score += 1
                        for rr in range(n):
                            if rr != r and values[rr][c] == 0:
                                peer_score += 1
                        for rr, cc in regions_by_index[g]:
                            if (rr != r or cc != c) and values[rr][cc] == 0:
                                peer_score += 1
                        if peer_score > best_score:
                            best = (r, c)
                            best_score = peer_score
        return best

    def ordered_candidates(r, c, values, cand):
        # Least-constraining-value ordering
        m = cand[r][c]
        g = cell_region_index[r][c]
        peers = set()
        for cc in range(n):
            if cc != c and values[r][cc] == 0:
                peers.add((r, cc))
        for rr in range(n):
            if rr != r and values[rr][c] == 0:
                peers.add((rr, c))
        for rr, cc in regions_by_index[g]:
            if (rr != r or cc != c) and values[rr][cc] == 0:
                peers.add((rr, cc))

        scored = []
        x = m
        while x:
            lsb = x & -x
            d = lsb.bit_length()
            impact = 0
            for rr, cc in peers:
                if cand[rr][cc] & lsb:
                    impact += 1
            scored.append((impact, d))
            x ^= lsb
        scored.sort()
        return [d for _, d in scored]

    def dfs(state):
        values, cand, row_used, col_used, reg_used = state
        if not propagate(state):
            return None
        if solved(values):
            return values

        cell = choose_branch_cell(values, cand)
        if cell is None:
            return values

        r, c = cell
        for v in ordered_candidates(r, c, values, cand):
            new_state = clone_state(values, cand, row_used, col_used, reg_used)
            queue = []
            if assign(new_state, r, c, v, queue):
                result = dfs(new_state)
                if result is not None:
                    return result
        return None

    initial_state = (values, cand, row_used, col_used, reg_used)
    result = dfs(initial_state)
    return result if result is not None else "No Solution"


