# Jigsaw Latin square solver:
# - rows contain 1..N exactly once
# - cols contain 1..N exactly once
# - irregular regions contain 1..N exactly once
#
# The solver is generalized:
# - bitmask candidates
# - aggressive propagation
# - human-like deductions:
#   * naked singles
#   * hidden singles in each row/col/region
#   * locked-set style subset elimination inside each unit
# - then minimal branching on MRV cell / constrained value order

from collections import defaultdict

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    if n == 0 or any(len(r) != n for r in region) or any(len(r) != n for r in data):
        return "No Solution"

    all_mask = (1 << n) - 1

    # Build regions
    reg_cells = defaultdict(list)
    for r in range(n):
        for c in range(n):
            reg_cells[region[r][c]].append((r, c))

    # Validate region sizes for Latin constraints
    for rid, cells in reg_cells.items():
        if len(cells) != n:
            return "No Solution"

    region_ids = sorted(reg_cells)
    region_index = {rid: i for i, rid in enumerate(region_ids)}

    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    regs = [reg_cells[rid] for rid in region_ids]
    units = rows + cols + regs

    # For each cell, list its 3 units
    cell_units = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            cell_units[r][c] = (r, n + c, 2 * n + region_index[region[r][c]])

    # Neighbors for each cell
    neighbors = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            s = set(rows[r]) | set(cols[c]) | set(regs[region_index[region[r][c]]])
            s.discard((r, c))
            neighbors[r][c] = tuple(s)

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def iter_values(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    def mask_to_sorted_values(mask):
        out = []
        while mask:
            b = mask & -mask
            out.append(b.bit_length())
            mask ^= b
        return out

    # State
    cand = [[all_mask for _ in range(n)] for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n
    solved_count = 0

    def assign(r, c, v):
        nonlocal solved_count
        m = bit(v)
        cur = cand[r][c]
        if not (cur & m):
            return False
        if cur == m:
            return True
        # Remove all other candidates from cell
        others = cur & ~m
        x = others
        while x:
            b = x & -x
            val = b.bit_length()
            if not eliminate(r, c, val):
                return False
            x ^= b
        return True

    def eliminate(r, c, v):
        nonlocal solved_count
        m = bit(v)
        cur = cand[r][c]
        if not (cur & m):
            return True
        new = cur & ~m
        if new == 0:
            return False
        was_single = (cur & (cur - 1)) == 0
        cand[r][c] = new

        # If newly single, record usage and propagate to peers
        if not was_single and (new & (new - 1)) == 0:
            solved_count += 1
            val = new.bit_length()
            bm = bit(val)
            ri = region_index[region[r][c]]
            if (row_used[r] & bm) or (col_used[c] & bm) or (reg_used[ri] & bm):
                return False
            row_used[r] |= bm
            col_used[c] |= bm
            reg_used[ri] |= bm

            for rr, cc in neighbors[r][c]:
                if not eliminate(rr, cc, val):
                    return False
        return True

    # Initialize givens and propagate direct contradictions
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                if not assign(r, c, v):
                    return "No Solution"

    # Seed solved_count / used masks for givens that were already single at start
    # The eliminate() path updates these, but cells that remained all_mask before assign
    # get fully processed there. Still, ensure any pre-single cells are reflected.
    for r in range(n):
        for c in range(n):
            m = cand[r][c]
            if (m & (m - 1)) == 0:
                v = m.bit_length()
                bm = bit(v)
                ri = region_index[region[r][c]]
                if not (row_used[r] & bm):
                    row_used[r] |= bm
                if not (col_used[c] & bm):
                    col_used[c] |= bm
                if not (reg_used[ri] & bm):
                    reg_used[ri] |= bm

    def unit_hidden_singles(unit):
        # If a digit can only appear in one cell of a unit, assign it.
        places = [0] * n
        count = [0] * n
        for idx, (r, c) in enumerate(unit):
            m = cand[r][c]
            x = m
            while x:
                b = x & -x
                d = b.bit_length() - 1
                places[d] = idx
                count[d] += 1
                x ^= b
        for d in range(n):
            if count[d] == 0:
                return False
            if count[d] == 1:
                r, c = unit[places[d]]
                if not assign(r, c, d + 1):
                    return False
        return True

    def unit_subset_elimination(unit):
        # Naked subsets / locked sets within one unit:
        # if k cells together contain exactly k values, remove those values from others.
        unsolved = []
        for r, c in unit:
            m = cand[r][c]
            if m & (m - 1):
                unsolved.append((r, c, m))
        mlen = len(unsolved)
        if mlen < 2:
            return True

        groups = defaultdict(list)
        for r, c, m in unsolved:
            groups[m].append((r, c))

        # Fast exact naked subset for repeated masks
        for m, cells in list(groups.items()):
            k = popcount(m)
            if 2 <= len(cells) == k:
                for r, c in unit:
                    if (r, c) not in cells:
                        x = cand[r][c] & m
                        while x:
                            b = x & -x
                            if not eliminate(r, c, b.bit_length()):
                                return False
                            x ^= b

        # Small-combination union subsets for robustness
        # Only examine up to size 4; enough for strong pruning on typical puzzles.
        idxs = list(range(mlen))
        masks = [unsolved[i][2] for i in idxs]

        def rec(start, depth, limit, chosen, union_mask):
            if depth == limit:
                if popcount(union_mask) != limit:
                    return True
                chosen_set = set(chosen)
                for j in idxs:
                    if j in chosen_set:
                        continue
                    r, c, _ = unsolved[j]
                    x = cand[r][c] & union_mask
                    while x:
                        b = x & -x
                        if not eliminate(r, c, b.bit_length()):
                            return False
                        x ^= b
                return True
            prev_union = union_mask
            for i in range(start, mlen - (limit - depth) + 1):
                new_union = prev_union | masks[i]
                if popcount(new_union) > limit:
                    continue
                chosen.append(i)
                if not rec(i + 1, depth + 1, limit, chosen, new_union):
                    return False
                chosen.pop()
            return True

        for k in range(2, min(4, mlen) + 1):
            if not rec(0, 0, k, [], 0):
                return False
        return True

    def global_consistency_check():
        # No repeated solved values in a unit; every digit must still have a place.
        for unit in units:
            seen = 0
            cover = 0
            for r, c in unit:
                m = cand[r][c]
                if m == 0:
                    return False
                if (m & (m - 1)) == 0:
                    if seen & m:
                        return False
                    seen |= m
                cover |= m
            if cover != all_mask:
                return False
        return True

    def propagate():
        # Fixed-point propagation: singles, hidden singles, subset elimination.
        while True:
            snapshot = tuple(tuple(row) for row in cand)

            # Unit-based hidden singles
            for unit in units:
                if not unit_hidden_singles(unit):
                    return False

            # Subset elimination
            for unit in units:
                if not unit_subset_elimination(unit):
                    return False

            # Basic coverage/consistency
            if not global_consistency_check():
                return False

            if snapshot == tuple(tuple(row) for row in cand):
                return True

    if not propagate():
        return "No Solution"

    def is_solved():
        for r in range(n):
            for c in range(n):
                if cand[r][c] & (cand[r][c] - 1):
                    return False
        return True

    def clone_state():
        return (
            [row[:] for row in cand],
            row_used[:],
            col_used[:],
            reg_used[:],
            solved_count,
        )

    def restore_state(state):
        nonlocal cand, row_used, col_used, reg_used, solved_count
        cand, row_used, col_used, reg_used, solved_count = state

    def select_branch_cell():
        # MRV + degree tie-break.
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                m = cand[r][c]
                cnt = popcount(m)
                if cnt <= 1:
                    continue
                # More constrained peers first
                degree = 0
                for rr, cc in neighbors[r][c]:
                    if cand[rr][cc] & (cand[rr][cc] - 1):
                        degree += 1
                key = (cnt, -degree)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (r, c)
        return best

    def search():
        if is_solved():
            return True

        cell = select_branch_cell()
        if cell is None:
            return False
        r, c = cell

        # Value ordering: least-constraining-ish using peer impact
        vals = []
        for v in mask_to_sorted_values(cand[r][c]):
            bm = bit(v)
            impact = 0
            for rr, cc in neighbors[r][c]:
                if cand[rr][cc] & bm:
                    impact += 1
            vals.append((impact, v))
        vals.sort()

        for _, v in vals:
            state = clone_state()
            if assign(r, c, v) and propagate() and search():
                return True
            restore_state(state)
        return False

    if not search():
        return "No Solution"

    solved = [[cand[r][c].bit_length() for c in range(n)] for r in range(n)]
    return str(solved)

if __name__ == "__main__":
    print(solve(OBSERVATION))

