from collections import defaultdict

STAR = 1
EMPTY = -1
UNKNOWN = 0


def neighbors8(r, c, n):
    for dr in (-1, 0, 1):
        rr = r + dr
        if rr < 0 or rr >= n:
            continue
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            cc = c + dc
            if 0 <= cc < n:
                yield rr, cc


def solve(observation):
    grid = observation["data"]
    n = len(grid)
    if any(len(row) != n for row in grid):
        return "No Solution"

    regions = defaultdict(list)
    for r in range(n):
        for c in range(n):
            regions[grid[r][c]].append((r, c))
    region_ids = sorted(regions)

    # Precompute all valid 2-cell placements for each region.
    # Human-like region reasoning: each region must choose one non-touching pair.
    region_pairs = {}
    cell_to_regions = {}
    for rid in region_ids:
        cells = regions[rid]
        for cell in cells:
            cell_to_regions[cell] = rid
        pairs = []
        m = len(cells)
        for i in range(m):
            r1, c1 = cells[i]
            for j in range(i + 1, m):
                r2, c2 = cells[j]
                if max(abs(r1 - r2), abs(c1 - c2)) <= 1:
                    continue
                pairs.append(((r1, c1), (r2, c2)))
        if not pairs:
            return "No Solution"
        region_pairs[rid] = pairs

    # Conflict map: a star at cell forbids all touching cells.
    touch_map = {}
    for r in range(n):
        for c in range(n):
            touch_map[(r, c)] = set(neighbors8(r, c, n))

    all_cells = [(r, c) for r in range(n) for c in range(n)]

    def initial_state():
        return {
            "status": {cell: UNKNOWN for cell in all_cells},
            "row_stars": [0] * n,
            "col_stars": [0] * n,
            "region_stars": {rid: 0 for rid in region_ids},
            "active_pairs": {rid: list(region_pairs[rid]) for rid in region_ids},
        }

    def clone_state(state):
        return {
            "status": dict(state["status"]),
            "row_stars": state["row_stars"][:],
            "col_stars": state["col_stars"][:],
            "region_stars": dict(state["region_stars"]),
            "active_pairs": {rid: lst[:] for rid, lst in state["active_pairs"].items()},
        }

    def set_empty(state, cell):
        if state["status"][cell] == EMPTY:
            return True
        if state["status"][cell] == STAR:
            return False
        state["status"][cell] = EMPTY
        return True

    def set_star(state, cell):
        cur = state["status"][cell]
        if cur == STAR:
            return True
        if cur == EMPTY:
            return False
        r, c = cell
        rid = cell_to_regions[cell]
        if state["row_stars"][r] >= 2 or state["col_stars"][c] >= 2 or state["region_stars"][rid] >= 2:
            return False
        state["status"][cell] = STAR
        state["row_stars"][r] += 1
        state["col_stars"][c] += 1
        state["region_stars"][rid] += 1
        if state["row_stars"][r] > 2 or state["col_stars"][c] > 2 or state["region_stars"][rid] > 2:
            return False
        for nb in touch_map[cell]:
            if not set_empty(state, nb):
                return False
        return True

    def pair_compatible_with_state(state, rid, pair):
        a, b = pair
        sa = state["status"][a]
        sb = state["status"][b]
        if sa == EMPTY or sb == EMPTY:
            return False
        # region may already have stars elsewhere
        fixed = state["region_stars"][rid]
        in_pair_fixed = (1 if sa == STAR else 0) + (1 if sb == STAR else 0)
        if fixed > in_pair_fixed:
            return False

        # row/col feasibility
        rows_add = defaultdict(int)
        cols_add = defaultdict(int)
        for cell in pair:
            if state["status"][cell] != STAR:
                rows_add[cell[0]] += 1
                cols_add[cell[1]] += 1
        for rr, add in rows_add.items():
            if state["row_stars"][rr] + add > 2:
                return False
        for cc, add in cols_add.items():
            if state["col_stars"][cc] + add > 2:
                return False

        # touching with already fixed stars
        for cell in pair:
            if state["status"][cell] == STAR:
                continue
            for nb in touch_map[cell]:
                if state["status"].get(nb) == STAR:
                    return False
        return True

    def line_bounds_ok(state):
        # Strong human-like counting:
        # for each row/col, compute min/max stars still possible from remaining region pairs.
        row_possible = [0] * n
        col_possible = [0] * n

        # Cell-level immediate feasibility
        for r in range(n):
            if state["row_stars"][r] > 2:
                return False
        for c in range(n):
            if state["col_stars"][c] > 2:
                return False
        for rid in region_ids:
            if state["region_stars"][rid] > 2:
                return False
            if not state["active_pairs"][rid]:
                return False

        # Max possible occupancy by remaining region options
        for rid in region_ids:
            seen_rows = set()
            seen_cols = set()
            for a, b in state["active_pairs"][rid]:
                for cell in (a, b):
                    if state["status"][cell] != EMPTY:
                        seen_rows.add(cell[0])
                        seen_cols.add(cell[1])
            for rr in seen_rows:
                row_possible[rr] += 1
            for cc in seen_cols:
                col_possible[cc] += 1

        for r in range(n):
            need = 2 - state["row_stars"][r]
            if need < 0:
                return False
            # Count unknown cells that are still in some active pair of their region.
            can = 0
            for c in range(n):
                if state["status"][(r, c)] == EMPTY:
                    continue
                rid = cell_to_regions[(r, c)]
                if any((r, c) == x or (r, c) == y for x, y in state["active_pairs"][rid]):
                    can += 1
            if can < need:
                return False

        for c in range(n):
            need = 2 - state["col_stars"][c]
            if need < 0:
                return False
            can = 0
            for r in range(n):
                if state["status"][(r, c)] == EMPTY:
                    continue
                rid = cell_to_regions[(r, c)]
                if any((r, c) == x or (r, c) == y for x, y in state["active_pairs"][rid]):
                    can += 1
            if can < need:
                return False

        return True

    def propagate(state):
        changed = True
        while changed:
            changed = False

            # Filter region pair domains.
            for rid in region_ids:
                old = state["active_pairs"][rid]
                new = [p for p in old if pair_compatible_with_state(state, rid, p)]
                if not new:
                    return False
                if len(new) != len(old):
                    state["active_pairs"][rid] = new
                    changed = True

            # If a region already has 2 fixed stars, all others in region are empty,
            # and only pairs containing both fixed stars remain.
            for rid in region_ids:
                cells = regions[rid]
                rs = state["region_stars"][rid]
                if rs == 2:
                    star_cells = [cell for cell in cells if state["status"][cell] == STAR]
                    star_set = set(star_cells)
                    for cell in cells:
                        if cell not in star_set:
                            if not set_empty(state, cell):
                                return False
                    new_pairs = []
                    for p in state["active_pairs"][rid]:
                        if set(p) == star_set:
                            new_pairs.append(p)
                    if not new_pairs:
                        return False
                    if len(new_pairs) != len(state["active_pairs"][rid]):
                        state["active_pairs"][rid] = new_pairs
                        changed = True

            # Common-cell deductions within a region:
            # if every remaining pair uses a cell -> that cell is forced star.
            # if no remaining pair uses a cell -> that cell is forced empty.
            for rid in region_ids:
                pairs = state["active_pairs"][rid]
                counts = defaultdict(int)
                for a, b in pairs:
                    counts[a] += 1
                    counts[b] += 1
                total = len(pairs)
                for cell in regions[rid]:
                    cnt = counts.get(cell, 0)
                    if cnt == 0:
                        if not set_empty(state, cell):
                            return False
                        changed = True
                    elif cnt == total:
                        if not set_star(state, cell):
                            return False
                        changed = True

            # Single-pair region forces both stars.
            for rid in region_ids:
                pairs = state["active_pairs"][rid]
                if len(pairs) == 1:
                    a, b = pairs[0]
                    if not set_star(state, a):
                        return False
                    if not set_star(state, b):
                        return False
                    changed = True

            # Row/column exact-count deductions.
            for r in range(n):
                if state["row_stars"][r] > 2:
                    return False
                candidates = []
                for c in range(n):
                    cell = (r, c)
                    if state["status"][cell] == UNKNOWN:
                        rid = cell_to_regions[cell]
                        if any(cell == x or cell == y for x, y in state["active_pairs"][rid]):
                            candidates.append(cell)
                        else:
                            if not set_empty(state, cell):
                                return False
                            changed = True
                need = 2 - state["row_stars"][r]
                if need < 0 or len(candidates) < need:
                    return False
                if need == 0:
                    for cell in candidates:
                        if not set_empty(state, cell):
                            return False
                        changed = True
                elif len(candidates) == need:
                    for cell in candidates:
                        if not set_star(state, cell):
                            return False
                        changed = True

            for c in range(n):
                if state["col_stars"][c] > 2:
                    return False
                candidates = []
                for r in range(n):
                    cell = (r, c)
                    if state["status"][cell] == UNKNOWN:
                        rid = cell_to_regions[cell]
                        if any(cell == x or cell == y for x, y in state["active_pairs"][rid]):
                            candidates.append(cell)
                        else:
                            if not set_empty(state, cell):
                                return False
                            changed = True
                need = 2 - state["col_stars"][c]
                if need < 0 or len(candidates) < need:
                    return False
                if need == 0:
                    for cell in candidates:
                        if not set_empty(state, cell):
                            return False
                        changed = True
                elif len(candidates) == need:
                    for cell in candidates:
                        if not set_star(state, cell):
                            return False
                        changed = True

            # Region exact-count deductions using cells still appearing in some pair.
            for rid in region_ids:
                cells = regions[rid]
                candidates = []
                for cell in cells:
                    if state["status"][cell] == UNKNOWN:
                        if any(cell == x or cell == y for x, y in state["active_pairs"][rid]):
                            candidates.append(cell)
                        else:
                            if not set_empty(state, cell):
                                return False
                            changed = True
                need = 2 - state["region_stars"][rid]
                if need < 0 or len(candidates) < need:
                    return False
                if need == 0:
                    for cell in candidates:
                        if not set_empty(state, cell):
                            return False
                        changed = True
                elif len(candidates) == need:
                    for cell in candidates:
                        if not set_star(state, cell):
                            return False
                        changed = True

            if not line_bounds_ok(state):
                return False

        return True

    def solved(state):
        return (
            all(v == 2 for v in state["row_stars"])
            and all(v == 2 for v in state["col_stars"])
            and all(state["region_stars"][rid] == 2 for rid in region_ids)
        )

    def choose_branch(state):
        # Prefer smallest region domain > 1.
        best = None
        best_key = None
        for rid in region_ids:
            k = len(state["active_pairs"][rid])
            if 1 < k and (best is None or k < best_key):
                best = ("region", rid)
                best_key = k
        if best is not None:
            return best

        # Fallback: pick an undecided cell with strongest bias from region options.
        best_cell = None
        best_score = None
        for cell in all_cells:
            if state["status"][cell] != UNKNOWN:
                continue
            rid = cell_to_regions[cell]
            total = len(state["active_pairs"][rid])
            cnt = 0
            for a, b in state["active_pairs"][rid]:
                if cell == a or cell == b:
                    cnt += 1
            if 0 < cnt < total:
                score = abs(total - 2 * cnt)
                if best_score is None or score < best_score:
                    best_score = score
                    best_cell = cell
        if best_cell is not None:
            return ("cell", best_cell)
        return None

    def search(state):
        if not propagate(state):
            return None
        if solved(state):
            return state

        branch = choose_branch(state)
        if branch is None:
            return None

        kind, obj = branch

        if kind == "region":
            rid = obj
            # Try pairs with stronger row/col pressure first.
            def pair_score(pair):
                s = 0
                for r, c in pair:
                    s += (2 - state["row_stars"][r]) + (2 - state["col_stars"][c])
                return s

            pairs = sorted(state["active_pairs"][rid], key=pair_score)
            for pair in pairs:
                nxt = clone_state(state)
                nxt["active_pairs"][rid] = [pair]
                res = search(nxt)
                if res is not None:
                    return res
            return None

        cell = obj
        rid = cell_to_regions[cell]
        total = len(state["active_pairs"][rid])
        cnt = sum(1 for a, b in state["active_pairs"][rid] if cell == a or cell == b)

        # Branch on the more promising value first.
        options = []
        if cnt * 2 >= total:
            options = [STAR, EMPTY]
        else:
            options = [EMPTY, STAR]

        for value in options:
            nxt = clone_state(state)
            ok = set_star(nxt, cell) if value == STAR else set_empty(nxt, cell)
            if not ok:
                continue
            res = search(nxt)
            if res is not None:
                return res
        return None

    result = search(initial_state())
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if result["status"][(r, c)] == STAR:
                answer[r][c] = "S"
    return str(answer)


