    print(solve(OBSERVATION))

OBSERVATION = {'U': [2, 0, 0, 1, 0, 6], 'D': [0, 0, 2, 2, 3, 0], 'L': [4, 0, 3, 0, 2, 0], 'R': [0, 0, 0, 0, 0, 0]}

from itertools import permutations


def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c


def clue_ok(clue, seen):
    return clue == 0 or clue == seen


def solve(observation):
    U = observation['U']
    D = observation['D']
    L = observation['L']
    R = observation['R']
    n = len(U)

    nums = tuple(range(1, n + 1))
    all_perms = list(permutations(nums))

    # Precompute visibility for every permutation once.
    perm_lr = {}
    for p in all_perms:
        perm_lr[p] = (visible_count(p), visible_count(reversed(p)))

    # Row candidates by left/right clues.
    row_candidates = []
    for r in range(n):
        lc, rc = L[r], R[r]
        cands = [p for p in all_perms if clue_ok(lc, perm_lr[p][0]) and clue_ok(rc, perm_lr[p][1])]
        if not cands:
            return "No Solution"
        row_candidates.append(cands)

    # Column candidates by up/down clues.
    col_allowed = []
    for c in range(n):
        uc, dc = U[c], D[c]
        cands = [p for p in all_perms if clue_ok(uc, perm_lr[p][0]) and clue_ok(dc, perm_lr[p][1])]
        if not cands:
            return "No Solution"
        col_allowed.append(cands)

    # For fast feasibility checks:
    # column c, row r, value v -> set of permutation indices in col_allowed[c] with perm[r] == v
    col_value_sets = []
    for c in range(n):
        allowed = col_allowed[c]
        value_sets = [{v: set() for v in nums} for _ in range(n)]
        for idx, p in enumerate(allowed):
            for r, v in enumerate(p):
                value_sets[r][v].add(idx)
        col_value_sets.append(value_sets)

    # Initial row-to-column compatibility filtering:
    # remove row candidates that can never appear in at least one column at that row position.
    filtered_rows = []
    for r in range(n):
        kept = []
        for p in row_candidates[r]:
            ok = True
            for c, v in enumerate(p):
                if not col_value_sets[c][r][v]:
                    ok = False
                    break
            if ok:
                kept.append(p)
        if not kept:
            return "No Solution"
        filtered_rows.append(kept)
    row_candidates = filtered_rows

    # State.
    grid = [None] * n
    assigned = [False] * n
    row_masks = [0] * n  # not strictly needed, but can aid readability
    col_used = [0] * n   # bitmask of used values in each column
    all_idx_sets = [set(range(len(col_allowed[c]))) for c in range(n)]
    col_poss = [s.copy() for s in all_idx_sets]

    bit = [0] + [1 << i for i in range(n)]  # value v maps to bit[v-1] via bit[v-1]? easier below
    valbit = {v: 1 << (v - 1) for v in nums}

    # Simple propagation: whenever a row is assigned, column possibility sets shrink.
    # Search chooses the most constrained row next (fewest valid candidates under current state).
    def candidate_list_for_row(r):
        if assigned[r]:
            return [grid[r]]

        out = []
        for p in row_candidates[r]:
            ok = True
            for c, v in enumerate(p):
                b = valbit[v]
                if col_used[c] & b:
                    ok = False
                    break
                # Human-like clue consistency:
                # value at (r,c) must be achievable by some remaining column candidate.
                if not (col_poss[c] & col_value_sets[c][r][v]):
                    ok = False
                    break
            if ok:
                out.append(p)
        return out

    def place_row(r, p):
        old_col_poss = [None] * n
        changed_cols = []
        for c, v in enumerate(p):
            old_col_poss[c] = col_poss[c]
            newset = col_poss[c] & col_value_sets[c][r][v]
            if not newset:
                return None
            if newset is not col_poss[c]:
                changed_cols.append(c)
            col_poss[c] = newset
            col_used[c] |= valbit[v]

        assigned[r] = True
        grid[r] = p
        row_masks[r] = 1
        return old_col_poss

    def unplace_row(r, p, old_col_poss):
        assigned[r] = False
        grid[r] = None
        row_masks[r] = 0
        for c, v in enumerate(p):
            col_used[c] &= ~valbit[v]
            col_poss[c] = old_col_poss[c]

    def global_feasible():
        # Every unassigned row must still have at least one candidate.
        for r in range(n):
            if not assigned[r]:
                found = False
                for p in row_candidates[r]:
                    ok = True
                    for c, v in enumerate(p):
                        if (col_used[c] & valbit[v]) or not (col_poss[c] & col_value_sets[c][r][v]):
                            ok = False
                            break
                    if ok:
                        found = True
                        break
                if not found:
                    return False

        # Every column possibility set must remain non-empty and compatible with current used-values pattern.
        for c in range(n):
            if not col_poss[c]:
                return False
        return True

    def choose_row():
        best_r = None
        best_cands = None
        best_len = 10**9
        for r in range(n):
            if not assigned[r]:
                cands = candidate_list_for_row(r)
                ln = len(cands)
                if ln == 0:
                    return r, []
                if ln < best_len:
                    best_len = ln
                    best_r = r
                    best_cands = cands
                    if ln == 1:
                        break
        return best_r, best_cands

    def dfs():
        if all(assigned):
            # Full solution already guaranteed by row uniqueness and surviving column clue sets.
            return [list(row) for row in grid]

        r, cands = choose_row()
        if not cands:
            return None

        # Heuristic ordering:
        # try candidates that constrain columns the most.
        def score(p):
            s = 0
            for c, v in enumerate(p):
                s += len(col_poss[c] & col_value_sets[c][r][v])
            return s

        cands.sort(key=score)

        for p in cands:
            old = place_row(r, p)
            if old is None:
                # restore partial effects if needed
                for c, v in enumerate(p):
                    if old is not None and old[c] is not None:
                        col_poss[c] = old[c]
                    col_used[c] &= ~valbit[v]
                continue

            if global_feasible():
                ans = dfs()
                if ans is not None:
                    return ans

            unplace_row(r, p, old)

        return None

    ans = dfs()
    return str(ans) if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

