from collections import defaultdict, deque

def solve(observation):
    data = observation["data"]
    rows = len(data)
    cols = len(data[0]) if rows else 0

    def inb(r, c):
        return 0 <= r < rows and 0 <= c < cols

    nbrs = {}
    for r in range(rows):
        for c in range(cols):
            nbrs[(r, c)] = [
                (rr, cc)
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c) and inb(rr, cc)
            ]

    clues = {}
    unknown_cells = []
    for r in range(rows):
        for c in range(cols):
            if data[r][c] is None:
                unknown_cells.append((r, c))
            else:
                clues[(r, c)] = data[r][c]

    frontier = set()
    constraints = []
    for cell, clue in clues.items():
        scope = [n for n in nbrs[cell] if data[n[0]][n[1]] is None]
        s = frozenset(scope)
        if s:
            constraints.append([set(s), clue])
            frontier.update(s)
        else:
            if clue != 0:
                return "No Solution"

    unconstrained = [v for v in unknown_cells if v not in frontier]

    # Map frontier vars to dense ids.
    var_list = list(frontier)
    vid = {v: i for i, v in enumerate(var_list)}

    dense_constraints = []
    for scope, total in constraints:
        dense_constraints.append((frozenset(vid[v] for v in scope), total))

    # Build components on frontier variables via shared constraints.
    var_to_cons = defaultdict(list)
    for ci, (scope, _) in enumerate(dense_constraints):
        for v in scope:
            var_to_cons[v].append(ci)

    seen = set()
    components = []
    for v in range(len(var_list)):
        if v in seen:
            continue
        dq = deque([v])
        seen.add(v)
        comp_vars = set()
        comp_cons = set()
        while dq:
            x = dq.popleft()
            comp_vars.add(x)
            for ci in var_to_cons[x]:
                if ci not in comp_cons:
                    comp_cons.add(ci)
                    for y in dense_constraints[ci][0]:
                        if y not in seen:
                            seen.add(y)
                            dq.append(y)
        components.append((sorted(comp_vars), sorted(comp_cons)))

    def propagate(assign, comp_constraints, comp_var_to_cons):
        # assign: dict var -> 0/1
        changed = True
        while changed:
            changed = False

            # Direct single-constraint deductions.
            for ci, (scope, total) in enumerate(comp_constraints):
                mines = 0
                unassigned = []
                for v in scope:
                    av = assign.get(v, -1)
                    if av == 1:
                        mines += 1
                    elif av == -1:
                        unassigned.append(v)
                rem = total - mines
                if rem < 0 or rem > len(unassigned):
                    return False
                if rem == 0 and unassigned:
                    for v in unassigned:
                        if v in assign:
                            if assign[v] != 0:
                                return False
                        else:
                            assign[v] = 0
                            changed = True
                elif rem == len(unassigned) and unassigned:
                    for v in unassigned:
                        if v in assign:
                            if assign[v] != 1:
                                return False
                        else:
                            assign[v] = 1
                            changed = True

            # Subset-style deductions between reduced constraints.
            reduced = []
            by_size = defaultdict(list)
            for ci, (scope, total) in enumerate(comp_constraints):
                mines = 0
                rem_scope = set()
                for v in scope:
                    av = assign.get(v, -1)
                    if av == 1:
                        mines += 1
                    elif av == -1:
                        rem_scope.add(v)
                rem_total = total - mines
                if rem_total < 0 or rem_total > len(rem_scope):
                    return False
                if rem_scope:
                    fs = frozenset(rem_scope)
                    reduced.append((fs, rem_total))
                    by_size[len(fs)].append((fs, rem_total))

            # Deduplicate exact same reduced scopes keeping consistency.
            merged = {}
            for fs, t in reduced:
                if fs in merged and merged[fs] != t:
                    return False
                merged[fs] = t
            reduced = [(fs, t) for fs, t in merged.items()]

            # Pairwise subset checks.
            reduced.sort(key=lambda x: len(x[0]))
            nred = len(reduced)
            for i in range(nred):
                a_set, a_t = reduced[i]
                la = len(a_set)
                for j in range(i + 1, nred):
                    b_set, b_t = reduced[j]
                    if la > len(b_set):
                        break
                    if a_set.issubset(b_set):
                        diff = b_set - a_set
                        dt = b_t - a_t
                        if dt < 0 or dt > len(diff):
                            return False
                        if not diff:
                            continue
                        if dt == 0:
                            for v in diff:
                                if v in assign:
                                    if assign[v] != 0:
                                        return False
                                else:
                                    assign[v] = 0
                                    changed = True
                        elif dt == len(diff):
                            for v in diff:
                                if v in assign:
                                    if assign[v] != 1:
                                        return False
                                else:
                                    assign[v] = 1
                                    changed = True
        return True

    def choose_var(assign, comp_constraints):
        best_v = None
        best_key = None
        freq = defaultdict(int)
        min_scope = {}
        mine_pressure = defaultdict(int)
        for scope, total in comp_constraints:
            un = [v for v in scope if v not in assign]
            if not un:
                continue
            mines = sum(assign.get(v, 0) == 1 for v in scope if v in assign)
            rem = total - mines
            for v in un:
                freq[v] += 1
                s = len(un)
                if v not in min_scope or s < min_scope[v]:
                    min_scope[v] = s
                mine_pressure[v] += rem
        for v in freq:
            key = (min_scope[v], -freq[v], -mine_pressure[v], v)
            if best_key is None or key < best_key:
                best_key = key
                best_v = v
        return best_v

    def branch_values(v, assign, comp_constraints):
        # Mine-first when local pressure is high.
        pressure = 0.0
        count = 0
        for scope, total in comp_constraints:
            if v in scope:
                un = 0
                mines = 0
                for x in scope:
                    if x in assign:
                        if assign[x] == 1:
                            mines += 1
                    else:
                        un += 1
                rem = total - mines
                if un > 0:
                    pressure += rem / un
                    count += 1
        score = pressure / count if count else 0.0
        return (1, 0) if score >= 0.5 else (0, 1)

    def solve_component(comp_vars, comp_cons):
        comp_constraints = []
        comp_var_set = set(comp_vars)
        for ci in comp_cons:
            scope, total = dense_constraints[ci]
            scope2 = frozenset(v for v in scope if v in comp_var_set)
            comp_constraints.append((scope2, total))

        comp_var_to_cons = defaultdict(list)
        for ci, (scope, _) in enumerate(comp_constraints):
            for v in scope:
                comp_var_to_cons[v].append(ci)

        memo = set()

        def state_key(assign):
            items = tuple(sorted(assign.items()))
            return items

        def dfs(assign):
            if not propagate(assign, comp_constraints, comp_var_to_cons):
                return None
            key = state_key(assign)
            if key in memo:
                return None
            if len(assign) == len(comp_vars):
                return assign
            v = choose_var(assign, comp_constraints)
            if v is None:
                return assign
            for val in branch_values(v, assign, comp_constraints):
                new_assign = dict(assign)
                new_assign[v] = val
                res = dfs(new_assign)
                if res is not None:
                    return res
            memo.add(key)
            return None

        return dfs({})

    global_assign = {}
    for comp_vars, comp_cons in components:
        res = solve_component(comp_vars, comp_cons)
        if res is None:
            return "No Solution"
        global_assign.update(res)

    ans = [[None for _ in range(cols)] for _ in range(rows)]
    for cell, i in vid.items():
        if global_assign.get(i, 0) == 1:
            ans[cell[0]][cell[1]] = 'F'

    # Unconstrained cells remain None; if a puzzle instance leaves them unconstrained,
    # any mine placement there would be non-unique and thus not logically forced.
    for r, c in unconstrained:
        ans[r][c] = None

    # Final verification.
    for (r, c), clue in clues.items():
        cnt = 0
        for rr, cc in nbrs[(r, c)]:
            if ans[rr][cc] == 'F':
                cnt += 1
        if cnt != clue:
            return "No Solution"

    return repr(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

