# General Akari / Light Up solver with strong propagation and bounded search.
# Board encoding in observation["data"]:
#   None -> white cell
#   -1   -> black unnumbered
#   0..4 -> black numbered

from copy import deepcopy

def solve(observation):
    data = observation["data"]
    n = len(data)

    white_cells = []
    black_numbered = []
    black_all = set()

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                white_cells.append((r, c))
            else:
                black_all.add((r, c))
                if v != -1:
                    black_numbered.append((r, c, v))

    white_set = set(white_cells)

    # Precompute line-of-sight peers and illumination candidates.
    visible = {}
    candidates_for_cover = {}

    def ray_cells(r, c, dr, dc):
        rr, cc = r + dr, c + dc
        out = []
        while 0 <= rr < n and 0 <= cc < n and (rr, cc) not in black_all:
            out.append((rr, cc))
            rr += dr
            cc += dc
        return out

    for cell in white_cells:
        r, c = cell
        peers = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            peers.extend(ray_cells(r, c, dr, dc))
        visible[cell] = tuple(peers)
        candidates_for_cover[cell] = tuple([cell] + peers)

    adj_white = {}
    for r, c, num in black_numbered:
        lst = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if (rr, cc) in white_set:
                lst.append((rr, cc))
        adj_white[(r, c)] = tuple(lst)

    # State:
    # bulbs: set of bulb cells
    # banned: white cells confirmed non-bulb
    # lit_count[cell]: number of bulbs illuminating the cell, counting self if bulb
    class State:
        __slots__ = ("bulbs", "banned", "lit_count")

        def __init__(self):
            self.bulbs = set()
            self.banned = set()
            self.lit_count = {cell: 0 for cell in white_cells}

        def clone(self):
            s = State()
            s.bulbs = set(self.bulbs)
            s.banned = set(self.banned)
            s.lit_count = dict(self.lit_count)
            return s

    def is_lit(state, cell):
        return state.lit_count[cell] > 0

    def can_place_bulb(state, cell):
        if cell in state.banned or cell in state.bulbs:
            return False
        # No visible bulb.
        for p in visible[cell]:
            if p in state.bulbs:
                return False
        # Numbered black upper-bound feasibility.
        r, c = cell
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < n and data[rr][cc] not in (None, -1):
                num = data[rr][cc]
                adj = adj_white[(rr, cc)]
                bulbs_now = sum((x in state.bulbs) for x in adj)
                if bulbs_now + 1 > num:
                    return False
        return True

    def place_bulb(state, cell):
        if not can_place_bulb(state, cell):
            return False
        state.bulbs.add(cell)
        state.lit_count[cell] += 1
        for p in visible[cell]:
            state.lit_count[p] += 1
        # Bulb cell and all visible cells cannot contain another bulb.
        state.banned.add(cell)
        for p in visible[cell]:
            state.banned.add(p)
        return True

    def ban_cell(state, cell):
        if cell in state.bulbs:
            return False
        state.banned.add(cell)
        return True

    def feasible_cover_sources(state, target):
        # Cells that could still host a bulb to illuminate target.
        out = []
        for src in candidates_for_cover[target]:
            if src in state.bulbs:
                return [src]
            if can_place_bulb(state, src):
                out.append(src)
        return out

    def check_numbered_consistency(state):
        for r, c, num in black_numbered:
            adj = adj_white[(r, c)]
            bulbs_now = sum((x in state.bulbs) for x in adj)
            free = sum((x not in state.banned and x not in state.bulbs and can_place_bulb(state, x)) for x in adj)
            if bulbs_now > num:
                return False
            if bulbs_now + free < num:
                return False
        return True

    def check_cover_consistency(state):
        for cell in white_cells:
            if is_lit(state, cell):
                continue
            if not feasible_cover_sources(state, cell):
                return False
        return True

    def propagate(state):
        changed = True
        while changed:
            changed = False

            # Numbered-cell deductions.
            for r, c, num in black_numbered:
                adj = adj_white[(r, c)]
                bulbs_now = [x for x in adj if x in state.bulbs]
                undecided = [x for x in adj if x not in state.bulbs and x not in state.banned]
                if len(bulbs_now) > num:
                    return None
                if len(bulbs_now) + len(undecided) < num:
                    return None

                # If satisfied, all remaining adjacent whites are non-bulbs.
                if len(bulbs_now) == num:
                    for x in undecided:
                        if x not in state.banned:
                            if not ban_cell(state, x):
                                return None
                            changed = True

                # If all undecided must be bulbs.
                elif len(bulbs_now) + len(undecided) == num:
                    for x in undecided:
                        if x not in state.bulbs:
                            if not place_bulb(state, x):
                                return None
                            changed = True

            # Any unlit cell with a single feasible illumination source forces a bulb there.
            for cell in white_cells:
                if is_lit(state, cell):
                    continue
                srcs = feasible_cover_sources(state, cell)
                if not srcs:
                    return None
                if len(srcs) == 1:
                    src = srcs[0]
                    if src not in state.bulbs:
                        if not place_bulb(state, src):
                            return None
                        changed = True

            # Any white cell that can no longer host a bulb but is not lit must still have another source.
            # This is mainly a consistency checkpoint.
            if not check_numbered_consistency(state):
                return None
            if not check_cover_consistency(state):
                return None

        return state

    def solved(state):
        if len(state.bulbs) == 0 and len(white_cells) > 0:
            return False
        for cell in white_cells:
            if not is_lit(state, cell):
                return False
        for r, c, num in black_numbered:
            if sum((x in state.bulbs) for x in adj_white[(r, c)]) != num:
                return False
        return True

    def choose_branch(state):
        # Most constrained branching:
        # 1) unlit white cell with minimum feasible cover sources
        # 2) numbered cell with tight adjacency choices
        best = None

        for cell in white_cells:
            if is_lit(state, cell):
                continue
            srcs = feasible_cover_sources(state, cell)
            if len(srcs) == 0:
                return ("dead", cell, [])
            if best is None or len(srcs) < len(best[2]):
                best = ("cover", cell, srcs)
                if len(srcs) == 2:
                    break

        if best is not None:
            return best

        # Fallback: choose a still-decidable cell near constraints.
        cand_cells = []
        for cell in white_cells:
            if cell in state.bulbs or cell in state.banned:
                continue
            if can_place_bulb(state, cell):
                pressure = 0
                r, c = cell
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n and data[rr][cc] not in (None, -1):
                        pressure += 1
                cand_cells.append((pressure, -len(candidates_for_cover[cell]), cell))
        if not cand_cells:
            return None
        cand_cells.sort(reverse=True)
        return ("binary", cand_cells[0][2], None)

    def search(state):
        state = propagate(state)
        if state is None:
            return None
        if solved(state):
            return state

        branch = choose_branch(state)
        if branch is None:
            return None
        if branch[0] == "dead":
            return None

        if branch[0] == "cover":
            _, target, srcs = branch
            # Try forcing one possible source to be the illuminating bulb.
            # Prefer the source that illuminates the most currently unlit cells.
            scored = []
            for src in srcs:
                score = sum((not is_lit(state, x)) for x in [src] + list(visible[src]))
                scored.append((-score, src))
            scored.sort()
            for _, src in scored:
                s2 = state.clone()
                if place_bulb(s2, src):
                    ans = search(s2)
                    if ans is not None:
                        return ans
            return None

        # binary branch on a candidate cell: bulb vs no bulb
        _, cell, _ = branch

        s2 = state.clone()
        if place_bulb(s2, cell):
            ans = search(s2)
            if ans is not None:
                return ans

        s3 = state.clone()
        if ban_cell(s3, cell):
            ans = search(s3)
            if ans is not None:
                return ans

        return None

    init = State()
    result = search(init)
    if result is None:
        return "No Solution"

    out = [[None for _ in range(n)] for _ in range(n)]
    for r, c in result.bulbs:
        out[r][c] = 'B'
    return str(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

