from ast import literal_eval

def solve(observation):
    data = observation["data"]
    n = len(data)
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def min_value(mask):
        return (mask & -mask).bit_length()

    def max_value(mask):
        return mask.bit_length()

    def values(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    idx = lambda r, c: r * n + c
    rc = lambda k: divmod(k, n)

    row_units = [[idx(r, c) for c in range(n)] for r in range(n)]
    col_units = [[idx(r, c) for r in range(n)] for c in range(n)]

    peers = []
    for r in range(n):
        for c in range(n):
            s = set(row_units[r] + col_units[c])
            s.remove(idx(r, c))
            peers.append(tuple(sorted(s)))

    h_raw = observation.get("horizontal", {})
    v_raw = observation.get("vertical", {})

    def parse_key(s):
        return literal_eval(s)

    # Build inequalities as pairs (a, b) meaning a < b.
    def build_ineqs(horizontal_standard=True, vertical_caret_means_top_less=True):
        ineqs = []

        for k, sym in h_raw.items():
            r, cc = parse_key(k)
            c = int(cc - 0.5)
            a = idx(int(r), c)
            b = idx(int(r), c + 1)
            if horizontal_standard:
                if sym == "<":
                    ineqs.append((a, b))
                else:
                    ineqs.append((b, a))
            else:
                if sym == "<":
                    ineqs.append((b, a))
                else:
                    ineqs.append((a, b))

        for k, sym in v_raw.items():
            rr, c = parse_key(k)
            r = int(rr - 0.5)
            a = idx(r, int(c))
            b = idx(r + 1, int(c))
            if vertical_caret_means_top_less:
                if sym == "^":
                    ineqs.append((a, b))
                else:
                    ineqs.append((b, a))
            else:
                if sym == "^":
                    ineqs.append((b, a))
                else:
                    ineqs.append((a, b))

        return ineqs

    # Exact arc consistency for a < b.
    def filter_lt(ma, mb):
        if not ma or not mb:
            return 0, 0, False
        max_b = max_value(mb)
        min_a = min_value(ma)

        new_a = 0
        ta = ma
        while ta:
            ba = ta & -ta
            va = ba.bit_length()
            if va < max_b:
                new_a |= ba
            ta ^= ba

        new_b = 0
        tb = mb
        while tb:
            bb = tb & -tb
            vb = bb.bit_length()
            if vb > min_a:
                new_b |= bb
            tb ^= bb

        return new_a, new_b, (new_a != ma or new_b != mb)

    def propagate(domains, ineqs):
        changed = True
        while changed:
            changed = False

            # 1) Row/column used-value elimination and contradiction checks.
            for units in (row_units, col_units):
                for unit in units:
                    seen = 0
                    for k in unit:
                        m = domains[k]
                        if m == 0:
                            return False
                        if m & (m - 1) == 0:
                            if seen & m:
                                return False
                            seen |= m
                    if seen:
                        for k in unit:
                            m = domains[k]
                            if m & (m - 1):
                                nm = m & ~seen
                                if nm != m:
                                    if nm == 0:
                                        return False
                                    domains[k] = nm
                                    changed = True

                    # Hidden singles.
                    for v in range(1, n + 1):
                        b = bit(v)
                        spots = []
                        for k in unit:
                            if domains[k] & b:
                                spots.append(k)
                                if len(spots) > 1:
                                    break
                        if len(spots) == 0:
                            return False
                        if len(spots) == 1 and domains[spots[0]] != b:
                            domains[spots[0]] = b
                            changed = True

            # 2) Peer elimination from singles.
            singles = [k for k, m in enumerate(domains) if m & (m - 1) == 0]
            for k in singles:
                m = domains[k]
                for p in peers[k]:
                    pm = domains[p]
                    if pm & m:
                        if pm == m:
                            return False
                        nm = pm & ~m
                        if nm == 0:
                            return False
                        if nm != pm:
                            domains[p] = nm
                            changed = True

            # 3) Inequality propagation.
            for a, b in ineqs:
                ma, mb = domains[a], domains[b]
                na, nb, ch = filter_lt(ma, mb)
                if na == 0 or nb == 0:
                    return False
                if ch:
                    domains[a], domains[b] = na, nb
                    changed = True

            # 4) Small naked subsets in rows/cols (pairs/triples), human-like pruning.
            for units in (row_units, col_units):
                for unit in units:
                    buckets = {}
                    for k in unit:
                        m = domains[k]
                        pc = popcount(m)
                        if 2 <= pc <= 3:
                            buckets.setdefault(m, []).append(k)
                    for m, cells in buckets.items():
                        pc = popcount(m)
                        if len(cells) == pc:
                            for k in unit:
                                if k not in cells:
                                    nm = domains[k] & ~m
                                    if nm == 0:
                                        return False
                                    if nm != domains[k]:
                                        domains[k] = nm
                                        changed = True

        return True

    def solved(domains):
        return all(m and (m & (m - 1) == 0) for m in domains)

    def domain_score(domains, k, ineq_adj):
        # Least-constraining value heuristic.
        scores = []
        r, c = rc(k)
        peer_set = set(peers[k])
        for v in values(domains[k]):
            b = bit(v)
            impact = 0
            for p in peer_set:
                if domains[p] & b:
                    impact += 1
            for p, is_left in ineq_adj[k]:
                pm = domains[p]
                if is_left:
                    # k < p
                    t = 0
                    for pv in values(pm):
                        if pv <= v:
                            t += 1
                    impact += t
                else:
                    # p < k
                    t = 0
                    for pv in values(pm):
                        if pv >= v:
                            t += 1
                    impact += t
            scores.append((impact, v))
        scores.sort()
        return [v for _, v in scores]

    def search(domains, ineqs, ineq_adj):
        if not propagate(domains, ineqs):
            return None
        if solved(domains):
            return domains

        # MRV + degree tie-break.
        best = None
        best_key = None
        for k, m in enumerate(domains):
            pc = popcount(m)
            if pc > 1:
                degree = 0
                for p in peers[k]:
                    if popcount(domains[p]) > 1:
                        degree += 1
                degree += len(ineq_adj[k])
                key = (pc, -degree)
                if best is None or key < best_key:
                    best = k
                    best_key = key

        if best is None:
            return None

        for v in domain_score(domains, best, ineq_adj):
            new_domains = domains[:]
            new_domains[best] = bit(v)
            result = search(new_domains, ineqs, ineq_adj)
            if result is not None:
                return result
        return None

    # Try possible global sign conventions to stay robust to image-notation ambiguity.
    conventions = [
        (True, True),
        (True, False),
        (False, True),
        (False, False),
    ]

    for horizontal_standard, vertical_caret_means_top_less in conventions:
        ineqs = build_ineqs(horizontal_standard, vertical_caret_means_top_less)

        # Quick adjacency for value ordering.
        ineq_adj = [[] for _ in range(n * n)]
        for a, b in ineqs:
            ineq_adj[a].append((b, True))   # a < b
            ineq_adj[b].append((a, False))  # a < b, so for b it's p < k

        domains = [full] * (n * n)
        ok = True
        for r in range(n):
            for c in range(n):
                v = data[r][c]
                if v is not None:
                    if not (1 <= v <= n):
                        ok = False
                        break
                    domains[idx(r, c)] = bit(v)
            if not ok:
                break
        if not ok:
            continue

        result = search(domains, ineqs, ineq_adj)
        if result is not None:
            grid = []
            for r in range(n):
                row = []
                for c in range(n):
                    row.append(min_value(result[idx(r, c)]))
                grid.append(row)
            return str(grid)

    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

