from collections import defaultdict

def solve(observation):
    region_grid = observation["region"]
    row_target = observation["row_water_counts"]
    col_target = observation["col_water_counts"]

    R = len(region_grid)
    C = len(region_grid[0])

    # Build regions
    regions = defaultdict(list)
    for r in range(R):
        for c in range(C):
            regions[region_grid[r][c]].append((r, c))
    region_ids = sorted(regions)

    # For each region, build all human-like "water level" patterns:
    # choose 0..k lowest occupied rows (from bottom upward) to be water.
    region_patterns = {}
    region_pattern_row_add = {}
    region_pattern_col_add = {}
    region_pattern_cells = {}

    for rid in region_ids:
        cells = regions[rid]
        rows_present = sorted({r for r, _ in cells})
        row_to_cells = defaultdict(list)
        for r, c in cells:
            row_to_cells[r].append(c)

        patterns = []
        row_adds = []
        col_adds = []
        cell_sets = []

        # Dry pattern
        dry_cells = set()
        patterns.append(0)
        row_adds.append(defaultdict(int))
        col_adds.append([0] * C)
        cell_sets.append(dry_cells)

        # Fill from bottom by occupied row-bands
        for k in range(1, len(rows_present) + 1):
            filled_rows = set(rows_present[-k:])
            filled = {(r, c) for (r, c) in cells if r in filled_rows}
            ra = defaultdict(int)
            ca = [0] * C
            for r, c in filled:
                ra[r] += 1
                ca[c] += 1
            patterns.append(k)
            row_adds.append(ra)
            col_adds.append(ca)
            cell_sets.append(filled)

        region_patterns[rid] = list(range(len(patterns)))
        region_pattern_row_add[rid] = row_adds
        region_pattern_col_add[rid] = col_adds
        region_pattern_cells[rid] = cell_sets

    # Incidence lists to speed pruning
    row_regions = defaultdict(list)
    col_regions = defaultdict(list)
    for rid in region_ids:
        seen_rows = set()
        seen_cols = set()
        for r, c in regions[rid]:
            seen_rows.add(r)
            seen_cols.add(c)
        for r in seen_rows:
            row_regions[r].append(rid)
        for c in seen_cols:
            col_regions[c].append(rid)

    def domain_minmax_row(domains, r):
        total_min = 0
        total_max = 0
        for rid in row_regions[r]:
            vals = [region_pattern_row_add[rid][p].get(r, 0) for p in domains[rid]]
            total_min += min(vals)
            total_max += max(vals)
        return total_min, total_max

    def domain_minmax_col(domains, c):
        total_min = 0
        total_max = 0
        for rid in col_regions[c]:
            vals = [region_pattern_col_add[rid][p][c] for p in domains[rid]]
            total_min += min(vals)
            total_max += max(vals)
        return total_min, total_max

    def propagate(domains):
        # Aggressive deduction by row/column feasibility.
        changed = True
        while changed:
            changed = False

            # Global row bounds
            for r in range(R):
                mn, mx = domain_minmax_row(domains, r)
                if row_target[r] < mn or row_target[r] > mx:
                    return None

            # Global col bounds
            for c in range(C):
                mn, mx = domain_minmax_col(domains, c)
                if col_target[c] < mn or col_target[c] > mx:
                    return None

            # Prune per row
            for r in range(R):
                tgt = row_target[r]
                involved = row_regions[r]
                if not involved:
                    if tgt != 0:
                        return None
                    continue

                # Precompute others' min/max for each region in this row
                row_contrib_cache = {}
                row_min = {}
                row_max = {}
                for rid in involved:
                    vals = [region_pattern_row_add[rid][p].get(r, 0) for p in domains[rid]]
                    row_contrib_cache[rid] = vals
                    row_min[rid] = min(vals)
                    row_max[rid] = max(vals)

                total_min = sum(row_min.values())
                total_max = sum(row_max.values())

                for rid in involved:
                    other_min = total_min - row_min[rid]
                    other_max = total_max - row_max[rid]
                    new_dom = set()
                    for p in domains[rid]:
                        v = region_pattern_row_add[rid][p].get(r, 0)
                        if other_min + v <= tgt <= other_max + v:
                            new_dom.add(p)
                    if not new_dom:
                        return None
                    if new_dom != domains[rid]:
                        domains[rid] = new_dom
                        changed = True

            # Prune per column
            for c in range(C):
                tgt = col_target[c]
                involved = col_regions[c]
                if not involved:
                    if tgt != 0:
                        return None
                    continue

                col_min = {}
                col_max = {}
                for rid in involved:
                    vals = [region_pattern_col_add[rid][p][c] for p in domains[rid]]
                    col_min[rid] = min(vals)
                    col_max[rid] = max(vals)

                total_min = sum(col_min.values())
                total_max = sum(col_max.values())

                for rid in involved:
                    other_min = total_min - col_min[rid]
                    other_max = total_max - col_max[rid]
                    new_dom = set()
                    for p in domains[rid]:
                        v = region_pattern_col_add[rid][p][c]
                        if other_min + v <= tgt <= other_max + v:
                            new_dom.add(p)
                    if not new_dom:
                        return None
                    if new_dom != domains[rid]:
                        domains[rid] = new_dom
                        changed = True

        return domains

    def choose_region(domains):
        # Minimum remaining values, tie-broken by total impact.
        best = None
        best_key = None
        for rid in region_ids:
            if len(domains[rid]) > 1:
                impact = len({r for r, _ in regions[rid]}) + len({c for _, c in regions[rid]})
                key = (len(domains[rid]), -impact, rid)
                if best_key is None or key < best_key:
                    best_key = key
                    best = rid
        return best

    def build_grid(assignments):
        out = [[None for _ in range(C)] for _ in range(R)]
        for rid, p in assignments.items():
            for r, c in region_pattern_cells[rid][p]:
                out[r][c] = 'W'
        return out

    def final_check(assignments):
        grid = build_grid(assignments)
        for r in range(R):
            if sum(1 for c in range(C) if grid[r][c] == 'W') != row_target[r]:
                return None
        for c in range(C):
            if sum(1 for r in range(R) if grid[r][c] == 'W') != col_target[c]:
                return None
        return grid

    def search(domains):
        domains = {rid: set(v) for rid, v in domains.items()}
        domains = propagate(domains)
        if domains is None:
            return None

        if all(len(domains[rid]) == 1 for rid in region_ids):
            assignments = {rid: next(iter(domains[rid])) for rid in region_ids}
            return final_check(assignments)

        rid = choose_region(domains)
        # Least-commitment order: smaller total water first, often matches human deduction.
        options = sorted(
            domains[rid],
            key=lambda p: (
                sum(region_pattern_row_add[rid][p].values()),
                sum(region_pattern_col_add[rid][p]),
                p
            )
        )

        for p in options:
            new_domains = {k: set(v) for k, v in domains.items()}
            new_domains[rid] = {p}
            res = search(new_domains)
            if res is not None:
                return res
        return None

    domains = {rid: set(region_patterns[rid]) for rid in region_ids}
    ans = search(domains)
    if ans is None:
        return "No Solution"
    return repr(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

