# Solver for the "3x3 neighborhood count" black/white puzzle.
# A numbered cell gives the exact count of black cells in its 3x3 neighborhood, including itself.

from collections import defaultdict, deque

def solve(observation):
    data = observation['data']
    if not data or not data[0]:
        return str([])

    h = len(data)
    w = len(data[0])
    n = h * w

    def vid(r, c):
        return r * w + c

    def rc(v):
        return divmod(v, w)

    # Build constraints from numbered cells.
    constraints = []
    cell_to_constraints = [[] for _ in range(n)]

    for r in range(h):
        for c in range(w):
            clue = data[r][c]
            if clue is None:
                continue
            vars_ = []
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    vars_.append(vid(rr, cc))
            idx = len(constraints)
            constraints.append((tuple(sorted(vars_)), clue))
            for v in vars_:
                cell_to_constraints[v].append(idx)

    # Quick impossible clues.
    for vars_, clue in constraints:
        if clue < 0 or clue > len(vars_):
            return "No Solution"

    # Domains: -1 unknown, 0 white, 1 black.
    initial = [-1] * n

    def assign(state, v, val, queue):
        cur = state[v]
        if cur == val:
            return True
        if cur != -1:
            return False
        state[v] = val
        for ci in cell_to_constraints[v]:
            queue.append(ci)
        return True

    def constraint_status(state, ci):
        vars_, target = constraints[ci]
        black = 0
        unknown = []
        for v in vars_:
            sv = state[v]
            if sv == 1:
                black += 1
            elif sv == -1:
                unknown.append(v)
        return black, unknown, target

    def propagate(state):
        # Human-like propagation:
        # 1) local min/max on each clue
        # 2) saturation: if residual target is 0 or all unknowns must be black
        # 3) subset-difference reasoning between residual constraint variable sets
        queue = deque(range(len(constraints)))
        in_queue = [True] * len(constraints)

        while queue:
            ci = queue.popleft()
            in_queue[ci] = False

            black, unknown, target = constraint_status(state, ci)
            need = target - black
            u = len(unknown)

            # Basic contradiction checks.
            if need < 0 or need > u:
                return False

            # Saturation rules.
            if need == 0:
                for v in unknown:
                    if not assign(state, v, 0, queue):
                        return False
            elif need == u:
                for v in unknown:
                    if not assign(state, v, 1, queue):
                        return False

            # Subset rules against nearby constraints.
            vars1 = set(unknown)
            need1 = need
            if not vars1:
                continue

            related = set()
            for v in vars1:
                related.update(cell_to_constraints[v])

            for cj in related:
                if cj == ci:
                    continue
                black2, unknown2, target2 = constraint_status(state, cj)
                need2 = target2 - black2
                u2 = len(unknown2)

                if need2 < 0 or need2 > u2:
                    return False

                vars2 = set(unknown2)

                if not vars2:
                    continue

                # If same residual set, residual targets must match.
                if vars1 == vars2:
                    if need1 != need2:
                        return False
                    continue

                # Subset reasoning: if A ⊆ B, then sum(B\A) = needB - needA.
                if vars1.issubset(vars2):
                    diff = vars2 - vars1
                    dneed = need2 - need1
                    if dneed < 0 or dneed > len(diff):
                        return False
                    if diff:
                        if dneed == 0:
                            for v in diff:
                                if not assign(state, v, 0, queue):
                                    return False
                        elif dneed == len(diff):
                            for v in diff:
                                if not assign(state, v, 1, queue):
                                    return False

                elif vars2.issubset(vars1):
                    diff = vars1 - vars2
                    dneed = need1 - need2
                    if dneed < 0 or dneed > len(diff):
                        return False
                    if diff:
                        if dneed == 0:
                            for v in diff:
                                if not assign(state, v, 0, queue):
                                    return False
                        elif dneed == len(diff):
                            for v in diff:
                                if not assign(state, v, 1, queue):
                                    return False

            # Re-queue newly affected constraints already handled through assign(queue),
            # but if no assignments happened, this still ensures local consistency only.

        # Final consistency check.
        for ci in range(len(constraints)):
            black, unknown, target = constraint_status(state, ci)
            need = target - black
            if need < 0 or need > len(unknown):
                return False

        return True

    def solved(state):
        return all(v != -1 for v in state)

    def choose_var(state):
        # Most-constrained unknown cell: involved in clues with the smallest residual slack.
        best_v = None
        best_key = None

        for v in range(n):
            if state[v] != -1:
                continue

            infos = []
            for ci in cell_to_constraints[v]:
                black, unknown, target = constraint_status(state, ci)
                need = target - black
                u = len(unknown)
                # tighter constraints first
                slack = min(need, u - need)
                infos.append((slack, u, len(constraints[ci][0])))

            if infos:
                infos.sort()
                key = (infos[0][0], infos[0][1], -len(infos))
            else:
                key = (10**9, 10**9, 0)

            if best_key is None or key < best_key:
                best_key = key
                best_v = v

        return best_v

    def value_order(state, v):
        # Try value preferred by local clues.
        score_black = 0
        score_white = 0

        for ci in cell_to_constraints[v]:
            black, unknown, target = constraint_status(state, ci)
            need = target - black
            u = len(unknown)
            if u <= 0:
                continue
            # Higher need/u favors black.
            score_black += need
            score_white += (u - need)

        if score_black > score_white:
            return (1, 0)
        return (0, 1)

    def dfs(state):
        if not propagate(state):
            return None
        if solved(state):
            return state

        v = choose_var(state)
        if v is None:
            return state

        for val in value_order(state, v):
            new_state = state[:]
            q = deque()
            if assign(new_state, v, val, q):
                result = dfs(new_state)
                if result is not None:
                    return result
        return None

    result = dfs(initial)
    if result is None:
        return "No Solution"

    answer = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append('B' if result[vid(r, c)] == 1 else None)
        answer.append(row)
    return str(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 2, None, 3, None, 1, None], [2, None, None, None, None, None, None], [None, None, None, None, 4, None, 4], [None, None, None, None, None, None, None], [None, 1, None, None, None, None, None], [None, None, None, None, 2, None, None], [3, None, None, 3, None, None, 3]]}

from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)

    islands = []
    pos_to_idx = {}
    for r in range(n):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                pos_to_idx[(r, c)] = len(islands)
                islands.append((r, c, data[r][c]))

    m = len(islands)
    if m == 0:
        return "{}"

    # Build visibility edges.
    edges = []
    edge_index = {}
    incident = [[] for _ in range(m)]

    # Horizontal visibility
    for r in range(n):
        last = None
        for c in range(len(data[r])):
            if data[r][c] is not None:
                if last is not None:
                    a = pos_to_idx[(r, last)]
                    b = pos_to_idx[(r, c)]
                    idx = len(edges)
                    edges.append((a, b, 'H', r, last, c))
                    edge_index[(min(a, b), max(a, b))] = idx
                    incident[a].append(idx)
                    incident[b].append(idx)
                last = c

    # Vertical visibility
    for c in range(len(data[0])):
        last = None
        for r in range(n):
            if data[r][c] is not None:
                if last is not None:
                    a = pos_to_idx[(last, c)]
                    b = pos_to_idx[(r, c)]
                    idx = len(edges)
                    edges.append((a, b, 'V', c, last, r))
                    edge_index[(min(a, b), max(a, b))] = idx
                    incident[a].append(idx)
                    incident[b].append(idx)
                last = r

    ecount = len(edges)

    # Crossing relationships.
    crossings = [[] for _ in range(ecount)]
    for i, ei in enumerate(edges):
        ai, bi, oi, fixi, s1i, s2i = ei
        if oi != 'H':
            continue
        ri = fixi
        c1i, c2i = s1i, s2i
        for j, ej in enumerate(edges):
            aj, bj, oj, fixj, s1j, s2j = ej
            if oj != 'V':
                continue
            cj = fixj
            r1j, r2j = s1j, s2j
            if c1i < cj < c2i and r1j < ri < r2j:
                crossings[i].append(j)
                crossings[j].append(i)

    degrees = [v for _, _, v in islands]

    # Initial per-edge upper bounds from endpoint demands.
    init_min = [0] * ecount
    init_max = [min(2, degrees[a], degrees[b]) for a, b, *_ in edges]

    # Small utilities.
    def clone_state(state):
        mn, mx = state
        return (mn[:], mx[:])

    def island_bounds(mn, mx, node):
        smin = 0
        smax = 0
        for e in incident[node]:
            smin += mn[e]
            smax += mx[e]
        return smin, smax

    def possible_graph_connected(mx):
        seen = [False] * m
        q = deque([0])
        seen[0] = True
        while q:
            u = q.popleft()
            for e in incident[u]:
                if mx[e] <= 0:
                    continue
                a, b = edges[e][0], edges[e][1]
                v = b if a == u else a
                if not seen[v]:
                    seen[v] = True
                    q.append(v)
        return all(seen)

    def forced_components(mn):
        parent = list(range(m))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra

        for e in range(ecount):
            if mn[e] > 0:
                a, b = edges[e][0], edges[e][1]
                union(a, b)

        comps = {}
        for i in range(m):
            r = find(i)
            comps.setdefault(r, []).append(i)
        return list(comps.values())

    def check_connectivity_pruning(mn, mx):
        # All islands must still be connectable through edges with positive max.
        if not possible_graph_connected(mx):
            return False

        # No closed forced-connected component may exist before completion.
        comps = forced_components(mn)
        if len(comps) > 1:
            comp_id = {}
            for k, comp in enumerate(comps):
                for x in comp:
                    comp_id[x] = k
            outgoing_possible = [False] * len(comps)
            for e in range(ecount):
                if mx[e] <= 0:
                    continue
                a, b = edges[e][0], edges[e][1]
                ca, cb = comp_id[a], comp_id[b]
                if ca != cb:
                    outgoing_possible[ca] = True
                    outgoing_possible[cb] = True
            for k, comp in enumerate(comps):
                if len(comp) < m and not outgoing_possible[k]:
                    return False

        # If all degrees are fully assigned, network must be single connected component.
        complete = True
        for i in range(m):
            smin, smax = island_bounds(mn, mx, i)
            if smin != degrees[i] or smax != degrees[i]:
                complete = False
                break
        if complete:
            comps = forced_components(mn)
            if len(comps) != 1:
                return False
        return True

    def propagate(state):
        mn, mx = state
        changed = True
        while changed:
            changed = False

            # Basic consistency and per-island equation propagation.
            for i in range(m):
                demand = degrees[i]
                smin = 0
                smax = 0
                inc = incident[i]
                for e in inc:
                    if mn[e] > mx[e]:
                        return None
                    smin += mn[e]
                    smax += mx[e]
                if smin > demand or smax < demand:
                    return None

                # Tighten each incident edge using equation bounds.
                for e in inc:
                    others_min = smin - mn[e]
                    others_max = smax - mx[e]
                    new_lo = max(mn[e], demand - others_max)
                    new_hi = min(mx[e], demand - others_min)
                    if new_lo > new_hi:
                        return None
                    if new_lo != mn[e]:
                        mn[e] = new_lo
                        changed = True
                    if new_hi != mx[e]:
                        mx[e] = new_hi
                        changed = True

            # Crossing propagation.
            for e in range(ecount):
                if mn[e] > 0:
                    for f in crossings[e]:
                        if mx[f] != 0:
                            mx[f] = 0
                            changed = True
                            if mn[f] > mx[f]:
                                return None
                if mx[e] == 0 and mn[e] != 0:
                    return None

            # If an edge can no longer exist, its min must be 0.
            for e in range(ecount):
                if mx[e] == 0 and mn[e] != 0:
                    return None

            if not check_connectivity_pruning(mn, mx):
                return None

        return state

    def solved(state):
        mn, mx = state
        for e in range(ecount):
            if mn[e] != mx[e]:
                return False
        for i in range(m):
            smin, smax = island_bounds(mn, mx, i)
            if smin != degrees[i] or smax != degrees[i]:
                return False
        return check_connectivity_pruning(mn, mx)

    def choose_edge(state):
        mn, mx = state
        best = None
        best_key = None
        for e in range(ecount):
            if mn[e] == mx[e]:
                continue
            a, b = edges[e][0], edges[e][1]
            ra = degrees[a] - sum(mn[x] for x in incident[a])
            rb = degrees[b] - sum(mn[x] for x in incident[b])
            width = mx[e] - mn[e]
            # Prefer narrow domains and high-pressure endpoints.
            key = (width, -(ra + rb), -(len(crossings[e])), -(degrees[a] + degrees[b]))
            if best is None or key < best_key:
                best = e
                best_key = key
        return best

    def branch_values(state, e):
        mn, mx = state
        vals = list(range(mn[e], mx[e] + 1))
        # Human-like order: try forced-looking/high values first when endpoints are tight.
        a, b = edges[e][0], edges[e][1]
        rem_a = degrees[a] - sum(mn[x] for x in incident[a])
        rem_b = degrees[b] - sum(mn[x] for x in incident[b])
        pressure = rem_a + rem_b
        if pressure >= 3:
            vals.sort(reverse=True)
        return vals

    def dfs(state):
        state = propagate(state)
        if state is None:
            return None
        if solved(state):
            return state

        e = choose_edge(state)
        if e is None:
            return None

        mn, mx = state
        for val in branch_values(state, e):
            new_state = clone_state(state)
            new_state[0][e] = val
            new_state[1][e] = val
            res = dfs(new_state)
            if res is not None:
                return res
        return None

    result = dfs((init_min[:], init_max[:]))
    if result is None:
        return "No Solution"

    mn, mx = result
    answer = {}
    for e in range(ecount):
        if mn[e] > 0:
            a, b = edges[e][0], edges[e][1]
            p1 = (islands[a][0], islands[a][1])
            p2 = (islands[b][0], islands[b][1])
            if p1 > p2:
                p1, p2 = p2, p1
            answer[(p1, p2)] = mn[e]
    return repr(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

