# Yin-Yang solver:
# - clues are fixed
# - both colors must each be orthogonally connected
# - no 2x2 monochrome blocks
#
# Strategy:
# 1. Aggressive propagation from local 2x2 rules.
# 2. Connectivity feasibility pruning on partial boards.
# 3. Failed-literal deduction: tentatively assign a cell and propagate; if one color fails, force the other.
# 4. Backtracking with strong variable ordering.

from collections import deque

B, W, U = 0, 1, -1
DIRS = [(1, 0), (-1, 0), (0, 1), (0, -1)]


def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0:
        return []

    board = [[U] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                board[r][c] = B
            elif v == 'W':
                board[r][c] = W

    memo_unsat = set()

    def inside(r, c):
        return 0 <= r < n and 0 <= c < n

    def copy_board(bd):
        return [row[:] for row in bd]

    def serialize(bd):
        return tuple(tuple(row) for row in bd)

    def neighbors(r, c):
        for dr, dc in DIRS:
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < n:
                yield rr, cc

    def component_possible(bd, color):
        # All assigned cells of this color must lie in one connected component
        # of cells that are either this color or still unknown.
        fixed = []
        for r in range(n):
            for c in range(n):
                if bd[r][c] == color:
                    fixed.append((r, c))
        if not fixed:
            return True

        start = fixed[0]
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for rr, cc in neighbors(r, c):
                if (rr, cc) not in seen and bd[rr][cc] != 1 - color:
                    seen.add((rr, cc))
                    q.append((rr, cc))

        for cell in fixed:
            if cell not in seen:
                return False
        return True

    def final_connected(bd, color):
        cells = [(r, c) for r in range(n) for c in range(n) if bd[r][c] == color]
        if not cells:
            return False
        start = cells[0]
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for rr, cc in neighbors(r, c):
                if (rr, cc) not in seen and bd[rr][cc] == color:
                    seen.add((rr, cc))
                    q.append((rr, cc))
        return len(seen) == len(cells)

    def local_2x2_propagate(bd):
        changed = False
        for r in range(n - 1):
            for c in range(n - 1):
                cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                vals = [bd[rr][cc] for rr, cc in cells]

                if vals.count(B) == 4 or vals.count(W) == 4:
                    return None, False

                if vals.count(B) == 3 and vals.count(U) == 1:
                    k = vals.index(U)
                    rr, cc = cells[k]
                    if bd[rr][cc] == U:
                        bd[rr][cc] = W
                        changed = True
                if vals.count(W) == 3 and vals.count(U) == 1:
                    k = vals.index(U)
                    rr, cc = cells[k]
                    if bd[rr][cc] == U:
                        bd[rr][cc] = B
                        changed = True
        return bd, changed

    def quick_valid(bd):
        # Check no forbidden 2x2 and color-connectivity feasibility.
        for r in range(n - 1):
            for c in range(n - 1):
                vals = [bd[r][c], bd[r + 1][c], bd[r][c + 1], bd[r + 1][c + 1]]
                if vals.count(B) == 4 or vals.count(W) == 4:
                    return False
        return component_possible(bd, B) and component_possible(bd, W)

    def propagation_candidates(bd):
        # Focus failed-literal on cells near information.
        items = []
        for r in range(n):
            for c in range(n):
                if bd[r][c] != U:
                    continue
                score = 0
                for rr, cc in neighbors(r, c):
                    if bd[rr][cc] != U:
                        score += 3
                for tr in range(max(0, r - 1), min(n - 1, r) + 1):
                    for tc in range(max(0, c - 1), min(n - 1, c) + 1):
                        vals = [bd[tr][tc], bd[tr + 1][tc], bd[tr][tc + 1], bd[tr + 1][tc + 1]]
                        score += 2 * (4 - vals.count(U))
                items.append((-score, r, c))
        items.sort()
        return [(r, c) for _, r, c in items]

    def propagate(bd, use_failed_literals=True):
        while True:
            changed_any = False

            res = local_2x2_propagate(bd)
            if res[0] is None:
                return None
            bd, changed = res
            changed_any |= changed

            if not quick_valid(bd):
                return None

            if use_failed_literals:
                forced = []
                for r, c in propagation_candidates(bd):
                    if bd[r][c] != U:
                        continue

                    ok = [False, False]
                    for val in (B, W):
                        test = copy_board(bd)
                        test[r][c] = val
                        test = propagate(test, use_failed_literals=False)
                        ok[val] = test is not None

                    if not ok[B] and not ok[W]:
                        return None
                    if ok[B] and not ok[W]:
                        forced.append((r, c, B))
                    elif ok[W] and not ok[B]:
                        forced.append((r, c, W))

                if forced:
                    for r, c, val in forced:
                        if bd[r][c] == U:
                            bd[r][c] = val
                            changed_any = True
                        elif bd[r][c] != val:
                            return None

            if not changed_any:
                return bd

    def is_solved(bd):
        for r in range(n):
            for c in range(n):
                if bd[r][c] == U:
                    return False
        return final_connected(bd, B) and final_connected(bd, W)

    def choose_cell(bd):
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                if bd[r][c] != U:
                    continue
                assigned_nbrs = 0
                same_block_pressure = 0
                for rr, cc in neighbors(r, c):
                    if bd[rr][cc] != U:
                        assigned_nbrs += 1
                for tr in range(max(0, r - 1), min(n - 1, r) + 1):
                    for tc in range(max(0, c - 1), min(n - 1, c) + 1):
                        vals = [bd[tr][tc], bd[tr + 1][tc], bd[tr][tc + 1], bd[tr + 1][tc + 1]]
                        same_block_pressure += 4 - vals.count(U)
                key = (assigned_nbrs, same_block_pressure)
                if best is None or key > best_key:
                    best = (r, c)
                    best_key = key
        return best

    def branch_order(bd, r, c):
        counts = {B: 0, W: 0}
        for rr, cc in neighbors(r, c):
            if bd[rr][cc] in (B, W):
                counts[bd[rr][cc]] += 1
        # Try color matching more neighbors first.
        if counts[B] > counts[W]:
            return [B, W]
        if counts[W] > counts[B]:
            return [W, B]
        return [B, W]

    def dfs(bd):
        bd = propagate(copy_board(bd), use_failed_literals=True)
        if bd is None:
            return None

        sig = serialize(bd)
        if sig in memo_unsat:
            return None

        if is_solved(bd):
            return bd

        cell = choose_cell(bd)
        if cell is None:
            memo_unsat.add(sig)
            return None

        r, c = cell
        for val in branch_order(bd, r, c):
            nxt = copy_board(bd)
            nxt[r][c] = val
            ans = dfs(nxt)
            if ans is not None:
                return ans

        memo_unsat.add(sig)
        return None

    ans = dfs(board)
    if ans is None:
        return "No Solution"
    return [['B' if ans[r][c] == B else 'W' for c in range(n)] for r in range(n)]


if __name__ == "__main__":
    print(solve(OBSERVATION))

