from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    all_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def values_of(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    # Build adjacency requirement map for orthogonal neighbors.
    req = {}
    adjacent_set = set()
    for a, b in observation['adjacent']:
        adjacent_set.add((a, b))

    for r in range(n):
        for c in range(n):
            if c + 1 < n:
                req[((r, c), (r, c + 1))] = ((float(r), c + 0.5) in adjacent_set)
                req[((r, c + 1), (r, c))] = req[((r, c), (r, c + 1))]
            if r + 1 < n:
                req[((r, c), (r + 1, c))] = ((r + 0.5, float(c)) in adjacent_set)
                req[((r + 1, c), (r, c))] = req[((r, c), (r + 1, c))]

    # Neighbor lists and unit lists.
    cells = [(r, c) for r in range(n) for c in range(n)]
    row_units = [[(r, c) for c in range(n)] for r in range(n)]
    col_units = [[(r, c) for r in range(n)] for c in range(n)]
    units = row_units + col_units

    peers = {}
    ortho = {}
    for r in range(n):
        for c in range(n):
            p = set(row_units[r] + col_units[c])
            p.remove((r, c))
            peers[(r, c)] = list(p)
            nb = []
            if r > 0:
                nb.append((r - 1, c))
            if r + 1 < n:
                nb.append((r + 1, c))
            if c > 0:
                nb.append((r, c - 1))
            if c + 1 < n:
                nb.append((r, c + 1))
            ortho[(r, c)] = nb

    # Precompute consecutive support masks.
    cons_mask = [0] * (n + 1)
    noncons_mask = [0] * (n + 1)
    for v in range(1, n + 1):
        m = 0
        if v > 1:
            m |= bit(v - 1)
        if v < n:
            m |= bit(v + 1)
        cons_mask[v] = m
        noncons_mask[v] = all_mask ^ m

    def supported_mask(domain_mask, neighbor_mask, need_consecutive):
        out = 0
        m = domain_mask
        while m:
            b = m & -m
            v = b.bit_length()
            if need_consecutive:
                if cons_mask[v] & neighbor_mask:
                    out |= b
            else:
                if noncons_mask[v] & neighbor_mask:
                    out |= b
            m ^= b
        return out

    def assign(domains, r, c, value, queue):
        m = bit(value)
        old = domains[r][c]
        if old == m:
            return True
        if not (old & m):
            return False
        domains[r][c] = m
        queue.append((r, c))
        return True

    def propagate(domains):
        queue = deque()
        for r in range(n):
            for c in range(n):
                queue.append((r, c))

        # Repeated logical deduction until stable.
        while True:
            while queue:
                r, c = queue.popleft()
                mask = domains[r][c]
                if mask == 0:
                    return False

                # Latin constraint: assigned value excludes peers.
                if mask & (mask - 1) == 0:
                    for rr, cc in peers[(r, c)]:
                        om = domains[rr][cc]
                        nm = om & ~mask
                        if nm != om:
                            if nm == 0:
                                return False
                            domains[rr][cc] = nm
                            queue.append((rr, cc))

                # Consecutive / non-consecutive constraints on orthogonal neighbors.
                for nr, nc in ortho[(r, c)]:
                    need = req[((r, c), (nr, nc))]
                    om = domains[r][c]
                    on = domains[nr][nc]

                    nm_self = supported_mask(om, on, need)
                    if nm_self != om:
                        if nm_self == 0:
                            return False
                        domains[r][c] = nm_self
                        om = nm_self
                        queue.append((r, c))

                    nm_nb = supported_mask(on, om, need)
                    if nm_nb != on:
                        if nm_nb == 0:
                            return False
                        domains[nr][nc] = nm_nb
                        queue.append((nr, nc))

            changed = False

            # Hidden singles + naked subsets within each row/column.
            for unit in units:
                positions_for_value = [0] * (n + 1)
                count_for_value = [0] * (n + 1)

                masks_in_unit = {}
                for idx, (r, c) in enumerate(unit):
                    mask = domains[r][c]
                    if mask == 0:
                        return False
                    m = mask
                    while m:
                        b = m & -m
                        v = b.bit_length()
                        count_for_value[v] += 1
                        positions_for_value[v] = idx if count_for_value[v] == 1 else positions_for_value[v]
                        m ^= b

                    pc = popcount(mask)
                    if 2 <= pc <= n - 1:
                        masks_in_unit.setdefault(mask, []).append((r, c))

                for v in range(1, n + 1):
                    cnt = count_for_value[v]
                    if cnt == 0:
                        return False
                    if cnt == 1:
                        r, c = unit[positions_for_value[v]]
                        if domains[r][c] != bit(v):
                            domains[r][c] = bit(v)
                            queue.append((r, c))
                            changed = True

                # Naked subsets by equal mask occurrences.
                for mask, spots in masks_in_unit.items():
                    k = popcount(mask)
                    if len(spots) == k:
                        for r, c in unit:
                            if (r, c) not in spots:
                                om = domains[r][c]
                                nm = om & ~mask
                                if nm != om:
                                    if nm == 0:
                                        return False
                                    domains[r][c] = nm
                                    queue.append((r, c))
                                    changed = True

            if not changed:
                break

        return True

    def clone_domains(domains):
        return [row[:] for row in domains]

    # Initial domains.
    domains = [[all_mask for _ in range(n)] for _ in range(n)]
    init_queue = deque()
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                if not assign(domains, r, c, data[r][c], init_queue):
                    return "No Solution"

    if not propagate(domains):
        return "No Solution"

    def solved(domains):
        return all(domains[r][c] & (domains[r][c] - 1) == 0 for r in range(n) for c in range(n))

    def choose_cell(domains):
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                pc = popcount(domains[r][c])
                if pc > 1:
                    # MRV + degree heuristic.
                    degree = sum(1 for rr, cc in peers[(r, c)] if popcount(domains[rr][cc]) > 1)
                    score = (pc, -degree)
                    if best is None or score < best_score:
                        best = (r, c)
                        best_score = score
        return best

    def value_order(domains, r, c):
        vals = list(values_of(domains[r][c]))
        scored = []
        for v in vals:
            impact = 0
            vm = bit(v)
            # Prefer values that fit neighbors and constrain peers.
            for rr, cc in peers[(r, c)]:
                if domains[rr][cc] & vm:
                    impact += 1
            for nr, nc in ortho[(r, c)]:
                need = req[((r, c), (nr, nc))]
                support = cons_mask[v] if need else noncons_mask[v]
                impact += n - popcount(domains[nr][nc] & support)
            scored.append((impact, v))
        scored.sort()
        return [v for _, v in scored]

    def search(domains):
        if solved(domains):
            return domains

        cell = choose_cell(domains)
        if cell is None:
            return domains
        r, c = cell

        for v in value_order(domains, r, c):
            new_domains = clone_domains(domains)
            new_domains[r][c] = bit(v)
            if propagate(new_domains):
                ans = search(new_domains)
                if ans is not None:
                    return ans
        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            m = result[r][c]
            if m == 0 or (m & (m - 1)) != 0:
                return "No Solution"
            row.append(m.bit_length())
        grid.append(row)
    return str(grid)

