from itertools import permutations


def visible_count(seq):
    m = 0
    c = 0
    for x in seq:
        if x > m:
            m = x
            c += 1
    return c


def solve(observation):
    U = observation["U"]
    D = observation["D"]
    L = observation["L"]
    R = observation["R"]
    n = len(U)

    nums = tuple(range(1, n + 1))
    all_perms = list(permutations(nums))

    # Precompute visibility for every permutation.
    perm_lr = {}
    perm_rl = {}
    for p in all_perms:
        perm_lr[p] = visible_count(p)
        perm_rl[p] = visible_count(reversed(p))

    def clue_ok(left, right, p):
        return (left == 0 or perm_lr[p] == left) and (right == 0 or perm_rl[p] == right)

    row_domains = []
    for i in range(n):
        dom = [p for p in all_perms if clue_ok(L[i], R[i], p)]
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for j in range(n):
        dom = [p for p in all_perms if clue_ok(U[j], D[j], p)]
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    def is_solved(rdom, cdom):
        return all(len(d) == 1 for d in rdom) and all(len(d) == 1 for d in cdom)

    def extract_grid(rdom):
        return [list(d[0]) for d in rdom]

    def propagate(rdom, cdom):
        # Repeatedly cross-filter row and column permutation domains via cell supports.
        changed = True
        while changed:
            changed = False

            # Allowed values per cell from current row domains.
            row_cell_vals = [[set() for _ in range(n)] for _ in range(n)]
            for i in range(n):
                dom = rdom[i]
                if not dom:
                    return None
                for p in dom:
                    for j, v in enumerate(p):
                        row_cell_vals[i][j].add(v)

            # Allowed values per cell from current column domains.
            col_cell_vals = [[set() for _ in range(n)] for _ in range(n)]
            for j in range(n):
                dom = cdom[j]
                if not dom:
                    return None
                for p in dom:
                    for i, v in enumerate(p):
                        col_cell_vals[i][j].add(v)

            # Intersect cell supports; if empty -> contradiction.
            cell_vals = [[None] * n for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    s = row_cell_vals[i][j] & col_cell_vals[i][j]
                    if not s:
                        return None
                    cell_vals[i][j] = s

            # Filter row domains by cell supports.
            for i in range(n):
                old = rdom[i]
                new = [p for p in old if all(p[j] in cell_vals[i][j] for j in range(n))]
                if not new:
                    return None
                if len(new) != len(old):
                    rdom[i] = new
                    changed = True

            # Filter column domains by cell supports.
            for j in range(n):
                old = cdom[j]
                new = [p for p in old if all(p[i] in cell_vals[i][j] for i in range(n))]
                if not new:
                    return None
                if len(new) != len(old):
                    cdom[j] = new
                    changed = True

            # Stronger uniqueness support:
            # If in a row/column a specific value can only occur in one position among all candidates,
            # force that position's cell support to that value by pruning incompatible permutations.
            for i in range(n):
                positions_for_value = {v: [] for v in nums}
                for j in range(n):
                    for v in cell_vals[i][j]:
                        positions_for_value[v].append(j)
                forced = {}
                for v, poslist in positions_for_value.items():
                    if len(poslist) == 0:
                        return None
                    if len(poslist) == 1:
                        forced[poslist[0]] = v
                if forced:
                    old = rdom[i]
                    new = [p for p in old if all(p[j] == v for j, v in forced.items())]
                    if not new:
                        return None
                    if len(new) != len(old):
                        rdom[i] = new
                        changed = True

            for j in range(n):
                positions_for_value = {v: [] for v in nums}
                for i in range(n):
                    for v in cell_vals[i][j]:
                        positions_for_value[v].append(i)
                forced = {}
                for v, poslist in positions_for_value.items():
                    if len(poslist) == 0:
                        return None
                    if len(poslist) == 1:
                        forced[poslist[0]] = v
                if forced:
                    old = cdom[j]
                    new = [p for p in old if all(p[i] == v for i, v in forced.items())]
                    if not new:
                        return None
                    if len(new) != len(old):
                        cdom[j] = new
                        changed = True

        return rdom, cdom

    def choose_branch_var(rdom, cdom):
        best_kind = None
        best_idx = None
        best_size = 10**9

        for i, d in enumerate(rdom):
            s = len(d)
            if 1 < s < best_size:
                best_kind = "row"
                best_idx = i
                best_size = s

        for j, d in enumerate(cdom):
            s = len(d)
            if 1 < s < best_size:
                best_kind = "col"
                best_idx = j
                best_size = s

        return best_kind, best_idx

    def search(rdom, cdom):
        state = propagate([list(d) for d in rdom], [list(d) for d in cdom])
        if state is None:
            return None
        rdom, cdom = state

        if is_solved(rdom, cdom):
            grid = extract_grid(rdom)
            # Final consistency check against columns.
            for j in range(n):
                col = tuple(grid[i][j] for i in range(n))
                if cdom[j][0] != col:
                    return None
            return grid

        kind, idx = choose_branch_var(rdom, cdom)
        if kind is None:
            return None

        if kind == "row":
            # Least-constraining first: candidates that fit current column supports best.
            scored = []
            for p in rdom[idx]:
                score = 0
                for j, v in enumerate(p):
                    score += sum(1 for cp in cdom[j] if cp[idx] == v)
                scored.append((-score, p))
            scored.sort()
            for _, p in scored:
                nr = [list(d) for d in rdom]
                nc = [list(d) for d in cdom]
                nr[idx] = [p]
                ans = search(nr, nc)
                if ans is not None:
                    return ans
        else:
            scored = []
            for p in cdom[idx]:
                score = 0
                for i, v in enumerate(p):
                    score += sum(1 for rp in rdom[i] if rp[idx] == v)
                scored.append((-score, p))
            scored.sort()
            for _, p in scored:
                nr = [list(d) for d in rdom]
                nc = [list(d) for d in cdom]
                nc[idx] = [p]
                ans = search(nr, nc)
                if ans is not None:
                    return ans

        return None

    result = search(row_domains, col_domains)
    return str(result) if result is not None else "No Solution"


