# Akari / Light Up solver with aggressive logical propagation plus guided search.
# Board encoding:
#   None -> white cell
#   -1   -> black unnumbered
#   0..4 -> black numbered

UNKNOWN = 0
BULB = 1
EMPTY = 2


def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n else 0

    whites = []
    numbered = {}
    black = set()

    for r in range(n):
        for c in range(m):
            v = data[r][c]
            if v is None:
                whites.append((r, c))
            else:
                black.add((r, c))
                if v != -1:
                    numbered[(r, c)] = v

    white_set = set(whites)

    # Precompute visible cells in four directions and illumination sets.
    visible_exclusive = {}
    illuminate_set = {}

    for cell in whites:
        r, c = cell
        vis = []

        rr = r - 1
        while rr >= 0 and (rr, c) not in black:
            vis.append((rr, c))
            rr -= 1
        rr = r + 1
        while rr < n and (rr, c) not in black:
            vis.append((rr, c))
            rr += 1
        cc = c - 1
        while cc >= 0 and (r, cc) not in black:
            vis.append((r, cc))
            cc -= 1
        cc = c + 1
        while cc < m and (r, cc) not in black:
            vis.append((r, cc))
            cc += 1

        visible_exclusive[cell] = tuple(vis)
        illuminate_set[cell] = (cell,) + tuple(vis)

    # Precompute adjacency of numbered blacks.
    num_adj = {}
    for b in numbered:
        r, c = b
        adj = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if (nr, nc) in white_set:
                adj.append((nr, nc))
        num_adj[b] = tuple(adj)

    white_adj_nums = {w: [] for w in whites}
    for b, adj in num_adj.items():
        for w in adj:
            white_adj_nums[w].append(b)
    white_adj_nums = {k: tuple(v) for k, v in white_adj_nums.items()}

    def compute_stats(state):
        bulbs = {w for w, s in state.items() if s == BULB}
        lit = set()
        for b in bulbs:
            lit.add(b)
            lit.update(visible_exclusive[b])

        bcount = {}
        ucount = {}
        for b, adj in num_adj.items():
            cb = 0
            cu = 0
            for w in adj:
                if state[w] == BULB:
                    cb += 1
                elif state[w] == UNKNOWN:
                    cu += 1
            bcount[b] = cb
            ucount[b] = cu
        return bulbs, lit, bcount, ucount

    def can_place_bulb_local(cell, state, bulbs=None, bcount=None, ucount=None):
        if state[cell] != UNKNOWN:
            return False

        if bulbs is None or bcount is None or ucount is None:
            bulbs, _, bcount, ucount = compute_stats(state)

        # No line-of-sight bulb conflict.
        for v in visible_exclusive[cell]:
            if state[v] == BULB:
                return False

        # Respect adjacent numbered-black bounds and future feasibility.
        for b in white_adj_nums[cell]:
            need = numbered[b]
            cb = bcount[b]
            cu = ucount[b]
            if cb + 1 > need:
                return False
            # After using this unknown as a bulb, remaining unknowns drop by 1.
            if cb + 1 + (cu - 1) < need:
                return False

        return True

    def set_empty(cell, state):
        s = state[cell]
        if s == EMPTY:
            return True, False
        if s == BULB:
            return False, False
        state[cell] = EMPTY
        return True, True

    def set_bulb(cell, state):
        if state[cell] == BULB:
            return True, False
        if state[cell] == EMPTY:
            return False, False

        bulbs, _, bcount, ucount = compute_stats(state)
        if not can_place_bulb_local(cell, state, bulbs, bcount, ucount):
            return False, False

        state[cell] = BULB
        changed = True

        # All visible cells can no longer contain bulbs.
        for v in visible_exclusive[cell]:
            ok, ch = set_empty(v, state)
            if not ok:
                return False, False

        return True, changed

    def propagate(state):
        while True:
            changed_any = False
            bulbs, lit, bcount, ucount = compute_stats(state)

            # Basic numbered-black deductions.
            for b, need in numbered.items():
                cb = bcount[b]
                cu = ucount[b]
                if cb > need:
                    return None
                if cb + cu < need:
                    return None

                if cb == need:
                    for w in num_adj[b]:
                        if state[w] == UNKNOWN:
                            ok, ch = set_empty(w, state)
                            if not ok:
                                return None
                            changed_any = changed_any or ch
                elif cb + cu == need:
                    for w in num_adj[b]:
                        if state[w] == UNKNOWN:
                            ok, ch = set_bulb(w, state)
                            if not ok:
                                return None
                            changed_any = changed_any or ch

            bulbs, lit, bcount, ucount = compute_stats(state)

            # Eliminate cells that can never be bulbs.
            for w in whites:
                if state[w] == UNKNOWN and not can_place_bulb_local(w, state, bulbs, bcount, ucount):
                    ok, ch = set_empty(w, state)
                    if not ok:
                        return None
                    changed_any = changed_any or ch

            bulbs, lit, bcount, ucount = compute_stats(state)

            # Coverage deductions: every unlit white cell must be lightable by some candidate bulb.
            for target in whites:
                if target in lit:
                    continue

                candidates = []
                for src in illuminate_set[target]:
                    if state[src] == BULB:
                        candidates = [src]
                        break
                    if state[src] == UNKNOWN and can_place_bulb_local(src, state, bulbs, bcount, ucount):
                        candidates.append(src)

                if not candidates:
                    return None

                if len(candidates) == 1 and state[candidates[0]] != BULB:
                    ok, ch = set_bulb(candidates[0], state)
                    if not ok:
                        return None
                    changed_any = changed_any or ch

            bulbs, lit, bcount, ucount = compute_stats(state)

            # Final consistency checks after deductions.
            for b, need in numbered.items():
                cb = bcount[b]
                cu = ucount[b]
                if cb > need or cb + cu < need:
                    return None

            for w in whites:
                if state[w] == UNKNOWN:
                    continue
                if state[w] == BULB:
                    # set_bulb should have prevented conflicts, but keep a safety check.
                    for v in visible_exclusive[w]:
                        if state[v] == BULB:
                            return None

            for target in whites:
                if target not in lit:
                    possible = False
                    for src in illuminate_set[target]:
                        if state[src] == UNKNOWN and can_place_bulb_local(src, state, bulbs, bcount, ucount):
                            possible = True
                            break
                        if state[src] == BULB:
                            possible = True
                            break
                    if not possible:
                        return None

            if not changed_any:
                return state

    def is_solved(state):
        bulbs, lit, bcount, _ = compute_stats(state)
        for b, need in numbered.items():
            if bcount[b] != need:
                return False
        for w in whites:
            if w not in lit:
                return False
        return True

    def choose_branch_target(state):
        bulbs, lit, bcount, ucount = compute_stats(state)

        # Prefer an unlit cell with fewest candidate bulbs.
        best = None
        best_cands = None
        for target in whites:
            if target in lit:
                continue
            cands = []
            for src in illuminate_set[target]:
                if state[src] == UNKNOWN and can_place_bulb_local(src, state, bulbs, bcount, ucount):
                    cands.append(src)
            if not cands:
                return ('cover', target, [])
            if best is None or len(cands) < len(best_cands):
                best = target
                best_cands = cands
                if len(cands) == 1:
                    break
        if best is not None:
            return ('cover', best, best_cands)

        # Otherwise branch on a numbered black with unresolved adjacent choices.
        best_black = None
        best_black_cands = None
        for b, need in numbered.items():
            have = bcount[b]
            if have == need:
                continue
            cands = [w for w in num_adj[b] if state[w] == UNKNOWN and can_place_bulb_local(w, state, bulbs, bcount, ucount)]
            rem = need - have
            if rem < 0 or len(cands) < rem:
                return ('num', b, [])
            score = len(cands)
            if best_black is None or score < len(best_black_cands):
                best_black = b
                best_black_cands = cands
        if best_black is not None:
            return ('num', best_black, best_black_cands)

        # Fallback: any feasible unknown bulb position.
        for w in whites:
            if state[w] == UNKNOWN and can_place_bulb_local(w, state, bulbs, bcount, ucount):
                return ('cell', w, [w])

        return None

    def search(state):
        state = propagate(state)
        if state is None:
            return None

        if is_solved(state):
            for w in whites:
                if state[w] == UNKNOWN:
                    state[w] = EMPTY
            return state

        branch = choose_branch_target(state)
        if branch is None:
            return None

        kind, obj, cands = branch
        if not cands:
            return None

        if kind == 'cover':
            # One of these candidates must contain a bulb to light obj.
            for cand in cands:
                new_state = state.copy()
                ok, _ = set_bulb(cand, new_state)
                if not ok:
                    continue
                res = search(new_state)
                if res is not None:
                    return res
            return None

        if kind == 'num':
            # Try combinations for remaining bulbs around the numbered cell.
            b = obj
            need = numbered[b]
            bulbs, _, bcount, _ = compute_stats(state)
            rem = need - bcount[b]
            if rem < 0 or rem > len(cands):
                return None

            # Generate combinations in a simple recursive, pruned manner.
            chosen = []

            def comb(idx, left):
                if left == 0:
                    yield tuple(chosen)
                    return
                if len(cands) - idx < left:
                    return
                for i in range(idx, len(cands)):
                    chosen.append(cands[i])
                    yield from comb(i + 1, left - 1)
                    chosen.pop()

            for subset in comb(0, rem):
                new_state = state.copy()
                ok_all = True

                subset_set = set(subset)
                for w in cands:
                    if w in subset_set:
                        ok, _ = set_bulb(w, new_state)
                    else:
                        ok, _ = set_empty(w, new_state)
                    if not ok:
                        ok_all = False
                        break

                if ok_all:
                    res = search(new_state)
                    if res is not None:
                        return res
            return None

        if kind == 'cell':
            w = obj
            new_state = state.copy()
            ok, _ = set_bulb(w, new_state)
            if ok:
                res = search(new_state)
                if res is not None:
                    return res

            new_state = state.copy()
            ok, _ = set_empty(w, new_state)
            if ok:
                res = search(new_state)
                if res is not None:
                    return res
            return None

        return None

    initial_state = {w: UNKNOWN for w in whites}
    result = search(initial_state)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(m)] for _ in range(n)]
    for (r, c), s in result.items():
        if s == BULB:
            answer[r][c] = 'B'
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], [None, 'B', None, 'W', None, 'B'], [None, None, None, None, None, None], [None, None, None, None, 'W', None], [None, 'W', 'W', None, None, 'B'], [None, 'W', None, 'B', None, None]]}

# Generalized Takuzu / Binairo solver with strong propagation and light backtracking.
# Cells: 'B' or 'W'; internally B=1, W=0.

from copy import deepcopy


def solve(observation):
    grid = observation["data"]
    if not grid or not grid[0]:
        return "No Solution"

    h = len(grid)
    w = len(grid[0])

    if h % 2 or w % 2:
        return "No Solution"

    row_patterns = generate_valid_patterns(w)
    col_patterns = generate_valid_patterns(h)

    row_cands = []
    for r in range(h):
        fixed = [sym_to_bit(grid[r][c]) for c in range(w)]
        cands = [p for p in row_patterns if line_matches_fixed(p, fixed)]
        if not cands:
            return "No Solution"
        row_cands.append(cands)

    col_cands = []
    for c in range(w):
        fixed = [sym_to_bit(grid[r][c]) for r in range(h)]
        cands = [p for p in col_patterns if line_matches_fixed(p, fixed)]
        if not cands:
            return "No Solution"
        col_cands.append(cands)

    state = {
        "h": h,
        "w": w,
        "row_cands": row_cands,
        "col_cands": col_cands,
    }

    result = search(state)
    if result is None:
        return "No Solution"
    return materialize_grid(result)


def sym_to_bit(v):
    if v == "B":
        return 1
    if v == "W":
        return 0
    return None


def bit_to_sym(b):
    return "B" if b else "W"


def generate_valid_patterns(n):
    half = n // 2
    out = []

    def rec(i, prev1, prev2, ones, bits):
        if ones > half:
            return
        zeros = i - ones
        if zeros > half:
            return
        rem = n - i
        if ones + rem < half or zeros + rem < half:
            return
        if i == n:
            if ones == half:
                out.append(tuple(bits))
            return

        for b in (0, 1):
            if i >= 2 and prev1 == prev2 == b:
                continue
            bits.append(b)
            rec(i + 1, prev2, b, ones + b, bits)
            bits.pop()

    rec(0, None, None, 0, [])
    return out


def line_matches_fixed(pattern, fixed):
    return all(f is None or p == f for p, f in zip(pattern, fixed))


def search(state):
    state = propagate(state)
    if state is None:
        return None
    if is_solved(state):
        return state

    choice = choose_branch(state)
    if choice is None:
        return None

    kind, idx, candidates = choice
    for cand in candidates:
        nxt = clone_state(state)
        if kind == "row":
            nxt["row_cands"][idx] = [cand]
        else:
            nxt["col_cands"][idx] = [cand]
        ans = search(nxt)
        if ans is not None:
            return ans
    return None


def clone_state(state):
    return {
        "h": state["h"],
        "w": state["w"],
        "row_cands": [list(c) for c in state["row_cands"]],
        "col_cands": [list(c) for c in state["col_cands"]],
    }


def is_solved(state):
    return all(len(c) == 1 for c in state["row_cands"]) and all(len(c) == 1 for c in state["col_cands"])


def choose_branch(state):
    best = None

    for i, cands in enumerate(state["row_cands"]):
        if 1 < len(cands) and (best is None or len(cands) < best[2]):
            best = ("row", i, len(cands))

    for i, cands in enumerate(state["col_cands"]):
        if 1 < len(cands) and (best is None or len(cands) < best[2]):
            best = ("col", i, len(cands))

    if best is None:
        return None

    kind, idx, _ = best
    cands = state["row_cands"][idx] if kind == "row" else state["col_cands"][idx]

    # Branch in a useful order: candidates that agree most with currently forced cells first.
    scored = []
    if kind == "row":
        allowed_by_col = [cell_allowed_from_col(state["col_cands"][c], idx) for c in range(state["w"])]
        for p in cands:
            score = sum((p[c] in allowed_by_col[c]) for c in range(state["w"]))
            scored.append((score, p))
    else:
        allowed_by_row = [cell_allowed_from_row(state["row_cands"][r], idx) for r in range(state["h"])]
        for p in cands:
            score = sum((p[r] in allowed_by_row[r]) for r in range(state["h"]))
            scored.append((score, p))

    scored.sort(reverse=True)
    return kind, idx, [p for _, p in scored]


def cell_allowed_from_row(row_cands, c):
    vals = set()
    for p in row_cands:
        vals.add(p[c])
        if len(vals) == 2:
            break
    return vals


def cell_allowed_from_col(col_cands, r):
    vals = set()
    for p in col_cands:
        vals.add(p[r])
        if len(vals) == 2:
            break
    return vals


def propagate(state):
    h, w = state["h"], state["w"]
    row_cands = state["row_cands"]
    col_cands = state["col_cands"]

    changed = True
    while changed:
        changed = False

        # Intersect row and column possibilities cell-by-cell.
        row_allowed = [[None] * w for _ in range(h)]
        col_allowed = [[None] * w for _ in range(h)]

        for r in range(h):
            per_col = [set() for _ in range(w)]
            for p in row_cands[r]:
                for c, v in enumerate(p):
                    per_col[c].add(v)
            for c in range(w):
                row_allowed[r][c] = per_col[c]

        for c in range(w):
            per_row = [set() for _ in range(h)]
            for p in col_cands[c]:
                for r, v in enumerate(p):
                    per_row[r].add(v)
            for r in range(h):
                col_allowed[r][c] = per_row[r]

        for r in range(h):
            new = []
            for p in row_cands[r]:
                ok = True
                for c, v in enumerate(p):
                    if v not in col_allowed[r][c]:
                        ok = False
                        break
                if ok:
                    new.append(p)
            if not new:
                return None
            if len(new) != len(row_cands[r]):
                row_cands[r] = new
                changed = True

        for c in range(w):
            new = []
            for p in col_cands[c]:
                ok = True
                for r, v in enumerate(p):
                    if v not in row_allowed[r][c]:
                        ok = False
                        break
                if ok:
                    new.append(p)
            if not new:
                return None
            if len(new) != len(col_cands[c]):
                col_cands[c] = new
                changed = True

        # Uniqueness pruning for solved rows/cols.
        solved_rows = {}
        for r in range(h):
            if len(row_cands[r]) == 1:
                solved_rows.setdefault(row_cands[r][0], []).append(r)
        for pat, rows in solved_rows.items():
            if len(rows) > 1:
                return None
            rr = rows[0]
            for r in range(h):
                if r != rr and len(row_cands[r]) > 1 and pat in row_cands[r]:
                    new = [p for p in row_cands[r] if p != pat]
                    if not new:
                        return None
                    if len(new) != len(row_cands[r]):
                        row_cands[r] = new
                        changed = True

        solved_cols = {}
        for c in range(w):
            if len(col_cands[c]) == 1:
                solved_cols.setdefault(col_cands[c][0], []).append(c)
        for pat, cols in solved_cols.items():
            if len(cols) > 1:
                return None
            cc = cols[0]
            for c in range(w):
                if c != cc and len(col_cands[c]) > 1 and pat in col_cands[c]:
                    new = [p for p in col_cands[c] if p != pat]
                    if not new:
                        return None
                    if len(new) != len(col_cands[c]):
                        col_cands[c] = new
                        changed = True

        # Pair-based uniqueness:
        # If two unresolved rows have exactly the same two candidates, no other row may use either pattern.
        changed |= eliminate_locked_pairs(row_cands)
        if any(not c for c in row_cands):
            return None
        changed |= eliminate_locked_pairs(col_cands)
        if any(not c for c in col_cands):
            return None

        # Cross-check exact solved structure if both sides complete enough.
        if not basic_consistency(state):
            return None

    return state


def eliminate_locked_pairs(line_cands):
    changed = False
    buckets = {}
    for i, cands in enumerate(line_cands):
        if len(cands) == 2:
            key = tuple(sorted(cands))
            buckets.setdefault(key, []).append(i)
    for pair, idxs in buckets.items():
        if len(idxs) == 2:
            p1, p2 = pair
            for i, cands in enumerate(line_cands):
                if i in idxs or len(cands) <= 1:
                    continue
                new = [p for p in cands if p != p1 and p != p2]
                if len(new) != len(cands):
                    line_cands[i] = new
                    changed = True
    return changed


def basic_consistency(state):
    h, w = state["h"], state["w"]
    row_cands = state["row_cands"]
    col_cands = state["col_cands"]

    # Check any fully solved row agrees with solved columns and vice versa.
    for r in range(h):
        if len(row_cands[r]) == 1:
            p = row_cands[r][0]
            for c in range(w):
                if len(col_cands[c]) == 1 and col_cands[c][0][r] != p[c]:
                    return False

    for c in range(w):
        if len(col_cands[c]) == 1:
            p = col_cands[c][0]
            for r in range(h):
                if len(row_cands[r]) == 1 and row_cands[r][0][c] != p[r]:
                    return False

    return True


def materialize_grid(state):
    h, w = state["h"], state["w"]
    grid = []
    for r in range(h):
        if len(state["row_cands"][r]) != 1:
            return "No Solution"
        p = state["row_cands"][r][0]
        grid.append([bit_to_sym(p[c]) for c in range(w)])
    return grid


