    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], ['W', None, None, None, 'W', None], [None, None, 'B', None, None, None], ['W', None, None, 'W', None, 'W'], [None, None, None, None, None, None], ['B', None, None, 'W', None, 'B']]}

from itertools import product

# Takuzu / Binairo solver using strong line-domain propagation plus small guided search.
# The solver is generalized for any even-sized square grid.


def opposite(v):
    return 'B' if v == 'W' else 'W'


def valid_line(line):
    n = len(line)
    half = n // 2
    if line.count('B') != half or line.count('W') != half:
        return False
    for i in range(n - 2):
        if line[i] == line[i + 1] == line[i + 2]:
            return False
    return True


def all_valid_lines(n):
    half = n // 2
    out = []
    for bits in product(('B', 'W'), repeat=n):
        if bits.count('B') != half:
            continue
        ok = True
        for i in range(n - 2):
            if bits[i] == bits[i + 1] == bits[i + 2]:
                ok = False
                break
        if ok:
            out.append(''.join(bits))
    return out


def get_col(grid, j):
    return [grid[i][j] for i in range(len(grid))]


def compatible(pattern, line):
    for a, b in zip(pattern, line):
        if b is not None and a != b:
            return False
    return True


def transpose_lines(lines):
    n = len(lines)
    return [''.join(lines[i][j] for i in range(n)) for j in range(n)]


def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data) or n % 2 != 0:
        return "No Solution"

    valid_patterns = all_valid_lines(n)

    row_poss = []
    for row in data:
        poss = [p for p in valid_patterns if compatible(p, row)]
        if not poss:
            return "No Solution"
        row_poss.append(set(poss))

    col_poss = []
    for j in range(n):
        col = get_col(data, j)
        poss = [p for p in valid_patterns if compatible(p, col)]
        if not poss:
            return "No Solution"
        col_poss.append(set(poss))

    def propagate(row_poss, col_poss):
        while True:
            changed = False

            # Remove already completed row/column patterns from peers to enforce uniqueness.
            fixed_rows = {}
            for i, s in enumerate(row_poss):
                if len(s) == 1:
                    p = next(iter(s))
                    if p in fixed_rows:
                        return None
                    fixed_rows[p] = i
            for p, owner in fixed_rows.items():
                for i in range(n):
                    if i != owner and p in row_poss[i]:
                        row_poss[i].remove(p)
                        if not row_poss[i]:
                            return None
                        changed = True

            fixed_cols = {}
            for j, s in enumerate(col_poss):
                if len(s) == 1:
                    p = next(iter(s))
                    if p in fixed_cols:
                        return None
                    fixed_cols[p] = j
            for p, owner in fixed_cols.items():
                for j in range(n):
                    if j != owner and p in col_poss[j]:
                        col_poss[j].remove(p)
                        if not col_poss[j]:
                            return None
                        changed = True

            # Cell-wise domain consistency between row and column possibilities.
            for i in range(n):
                row_sets = [set(p[k] for p in row_poss[i]) for k in range(n)]
                for j in range(n):
                    col_vals = set(p[i] for p in col_poss[j])
                    inter = row_sets[j] & col_vals
                    if not inter:
                        return None

                    new_r = {p for p in row_poss[i] if p[j] in inter}
                    if new_r != row_poss[i]:
                        if not new_r:
                            return None
                        row_poss[i] = new_r
                        changed = True

                    new_c = {p for p in col_poss[j] if p[i] in inter}
                    if new_c != col_poss[j]:
                        if not new_c:
                            return None
                        col_poss[j] = new_c
                        changed = True

            # Extra pairwise uniqueness pruning:
            # if two rows can only be the same complete pattern, impossible;
            # if one row has one possibility p and another has {p, q...}, p already removed above.
            # Do the same implicitly for columns via completed-pattern elimination.

            # Cross-check complete row/column grids if all rows or all cols fixed.
            if all(len(s) == 1 for s in row_poss):
                rows = [next(iter(s)) for s in row_poss]
                if len(set(rows)) != n:
                    return None
                cols = transpose_lines(rows)
                if any(not valid_line(list(c)) for c in cols):
                    return None
                if len(set(cols)) != n:
                    return None
                for j in range(n):
                    p = cols[j]
                    if p not in col_poss[j]:
                        return None
                    if col_poss[j] != {p}:
                        col_poss[j] = {p}
                        changed = True

            if all(len(s) == 1 for s in col_poss):
                cols = [next(iter(s)) for s in col_poss]
                if len(set(cols)) != n:
                    return None
                rows = transpose_lines(cols)
                if any(not valid_line(list(r)) for r in rows):
                    return None
                if len(set(rows)) != n:
                    return None
                for i in range(n):
                    p = rows[i]
                    if p not in row_poss[i]:
                        return None
                    if row_poss[i] != {p}:
                        row_poss[i] = {p}
                        changed = True

            if not changed:
                return row_poss, col_poss

    def solved(row_poss, col_poss):
        return all(len(s) == 1 for s in row_poss) and all(len(s) == 1 for s in col_poss)

    def choose_branch(row_poss, col_poss):
        best_kind = None
        best_idx = None
        best_size = 10**9

        for i, s in enumerate(row_poss):
            ls = len(s)
            if 1 < ls < best_size:
                best_kind, best_idx, best_size = 'row', i, ls

        for j, s in enumerate(col_poss):
            ls = len(s)
            if 1 < ls < best_size:
                best_kind, best_idx, best_size = 'col', j, ls

        return best_kind, best_idx

    def search(row_poss, col_poss):
        state = propagate([set(s) for s in row_poss], [set(s) for s in col_poss])
        if state is None:
            return None
        row_poss, col_poss = state

        if solved(row_poss, col_poss):
            rows = [list(next(iter(s))) for s in row_poss]
            return rows

        kind, idx = choose_branch(row_poss, col_poss)
        if kind is None:
            return None

        if kind == 'row':
            candidates = sorted(row_poss[idx])
            for p in candidates:
                nr = [set(s) for s in row_poss]
                nc = [set(s) for s in col_poss]
                nr[idx] = {p}
                res = search(nr, nc)
                if res is not None:
                    return res
        else:
            candidates = sorted(col_poss[idx])
            for p in candidates:
                nr = [set(s) for s in row_poss]
                nc = [set(s) for s in col_poss]
                nc[idx] = {p}
                res = search(nr, nc)
                if res is not None:
                    return res

        return None

    ans = search(row_poss, col_poss)
    return ans if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 1], [0, 1, 1, 2, 2], [0, 2, 2, 2, 3], [0, 3, 3, 3, 3], [4, 4, 4, 4, 4]], 'data': [[None, None, None, 2, None], [None, None, None, None, None], [None, 5, None, 1, None], [None, None, None, None, None], [None, 4, None, None, None]]}

from copy import deepcopy

ALL_MASK_CACHE = {}

def bit_count(x):
    return x.bit_count()

def mask_to_values(mask, n):
    vals = []
    v = 1
    while mask:
        if mask & 1:
            vals.append(v)
        mask >>= 1
        v += 1
    return vals

def single_value(mask):
    return mask.bit_length()

def build_units(region):
    n = len(region)
    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    reg_map = {}
    for r in range(n):
        for c in range(n):
            reg_map.setdefault(region[r][c], []).append((r, c))
    regs = [cells for _, cells in sorted(reg_map.items(), key=lambda kv: kv[0])]
    return rows, cols, regs

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)

    if n not in ALL_MASK_CACHE:
        ALL_MASK_CACHE[n] = (1 << n) - 1
    ALL = ALL_MASK_CACHE[n]

    rows, cols, regs = build_units(region)

    if len(regs) != n:
        return "No Solution"
    if any(len(cells) != n for cells in regs):
        return "No Solution"

    cell_to_units = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            cell_to_units[(r, c)] = (r, c, rid)

    peers = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            s = set(rows[r]) | set(cols[c]) | set(regs[rid])
            s.discard((r, c))
            peers[(r, c)] = tuple(s)

    board = [[ALL for _ in range(n)] for _ in range(n)]

    # Initial givens
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                board[r][c] = 1 << (v - 1)

    def assign(bd, r, c, value_mask, queue):
        cur = bd[r][c]
        if cur == value_mask:
            return True
        if not (cur & value_mask):
            return False
        bd[r][c] = value_mask
        queue.append((r, c))
        return True

    def eliminate_mask(bd, r, c, rem_mask, queue):
        cur = bd[r][c]
        new = cur & ~rem_mask
        if new == cur:
            return True
        if new == 0:
            return False
        bd[r][c] = new
        if bit_count(new) == 1:
            queue.append((r, c))
        return True

    def unit_hidden_singles(bd, unit, queue):
        # For each value, if it can go in only one cell in the unit, assign it.
        pos = [0] * n
        cnt = [0] * n
        for r, c in unit:
            m = bd[r][c]
            mm = m
            while mm:
                lb = mm & -mm
                d = lb.bit_length() - 1
                cnt[d] += 1
                pos[d] = (r, c)
                mm ^= lb
        for d in range(n):
            if cnt[d] == 0:
                return False
            if cnt[d] == 1:
                r, c = pos[d]
                if not assign(bd, r, c, 1 << d, queue):
                    return False
        return True

    def region_line_interactions(bd, rid, queue):
        # Human-like locked candidates:
        # If in a region a digit's candidates all lie on one row/col,
        # eliminate that digit from the rest of that row/col outside the region.
        cells = regs[rid]
        digit_rows = [set() for _ in range(n)]
        digit_cols = [set() for _ in range(n)]
        digit_cells = [[] for _ in range(n)]
        for r, c in cells:
            m = bd[r][c]
            mm = m
            while mm:
                lb = mm & -mm
                d = lb.bit_length() - 1
                digit_rows[d].add(r)
                digit_cols[d].add(c)
                digit_cells[d].append((r, c))
                mm ^= lb

        for d in range(n):
            if not digit_cells[d]:
                return False
            bit = 1 << d
            if len(digit_rows[d]) == 1:
                row = next(iter(digit_rows[d]))
                region_set = set(cells)
                for rr, cc in rows[row]:
                    if (rr, cc) not in region_set:
                        if not eliminate_mask(bd, rr, cc, bit, queue):
                            return False
            if len(digit_cols[d]) == 1:
                col = next(iter(digit_cols[d]))
                region_set = set(cells)
                for rr, cc in cols[col]:
                    if (rr, cc) not in region_set:
                        if not eliminate_mask(bd, rr, cc, bit, queue):
                            return False
        return True

    def propagate(bd):
        queue = []

        # Seed singles
        for r in range(n):
            for c in range(n):
                if bd[r][c] == 0:
                    return False
                if bit_count(bd[r][c]) == 1:
                    queue.append((r, c))

        changed = True
        while changed:
            changed = False

            # Process all naked singles
            while queue:
                r, c = queue.pop()
                m = bd[r][c]
                if bit_count(m) != 1:
                    continue
                for rr, cc in peers[(r, c)]:
                    if not eliminate_mask(bd, rr, cc, m, queue):
                        return False
                changed = True

            # Hidden singles in rows, columns, regions
            snapshot = [[bd[r][c] for c in range(n)] for r in range(n)]
            for unit in rows:
                if not unit_hidden_singles(bd, unit, queue):
                    return False
            for unit in cols:
                if not unit_hidden_singles(bd, unit, queue):
                    return False
            for unit in regs:
                if not unit_hidden_singles(bd, unit, queue):
                    return False

            # Locked candidates from regions to rows/cols
            for rid in range(n):
                if not region_line_interactions(bd, rid, queue):
                    return False

            if queue:
                changed = True
                continue

            # Detect stasis
            if snapshot != bd:
                changed = True

        return True

    def is_solved(bd):
        for r in range(n):
            for c in range(n):
                if bit_count(bd[r][c]) != 1:
                    return False
        return True

    def select_cell(bd):
        # MRV + degree tie-break
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                bc = bit_count(bd[r][c])
                if bc > 1:
                    unresolved_peer_count = sum(1 for rr, cc in peers[(r, c)] if bit_count(bd[rr][cc]) > 1)
                    key = (bc, -unresolved_peer_count)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def search(bd):
        if not propagate(bd):
            return None
        if is_solved(bd):
            return bd

        r, c = select_cell(bd)
        options = bd[r][c]

        # Least-constraining value order
        scored = []
        mm = options
        while mm:
            lb = mm & -mm
            score = 0
            for rr, cc in peers[(r, c)]:
                if bd[rr][cc] & lb:
                    score += 1
            scored.append((score, lb))
            mm ^= lb
        scored.sort()

        for _, val_mask in scored:
            nxt = [row[:] for row in bd]
            q = []
            if assign(nxt, r, c, val_mask, q):
                res = search(nxt)
                if res is not None:
                    return res
        return None

    # Validate givens via initial propagation-ready assignments
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                vmask = 1 << (data[r][c] - 1)
                board[r][c] = vmask

    result = search(board)
    if result is None:
        return "No Solution"

    solved = [[single_value(result[r][c]) for c in range(n)] for r in range(n)]
    return solved

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [['W', None, 'B', None, 'W', None, None, None, None, None], [None, 'B', None, None, None, 'W', None, None, None, None], [None, None, 'B', 'B', None, None, None, None, 'W', None], [None, 'B', None, None, 'B', None, None, None, None, None], [None, None, 'B', None, None, None, None, None, None, None], [None, None, None, None, 'W', 'B', 'B', None, None, None], [None, None, 'W', None, None, None, None, None, None, None], [None, None, None, None, None, 'W', None, 'W', 'W', None], [None, None, None, 'W', None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None]]}

# Yin-Yang solver:
# - aggressive local propagation from 2x2 constraints
# - connectivity feasibility pruning for both colors
# - simple human-like "no stranded component" checks
# - informed backtracking with MRV-style branching

BLACK = 1
WHITE = 0
UNKNOWN = -1

def solve(observation):
    data = observation["data"]
    n = len(data)
    board = [[UNKNOWN] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] == 'B':
                board[r][c] = BLACK
            elif data[r][c] == 'W':
                board[r][c] = WHITE

    def neighbors(r, c):
        if r > 0:
            yield r - 1, c
        if r + 1 < n:
            yield r + 1, c
        if c > 0:
            yield r, c - 1
        if c + 1 < n:
            yield r, c + 1

    def copy_board(b):
        return [row[:] for row in b]

    def set_cell(b, r, c, val):
        cur = b[r][c]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False
        b[r][c] = val
        return True

    def apply_2x2_forces(b):
        changed = False
        for r in range(n - 1):
            for c in range(n - 1):
                cells = [(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)]
                vals = [b[x][y] for x, y in cells]
                if UNKNOWN not in vals:
                    if vals.count(BLACK) == 4 or vals.count(WHITE) == 4:
                        return None
                    continue
                for color in (BLACK, WHITE):
                    if vals.count(color) == 3 and vals.count(UNKNOWN) == 1:
                        idx = vals.index(UNKNOWN)
                        x, y = cells[idx]
                        if not set_cell(b, x, y, 1 - color):
                            return None
                        changed = True
        return changed

    def allowed_components(b, color):
        # Components in graph of cells that are not opposite color.
        opp = 1 - color
        seen = [[False] * n for _ in range(n)]
        comps = []
        comp_id = [[-1] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                if not seen[r][c] and b[r][c] != opp:
                    stack = [(r, c)]
                    seen[r][c] = True
                    cells = []
                    has_assigned = False
                    has_unknown = False
                    while stack:
                        x, y = stack.pop()
                        comp_id[x][y] = len(comps)
                        cells.append((x, y))
                        if b[x][y] == color:
                            has_assigned = True
                        elif b[x][y] == UNKNOWN:
                            has_unknown = True
                        for nx, ny in neighbors(x, y):
                            if not seen[nx][ny] and b[nx][ny] != opp:
                                seen[nx][ny] = True
                                stack.append((nx, ny))
                    comps.append((cells, has_assigned, has_unknown))
        return comps, comp_id

    def assigned_components(b, color):
        seen = [[False] * n for _ in range(n)]
        comps = []
        for r in range(n):
            for c in range(n):
                if b[r][c] == color and not seen[r][c]:
                    stack = [(r, c)]
                    seen[r][c] = True
                    cells = []
                    frontier = set()
                    while stack:
                        x, y = stack.pop()
                        cells.append((x, y))
                        for nx, ny in neighbors(x, y):
                            if b[nx][ny] == color and not seen[nx][ny]:
                                seen[nx][ny] = True
                                stack.append((nx, ny))
                            elif b[nx][ny] == UNKNOWN:
                                frontier.add((nx, ny))
                    comps.append((cells, frontier))
        return comps

    def connectivity_forces(b):
        changed = False

        for color in (BLACK, WHITE):
            comps, comp_id = allowed_components(b, color)

            assigned_comp_indices = [i for i, (_, has_assigned, _) in enumerate(comps) if has_assigned]
            if len(assigned_comp_indices) > 1:
                return None

            if len(assigned_comp_indices) == 1:
                root = assigned_comp_indices[0]
                for i, (cells, has_assigned, _) in enumerate(comps):
                    if i != root:
                        for x, y in cells:
                            if b[x][y] == UNKNOWN:
                                if not set_cell(b, x, y, 1 - color):
                                    return None
                                changed = True

            # Assigned same-color components must not become stranded.
            a_comps = assigned_components(b, color)
            if len(a_comps) > 1:
                for cells, frontier in a_comps:
                    if not frontier:
                        return None

            # Single allowed component but some unknown cells cannot reach any assigned color
            # due to earlier forcing is already covered by component-level pruning.
            # Additional local forcing: if there is exactly one assigned component and an
            # unknown cell is the only frontier of a stranded assigned component, force it.
            if len(a_comps) >= 1:
                for cells, frontier in a_comps:
                    if len(a_comps) > 1 and len(frontier) == 1:
                        x, y = next(iter(frontier))
                        if not set_cell(b, x, y, color):
                            return None
                        changed = True

        return changed

    def local_dead_end_forces(b):
        # If an assigned cell/component can only expand through one unknown to avoid isolation, force it.
        changed = False
        for color in (BLACK, WHITE):
            opp = 1 - color
            comps = assigned_components(b, color)
            total_assigned = sum(len(cells) for cells, _ in comps)
            for cells, frontier in comps:
                if total_assigned > len(cells):
                    if len(frontier) == 0:
                        return None
                    if len(frontier) == 1:
                        x, y = next(iter(frontier))
                        if not set_cell(b, x, y, color):
                            return None
                        changed = True

            # If an unknown cell is surrounded by opposite color on 3 or 4 sides and not enough
            # room remains for its own color connectivity when already assigned elsewhere, it may force.
            for r in range(n):
                for c in range(n):
                    if b[r][c] != UNKNOWN:
                        continue
                    same_neighbors = {BLACK: 0, WHITE: 0}
                    opp_block = {BLACK: 0, WHITE: 0}
                    for nx, ny in neighbors(r, c):
                        v = b[nx][ny]
                        if v in (BLACK, WHITE):
                            same_neighbors[v] += 1
                            opp_block[1 - v] += 1
                    # Prefer extending existing regions if cell has no possible contact to one color.
                    for color2 in (BLACK, WHITE):
                        if same_neighbors[color2] == 0:
                            continue
                        if opp_block[color2] == len(list(neighbors(r, c))):
                            if not set_cell(b, r, c, color2):
                                return None
                            changed = True
        return changed

    def propagate(b):
        while True:
            any_change = False
            res = apply_2x2_forces(b)
            if res is None:
                return False
            any_change |= res

            res = connectivity_forces(b)
            if res is None:
                return False
            any_change |= res

            res = local_dead_end_forces(b)
            if res is None:
                return False
            any_change |= res

            # Full 2x2 validation on decided blocks.
            for r in range(n - 1):
                for c in range(n - 1):
                    vals = [b[r][c], b[r + 1][c], b[r][c + 1], b[r + 1][c + 1]]
                    if UNKNOWN not in vals and (vals.count(BLACK) == 4 or vals.count(WHITE) == 4):
                        return False

            if not feasibility_check(b):
                return False

            if not any_change:
                return True

    def feasibility_check(b):
        # Every color's assigned cells must be embeddable in one connected allowed area.
        for color in (BLACK, WHITE):
            comps, _ = allowed_components(b, color)
            assigned_comp_count = sum(1 for _, has_assigned, _ in comps if has_assigned)
            if assigned_comp_count > 1:
                return False

        # No fully monochromatic 2x2 on fixed cells.
        for r in range(n - 1):
            for c in range(n - 1):
                vals = [b[r][c], b[r + 1][c], b[r][c + 1], b[r + 1][c + 1]]
                if UNKNOWN not in vals and (vals[0] == vals[1] == vals[2] == vals[3]):
                    return False

        # A decided cell should not be completely isolated from same-color possibility if same color exists elsewhere.
        for color in (BLACK, WHITE):
            total = sum(1 for r in range(n) for c in range(n) if b[r][c] == color)
            if total <= 1:
                continue
            for r in range(n):
                for c in range(n):
                    if b[r][c] != color:
                        continue
                    has_route = False
                    for nx, ny in neighbors(r, c):
                        if b[nx][ny] != 1 - color:
                            has_route = True
                            break
                    if not has_route:
                        return False
        return True

    def is_complete(b):
        for row in b:
            for v in row:
                if v == UNKNOWN:
                    return False
        return True

    def final_check(b):
        if not is_complete(b):
            return False

        for color in (BLACK, WHITE):
            cells = [(r, c) for r in range(n) for c in range(n) if b[r][c] == color]
            if not cells:
                return False
            seen = set([cells[0]])
            stack = [cells[0]]
            while stack:
                x, y = stack.pop()
                for nx, ny in neighbors(x, y):
                    if b[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            if len(seen) != len(cells):
                return False

        for r in range(n - 1):
            for c in range(n - 1):
                vals = [b[r][c], b[r + 1][c], b[r][c + 1], b[r + 1][c + 1]]
                if vals[0] == vals[1] == vals[2] == vals[3]:
                    return False
        return True

    def cell_score(b, r, c):
        score = 0
        for nx, ny in neighbors(r, c):
            if b[nx][ny] != UNKNOWN:
                score += 2
        if 0 < r < n - 1 and 0 < c < n - 1:
            score += 2
        # Involvement in 2x2s
        score += (r > 0 and c > 0)
        score += (r > 0 and c < n - 1)
        score += (r < n - 1 and c > 0)
        score += (r < n - 1 and c < n - 1)
        return score

    def branch_order(b, r, c):
        black_score = 0
        white_score = 0
        for nx, ny in neighbors(r, c):
            if b[nx][ny] == BLACK:
                black_score += 1
            elif b[nx][ny] == WHITE:
                white_score += 1
        # Try color that extends more neighbors first.
        if black_score > white_score:
            return (BLACK, WHITE)
        if white_score > black_score:
            return (WHITE, BLACK)
        return (BLACK, WHITE)

    def choose_cell(b):
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                if b[r][c] == UNKNOWN:
                    score = cell_score(b, r, c)
                    if best is None or score > best_score:
                        best = (r, c)
                        best_score = score
        return best

    def dfs(b):
        if not propagate(b):
            return None
        if is_complete(b):
            return b if final_check(b) else None

        r, c = choose_cell(b)
        for val in branch_order(b, r, c):
            nb = copy_board(b)
            nb[r][c] = val
            ans = dfs(nb)
            if ans is not None:
                return ans
        return None

    ans = dfs(board)
    if ans is None:
        return "No Solution"
    return [['B' if v == BLACK else 'W' for v in row] for row in ans]

if __name__ == "__main__":
    print(solve(OBSERVATION))

