# Generalized solver for consecutive-adjacency Latin square puzzles.
# Rules:
# - Fill an N x N grid with numbers 1..N.
# - Each row and column is a permutation of 1..N.
# - A marked midpoint means the two adjacent cells differ by exactly 1.
# - An unmarked orthogonal adjacency means the two cells are NOT consecutive.

ALL = None

def bit(v):
    return 1 << (v - 1)

def bits_from_mask(mask, n):
    v = 1
    while mask:
        if mask & 1:
            yield v
        v += 1
        mask >>= 1

def popcount(x):
    return x.bit_count()

def is_single(mask):
    return mask and (mask & (mask - 1)) == 0

def single_value(mask):
    return mask.bit_length()

def format_grid(grid):
    return str(grid)

def build_edges(n, adjacent_midpoints):
    marked = set()
    for a, b in adjacent_midpoints:
        if abs(a - round(a)) < 1e-9 and abs((b * 2) - round(b * 2)) < 1e-9 and abs(b - round(b)) > 1e-9:
            r = int(round(a))
            c = int(round(b - 0.5))
            if 0 <= r < n and 0 <= c < n - 1:
                marked.add(((r, c), (r, c + 1)))
                marked.add(((r, c + 1), (r, c)))
        elif abs(b - round(b)) < 1e-9 and abs((a * 2) - round(a * 2)) < 1e-9 and abs(a - round(a)) > 1e-9:
            r = int(round(a - 0.5))
            c = int(round(b))
            if 0 <= r < n - 1 and 0 <= c < n:
                marked.add(((r, c), (r + 1, c)))
                marked.add(((r + 1, c), (r, c)))
    neighbors = [[] for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            i = r * n + c
            for dr, dc in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    j = rr * n + cc
                    marked_edge = ((r, c), (rr, cc)) in marked
                    neighbors[i].append((j, marked_edge))
    return neighbors

def allowed_with_relation(mask_a, mask_b, marked, n):
    out_a = 0
    vals_b = tuple(bits_from_mask(mask_b, n))
    for va in bits_from_mask(mask_a, n):
        ok = False
        for vb in vals_b:
            consec = abs(va - vb) == 1
            if consec == marked:
                ok = True
                break
        if ok:
            out_a |= bit(va)
    return out_a

def line_hidden_single_masks(indices, domains, n):
    changed = []
    for v in range(1, n + 1):
        bv = bit(v)
        spots = [idx for idx in indices if domains[idx] & bv]
        if not spots:
            return None
        if len(spots) == 1 and domains[spots[0]] != bv:
            changed.append((spots[0], bv))
    return changed

def line_subset_elimination(indices, domains, n):
    # Human-style naked subsets on row/column.
    # For each repeated domain among unsolved cells, if it appears k times and has size k,
    # remove those values from all other cells in line.
    updates = []
    freq = {}
    for idx in indices:
        m = domains[idx]
        pc = popcount(m)
        if 2 <= pc <= n - 1:
            freq.setdefault(m, []).append(idx)
    for m, cells in freq.items():
        k = popcount(m)
        if len(cells) == k:
            for idx in indices:
                if idx not in cells and domains[idx] & m:
                    nm = domains[idx] & ~m
                    if nm != domains[idx]:
                        if nm == 0:
                            return None
                        updates.append((idx, nm))
    return updates

def solve(observation):
    data = observation['data']
    n = len(data)
    global ALL
    ALL = (1 << n) - 1

    neighbors = build_edges(n, observation['adjacent'])

    domains = [ALL] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                domains[r * n + c] = bit(v)

    row_indices = [[r * n + c for c in range(n)] for r in range(n)]
    col_indices = [[r * n + c for r in range(n)] for c in range(n)]

    peer_rows = [None] * (n * n)
    peer_cols = [None] * (n * n)
    for r in range(n):
        for c in range(n):
            i = r * n + c
            peer_rows[i] = [r * n + cc for cc in range(n) if cc != c]
            peer_cols[i] = [rr * n + c for rr in range(n) if rr != r]

    def propagate(domains):
        queue = list(range(n * n))
        inq = [True] * (n * n)

        while True:
            while queue:
                i = queue.pop()
                inq[i] = False
                mi = domains[i]
                if mi == 0:
                    return None

                # Latin uniqueness from solved cells.
                if is_single(mi):
                    vmask = mi
                    for j in peer_rows[i]:
                        mj = domains[j]
                        if mj & vmask:
                            nm = mj & ~vmask
                            if nm == 0:
                                return None
                            if nm != mj:
                                domains[j] = nm
                                if not inq[j]:
                                    queue.append(j)
                                    inq[j] = True
                    for j in peer_cols[i]:
                        mj = domains[j]
                        if mj & vmask:
                            nm = mj & ~vmask
                            if nm == 0:
                                return None
                            if nm != mj:
                                domains[j] = nm
                                if not inq[j]:
                                    queue.append(j)
                                    inq[j] = True

                # Edge constraints.
                for j, marked in neighbors[i]:
                    mj = domains[j]
                    ai = allowed_with_relation(domains[i], mj, marked, n)
                    if ai == 0:
                        return None
                    if ai != domains[i]:
                        domains[i] = ai
                        if not inq[i]:
                            queue.append(i)
                            inq[i] = True
                    bj = allowed_with_relation(mj, domains[i], marked, n)
                    if bj == 0:
                        return None
                    if bj != domains[j]:
                        domains[j] = bj
                        if not inq[j]:
                            queue.append(j)
                            inq[j] = True

            progress = False

            # Row/column digit coverage + hidden singles + subset elimination.
            for lines in (row_indices, col_indices):
                for indices in lines:
                    union = 0
                    for idx in indices:
                        if domains[idx] == 0:
                            return None
                        union |= domains[idx]
                    if union != ALL:
                        return None

                    hs = line_hidden_single_masks(indices, domains, n)
                    if hs is None:
                        return None
                    for idx, nm in hs:
                        if domains[idx] != nm:
                            domains[idx] = nm
                            if not inq[idx]:
                                queue.append(idx)
                                inq[idx] = True
                            progress = True

                    subs = line_subset_elimination(indices, domains, n)
                    if subs is None:
                        return None
                    for idx, nm in subs:
                        if domains[idx] != nm:
                            domains[idx] = nm
                            if not inq[idx]:
                                queue.append(idx)
                                inq[idx] = True
                            progress = True

                    # Hall-like check for small candidate unions (human-ish advanced pruning).
                    uns = [idx for idx in indices if not is_single(domains[idx])]
                    mlen = len(uns)
                    if 2 <= mlen <= n:
                        # Limited combinations for efficiency: pairs and triples only.
                        for size in (2, 3):
                            if size > mlen:
                                continue
                            stack = [(0, [], 0)]
                            while stack:
                                pos, chosen, umask = stack.pop()
                                if len(chosen) == size:
                                    if popcount(umask) < size:
                                        return None
                                    if popcount(umask) == size:
                                        for idx in indices:
                                            if idx not in chosen and domains[idx] & umask:
                                                nm = domains[idx] & ~umask
                                                if nm == 0:
                                                    return None
                                                if nm != domains[idx]:
                                                    domains[idx] = nm
                                                    if not inq[idx]:
                                                        queue.append(idx)
                                                        inq[idx] = True
                                                    progress = True
                                    continue
                                if pos >= mlen:
                                    continue
                                remaining = size - len(chosen)
                                if mlen - pos < remaining:
                                    continue
                                idx = uns[pos]
                                stack.append((pos + 1, chosen, umask))
                                stack.append((pos + 1, chosen + [idx], umask | domains[idx]))

            if not queue and not progress:
                break

        # Final all-different validation for solved lines.
        for indices in row_indices + col_indices:
            seen = 0
            for idx in indices:
                m = domains[idx]
                if is_single(m):
                    if seen & m:
                        return None
                    seen |= m
        return domains

    def choose_branch_cell(domains):
        # Pick the most constrained cell with strongest adjacency interaction.
        best = None
        best_key = None
        for i, m in enumerate(domains):
            pc = popcount(m)
            if pc <= 1:
                continue
            deg = len(neighbors[i])
            marked_deg = sum(1 for _, mk in neighbors[i] if mk)
            key = (pc, -marked_deg, -deg)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def value_order(i, domains):
        # Least-constraining value ordering guided by row/col/adjacency impact.
        vals = list(bits_from_mask(domains[i], n))
        scored = []
        row = i // n
        col = i % n
        for v in vals:
            score = 0
            bv = bit(v)
            for j in row_indices[row]:
                if j != i and domains[j] & bv:
                    score += 1
            for j in col_indices[col]:
                if j != i and domains[j] & bv:
                    score += 1
            for j, marked in neighbors[i]:
                compat = 0
                for w in bits_from_mask(domains[j], n):
                    if (abs(v - w) == 1) == marked:
                        compat += 1
                score += compat
            scored.append((score, v))
        scored.sort()
        return [v for _, v in scored]

    def search(domains):
        domains = propagate(domains[:])
        if domains is None:
            return None
        if all(is_single(m) for m in domains):
            grid = [[single_value(domains[r * n + c]) for c in range(n)] for r in range(n)]
            return grid

        i = choose_branch_cell(domains)
        if i is None:
            return None

        for v in value_order(i, domains):
            nd = domains[:]
            nd[i] = bit(v)
            res = search(nd)
            if res is not None:
                return res
        return None

    result = search(domains)
    if result is None:
        return "No Solution"
    return format_grid(result)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 1, 1, 1, 1, 1], [0, 1, 1, 1, 2, 2], [3, 3, 4, 2, 2, 2], [3, 4, 4, 4, 4, 5], [3, 4, 3, 3, 3, 5], [3, 3, 3, 3, 5, 5]], 'row_water_counts': [1, 4, 4, 5, 5, 4], 'col_water_counts': [5, 4, 5, 5, 3, 1]}

from collections import defaultdict

# General solver for "fill regions with a single water level" puzzles.
# A region's water pattern is determined by a threshold row:
# choose a level t, and every cell in that region with row >= t is water.
# Empty region is represented by t beyond the bottom.

def build_regions(region_grid):
    regions = defaultdict(list)
    for r, row in enumerate(region_grid):
        for c, rid in enumerate(row):
            regions[rid].append((r, c))
    return dict(sorted(regions.items()))

def region_candidates(cells, h, w):
    rows_present = sorted({r for r, _ in cells})
    max_r = max(rows_present)

    # Unique candidates by actual water-cell set.
    seen = set()
    candidates = []

    # Empty candidate.
    thresholds = [max_r + 1] + rows_present
    for t in thresholds:
        water = tuple(sorted((r, c) for (r, c) in cells if r >= t))
        if water in seen:
            continue
        seen.add(water)

        row_add = [0] * h
        col_add = [0] * w
        water_set = set(water)
        for r, c in water_set:
            row_add[r] += 1
            col_add[c] += 1

        candidates.append({
            'water': water_set,
            'row_add': tuple(row_add),
            'col_add': tuple(col_add),
            'count': len(water_set),
        })

    # Sort by water count to encourage strong propagation.
    candidates.sort(key=lambda x: x['count'])
    return candidates

def precompute_bounds(region_ids, cand_map, h, w):
    row_min = {}
    row_max = {}
    col_min = {}
    col_max = {}
    for rid in region_ids:
        cands = cand_map[rid]
        row_min[rid] = [min(c['row_add'][r] for c in cands) for r in range(h)]
        row_max[rid] = [max(c['row_add'][r] for c in cands) for r in range(h)]
        col_min[rid] = [min(c['col_add'][c] for c in cands) for c in range(w)]
        col_max[rid] = [max(c['col_add'][c] for c in cands) for c in range(w)]
    return row_min, row_max, col_min, col_max

def feasible_group_sums(active_regions, cand_map, target_rows, target_cols, h, w):
    # Fast necessary condition using per-region min/max.
    row_min = [0] * h
    row_max = [0] * h
    col_min = [0] * w
    col_max = [0] * w
    for rid in active_regions:
        cands = cand_map[rid]
        for r in range(h):
            vals = [c['row_add'][r] for c in cands]
            row_min[r] += min(vals)
            row_max[r] += max(vals)
        for c in range(w):
            vals = [cand['col_add'][c] for cand in cands]
            col_min[c] += min(vals)
            col_max[c] += max(vals)
    for r in range(h):
        if not (row_min[r] <= target_rows[r] <= row_max[r]):
            return False
    for c in range(w):
        if not (col_min[c] <= target_cols[c] <= col_max[c]):
            return False
    return True

def propagate(domains, region_ids, cand_map, row_goal, col_goal, h, w):
    domains = {rid: list(vals) for rid, vals in domains.items()}

    while True:
        changed = False

        # Totals from fixed regions.
        fixed_row = [0] * h
        fixed_col = [0] * w
        for rid in region_ids:
            if len(domains[rid]) == 1:
                cand = cand_map[rid][domains[rid][0]]
                for r in range(h):
                    fixed_row[r] += cand['row_add'][r]
                for c in range(w):
                    fixed_col[c] += cand['col_add'][c]

        # Min/max contribution from unfixed regions.
        rem_row_min = [0] * h
        rem_row_max = [0] * h
        rem_col_min = [0] * w
        rem_col_max = [0] * w
        for rid in region_ids:
            if len(domains[rid]) > 1:
                cands = [cand_map[rid][i] for i in domains[rid]]
                for r in range(h):
                    vals = [c['row_add'][r] for c in cands]
                    rem_row_min[r] += min(vals)
                    rem_row_max[r] += max(vals)
                for c in range(w):
                    vals = [cand['col_add'][c] for cand in cands]
                    rem_col_min[c] += min(vals)
                    rem_col_max[c] += max(vals)

        # Global feasibility.
        for r in range(h):
            if fixed_row[r] > row_goal[r]:
                return None
            if fixed_row[r] + rem_row_min[r] > row_goal[r]:
                return None
            if fixed_row[r] + rem_row_max[r] < row_goal[r]:
                return None
        for c in range(w):
            if fixed_col[c] > col_goal[c]:
                return None
            if fixed_col[c] + rem_col_min[c] > col_goal[c]:
                return None
            if fixed_col[c] + rem_col_max[c] < col_goal[c]:
                return None

        # Candidate filtering by row/col residual bounds.
        for rid in region_ids:
            if len(domains[rid]) == 1:
                continue

            other_row_min = [0] * h
            other_row_max = [0] * h
            other_col_min = [0] * w
            other_col_max = [0] * w

            for orid in region_ids:
                if orid == rid or len(domains[orid]) == 1:
                    continue
                cands = [cand_map[orid][i] for i in domains[orid]]
                for r in range(h):
                    vals = [c['row_add'][r] for c in cands]
                    other_row_min[r] += min(vals)
                    other_row_max[r] += max(vals)
                for c in range(w):
                    vals = [cand['col_add'][c] for c in cands]
                    other_col_min[c] += min(vals)
                    other_col_max[c] += max(vals)

            new_dom = []
            for idx in domains[rid]:
                cand = cand_map[rid][idx]
                ok = True
                for r in range(h):
                    need = row_goal[r] - fixed_row[r] - cand['row_add'][r]
                    if need < other_row_min[r] or need > other_row_max[r]:
                        ok = False
                        break
                if ok:
                    for c in range(w):
                        need = col_goal[c] - fixed_col[c] - cand['col_add'][c]
                        if need < other_col_min[c] or need > other_col_max[c]:
                            ok = False
                            break
                if ok:
                    new_dom.append(idx)

            if not new_dom:
                return None
            if len(new_dom) != len(domains[rid]):
                domains[rid] = new_dom
                changed = True

        # Exact fulfillment forcing.
        fixed_row = [0] * h
        fixed_col = [0] * w
        rem_row_min = [0] * h
        rem_row_max = [0] * h
        rem_col_min = [0] * w
        rem_col_max = [0] * w
        for rid in region_ids:
            cands = [cand_map[rid][i] for i in domains[rid]]
            if len(domains[rid]) == 1:
                c = cands[0]
                for r in range(h):
                    fixed_row[r] += c['row_add'][r]
                for cidx in range(w):
                    fixed_col[cidx] += c['col_add'][cidx]
            else:
                for r in range(h):
                    vals = [c['row_add'][r] for c in cands]
                    rem_row_min[r] += min(vals)
                    rem_row_max[r] += max(vals)
                for cidx in range(w):
                    vals = [c['col_add'][cidx] for c in cands]
                    rem_col_min[cidx] += min(vals)
                    rem_col_max[cidx] += max(vals)

        for r in range(h):
            if fixed_row[r] == row_goal[r]:
                for rid in region_ids:
                    if len(domains[rid]) > 1:
                        filtered = [i for i in domains[rid] if cand_map[rid][i]['row_add'][r] == 0]
                        if not filtered:
                            return None
                        if len(filtered) != len(domains[rid]):
                            domains[rid] = filtered
                            changed = True
            elif fixed_row[r] + rem_row_min[r] == row_goal[r]:
                for rid in region_ids:
                    if len(domains[rid]) > 1:
                        cands = [cand_map[rid][i] for i in domains[rid]]
                        mn = min(c['row_add'][r] for c in cands)
                        filtered = [i for i in domains[rid] if cand_map[rid][i]['row_add'][r] == mn]
                        if not filtered:
                            return None
                        if len(filtered) != len(domains[rid]):
                            domains[rid] = filtered
                            changed = True
            elif fixed_row[r] + rem_row_max[r] == row_goal[r]:
                for rid in region_ids:
                    if len(domains[rid]) > 1:
                        cands = [cand_map[rid][i] for i in domains[rid]]
                        mx = max(c['row_add'][r] for c in cands)
                        filtered = [i for i in domains[rid] if cand_map[rid][i]['row_add'][r] == mx]
                        if not filtered:
                            return None
                        if len(filtered) != len(domains[rid]):
                            domains[rid] = filtered
                            changed = True

        for c in range(w):
            if fixed_col[c] == col_goal[c]:
                for rid in region_ids:
                    if len(domains[rid]) > 1:
                        filtered = [i for i in domains[rid] if cand_map[rid][i]['col_add'][c] == 0]
                        if not filtered:
                            return None
                        if len(filtered) != len(domains[rid]):
                            domains[rid] = filtered
                            changed = True
            elif fixed_col[c] + rem_col_min[c] == col_goal[c]:
                for rid in region_ids:
                    if len(domains[rid]) > 1:
                        cands = [cand_map[rid][i] for i in domains[rid]]
                        mn = min(cand['col_add'][c] for cand in cands)
                        filtered = [i for i in domains[rid] if cand_map[rid][i]['col_add'][c] == mn]
                        if not filtered:
                            return None
                        if len(filtered) != len(domains[rid]):
                            domains[rid] = filtered
                            changed = True
            elif fixed_col[c] + rem_col_max[c] == col_goal[c]:
                for rid in region_ids:
                    if len(domains[rid]) > 1:
                        cands = [cand_map[rid][i] for i in domains[rid]]
                        mx = max(cand['col_add'][c] for cand in cands)
                        filtered = [i for i in domains[rid] if cand_map[rid][i]['col_add'][c] == mx]
                        if not filtered:
                            return None
                        if len(filtered) != len(domains[rid]):
                            domains[rid] = filtered
                            changed = True

        if not changed:
            return domains

def choose_region(domains, cand_map, region_ids, row_goal, col_goal, h, w):
    # Most constrained region, with highest impact as tiebreak.
    best = None
    best_key = None
    for rid in region_ids:
        if len(domains[rid]) <= 1:
            continue
        impacts = set()
        for idx in domains[rid]:
            impacts.add((cand_map[rid][idx]['row_add'], cand_map[rid][idx]['col_add']))
        key = (len(domains[rid]), -len(impacts), -max(cand_map[rid][idx]['count'] for idx in domains[rid]))
        if best is None or key < best_key:
            best = rid
            best_key = key
    return best

def finalize_solution(domains, region_ids, cand_map, h, w):
    grid = [[None for _ in range(w)] for _ in range(h)]
    for rid in region_ids:
        cand = cand_map[rid][domains[rid][0]]
        for r, c in cand['water']:
            grid[r][c] = 'W'
    return grid

def search(domains, region_ids, cand_map, row_goal, col_goal, h, w):
    domains = propagate(domains, region_ids, cand_map, row_goal, col_goal, h, w)
    if domains is None:
        return None
    if all(len(domains[rid]) == 1 for rid in region_ids):
        return finalize_solution(domains, region_ids, cand_map, h, w)

    rid = choose_region(domains, cand_map, region_ids, row_goal, col_goal, h, w)
    if rid is None:
        return None

    # Try candidates ordered by closeness to remaining totals and larger information content.
    ordering = []
    for idx in domains[rid]:
        cand = cand_map[rid][idx]
        score = -cand['count']
        ordering.append((score, idx))
    ordering.sort()

    for _, idx in ordering:
        new_domains = {k: list(v) for k, v in domains.items()}
        new_domains[rid] = [idx]
        ans = search(new_domains, region_ids, cand_map, row_goal, col_goal, h, w)
        if ans is not None:
            return ans
    return None

def solve(observation):
    region_grid = observation['region']
    row_goal = observation['row_water_counts']
    col_goal = observation['col_water_counts']

    h = len(region_grid)
    w = len(region_grid[0]) if h else 0

    if len(row_goal) != h or len(col_goal) != w:
        return "No Solution"

    regions = build_regions(region_grid)
    region_ids = sorted(regions)

    cand_map = {}
    for rid in region_ids:
        cand_map[rid] = region_candidates(regions[rid], h, w)
        if not cand_map[rid]:
            return "No Solution"

    # Initial domain setup.
    domains = {rid: list(range(len(cand_map[rid]))) for rid in region_ids}

    # Early aggregate feasibility.
    if not feasible_group_sums(region_ids, cand_map, row_goal, col_goal, h, w):
        return "No Solution"

    solution = search(domains, region_ids, cand_map, row_goal, col_goal, h, w)
    if solution is None:
        return "No Solution"
    return str(solution)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 1, None, None, None, None, 3], [2, None, None, 1, None, 2, None], [None, None, None, None, None, None, 3], [5, None, None, None, None, 3, None], [None, None, None, None, None, None, 2], [None, None, 1, None, None, 2, None], [4, None, None, 3, None, None, 2]]}

from collections import deque

def solve(observation):
    data = observation["data"]
    n = len(data)

    islands = []
    island_index = {}
    for r in range(n):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                island_index[(r, c)] = len(islands)
                islands.append(((r, c), data[r][c]))

    m = len(islands)
    if m == 0:
        return {}

    # Build visibility edges between consecutive islands in rows and columns.
    edges = []
    incident = [[] for _ in range(m)]

    def add_edge(i, j, orient):
        a = islands[i][0]
        b = islands[j][0]
        if a > b:
            i, j = j, i
            a, b = b, a
        idx = len(edges)
        edges.append({
            "u": i,
            "v": j,
            "a": a,
            "b": b,
            "orient": orient,
            "cross": [],
        })
        incident[i].append(idx)
        incident[j].append(idx)

    # Horizontal
    for r in range(n):
        prev = None
        for c in range(len(data[r])):
            if data[r][c] is not None:
                cur = island_index[(r, c)]
                if prev is not None:
                    add_edge(prev, cur, "H")
                prev = cur

    # Vertical
    max_cols = max(len(row) for row in data)
    for c in range(max_cols):
        prev = None
        for r in range(n):
            if c < len(data[r]) and data[r][c] is not None:
                cur = island_index[(r, c)]
                if prev is not None:
                    add_edge(prev, cur, "V")
                prev = cur

    # Crossing relationships.
    ecount = len(edges)
    for i in range(ecount):
        ei = edges[i]
        if ei["orient"] != "H":
            continue
        r = ei["a"][0]
        c1 = ei["a"][1]
        c2 = ei["b"][1]
        for j in range(ecount):
            ej = edges[j]
            if ej["orient"] != "V":
                continue
            c = ej["a"][1]
            r1 = ej["a"][0]
            r2 = ej["b"][0]
            if c1 < c < c2 and r1 < r < r2:
                ei["cross"].append(j)
                ej["cross"].append(i)

    targets = [v for _, v in islands]

    # Useful immutable data for local reasoning.
    edge_endpoints = [(e["u"], e["v"]) for e in edges]
    crossings = [tuple(e["cross"]) for e in edges]

    def initial_state():
        lo = [0] * ecount
        hi = [2] * ecount
        return (lo, hi)

    def clone_state(state):
        lo, hi = state
        return (lo[:], hi[:])

    def assign_edge(state, e, value):
        lo, hi = state
        if value < lo[e] or value > hi[e]:
            return False
        if lo[e] == hi[e] == value:
            return True
        lo[e] = hi[e] = value
        return True

    def set_lo(state, e, value):
        lo, hi = state
        if value > hi[e]:
            return False
        if value <= lo[e]:
            return True
        lo[e] = value
        return True

    def set_hi(state, e, value):
        lo, hi = state
        if value < lo[e]:
            return False
        if value >= hi[e]:
            return True
        hi[e] = value
        return True

    def island_sums(state, i):
        lo, hi = state
        s_lo = 0
        s_hi = 0
        for e in incident[i]:
            s_lo += lo[e]
            s_hi += hi[e]
        return s_lo, s_hi

    def mandatory_possible_components(state):
        lo, hi = state

        parent = list(range(m))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra

        # Mandatory edges already connect components.
        for e, (u, v) in enumerate(edge_endpoints):
            if lo[e] > 0:
                union(u, v)

        comp_members = {}
        for i in range(m):
            r = find(i)
            comp_members.setdefault(r, []).append(i)

        comp_id = {}
        comp_list = list(comp_members.keys())
        for idx, root in enumerate(comp_list):
            comp_id[root] = idx

        possible_adj = [set() for _ in comp_list]
        outside_possible = [False] * len(comp_list)

        for e, (u, v) in enumerate(edge_endpoints):
            if hi[e] <= 0:
                continue
            cu = comp_id[find(u)]
            cv = comp_id[find(v)]
            if cu != cv:
                possible_adj[cu].add(cv)
                possible_adj[cv].add(cu)
                outside_possible[cu] = True
                outside_possible[cv] = True

        return parent, comp_members, possible_adj, outside_possible

    def connectivity_feasible(state):
        lo, hi = state

        parent, comp_members, possible_adj, outside_possible = mandatory_possible_components(state)

        # If more than one mandatory component exists, they must be connectable through possible edges.
        if len(comp_members) > 1:
            seen = set([0])
            q = deque([0])
            while q:
                x = q.popleft()
                for y in possible_adj[x]:
                    if y not in seen:
                        seen.add(y)
                        q.append(y)
            if len(seen) != len(comp_members):
                return False

        # No proper subset may already be sealed off.
        roots = list(comp_members.keys())
        root_to_idx = {r: i for i, r in enumerate(roots)}
        for root, members in comp_members.items():
            idx = root_to_idx[root]
            if len(members) == m:
                continue
            if not outside_possible[idx]:
                return False

        return True

    def forced_connectivity_rules(state):
        # Human-like connectivity rule:
        # if a mandatory component has exactly one possible exit edge to the outside,
        # that edge must carry at least one bridge.
        lo, hi = state
        parent, comp_members, possible_adj, outside_possible = mandatory_possible_components(state)

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        exits = {}
        for e, (u, v) in enumerate(edge_endpoints):
            if hi[e] <= 0:
                continue
            ru = find(u)
            rv = find(v)
            if ru != rv:
                exits.setdefault(ru, []).append(e)
                exits.setdefault(rv, []).append(e)

        changed = False
        for root, members in comp_members.items():
            if len(members) == m:
                continue
            cand = exits.get(root, [])
            if len(cand) == 0:
                return None
            if len(cand) == 1:
                e = cand[0]
                if lo[e] == 0:
                    if not set_lo(state, e, 1):
                        return None
                    changed = True
        return changed

    def propagate(state):
        lo, hi = state
        changed = True
        while changed:
            changed = False

            # Crossing rule: once an edge is positive, all crossing edges are zero.
            for e in range(ecount):
                if lo[e] > 0:
                    for ce in crossings[e]:
                        if hi[ce] > 0:
                            if not set_hi(state, ce, 0):
                                return False
                            changed = True

            # Per-island degree bounds and edge-wise tightening.
            for i in range(m):
                t = targets[i]
                inc = incident[i]

                s_lo = 0
                s_hi = 0
                for e in inc:
                    s_lo += lo[e]
                    s_hi += hi[e]

                if t < s_lo or t > s_hi:
                    return False

                # Tighten each incident edge from the island equation.
                for e in inc:
                    other_lo = s_lo - lo[e]
                    other_hi = s_hi - hi[e]
                    new_lo = max(lo[e], t - other_hi)
                    new_hi = min(hi[e], t - other_lo)
                    if new_lo > new_hi:
                        return False
                    if new_lo != lo[e]:
                        lo[e] = new_lo
                        changed = True
                    if new_hi != hi[e]:
                        hi[e] = new_hi
                        changed = True

                # Human-style direct cases.
                s_lo = 0
                s_hi = 0
                for e in inc:
                    s_lo += lo[e]
                    s_hi += hi[e]

                if s_lo == t:
                    for e in inc:
                        if hi[e] != lo[e]:
                            hi[e] = lo[e]
                            changed = True
                elif s_hi == t:
                    for e in inc:
                        if hi[e] != lo[e]:
                            lo[e] = hi[e]
                            changed = True

                # If island still needs positive bridges on all currently possible edges.
                remaining = t - sum(lo[e] for e in inc)
                poss = [e for e in inc if hi[e] > lo[e]]
                cap = sum(hi[e] - lo[e] for e in poss)
                if remaining < 0 or remaining > cap:
                    return False

            # More crossing propagation after domain changes.
            for e in range(ecount):
                if hi[e] == 0:
                    continue
                # If all crossings are already positive-blocked? handled by loop above.
                pass

            # Connectivity feasibility and forced exits.
            if not connectivity_feasible(state):
                return False

            conn_changed = forced_connectivity_rules(state)
            if conn_changed is None:
                return False
            if conn_changed:
                changed = True

        return True

    def is_solved(state):
        lo, hi = state
        for e in range(ecount):
            if lo[e] != hi[e]:
                return False
        for i in range(m):
            s = sum(lo[e] for e in incident[i])
            if s != targets[i]:
                return False
        return connectivity_feasible(state) and connected_by_positive(state)

    def connected_by_positive(state):
        lo, hi = state
        seen = set([0])
        q = deque([0])
        while q:
            u = q.popleft()
            for e in incident[u]:
                if lo[e] > 0:
                    a, b = edge_endpoints[e]
                    v = b if a == u else a
                    if v not in seen:
                        seen.add(v)
                        q.append(v)
        return len(seen) == m

    def component_exit_count(state, comp_nodes):
        lo, hi = state
        s = set(comp_nodes)
        out = []
        for e, (u, v) in enumerate(edge_endpoints):
            if hi[e] <= 0:
                continue
            if (u in s) ^ (v in s):
                out.append(e)
        return out

    def choose_branch(state):
        lo, hi = state

        # Prefer islands with the tightest remaining degree distribution.
        best = None
        best_key = None

        for i in range(m):
            inc = incident[i]
            vals = []
            for e in inc:
                if lo[e] != hi[e]:
                    vals.append(e)
            if not vals:
                continue
            t = targets[i]
            s_lo = sum(lo[e] for e in inc)
            s_hi = sum(hi[e] for e in inc)
            slack = s_hi - s_lo
            key = (len(vals), slack, -len(inc))
            if best_key is None or key < best_key:
                best_key = key
                best = ("island", i, vals)

        # Prefer branching on a highly constrained edge, especially one involved in crossings.
        best_edge = None
        best_edge_key = None
        for e in range(ecount):
            if lo[e] != hi[e]:
                domain_size = hi[e] - lo[e] + 1
                u, v = edge_endpoints[e]
                deg_pressure = (targets[u], targets[v])
                key = (domain_size, -len(crossings[e]), -sum(deg_pressure))
                if best_edge_key is None or key < best_edge_key:
                    best_edge_key = key
                    best_edge = e

        if best_edge is None:
            return None

        return ("edge", best_edge)

    def candidate_values_for_edge(state, e):
        lo, hi = state
        vals = list(range(lo[e], hi[e] + 1))

        # Prefer positive values first when connectivity or degree pressure suggests so.
        u, v = edge_endpoints[e]
        need_u = targets[u] - sum(lo[x] for x in incident[u])
        need_v = targets[v] - sum(lo[x] for x in incident[v])

        vals.sort(key=lambda x: (
            0 if (x > 0 and (need_u > 0 or need_v > 0)) else 1,
            0 if x == hi[e] else 1,
            x
        ))
        return vals

    def search(state):
        if not propagate(state):
            return None
        if is_solved(state):
            return state

        branch = choose_branch(state)
        if branch is None:
            return None

        _, e = branch
        for val in candidate_values_for_edge(state, e):
            new_state = clone_state(state)
            if assign_edge(new_state, e, val):
                res = search(new_state)
                if res is not None:
                    return res
        return None

    result = search(initial_state())
    if result is None:
        return "No Solution"

    lo, hi = result
    answer = {}
    for e, cnt in enumerate(lo):
        if cnt > 0:
            a = edges[e]["a"]
            b = edges[e]["b"]
            answer[(a, b)] = cnt
    return answer


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 1, None], [None, 2, 3, 4, None], [None, 3, 6, 6, None], [None, 5, None, 8, None], [None, None, 6, None, None]]}

# General solver for the "3x3 neighborhood black-count" puzzle.
# A cell is binary: black (1 / 'B') or white (0 / None).
# Each numbered cell constrains the sum of black cells in its 3x3 neighborhood.

from collections import deque


def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0
    nvars = h * w

    def vid(r, c):
        return r * w + c

    def rc(v):
        return divmod(v, w)

    # Build constraints from numbered cells.
    constraints = []
    var_to_constraints = [[] for _ in range(nvars)]

    for r in range(h):
        for c in range(w):
            val = data[r][c]
            if val is None:
                continue
            scope = []
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    scope.append(vid(rr, cc))
            cid = len(constraints)
            constraints.append({
                "scope": tuple(scope),
                "target": val,
            })
            for v in scope:
                var_to_constraints[v].append(cid)

    if not constraints:
        # No clues: all white is a valid solution.
        ans = [[None for _ in range(w)] for _ in range(h)]
        return repr(ans)

    # Precompute subset relations between scopes for stronger human-like deductions.
    scope_sets = [set(c["scope"]) for c in constraints]
    subset_pairs = []
    for i in range(len(constraints)):
        si = scope_sets[i]
        for j in range(len(constraints)):
            if i == j:
                continue
            sj = scope_sets[j]
            if si < sj:
                subset_pairs.append((i, j, tuple(sorted(sj - si))))

    # State:
    # assign[v] in {-1 unknown, 0 white, 1 black}
    # For each constraint:
    #   known_black[cid]
    #   unknown_count[cid]
    assign = [-1] * nvars
    known_black = [0] * len(constraints)
    unknown_count = [len(c["scope"]) for c in constraints]
    unknown_sets = [set(c["scope"]) for c in constraints]

    # Quick initial feasibility check.
    for cid, c in enumerate(constraints):
        t = c["target"]
        if t < 0 or t > len(c["scope"]):
            return "No Solution"

    # Queue of constraints to process.
    q = deque(range(len(constraints)))
    in_q = [True] * len(constraints)

    def assign_var(v, value):
        cur = assign[v]
        if cur == value:
            return True
        if cur != -1:
            return False
        assign[v] = value
        for cid in var_to_constraints[v]:
            if v in unknown_sets[cid]:
                unknown_sets[cid].remove(v)
                unknown_count[cid] -= 1
                if value == 1:
                    known_black[cid] += 1
                if not in_q[cid]:
                    q.append(cid)
                    in_q[cid] = True
        return True

    def constraint_bounds_ok(cid):
        need = constraints[cid]["target"] - known_black[cid]
        unk = unknown_count[cid]
        return 0 <= need <= unk

    def propagate():
        # Repeatedly apply direct saturation rules and subset-difference deductions.
        while q:
            cid = q.popleft()
            in_q[cid] = False

            if not constraint_bounds_ok(cid):
                return False

            need = constraints[cid]["target"] - known_black[cid]
            unk = unknown_count[cid]

            # Direct human rule:
            # If all remaining blacks are exhausted -> rest white.
            # If all unknowns must be black -> fill them black.
            if need == 0:
                for v in tuple(unknown_sets[cid]):
                    if not assign_var(v, 0):
                        return False
            elif need == unk:
                for v in tuple(unknown_sets[cid]):
                    if not assign_var(v, 1):
                        return False

            # Stronger human-like subset rule:
            # If scope(A) subset scope(B), then the difference scope(B)\scope(A)
            # must contain exactly target(B)-target(A) blacks after accounting
            # for current assignments. This yields more forced cells.
            for a, b, diff in subset_pairs:
                # Only process pairs involving the recently updated constraint
                # to keep propagation focused.
                if a != cid and b != cid:
                    continue

                # Current residuals over full scopes.
                need_a = constraints[a]["target"] - known_black[a]
                need_b = constraints[b]["target"] - known_black[b]
                if need_a < 0 or need_b < 0:
                    return False
                if need_a > unknown_count[a] or need_b > unknown_count[b]:
                    return False

                # Over the difference set B\A, assigned blacks already present:
                diff_unknown = []
                diff_black = 0
                for v in diff:
                    av = assign[v]
                    if av == -1:
                        diff_unknown.append(v)
                    elif av == 1:
                        diff_black += 1

                # Since A subset B:
                # blacks(diff) = target(B)-target(A), but residual form must account
                # for assigned blacks both inside and outside.
                # A cleaner dynamic equation:
                # residual blacks available in diff equals need_b - need_a.
                need_diff = need_b - need_a

                # Feasibility:
                if need_diff < diff_black:
                    return False
                rem_need_diff = need_diff - diff_black
                if rem_need_diff < 0 or rem_need_diff > len(diff_unknown):
                    return False

                if rem_need_diff == 0:
                    for v in diff_unknown:
                        if not assign_var(v, 0):
                            return False
                elif rem_need_diff == len(diff_unknown):
                    for v in diff_unknown:
                        if not assign_var(v, 1):
                            return False

        # Final consistency sweep.
        for cid in range(len(constraints)):
            if not constraint_bounds_ok(cid):
                return False
        return True

    # Better branching: choose variable with maximal constrainedness.
    # Score uses how tight its neighboring constraints are.
    def choose_var():
        best_v = None
        best_key = None
        for v in range(nvars):
            if assign[v] != -1:
                continue
            if not var_to_constraints[v]:
                # Unconstrained cells can be safely white unless search needs them.
                key = (-1, -1, -1)
            else:
                degree = len(var_to_constraints[v])
                tightness = 0
                forcedness = 0
                for cid in var_to_constraints[v]:
                    need = constraints[cid]["target"] - known_black[cid]
                    unk = unknown_count[cid]
                    # Smaller slack => tighter.
                    slack = min(need, unk - need)
                    tightness += (10 - slack)
                    forcedness += abs(2 * need - unk)
                key = (degree, tightness, forcedness)
            if best_key is None or key > best_key:
                best_key = key
                best_v = v
        return best_v

    # Value ordering: try the value that best matches local clue pressure.
    def value_order(v):
        score_black = 0
        score_white = 0
        for cid in var_to_constraints[v]:
            need = constraints[cid]["target"] - known_black[cid]
            unk = unknown_count[cid]
            # Preference for black if need/unk is large.
            score_black += need
            score_white += (unk - need)
        return [1, 0] if score_black >= score_white else [0, 1]

    def snapshot():
        return (
            assign[:],
            known_black[:],
            unknown_count[:],
            [s.copy() for s in unknown_sets],
            deque(q),
            in_q[:],
        )

    def restore(state):
        nonlocal assign, known_black, unknown_count, unknown_sets, q, in_q
        assign, known_black, unknown_count, unknown_sets, q_saved, in_q = state
        q = deque(q_saved)

    # Initial propagation.
    if not propagate():
        return "No Solution"

    # Any cell unconstrained by all clues can be set white immediately.
    for v in range(nvars):
        if assign[v] == -1 and not var_to_constraints[v]:
            assign[v] = 0

    def solved():
        # All constraints exactly satisfied and all vars determined.
        for cid, c in enumerate(constraints):
            if known_black[cid] != c["target"] or unknown_count[cid] != 0:
                return False
        return all(a != -1 for a in assign)

    def finalize_if_all_constraints_satisfied():
        # Remaining unconstrained unknowns -> white.
        ok = True
        for cid, c in enumerate(constraints):
            if known_black[cid] > c["target"]:
                ok = False
                break
            if known_black[cid] + unknown_count[cid] < c["target"]:
                ok = False
                break
        if not ok:
            return False
        done = True
        for cid, c in enumerate(constraints):
            if known_black[cid] != c["target"] or unknown_count[cid] != 0:
                done = False
                break
        if done:
            for v in range(nvars):
                if assign[v] == -1:
                    assign[v] = 0
            return True
        return False

    def dfs():
        if finalize_if_all_constraints_satisfied():
            return True
        v = choose_var()
        if v is None:
            return solved()

        for val in value_order(v):
            st = snapshot()
            if assign_var(v, val) and propagate():
                # Opportunistically whiten unconstrained unknowns.
                for u in range(nvars):
                    if assign[u] == -1 and not var_to_constraints[u]:
                        assign[u] = 0
                if dfs():
                    return True
            restore(st)
        return False

    if not dfs():
        return "No Solution"

    ans = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append('B' if assign[vid(r, c)] == 1 else None)
        ans.append(row)
    return repr(ans)


if __name__ == "__main__":
    print(solve(OBSERVATION))

