from collections import deque

# Black/white filling puzzle:
# Each numbered cell gives the number of black cells in its 3x3 neighborhood.

def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0
    n = h * w

    def vid(r, c):
        return r * w + c

    def rc(v):
        return divmod(v, w)

    # Build base constraints: sum(vars in 3x3 neighborhood) == clue
    base_constraints = []
    var_to_constraints = [[] for _ in range(n)]
    for r in range(h):
        for c in range(w):
            clue = data[r][c]
            if clue is None:
                continue
            cells = []
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    cells.append(vid(rr, cc))
            idx = len(base_constraints)
            base_constraints.append((tuple(sorted(cells)), clue))
            for v in cells:
                var_to_constraints[v].append(idx)

    # State:
    # -1 unknown, 0 white, 1 black
    initial = [-1] * n

    # Fast residual computation for one constraint
    def residual_of_constraint(state, cons):
        vars_, target = cons
        s = 0
        unknown = []
        for v in vars_:
            val = state[v]
            if val == -1:
                unknown.append(v)
            else:
                s += val
        rhs = target - s
        return unknown, rhs

    # Generate residual constraints and useful subset-derived constraints.
    # We only keep constraints over unknown variables.
    def build_residual_constraints(state):
        exact = {}
        raw = []
        for vars_, target in base_constraints:
            s = 0
            unknown = []
            for v in vars_:
                val = state[v]
                if val == -1:
                    unknown.append(v)
                else:
                    s += val
            rhs = target - s
            if rhs < 0 or rhs > len(unknown):
                return None
            if not unknown:
                if rhs != 0:
                    return None
                continue
            key = frozenset(unknown)
            prev = exact.get(key)
            if prev is None:
                exact[key] = rhs
            elif prev != rhs:
                return None

        raw = [(set(k), v) for k, v in exact.items()]

        # Subset derivation:
        # if A subset B, then sum(B\A) = rhsB-rhsA.
        # Iterate to closure, but bounded by practical size.
        changed = True
        while changed:
            changed = False
            items = list(exact.items())
            m = len(items)
            for i in range(m):
                A, a = items[i]
                for j in range(i + 1, m):
                    B, b = items[j]
                    if len(A) <= len(B):
                        small, sval, large, lval = A, a, B, b
                    else:
                        small, sval, large, lval = B, b, A, a
                    if small.issubset(large):
                        diff = large - small
                        rhs = lval - sval
                        if rhs < 0 or rhs > len(diff):
                            return None
                        if diff:
                            prev = exact.get(diff)
                            if prev is None:
                                exact[diff] = rhs
                                changed = True
                            elif prev != rhs:
                                return None
                        else:
                            if rhs != 0:
                                return None

        return [(tuple(sorted(k)), v) for k, v in exact.items()]

    # Strong propagation from residual constraints
    def propagate(state):
        state = state[:]  # copy-on-entry for clean branching
        while True:
            residuals = build_residual_constraints(state)
            if residuals is None:
                return None

            changed = False

            # Direct min/max forcing
            for vars_, rhs in residuals:
                ln = len(vars_)
                if rhs < 0 or rhs > ln:
                    return None
                if rhs == 0:
                    for v in vars_:
                        if state[v] == -1:
                            state[v] = 0
                            changed = True
                        elif state[v] != 0:
                            return None
                elif rhs == ln:
                    for v in vars_:
                        if state[v] == -1:
                            state[v] = 1
                            changed = True
                        elif state[v] != 1:
                            return None

            if changed:
                continue

            # Variable-level lookahead inside each residual constraint:
            # For x in vars with sum(vars)=rhs:
            # - if assigning x=1 makes remaining impossible, then x=0
            # - if assigning x=0 makes remaining impossible, then x=1
            forced = []
            for vars_, rhs in residuals:
                ln = len(vars_)
                # For any x:
                # with x=1, remaining need rhs-1 among ln-1 vars => feasible iff 0 <= rhs-1 <= ln-1
                # with x=0, remaining need rhs   among ln-1 vars => feasible iff 0 <= rhs   <= ln-1
                feas_if_1 = (0 <= rhs - 1 <= ln - 1)
                feas_if_0 = (0 <= rhs <= ln - 1)
                if not feas_if_1:
                    for v in vars_:
                        forced.append((v, 0))
                elif not feas_if_0:
                    for v in vars_:
                        forced.append((v, 1))

            if forced:
                for v, val in forced:
                    if state[v] == -1:
                        state[v] = val
                        changed = True
                    elif state[v] != val:
                        return None
                if changed:
                    continue

            # No more progress
            return state

    # Choose a highly constrained variable for branching
    def choose_var(state):
        residuals = build_residual_constraints(state)
        if residuals is None:
            return None, None

        score = [0] * n
        preferred = [0] * n
        for vars_, rhs in residuals:
            ln = len(vars_)
            tight = min(rhs, ln - rhs)
            weight = 100 - ln * 3 + tight * 5
            for v in vars_:
                if state[v] == -1:
                    score[v] += weight
                    # crude preferred value from local density
                    preferred[v] += rhs * 2 - ln

        best = -1
        best_score = None
        for v in range(n):
            if state[v] != -1:
                continue
            s = score[v]
            if best == -1 or s > best_score:
                best = v
                best_score = s

        if best == -1:
            return None, None

        # Try more plausible value first
        first = 1 if preferred[best] > 0 else 0
        return best, first

    def is_complete(state):
        return all(v != -1 for v in state)

    def dfs(state):
        state = propagate(state)
        if state is None:
            return None
        if is_complete(state):
            # Final verification
            for vars_, target in base_constraints:
                s = sum(state[v] for v in vars_)
                if s != target:
                    return None
            return state

        v, first = choose_var(state)
        if v is None:
            return None

        for val in (first, 1 - first):
            nxt = state[:]
            nxt[v] = val
            ans = dfs(nxt)
            if ans is not None:
                return ans
        return None

    result = dfs(initial)
    if result is None:
        return "No Solution"

    out = []
    for r in range(h):
        row = []
        for c in range(w):
            row.append('B' if result[vid(r, c)] == 1 else None)
        out.append(row)
    return repr(out)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], [None, 3, 2, 2, 1, None], [None, None, 3, None, 3, None], [1, 2, None, 2, None, 1], [1, None, 3, 2, None, 1], [None, None, 1, None, 1, None]]}

# General Slant solver:
# - exactly one diagonal per cell
# - each numbered dot has exact incident count
# - no closed loops
#
# The solver is designed around strong propagation:
# 1) Dot-count propagation (min/max, forced inclusion/exclusion)
# 2) Immediate loop prevention using rollback union-find
# 3) MRV branching only when deduction stalls
#
# Representation:
#   cell state: bitmask
#       1 -> '/'
#       2 -> '\'
#       3 -> undecided
#
# Edges induced by a cell (r,c):
#   '/'  connects dot (r, c+1) to (r+1, c)
#   '\' connects dot (r, c)   to (r+1, c+1)

from collections import deque

SLASH = 1
BACKSLASH = 2
BOTH = SLASH | BACKSLASH

def solve(observation):
    data = observation['data']
    n1 = len(data)
    if n1 == 0 or any(len(row) != n1 for row in data):
        return "No Solution"
    n = n1 - 1

    def dot_id(r, c):
        return r * (n + 1) + c

    # For each cell, precompute endpoints for each orientation.
    cell_edges = []
    for r in range(n):
        row = []
        for c in range(n):
            slash = (dot_id(r, c + 1), dot_id(r + 1, c))
            backslash = (dot_id(r, c), dot_id(r + 1, c + 1))
            row.append({SLASH: slash, BACKSLASH: backslash})
        cell_edges.append(row)

    # For each dot, list incident (cell, orientation, contributes=1).
    # A cell adjacent to a dot contributes iff its chosen diagonal touches that dot.
    dot_inc = [[[] for _ in range(n + 1)] for _ in range(n + 1)]
    for r in range(n):
        for c in range(n):
            # '/' touches (r,c+1) and (r+1,c)
            dot_inc[r][c + 1].append((r, c, SLASH))
            dot_inc[r + 1][c].append((r, c, SLASH))
            # '\' touches (r,c) and (r+1,c+1)
            dot_inc[r][c].append((r, c, BACKSLASH))
            dot_inc[r + 1][c + 1].append((r, c, BACKSLASH))

    clues = data

    class RollbackDSU:
        __slots__ = ("parent", "size", "hist")
        def __init__(self, m):
            self.parent = list(range(m))
            self.size = [1] * m
            self.hist = []

        def find(self, x):
            while self.parent[x] != x:
                x = self.parent[x]
            return x

        def union(self, a, b):
            ra = self.find(a)
            rb = self.find(b)
            if ra == rb:
                self.hist.append((-1, -1, -1))
                return False
            if self.size[ra] < self.size[rb]:
                ra, rb = rb, ra
            self.hist.append((rb, ra, self.size[ra]))
            self.parent[rb] = ra
            self.size[ra] += self.size[rb]
            return True

        def snapshot(self):
            return len(self.hist)

        def rollback(self, snap):
            while len(self.hist) > snap:
                rb, ra, old_size = self.hist.pop()
                if rb == -1:
                    continue
                self.parent[rb] = rb
                self.size[ra] = old_size

    total_dots = (n + 1) * (n + 1)

    class State:
        __slots__ = ("domains", "assigned", "remaining", "dsu", "queue_dots", "queue_cells")

        def __init__(self):
            self.domains = [[BOTH for _ in range(n)] for _ in range(n)]
            self.assigned = 0
            self.remaining = n * n
            self.dsu = RollbackDSU(total_dots)
            self.queue_dots = deque()
            self.queue_cells = deque()

    def is_single(mask):
        return mask == SLASH or mask == BACKSLASH

    def single_val(mask):
        return SLASH if mask == SLASH else BACKSLASH

    def enqueue_neighbors_of_cell(st, r, c):
        for dr in (0, 1):
            for dc in (0, 1):
                rr, cc = r + dr, c + dc
                st.queue_dots.append((rr, cc))
        st.queue_cells.append((r, c))

    def assign_cell(st, r, c, val):
        cur = st.domains[r][c]
        if cur == val:
            return True
        if (cur & val) == 0:
            return False
        st.domains[r][c] = val
        if cur == BOTH:
            st.assigned += 1
            st.remaining -= 1
            a, b = cell_edges[r][c][val]
            if st.dsu.find(a) == st.dsu.find(b):
                return False
            st.dsu.union(a, b)
        enqueue_neighbors_of_cell(st, r, c)
        return True

    def remove_orientation(st, r, c, val):
        cur = st.domains[r][c]
        if (cur & val) == 0:
            return True
        new_mask = cur & (~val)
        if new_mask == 0:
            return False
        if new_mask == cur:
            return True
        if is_single(cur):
            return False
        return assign_cell(st, r, c, new_mask)

    def loop_filter_cell(st, r, c):
        mask = st.domains[r][c]
        if is_single(mask):
            return True
        allowed = 0
        for val in (SLASH, BACKSLASH):
            if mask & val:
                a, b = cell_edges[r][c][val]
                if st.dsu.find(a) != st.dsu.find(b):
                    allowed |= val
        if allowed == 0:
            return False
        if allowed != mask:
            return assign_cell(st, r, c, allowed)
        return True

    def propagate_dot(st, r, c):
        clue = clues[r][c]
        if clue is None:
            return True

        inc = dot_inc[r][c]
        current = 0
        possible = 0
        undec = []

        for cr, cc, ori in inc:
            mask = st.domains[cr][cc]
            if mask == ori:
                current += 1
                possible += 1
            elif mask & ori:
                possible += 1
                if mask == BOTH:
                    undec.append((cr, cc, ori))
            else:
                pass

        if current > clue or possible < clue:
            return False

        need = clue - current
        avail = possible - current

        if need == 0:
            for cr, cc, ori in undec:
                if not remove_orientation(st, cr, cc, ori):
                    return False
        elif need == avail:
            for cr, cc, ori in undec:
                if not assign_cell(st, cr, cc, ori):
                    return False

        return True

    def initial_seed(st):
        for r in range(n + 1):
            for c in range(n + 1):
                if clues[r][c] is not None:
                    st.queue_dots.append((r, c))
        for r in range(n):
            for c in range(n):
                st.queue_cells.append((r, c))
        return True

    def propagate_all(st):
        while st.queue_dots or st.queue_cells:
            while st.queue_dots:
                r, c = st.queue_dots.popleft()
                if not propagate_dot(st, r, c):
                    return False
            while st.queue_cells:
                r, c = st.queue_cells.popleft()
                if not loop_filter_cell(st, r, c):
                    return False
        return True

    def snapshot_state(st):
        return (
            [row[:] for row in st.domains],
            st.assigned,
            st.remaining,
            st.dsu.snapshot(),
            list(st.queue_dots),
            list(st.queue_cells),
        )

    def restore_state(st, snap):
        domains, assigned, remaining, dsu_snap, qd, qc = snap
        st.domains = [row[:] for row in domains]
        st.assigned = assigned
        st.remaining = remaining
        st.dsu.rollback(dsu_snap)
        st.queue_dots = deque(qd)
        st.queue_cells = deque(qc)

    def choose_branch_cell(st):
        # MRV on undecided cells, tie-break by involvement in constrained dots.
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                if st.domains[r][c] != BOTH:
                    continue
                score = 0
                for dr in (0, 1):
                    for dc in (0, 1):
                        clue = clues[r + dr][c + dc]
                        if clue is not None:
                            score += 1
                key = (-score, r, c)
                if best is None or key < best_score:
                    best = (r, c)
                    best_score = key
        return best

    def orientation_priority(st, r, c):
        # Prefer orientation that better satisfies nearby tight clues.
        scores = []
        for val in (SLASH, BACKSLASH):
            s = 0
            for dr in (0, 1):
                for dc in (0, 1):
                    rr, cc = r + dr, c + dc
                    clue = clues[rr][cc]
                    if clue is None:
                        continue
                    touches = False
                    if val == SLASH:
                        touches = (rr == r and cc == c + 1) or (rr == r + 1 and cc == c)
                    else:
                        touches = (rr == r and cc == c) or (rr == r + 1 and cc == c + 1)
                    # Gentle heuristic: favor touching larger clues.
                    s += clue if touches else 0
            scores.append((s, val))
        scores.sort(reverse=True)
        return [v for _, v in scores]

    def final_check(st):
        # Dot counts exact
        for r in range(n + 1):
            for c in range(n + 1):
                clue = clues[r][c]
                if clue is None:
                    continue
                cnt = 0
                for cr, cc, ori in dot_inc[r][c]:
                    if st.domains[cr][cc] == ori:
                        cnt += 1
                if cnt != clue:
                    return False
        # No cycles already guaranteed incrementally; graph is a forest.
        return True

    def dfs(st):
        if not propagate_all(st):
            return None
        if st.remaining == 0:
            if final_check(st):
                return [[('/' if st.domains[r][c] == SLASH else '\\') for c in range(n)] for r in range(n)]
            return None

        rc = choose_branch_cell(st)
        if rc is None:
            return None
        r, c = rc
        for val in orientation_priority(st, r, c):
            snap = snapshot_state(st)
            if assign_cell(st, r, c, val):
                ans = dfs(st)
                if ans is not None:
                    return ans
            restore_state(st, snap)
        return None

    st = State()
    initial_seed(st)
    ans = dfs(st)
    return ans if ans is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

