from copy import deepcopy

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    # Cell indexing helpers
    def idx(r, c):
        return r * n + c

    def rc(i):
        return divmod(i, n)

    num_cells = n * n

    # Regions
    region_ids = sorted({x for row in data for x in row})
    rid_to_cells = {rid: [] for rid in region_ids}
    cell_region = [None] * num_cells
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            rid = data[r][c]
            rid_to_cells[rid].append(i)
            cell_region[i] = rid

    # Adjacency masks: stars cannot touch orthogonally or diagonally
    adj_mask = [0] * num_cells
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            m = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < n:
                        m |= 1 << idx(rr, cc)
            adj_mask[i] = m

    row_cells = [[idx(r, c) for c in range(n)] for r in range(n)]
    col_cells = [[idx(r, c) for r in range(n)] for c in range(n)]

    # Candidate pair masks for each region: exactly 2 stars per region, non-touching.
    region_candidates = {}
    cell_bit = [1 << i for i in range(num_cells)]
    for rid, cells in rid_to_cells.items():
        cand = []
        L = len(cells)
        for a in range(L):
            i = cells[a]
            for b in range(a + 1, L):
                j = cells[b]
                if not (adj_mask[i] & cell_bit[j]):
                    cand.append(cell_bit[i] | cell_bit[j])
        if not cand:
            return "No Solution"
        region_candidates[rid] = cand

    # Precompute cells in each row/col as masks
    row_masks = []
    col_masks = []
    for r in range(n):
        m = 0
        for i in row_cells[r]:
            m |= cell_bit[i]
        row_masks.append(m)
    for c in range(n):
        m = 0
        for i in col_cells[c]:
            m |= cell_bit[i]
        col_masks.append(m)

    all_region_cells_mask = {}
    for rid, cells in rid_to_cells.items():
        m = 0
        for i in cells:
            m |= cell_bit[i]
        all_region_cells_mask[rid] = m

    # State:
    # cell_state[i] = 1 star, 0 empty, -1 undecided
    init_state = {
        'cell_state': [-1] * num_cells,
        'region_candidates': {rid: list(cands) for rid, cands in region_candidates.items()},
    }

    def popcount(x):
        return x.bit_count()

    def set_star(state, i):
        cs = state['cell_state']
        if cs[i] == 1:
            return True
        if cs[i] == 0:
            return False
        cs[i] = 1
        # Neighbors must be empty
        neigh = adj_mask[i]
        while neigh:
            lsb = neigh & -neigh
            j = lsb.bit_length() - 1
            if not set_empty(state, j):
                return False
            neigh ^= lsb
        return True

    def set_empty(state, i):
        cs = state['cell_state']
        if cs[i] == 0:
            return True
        if cs[i] == 1:
            return False
        cs[i] = 0
        return True

    def region_union_and_intersection(cands):
        u = 0
        inter = None
        for m in cands:
            u |= m
            inter = m if inter is None else (inter & m)
        return u, (0 if inter is None else inter)

    def prune_region_candidates(state, rid):
        cs = state['cell_state']
        cands = state['region_candidates'][rid]
        new_cands = []

        # Forced stars already placed inside this region
        forced_star_mask = 0
        for i in rid_to_cells[rid]:
            if cs[i] == 1:
                forced_star_mask |= cell_bit[i]

        # Quick overfill in region
        if popcount(forced_star_mask) > 2:
            return False

        for m in cands:
            # Candidate must include all already forced stars in region
            if (m & forced_star_mask) != forced_star_mask:
                continue

            # Candidate cannot use empties
            bad = False
            mm = m
            while mm:
                lsb = mm & -mm
                i = lsb.bit_length() - 1
                if cs[i] == 0:
                    bad = True
                    break
                mm ^= lsb
            if bad:
                continue

            # Candidate must not push any row/col above 2 stars
            ok = True
            tmp = m
            while tmp and ok:
                lsb = tmp & -tmp
                i = lsb.bit_length() - 1
                r, c = rc(i)
                row_stars = sum(1 for j in row_cells[r] if cs[j] == 1 and j != i)
                col_stars = sum(1 for j in col_cells[c] if cs[j] == 1 and j != i)
                if row_stars >= 2 or col_stars >= 2:
                    ok = False
                    break
                tmp ^= lsb
            if ok:
                new_cands.append(m)

        if not new_cands:
            return False
        if len(new_cands) != len(cands):
            state['region_candidates'][rid] = new_cands
        return True

    def possible_star_mask_for_line(state, cell_list):
        m = 0
        for i in cell_list:
            if state['cell_state'][i] == 1:
                m |= cell_bit[i]
            elif state['cell_state'][i] == -1:
                rid = cell_region[i]
                # If any candidate in region contains i, it is still possible
                for cand in state['region_candidates'][rid]:
                    if cand & cell_bit[i]:
                        m |= cell_bit[i]
                        break
        return m

    def propagate(state):
        changed = True
        while changed:
            changed = False
            cs = state['cell_state']

            # Prune region candidates against cell assignments
            for rid in region_ids:
                old_len = len(state['region_candidates'][rid])
                if not prune_region_candidates(state, rid):
                    return False
                if len(state['region_candidates'][rid]) != old_len:
                    changed = True

            # Region deductions
            for rid in region_ids:
                cands = state['region_candidates'][rid]
                union_mask, inter_mask = region_union_and_intersection(cands)

                # Cells not in any candidate are empty
                region_mask = all_region_cells_mask[rid]
                impossible = region_mask & ~union_mask
                tmp = impossible
                while tmp:
                    lsb = tmp & -tmp
                    i = lsb.bit_length() - 1
                    if not set_empty(state, i):
                        return False
                    tmp ^= lsb

                # Cells in all candidates are stars
                tmp = inter_mask
                while tmp:
                    lsb = tmp & -tmp
                    i = lsb.bit_length() - 1
                    if not set_star(state, i):
                        return False
                    tmp ^= lsb

                # If only one candidate remains, enforce it exactly
                if len(cands) == 1:
                    m = cands[0]
                    tmp = region_mask
                    while tmp:
                        lsb = tmp & -tmp
                        i = lsb.bit_length() - 1
                        if m & lsb:
                            if not set_star(state, i):
                                return False
                        else:
                            if not set_empty(state, i):
                                return False
                        tmp ^= lsb

            # Row/column deductions
            for r in range(n):
                line = row_cells[r]
                stars = [i for i in line if cs[i] == 1]
                if len(stars) > 2:
                    return False
                possible_mask = possible_star_mask_for_line(state, line)
                possible_count = popcount(possible_mask)
                if possible_count < 2:
                    return False
                if len(stars) == 2:
                    for i in line:
                        if cs[i] == -1:
                            if not set_empty(state, i):
                                return False
                else:
                    # Count cells still capable of being stars
                    undecided_possible = [i for i in line if possible_mask & cell_bit[i] and cs[i] != 1]
                    needed = 2 - len(stars)
                    if len(undecided_possible) < needed:
                        return False
                    if len(undecided_possible) == needed:
                        for i in undecided_possible:
                            if not set_star(state, i):
                                return False

            for c in range(n):
                line = col_cells[c]
                stars = [i for i in line if cs[i] == 1]
                if len(stars) > 2:
                    return False
                possible_mask = possible_star_mask_for_line(state, line)
                possible_count = popcount(possible_mask)
                if possible_count < 2:
                    return False
                if len(stars) == 2:
                    for i in line:
                        if cs[i] == -1:
                            if not set_empty(state, i):
                                return False
                else:
                    undecided_possible = [i for i in line if possible_mask & cell_bit[i] and cs[i] != 1]
                    needed = 2 - len(stars)
                    if len(undecided_possible) < needed:
                        return False
                    if len(undecided_possible) == needed:
                        for i in undecided_possible:
                            if not set_star(state, i):
                                return False

            # Re-prune after line deductions
            for rid in region_ids:
                old_len = len(state['region_candidates'][rid])
                if not prune_region_candidates(state, rid):
                    return False
                if len(state['region_candidates'][rid]) != old_len:
                    changed = True

            # Validate line upper/lower bounds with current possibilities
            for r in range(n):
                line = row_cells[r]
                placed = sum(1 for i in line if cs[i] == 1)
                if placed > 2:
                    return False
                possible = 0
                for i in line:
                    if cs[i] == 1:
                        possible += 1
                    elif cs[i] == -1:
                        rid = cell_region[i]
                        if any(cand & cell_bit[i] for cand in state['region_candidates'][rid]):
                            possible += 1
                if possible < 2:
                    return False

            for c in range(n):
                line = col_cells[c]
                placed = sum(1 for i in line if cs[i] == 1)
                if placed > 2:
                    return False
                possible = 0
                for i in line:
                    if cs[i] == 1:
                        possible += 1
                    elif cs[i] == -1:
                        rid = cell_region[i]
                        if any(cand & cell_bit[i] for cand in state['region_candidates'][rid]):
                            possible += 1
                if possible < 2:
                    return False

        return True

    def is_solved(state):
        cs = state['cell_state']
        for rid in region_ids:
            if len(state['region_candidates'][rid]) != 1:
                return False
        for r in range(n):
            if sum(1 for i in row_cells[r] if cs[i] == 1) != 2:
                return False
        for c in range(n):
            if sum(1 for i in col_cells[c] if cs[i] == 1) != 2:
                return False
        return True

    def score_candidate(state, rid, cand):
        # Lower score = better branch first
        cs = state['cell_state']
        row_need = [2 - sum(1 for i in row_cells[r] if cs[i] == 1) for r in range(n)]
        col_need = [2 - sum(1 for i in col_cells[c] if cs[i] == 1) for c in range(n)]
        s = 0
        tmp = cand
        while tmp:
            lsb = tmp & -tmp
            i = lsb.bit_length() - 1
            r, c = rc(i)
            s -= 3 * max(0, row_need[r])
            s -= 3 * max(0, col_need[c])
            s += popcount(adj_mask[i])  # slightly prefer constraining cells
            tmp ^= lsb
        return s

    def choose_branch_region(state):
        # Most constrained region first
        best = None
        best_key = None
        cs = state['cell_state']
        for rid in region_ids:
            cands = state['region_candidates'][rid]
            if len(cands) <= 1:
                continue

            union_mask, _ = region_union_and_intersection(cands)
            possible_cells = popcount(union_mask)
            placed = sum(1 for i in rid_to_cells[rid] if cs[i] == 1)
            key = (len(cands), possible_cells, -placed, -len(rid_to_cells[rid]))
            if best is None or key < best_key:
                best = rid
                best_key = key
        return best

    def dfs(state):
        if not propagate(state):
            return None
        if is_solved(state):
            return state

        rid = choose_branch_region(state)
        if rid is None:
            return None

        cands = sorted(state['region_candidates'][rid], key=lambda m: score_candidate(state, rid, m))
        for cand in cands:
            new_state = {
                'cell_state': state['cell_state'][:],
                'region_candidates': {k: (v[:] if k != rid else [cand]) for k, v in state['region_candidates'].items()},
            }
            region_mask = all_region_cells_mask[rid]
            tmp = region_mask
            ok = True
            while tmp:
                lsb = tmp & -tmp
                i = lsb.bit_length() - 1
                if cand & lsb:
                    ok = set_star(new_state, i)
                else:
                    ok = set_empty(new_state, i)
                if not ok:
                    break
                tmp ^= lsb
            if not ok:
                continue

            res = dfs(new_state)
            if res is not None:
                return res
        return None

    result = dfs(init_state)
    if result is None:
        return "No Solution"

    answer = []
    cs = result['cell_state']
    for r in range(n):
        row = []
        for c in range(n):
            row.append('S' if cs[idx(r, c)] == 1 else None)
        answer.append(row)
    return str(answer)


