# Akari / Light Up solver
# Board encoding in observation:
#   None -> white cell
#   -1   -> unnumbered black cell
#   0..4 -> numbered black cell
#
# Returned answer:
#   repr(NxN grid) with 'B' on bulb cells and None elsewhere

from copy import deepcopy

UNKNOWN = 0
BULB = 1
EMPTY = -1


def solve(observation):
    data = observation["data"]
    n = len(data)
    m = len(data[0]) if n else 0

    white_cells = []
    black_cells = set()
    numbered = {}

    for r in range(n):
        for c in range(m):
            v = data[r][c]
            if v is None:
                white_cells.append((r, c))
            else:
                black_cells.add((r, c))
                if v != -1:
                    numbered[(r, c)] = v

    white_set = set(white_cells)

    # Precompute row/col visibility peers and support sets.
    row_seg_id = {}
    col_seg_id = {}
    row_segments = []
    col_segments = []

    for r in range(n):
        c = 0
        while c < m:
            if (r, c) in black_cells:
                c += 1
                continue
            seg = []
            while c < m and (r, c) not in black_cells:
                seg.append((r, c))
                c += 1
            idx = len(row_segments)
            row_segments.append(seg)
            for cell in seg:
                row_seg_id[cell] = idx

    for c in range(m):
        r = 0
        while r < n:
            if (r, c) in black_cells:
                r += 1
                continue
            seg = []
            while r < n and (r, c) not in black_cells:
                seg.append((r, c))
                r += 1
            idx = len(col_segments)
            col_segments.append(seg)
            for cell in seg:
                col_seg_id[cell] = idx

    visible_peers = {}
    supports = {}
    for cell in white_cells:
        rs = row_segments[row_seg_id[cell]]
        cs = col_segments[col_seg_id[cell]]
        peers = set(rs) | set(cs)
        peers.remove(cell)
        visible_peers[cell] = tuple(peers)
        supports[cell] = tuple(set(rs) | set(cs))

    # Adjacent white cells for numbered blacks; reverse mapping too.
    adj_whites = {}
    incident_numbers = {cell: [] for cell in white_cells}
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for bcell, num in numbered.items():
        r, c = bcell
        arr = []
        for dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if (nr, nc) in white_set:
                arr.append((nr, nc))
                incident_numbers[(nr, nc)].append(bcell)
        adj_whites[bcell] = tuple(arr)

    # Segment membership for "at most one bulb in a segment"
    row_seg_cells = [tuple(seg) for seg in row_segments]
    col_seg_cells = [tuple(seg) for seg in col_segments]

    # Heuristic degrees
    degree = {}
    for cell in white_cells:
        degree[cell] = len(visible_peers[cell]) + len(incident_numbers[cell])

    def new_state():
        return {cell: UNKNOWN for cell in white_cells}

    def assign(state, cell, value):
        cur = state[cell]
        if cur == value:
            return True
        if cur != UNKNOWN and cur != value:
            return False
        if value == BULB:
            # Bulb cannot see another bulb.
            for peer in visible_peers[cell]:
                if state[peer] == BULB:
                    return False
        state[cell] = value
        return True

    def numbered_feasible(state, bcell):
        need = numbered[bcell]
        bulbs = 0
        undec = 0
        for cell in adj_whites[bcell]:
            if state[cell] == BULB:
                bulbs += 1
            elif state[cell] == UNKNOWN:
                undec += 1
        if bulbs > need:
            return False
        if bulbs + undec < need:
            return False
        return True

    def lit_status(state, cell):
        # returns (is_lit_now, possible_supports_when_unlit)
        poss = []
        for s in supports[cell]:
            if state[s] == BULB:
                return True, None
            if state[s] != EMPTY:
                poss.append(s)
        return False, poss

    def propagate(state):
        changed = True
        while changed:
            changed = False

            # 1) Segment constraints: if a segment has a bulb, all others in it are EMPTY.
            for seg in row_seg_cells:
                bulb = None
                for cell in seg:
                    if state[cell] == BULB:
                        bulb = cell
                        break
                if bulb is not None:
                    for cell in seg:
                        if cell != bulb and state[cell] == UNKNOWN:
                            if not assign(state, cell, EMPTY):
                                return False
                            changed = True
                        elif cell != bulb and state[cell] == BULB:
                            return False

            for seg in col_seg_cells:
                bulb = None
                for cell in seg:
                    if state[cell] == BULB:
                        bulb = cell
                        break
                if bulb is not None:
                    for cell in seg:
                        if cell != bulb and state[cell] == UNKNOWN:
                            if not assign(state, cell, EMPTY):
                                return False
                            changed = True
                        elif cell != bulb and state[cell] == BULB:
                            return False

            # 2) Numbered black deductions.
            for bcell in numbered:
                if not numbered_feasible(state, bcell):
                    return False
                need = numbered[bcell]
                bulbs = []
                undec = []
                for cell in adj_whites[bcell]:
                    if state[cell] == BULB:
                        bulbs.append(cell)
                    elif state[cell] == UNKNOWN:
                        undec.append(cell)
                if len(bulbs) == need:
                    for cell in undec:
                        if not assign(state, cell, EMPTY):
                            return False
                        changed = True
                elif len(bulbs) + len(undec) == need:
                    for cell in undec:
                        if not assign(state, cell, BULB):
                            return False
                        changed = True

            # 3) Illumination deductions.
            for cell in white_cells:
                is_lit, poss = lit_status(state, cell)
                if is_lit:
                    continue
                if not poss:
                    return False
                uniq = None
                if len(poss) == 1:
                    uniq = poss[0]
                else:
                    # Distinct-support forcedness:
                    # if among possible supports exactly one can legally be a bulb due to current segment conflicts,
                    # force it.
                    legal = []
                    for s in poss:
                        ok = True
                        for peer in visible_peers[s]:
                            if state[peer] == BULB:
                                ok = False
                                break
                        if ok:
                            legal.append(s)
                    if not legal:
                        return False
                    if len(legal) == 1:
                        uniq = legal[0]
                if uniq is not None and state[uniq] == UNKNOWN:
                    if not assign(state, uniq, BULB):
                        return False
                    changed = True

            # 4) Immediate contradiction checks.
            for bcell in numbered:
                if not numbered_feasible(state, bcell):
                    return False

            for cell in white_cells:
                if state[cell] == BULB:
                    for peer in visible_peers[cell]:
                        if state[peer] == BULB:
                            return False

            # 5) Additional local numbered-cell pattern:
            # If an UNKNOWN adjacent cell cannot be BULB because it would violate visibility,
            # treat it as effectively unavailable; numbered feasibility already sees UNKNOWN,
            # so we can convert impossible UNKNOWNs to EMPTY.
            for cell in white_cells:
                if state[cell] != UNKNOWN:
                    continue
                impossible = False
                for peer in visible_peers[cell]:
                    if state[peer] == BULB:
                        impossible = True
                        break
                if impossible:
                    if not assign(state, cell, EMPTY):
                        return False
                    changed = True
                    continue
                # If making it BULB would instantly break some numbered black lower/upper bound, eliminate it.
                state[cell] = BULB
                ok = True
                for bcell in incident_numbers[cell]:
                    if not numbered_feasible(state, bcell):
                        ok = False
                        break
                if ok:
                    # Also cannot create visible bulb conflict; already checked above.
                    pass
                state[cell] = UNKNOWN
                if not ok:
                    if not assign(state, cell, EMPTY):
                        return False
                    changed = True

        return True

    def is_solved(state):
        for bcell in numbered:
            need = numbered[bcell]
            bulbs = sum(1 for cell in adj_whites[bcell] if state[cell] == BULB)
            if bulbs != need:
                return False
        for cell in white_cells:
            if not lit_status(state, cell)[0]:
                return False
        for cell in white_cells:
            if state[cell] == BULB:
                for peer in visible_peers[cell]:
                    if state[peer] == BULB:
                        return False
        return True

    def choose_branch_cell(state):
        # Priority 1: numbered black with smallest unresolved slack.
        best = None
        best_key = None

        for bcell, need in numbered.items():
            bulbs = 0
            undec = []
            for cell in adj_whites[bcell]:
                if state[cell] == BULB:
                    bulbs += 1
                elif state[cell] == UNKNOWN:
                    undec.append(cell)
            if not undec:
                continue
            rem = need - bulbs
            # More constrained when undec small or rem near edges.
            key = (len(undec), min(rem, len(undec) - rem), 0)
            if best_key is None or key < best_key:
                best_key = key
                # choose the most connected cell among undec
                best = max(undec, key=lambda x: degree[x])

        if best is not None:
            return best

        # Priority 2: currently unlit cell with smallest number of possible supports.
        support_choice = None
        support_key = None
        for cell in white_cells:
            if state[cell] != UNKNOWN:
                continue
            # direct variable usefulness
            pass

        for cell in white_cells:
            lit, poss = lit_status(state, cell)
            if lit:
                continue
            legal = []
            for s in poss:
                if state[s] == UNKNOWN:
                    conflict = any(state[p] == BULB for p in visible_peers[s])
                    if not conflict:
                        legal.append(s)
            if legal:
                key = (len(legal), -max(degree[s] for s in legal))
                if support_key is None or key < support_key:
                    support_key = key
                    support_choice = max(legal, key=lambda x: degree[x])

        if support_choice is not None:
            return support_choice

        # Priority 3: any unknown cell, highest degree first.
        unknowns = [cell for cell in white_cells if state[cell] == UNKNOWN]
        if not unknowns:
            return None
        return max(unknowns, key=lambda x: degree[x])

    def branch_order(state, cell):
        # Decide whether to try BULB first or EMPTY first.
        # Try BULB first when cell is useful for some unmet numbered black or some currently unlit support.
        score = 0
        for bcell in incident_numbers[cell]:
            need = numbered[bcell]
            bulbs = sum(1 for x in adj_whites[bcell] if state[x] == BULB)
            undec = sum(1 for x in adj_whites[bcell] if state[x] == UNKNOWN)
            rem = need - bulbs
            if rem > 0:
                score += 3
            if rem == undec:
                score += 10
        for target in supports[cell]:
            lit, poss = lit_status(state, target)
            if not lit and poss and cell in poss:
                score += 1
        if score > 0:
            return (BULB, EMPTY)
        return (EMPTY, BULB)

    def search(state):
        if not propagate(state):
            return None
        if is_solved(state):
            return state

        cell = choose_branch_cell(state)
        if cell is None:
            return None

        for val in branch_order(state, cell):
            new_st = state.copy()
            if assign(new_st, cell, val):
                result = search(new_st)
                if result is not None:
                    return result
        return None

    result = search(new_state())
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(m)] for _ in range(n)]
    for r, c in white_cells:
        if result[(r, c)] == BULB:
            answer[r][c] = 'B'
    return repr(answer)


