# Akari / Light Up solver using human-like deduction plus tightly-pruned search.
# Output is a Python-literal N x N grid containing 'B' for bulbs and None elsewhere.

from copy import deepcopy

WHITE = 0
BLACK = 1

UNKNOWN = 0
BULB = 1
NOBULB = 2

DIRS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def solve(observation):
    data = observation["data"]
    board = AkariBoard(data)
    state = AkariState(board)

    if not propagate(board, state):
        return "No Solution"

    solved = search(board, state)
    if solved is None:
        return "No Solution"

    ans = [[None for _ in range(board.n)] for _ in range(board.n)]
    for r, c in board.whites:
        if solved.cell_state[(r, c)] == BULB:
            ans[r][c] = 'B'
    return repr(ans)


class AkariBoard:
    def __init__(self, data):
        self.data = data
        self.n = len(data)
        self.kind = {}
        self.number = {}
        self.whites = []
        self.black_cells = []
        self.numbered = []

        for r in range(self.n):
            for c in range(self.n):
                v = data[r][c]
                if v is None:
                    self.kind[(r, c)] = WHITE
                    self.whites.append((r, c))
                else:
                    self.kind[(r, c)] = BLACK
                    self.black_cells.append((r, c))
                    if v != -1:
                        self.number[(r, c)] = v
                        self.numbered.append((r, c))

        # Visibility segments and peers
        self.visible = {}
        self.peers = {}
        self.row_segments = []
        self.col_segments = []
        self.segments = []
        self.cell_to_segments = {cell: [] for cell in self.whites}

        self._build_segments_and_visibility()

        # Numbered black cell adjacency
        self.adj_white = {}
        self.adj_numbers_of_white = {cell: [] for cell in self.whites}
        for b in self.numbered:
            cells = []
            r, c = b
            for dr, dc in DIRS:
                nr, nc = r + dr, c + dc
                if 0 <= nr < self.n and 0 <= nc < self.n and self.kind[(nr, nc)] == WHITE:
                    cells.append((nr, nc))
                    self.adj_numbers_of_white[(nr, nc)].append(b)
            self.adj_white[b] = cells

    def _build_segments_and_visibility(self):
        # Row segments
        for r in range(self.n):
            cur = []
            for c in range(self.n):
                if self.kind[(r, c)] == WHITE:
                    cur.append((r, c))
                else:
                    if cur:
                        idx = len(self.segments)
                        self.row_segments.append(cur[:])
                        self.segments.append(cur[:])
                        for cell in cur:
                            self.cell_to_segments[cell].append(idx)
                        cur = []
            if cur:
                idx = len(self.segments)
                self.row_segments.append(cur[:])
                self.segments.append(cur[:])
                for cell in cur:
                    self.cell_to_segments[cell].append(idx)

        # Column segments
        for c in range(self.n):
            cur = []
            for r in range(self.n):
                if self.kind[(r, c)] == WHITE:
                    cur.append((r, c))
                else:
                    if cur:
                        idx = len(self.segments)
                        self.col_segments.append(cur[:])
                        self.segments.append(cur[:])
                        for cell in cur:
                            self.cell_to_segments[cell].append(idx)
                        cur = []
            if cur:
                idx = len(self.segments)
                self.col_segments.append(cur[:])
                self.segments.append(cur[:])
                for cell in cur:
                    self.cell_to_segments[cell].append(idx)

        # Visible cells = union of both segments minus self
        for cell in self.whites:
            vis = set()
            for seg_idx in self.cell_to_segments[cell]:
                for other in self.segments[seg_idx]:
                    if other != cell:
                        vis.add(other)
            self.visible[cell] = tuple(vis)
            self.peers[cell] = self.visible[cell]


class AkariState:
    def __init__(self, board):
        self.cell_state = {cell: UNKNOWN for cell in board.whites}
        self.lit_count = {cell: 0 for cell in board.whites}
        self.seg_bulb_count = [0] * len(board.segments)

    def clone(self):
        s = AkariState.__new__(AkariState)
        s.cell_state = self.cell_state.copy()
        s.lit_count = self.lit_count.copy()
        s.seg_bulb_count = self.seg_bulb_count[:]
        return s


def place_nobulb(board, state, cell):
    st = state.cell_state[cell]
    if st == NOBULB:
        return True
    if st == BULB:
        return False
    state.cell_state[cell] = NOBULB
    return True


def place_bulb(board, state, cell):
    st = state.cell_state[cell]
    if st == BULB:
        return True
    if st == NOBULB:
        return False

    # No bulb may see another bulb
    for seg_idx in board.cell_to_segments[cell]:
        if state.seg_bulb_count[seg_idx] >= 1:
            return False

    state.cell_state[cell] = BULB
    state.lit_count[cell] += 1
    for peer in board.visible[cell]:
        state.lit_count[peer] += 1
    for seg_idx in board.cell_to_segments[cell]:
        state.seg_bulb_count[seg_idx] += 1
    return True


def numbered_status(board, state, bcell):
    need = board.number[bcell]
    adj = board.adj_white[bcell]
    bulbs = 0
    unknown = []
    for cell in adj:
        st = state.cell_state[cell]
        if st == BULB:
            bulbs += 1
        elif st == UNKNOWN:
            unknown.append(cell)
    return need, bulbs, unknown


def check_consistency(board, state):
    # Numbered black cells feasibility
    for b in board.numbered:
        need, bulbs, unknown = numbered_status(board, state, b)
        if bulbs > need:
            return False
        if bulbs + len(unknown) < need:
            return False

    # Segment capacity: at most one bulb per segment; ensure unlit cells can still be lit somehow.
    for seg in board.segments:
        bulb_count = 0
        unknowns = 0
        has_lit = False
        for cell in seg:
            st = state.cell_state[cell]
            if st == BULB:
                bulb_count += 1
                has_lit = True
            elif state.lit_count[cell] > 0:
                has_lit = True
            if st == UNKNOWN:
                unknowns += 1
        if bulb_count > 1:
            return False
        if not has_lit and unknowns == 0:
            return False

    # Each white cell either lit already or still has at least one possible bulb source in row/col sightline.
    for cell in board.whites:
        if state.lit_count[cell] > 0:
            continue
        possible = state.cell_state[cell] != NOBULB
        if not possible:
            for peer in board.visible[cell]:
                if state.cell_state[peer] == UNKNOWN:
                    possible = True
                    break
        if not possible:
            return False

    return True


def propagate(board, state):
    changed = True
    while changed:
        changed = False

        # Rule 1: numbered black exact-fill / exact-block logic
        for b in board.numbered:
            need, bulbs, unknown = numbered_status(board, state, b)
            if bulbs > need or bulbs + len(unknown) < need:
                return False
            if not unknown:
                continue
            if bulbs == need:
                for cell in unknown:
                    if not place_nobulb(board, state, cell):
                        return False
                    changed = True
            elif bulbs + len(unknown) == need:
                for cell in unknown:
                    if not place_bulb(board, state, cell):
                        return False
                    changed = True

        # Rule 2: bulbs force all visible cells to be non-bulbs
        for cell in board.whites:
            if state.cell_state[cell] == BULB:
                for peer in board.visible[cell]:
                    if state.cell_state[peer] == UNKNOWN:
                        if not place_nobulb(board, state, peer):
                            return False
                        changed = True

        # Rule 3: if an unlit cell has only one possible illuminating source, force it.
        for target in board.whites:
            if state.lit_count[target] > 0:
                continue
            candidates = []
            if state.cell_state[target] != NOBULB:
                candidates.append(target)
            for peer in board.visible[target]:
                if state.cell_state[peer] == UNKNOWN:
                    candidates.append(peer)
            if not candidates:
                return False
            if len(candidates) == 1:
                if not place_bulb(board, state, candidates[0]):
                    return False
                changed = True

        # Rule 4: segment singleton necessity:
        # if a whole row/col segment is unlit and only one cell in it can still host a bulb, that cell is forced.
        for seg_idx, seg in enumerate(board.segments):
            if state.seg_bulb_count[seg_idx] > 1:
                return False
            has_lit = False
            candidates = []
            for cell in seg:
                if state.lit_count[cell] > 0:
                    has_lit = True
                if state.cell_state[cell] == UNKNOWN:
                    candidates.append(cell)
                elif state.cell_state[cell] == BULB:
                    has_lit = True
            if not has_lit:
                if not candidates:
                    return False
                if len(candidates) == 1:
                    if not place_bulb(board, state, candidates[0]):
                        return False
                    changed = True

        # Rule 5: adjacency impossibility around numbered cells.
        # If an unknown adjacent cell cannot be a bulb without violating the clue, mark NOBULB.
        for b in board.numbered:
            need, bulbs, unknown = numbered_status(board, state, b)
            for cell in unknown:
                # Immediate visibility impossibility
                possible = True
                for seg_idx in board.cell_to_segments[cell]:
                    if state.seg_bulb_count[seg_idx] >= 1:
                        possible = False
                        break
                # Clue impossibility
                if possible and bulbs + 1 > need:
                    possible = False
                if not possible:
                    if not place_nobulb(board, state, cell):
                        return False
                    changed = True

        if not check_consistency(board, state):
            return False

    return True


def score_branch_cell(board, state, cell):
    # Prefer cells with many effects and strong clue involvement.
    unlit_impact = 0
    if state.lit_count[cell] == 0:
        unlit_impact += 2
    for peer in board.visible[cell]:
        if state.lit_count[peer] == 0:
            unlit_impact += 1
    clue_pressure = 0
    for b in board.adj_numbers_of_white[cell]:
        need, bulbs, unknown = numbered_status(board, state, b)
        rem = need - bulbs
        clue_pressure += 5 - abs(len(unknown) - rem)
    return unlit_impact + clue_pressure


def choose_branch(board, state):
    # First try unresolved numbered constraints with smallest slack.
    best = None
    best_key = None

    for b in board.numbered:
        need, bulbs, unknown = numbered_status(board, state, b)
        if unknown:
            rem = need - bulbs
            key = (len(unknown), abs(len(unknown) - rem))
            if best_key is None or key < best_key:
                best_key = key
                best = ("number", b, unknown)

    if best is not None:
        # Branch on the strongest candidate among these unknowns.
        _, b, unknown = best
        cell = max(unknown, key=lambda x: score_branch_cell(board, state, x))
        return cell

    # Otherwise branch on a high-impact unknown cell that could light many unlit cells.
    candidates = [cell for cell in board.whites if state.cell_state[cell] == UNKNOWN]
    if not candidates:
        return None
    return max(candidates, key=lambda x: score_branch_cell(board, state, x))


def is_solved(board, state):
    for cell in board.whites:
        if state.lit_count[cell] <= 0:
            return False
        if state.cell_state[cell] == UNKNOWN:
            return False
    for b in board.numbered:
        need, bulbs, unknown = numbered_status(board, state, b)
        if bulbs != need or unknown:
            return False
    return check_consistency(board, state)


def search(board, state):
    if not check_consistency(board, state):
        return None
    if is_solved(board, state):
        return state

    cell = choose_branch(board, state)
    if cell is None:
        # Finalize remaining unknowns as NOBULB if possible
        final_state = state.clone()
        for c in board.whites:
            if final_state.cell_state[c] == UNKNOWN:
                if not place_nobulb(board, final_state, c):
                    return None
        if is_solved(board, final_state):
            return final_state
        return None

    # Try bulb first when plausible, then no-bulb.
    for choice in (BULB, NOBULB):
        nxt = state.clone()
        ok = place_bulb(board, nxt, cell) if choice == BULB else place_nobulb(board, nxt, cell)
        if not ok:
            continue
        if not propagate(board, nxt):
            continue
        res = search(board, nxt)
        if res is not None:
            return res

    return None


if __name__ == "__main__":
    print(solve(OBSERVATION))

