# Generalized solver for Latin-consecutive-dot puzzles.
# Rules:
# - Fill an N x N Latin square with values 1..N.
# - Dotted orthogonal neighbors must be consecutive.
# - Non-dotted orthogonal neighbors must not be consecutive.

FULL_MASK_CACHE = {}

def bit(v):
    return 1 << (v - 1)

def mask_to_values(mask, n):
    vals = []
    v = 1
    while mask:
        if mask & 1:
            vals.append(v)
        mask >>= 1
        v += 1
    return vals

def popcount(x):
    return x.bit_count()

def singleton_value(mask):
    return mask.bit_length()

def full_mask(n):
    if n not in FULL_MASK_CACHE:
        FULL_MASK_CACHE[n] = (1 << n) - 1
    return FULL_MASK_CACHE[n]

def build_neighbors(n, adjacent):
    dotted = set()
    for r, c in adjacent:
        if float(r).is_integer():
            rr = int(r)
            cc = int(c - 0.5)
            a = (rr, cc)
            b = (rr, cc + 1)
        else:
            rr = int(r - 0.5)
            cc = int(c)
            a = (rr, cc)
            b = (rr + 1, cc)
        if 0 <= a[0] < n and 0 <= a[1] < n and 0 <= b[0] < n and 0 <= b[1] < n:
            dotted.add((a, b))
            dotted.add((b, a))

    adj_type = {}
    neighbors = { (r, c): [] for r in range(n) for c in range(n) }
    for r in range(n):
        for c in range(n):
            for dr, dc in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n:
                    t = 1 if ((r, c), (nr, nc)) in dotted else 0
                    neighbors[(r, c)].append((nr, nc))
                    adj_type[((r, c), (nr, nc))] = t
    return neighbors, adj_type

def support_mask(mask_other, n, dotted):
    # Values in current domain that have support in neighbor domain.
    res = 0
    m = mask_other
    while m:
        lsb = m & -m
        v = lsb.bit_length()
        if dotted:
            if v > 1:
                res |= bit(v - 1)
            if v < n:
                res |= bit(v + 1)
        else:
            res |= full_mask(n) & ~((bit(v - 1) if v > 1 else 0) | (bit(v + 1) if v < n else 0))
        m ^= lsb
    return res

def enforce_latin_elimination(domains, n):
    changed = True
    while changed:
        changed = False

        # Fixed values eliminate from peers.
        for r in range(n):
            fixed_vals = 0
            for c in range(n):
                m = domains[r][c]
                if m == 0:
                    return False
                if popcount(m) == 1:
                    if fixed_vals & m:
                        return False
                    fixed_vals |= m
            for c in range(n):
                m = domains[r][c]
                if popcount(m) > 1:
                    nm = m & ~fixed_vals
                    if nm == 0:
                        return False
                    if nm != m:
                        domains[r][c] = nm
                        changed = True

        for c in range(n):
            fixed_vals = 0
            for r in range(n):
                m = domains[r][c]
                if m == 0:
                    return False
                if popcount(m) == 1:
                    if fixed_vals & m:
                        return False
                    fixed_vals |= m
            for r in range(n):
                m = domains[r][c]
                if popcount(m) > 1:
                    nm = m & ~fixed_vals
                    if nm == 0:
                        return False
                    if nm != m:
                        domains[r][c] = nm
                        changed = True

        # Hidden singles in rows.
        for r in range(n):
            for v in range(1, n + 1):
                mv = bit(v)
                places = []
                for c in range(n):
                    if domains[r][c] & mv:
                        places.append(c)
                if not places:
                    return False
                if len(places) == 1:
                    c = places[0]
                    if domains[r][c] != mv:
                        domains[r][c] = mv
                        changed = True

        # Hidden singles in columns.
        for c in range(n):
            for v in range(1, n + 1):
                mv = bit(v)
                places = []
                for r in range(n):
                    if domains[r][c] & mv:
                        places.append(r)
                if not places:
                    return False
                if len(places) == 1:
                    r = places[0]
                    if domains[r][c] != mv:
                        domains[r][c] = mv
                        changed = True

        # Small naked subsets (pairs/triples) in rows and columns.
        for is_row in (True, False):
            for idx in range(n):
                cells = []
                for j in range(n):
                    r, c = (idx, j) if is_row else (j, idx)
                    m = domains[r][c]
                    pc = popcount(m)
                    if 2 <= pc <= min(4, n):
                        cells.append((j, m))
                groups = {}
                for j, m in cells:
                    groups.setdefault(m, []).append(j)
                for m, positions in groups.items():
                    k = popcount(m)
                    if len(positions) == k:
                        for j in range(n):
                            if j not in positions:
                                r, c = (idx, j) if is_row else (j, idx)
                                old = domains[r][c]
                                nm = old & ~m
                                if nm == 0:
                                    return False
                                if nm != old:
                                    domains[r][c] = nm
                                    changed = True

    return True

def enforce_adjacency_ac3(domains, n, neighbors, adj_type):
    changed = True
    while changed:
        changed = False
        for r in range(n):
            for c in range(n):
                m = domains[r][c]
                if m == 0:
                    return False
                newm = m
                for nr, nc in neighbors[(r, c)]:
                    allowed = support_mask(domains[nr][nc], n, adj_type[((r, c), (nr, nc))] == 1)
                    newm &= allowed
                    if newm == 0:
                        return False
                if newm != m:
                    domains[r][c] = newm
                    changed = True
    return True

def propagate(domains, n, neighbors, adj_type):
    while True:
        snapshot = [row[:] for row in domains]
        if not enforce_latin_elimination(domains, n):
            return False
        if not enforce_adjacency_ac3(domains, n, neighbors, adj_type):
            return False
        if domains == snapshot:
            break
    return True

def is_solved(domains, n):
    for r in range(n):
        for c in range(n):
            if popcount(domains[r][c]) != 1:
                return False
    return True

def choose_branch_cell(domains, n, neighbors, adj_type):
    best = None
    best_key = None
    for r in range(n):
        for c in range(n):
            m = domains[r][c]
            pc = popcount(m)
            if pc <= 1:
                continue
            # Strong heuristic:
            # 1) minimum remaining values
            # 2) more constrained by row/col unresolved peers
            # 3) more adjacency degree
            unresolved_row = sum(popcount(domains[r][j]) > 1 for j in range(n) if j != c)
            unresolved_col = sum(popcount(domains[i][c]) > 1 for i in range(n) if i != r)
            dot_deg = sum(adj_type[((r, c), nb)] for nb in neighbors[(r, c)])
            key = (pc, -(unresolved_row + unresolved_col), -dot_deg)
            if best_key is None or key < best_key:
                best_key = key
                best = (r, c)
    return best

def ordered_values_for_cell(domains, r, c, n, neighbors, adj_type):
    vals = mask_to_values(domains[r][c], n)
    scores = []
    for v in vals:
        mv = bit(v)
        score = 0
        # Prefer values that keep more options in neighbors/peers.
        for nr, nc in neighbors[(r, c)]:
            t = adj_type[((r, c), (nr, nc))] == 1
            supported = support_mask(mv, n, t) & domains[nr][nc]
            score += popcount(supported)
        for j in range(n):
            if j != c and domains[r][j] & mv:
                score += 1
        for i in range(n):
            if i != r and domains[i][c] & mv:
                score += 1
        scores.append((-score, v))
    scores.sort()
    return [v for _, v in scores]

def clone_domains(domains):
    return [row[:] for row in domains]

def search(domains, n, neighbors, adj_type):
    if not propagate(domains, n, neighbors, adj_type):
        return None
    if is_solved(domains, n):
        return domains

    r, c = choose_branch_cell(domains, n, neighbors, adj_type)
    for v in ordered_values_for_cell(domains, r, c, n, neighbors, adj_type):
        nd = clone_domains(domains)
        nd[r][c] = bit(v)
        res = search(nd, n, neighbors, adj_type)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation["data"]
    adjacent = observation["adjacent"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    neighbors, adj_type = build_neighbors(n, adjacent)
    fm = full_mask(n)
    domains = [[fm for _ in range(n)] for _ in range(n)]

    # Apply givens.
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                domains[r][c] = bit(v)

    res = search(domains, n, neighbors, adj_type)
    if res is None:
        return "No Solution"

    answer = [[singleton_value(res[r][c]) for c in range(n)] for r in range(n)]
    return str(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

