from itertools import product

# Takuzu / Binairo solver using:
# - precomputed valid line patterns
# - row/column candidate propagation
# - human-style deductions via line intersections
# - uniqueness pruning
# - shallow, strongly pruned backtracking only when necessary

def solve(observation):
    grid = [row[:] for row in observation['data']]
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid) or n % 2 != 0:
        return "No Solution"

    all_patterns = generate_valid_patterns(n)

    # Row/column candidate domains
    row_cands = [filter_patterns_for_line(all_patterns, grid[r]) for r in range(n)]
    col_cands = [filter_patterns_for_line(all_patterns, [grid[r][c] for r in range(n)]) for c in range(n)]

    state = {
        'grid': grid,
        'row_cands': row_cands,
        'col_cands': col_cands,
    }

    state = propagate(state)
    if state is None:
        return "No Solution"

    state = search(state)
    if state is None:
        return "No Solution"

    return state['grid']


def generate_valid_patterns(n):
    half = n // 2
    res = []

    def rec(pos, pat, b_count, w_count):
        if b_count > half or w_count > half:
            return
        if pos >= 3 and pat[pos - 1] == pat[pos - 2] == pat[pos - 3]:
            return
        if pos == n:
            if b_count == half and w_count == half:
                res.append(tuple(pat))
            return
        pat.append('B')
        rec(pos + 1, pat, b_count + 1, w_count)
        pat.pop()

        pat.append('W')
        rec(pos + 1, pat, b_count, w_count + 1)
        pat.pop()

    rec(0, [], 0, 0)
    return res


def filter_patterns_for_line(patterns, line):
    out = []
    for p in patterns:
        ok = True
        for i, v in enumerate(line):
            if v is not None and p[i] != v:
                ok = False
                break
        if ok:
            out.append(p)
    return out


def copy_state(state):
    return {
        'grid': [row[:] for row in state['grid']],
        'row_cands': [cand[:] for cand in state['row_cands']],
        'col_cands': [cand[:] for cand in state['col_cands']],
    }


def line_from_row_candidates(cands, n):
    vals = [None] * n
    if not cands:
        return None
    for i in range(n):
        first = cands[0][i]
        if all(p[i] == first for p in cands):
            vals[i] = first
    return vals


def propagate(state):
    n = len(state['grid'])

    changed = True
    while changed:
        changed = False

        # Basic contradiction checks
        for r in range(n):
            if not state['row_cands'][r]:
                return None
        for c in range(n):
            if not state['col_cands'][c]:
                return None

        # Remove candidates inconsistent with current grid
        for r in range(n):
            line = state['grid'][r]
            new_cands = filter_patterns_for_line(state['row_cands'][r], line)
            if not new_cands:
                return None
            if len(new_cands) != len(state['row_cands'][r]):
                state['row_cands'][r] = new_cands
                changed = True

        for c in range(n):
            line = [state['grid'][r][c] for r in range(n)]
            new_cands = filter_patterns_for_line(state['col_cands'][c], line)
            if not new_cands:
                return None
            if len(new_cands) != len(state['col_cands'][c]):
                state['col_cands'][c] = new_cands
                changed = True

        # Intersect row candidates into grid
        for r in range(n):
            forced = line_from_row_candidates(state['row_cands'][r], n)
            if forced is None:
                return None
            for c, v in enumerate(forced):
                if v is not None:
                    cur = state['grid'][r][c]
                    if cur is None:
                        state['grid'][r][c] = v
                        changed = True
                    elif cur != v:
                        return None

        # Intersect column candidates into grid
        for c in range(n):
            forced = line_from_row_candidates(state['col_cands'][c], n)
            if forced is None:
                return None
            for r, v in enumerate(forced):
                if v is not None:
                    cur = state['grid'][r][c]
                    if cur is None:
                        state['grid'][r][c] = v
                        changed = True
                    elif cur != v:
                        return None

        # Human-style local deductions from triples and counts
        if apply_local_rules(state['grid']):
            changed = True

        # Refilter after local updates
        for r in range(n):
            new_cands = filter_patterns_for_line(state['row_cands'][r], state['grid'][r])
            if not new_cands:
                return None
            if len(new_cands) != len(state['row_cands'][r]):
                state['row_cands'][r] = new_cands
                changed = True

        for c in range(n):
            col = [state['grid'][r][c] for r in range(n)]
            new_cands = filter_patterns_for_line(state['col_cands'][c], col)
            if not new_cands:
                return None
            if len(new_cands) != len(state['col_cands'][c]):
                state['col_cands'][c] = new_cands
                changed = True

        # Uniqueness pruning against completed lines
        completed_rows = {}
        for r in range(n):
            if len(state['row_cands'][r]) == 1:
                pat = state['row_cands'][r][0]
                if pat in completed_rows:
                    return None
                completed_rows[pat] = r

        completed_cols = {}
        for c in range(n):
            if len(state['col_cands'][c]) == 1:
                pat = state['col_cands'][c][0]
                if pat in completed_cols:
                    return None
                completed_cols[pat] = c

        for r in range(n):
            if len(state['row_cands'][r]) > 1:
                new_cands = [p for p in state['row_cands'][r] if p not in completed_rows]
                if not new_cands:
                    return None
                if len(new_cands) != len(state['row_cands'][r]):
                    state['row_cands'][r] = new_cands
                    changed = True

        for c in range(n):
            if len(state['col_cands'][c]) > 1:
                new_cands = [p for p in state['col_cands'][c] if p not in completed_cols]
                if not new_cands:
                    return None
                if len(new_cands) != len(state['col_cands'][c]):
                    state['col_cands'][c] = new_cands
                    changed = True

        # Final consistency checks on current partial grid
        if not partial_grid_consistent(state['grid']):
            return None

    # Finished propagation
    if not partial_grid_consistent(state['grid']):
        return None
    return state


def apply_local_rules(grid):
    n = len(grid)
    changed = False

    def opposite(v):
        return 'W' if v == 'B' else 'B'

    def set_cell(r, c, v):
        nonlocal changed
        cur = grid[r][c]
        if cur is None:
            grid[r][c] = v
            changed = True
        elif cur != v:
            raise ValueError

    try:
        # Row rules
        for r in range(n):
            line = grid[r]

            # No three consecutive
            for i in range(n - 2):
                a, b, c = line[i], line[i + 1], line[i + 2]
                if a is not None and a == b and c is None:
                    set_cell(r, i + 2, opposite(a))
                if b is not None and b == c and a is None:
                    set_cell(r, i, opposite(b))
                if a is not None and c is not None and a == c and b is None:
                    set_cell(r, i + 1, opposite(a))

            # Balance
            bcnt = sum(v == 'B' for v in line)
            wcnt = sum(v == 'W' for v in line)
            unk = [i for i, v in enumerate(line) if v is None]
            half = n // 2
            if bcnt > half or wcnt > half:
                raise ValueError
            if bcnt == half:
                for i in unk:
                    set_cell(r, i, 'W')
            if wcnt == half:
                for i in unk:
                    set_cell(r, i, 'B')

        # Column rules
        for c in range(n):
            line = [grid[r][c] for r in range(n)]

            for i in range(n - 2):
                a, b, d = line[i], line[i + 1], line[i + 2]
                if a is not None and a == b and d is None:
                    set_cell(i + 2, c, opposite(a))
                if b is not None and b == d and a is None:
                    set_cell(i, c, opposite(b))
                if a is not None and d is not None and a == d and b is None:
                    set_cell(i + 1, c, opposite(a))

            bcnt = sum(v == 'B' for v in line)
            wcnt = sum(v == 'W' for v in line)
            unk = [i for i, v in enumerate(line) if v is None]
            half = n // 2
            if bcnt > half or wcnt > half:
                raise ValueError
            if bcnt == half:
                for i in unk:
                    set_cell(i, c, 'W')
            if wcnt == half:
                for i in unk:
                    set_cell(i, c, 'B')
    except ValueError:
        # Contradiction will be caught by consistency check after propagation
        return True

    return changed


def partial_grid_consistent(grid):
    n = len(grid)
    half = n // 2

    # Rows
    seen_full_rows = set()
    for r in range(n):
        line = grid[r]
        bcnt = sum(v == 'B' for v in line)
        wcnt = sum(v == 'W' for v in line)
        if bcnt > half or wcnt > half:
            return False
        for i in range(n - 2):
            a, b, c = line[i], line[i + 1], line[i + 2]
            if a is not None and a == b == c:
                return False
        if None not in line:
            t = tuple(line)
            if t in seen_full_rows:
                return False
            seen_full_rows.add(t)

    # Columns
    seen_full_cols = set()
    for c in range(n):
        line = [grid[r][c] for r in range(n)]
        bcnt = sum(v == 'B' for v in line)
        wcnt = sum(v == 'W' for v in line)
        if bcnt > half or wcnt > half:
            return False
        for i in range(n - 2):
            a, b, d = line[i], line[i + 1], line[i + 2]
            if a is not None and a == b == d:
                return False
        if None not in line:
            t = tuple(line)
            if t in seen_full_cols:
                return False
            seen_full_cols.add(t)

    return True


def is_solved(state):
    return all(all(v is not None for v in row) for row in state['grid'])


def search(state):
    if state is None:
        return None
    if is_solved(state):
        return state

    n = len(state['grid'])
    best_kind = None
    best_idx = None
    best_size = 10**9

    # Choose the most constrained row/column domain > 1
    for r in range(n):
        k = len(state['row_cands'][r])
        if 1 < k < best_size:
            best_size = k
            best_kind = 'row'
            best_idx = r
    for c in range(n):
        k = len(state['col_cands'][c])
        if 1 < k < best_size:
            best_size = k
            best_kind = 'col'
            best_idx = c

    if best_kind is None:
        return None

    if best_kind == 'row':
        idx = best_idx
        # Prefer candidates that match current forced cells most tightly
        candidates = state['row_cands'][idx]
        for pat in candidates:
            new_state = copy_state(state)
            new_state['row_cands'][idx] = [pat]
            for c, v in enumerate(pat):
                cur = new_state['grid'][idx][c]
                if cur is not None and cur != v:
                    new_state = None
                    break
                new_state['grid'][idx][c] = v
            if new_state is None:
                continue
            new_state = propagate(new_state)
            if new_state is not None:
                result = search(new_state)
                if result is not None:
                    return result
    else:
        idx = best_idx
        candidates = state['col_cands'][idx]
        for pat in candidates:
            new_state = copy_state(state)
            new_state['col_cands'][idx] = [pat]
            for r, v in enumerate(pat):
                cur = new_state['grid'][r][idx]
                if cur is not None and cur != v:
                    new_state = None
                    break
                new_state['grid'][r][idx] = v
            if new_state is None:
                continue
            new_state = propagate(new_state)
            if new_state is not None:
                result = search(new_state)
                if result is not None:
                    return result

    return None


