from collections import defaultdict, deque

# General Hashi solver with:
# - graph extraction from grid
# - edge domains {0,1,2}
# - aggressive propagation from island degree constraints
# - bridge crossing elimination
# - connectivity pruning
# - informed backtracking


def solve(observation):
    data = observation["data"]
    puzzle = HashiPuzzle(data)
    result = puzzle.solve()
    if result is None:
        return "No Solution"
    return str(result)


class HashiPuzzle:
    def __init__(self, grid):
        self.grid = grid
        self.n = len(grid)
        self.islands = []
        self.req = []
        self.pos_to_idx = {}

        for r in range(self.n):
            for c in range(len(grid[r])):
                v = grid[r][c]
                if isinstance(v, int):
                    idx = len(self.islands)
                    self.islands.append((r, c))
                    self.req.append(v)
                    self.pos_to_idx[(r, c)] = idx

        self.edges = []
        self.edge_index = {}
        self.incident = [[] for _ in self.islands]
        self.crosses = []
        self._build_edges()
        self._build_crossings()

    def _build_edges(self):
        # Horizontal visibility
        for r in range(self.n):
            last = None
            for c in range(len(self.grid[r])):
                if isinstance(self.grid[r][c], int):
                    if last is not None:
                        a = self.pos_to_idx[(r, last)]
                        b = self.pos_to_idx[(r, c)]
                        self._add_edge(a, b)
                    last = c

        # Vertical visibility
        width = max(len(row) for row in self.grid)
        for c in range(width):
            last = None
            for r in range(self.n):
                if c < len(self.grid[r]) and isinstance(self.grid[r][c], int):
                    if last is not None:
                        a = self.pos_to_idx[(last, c)]
                        b = self.pos_to_idx[(r, c)]
                        self._add_edge(a, b)
                    last = r

    def _add_edge(self, a, b):
        if a > b:
            a, b = b, a
        if (a, b) in self.edge_index:
            return
        ia = self.islands[a]
        ib = self.islands[b]
        orient = "H" if ia[0] == ib[0] else "V"
        idx = len(self.edges)
        self.edge_index[(a, b)] = idx
        self.edges.append((a, b, orient))
        self.incident[a].append(idx)
        self.incident[b].append(idx)

    def _build_crossings(self):
        m = len(self.edges)
        self.crosses = [[] for _ in range(m)]
        for i in range(m):
            a1, b1, o1 = self.edges[i]
            r1, c1 = self.islands[a1]
            r2, c2 = self.islands[b1]
            if o1 == "H":
                hr = r1
                hc1, hc2 = sorted((c1, c2))
            else:
                vc = c1
                vr1, vr2 = sorted((r1, r2))

            for j in range(i + 1, m):
                a2, b2, o2 = self.edges[j]
                if o1 == o2:
                    continue
                x1, y1 = self.islands[a2]
                x2, y2 = self.islands[b2]

                if o1 == "H" and o2 == "V":
                    hr = r1
                    hc1, hc2 = sorted((c1, c2))
                    vc = y1
                    vr1, vr2 = sorted((x1, x2))
                    if vr1 < hr < vr2 and hc1 < vc < hc2:
                        self.crosses[i].append(j)
                        self.crosses[j].append(i)
                elif o1 == "V" and o2 == "H":
                    vc = c1
                    vr1, vr2 = sorted((r1, r2))
                    hr = x1
                    hc1, hc2 = sorted((y1, y2))
                    if vr1 < hr < vr2 and hc1 < vc < hc2:
                        self.crosses[i].append(j)
                        self.crosses[j].append(i)

    def solve(self):
        m = len(self.edges)
        lo = [0] * m
        hi = [2] * m

        # Static upper bounds from endpoint requirements.
        for e, (a, b, _) in enumerate(self.edges):
            hi[e] = min(2, self.req[a], self.req[b])

        if not self._propagate(lo, hi):
            return None

        ans = self._search(lo, hi)
        if ans is None:
            return None

        out = {}
        for e, v in enumerate(ans):
            if v > 0:
                a, b, _ = self.edges[e]
                p = self.islands[a]
                q = self.islands[b]
                if p > q:
                    p, q = q, p
                out[(p, q)] = v
        return out

    def _search(self, lo, hi):
        if not self._propagate(lo, hi):
            return None

        if all(lo[i] == hi[i] for i in range(len(lo))):
            vals = lo
            if self._is_complete_valid(vals):
                return vals[:]
            return None

        e = self._choose_branch_edge(lo, hi)
        values = list(range(hi[e], lo[e] - 1, -1))

        for v in values:
            nlo = lo[:]
            nhi = hi[:]
            nlo[e] = nhi[e] = v
            res = self._search(nlo, nhi)
            if res is not None:
                return res
        return None

    def _choose_branch_edge(self, lo, hi):
        # Prefer edges participating in crossings and touching tight islands.
        best = None
        best_key = None
        for e in range(len(lo)):
            if lo[e] == hi[e]:
                continue
            a, b, _ = self.edges[e]
            span = hi[e] - lo[e]
            ra = self.req[a]
            rb = self.req[b]
            deg_a_tight = self._node_tightness(a, lo, hi)
            deg_b_tight = self._node_tightness(b, lo, hi)
            key = (
                span,
                -(deg_a_tight + deg_b_tight),
                -len(self.crosses[e]),
                -(ra + rb),
            )
            if best_key is None or key < best_key:
                best_key = key
                best = e
        return best

    def _node_tightness(self, i, lo, hi):
        lsum = 0
        hsum = 0
        for e in self.incident[i]:
            lsum += lo[e]
            hsum += hi[e]
        return min(self.req[i] - lsum, hsum - self.req[i])

    def _propagate(self, lo, hi):
        m = len(lo)
        changed = True
        while changed:
            changed = False

            # Crossing rule: if one edge is positive, crossing edges must be zero.
            for e in range(m):
                if lo[e] > 0:
                    for f in self.crosses[e]:
                        if hi[f] != 0:
                            hi[f] = 0
                            changed = True
                        if lo[f] > hi[f]:
                            return False
                if hi[e] == 0:
                    continue
                for f in self.crosses[e]:
                    if lo[f] > 0:
                        if hi[e] != 0:
                            hi[e] = 0
                            changed = True
                        if lo[e] > hi[e]:
                            return False

            # Degree rules for each island.
            for i in range(len(self.islands)):
                inc = self.incident[i]
                lsum = sum(lo[e] for e in inc)
                hsum = sum(hi[e] for e in inc)
                need = self.req[i]

                if lsum > need or hsum < need:
                    return False

                # Compute per-edge bounds from remaining requirement.
                for e in inc:
                    other_min = lsum - lo[e]
                    other_max = hsum - hi[e]
                    new_lo = max(lo[e], need - other_max)
                    new_hi = min(hi[e], need - other_min)
                    if new_lo > new_hi:
                        return False
                    if new_lo != lo[e]:
                        lo[e] = new_lo
                        changed = True
                    if new_hi != hi[e]:
                        hi[e] = new_hi
                        changed = True

                # Human-like complete saturation:
                # if need equals total mins/maxes, all incident edges fixed accordingly.
                lsum = sum(lo[e] for e in inc)
                hsum = sum(hi[e] for e in inc)
                if lsum == need:
                    for e in inc:
                        if hi[e] != lo[e]:
                            hi[e] = lo[e]
                            changed = True
                elif hsum == need:
                    for e in inc:
                        if lo[e] != hi[e]:
                            lo[e] = hi[e]
                            changed = True

            # If an island still needs >0 bridges and only one available edge remains, force it.
            for i in range(len(self.islands)):
                inc = self.incident[i]
                need = self.req[i]
                lsum = sum(lo[e] for e in inc)
                rem = need - lsum
                if rem < 0:
                    return False
                free = [e for e in inc if hi[e] > lo[e]]
                if rem == 0:
                    for e in free:
                        if hi[e] != lo[e]:
                            hi[e] = lo[e]
                            changed = True
                elif len(free) == 1:
                    e = free[0]
                    if lo[e] < hi[e]:
                        v = lo[e] + rem
                        if v < lo[e] or v > hi[e]:
                            return False
                        if lo[e] != v or hi[e] != v:
                            lo[e] = hi[e] = v
                            changed = True

            if not self._connectivity_possible(lo, hi):
                return False
            if not self._no_closed_subnetwork(lo, hi):
                return False

            for e in range(m):
                if lo[e] > hi[e]:
                    return False

        return True

    def _connectivity_possible(self, lo, hi):
        # Graph using edges that may still be positive must connect all islands.
        n = len(self.islands)
        adj = [[] for _ in range(n)]
        for e, (_, _, _) in enumerate(self.edges):
            if hi[e] > 0:
                a, b, _ = self.edges[e]
                adj[a].append(b)
                adj[b].append(a)

        seen = [False] * n
        q = deque([0])
        seen[0] = True
        while q:
            u = q.popleft()
            for v in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    q.append(v)
        if not all(seen):
            return False

        # Each current positive component must have a potential outgoing edge,
        # unless it already spans all islands.
        pos_adj = [[] for _ in range(n)]
        for e in range(len(self.edges)):
            if lo[e] > 0:
                a, b, _ = self.edges[e]
                pos_adj[a].append((b, e))
                pos_adj[b].append((a, e))

        seen = [False] * n
        for s in range(n):
            if seen[s]:
                continue
            comp = []
            dq = deque([s])
            seen[s] = True
            while dq:
                u = dq.popleft()
                comp.append(u)
                for v, _ in pos_adj[u]:
                    if not seen[v]:
                        seen[v] = True
                        dq.append(v)
            if len(comp) == n:
                continue
            comp_set = set(comp)
            can_exit = False
            for u in comp:
                for e in self.incident[u]:
                    a, b, _ = self.edges[e]
                    v = b if a == u else a
                    if v not in comp_set and hi[e] > 0:
                        can_exit = True
                        break
                if can_exit:
                    break
            # Only components containing at least one positive edge matter here.
            has_pos_edge = False
            for u in comp:
                for e in self.incident[u]:
                    if lo[e] > 0:
                        has_pos_edge = True
                        break
                if has_pos_edge:
                    break
            if has_pos_edge and not can_exit:
                return False

        return True

    def _no_closed_subnetwork(self, lo, hi):
        # If a component formed by fixed-positive edges is fully satisfied and isolated from all possible exits,
        # then it cannot be a proper subset.
        n = len(self.islands)
        pos_adj = [[] for _ in range(n)]
        for e in range(len(self.edges)):
            if lo[e] > 0:
                a, b, _ = self.edges[e]
                pos_adj[a].append(b)
                pos_adj[b].append(a)

        seen = [False] * n
        for s in range(n):
            if seen[s]:
                continue
            comp = []
            dq = deque([s])
            seen[s] = True
            while dq:
                u = dq.popleft()
                comp.append(u)
                for v in pos_adj[u]:
                    if not seen[v]:
                        seen[v] = True
                        dq.append(v)

            if len(comp) == n:
                continue

            # Consider only components that actually have some positive structure.
            if not any(lo[e] > 0 for u in comp for e in self.incident[u]):
                continue

            comp_set = set(comp)
            isolated = True
            fully_satisfied = True
            for u in comp:
                lsum = sum(lo[e] for e in self.incident[u])
                if lsum != self.req[u]:
                    fully_satisfied = False
                for e in self.incident[u]:
                    a, b, _ = self.edges[e]
                    v = b if a == u else a
                    if v not in comp_set and hi[e] > 0:
                        isolated = False
            if isolated and fully_satisfied:
                return False

        return True

    def _is_complete_valid(self, vals):
        # Degree exactness
        for i in range(len(self.islands)):
            if sum(vals[e] for e in self.incident[i]) != self.req[i]:
                return False

        # Crossing validity
        for e in range(len(vals)):
            if vals[e] > 0:
                for f in self.crosses[e]:
                    if vals[f] > 0:
                        return False

        # Connectivity
        n = len(self.islands)
        adj = [[] for _ in range(n)]
        for e, v in enumerate(vals):
            if v > 0:
                a, b, _ = self.edges[e]
                adj[a].append(b)
                adj[b].append(a)
        seen = [False] * n
        q = deque([0])
        seen[0] = True
        while q:
            u = q.popleft()
            for v in adj[u]:
                if not seen[v]:
                    seen[v] = True
                    q.append(v)
        return all(seen)


