OBSERVATION = {'data': [[None, None, None, None, None, 'W', None, None], ['B', None, 'B', None, None, None, None, 'B'], ['W', None, None, 'W', None, None, None, None], [None, 'B', None, None, None, None, None, None], [None, 'B', 'B', None, None, None, 'W', None], [None, None, None, None, None, 'B', None, 'B'], ['W', None, 'B', None, None, None, None, 'W'], [None, None, None, 'W', None, None, None, None]]}

from copy import deepcopy

B = 1
W = 0
SYM = {1: 'B', 0: 'W'}

def encode_cell(v):
    if v == 'B':
        return B
    if v == 'W':
        return W
    return None

def decode_grid(grid):
    return [[SYM[v] for v in row] for row in grid]

def valid_line_patterns(n):
    half = n // 2
    out = []

    def rec(pos, line, b_count, w_count):
        if b_count > half or w_count > half:
            return
        if pos >= 2 and line[pos - 1] == line[pos - 2]:
            # Force opposite if same twice already
            forced = 1 - line[pos - 1]
            if forced == B and b_count == half:
                return
            if forced == W and w_count == half:
                return
            line.append(forced)
            rec(pos + 1, line, b_count + (forced == B), w_count + (forced == W))
            line.pop()
            return
        rem = n - pos
        if b_count + rem < half or w_count + rem < half:
            return
        for v in (W, B):
            if v == B and b_count == half:
                continue
            if v == W and w_count == half:
                continue
            line.append(v)
            rec(pos + 1, line, b_count + (v == B), w_count + (v == W))
            line.pop()

    rec(0, [], 0, 0)
    return [tuple(x) for x in out] if out else _valid_line_patterns_fallback(n)

def _valid_line_patterns_fallback(n):
    # Safe fallback; should rarely be used if rec above is correct.
    half = n // 2
    res = []
    def rec(i, line, b, w):
        if b > half or w > half:
            return
        if i == n:
            if b == half and w == half:
                res.append(tuple(line))
            return
        for v in (W, B):
            if i >= 2 and line[-1] == line[-2] == v:
                continue
            line.append(v)
            rec(i + 1, line, b + (v == B), w + (v == W))
            line.pop()
    rec(0, [], 0, 0)
    return res

def build_pattern_cache(n):
    patterns = valid_line_patterns(n)
    by_pos_val = [[set() for _ in range(2)] for _ in range(n)]
    for p in patterns:
        for i, v in enumerate(p):
            by_pos_val[i][v].add(p)
    return patterns, by_pos_val

def initial_state(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data) or n % 2 != 0:
        return None
    grid = [[encode_cell(v) for v in row] for row in data]
    return grid

def filter_row_domain(row_domain, r, col_domains, grid):
    new_dom = set()
    for p in row_domain:
        ok = True
        for c, v in enumerate(p):
            g = grid[r][c]
            if g is not None and g != v:
                ok = False
                break
            if not any(cp[r] == v for cp in col_domains[c]):
                ok = False
                break
        if ok:
            new_dom.add(p)
    return new_dom

def filter_col_domain(col_domain, c, row_domains, grid):
    new_dom = set()
    for p in col_domain:
        ok = True
        for r, v in enumerate(p):
            g = grid[r][c]
            if g is not None and g != v:
                ok = False
                break
            if not any(rp[c] == v for rp in row_domains[r]):
                ok = False
                break
        if ok:
            new_dom.add(p)
    return new_dom

def propagate(grid, row_domains, col_domains):
    n = len(grid)
    changed = True
    while changed:
        changed = False

        # Filter domains against current opposite-axis possibilities.
        for r in range(n):
            nd = filter_row_domain(row_domains[r], r, col_domains, grid)
            if not nd:
                return None
            if len(nd) != len(row_domains[r]):
                row_domains[r] = nd
                changed = True

        for c in range(n):
            nd = filter_col_domain(col_domains[c], c, row_domains, grid)
            if not nd:
                return None
            if len(nd) != len(col_domains[c]):
                col_domains[c] = nd
                changed = True

        # Cell-level intersection propagation.
        for r in range(n):
            for c in range(n):
                rv = {p[c] for p in row_domains[r]}
                cv = {p[r] for p in col_domains[c]}
                vals = rv & cv
                if not vals:
                    return None
                if grid[r][c] is not None:
                    if grid[r][c] not in vals:
                        return None
                elif len(vals) == 1:
                    grid[r][c] = next(iter(vals))
                    changed = True

        # All-different propagation for completed lines.
        fixed_rows = {}
        for r in range(n):
            if len(row_domains[r]) == 1:
                p = next(iter(row_domains[r]))
                if p in fixed_rows:
                    return None
                fixed_rows[p] = r
        for p, owner in fixed_rows.items():
            for r in range(n):
                if r != owner and p in row_domains[r]:
                    if len(row_domains[r]) == 1:
                        return None
                    row_domains[r] = set(row_domains[r])
                    row_domains[r].discard(p)
                    if not row_domains[r]:
                        return None
                    changed = True

        fixed_cols = {}
        for c in range(n):
            if len(col_domains[c]) == 1:
                p = next(iter(col_domains[c]))
                if p in fixed_cols:
                    return None
                fixed_cols[p] = c
        for p, owner in fixed_cols.items():
            for c in range(n):
                if c != owner and p in col_domains[c]:
                    if len(col_domains[c]) == 1:
                        return None
                    col_domains[c] = set(col_domains[c])
                    col_domains[c].discard(p)
                    if not col_domains[c]:
                        return None
                    changed = True

    return grid, row_domains, col_domains

def is_solved(grid, row_domains, col_domains):
    n = len(grid)
    return all(all(v is not None for v in row) for row in grid) and all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)

def choose_branch(row_domains, col_domains):
    best_kind = None
    best_idx = None
    best_size = 10**9

    for r, d in enumerate(row_domains):
        s = len(d)
        if 1 < s < best_size:
            best_kind, best_idx, best_size = 'row', r, s
    for c, d in enumerate(col_domains):
        s = len(d)
        if 1 < s < best_size:
            best_kind, best_idx, best_size = 'col', c, s

    return best_kind, best_idx

def domain_value_score_for_row(pattern, r, col_domains):
    score = 0
    for c, v in enumerate(pattern):
        score += sum(1 for cp in col_domains[c] if cp[r] == v)
    return score

def domain_value_score_for_col(pattern, c, row_domains):
    score = 0
    for r, v in enumerate(pattern):
        score += sum(1 for rp in row_domains[r] if rp[c] == v)
    return score

def search(grid, row_domains, col_domains):
    state = propagate(grid, row_domains, col_domains)
    if state is None:
        return None
    grid, row_domains, col_domains = state

    if is_solved(grid, row_domains, col_domains):
        return grid

    kind, idx = choose_branch(row_domains, col_domains)
    if kind is None:
        return None

    if kind == 'row':
        candidates = sorted(row_domains[idx], key=lambda p: domain_value_score_for_row(p, idx, col_domains))
        for p in candidates:
            ng = [row[:] for row in grid]
            nr = [set(d) for d in row_domains]
            nc = [set(d) for d in col_domains]
            nr[idx] = {p}
            for c, v in enumerate(p):
                if ng[idx][c] is not None and ng[idx][c] != v:
                    break
                ng[idx][c] = v
            else:
                ans = search(ng, nr, nc)
                if ans is not None:
                    return ans
    else:
        candidates = sorted(col_domains[idx], key=lambda p: domain_value_score_for_col(p, idx, row_domains))
        for p in candidates:
            ng = [row[:] for row in grid]
            nr = [set(d) for d in row_domains]
            nc = [set(d) for d in col_domains]
            nc[idx] = {p}
            for r, v in enumerate(p):
                if ng[r][idx] is not None and ng[r][idx] != v:
                    break
                ng[r][idx] = v
            else:
                ans = search(ng, nr, nc)
                if ans is not None:
                    return ans

    return None

def solve(observation):
    grid = initial_state(observation)
    if grid is None:
        return "No Solution"

    n = len(grid)
    patterns, _ = build_pattern_cache(n)
    all_patterns = set(patterns)

    row_domains = []
    for r in range(n):
        dom = set()
        for p in all_patterns:
            ok = True
            for c, v in enumerate(p):
                g = grid[r][c]
                if g is not None and g != v:
                    ok = False
                    break
            if ok:
                dom.add(p)
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for c in range(n):
        dom = set()
        for p in all_patterns:
            ok = True
            for r, v in enumerate(p):
                g = grid[r][c]
                if g is not None and g != v:
                    ok = False
                    break
            if ok:
                dom.add(p)
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    ans = search([row[:] for row in grid], [set(d) for d in row_domains], [set(d) for d in col_domains])
    if ans is None:
        return "No Solution"
    return decode_grid(ans)

