from functools import lru_cache
from itertools import combinations


def solve_binary_matrix(row_sums, col_sums):
    # Fast exact 0/1 matrix construction from row/column sums.
    # Uses row-wise branching with strong feasibility pruning.
    R = len(row_sums)
    C = len(col_sums)

    if sum(row_sums) != sum(col_sums):
        return None
    if any(x < 0 or x > C for x in row_sums):
        return None
    if any(x < 0 or x > R for x in col_sums):
        return None

    order = sorted(range(R), key=lambda r: (-row_sums[r], r))
    sorted_row_sums = [row_sums[r] for r in order]

    comb_cache = {}
    for k in set(sorted_row_sums):
        comb_cache[k] = list(combinations(range(C), k))

    def feasible_suffix(remaining_rows, cols):
        # Simple but effective future feasibility:
        # 1) nonnegative and per-column upper bounds
        # 2) total sum match
        # 3) Hall-like prefix bound via conjugate capacity
        n = len(remaining_rows)
        if any(v < 0 or v > n for v in cols):
            return False
        if sum(remaining_rows) != sum(cols):
            return False
        rs = sorted(remaining_rows, reverse=True)
        cs = sorted(cols, reverse=True)
        # Gale-Ryser style necessary/sufficient check
        prefix = [0]
        for x in rs:
            prefix.append(prefix[-1] + x)
        for k in range(1, n + 1):
            rhs = sum(min(c, k) for c in cs)
            if prefix[k] > rhs:
                return False
        return True

    @lru_cache(maxsize=None)
    def dfs(i, cols):
        cols = list(cols)
        if i == R:
            if all(v == 0 for v in cols):
                return ()
            return None

        need = sorted_row_sums[i]
        rem_rows = sorted_row_sums[i + 1 :]

        positive_cols = [c for c in range(C) if cols[c] > 0]
        if len(positive_cols) < need:
            return None

        # Human-like ordering:
        # prefer columns with largest remaining demand first.
        positive_cols.sort(key=lambda c: (-cols[c], c))

        # Candidate combinations generated from only positive columns.
        # Strong local feasibility check applied to each candidate.
        for chosen in combinations(positive_cols, need):
            new_cols = cols[:]
            ok = True
            for c in chosen:
                new_cols[c] -= 1
                if new_cols[c] < 0:
                    ok = False
                    break
            if not ok:
                continue

            if not feasible_suffix(rem_rows, new_cols):
                continue

            tail = dfs(i + 1, tuple(new_cols))
            if tail is not None:
                return (chosen,) + tail
        return None

    plan = dfs(0, tuple(col_sums))
    if plan is None:
        return None

    grid = [[None for _ in range(C)] for _ in range(R)]
    for i, chosen in enumerate(plan):
        r = order[i]
        for c in chosen:
            grid[r][c] = 'W'
    return grid


def solve_region_puzzle(observation):
    region_grid = observation['region']
    row_target = observation['row_water_counts']
    col_target = observation['col_water_counts']

    R = len(region_grid)
    C = len(region_grid[0]) if R else 0

    if sum(row_target) != sum(col_target):
        return None

    # Build regions
    regions = {}
    for r in range(R):
        for c in range(C):
            rid = region_grid[r][c]
            regions.setdefault(rid, []).append((r, c))

    region_ids = sorted(regions)
    reg_index = {rid: i for i, rid in enumerate(region_ids)}
    nreg = len(region_ids)

    # For each region, legal water states are "empty" or "all cells at/below a level".
    options = []
    for rid in region_ids:
        cells = regions[rid]
        rows_present = sorted({r for r, _ in cells})
        row_groups = {}
        for r, c in cells:
            row_groups.setdefault(r, []).append(c)

        # Empty option
        reg_opts = []
        empty_rows = [0] * R
        empty_cols = [0] * C
        reg_opts.append((empty_rows, empty_cols, set()))

        # Water up to level: choose a topmost flooded row t, flood all cells with row >= t.
        for t in rows_present:
            rr = [0] * R
            cc = [0] * C
            flooded = set()
            for r, c in cells:
                if r >= t:
                    rr[r] += 1
                    cc[c] += 1
                    flooded.add((r, c))
            reg_opts.append((rr, cc, flooded))

        # Remove duplicates if region shape causes identical flooded sets
        uniq = []
        seen = set()
        for rr, cc, flooded in reg_opts:
            key = tuple(sorted(flooded))
            if key not in seen:
                seen.add(key)
                uniq.append((rr, cc, flooded))
        options.append(uniq)

    # Precompute contributions
    opt_row = []
    opt_col = []
    for reg_opts in options:
        opt_row.append([x[0] for x in reg_opts])
        opt_col.append([x[1] for x in reg_opts])

    # Domain as bitmask per region
    domains0 = tuple((1 << len(options[i])) - 1 for i in range(nreg))

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def bounds_for_domains(domains):
        row_min = [0] * R
        row_max = [0] * R
        col_min = [0] * C
        col_max = [0] * C
        for i in range(nreg):
            mask = domains[i]
            mins_r = [10**9] * R
            maxs_r = [-1] * R
            mins_c = [10**9] * C
            maxs_c = [-1] * C
            for oi in iter_bits(mask):
                rr = opt_row[i][oi]
                cc = opt_col[i][oi]
                for r in range(R):
                    v = rr[r]
                    if v < mins_r[r]:
                        mins_r[r] = v
                    if v > maxs_r[r]:
                        maxs_r[r] = v
                for c in range(C):
                    v = cc[c]
                    if v < mins_c[c]:
                        mins_c[c] = v
                    if v > maxs_c[c]:
                        maxs_c[c] = v
            for r in range(R):
                row_min[r] += mins_r[r]
                row_max[r] += maxs_r[r]
            for c in range(C):
                col_min[c] += mins_c[c]
                col_max[c] += maxs_c[c]
        return row_min, row_max, col_min, col_max

    def propagate(domains):
        domains = list(domains)
        changed = True
        while changed:
            changed = False

            row_min, row_max, col_min, col_max = bounds_for_domains(tuple(domains))

            for r in range(R):
                if row_target[r] < row_min[r] or row_target[r] > row_max[r]:
                    return None
            for c in range(C):
                if col_target[c] < col_min[c] or col_target[c] > col_max[c]:
                    return None

            # Prune options incompatible with row/column residual windows.
            for i in range(nreg):
                mask = domains[i]
                new_mask = 0
                for oi in iter_bits(mask):
                    rr = opt_row[i][oi]
                    cc = opt_col[i][oi]
                    ok = True
                    for r in range(R):
                        others_min = row_min[r] - min(opt_row[i][oj][r] for oj in iter_bits(mask))
                        others_max = row_max[r] - max(opt_row[i][oj][r] for oj in iter_bits(mask))
                        v = rr[r]
                        if not (others_min + v <= row_target[r] <= others_max + v):
                            ok = False
                            break
                    if ok:
                        for c in range(C):
                            others_min = col_min[c] - min(opt_col[i][oj][c] for oj in iter_bits(mask))
                            others_max = col_max[c] - max(opt_col[i][oj][c] for oj in iter_bits(mask))
                            v = cc[c]
                            if not (others_min + v <= col_target[c] <= others_max + v):
                                ok = False
                                break
                    if ok:
                        new_mask |= 1 << oi

                if new_mask == 0:
                    return None
                if new_mask != mask:
                    domains[i] = new_mask
                    changed = True

            # Forced exact row/column reasoning:
            row_min, row_max, col_min, col_max = bounds_for_domains(tuple(domains))
            for i in range(nreg):
                if domains[i] & (domains[i] - 1) == 0:
                    continue
                mask = domains[i]
                allowed = 0
                # Cache per-region current min/max contributions
                min_r = [min(opt_row[i][oi][r] for oi in iter_bits(mask)) for r in range(R)]
                max_r = [max(opt_row[i][oi][r] for oi in iter_bits(mask)) for r in range(R)]
                min_c = [min(opt_col[i][oi][c] for oi in iter_bits(mask)) for c in range(C)]
                max_c = [max(opt_col[i][oi][c] for oi in iter_bits(mask)) for c in range(C)]
                for oi in iter_bits(mask):
                    rr = opt_row[i][oi]
                    cc = opt_col[i][oi]
                    ok = True
                    for r in range(R):
                        new_global_min = row_min[r] - min_r[r] + rr[r]
                        new_global_max = row_max[r] - max_r[r] + rr[r]
                        if row_target[r] < new_global_min or row_target[r] > new_global_max:
                            ok = False
                            break
                    if ok:
                        for c in range(C):
                            new_global_min = col_min[c] - min_c[c] + cc[c]
                            new_global_max = col_max[c] - max_c[c] + cc[c]
                            if col_target[c] < new_global_min or col_target[c] > new_global_max:
                                ok = False
                                break
                    if ok:
                        allowed |= 1 << oi
                if allowed == 0:
                    return None
                if allowed != mask:
                    domains[i] = allowed
                    changed = True

        return tuple(domains)

    @lru_cache(maxsize=None)
    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None

        if all(mask & (mask - 1) == 0 for mask in domains):
            # Build final grid
            grid = [[None for _ in range(C)] for _ in range(R)]
            for i, mask in enumerate(domains):
                oi = (mask & -mask).bit_length() - 1
                for r, c in options[i][oi][2]:
                    grid[r][c] = 'W'
            # Final exact verification
            if [sum(1 for c in range(C) if grid[r][c] == 'W') for r in range(R)] != row_target:
                return None
            if [sum(1 for r in range(R) if grid[r][c] == 'W') for c in range(C)] != col_target:
                return None
            return grid

        # Choose most constrained region
        best_i = None
        best_count = 10**9
        for i, mask in enumerate(domains):
            cnt = mask.bit_count()
            if 1 < cnt < best_count:
                best_count = cnt
                best_i = i

        mask = domains[best_i]

        # Order options to mimic human preference:
        # try options whose total water matches current residual pressure.
        row_min, row_max, col_min, col_max = bounds_for_domains(domains)
        scored = []
        for oi in iter_bits(mask):
            rr = opt_row[best_i][oi]
            cc = opt_col[best_i][oi]
            score = 0
            for r in range(R):
                need_band_center = (row_target[r] - row_min[r] + row_target[r] - row_max[r]) ** 2
                score += abs(rr[r]) + need_band_center
            for c in range(C):
                need_band_center = (col_target[c] - col_min[c] + col_target[c] - col_max[c]) ** 2
                score += abs(cc[c]) + need_band_center
            scored.append((score, oi))
        scored.sort()

        for _, oi in scored:
            new_domains = list(domains)
            new_domains[best_i] = 1 << oi
            res = search(tuple(new_domains))
            if res is not None:
                return res
        return None

    return search(domains0)


def solve(observation):
    region_grid = observation['region']
    row_target = observation['row_water_counts']
    col_target = observation['col_water_counts']

    R = len(region_grid)
    C = len(region_grid[0]) if R else 0

    # Special fast path: all regions singleton.
    regions = {}
    for r in range(R):
        for c in range(C):
            regions.setdefault(region_grid[r][c], []).append((r, c))

    if all(len(cells) == 1 for cells in regions.values()):
        grid = solve_binary_matrix(row_target, col_target)
    else:
        grid = solve_region_puzzle(observation)

    if grid is None:
        return "No Solution"
    return repr(grid)


