# Mosaic / Corral-like 3x3 counting puzzle solver.
# Cells are binary: white=None, black='B'.
# Each clue gives the count of black cells in its 3x3 neighborhood including itself.

from collections import deque

UNKNOWN = 3  # {white, black}
WHITE = 1    # white only
BLACK = 2    # black only


def solve(observation):
    data = observation["data"]
    if not data or not data[0]:
        return repr([])

    rows, cols = len(data), len(data[0])
    n = rows * cols

    def idx(r, c):
        return r * cols + c

    def rc(i):
        return divmod(i, cols)

    # Build clue structures.
    clues = []
    var_to_clues = [[] for _ in range(n)]

    for r in range(rows):
        for c in range(cols):
            v = data[r][c]
            if v is None:
                continue
            cells = []
            for rr in range(max(0, r - 1), min(rows, r + 2)):
                for cc in range(max(0, c - 1), min(cols, c + 2)):
                    cells.append(idx(rr, cc))
            clue_id = len(clues)
            cellset = frozenset(cells)
            clues.append({
                "target": v,
                "cells": tuple(cells),
                "cellset": cellset,
            })
            for x in cells:
                var_to_clues[x].append(clue_id)

    m = len(clues)

    # Precompute pairwise overlap/difference structures for stronger deductions.
    pair_info_by_clue = [[] for _ in range(m)]
    for a in range(m):
        A = clues[a]["cellset"]
        for b in range(a + 1, m):
            B = clues[b]["cellset"]
            if not (A & B):
                continue
            a_only = tuple(sorted(A - B))
            b_only = tuple(sorted(B - A))
            if not a_only and not b_only:
                continue
            pair_info_by_clue[a].append((a, b, a_only, b_only))
            pair_info_by_clue[b].append((a, b, a_only, b_only))

    impact = [len(var_to_clues[i]) for i in range(n)]
    domains0 = [UNKNOWN] * n

    def assign(domains, cell, value, queue):
        cur = domains[cell]
        if cur == value:
            return True
        if cur != UNKNOWN:
            return False
        domains[cell] = value
        for cid in var_to_clues[cell]:
            queue.append(cid)
        return True

    def clue_stats(domains, cells):
        black_fixed = 0
        undec = []
        for x in cells:
            d = domains[x]
            if d == BLACK:
                black_fixed += 1
            elif d == UNKNOWN:
                undec.append(x)
        return black_fixed, undec

    def propagate(domains):
        queue = deque(range(m))
        in_queue = [True] * m

        while queue:
            cid = queue.popleft()
            in_queue[cid] = False
            clue = clues[cid]
            target = clue["target"]
            cells = clue["cells"]

            black_fixed, undec = clue_stats(domains, cells)
            mn = black_fixed
            mx = black_fixed + len(undec)

            if target < mn or target > mx:
                return False

            # Direct human-style saturation:
            # if target already reached => remaining are white
            # if all remaining must be black => set them black
            if undec:
                if target == mn:
                    for x in undec:
                        if not assign(domains, x, WHITE, queue):
                            return False
                elif target == mx:
                    for x in undec:
                        if not assign(domains, x, BLACK, queue):
                            return False

            # Pairwise clue difference propagation.
            # For clues A,B: sum(A_only) - sum(B_only) = targetA - targetB
            for a, b, a_only, b_only in pair_info_by_clue[cid]:
                ta = clues[a]["target"]
                tb = clues[b]["target"]
                diff = ta - tb

                af = au = 0
                a_undec = []
                for x in a_only:
                    d = domains[x]
                    if d == BLACK:
                        af += 1
                    elif d == UNKNOWN:
                        au += 1
                        a_undec.append(x)

                bf = bu = 0
                b_undec = []
                for x in b_only:
                    d = domains[x]
                    if d == BLACK:
                        bf += 1
                    elif d == UNKNOWN:
                        bu += 1
                        b_undec.append(x)

                a_min, a_max = af, af + au
                b_min, b_max = bf, bf + bu

                # Existence check.
                if diff < a_min - b_max or diff > a_max - b_min:
                    return False

                # Tighten sum(A_only) bounds using sum(B_only) bounds.
                new_a_min = max(a_min, diff + b_min)
                new_a_max = min(a_max, diff + b_max)

                # Tighten sum(B_only) bounds using sum(A_only) bounds.
                new_b_min = max(b_min, a_min - diff)
                new_b_max = min(b_max, a_max - diff)

                if new_a_min > new_a_max or new_b_min > new_b_max:
                    return False

                # If exact sum over difference set is known, force extremal cells.
                if au:
                    if new_a_min == new_a_max:
                        exact = new_a_min
                        if exact < af or exact > af + au:
                            return False
                        if exact == af:
                            for x in a_undec:
                                if not assign(domains, x, WHITE, queue):
                                    return False
                        elif exact == af + au:
                            for x in a_undec:
                                if not assign(domains, x, BLACK, queue):
                                    return False

                if bu:
                    if new_b_min == new_b_max:
                        exact = new_b_min
                        if exact < bf or exact > bf + bu:
                            return False
                        if exact == bf:
                            for x in b_undec:
                                if not assign(domains, x, WHITE, queue):
                                    return False
                        elif exact == bf + bu:
                            for x in b_undec:
                                if not assign(domains, x, BLACK, queue):
                                    return False

        return True

    def fully_satisfied(domains):
        for clue in clues:
            black_fixed, undec = clue_stats(domains, clue["cells"])
            if undec or black_fixed != clue["target"]:
                return False
        return True

    def choose_var(domains):
        best = None
        best_key = None
        for i, d in enumerate(domains):
            if d != UNKNOWN:
                continue
            # Most constrained / most influential variable.
            # Use aggregate slack among adjacent clues.
            degree = impact[i]
            total_span = 0
            for cid in var_to_clues[i]:
                clue = clues[cid]
                black_fixed, undec = clue_stats(domains, clue["cells"])
                total_span += (black_fixed + len(undec)) - black_fixed
            key = (-degree, total_span)
            if best is None or key < best_key:
                best = i
                best_key = key
        return best

    def branch_order(domains, cell):
        # Estimate whether black or white is more constrained by neighboring clues.
        black_pressure = 0
        white_pressure = 0
        for cid in var_to_clues[cell]:
            clue = clues[cid]
            black_fixed, undec = clue_stats(domains, clue["cells"])
            need = clue["target"] - black_fixed
            rem = len(undec)
            # If need/rem high, black is favored; if low, white is favored.
            black_pressure += need
            white_pressure += rem - need
        if black_pressure >= white_pressure:
            return (BLACK, WHITE)
        return (WHITE, BLACK)

    def search(domains):
        if not propagate(domains):
            return None

        cell = choose_var(domains)
        if cell is None:
            return domains if fully_satisfied(domains) else None

        for value in branch_order(domains, cell):
            nd = domains[:]
            q = deque()
            if assign(nd, cell, value, q):
                # Consume immediate queue with normal propagation machinery.
                # push all clues if needed; q already has touched clues.
                if q:
                    seen = [False] * m
                    while q:
                        cid = q.popleft()
                        if not seen[cid]:
                            seen[cid] = True
                    # Standard propagate will revisit everything relevant and remain simple.
                ans = search(nd)
                if ans is not None:
                    return ans
        return None

    result = search(domains0)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(rows):
        row = []
        for c in range(cols):
            row.append('B' if result[idx(r, c)] == BLACK else None)
        grid.append(row)
    return repr(grid)


