from collections import deque

# Cell states for white cells:
#  0 = undecided
#  1 = bulb
# -1 = confirmed non-bulb
#
# Black cells are stored in the observation grid:
#  None -> white
#  -1   -> unnumbered black
#  0..4 -> numbered black

def solve(observation):
    board = observation["data"]
    n = len(board)
    m = len(board[0]) if n else 0

    white_cells = []
    black_cells = []
    numbered_blacks = []

    for r in range(n):
        for c in range(m):
            v = board[r][c]
            if v is None:
                white_cells.append((r, c))
            else:
                black_cells.append((r, c))
                if v >= 0:
                    numbered_blacks.append((r, c))

    white_index = {cell: i for i, cell in enumerate(white_cells)}
    wcount = len(white_cells)

    # Precompute orthogonal neighbors for numbered black constraints.
    adj_whites_of_black = {}
    adj_blacks_of_white = {cell: [] for cell in white_cells}
    for br, bc in numbered_blacks:
        adj = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = br + dr, bc + dc
            if 0 <= nr < n and 0 <= nc < m and board[nr][nc] is None:
                adj.append((nr, nc))
                adj_blacks_of_white[(nr, nc)].append((br, bc))
        adj_whites_of_black[(br, bc)] = adj

    # Precompute visibility sets for each white cell.
    # vis[cell] = all white cells seen by placing a bulb at cell, including itself.
    vis = {}
    for r, c in white_cells:
        seen = [(r, c)]
        rr = r - 1
        while rr >= 0 and board[rr][c] is None:
            seen.append((rr, c))
            rr -= 1
        rr = r + 1
        while rr < n and board[rr][c] is None:
            seen.append((rr, c))
            rr += 1
        cc = c - 1
        while cc >= 0 and board[r][cc] is None:
            seen.append((r, cc))
            cc -= 1
        cc = c + 1
        while cc < m and board[r][cc] is None:
            seen.append((r, cc))
            cc += 1
        vis[(r, c)] = tuple(seen)

    # Maximal row/column segments of white cells.
    row_segments = []
    row_seg_id = {}
    for r in range(n):
        c = 0
        while c < m:
            if board[r][c] is None:
                seg = []
                while c < m and board[r][c] is None:
                    seg.append((r, c))
                    c += 1
                sid = len(row_segments)
                row_segments.append(tuple(seg))
                for cell in seg:
                    row_seg_id[cell] = sid
            else:
                c += 1

    col_segments = []
    col_seg_id = {}
    for c in range(m):
        r = 0
        while r < n:
            if board[r][c] is None:
                seg = []
                while r < n and board[r][c] is None:
                    seg.append((r, c))
                    r += 1
                sid = len(col_segments)
                col_segments.append(tuple(seg))
                for cell in seg:
                    col_seg_id[cell] = sid
            else:
                r += 1

    # For each white cell, all potential bulb positions that can light it.
    # This is exactly vis[cell], because visibility is symmetric on white runs.
    coverers = {cell: vis[cell] for cell in white_cells}

    # Initialize state.
    state = {cell: 0 for cell in white_cells}
    lit_count = {cell: 0 for cell in white_cells}

    # Numbered black bookkeeping.
    black_bulbs = {b: 0 for b in numbered_blacks}
    black_unknown = {b: len(adj_whites_of_black[b]) for b in numbered_blacks}

    # Segment bookkeeping: at most one bulb per segment.
    row_seg_bulb = [0] * len(row_segments)
    row_seg_unknown = [len(seg) for seg in row_segments]
    col_seg_bulb = [0] * len(col_segments)
    col_seg_unknown = [len(seg) for seg in col_segments]

    # Reversible action log for DFS.
    log = []

    def snapshot():
        return len(log)

    def rollback(mark):
        while len(log) > mark:
            kind, data = log.pop()
            if kind == "state":
                cell, old = data
                state[cell] = old
            elif kind == "lit":
                cell, old = data
                lit_count[cell] = old
            elif kind == "bb":
                b, old = data
                black_bulbs[b] = old
            elif kind == "bu":
                b, old = data
                black_unknown[b] = old
            elif kind == "rsb":
                sid, old = data
                row_seg_bulb[sid] = old
            elif kind == "rsu":
                sid, old = data
                row_seg_unknown[sid] = old
            elif kind == "csb":
                sid, old = data
                col_seg_bulb[sid] = old
            elif kind == "csu":
                sid, old = data
                col_seg_unknown[sid] = old

    def set_state(cell, new_state, queue):
        old = state[cell]
        if old == new_state:
            return True
        if old != 0:
            return False

        log.append(("state", (cell, old)))
        state[cell] = new_state

        rs = row_seg_id[cell]
        cs = col_seg_id[cell]
        log.append(("rsu", (rs, row_seg_unknown[rs])))
        row_seg_unknown[rs] -= 1
        log.append(("csu", (cs, col_seg_unknown[cs])))
        col_seg_unknown[cs] -= 1

        for b in adj_blacks_of_white[cell]:
            log.append(("bu", (b, black_unknown[b])))
            black_unknown[b] -= 1
            queue.append(("black", b))

        queue.append(("cover", cell))
        queue.append(("rowseg", rs))
        queue.append(("colseg", cs))

        if new_state == 1:
            log.append(("rsb", (rs, row_seg_bulb[rs])))
            row_seg_bulb[rs] += 1
            log.append(("csb", (cs, col_seg_bulb[cs])))
            col_seg_bulb[cs] += 1

            for b in adj_blacks_of_white[cell]:
                log.append(("bb", (b, black_bulbs[b])))
                black_bulbs[b] += 1
                queue.append(("black", b))

            for seen in vis[cell]:
                log.append(("lit", (seen, lit_count[seen])))
                lit_count[seen] += 1
                queue.append(("cover", seen))

            # A bulb forbids every other visible cell from being a bulb.
            for seen in vis[cell]:
                if seen != cell:
                    queue.append(("force_empty", seen))

        return True

    def check_black(b):
        need = board[b[0]][b[1]]
        bulbs = black_bulbs[b]
        unk = black_unknown[b]
        if bulbs > need:
            return False
        if bulbs + unk < need:
            return False
        return True

    def process_black(b, queue):
        if not check_black(b):
            return False
        need = board[b[0]][b[1]]
        bulbs = black_bulbs[b]
        unk = black_unknown[b]
        rem = need - bulbs
        if rem == 0:
            for cell in adj_whites_of_black[b]:
                if state[cell] == 0:
                    if not set_state(cell, -1, queue):
                        return False
        elif rem == unk:
            for cell in adj_whites_of_black[b]:
                if state[cell] == 0:
                    if not set_state(cell, 1, queue):
                        return False
        return True

    def process_rowseg(sid, queue):
        bulbs = row_seg_bulb[sid]
        unk = row_seg_unknown[sid]
        if bulbs > 1:
            return False
        if bulbs == 1:
            for cell in row_segments[sid]:
                if state[cell] == 0:
                    if not set_state(cell, -1, queue):
                        return False
        elif bulbs == 0 and unk == 1:
            # Human-like pressure from "this segment must host the only possible bulb"
            # is handled more safely by cover constraints. No forced move here.
            pass
        return True

    def process_colseg(sid, queue):
        bulbs = col_seg_bulb[sid]
        unk = col_seg_unknown[sid]
        if bulbs > 1:
            return False
        if bulbs == 1:
            for cell in col_segments[sid]:
                if state[cell] == 0:
                    if not set_state(cell, -1, queue):
                        return False
        elif bulbs == 0 and unk == 1:
            pass
        return True

    def process_cover(cell, queue):
        # Every white cell must be lit by at least one bulb.
        if lit_count[cell] > 0:
            return True

        possibles = []
        for p in coverers[cell]:
            if state[p] != -1:
                # state 0 or 1 can still/does light this cell
                possibles.append(p)

        if not possibles:
            return False
        if len(possibles) == 1:
            only = possibles[0]
            if not set_state(only, 1, queue):
                return False
        return True

    def propagate(initial_events=None):
        queue = deque()
        if initial_events:
            queue.extend(initial_events)
        else:
            for b in numbered_blacks:
                queue.append(("black", b))
            for sid in range(len(row_segments)):
                queue.append(("rowseg", sid))
            for sid in range(len(col_segments)):
                queue.append(("colseg", sid))
            for cell in white_cells:
                queue.append(("cover", cell))

        while queue:
            typ, obj = queue.popleft()
            if typ == "black":
                if not process_black(obj, queue):
                    return False
            elif typ == "rowseg":
                if not process_rowseg(obj, queue):
                    return False
            elif typ == "colseg":
                if not process_colseg(obj, queue):
                    return False
            elif typ == "cover":
                if not process_cover(obj, queue):
                    return False
            elif typ == "force_empty":
                if state[obj] == 0:
                    if not set_state(obj, -1, queue):
                        return False
                elif state[obj] == 1:
                    return False
        return True

    def all_satisfied():
        for b in numbered_blacks:
            if black_bulbs[b] != board[b[0]][b[1]]:
                return False
        for sid in range(len(row_segments)):
            if row_seg_bulb[sid] > 1:
                return False
        for sid in range(len(col_segments)):
            if col_seg_bulb[sid] > 1:
                return False
        for cell in white_cells:
            if lit_count[cell] <= 0:
                return False
        return True

    def choose_branch_cell():
        # Prefer unresolved cells participating in tight numbered constraints.
        best = None
        best_key = None

        for cell in white_cells:
            if state[cell] != 0:
                continue

            pressure = 0
            for b in adj_blacks_of_white[cell]:
                need = board[b[0]][b[1]] - black_bulbs[b]
                unk = black_unknown[b]
                pressure += 10 - (unk - need) - need

            # How many still-possible bulbs can light this cell?
            cov = 0
            for p in coverers[cell]:
                if state[p] != -1:
                    cov += 1

            # Segment tightness: fewer remaining unknowns means stronger branch.
            rs = row_seg_id[cell]
            cs = col_seg_id[cell]
            seg_tight = row_seg_unknown[rs] + col_seg_unknown[cs]

            key = (-pressure, cov, seg_tight)
            if best_key is None or key < best_key:
                best_key = key
                best = cell

        return best

    def search():
        if not propagate():
            return False

        done = True
        for cell in white_cells:
            if state[cell] == 0:
                done = False
                break
        if done:
            return all_satisfied()

        cell = choose_branch_cell()
        if cell is None:
            return all_satisfied()

        # Branch order is heuristic:
        # If the cell is the unique remaining coverer for many cells, try bulb first.
        bulb_score = 0
        for target in vis[cell]:
            if lit_count[target] == 0:
                cnt = 0
                for p in coverers[target]:
                    if state[p] != -1:
                        cnt += 1
                if cnt == 1:
                    bulb_score += 3
                elif cnt == 2:
                    bulb_score += 1

        tries = [1, -1] if bulb_score >= 1 else [-1, 1]

        for choice in tries:
            mark = snapshot()
            q = deque()
            if set_state(cell, choice, q) and propagate(q):
                if search():
                    return True
            rollback(mark)

        return False

    if not search():
        return "No Solution"

    answer = [[None for _ in range(m)] for _ in range(n)]
    for r, c in white_cells:
        if state[(r, c)] == 1:
            answer[r][c] = "B"
    return repr(answer)


