from collections import deque

def solve(observation):
    data = observation["data"]
    N = len(data)
    full = (1 << N) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def is_single(x):
        return x and (x & (x - 1)) == 0

    def single_value(x):
        return x.bit_length()

    def values_of(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    def idx(r, c):
        return r * N + c

    def rc(i):
        return divmod(i, N)

    rows = [[idx(r, c) for c in range(N)] for r in range(N)]
    cols = [[idx(r, c) for r in range(N)] for c in range(N)]

    # Orthogonal adjacency graph with explicit relation:
    # True  -> consecutive required
    # False -> consecutive forbidden
    consecutive_edges = set()
    for a, b in observation["adjacent"]:
        if float(a).is_integer():
            r = int(a)
            c = int(b - 0.5)
            u, v = idx(r, c), idx(r, c + 1)
        else:
            r = int(a - 0.5)
            c = int(b)
            u, v = idx(r, c), idx(r + 1, c)
        if u > v:
            u, v = v, u
        consecutive_edges.add((u, v))

    neighbors = [[] for _ in range(N * N)]
    ortho_pairs = []
    for r in range(N):
        for c in range(N):
            u = idx(r, c)
            for dr, dc in ((0, 1), (1, 0)):
                rr, cc = r + dr, c + dc
                if rr < N and cc < N:
                    v = idx(rr, cc)
                    a, b = (u, v) if u < v else (v, u)
                    req = (a, b) in consecutive_edges
                    neighbors[u].append((v, req))
                    neighbors[v].append((u, req))
                    ortho_pairs.append((a, b, req))

    degree = [len(neighbors[i]) + 2 * (2 * N - 2) for i in range(N * N)]

    # Precompute support for consecutive relation.
    consec_support = [0] * (full + 1)
    for m in range(full + 1):
        consec_support[m] = ((m << 1) | (m >> 1)) & full

    def has_nonconsec_support(v, mask_j):
        # v is 1..N
        bad = 0
        if v > 1:
            bad |= bit(v - 1)
        if v < N:
            bad |= bit(v + 1)
        return (mask_j & ~bad) != 0

    def revise(dom, i, j, req):
        mi = dom[i]
        mj = dom[j]
        if req:
            nm = mi & consec_support[mj]
        else:
            nm = 0
            mm = mi
            while mm:
                b = mm & -mm
                v = b.bit_length()
                if has_nonconsec_support(v, mj):
                    nm |= b
                mm ^= b
        if nm != mi:
            if nm == 0:
                return -1
            dom[i] = nm
            return 1
        return 0

    def eliminate_used(dom):
        changed = False
        for groups in (rows, cols):
            for group in groups:
                used = 0
                for i in group:
                    m = dom[i]
                    if is_single(m):
                        if used & m:
                            return None
                        used |= m
                for i in group:
                    m = dom[i]
                    if not is_single(m):
                        nm = m & ~used
                        if nm == 0:
                            return None
                        if nm != m:
                            dom[i] = nm
                            changed = True
        return changed

    def hidden_singles(dom):
        changed = False
        for groups in (rows, cols):
            for group in groups:
                spots = [0] * N
                for i in group:
                    m = dom[i]
                    mm = m
                    while mm:
                        b = mm & -mm
                        v = b.bit_length() - 1
                        if spots[v] == -1:
                            pass
                        elif spots[v] == 0:
                            spots[v] = i + 1
                        else:
                            spots[v] = -1
                        mm ^= b
                for v in range(N):
                    s = spots[v]
                    if s > 0:
                        i = s - 1
                        b = 1 << v
                        if dom[i] != b:
                            dom[i] = b
                            changed = True
        return changed

    def naked_pairs(dom):
        changed = False
        for groups in (rows, cols):
            for group in groups:
                seen = {}
                for i in group:
                    m = dom[i]
                    if popcount(m) == 2:
                        seen.setdefault(m, []).append(i)
                for m, cells in seen.items():
                    if len(cells) == 2:
                        for i in group:
                            if i not in cells:
                                nm = dom[i] & ~m
                                if nm == 0:
                                    return None
                                if nm != dom[i]:
                                    dom[i] = nm
                                    changed = True
        return changed

    def propagate(dom):
        q = deque()
        inq = set()
        for i in range(N * N):
            for j, req in neighbors[i]:
                q.append((i, j, req))
                inq.add((i, j))

        while True:
            changed_any = False

            res = eliminate_used(dom)
            if res is None:
                return None
            changed_any |= res

            res = hidden_singles(dom)
            if res is None:
                return None
            changed_any |= res

            res = naked_pairs(dom)
            if res is None:
                return None
            changed_any |= res

            # Requeue arcs after structural row/col deductions.
            if changed_any:
                q.clear()
                inq.clear()
                for i in range(N * N):
                    for j, req in neighbors[i]:
                        q.append((i, j, req))
                        inq.add((i, j))

            arc_changed = False
            while q:
                i, j, req = q.popleft()
                inq.discard((i, j))
                r = revise(dom, i, j, req)
                if r == -1:
                    return None
                if r == 1:
                    arc_changed = True
                    for k, req2 in neighbors[i]:
                        if k != j and (k, i) not in inq:
                            q.append((k, i, req2))
                            inq.add((k, i))
            if not arc_changed and not changed_any:
                break

        # Final Latin validity on solved rows/cols.
        for groups in (rows, cols):
            for group in groups:
                used = 0
                for i in group:
                    m = dom[i]
                    if is_single(m):
                        if used & m:
                            return None
                        used |= m
        return dom

    domains = [full] * (N * N)
    for r in range(N):
        for c in range(N):
            if data[r][c] is not None:
                domains[idx(r, c)] = bit(data[r][c])

    domains = propagate(domains)
    if domains is None:
        return "No Solution"

    def solved(dom):
        return all(is_single(m) for m in dom)

    def choose_cell(dom):
        best = None
        best_key = None
        for i, m in enumerate(dom):
            pc = popcount(m)
            if pc > 1:
                # MRV, then higher constraint degree
                key = (pc, -degree[i])
                if best_key is None or key < best_key:
                    best_key = key
                    best = i
        return best

    def value_order(dom, i):
        # Least-constraining value based on immediate effect on row/col and orthogonal neighbors.
        r, c = rc(i)
        group = set(rows[r] + cols[c])
        group.discard(i)
        opts = []
        for v in values_of(dom[i]):
            score = 0
            b = bit(v)
            for j in group:
                if dom[j] & b:
                    score += 1
            for j, req in neighbors[i]:
                mj = dom[j]
                if req:
                    support = consec_support[b]
                    score += popcount(mj & ~support)
                else:
                    bad = 0
                    if v > 1:
                        bad |= bit(v - 1)
                    if v < N:
                        bad |= bit(v + 1)
                    score += popcount(mj & bad)
            opts.append((score, v))
        opts.sort()
        return [v for _, v in opts]

    def search(dom):
        if solved(dom):
            return dom

        i = choose_cell(dom)
        for v in value_order(dom, i):
            nd = dom[:]
            nd[i] = bit(v)
            nd = propagate(nd)
            if nd is None:
                continue
            res = search(nd)
            if res is not None:
                return res
        return None

    ans = search(domains)
    if ans is None:
        return "No Solution"

    grid = []
    for r in range(N):
        row = []
        for c in range(N):
            row.append(str(single_value(ans[idx(r, c)])))
        grid.append(" ".join(row))
    return "\n".join(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 2, None, None, None, None, None, None, 3], [1, None, None, 1, None, None, None, 3, None, None], [None, None, None, None, None, None, None, None, None, None], [3, None, 4, None, None, None, None, 3, None, None], [None, None, None, None, None, None, None, None, None, None], [None, None, 2, None, None, None, 1, None, None, None], [5, None, None, None, None, None, None, None, 3, None], [None, None, None, None, None, None, None, None, None, None], [4, None, None, 3, None, None, 1, None, None, 2], [None, None, None, None, None, None, None, None, 1, None]]}

from collections import deque

# Bitmask domain helpers for values {0,1,2}
BIT = [1, 2, 4]
MASKS_BY_MAX = [1, 3, 7]

def mask_values(mask):
    return [v for v in (0, 1, 2) if mask & BIT[v]]

def mask_min(mask):
    if mask & 1:
        return 0
    if mask & 2:
        return 1
    return 2

def mask_max(mask):
    if mask & 4:
        return 2
    if mask & 2:
        return 1
    return 0

def singleton_value(mask):
    if mask == 1:
        return 0
    if mask == 2:
        return 1
    if mask == 4:
        return 2
    return None

def is_singleton(mask):
    return mask in (1, 2, 4)

def interval_mask(lo, hi):
    if lo > hi:
        return 0
    m = 0
    for v in range(max(0, lo), min(2, hi) + 1):
        m |= BIT[v]
    return m

def build_problem(data):
    n = len(data)
    islands = []
    pos_to_idx = {}
    for r in range(n):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                pos_to_idx[(r, c)] = len(islands)
                islands.append(((r, c), data[r][c]))

    edges = []
    incident = [[] for _ in islands]

    # Horizontal visibility edges
    for r in range(n):
        prev = None
        for c in range(len(data[r])):
            if data[r][c] is not None:
                if prev is not None:
                    a = pos_to_idx[(r, prev)]
                    b = pos_to_idx[(r, c)]
                    eid = len(edges)
                    edges.append({
                        'a': a, 'b': b, 'orient': 'H',
                        'r': r, 'c1': prev, 'c2': c,
                        'cross': []
                    })
                    incident[a].append(eid)
                    incident[b].append(eid)
                prev = c

    # Vertical visibility edges
    cols = max(len(row) for row in data)
    for c in range(cols):
        prev = None
        for r in range(n):
            if c < len(data[r]) and data[r][c] is not None:
                if prev is not None:
                    a = pos_to_idx[(prev, c)]
                    b = pos_to_idx[(r, c)]
                    eid = len(edges)
                    edges.append({
                        'a': a, 'b': b, 'orient': 'V',
                        'c': c, 'r1': prev, 'r2': r,
                        'cross': []
                    })
                    incident[a].append(eid)
                    incident[b].append(eid)
                prev = r

    # Crossing relations: only H-V, strict interior crossing
    horiz = [i for i, e in enumerate(edges) if e['orient'] == 'H']
    vert = [i for i, e in enumerate(edges) if e['orient'] == 'V']
    for hi in horiz:
        eh = edges[hi]
        r = eh['r']
        for vi in vert:
            ev = edges[vi]
            c = ev['c']
            if eh['c1'] < c < eh['c2'] and ev['r1'] < r < ev['r2']:
                edges[hi]['cross'].append(vi)
                edges[vi]['cross'].append(hi)

    demands = [v for _, v in islands]
    return {
        'islands': islands,
        'edges': edges,
        'incident': incident,
        'demands': demands,
    }

def connected_possible(problem, domains):
    n = len(problem['islands'])
    if n == 0:
        return True
    adj = [[] for _ in range(n)]
    for eid, e in enumerate(problem['edges']):
        if domains[eid] & (BIT[1] | BIT[2]):
            a, b = e['a'], e['b']
            adj[a].append(b)
            adj[b].append(a)
    seen = [False] * n
    dq = deque([0])
    seen[0] = True
    while dq:
        x = dq.popleft()
        for y in adj[x]:
            if not seen[y]:
                seen[y] = True
                dq.append(y)
    return all(seen)

def forced_component_dead_end(problem, domains):
    n = len(problem['islands'])
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    for eid, e in enumerate(problem['edges']):
        if mask_min(domains[eid]) > 0:
            union(e['a'], e['b'])

    comps = {}
    for i in range(n):
        comps.setdefault(find(i), []).append(i)

    if len(comps) <= 1:
        return False

    # If any forced component has no possible edge leaving it, impossible.
    comp_id = [find(i) for i in range(n)]
    for root, nodes in comps.items():
        closed = True
        node_set = set(nodes)
        for i in nodes:
            for eid in problem['incident'][i]:
                e = problem['edges'][eid]
                j = e['b'] if e['a'] == i else e['a']
                if j not in node_set and mask_max(domains[eid]) > 0:
                    closed = False
                    break
            if not closed:
                break
        if closed:
            return True
    return False

def propagate(problem, domains):
    domains = domains[:]  # copy
    edges = problem['edges']
    incident = problem['incident']
    demands = problem['demands']
    n_islands = len(problem['islands'])

    changed = True
    while changed:
        changed = False

        # Edge-local pruning from endpoints and crossings.
        for eid, e in enumerate(edges):
            old = domains[eid]
            if old == 0:
                return None

            a, b = e['a'], e['b']
            # Capacity ceiling from endpoints' remaining possible totals
            max_edge = min(2, demands[a], demands[b])
            old &= MASKS_BY_MAX[max_edge]
            if old == 0:
                return None

            # If edge is forced positive, all crossing edges must be zero.
            if mask_min(old) > 0:
                for xid in e['cross']:
                    newm = domains[xid] & 1
                    if newm == 0:
                        return None
                    if newm != domains[xid]:
                        domains[xid] = newm
                        changed = True

            # If any crossing edge is forced positive, this one must be zero.
            for xid in e['cross']:
                if mask_min(domains[xid]) > 0:
                    old &= 1
                    break
            if old == 0:
                return None
            if old != domains[eid]:
                domains[eid] = old
                changed = True

        # Island quota propagation.
        for i in range(n_islands):
            inc = incident[i]
            mins = [mask_min(domains[eid]) for eid in inc]
            maxs = [mask_max(domains[eid]) for eid in inc]
            smin = sum(mins)
            smax = sum(maxs)
            need = demands[i]
            if need < smin or need > smax:
                return None

            # Human-style exact fill / exact exhaustion.
            if need == smin:
                for idx, eid in enumerate(inc):
                    m = BIT[mins[idx]]
                    if domains[eid] != m:
                        domains[eid] = m
                        changed = True
            elif need == smax:
                for idx, eid in enumerate(inc):
                    m = BIT[maxs[idx]]
                    if domains[eid] != m:
                        domains[eid] = m
                        changed = True
            else:
                # Per-edge necessary range:
                for idx, eid in enumerate(inc):
                    other_min = smin - mins[idx]
                    other_max = smax - maxs[idx]
                    lo = need - other_max
                    hi = need - other_min
                    newm = domains[eid] & interval_mask(lo, hi)
                    if newm == 0:
                        return None
                    if newm != domains[eid]:
                        domains[eid] = newm
                        changed = True

        # Global connectivity pruning.
        if not connected_possible(problem, domains):
            return None
        if forced_component_dead_end(problem, domains):
            return None

    return domains

def final_check(problem, domains):
    vals = [singleton_value(m) for m in domains]
    if any(v is None for v in vals):
        return False
    for i, need in enumerate(problem['demands']):
        s = 0
        for eid in problem['incident'][i]:
            s += vals[eid]
        if s != need:
            return False
    n = len(problem['islands'])
    if n == 0:
        return True
    adj = [[] for _ in range(n)]
    for eid, e in enumerate(problem['edges']):
        if vals[eid] > 0:
            adj[e['a']].append(e['b'])
            adj[e['b']].append(e['a'])
    seen = [False] * n
    dq = deque([0])
    seen[0] = True
    while dq:
        x = dq.popleft()
        for y in adj[x]:
            if not seen[y]:
                seen[y] = True
                dq.append(y)
    return all(seen)

def choose_branch_edge(problem, domains):
    best = None
    best_key = None
    for eid, m in enumerate(domains):
        if is_singleton(m):
            continue
        vals = mask_values(m)
        e = problem['edges'][eid]
        # Smaller domain first, then more crossings, then tighter endpoints.
        score = (
            len(vals),
            -len(e['cross']),
            len(problem['incident'][e['a']]) + len(problem['incident'][e['b']])
        )
        if best is None or score < best_key:
            best = eid
            best_key = score
    return best

def branch_values(problem, domains, eid):
    vals = mask_values(domains[eid])

    # Prefer values that align with human deductions:
    # if any endpoint is nearly saturated, try higher values first; otherwise middle first.
    e = problem['edges'][eid]
    prefs = []
    for i in (e['a'], e['b']):
        need = problem['demands'][i]
        smin = sum(mask_min(domains[x]) for x in problem['incident'][i])
        smax = sum(mask_max(domains[x]) for x in problem['incident'][i])
        slack_low = need - smin
        slack_high = smax - need
        prefs.append((slack_low, slack_high))
    tight = min(a + b for a, b in prefs)

    if tight <= 1:
        order = [2, 1, 0]
    else:
        order = [1, 2, 0]
    return [v for v in order if v in vals]

def search(problem, domains):
    domains = propagate(problem, domains)
    if domains is None:
        return None
    if all(is_singleton(m) for m in domains):
        return domains if final_check(problem, domains) else None

    eid = choose_branch_edge(problem, domains)
    for v in branch_values(problem, domains, eid):
        new_domains = domains[:]
        new_domains[eid] = BIT[v]
        res = search(problem, new_domains)
        if res is not None:
            return res
    return None

def format_answer(problem, domains):
    ans = {}
    for eid, m in enumerate(domains):
        v = singleton_value(m)
        if v and v > 0:
            a = problem['islands'][problem['edges'][eid]['a']][0]
            b = problem['islands'][problem['edges'][eid]['b']][0]
            if a <= b:
                ans[(a, b)] = v
            else:
                ans[(b, a)] = v
    # Stable ordering for repr
    ordered = {}
    for k in sorted(ans):
        ordered[k] = ans[k]
    return ordered

def solve(observation):
    data = observation['data']
    problem = build_problem(data)
    initial_domains = []
    for e in problem['edges']:
        a, b = e['a'], e['b']
        mx = min(2, problem['demands'][a], problem['demands'][b])
        initial_domains.append(MASKS_BY_MAX[mx])

    result = search(problem, initial_domains)
    if result is None:
        return "No Solution"
    return str(format_answer(problem, result))

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 0, None, 0, None], [2, None, None, None, None, None], [None, None, 2, None, None, 2], [2, 2, None, 2, 1, None], [0, None, None, None, None, 0], [None, None, 0, None, 1, None]]}

# Slant puzzle solver:
# - one diagonal per cell: '/' or '\'
# - numbered dots require exact incident diagonal count
# - no closed loops allowed
#
# The solver uses:
# 1) domain filtering on each cell
# 2) exact-count propagation on each clue dot
# 3) dynamic loop prevention via DSU over dot graph
# 4) focused backtracking only when deduction stalls

SLASH = 1
BACKSLASH = 2
BOTH = SLASH | BACKSLASH


def solve(observation):
    data = observation['data']
    m = len(data)
    if m == 0 or any(len(row) != m for row in data):
        return "No Solution"
    n = m - 1
    if n < 0:
        return "No Solution"

    def dot_id(r, c):
        return r * (n + 1) + c

    # For each cell and orientation, store:
    # - endpoints of the diagonal edge in the dot graph
    # - for each of the four surrounding dots whether that orientation touches the dot
    cell_info = [[None] * n for _ in range(n)]
    dot_to_incident = [[[] for _ in range(n + 1)] for _ in range(n + 1)]

    for r in range(n):
        for c in range(n):
            slash_endpoints = (dot_id(r, c + 1), dot_id(r + 1, c))
            backslash_endpoints = (dot_id(r, c), dot_id(r + 1, c + 1))

            # Corner touch maps
            # corners: TL=(r,c), TR=(r,c+1), BL=(r+1,c), BR=(r+1,c+1)
            touch = {
                (r, c): {SLASH: False, BACKSLASH: True},
                (r, c + 1): {SLASH: True, BACKSLASH: False},
                (r + 1, c): {SLASH: True, BACKSLASH: False},
                (r + 1, c + 1): {SLASH: False, BACKSLASH: True},
            }

            cell_info[r][c] = {
                SLASH: slash_endpoints,
                BACKSLASH: backslash_endpoints,
                'touch': touch,
            }

            for dr in (0, 1):
                for dc in (0, 1):
                    rr, cc = r + dr, c + dc
                    dot_to_incident[rr][cc].append((r, c))

    total_dots = (n + 1) * (n + 1)

    def dsu_find(parent, x):
        while parent[x] != x:
            x = parent[x]
        return x

    def dsu_union(parent, size, a, b):
        ra = dsu_find(parent, a)
        rb = dsu_find(parent, b)
        if ra == rb:
            return False
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        return True

    def make_state():
        return {
            'domains': [[BOTH for _ in range(n)] for _ in range(n)],
            'assigned': [[0 for _ in range(n)] for _ in range(n)],
            'parent': list(range(total_dots)),
            'size': [1] * total_dots,
        }

    def clone_state(state):
        return {
            'domains': [row[:] for row in state['domains']],
            'assigned': [row[:] for row in state['assigned']],
            'parent': state['parent'][:],
            'size': state['size'][:],
        }

    def orientation_char(v):
        return '/' if v == SLASH else '\\'

    def endpoints_of(r, c, orient):
        return cell_info[r][c][orient]

    def orientation_touches_dot(r, c, orient, dr, dc):
        return cell_info[r][c]['touch'][(dr, dc)][orient]

    def restrict_cell(state, r, c, must_touch_dot=None, dot_pos=None, keep_mask=None):
        d = state['domains'][r][c]
        if keep_mask is None:
            if must_touch_dot is None or dot_pos is None:
                return True, False
            rr, cc = dot_pos
            mask = 0
            if d & SLASH and orientation_touches_dot(r, c, SLASH, rr, cc) == must_touch_dot:
                mask |= SLASH
            if d & BACKSLASH and orientation_touches_dot(r, c, BACKSLASH, rr, cc) == must_touch_dot:
                mask |= BACKSLASH
            keep_mask = mask

        nd = d & keep_mask
        if nd == 0:
            return False, False
        if nd != d:
            state['domains'][r][c] = nd
            return True, True
        return True, False

    def assign_singletons_and_filter_cycles(state):
        changed = False
        progress = True
        while progress:
            progress = False

            # Remove orientations that would create a loop immediately.
            for r in range(n):
                for c in range(n):
                    d = state['domains'][r][c]
                    nd = d

                    if d & SLASH:
                        a, b = endpoints_of(r, c, SLASH)
                        if dsu_find(state['parent'], a) == dsu_find(state['parent'], b):
                            nd &= ~SLASH

                    if d & BACKSLASH:
                        a, b = endpoints_of(r, c, BACKSLASH)
                        if dsu_find(state['parent'], a) == dsu_find(state['parent'], b):
                            nd &= ~BACKSLASH

                    if nd == 0:
                        return False, changed
                    if nd != d:
                        state['domains'][r][c] = nd
                        changed = True
                        progress = True

            # Materialize singleton assignments into the DSU.
            for r in range(n):
                for c in range(n):
                    d = state['domains'][r][c]
                    assigned = state['assigned'][r][c]

                    if d == BOTH:
                        continue
                    if d not in (SLASH, BACKSLASH):
                        return False, changed

                    if assigned == 0:
                        a, b = endpoints_of(r, c, d)
                        if not dsu_union(state['parent'], state['size'], a, b):
                            return False, changed
                        state['assigned'][r][c] = d
                        changed = True
                        progress = True
                    elif assigned != d:
                        return False, changed

        return True, changed

    def propagate_dot_clues(state):
        changed = False
        for dr in range(n + 1):
            for dc in range(n + 1):
                clue = data[dr][dc]
                if clue is None:
                    continue

                forced = 0
                possible = 0
                flexible = []

                for r, c in dot_to_incident[dr][dc]:
                    d = state['domains'][r][c]
                    can_touch = False
                    can_avoid = False

                    if d & SLASH:
                        if orientation_touches_dot(r, c, SLASH, dr, dc):
                            can_touch = True
                        else:
                            can_avoid = True
                    if d & BACKSLASH:
                        if orientation_touches_dot(r, c, BACKSLASH, dr, dc):
                            can_touch = True
                        else:
                            can_avoid = True

                    if can_touch:
                        possible += 1
                    if can_touch and not can_avoid:
                        forced += 1
                    elif can_touch and can_avoid:
                        flexible.append((r, c))

                if clue < forced or clue > possible:
                    return False, changed

                if clue == forced:
                    # All flexible incident cells must avoid this dot.
                    for r, c in flexible:
                        ok, ch = restrict_cell(state, r, c, must_touch_dot=False, dot_pos=(dr, dc))
                        if not ok:
                            return False, changed
                        changed |= ch

                if clue == possible:
                    # Every cell that can touch this dot must touch it.
                    for r, c in dot_to_incident[dr][dc]:
                        d = state['domains'][r][c]
                        can_touch = False
                        can_avoid = False
                        if d & SLASH:
                            if orientation_touches_dot(r, c, SLASH, dr, dc):
                                can_touch = True
                            else:
                                can_avoid = True
                        if d & BACKSLASH:
                            if orientation_touches_dot(r, c, BACKSLASH, dr, dc):
                                can_touch = True
                            else:
                                can_avoid = True
                        if can_touch and can_avoid:
                            ok, ch = restrict_cell(state, r, c, must_touch_dot=True, dot_pos=(dr, dc))
                            if not ok:
                                return False, changed
                            changed |= ch

        return True, changed

    def propagate(state):
        while True:
            any_change = False

            ok, ch = assign_singletons_and_filter_cycles(state)
            if not ok:
                return False
            any_change |= ch

            ok, ch = propagate_dot_clues(state)
            if not ok:
                return False
            any_change |= ch

            if not any_change:
                break

        # Final clue consistency check
        for dr in range(n + 1):
            for dc in range(n + 1):
                clue = data[dr][dc]
                if clue is None:
                    continue
                forced = 0
                possible = 0
                for r, c in dot_to_incident[dr][dc]:
                    d = state['domains'][r][c]
                    can_touch = False
                    can_avoid = False
                    if d & SLASH:
                        if orientation_touches_dot(r, c, SLASH, dr, dc):
                            can_touch = True
                        else:
                            can_avoid = True
                    if d & BACKSLASH:
                        if orientation_touches_dot(r, c, BACKSLASH, dr, dc):
                            can_touch = True
                        else:
                            can_avoid = True
                    if can_touch:
                        possible += 1
                    if can_touch and not can_avoid:
                        forced += 1
                if clue < forced or clue > possible:
                    return False

        return True

    def solved(state):
        for r in range(n):
            for c in range(n):
                if state['domains'][r][c] == BOTH:
                    return False
                if state['domains'][r][c] not in (SLASH, BACKSLASH):
                    return False
        return True

    def choose_branch_cell(state):
        best = None
        best_score = None

        for r in range(n):
            for c in range(n):
                if state['domains'][r][c] != BOTH:
                    continue

                # Heuristic: branch on the most clue-constrained cell.
                score = 0
                for dr in (r, r + 1):
                    for dc in (c, c + 1):
                        clue = data[dr][dc]
                        if clue is not None:
                            score += 1

                # More constrained dots and proximity to forced structure are preferred.
                key = (-score, r, c)
                if best is None or key < best_score:
                    best = (r, c)
                    best_score = key

        return best

    def order_orientations(state, r, c):
        # Try the orientation that better fits nearby clue pressure first.
        scores = []
        for orient in (SLASH, BACKSLASH):
            if not (state['domains'][r][c] & orient):
                continue
            fit = 0
            for dr in (r, r + 1):
                for dc in (c, c + 1):
                    clue = data[dr][dc]
                    if clue is None:
                        continue
                    incident = dot_to_incident[dr][dc]
                    forced = 0
                    possible = 0
                    for rr, cc in incident:
                        d = state['domains'][rr][cc]
                        if rr == r and cc == c:
                            d = orient
                        can_touch = False
                        can_avoid = False
                        if d & SLASH:
                            if orientation_touches_dot(rr, cc, SLASH, dr, dc):
                                can_touch = True
                            else:
                                can_avoid = True
                        if d & BACKSLASH:
                            if orientation_touches_dot(rr, cc, BACKSLASH, dr, dc):
                                can_touch = True
                            else:
                                can_avoid = True
                        if can_touch:
                            possible += 1
                        if can_touch and not can_avoid:
                            forced += 1
                    if forced <= clue <= possible:
                        # Favor orientations that tighten the range.
                        fit += (possible - forced)
                    else:
                        fit += 1000
            scores.append((fit, orient))
        scores.sort()
        return [orient for _, orient in scores]

    def dfs(state):
        if not propagate(state):
            return None
        if solved(state):
            return [[orientation_char(state['domains'][r][c]) for c in range(n)] for r in range(n)]

        cell = choose_branch_cell(state)
        if cell is None:
            return None
        r, c = cell

        for orient in order_orientations(state, r, c):
            nxt = clone_state(state)
            nxt['domains'][r][c] = orient
            ans = dfs(nxt)
            if ans is not None:
                return ans
        return None

    state = make_state()
    ans = dfs(state)
    return ans if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 2, 2, 3], [0, 0, 1, 1, 2, 2, 3], [0, 1, 1, 2, 2, 4, 3], [0, 0, 1, 2, 4, 4, 3], [5, 5, 5, 5, 4, 4, 3], [5, 6, 6, 5, 6, 4, 3], [5, 6, 6, 6, 6, 4, 3]], 'data': [[None, None, None, None, None, None, None], [1, 7, None, 2, None, None, 6], [2, None, None, 7, 6, None, None], [None, None, 5, None, 2, None, None], [None, None, 2, 3, None, None, 4], [5, None, None, 4, None, 3, 7], [None, None, None, None, None, None, None]]}

# Generalized Jigsaw Latin / Irregular Sudoku solver.
# Rules:
# - Fill 1..N exactly once in each row, column, and irregular region.

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(data)
    digits = tuple(range(1, n + 1))
    full_mask = (1 << n) - 1

    # Basic validation
    if any(len(row) != n for row in data) or any(len(row) != n for row in region):
        return "No Solution"

    # Build unit membership
    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]

    reg_to_cells = {}
    for r in range(n):
        for c in range(n):
            reg_to_cells.setdefault(region[r][c], []).append((r, c))
    regions = list(reg_to_cells.values())

    # Every region must have size N
    if len(regions) != n or any(len(cells) != n for cells in regions):
        return "No Solution"

    cell_region_index = {}
    region_ids_sorted = sorted(reg_to_cells)
    reg_index_of = {rid: i for i, rid in enumerate(region_ids_sorted)}
    region_cells = [reg_to_cells[rid] for rid in region_ids_sorted]
    for rid, cells in reg_to_cells.items():
        idx = reg_index_of[rid]
        for rc in cells:
            cell_region_index[rc] = idx

    # Peers
    peers = {}
    for r in range(n):
        for c in range(n):
            p = set(rows[r]) | set(cols[c]) | set(region_cells[cell_region_index[(r, c)]])
            p.discard((r, c))
            peers[(r, c)] = tuple(p)

    def bit(v):
        return 1 << (v - 1)

    def mask_to_values(mask):
        vals = []
        while mask:
            lsb = mask & -mask
            vals.append(lsb.bit_length())
            mask ^= lsb
        return vals

    # State
    board = [[0] * n for _ in range(n)]
    cand = [[full_mask] * n for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n

    # Assignment stack for reversible propagation
    stack = []

    def push_marker():
        stack.append(("MARK",))

    def rollback():
        while stack:
            item = stack.pop()
            if item[0] == "MARK":
                break
            kind = item[0]
            if kind == "A":
                _, r, c, old_board, old_cand, old_ru, old_cu, old_gu = item
                board[r][c] = old_board
                cand[r][c] = old_cand
                row_used[r] = old_ru
                col_used[c] = old_cu
                reg_used[cell_region_index[(r, c)]] = old_gu
            else:
                _, r, c, old_cand = item
                cand[r][c] = old_cand

    def assign(r, c, v, queue):
        b = bit(v)
        g = cell_region_index[(r, c)]
        if board[r][c] == v:
            return True
        if board[r][c] != 0 and board[r][c] != v:
            return False
        if not (cand[r][c] & b):
            return False
        if (row_used[r] & b) or (col_used[c] & b) or (reg_used[g] & b):
            return False

        stack.append(("A", r, c, board[r][c], cand[r][c], row_used[r], col_used[c], reg_used[g]))
        board[r][c] = v
        cand[r][c] = b
        row_used[r] |= b
        col_used[c] |= b
        reg_used[g] |= b
        queue.append((r, c))
        return True

    def eliminate_mask(r, c, remove_mask, queue):
        if board[r][c] != 0:
            if cand[r][c] & remove_mask:
                # assigned cell cannot lose its fixed value
                return False
            return True
        old = cand[r][c]
        new = old & ~remove_mask
        if new == old:
            return True
        if new == 0:
            return False
        stack.append(("C", r, c, old))
        cand[r][c] = new
        if new & (new - 1) == 0:
            if not assign(r, c, new.bit_length(), queue):
                return False
        return True

    def initial_setup():
        # Remove impossible values from all cells using givens and current unit usage
        queue = []
        for r in range(n):
            for c in range(n):
                val = data[r][c]
                if val is not None:
                    if not (1 <= val <= n):
                        return False
                    if not assign(r, c, val, queue):
                        return False

        # Initial candidate cleanup
        for r in range(n):
            for c in range(n):
                if board[r][c] == 0:
                    g = cell_region_index[(r, c)]
                    forbidden = row_used[r] | col_used[c] | reg_used[g]
                    new = full_mask & ~forbidden
                    if new == 0:
                        return False
                    cand[r][c] = new
        return propagate(queue)

    def hidden_singles_in_unit(cells, queue):
        placed_mask = 0
        for r, c in cells:
            if board[r][c]:
                placed_mask |= cand[r][c]
        missing = full_mask & ~placed_mask
        m = missing
        while m:
            lsb = m & -m
            target = None
            count = 0
            for r, c in cells:
                if board[r][c] == 0 and (cand[r][c] & lsb):
                    count += 1
                    target = (r, c)
                    if count > 1:
                        break
            if count == 0:
                return False
            if count == 1:
                if not assign(target[0], target[1], lsb.bit_length(), queue):
                    return False
            m ^= lsb
        return True

    def naked_subset_reduce(cells, queue):
        # Human-like subset rule:
        # if k cells in a unit share exactly k candidate values, remove them from others.
        buckets = {}
        unsolved = [(r, c) for r, c in cells if board[r][c] == 0]
        for r, c in unsolved:
            m = cand[r][c]
            bits = m.bit_count()
            if 2 <= bits <= 4:
                buckets.setdefault(m, []).append((r, c))
        for m, clist in buckets.items():
            k = m.bit_count()
            if len(clist) == k:
                for r, c in unsolved:
                    if (r, c) not in clist:
                        if not eliminate_mask(r, c, m, queue):
                            return False
        return True

    def fish_like_intersection(queue):
        # Intersection removal for row/region and col/region:
        # if all positions of a value in a row lie in one region, remove from rest of region;
        # if all positions of a value in a region lie in one row/col, remove from rest of row/col.
        for v in digits:
            b = bit(v)

            # Rows
            for r in range(n):
                pos = [(r, c) for c in range(n) if board[r][c] == 0 and (cand[r][c] & b)]
                if len(pos) >= 2:
                    regs = {cell_region_index[p] for p in pos}
                    if len(regs) == 1:
                        g = next(iter(regs))
                        for rr, cc in region_cells[g]:
                            if rr != r and board[rr][cc] == 0:
                                if not eliminate_mask(rr, cc, b, queue):
                                    return False

            # Cols
            for c in range(n):
                pos = [(r, c) for r in range(n) if board[r][c] == 0 and (cand[r][c] & b)]
                if len(pos) >= 2:
                    regs = {cell_region_index[p] for p in pos}
                    if len(regs) == 1:
                        g = next(iter(regs))
                        for rr, cc in region_cells[g]:
                            if cc != c and board[rr][cc] == 0:
                                if not eliminate_mask(rr, cc, b, queue):
                                    return False

            # Regions -> rows/cols
            for g, cells in enumerate(region_cells):
                pos = [(r, c) for r, c in cells if board[r][c] == 0 and (cand[r][c] & b)]
                if len(pos) >= 2:
                    rows_set = {r for r, _ in pos}
                    if len(rows_set) == 1:
                        r0 = next(iter(rows_set))
                        for cc in range(n):
                            if cell_region_index[(r0, cc)] != g and board[r0][cc] == 0:
                                if not eliminate_mask(r0, cc, b, queue):
                                    return False
                    cols_set = {c for _, c in pos}
                    if len(cols_set) == 1:
                        c0 = next(iter(cols_set))
                        for rr in range(n):
                            if cell_region_index[(rr, c0)] != g and board[rr][c0] == 0:
                                if not eliminate_mask(rr, c0, b, queue):
                                    return False
        return True

    def propagate(queue):
        while True:
            progress_before = len(stack)

            # Direct propagation from assigned cells
            while queue:
                r, c = queue.pop()
                val_mask = cand[r][c]
                for rr, cc in peers[(r, c)]:
                    if not eliminate_mask(rr, cc, val_mask, queue):
                        return False

            # Basic consistency + forced singles from unit deficits
            for r in range(n):
                if not hidden_singles_in_unit(rows[r], queue):
                    return False
            for c in range(n):
                if not hidden_singles_in_unit(cols[c], queue):
                    return False
            for cells in region_cells:
                if not hidden_singles_in_unit(cells, queue):
                    return False

            while queue:
                r, c = queue.pop()
                val_mask = cand[r][c]
                for rr, cc in peers[(r, c)]:
                    if not eliminate_mask(rr, cc, val_mask, queue):
                        return False

            # Human-style subset and intersection eliminations
            for r in range(n):
                if not naked_subset_reduce(rows[r], queue):
                    return False
            for c in range(n):
                if not naked_subset_reduce(cols[c], queue):
                    return False
            for cells in region_cells:
                if not naked_subset_reduce(cells, queue):
                    return False

            while queue:
                r, c = queue.pop()
                val_mask = cand[r][c]
                for rr, cc in peers[(r, c)]:
                    if not eliminate_mask(rr, cc, val_mask, queue):
                        return False

            if not fish_like_intersection(queue):
                return False

            while queue:
                r, c = queue.pop()
                val_mask = cand[r][c]
                for rr, cc in peers[(r, c)]:
                    if not eliminate_mask(rr, cc, val_mask, queue):
                        return False

            # Check unsolved cells have feasible candidates
            for r in range(n):
                for c in range(n):
                    if board[r][c] == 0:
                        g = cell_region_index[(r, c)]
                        allowed = full_mask & ~(row_used[r] | col_used[c] | reg_used[g])
                        if cand[r][c] & allowed != cand[r][c]:
                            if not eliminate_mask(r, c, cand[r][c] & ~allowed, queue):
                                return False
                        if cand[r][c] == 0:
                            return False

            if len(stack) == progress_before and not queue:
                return True

    def solved():
        for r in range(n):
            for c in range(n):
                if board[r][c] == 0:
                    return False
        return True

    def choose_branch_cell():
        # MRV + degree heuristic
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                if board[r][c] == 0:
                    m = cand[r][c]
                    cnt = m.bit_count()
                    peer_unsolved = sum(1 for rr, cc in peers[(r, c)] if board[rr][cc] == 0)
                    key = (cnt, -peer_unsolved)
                    if best is None or key < best_key:
                        best = (r, c)
                        best_key = key
                        if cnt == 2:
                            return best
        return best

    def search():
        if solved():
            return True

        cell = choose_branch_cell()
        if cell is None:
            return False
        r, c = cell

        # Least-constraining value ordering
        options = mask_to_values(cand[r][c])

        def impact(v):
            b = bit(v)
            score = 0
            for rr, cc in peers[(r, c)]:
                if board[rr][cc] == 0 and (cand[rr][cc] & b):
                    score += 1
            return score

        options.sort(key=impact)

        for v in options:
            push_marker()
            q = []
            if assign(r, c, v, q) and propagate(q) and search():
                return True
            rollback()
        return False

    if not initial_setup():
        return "No Solution"
    if not search():
        return "No Solution"
    return str(board)

