# Generalized irregular Latin-square / jigsaw sudoku solver.
# Uses:
# - bitmask candidates
# - immediate propagation on assignment
# - naked singles
# - hidden singles in every row/column/region
# - optional naked pairs in every unit
# - DFS only after strong deduction stalls


def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data) or any(len(row) != n for row in region):
        return "No Solution"

    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def mask_to_value(x):
        # assumes single bit
        return x.bit_length()

    # Build units
    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]

    reg_cells = {}
    for r in range(n):
        for c in range(n):
            reg_cells.setdefault(region[r][c], []).append((r, c))

    if len(reg_cells) != n:
        return "No Solution"
    if any(len(cells) != n for cells in reg_cells.values()):
        return "No Solution"

    reg_ids = sorted(reg_cells)
    regs = [reg_cells[rid] for rid in reg_ids]

    units = rows + cols + regs

    cell_to_units = {}
    for unit in units:
        for cell in unit:
            cell_to_units.setdefault(cell, []).append(unit)

    # Candidate grid
    cand = [[full_mask for _ in range(n)] for _ in range(n)]

    def peers_of(r, c):
        s = set()
        for unit in cell_to_units[(r, c)]:
            s.update(unit)
        s.discard((r, c))
        return s

    peers = {(r, c): peers_of(r, c) for r in range(n) for c in range(n)}

    def assign(cand_grid, r, c, vmask):
        # Force cell to a single candidate or given mask.
        current = cand_grid[r][c]
        if current == vmask:
            return True
        if not (current & vmask):
            return False
        other = current & ~vmask
        # eliminate all other values from the cell
        m = other
        while m:
            b = m & -m
            if not eliminate(cand_grid, r, c, b):
                return False
            m ^= b
        return True

    def eliminate(cand_grid, r, c, vmask):
        current = cand_grid[r][c]
        if not (current & vmask):
            return True
        newmask = current & ~vmask
        if newmask == 0:
            return False
        if newmask == current:
            return True
        cand_grid[r][c] = newmask

        # Naked single: remove value from all peers
        if newmask & (newmask - 1) == 0:
            for rr, cc in peers[(r, c)]:
                if not eliminate(cand_grid, rr, cc, newmask):
                    return False

        # Hidden single checks in affected units for the eliminated value and remaining values
        for unit in cell_to_units[(r, c)]:
            # For each digit, if it can appear in only one place, assign it there
            positions = {}
            for rr, cc in unit:
                m = cand_grid[rr][cc]
                mm = m
                while mm:
                    b = mm & -mm
                    positions[b] = positions.get(b, 0) + 1
                    mm ^= b
            for b, cnt in positions.items():
                if cnt == 0:
                    return False
                if cnt == 1:
                    for rr, cc in unit:
                        if cand_grid[rr][cc] & b:
                            if not assign(cand_grid, rr, cc, b):
                                return False
                            break

            # Contradiction: any digit absent from the unit
            seen = 0
            for rr, cc in unit:
                seen |= cand_grid[rr][cc]
            if seen != full_mask:
                return False

        return True

    def apply_hidden_singles(cand_grid):
        changed = False
        for unit in units:
            pos = {}
            for r, c in unit:
                m = cand_grid[r][c]
                mm = m
                while mm:
                    b = mm & -mm
                    pos.setdefault(b, []).append((r, c))
                    mm ^= b
            for b, cells in pos.items():
                if len(cells) == 1:
                    r, c = cells[0]
                    if cand_grid[r][c] != b:
                        if not assign(cand_grid, r, c, b):
                            return None
                        changed = True
            if len(pos) < n:
                return None
        return changed

    def apply_naked_pairs(cand_grid):
        changed = False
        for unit in units:
            pairs = {}
            for r, c in unit:
                m = cand_grid[r][c]
                if popcount(m) == 2:
                    pairs.setdefault(m, []).append((r, c))
            for pmask, cells in pairs.items():
                if len(cells) == 2:
                    for r, c in unit:
                        if (r, c) not in cells and (cand_grid[r][c] & pmask):
                            newm = cand_grid[r][c] & ~pmask
                            if newm == 0:
                                return None
                            if newm != cand_grid[r][c]:
                                cand_grid[r][c] = newm
                                changed = True
        return changed

    def propagate(cand_grid):
        while True:
            progress = False

            # Sanity checks + naked singles push
            for r in range(n):
                for c in range(n):
                    m = cand_grid[r][c]
                    if m == 0:
                        return False
                    if m & (m - 1) == 0:
                        for rr, cc in peers[(r, c)]:
                            if cand_grid[rr][cc] & m:
                                if not eliminate(cand_grid, rr, cc, m):
                                    return False

            hs = apply_hidden_singles(cand_grid)
            if hs is None:
                return False
            progress |= hs

            np = apply_naked_pairs(cand_grid)
            if np is None:
                return False
            progress |= np

            # Re-check unit coverage
            for unit in units:
                union_mask = 0
                seen_singles = 0
                for r, c in unit:
                    m = cand_grid[r][c]
                    union_mask |= m
                    if m & (m - 1) == 0:
                        if seen_singles & m:
                            return False
                        seen_singles |= m
                if union_mask != full_mask:
                    return False

            if not progress:
                return True

    # Initialize from givens
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                if not assign(cand, r, c, bit(v)):
                    return "No Solution"

    if not propagate(cand):
        return "No Solution"

    def solved(cand_grid):
        return all(cand_grid[r][c] & (cand_grid[r][c] - 1) == 0 for r in range(n) for c in range(n))

    def copy_grid(cand_grid):
        return [row[:] for row in cand_grid]

    def choose_branch_cell(cand_grid):
        # Most constrained cell, tie-broken by strongest peer pressure
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                m = cand_grid[r][c]
                pc = popcount(m)
                if pc > 1:
                    peer_entropy = sum(popcount(cand_grid[rr][cc]) for rr, cc in peers[(r, c)])
                    key = (pc, -peer_entropy)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def search(cand_grid):
        if solved(cand_grid):
            return cand_grid

        cell = choose_branch_cell(cand_grid)
        if cell is None:
            return None
        r, c = cell
        m = cand_grid[r][c]

        # Least-constraining value order
        options = []
        mm = m
        while mm:
            b = mm & -mm
            impact = 0
            for rr, cc in peers[(r, c)]:
                if cand_grid[rr][cc] & b:
                    impact += 1
            options.append((impact, b))
            mm ^= b
        options.sort()

        for _, b in options:
            nxt = copy_grid(cand_grid)
            if assign(nxt, r, c, b) and propagate(nxt):
                res = search(nxt)
                if res is not None:
                    return res
        return None

    result = search(cand)
    if result is None:
        return "No Solution"

    solved_grid = [[mask_to_value(result[r][c]) for c in range(n)] for r in range(n)]
    return solved_grid


