from copy import deepcopy

def solve(observation):
    data = observation["data"]
    n = len(data)
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def is_single(x):
        return x and (x & (x - 1)) == 0

    def mask_to_values(mask):
        vals = []
        while mask:
            b = mask & -mask
            vals.append(b.bit_length())
            mask ^= b
        return vals

    def single_value(mask):
        return mask.bit_length()

    # Build adjacency map from midpoint coordinates.
    dot_edges = set()
    for r, c in observation["adjacent"]:
        if abs(r - round(r)) < 1e-9:
            rr = int(round(r))
            cc = int(c - 0.5)
            if 0 <= rr < n and 0 <= cc < n - 1:
                a = (rr, cc)
                b = (rr, cc + 1)
                dot_edges.add(tuple(sorted((a, b))))
        else:
            rr = int(r - 0.5)
            cc = int(round(c))
            if 0 <= rr < n - 1 and 0 <= cc < n:
                a = (rr, cc)
                b = (rr + 1, cc)
                dot_edges.add(tuple(sorted((a, b))))

    neighbors = {(r, c): [] for r in range(n) for c in range(n)}
    all_orth_edges = []
    for r in range(n):
        for c in range(n):
            if c + 1 < n:
                a, b = (r, c), (r, c + 1)
                has_dot = tuple(sorted((a, b))) in dot_edges
                neighbors[a].append((b, has_dot))
                neighbors[b].append((a, has_dot))
                all_orth_edges.append((a, b, has_dot))
            if r + 1 < n:
                a, b = (r, c), (r + 1, c)
                has_dot = tuple(sorted((a, b))) in dot_edges
                neighbors[a].append((b, has_dot))
                neighbors[b].append((a, has_dot))
                all_orth_edges.append((a, b, has_dot))

    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    peers = {}
    for r in range(n):
        for c in range(n):
            s = set(rows[r] + cols[c])
            s.remove((r, c))
            peers[(r, c)] = tuple(s)

    consec_masks = [0] * (n + 1)
    for v in range(1, n + 1):
        m = 0
        if v > 1:
            m |= bit(v - 1)
        if v < n:
            m |= bit(v + 1)
        consec_masks[v] = m

    def revise_pair(dom_a, dom_b, has_dot):
        new_a = 0
        if has_dot:
            for v in mask_to_values(dom_a):
                if consec_masks[v] & dom_b:
                    new_a |= bit(v)
        else:
            for v in mask_to_values(dom_a):
                supported = False
                mb = dom_b
                while mb:
                    bb = mb & -mb
                    u = bb.bit_length()
                    if abs(v - u) != 1:
                        supported = True
                        break
                    mb ^= bb
                if supported:
                    new_a |= bit(v)
        return new_a

    def assign(domains, r, c, value_mask, queue):
        old = domains[r][c]
        new = old & value_mask
        if new == 0:
            return False
        if new == old:
            return True
        domains[r][c] = new
        queue.append((r, c))
        return True

    def propagate(domains):
        queue = []

        # Initial queue: all cells.
        for r in range(n):
            for c in range(n):
                queue.append((r, c))

        while True:
            while queue:
                r, c = queue.pop()
                mask = domains[r][c]
                if mask == 0:
                    return False

                # If single, eliminate from Latin peers.
                if is_single(mask):
                    for pr, pc in peers[(r, c)]:
                        pm = domains[pr][pc]
                        nm = pm & ~mask
                        if nm == 0:
                            return False
                        if nm != pm:
                            domains[pr][pc] = nm
                            queue.append((pr, pc))

                # Adjacency revision in both directions.
                for (nr, nc), has_dot in neighbors[(r, c)]:
                    a = domains[r][c]
                    b = domains[nr][nc]
                    na = revise_pair(a, b, has_dot)
                    if na == 0:
                        return False
                    if na != a:
                        domains[r][c] = na
                        a = na
                        queue.append((r, c))
                    nb = revise_pair(b, a, has_dot)
                    if nb == 0:
                        return False
                    if nb != b:
                        domains[nr][nc] = nb
                        queue.append((nr, nc))

            changed = False

            # Human-like Latin deductions: used numbers and hidden singles in rows/cols.
            for unit in rows + cols:
                used = 0
                singles = {}
                for r, c in unit:
                    m = domains[r][c]
                    if is_single(m):
                        if m in singles:
                            return False
                        singles[m] = (r, c)
                        used |= m

                # Remove already fixed values from non-single cells.
                for r, c in unit:
                    m = domains[r][c]
                    if not is_single(m):
                        nm = m & ~used
                        if nm == 0:
                            return False
                        if nm != m:
                            domains[r][c] = nm
                            queue.append((r, c))
                            changed = True

                # Hidden singles.
                support = [0] * (n + 1)
                support_cell = [None] * (n + 1)
                for r, c in unit:
                    m = domains[r][c]
                    mm = m
                    while mm:
                        b = mm & -mm
                        v = b.bit_length()
                        support[v] += 1
                        support_cell[v] = (r, c)
                        mm ^= b
                for v in range(1, n + 1):
                    if support[v] == 0:
                        return False
                    if support[v] == 1:
                        rr, cc = support_cell[v]
                        if domains[rr][cc] != bit(v):
                            domains[rr][cc] = bit(v)
                            queue.append((rr, cc))
                            changed = True

            # Additional adjacency extremal reasoning:
            # On a dot, if one side cannot be low/high enough to support, prune.
            for (a, b, has_dot) in all_orth_edges:
                if not has_dot:
                    continue
                ar, ac = a
                br, bc = b
                am = domains[ar][ac]
                bm = domains[br][bc]
                na = revise_pair(am, bm, True)
                nb = revise_pair(bm, am, True)
                if na == 0 or nb == 0:
                    return False
                if na != am:
                    domains[ar][ac] = na
                    queue.append((ar, ac))
                    changed = True
                if nb != bm:
                    domains[br][bc] = nb
                    queue.append((br, bc))
                    changed = True

            if queue:
                continue
            if not changed:
                break

        return True

    def solved(domains):
        return all(is_single(domains[r][c]) for r in range(n) for c in range(n))

    def contradiction_score(domains, r, c, vmask):
        # Lower is better; estimate by resulting domain pressure on peers and neighbors.
        score = 0
        v = single_value(vmask)
        for pr, pc in peers[(r, c)]:
            pm = domains[pr][pc]
            if pm & vmask:
                score += 1
        for (nr, nc), has_dot in neighbors[(r, c)]:
            nm = domains[nr][nc]
            if has_dot:
                score += popcount(nm & consec_masks[v])
            else:
                cnt = 0
                mm = nm
                while mm:
                    b = mm & -mm
                    u = b.bit_length()
                    if abs(v - u) != 1:
                        cnt += 1
                    mm ^= b
                score += cnt
        return score

    def choose_cell(domains):
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                m = domains[r][c]
                pc = popcount(m)
                if pc <= 1:
                    continue
                deg = len(peers[(r, c)]) + len(neighbors[(r, c)])
                key = (pc, -deg)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (r, c)
        return best

    def search(domains):
        if not propagate(domains):
            return None
        if solved(domains):
            return domains

        r, c = choose_cell(domains)
        m = domains[r][c]
        values = [bit(v) for v in mask_to_values(m)]
        values.sort(key=lambda vm: contradiction_score(domains, r, c, vm))

        for vm in values:
            new_domains = [row[:] for row in domains]
            new_domains[r][c] = vm
            result = search(new_domains)
            if result is not None:
                return result
        return None

    domains = [[full for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                domains[r][c] = bit(data[r][c])

    result = search(domains)
    if result is None:
        return "No Solution"

    grid = [[single_value(result[r][c]) for c in range(n)] for r in range(n)]
    return str(grid)

