from collections import defaultdict, deque

ALL012 = 0b111
ALL12 = 0b110

def mask_values(mask):
    return [v for v in (0, 1, 2) if mask & (1 << v)]

def is_single(mask):
    return mask in (1, 2, 4)

def single_value(mask):
    if mask == 1:
        return 0
    if mask == 2:
        return 1
    if mask == 4:
        return 2
    return None

def min_value(mask):
    if mask & 1:
        return 0
    if mask & 2:
        return 1
    return 2

def max_value(mask):
    if mask & 4:
        return 2
    if mask & 2:
        return 1
    return 0

def edge_key(a, b):
    return (a, b) if a < b else (b, a)

def build_model(data):
    n = len(data)
    islands = []
    idx_of = {}
    for r in range(n):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                idx_of[(r, c)] = len(islands)
                islands.append(((r, c), data[r][c]))

    edges = []
    incident = [[] for _ in islands]
    edge_lookup = {}

    # Horizontal visibility
    for r in range(n):
        cols = [c for c in range(len(data[r])) if data[r][c] is not None]
        for i in range(len(cols) - 1):
            c1, c2 = cols[i], cols[i + 1]
            a = idx_of[(r, c1)]
            b = idx_of[(r, c2)]
            eidx = len(edges)
            edges.append({
                'a': a, 'b': b, 'ori': 'H',
                'r': r, 'c1': c1, 'c2': c2,
                'cross': []
            })
            incident[a].append(eidx)
            incident[b].append(eidx)
            edge_lookup[edge_key((r, c1), (r, c2))] = eidx

    # Vertical visibility
    cols_range = max(len(row) for row in data)
    for c in range(cols_range):
        rows = [r for r in range(n) if c < len(data[r]) and data[r][c] is not None]
        for i in range(len(rows) - 1):
            r1, r2 = rows[i], rows[i + 1]
            a = idx_of[(r1, c)]
            b = idx_of[(r2, c)]
            eidx = len(edges)
            edges.append({
                'a': a, 'b': b, 'ori': 'V',
                'c': c, 'r1': r1, 'r2': r2,
                'cross': []
            })
            incident[a].append(eidx)
            incident[b].append(eidx)
            edge_lookup[edge_key((r1, c), (r2, c))] = eidx

    # Crossings
    horiz = [i for i, e in enumerate(edges) if e['ori'] == 'H']
    vert = [i for i, e in enumerate(edges) if e['ori'] == 'V']
    for hi in horiz:
        eh = edges[hi]
        for vi in vert:
            ev = edges[vi]
            if eh['c1'] < ev['c'] < eh['c2'] and ev['r1'] < eh['r'] < ev['r2']:
                eh['cross'].append(vi)
                ev['cross'].append(hi)

    return islands, edges, incident

def possible_tuples_for_island(target, edge_masks):
    vals_lists = [mask_values(m) for m in edge_masks]
    out = []

    def rec(i, acc, tup):
        if i == len(vals_lists):
            if acc == target:
                out.append(tuple(tup))
            return
        rem_min = 0
        rem_max = 0
        for j in range(i + 1, len(vals_lists)):
            rem_min += min_value(edge_masks[j])
            rem_max += max_value(edge_masks[j])
        for v in vals_lists[i]:
            s = acc + v
            if s + rem_min <= target <= s + rem_max:
                tup.append(v)
                rec(i + 1, s, tup)
                tup.pop()

    rec(0, 0, [])
    return out

def graph_connected(num_nodes, edge_indices, edges):
    if num_nodes == 0:
        return True
    g = [[] for _ in range(num_nodes)]
    for ei in edge_indices:
        e = edges[ei]
        g[e['a']].append(e['b'])
        g[e['b']].append(e['a'])
    seen = [False] * num_nodes
    q = deque([0])
    seen[0] = True
    while q:
        u = q.popleft()
        for v in g[u]:
            if not seen[v]:
                seen[v] = True
                q.append(v)
    return all(seen)

def forced_components(num_nodes, domains, edges):
    parent = list(range(num_nodes))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    for i, e in enumerate(edges):
        if not (domains[i] & 1):  # forced positive
            union(e['a'], e['b'])

    comps = defaultdict(list)
    for i in range(num_nodes):
        comps[find(i)].append(i)
    return list(comps.values())

def propagate(domains, islands, edges, incident):
    num_nodes = len(islands)
    changed = True
    while changed:
        changed = False

        # Crossing propagation
        for i, e in enumerate(edges):
            if not (domains[i] & 1):  # forced positive
                for j in e['cross']:
                    nd = domains[j] & 1
                    if nd == 0:
                        return None
                    if nd != domains[j]:
                        domains[j] = nd
                        changed = True

        # Island sum propagation
        for node_idx, ((r, c), target) in enumerate(islands):
            inc = incident[node_idx]
            masks = [domains[ei] for ei in inc]

            smin = sum(min_value(m) for m in masks)
            smax = sum(max_value(m) for m in masks)
            if target < smin or target > smax:
                return None

            tuples = possible_tuples_for_island(target, masks)
            if not tuples:
                return None

            allowed = [0] * len(inc)
            for tup in tuples:
                for k, v in enumerate(tup):
                    allowed[k] |= (1 << v)

            for k, ei in enumerate(inc):
                nd = domains[ei] & allowed[k]
                if nd == 0:
                    return None
                if nd != domains[ei]:
                    domains[ei] = nd
                    changed = True

            # Human-like forcing by exact deficits
            mins = [min_value(domains[ei]) for ei in inc]
            maxs = [max_value(domains[ei]) for ei in inc]
            total_min = sum(mins)
            total_max = sum(maxs)
            need_above_min = target - total_min
            spare_below_max = total_max - target

            for k, ei in enumerate(inc):
                other_max_extra = sum(maxs[j] - mins[j] for j in range(len(inc)) if j != k)
                forced_min = mins[k] + max(0, need_above_min - other_max_extra)

                other_min_lack = sum(maxs[j] - mins[j] for j in range(len(inc)) if j != k)
                forced_max = maxs[k] - max(0, spare_below_max - other_min_lack)

                allowed_mask = 0
                for v in mask_values(domains[ei]):
                    if forced_min <= v <= forced_max:
                        allowed_mask |= (1 << v)
                if allowed_mask == 0:
                    return None
                if allowed_mask != domains[ei]:
                    domains[ei] = allowed_mask
                    changed = True

        # Possible-positive graph must stay connected
        possible_edges = [i for i, m in enumerate(domains) if m & 0b110]
        if not graph_connected(num_nodes, possible_edges, edges):
            return None

        # No closed forced component unless whole graph
        comps = forced_components(num_nodes, domains, edges)
        if len(comps) > 1:
            for comp in comps:
                comp_set = set(comp)
                has_possible_out = False
                for ei, e in enumerate(edges):
                    a_in = e['a'] in comp_set
                    b_in = e['b'] in comp_set
                    if a_in ^ b_in:
                        if domains[ei] & 0b110:
                            has_possible_out = True
                            break
                if not has_possible_out:
                    return None

    return domains

def solved(domains):
    return all(is_single(m) for m in domains)

def exact_check(domains, islands, edges, incident):
    # Sum exact
    for node_idx, (_, target) in enumerate(islands):
        total = sum(single_value(domains[ei]) for ei in incident[node_idx])
        if total != target:
            return False
    # No crossing positives
    for i, e in enumerate(edges):
        vi = single_value(domains[i])
        if vi > 0:
            for j in e['cross']:
                if single_value(domains[j]) > 0:
                    return False
    # Connected
    pos_edges = [i for i, m in enumerate(domains) if single_value(m) > 0]
    return graph_connected(len(islands), pos_edges, edges)

def choose_branch_edge(domains, islands, edges, incident):
    best = None
    best_score = None
    for i, m in enumerate(domains):
        vals = mask_values(m)
        if len(vals) <= 1:
            continue
        a = edges[i]['a']
        b = edges[i]['b']
        rem_a = islands[a][1] - sum(min_value(domains[ei]) for ei in incident[a])
        rem_b = islands[b][1] - sum(min_value(domains[ei]) for ei in incident[b])
        score = (len(vals), -(rem_a + rem_b), -len(edges[i]['cross']))
        if best is None or score < best_score:
            best = i
            best_score = score
    return best

def search(domains, islands, edges, incident):
    domains = propagate(domains[:], islands, edges, incident)
    if domains is None:
        return None
    if solved(domains):
        return domains if exact_check(domains, islands, edges, incident) else None

    ei = choose_branch_edge(domains, islands, edges, incident)
    if ei is None:
        return None

    vals = mask_values(domains[ei])

    # Prefer human-like stronger commitments first: 2, then 1, then 0 when possible
    vals.sort(key=lambda v: {2: 0, 1: 1, 0: 2}[v])

    for v in vals:
        nd = domains[:]
        nd[ei] = (1 << v)
        res = search(nd, islands, edges, incident)
        if res is not None:
            return res
    return None

def format_answer(domains, islands, edges):
    ans = {}
    for i, m in enumerate(domains):
        v = single_value(m)
        if v and v > 0:
            a = islands[edges[i]['a']][0]
            b = islands[edges[i]['b']][0]
            k = edge_key(a, b)
            ans[k] = v
    return ans

def solve(observation):
    data = observation['data']
    islands, edges, incident = build_model(data)
    if not islands:
        return "{}"
    domains = [ALL012] * len(edges)
    res = search(domains, islands, edges, incident)
    if res is None:
        return "No Solution"
    return str(format_answer(res, islands, edges))

if __name__ == "__main__":
    print(solve(OBSERVATION))

