# Diagonal puzzle solver:
# - one diagonal per cell ('/' or '\')
# - numbered dots count incident diagonals
# - no closed loop anywhere in the diagonal graph

def solve(observation):
    data = observation["data"]
    H = len(data) - 1
    W = len(data[0]) - 1
    if H != W:
        return "No Solution"
    N = H

    num_cells = N * N
    num_vertices = (N + 1) * (N + 1)

    SLASH = 1       # '/'
    BACKSLASH = 2   # '\'
    BOTH = 3

    def cell_id(r, c):
        return r * N + c

    def vid(r, c):
        return r * (N + 1) + c

    # Endpoints for each cell/orientation.
    # val == SLASH => (r,c+1) -- (r+1,c)
    # val == BACKSLASH => (r,c) -- (r+1,c+1)
    edge_of = [[None, None, None] for _ in range(num_cells)]
    for r in range(N):
        for c in range(N):
            i = cell_id(r, c)
            edge_of[i][SLASH] = (vid(r, c + 1), vid(r + 1, c))
            edge_of[i][BACKSLASH] = (vid(r, c), vid(r + 1, c + 1))

    # For each clue vertex, list of (cell, touching_value)
    clues = []
    cell_to_clues = [[] for _ in range(num_cells)]
    for vr in range(N + 1):
        for vc in range(N + 1):
            clue = data[vr][vc]
            if clue is None:
                continue
            inc = []

            # NW cell: '\' touches (vr,vc)
            if vr - 1 >= 0 and vc - 1 >= 0:
                i = cell_id(vr - 1, vc - 1)
                inc.append((i, BACKSLASH))
                cell_to_clues[i].append(len(clues))

            # NE cell: '/' touches (vr,vc)
            if vr - 1 >= 0 and vc < N:
                i = cell_id(vr - 1, vc)
                inc.append((i, SLASH))
                cell_to_clues[i].append(len(clues))

            # SW cell: '/' touches (vr,vc)
            if vr < N and vc - 1 >= 0:
                i = cell_id(vr, vc - 1)
                inc.append((i, SLASH))
                cell_to_clues[i].append(len(clues))

            # SE cell: '\' touches (vr,vc)
            if vr < N and vc < N:
                i = cell_id(vr, vc)
                inc.append((i, BACKSLASH))
                cell_to_clues[i].append(len(clues))

            clues.append((clue, inc))

    class RollbackUF:
        def __init__(self, n):
            self.parent = list(range(n))
            self.size = [1] * n
            self.stack = []

        def find(self, x):
            while self.parent[x] != x:
                x = self.parent[x]
            return x

        def connected(self, a, b):
            return self.find(a) == self.find(b)

        def union(self, a, b):
            ra = self.find(a)
            rb = self.find(b)
            if ra == rb:
                return False
            if self.size[ra] < self.size[rb]:
                ra, rb = rb, ra
            self.stack.append((rb, self.parent[rb], ra, self.size[ra]))
            self.parent[rb] = ra
            self.size[ra] += self.size[rb]
            return True

        def mark(self):
            return len(self.stack)

        def rollback(self, mark):
            while len(self.stack) > mark:
                rb, old_parent_rb, ra, old_size_ra = self.stack.pop()
                self.parent[rb] = old_parent_rb
                self.size[ra] = old_size_ra

    uf = RollbackUF(num_vertices)
    domain = [BOTH] * num_cells
    dom_stack = []

    def dom_count(mask):
        return 2 if mask == BOTH else 1

    def dom_values(mask):
        if mask == BOTH:
            return (SLASH, BACKSLASH)
        return (SLASH,) if mask == SLASH else (BACKSLASH,)

    def mark():
        return (len(dom_stack), uf.mark())

    def rollback(state):
        dom_mark, uf_mark = state
        uf.rollback(uf_mark)
        while len(dom_stack) > dom_mark:
            i, old = dom_stack.pop()
            domain[i] = old

    def force_domain(i, new_mask):
        old = domain[i]
        if old == new_mask:
            return True
        if old & new_mask == 0:
            return False
        dom_stack.append((i, old))
        domain[i] = new_mask
        if old == BOTH and new_mask != BOTH:
            a, b = edge_of[i][new_mask]
            if uf.connected(a, b):
                return False
            if not uf.union(a, b):
                return False
        return True

    def remove_value(i, val):
        old = domain[i]
        if not (old & val):
            return True
        new_mask = old & (~val)
        if new_mask == 0:
            return False
        return force_domain(i, new_mask)

    def clue_status(clue_idx):
        target, inc = clues[clue_idx]
        fixed = 0
        possible = 0
        undecided_touch = []
        undecided_notouch = []
        for i, touch_val in inc:
            d = domain[i]
            if d == BOTH:
                possible += 1
                undecided_touch.append((i, touch_val))
                undecided_notouch.append((i, SLASH if touch_val == BACKSLASH else BACKSLASH))
            elif d == touch_val:
                fixed += 1
                possible += 1
            else:
                pass
        return target, fixed, possible, undecided_touch, undecided_notouch

    def propagate():
        changed = True
        while changed:
            changed = False

            # Exact-count propagation on every clue.
            for clue_idx in range(len(clues)):
                target, fixed, possible, undecided_touch, undecided_notouch = clue_status(clue_idx)

                if fixed > target or possible < target:
                    return False

                need = target - fixed
                free = len(undecided_touch)

                if need < 0 or need > free:
                    return False

                # If clue already satisfied, all remaining incident cells must avoid this vertex.
                if need == 0:
                    for i, touch_val in undecided_touch:
                        before = domain[i]
                        if not remove_value(i, touch_val):
                            return False
                        if domain[i] != before:
                            changed = True

                # If all remaining undecided incidents must touch this vertex, force them.
                elif need == free:
                    for i, touch_val in undecided_touch:
                        before = domain[i]
                        if not force_domain(i, touch_val):
                            return False
                        if domain[i] != before:
                            changed = True

            # Global "no premature loop" propagation:
            # if one orientation of a cell would connect already-connected endpoints, remove it.
            for i in range(num_cells):
                d = domain[i]
                if d == BOTH:
                    bad = 0
                    a, b = edge_of[i][SLASH]
                    if uf.connected(a, b):
                        bad |= SLASH
                    a, b = edge_of[i][BACKSLASH]
                    if uf.connected(a, b):
                        bad |= BACKSLASH
                    if bad:
                        before = domain[i]
                        if not force_domain(i, d & (~bad)):
                            return False
                        if domain[i] != before:
                            changed = True
                else:
                    val = d
                    a, b = edge_of[i][val]
                    if uf.connected(a, b):
                        return False

        return True

    def choose_cell():
        best_i = -1
        best_key = None
        for i in range(num_cells):
            if domain[i] != BOTH:
                continue

            r = i // N
            c = i % N

            # Heuristic:
            # 1) more constrained by nearby clues
            # 2) more likely to create cycles
            clue_pressure = 0
            clue_slack = 0
            for clue_idx in cell_to_clues[i]:
                target, fixed, possible, undecided_touch, _ = clue_status(clue_idx)
                need = target - fixed
                free = len(undecided_touch)
                clue_pressure += 1
                clue_slack += abs(free - need) + abs(need)

            cyc = 0
            for val in (SLASH, BACKSLASH):
                a, b = edge_of[i][val]
                if uf.connected(a, b):
                    cyc += 1

            key = (-clue_pressure, clue_slack, -cyc, min(r, N - 1 - r, c, N - 1 - c), r, c)
            if best_key is None or key < best_key:
                best_key = key
                best_i = i
        return best_i

    def branch_order(i):
        # Prefer the orientation that is more demanded by adjacent clues.
        score = {SLASH: 0, BACKSLASH: 0}
        for clue_idx in cell_to_clues[i]:
            target, fixed, possible, undecided_touch, _ = clue_status(clue_idx)
            need = target - fixed
            free = len(undecided_touch)
            for cell_j, touch_val in undecided_touch:
                if cell_j == i:
                    # Stronger if clue is near saturation.
                    if free > 0:
                        score[touch_val] += 10 * need - free
        vals = [SLASH, BACKSLASH]
        vals.sort(key=lambda v: (-score[v], v))
        return vals

    def dfs():
        if not propagate():
            return None

        i = choose_cell()
        if i == -1:
            # All cells assigned and no loops formed among forced edges by construction.
            ans = []
            for r in range(N):
                row = []
                for c in range(N):
                    d = domain[cell_id(r, c)]
                    if d == SLASH:
                        row.append('/')
                    elif d == BACKSLASH:
                        row.append('\\')
                    else:
                        return None
                ans.append(row)
            return ans

        for val in branch_order(i):
            state = mark()
            if force_domain(i, val):
                res = dfs()
                if res is not None:
                    return res
            rollback(state)

        return None

    result = dfs()
    return result if result is not None else "No Solution"


