# Binary Puzzle / Takuzu solver
# Uses human-like line reasoning encoded as domain propagation:
# - each row/column must be a valid balanced, no-triple pattern
# - given clues restrict line domains
# - row/column domains cross-filter each cell until fixpoint
# - uniqueness of rows and columns is propagated when a line is fixed
# - backtracking only on the smallest remaining domain

from functools import lru_cache

B = 1
W = 0


def _char_to_bit(ch):
    if ch == 'B':
        return B
    if ch == 'W':
        return W
    return None


def _bit_to_char(bit):
    return 'B' if bit == B else 'W'


@lru_cache(maxsize=None)
def generate_valid_patterns(n):
    target = n // 2
    out = []

    def rec(pos, prev1, prev2, count_b, bits):
        rem = n - pos
        count_w = pos - count_b

        if count_b > target or count_w > target:
            return
        if count_b + rem < target or count_w + rem < target:
            return

        if pos == n:
            if count_b == target and count_w == target:
                out.append(bits)
            return

        for bit in (W, B):
            if pos >= 2 and prev1 == prev2 == bit:
                continue
            rec(pos + 1, prev2, bit, count_b + (bit == B), (bits << 1) | bit)

    rec(0, -1, -1, 0, 0)
    return tuple(out)


def pattern_bit(pattern, n, idx):
    return (pattern >> (n - 1 - idx)) & 1


def pattern_matches_givens(pattern, givens_line, n):
    for i, v in enumerate(givens_line):
        if v is not None and pattern_bit(pattern, n, i) != v:
            return False
    return True


def build_initial_domains(grid):
    n = len(grid)
    valid = generate_valid_patterns(n)

    row_domains = []
    for r in range(n):
        givens = [_char_to_bit(x) for x in grid[r]]
        dom = {p for p in valid if pattern_matches_givens(p, givens, n)}
        row_domains.append(dom)

    col_domains = []
    for c in range(n):
        givens = [_char_to_bit(grid[r][c]) for r in range(n)]
        dom = {p for p in valid if pattern_matches_givens(p, givens, n)}
        col_domains.append(dom)

    return row_domains, col_domains


def domains_cell_values_row(row_domain, n, c):
    vals = 0
    for p in row_domain:
        vals |= 1 << pattern_bit(p, n, c)
        if vals == 0b11:
            break
    return vals


def domains_cell_values_col(col_domain, n, r):
    vals = 0
    for p in col_domain:
        vals |= 1 << pattern_bit(p, n, r)
        if vals == 0b11:
            break
    return vals


def propagate(row_domains, col_domains, n):
    changed = True
    while changed:
        changed = False

        # Contradiction check
        for dom in row_domains:
            if not dom:
                return False
        for dom in col_domains:
            if not dom:
                return False

        # Cell-wise arc consistency between row and column domains
        for r in range(n):
            row_dom = row_domains[r]
            for c in range(n):
                rv = domains_cell_values_row(row_dom, n, c)
                cv = domains_cell_values_col(col_domains[c], n, r)
                allowed = rv & cv
                if allowed == 0:
                    return False

                if rv != allowed:
                    new_row = {p for p in row_dom if ((1 << pattern_bit(p, n, c)) & allowed)}
                    if not new_row:
                        return False
                    if len(new_row) != len(row_dom):
                        row_domains[r] = new_row
                        row_dom = new_row
                        changed = True

                col_dom = col_domains[c]
                if cv != allowed:
                    new_col = {p for p in col_dom if ((1 << pattern_bit(p, n, r)) & allowed)}
                    if not new_col:
                        return False
                    if len(new_col) != len(col_dom):
                        col_domains[c] = new_col
                        changed = True

        # Uniqueness propagation for fixed rows
        fixed_rows = {}
        for i, dom in enumerate(row_domains):
            if len(dom) == 1:
                p = next(iter(dom))
                if p in fixed_rows:
                    return False
                fixed_rows[p] = i
        if fixed_rows:
            fixed_patterns = set(fixed_rows)
            for i, dom in enumerate(row_domains):
                if len(dom) > 1:
                    new_dom = dom - fixed_patterns
                    if not new_dom:
                        return False
                    if len(new_dom) != len(dom):
                        row_domains[i] = new_dom
                        changed = True

        fixed_cols = {}
        for i, dom in enumerate(col_domains):
            if len(dom) == 1:
                p = next(iter(dom))
                if p in fixed_cols:
                    return False
                fixed_cols[p] = i
        if fixed_cols:
            fixed_patterns = set(fixed_cols)
            for i, dom in enumerate(col_domains):
                if len(dom) > 1:
                    new_dom = dom - fixed_patterns
                    if not new_dom:
                        return False
                    if len(new_dom) != len(dom):
                        col_domains[i] = new_dom
                        changed = True

    return True


def is_solved(row_domains, col_domains):
    return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)


def clone_domains(domains):
    return [set(d) for d in domains]


def extract_grid(row_domains, n):
    grid = []
    for r in range(n):
        p = next(iter(row_domains[r]))
        grid.append([_bit_to_char(pattern_bit(p, n, c)) for c in range(n)])
    return grid


def verify_solution(grid):
    n = len(grid)
    target = n // 2

    # rows
    rows = []
    for r in range(n):
        row = grid[r]
        if row.count('B') != target or row.count('W') != target:
            return False
        for i in range(n - 2):
            if row[i] == row[i + 1] == row[i + 2]:
                return False
        t = tuple(row)
        if t in rows:
            return False
        rows.append(t)

    # cols
    cols = []
    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if col.count('B') != target or col.count('W') != target:
            return False
        for i in range(n - 2):
            if col[i] == col[i + 1] == col[i + 2]:
                return False
        t = tuple(col)
        if t in cols:
            return False
        cols.append(t)

    return True


def search(row_domains, col_domains, n):
    if not propagate(row_domains, col_domains, n):
        return None

    if is_solved(row_domains, col_domains):
        grid = extract_grid(row_domains, n)
        return grid if verify_solution(grid) else None

    # Choose the most constrained unresolved line among rows and columns
    best_is_row = True
    best_idx = -1
    best_size = 10**9

    for i, dom in enumerate(row_domains):
        s = len(dom)
        if 1 < s < best_size:
            best_size = s
            best_idx = i
            best_is_row = True

    for i, dom in enumerate(col_domains):
        s = len(dom)
        if 1 < s < best_size:
            best_size = s
            best_idx = i
            best_is_row = False

    if best_idx == -1:
        return None

    domain = sorted(row_domains[best_idx] if best_is_row else col_domains[best_idx])

    for p in domain:
        new_rows = clone_domains(row_domains)
        new_cols = clone_domains(col_domains)
        if best_is_row:
            new_rows[best_idx] = {p}
        else:
            new_cols[best_idx] = {p}
        ans = search(new_rows, new_cols, n)
        if ans is not None:
            return ans

    return None


def solve(observation):
    grid = observation['data']
    n = len(grid)

    if n == 0 or any(len(row) != n for row in grid) or n % 2 != 0:
        return "No Solution"

    row_domains, col_domains = build_initial_domains(grid)
    ans = search(row_domains, col_domains, n)
    return ans if ans is not None else "No Solution"


