# Akari / Light Up solver with strong deduction + constrained search.
# Board encoding:
#   None : white cell
#   -1   : unnumbered black cell
#   0..4 : numbered black cell
#
# Output encoding:
#   'B'  : bulb
#   None : every non-bulb cell

def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0]) if n else 0

    white_cells = []
    white_index = {}
    black_numbered = []

    for r in range(n):
        for c in range(m):
            v = data[r][c]
            if v is None:
                white_index[(r, c)] = len(white_cells)
                white_cells.append((r, c))
            elif isinstance(v, int) and v >= 0:
                black_numbered.append((r, c, v))

    W = len(white_cells)

    # Visibility graph
    sees = [[] for _ in range(W)]
    lighters = [[] for _ in range(W)]  # includes self

    # Row scans
    for r in range(n):
        c = 0
        while c < m:
            if data[r][c] is not None:
                c += 1
                continue
            seg = []
            while c < m and data[r][c] is None:
                seg.append(white_index[(r, c)])
                c += 1
            for i in seg:
                for j in seg:
                    if i != j:
                        sees[i].append(j)

    # Column scans
    for c in range(m):
        r = 0
        while r < n:
            if data[r][c] is not None:
                r += 1
                continue
            seg = []
            while r < n and data[r][c] is None:
                seg.append(white_index[(r, c)])
                r += 1
            for i in seg:
                for j in seg:
                    if i != j:
                        sees[i].append(j)

    # Deduplicate and build lighters
    for i in range(W):
        if sees[i]:
            sees[i] = list(dict.fromkeys(sees[i]))
        lighters[i] = [i] + sees[i]

    # Numbered-black adjacency
    clue_adj = []
    cell_to_clues = [[] for _ in range(W)]
    for r, c, req in black_numbered:
        adj = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if (rr, cc) in white_index:
                idx = white_index[(rr, cc)]
                adj.append(idx)
                cell_to_clues[idx].append(len(clue_adj))
        clue_adj.append((req, adj))

    UNKNOWN, EMPTY, BULB = -1, 0, 1

    def copy_state(state):
        return state[:]

    def current_bulbs(state):
        return [i for i, v in enumerate(state) if v == BULB]

    def lit_map(state):
        lit = [False] * W
        for i, v in enumerate(state):
            if v == BULB:
                lit[i] = True
                for j in sees[i]:
                    lit[j] = True
        return lit

    def clue_counts(state, clue_id):
        req, adj = clue_adj[clue_id]
        bulbs = 0
        unknowns = 0
        for i in adj:
            if state[i] == BULB:
                bulbs += 1
            elif state[i] == UNKNOWN:
                unknowns += 1
        return req, bulbs, unknowns

    def can_be_bulb_basic(state, i):
        if state[i] == EMPTY:
            return False
        # No visible bulb
        for j in sees[i]:
            if state[j] == BULB:
                return False
        # Numbered clues cannot be exceeded
        for clue_id in cell_to_clues[i]:
            req, adj = clue_adj[clue_id]
            bulbs = 0
            for k in adj:
                if state[k] == BULB:
                    bulbs += 1
            if bulbs + 1 > req:
                return False
        return True

    def assign_empty(state, i):
        if state[i] == EMPTY:
            return True
        if state[i] == BULB:
            return False
        state[i] = EMPTY
        return True

    def assign_bulb(state, i):
        if state[i] == BULB:
            return True
        if state[i] == EMPTY:
            return False
        if not can_be_bulb_basic(state, i):
            return False
        state[i] = BULB
        # All visible cells become non-bulbs immediately
        for j in sees[i]:
            if state[j] == BULB:
                return False
            if state[j] == UNKNOWN:
                state[j] = EMPTY
        return True

    def propagate(state):
        changed = True
        while changed:
            changed = False

            # Immediate contradiction / forced empty from visibility to existing bulbs
            for i in range(W):
                if state[i] == UNKNOWN and not can_be_bulb_basic(state, i):
                    state[i] = EMPTY
                    changed = True

            # Numbered clues
            for clue_id in range(len(clue_adj)):
                req, bulbs, unknowns = clue_counts(state, clue_id)
                if bulbs > req or bulbs + unknowns < req:
                    return None
                if unknowns:
                    _, adj = clue_adj[clue_id]
                    if bulbs == req:
                        for i in adj:
                            if state[i] == UNKNOWN:
                                if not assign_empty(state, i):
                                    return None
                                changed = True
                    elif bulbs + unknowns == req:
                        for i in adj:
                            if state[i] == UNKNOWN:
                                if not assign_bulb(state, i):
                                    return None
                                changed = True

            # Every white cell must remain lightable.
            lit = lit_map(state)
            for i in range(W):
                bulb_present = lit[i]
                candidates = []
                if not bulb_present:
                    for j in lighters[i]:
                        if state[j] == UNKNOWN and can_be_bulb_basic(state, j):
                            candidates.append(j)
                if not bulb_present and not candidates:
                    return None
                if not bulb_present and len(candidates) == 1:
                    if not assign_bulb(state, candidates[0]):
                        return None
                    changed = True

            # Re-check clue feasibility after recent assignments
            for clue_id in range(len(clue_adj)):
                req, bulbs, unknowns = clue_counts(state, clue_id)
                if bulbs > req or bulbs + unknowns < req:
                    return None

            # If an unknown cell cannot be bulb and is already lit, safely make it empty.
            # This reduces branching and mirrors human elimination.
            lit = lit_map(state)
            for i in range(W):
                if state[i] == UNKNOWN and lit[i] and not can_be_bulb_basic(state, i):
                    if not assign_empty(state, i):
                        return None
                    changed = True

        # Final consistency checks
        for i in range(W):
            if state[i] == BULB:
                for j in sees[i]:
                    if state[j] == BULB:
                        return None
        for clue_id in range(len(clue_adj)):
            req, bulbs, unknowns = clue_counts(state, clue_id)
            if bulbs > req or bulbs + unknowns < req:
                return None
        for i in range(W):
            if state[i] == UNKNOWN and not can_be_bulb_basic(state, i):
                state[i] = EMPTY
        return state

    def is_solved(state):
        # All clues exact and every white cell lit; any remaining unknowns can be empty iff lit.
        lit = lit_map(state)
        for clue_id in range(len(clue_adj)):
            req, bulbs, unknowns = clue_counts(state, clue_id)
            if bulbs != req:
                return False
            if unknowns and req == bulbs:
                # These unknowns are effectively empty, but state not fully normalized.
                pass
        for i in range(W):
            if not lit[i]:
                return False
        return True

    def finalize_grid(state):
        # Set all remaining unknowns to empty; solution validity already ensured.
        out = [[None for _ in range(m)] for _ in range(n)]
        for i, (r, c) in enumerate(white_cells):
            if state[i] == BULB:
                out[r][c] = 'B'
            else:
                out[r][c] = None
        return out

    def choose_branch(state):
        # Prefer an unlit cell with the fewest possible lighters.
        lit = lit_map(state)
        best = None
        for i in range(W):
            if lit[i]:
                continue
            cands = []
            for j in lighters[i]:
                if state[j] == UNKNOWN and can_be_bulb_basic(state, j):
                    cands.append(j)
            if not cands:
                return ('contradiction', [])
            cands = list(dict.fromkeys(cands))
            if best is None or len(cands) < len(best[1]):
                best = ('cover', cands)
                if len(cands) <= 2:
                    return best

        if best is not None:
            return best

        # Otherwise choose a highly constrained unknown cell.
        best_cell = None
        best_score = None
        for i in range(W):
            if state[i] != UNKNOWN:
                continue
            can_bulb = can_be_bulb_basic(state, i)
            lit_i = lit[i]
            # lower score => more constrained
            score = (
                0 if not lit_i else 1,
                0 if can_bulb else 1,
                len(cell_to_clues[i]),
                len(lighters[i]),
            )
            if best_score is None or score < best_score:
                best_score = score
                best_cell = i
        if best_cell is None:
            return None
        return ('cell', best_cell)

    def search(state):
        state = propagate(copy_state(state))
        if state is None:
            return None

        if is_solved(state):
            return state

        branch = choose_branch(state)
        if branch is None:
            return state if is_solved(state) else None
        kind, payload = branch

        if kind == 'contradiction':
            return None

        if kind == 'cover':
            # At least one candidate must be a bulb.
            for j in payload:
                new_state = copy_state(state)
                if assign_bulb(new_state, j):
                    res = search(new_state)
                    if res is not None:
                        return res
            return None

        # Branch on a single cell: try bulb first only if legal, then empty.
        i = payload
        if can_be_bulb_basic(state, i):
            new_state = copy_state(state)
            if assign_bulb(new_state, i):
                res = search(new_state)
                if res is not None:
                    return res

        new_state = copy_state(state)
        if assign_empty(new_state, i):
            res = search(new_state)
            if res is not None:
                return res

        return None

    init_state = [UNKNOWN] * W
    result = search(init_state)
    if result is None:
        return "No Solution"
    return repr(finalize_grid(result))


if __name__ == "__main__":
    print(solve(OBSERVATION))

