from collections import defaultdict, deque

# General Hashiwokakero solver with strong propagation and bounded search.
# The implementation favors human-like deductions:
# - determine visible neighbors
# - keep per-edge domains {0,1,2}
# - repeatedly tighten domains from island sums
# - apply crossing exclusions
# - prune by connectivity feasibility
# - branch only when logic stalls

def solve(observation):
    data = observation["data"]
    n = len(data)
    islands = []
    pos_to_idx = {}
    for r in range(n):
        for c in range(len(data[r])):
            if data[r][c] is not None:
                pos_to_idx[(r, c)] = len(islands)
                islands.append({"pos": (r, c), "need": data[r][c]})

    if not islands:
        return "{}"

    edges = []
    inc = [[] for _ in islands]

    # Build horizontal visible edges.
    for r in range(n):
        prev = None
        for c in range(len(data[r])):
            if data[r][c] is not None:
                if prev is not None:
                    a = pos_to_idx[(r, prev)]
                    b = pos_to_idx[(r, c)]
                    eidx = len(edges)
                    edges.append({
                        "a": a, "b": b,
                        "p1": (r, prev), "p2": (r, c),
                        "orient": "H",
                        "cross": []
                    })
                    inc[a].append(eidx)
                    inc[b].append(eidx)
                prev = c

    # Build vertical visible edges.
    for c in range(len(data[0])):
        prev = None
        for r in range(n):
            if data[r][c] is not None:
                if prev is not None:
                    a = pos_to_idx[(prev, c)]
                    b = pos_to_idx[(r, c)]
                    eidx = len(edges)
                    edges.append({
                        "a": a, "b": b,
                        "p1": (prev, c), "p2": (r, c),
                        "orient": "V",
                        "cross": []
                    })
                    inc[a].append(eidx)
                    inc[b].append(eidx)
                prev = r

    # Crossing pairs: horizontal segment crosses vertical segment if the interior points intersect.
    for i, e1 in enumerate(edges):
        if e1["orient"] != "H":
            continue
        r = e1["p1"][0]
        c1, c2 = e1["p1"][1], e1["p2"][1]
        lo_c, hi_c = min(c1, c2), max(c1, c2)
        for j, e2 in enumerate(edges):
            if e2["orient"] != "V":
                continue
            c = e2["p1"][1]
            r1, r2 = e2["p1"][0], e2["p2"][0]
            lo_r, hi_r = min(r1, r2), max(r1, r2)
            if lo_c < c < hi_c and lo_r < r < hi_r:
                e1["cross"].append(j)
                e2["cross"].append(i)

    need = [x["need"] for x in islands]
    m = len(edges)

    # Domains are inclusive [lo[i], hi[i]] over {0,1,2}.
    lo0 = [0] * m
    hi0 = [2] * m

    # Initial trivial upper bounds from endpoint demands.
    for i, e in enumerate(edges):
        hi0[i] = min(2, need[e["a"]], need[e["b"]])

    def copy_state(lo, hi):
        return lo[:], hi[:]

    def set_range(lo, hi, i, new_lo, new_hi):
        if new_lo > new_hi:
            return False, True
        changed = False
        if new_lo > lo[i]:
            lo[i] = new_lo
            changed = True
        if new_hi < hi[i]:
            hi[i] = new_hi
            changed = True
        if lo[i] > hi[i]:
            return False, True
        return changed, False

    def island_bounds(lo, hi, v):
        s_lo = 0
        s_hi = 0
        for e in inc[v]:
            s_lo += lo[e]
            s_hi += hi[e]
        return s_lo, s_hi

    def possible_graph(hi):
        g = [[] for _ in islands]
        for i, e in enumerate(edges):
            if hi[i] > 0:
                a, b = e["a"], e["b"]
                g[a].append(b)
                g[b].append(a)
        return g

    def assigned_positive_graph(lo):
        g = [[] for _ in islands]
        for i, e in enumerate(edges):
            if lo[i] > 0:
                a, b = e["a"], e["b"]
                g[a].append(b)
                g[b].append(a)
        return g

    def components_from_graph(g):
        comp = [-1] * len(g)
        cid = 0
        for s in range(len(g)):
            if comp[s] != -1:
                continue
            q = [s]
            comp[s] = cid
            for u in q:
                for v in g[u]:
                    if comp[v] == -1:
                        comp[v] = cid
                        q.append(v)
            cid += 1
        groups = [[] for _ in range(cid)]
        for i, c in enumerate(comp):
            groups[c].append(i)
        return comp, groups

    def connectivity_prune(lo, hi):
        # Potential connectivity must remain possible.
        g_possible = possible_graph(hi)
        comp_possible, groups_possible = components_from_graph(g_possible)
        if len(groups_possible) > 1:
            return False

        # Existing positive-bridge components cannot become sealed off.
        g_assigned = assigned_positive_graph(lo)
        comp_assigned, groups_assigned = components_from_graph(g_assigned)

        if len(groups_assigned) == 1:
            return True

        for group in groups_assigned:
            if len(group) == len(islands):
                continue

            # Need at least one possible edge leaving the component.
            external_possible = False
            forced_external = 0
            for u in group:
                for ei in inc[u]:
                    e = edges[ei]
                    v = e["b"] if e["a"] == u else e["a"]
                    if comp_assigned[v] != comp_assigned[u] and hi[ei] > 0:
                        external_possible = True
                        if lo[ei] > 0:
                            forced_external += 1
            if not external_possible:
                return False

            # If all islands in the component are already exactly saturated, component cannot later connect out.
            all_saturated = True
            for u in group:
                s_lo, s_hi = island_bounds(lo, hi, u)
                if not (s_lo == s_hi == need[u]):
                    all_saturated = False
                    break
            if all_saturated:
                return False

        return True

    def propagate(lo, hi):
        changed = True
        while changed:
            changed = False

            # Crossing propagation.
            for i, e in enumerate(edges):
                if lo[i] > 0:
                    for j in e["cross"]:
                        if hi[j] > 0:
                            ch, bad = set_range(lo, hi, j, lo[j], 0)
                            if bad:
                                return False
                            changed |= ch
                if hi[i] == 0:
                    continue

            # Island sum propagation.
            for v in range(len(islands)):
                elist = inc[v]
                cur_lo = sum(lo[e] for e in elist)
                cur_hi = sum(hi[e] for e in elist)
                tgt = need[v]

                if tgt < cur_lo or tgt > cur_hi:
                    return False

                # Tighten each incident edge using residual bounds.
                for ei in elist:
                    others_lo = cur_lo - lo[ei]
                    others_hi = cur_hi - hi[ei]
                    nlo = max(lo[ei], tgt - others_hi)
                    nhi = min(hi[ei], tgt - others_lo)
                    ch, bad = set_range(lo, hi, ei, nlo, nhi)
                    if bad:
                        return False
                    changed |= ch

                # Recompute after local updates if changed.
                cur_lo = sum(lo[e] for e in elist)
                cur_hi = sum(hi[e] for e in elist)
                if tgt < cur_lo or tgt > cur_hi:
                    return False

                # Human-style forced rules.
                rem_need = tgt - cur_lo
                rem_cap = cur_hi - cur_lo
                if rem_need == 0:
                    for ei in elist:
                        ch, bad = set_range(lo, hi, ei, lo[ei], lo[ei])
                        if bad:
                            return False
                        changed |= ch
                elif rem_need == rem_cap:
                    for ei in elist:
                        ch, bad = set_range(lo, hi, ei, hi[ei], hi[ei])
                        if bad:
                            return False
                        changed |= ch

                # Degree-like rule:
                # if island still needs k and exactly k units can only come from some subset, they become forced
                # already largely captured by bound tightening.

            # Crossings after upper/lower changes.
            for i, e in enumerate(edges):
                if lo[i] > 0:
                    for j in e["cross"]:
                        if hi[j] > 0:
                            ch, bad = set_range(lo, hi, j, lo[j], 0)
                            if bad:
                                return False
                            changed |= ch

            if not connectivity_prune(lo, hi):
                return False

        return True

    def is_complete(lo, hi):
        for i in range(m):
            if lo[i] != hi[i]:
                return False
        for v in range(len(islands)):
            s = sum(lo[e] for e in inc[v])
            if s != need[v]:
                return False

        # Final connectivity on positive edges.
        g = [[] for _ in islands]
        for i, e in enumerate(edges):
            if lo[i] > 0:
                g[e["a"]].append(e["b"])
                g[e["b"]].append(e["a"])
        seen = set()
        stack = [0]
        seen.add(0)
        while stack:
            u = stack.pop()
            for w in g[u]:
                if w not in seen:
                    seen.add(w)
                    stack.append(w)
        return len(seen) == len(islands)

    def choose_branch_edge(lo, hi):
        # Prefer edge with smallest domain and strongest structural impact.
        best = None
        best_key = None
        for i, e in enumerate(edges):
            if lo[i] == hi[i]:
                continue
            size = hi[i] - lo[i]
            impact = len(e["cross"]) + len(inc[e["a"]]) + len(inc[e["b"]])
            slack_a = need[e["a"]] - sum(lo[x] for x in inc[e["a"]])
            slack_b = need[e["b"]] - sum(lo[x] for x in inc[e["b"]])
            key = (size, -impact, slack_a + slack_b)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def branch_values(lo_i, hi_i):
        # Try human-preferred stronger assumptions first:
        # if binary {0,2}, 2 then 0; if ternary {0,1,2}, try endpoints guided by forcing strength.
        if lo_i == hi_i:
            return [lo_i]
        vals = list(range(lo_i, hi_i + 1))
        if vals == [0, 1]:
            return [1, 0]
        if vals == [1, 2]:
            return [2, 1]
        if vals == [0, 2]:
            return [2, 0]
        if vals == [0, 1, 2]:
            return [1, 2, 0]
        return vals[::-1]

    def search(lo, hi):
        if not propagate(lo, hi):
            return None
        if is_complete(lo, hi):
            return lo

        ei = choose_branch_edge(lo, hi)
        if ei is None:
            return None

        for val in branch_values(lo[ei], hi[ei]):
            lo2, hi2 = copy_state(lo, hi)
            ok, bad = set_range(lo2, hi2, ei, val, val)
            if bad:
                continue
            res = search(lo2, hi2)
            if res is not None:
                return res

        return None

    result = search(lo0[:], hi0[:])
    if result is None:
        return "No Solution"

    ans = {}
    for i, cnt in enumerate(result):
        if cnt > 0:
            p1 = islands[edges[i]["a"]]["pos"]
            p2 = islands[edges[i]["b"]]["pos"]
            if p2 < p1:
                p1, p2 = p2, p1
            ans[(p1, p2)] = cnt
    return str(ans)


