from itertools import product

# Takuzu / Binairo solver:
# - equal number of B/W in each row and column
# - no three consecutive equal colors
# - all rows unique, all columns unique
# - givens fixed

B = 1
W = 0
U = -1

def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data) or n % 2 != 0:
        return "No Solution"

    grid = [[char_to_int(v) for v in row] for row in data]

    # Precompute every legal full line of length n.
    all_lines = generate_legal_lines(n)

    # Initial row/column domains from givens.
    row_domains = []
    for r in range(n):
        dom = [line for line in all_lines if line_matches_grid_row(line, grid[r])]
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        dom = [line for line in all_lines if line_matches_grid_row(line, col)]
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    result = search(grid, row_domains, col_domains)
    if result is None:
        return "No Solution"
    return [[int_to_char(v) for v in row] for row in result]

def char_to_int(v):
    if v == 'B':
        return B
    if v == 'W':
        return W
    return U

def int_to_char(v):
    return 'B' if v == B else 'W'

def generate_legal_lines(n):
    half = n // 2
    out = []

    def rec(pos, line, bcnt, wcnt):
        if bcnt > half or wcnt > half:
            return
        if pos >= 2 and line[pos - 1] == line[pos - 2]:
            # Next value cannot equal them.
            for v in (B, W):
                if v == line[pos - 1]:
                    continue
                if v == B:
                    if bcnt + 1 <= half:
                        rec(pos + 1, line + (v,), bcnt + 1, wcnt)
                else:
                    if wcnt + 1 <= half:
                        rec(pos + 1, line + (v,), bcnt, wcnt + 1)
            return
        if pos == n:
            if bcnt == half and wcnt == half:
                out.append(line)
            return
        rem = n - pos
        if bcnt + rem < half or wcnt + rem < half:
            return
        for v in (B, W):
            if pos >= 2 and line[pos - 1] == line[pos - 2] == v:
                continue
            if v == B:
                if bcnt < half:
                    rec(pos + 1, line + (v,), bcnt + 1, wcnt)
            else:
                if wcnt < half:
                    rec(pos + 1, line + (v,), bcnt, wcnt + 1)

    rec(0, tuple(), 0, 0)
    return out

def line_matches_grid_row(line, partial):
    for a, b in zip(line, partial):
        if b != U and a != b:
            return False
    return True

def compatible_prefix_with_grid_row(line, partial):
    # Same as line_matches_grid_row, but named for clarity in propagation.
    for a, b in zip(line, partial):
        if b != U and a != b:
            return False
    return True

def copy_domains(domains):
    return [d[:] for d in domains]

def transpose(grid):
    n = len(grid)
    return [[grid[r][c] for r in range(n)] for c in range(n)]

def derive_forced_cells(domains, n):
    forced = []
    for i, dom in enumerate(domains):
        if not dom:
            return None
        if len(dom) == 1:
            forced.append(list(dom[0]))
            continue
        row = [U] * n
        first = dom[0]
        for j in range(n):
            v = first[j]
            same = True
            for line in dom[1:]:
                if line[j] != v:
                    same = False
                    break
            if same:
                row[j] = v
        forced.append(row)
    return forced

def apply_human_cell_rules(grid):
    # Repeatedly apply local human rules:
    # 1) XX_ -> opposite, _XX -> opposite, X_X -> opposite
    # 2) count completion in rows/cols
    n = len(grid)
    changed = True
    while changed:
        changed = False

        # Triple-avoidance on rows
        for r in range(n):
            row = grid[r]
            for c in range(n - 2):
                a, b, d = row[c], row[c + 1], row[c + 2]
                if a != U and a == b and d == U:
                    row[c + 2] = 1 - a
                    changed = True
                elif a == U and b != U and b == d:
                    row[c] = 1 - b
                    changed = True
                elif a != U and d != U and a == d and b == U:
                    row[c + 1] = 1 - a
                    changed = True

        # Triple-avoidance on cols
        for c in range(n):
            for r in range(n - 2):
                a, b, d = grid[r][c], grid[r + 1][c], grid[r + 2][c]
                if a != U and a == b and d == U:
                    grid[r + 2][c] = 1 - a
                    changed = True
                elif a == U and b != U and b == d:
                    grid[r][c] = 1 - b
                    changed = True
                elif a != U and d != U and a == d and b == U:
                    grid[r + 1][c] = 1 - a
                    changed = True

        # Count completion rows
        half = n // 2
        for r in range(n):
            row = grid[r]
            bcnt = row.count(B)
            wcnt = row.count(W)
            if bcnt > half or wcnt > half:
                return False
            if bcnt == half:
                for c in range(n):
                    if row[c] == U:
                        row[c] = W
                        changed = True
            elif wcnt == half:
                for c in range(n):
                    if row[c] == U:
                        row[c] = B
                        changed = True

        # Count completion cols
        for c in range(n):
            col = [grid[r][c] for r in range(n)]
            bcnt = col.count(B)
            wcnt = col.count(W)
            if bcnt > half or wcnt > half:
                return False
            if bcnt == half:
                for r in range(n):
                    if grid[r][c] == U:
                        grid[r][c] = W
                        changed = True
            elif wcnt == half:
                for r in range(n):
                    if grid[r][c] == U:
                        grid[r][c] = B
                        changed = True

        # Early validity check
        if not basic_grid_valid(grid):
            return False

    return True

def basic_grid_valid(grid):
    n = len(grid)
    half = n // 2

    # Counts + no triples in rows
    for r in range(n):
        row = grid[r]
        if row.count(B) > half or row.count(W) > half:
            return False
        for c in range(n - 2):
            a, b, d = row[c], row[c + 1], row[c + 2]
            if a != U and a == b == d:
                return False

    # Counts + no triples in cols
    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        if col.count(B) > half or col.count(W) > half:
            return False
        for r in range(n - 2):
            a, b, d = col[r], col[r + 1], col[r + 2]
            if a != U and a == b == d:
                return False

    # Uniqueness among completed rows
    full_rows = {}
    for r in range(n):
        row = tuple(grid[r])
        if U not in row:
            if row in full_rows:
                return False
            full_rows[row] = r

    # Uniqueness among completed cols
    full_cols = {}
    for c in range(n):
        col = tuple(grid[r][c] for r in range(n))
        if U not in col:
            if col in full_cols:
                return False
            full_cols[col] = c

    return True

def restrict_domains_from_grid(grid, row_domains, col_domains):
    n = len(grid)

    # Filter row domains by row state and fixed completed uniqueness.
    completed_rows = {}
    for r in range(n):
        row = tuple(grid[r])
        if U not in row:
            completed_rows[row] = completed_rows.get(row, 0) + 1
            if completed_rows[row] > 1:
                return False

    for r in range(n):
        row = grid[r]
        dom = [line for line in row_domains[r] if compatible_prefix_with_grid_row(line, row)]
        if not dom:
            return False
        row_domains[r] = dom

    # Filter col domains by col state and fixed completed uniqueness.
    completed_cols = {}
    for c in range(n):
        col = tuple(grid[r][c] for r in range(n))
        if U not in col:
            completed_cols[col] = completed_cols.get(col, 0) + 1
            if completed_cols[col] > 1:
                return False

    for c in range(n):
        col = [grid[r][c] for r in range(n)]
        dom = [line for line in col_domains[c] if compatible_prefix_with_grid_row(line, col)]
        if not dom:
            return False
        col_domains[c] = dom

    # Remove row candidates incompatible with some column candidate per cell.
    col_value_masks = [[0, 0] for _ in range(n)]  # overwritten per column later; placeholder for shape clarity
    for c in range(n):
        vals = [0] * n
        for line in col_domains[c]:
            for r in range(n):
                vals[r] |= (1 << line[r])
        for r in range(n):
            if vals[r] == 0:
                return False
        new_dom = []
        for line in row_domains_for_cell_filter(row_domains, c=None):
            pass

    # Row pruning using column possibilities
    col_possible = [[0] * n for _ in range(n)]
    for c in range(n):
        for line in col_domains[c]:
            for r in range(n):
                col_possible[r][c] |= (1 << line[r])

    for r in range(n):
        new_dom = []
        for line in row_domains[r]:
            ok = True
            for c in range(n):
                if not (col_possible[r][c] & (1 << line[c])):
                    ok = False
                    break
            if ok:
                new_dom.append(line)
        if not new_dom:
            return False
        row_domains[r] = new_dom

    # Column pruning using row possibilities
    row_possible = [[0] * n for _ in range(n)]
    for r in range(n):
        for line in row_domains[r]:
            for c in range(n):
                row_possible[r][c] |= (1 << line[c])

    for c in range(n):
        new_dom = []
        for line in col_domains[c]:
            ok = True
            for r in range(n):
                if not (row_possible[r][c] & (1 << line[r])):
                    ok = False
                    break
            if ok:
                new_dom.append(line)
        if not new_dom:
            return False
        col_domains[c] = new_dom

    # Uniqueness pruning for completed/forced lines:
    # if a row is fixed to exactly one line, no other row may use the same completed line.
    if not uniqueness_prune(row_domains):
        return False
    if not uniqueness_prune(col_domains):
        return False

    return True

def row_domains_for_cell_filter(row_domains, c=None):
    # Helper used only to preserve code readability above.
    return ()

def uniqueness_prune(domains):
    singles = {}
    for i, dom in enumerate(domains):
        if len(dom) == 1:
            singles[dom[0]] = singles.get(dom[0], 0) + 1
            if singles[dom[0]] > 1:
                return False
    fixed_lines = {dom[0] for dom in domains if len(dom) == 1}
    for i, dom in enumerate(domains):
        if len(dom) > 1:
            new_dom = [line for line in dom if line not in fixed_lines]
            if new_dom:
                domains[i] = new_dom
    return True

def propagate(grid, row_domains, col_domains):
    n = len(grid)
    while True:
        snapshot = (
            tuple(tuple(row) for row in grid),
            tuple(len(d) for d in row_domains),
            tuple(len(d) for d in col_domains),
        )

        if not apply_human_cell_rules(grid):
            return False

        if not restrict_domains_from_grid(grid, row_domains, col_domains):
            return False

        # Force cells from row domains
        row_forced = derive_forced_cells(row_domains, n)
        if row_forced is None:
            return False
        for r in range(n):
            for c in range(n):
                v = row_forced[r][c]
                if v != U:
                    if grid[r][c] == U:
                        grid[r][c] = v
                    elif grid[r][c] != v:
                        return False

        # Force cells from column domains
        col_forced = derive_forced_cells(col_domains, n)
        if col_forced is None:
            return False
        for c in range(n):
            for r in range(n):
                v = col_forced[c][r]
                if v != U:
                    if grid[r][c] == U:
                        grid[r][c] = v
                    elif grid[r][c] != v:
                        return False

        if not basic_grid_valid(grid):
            return False

        new_snapshot = (
            tuple(tuple(row) for row in grid),
            tuple(len(d) for d in row_domains),
            tuple(len(d) for d in col_domains),
        )
        if new_snapshot == snapshot:
            break

    return True

def is_solved(grid):
    n = len(grid)
    if any(U in row for row in grid):
        return False

    half = n // 2
    row_set = set()
    for r in range(n):
        row = tuple(grid[r])
        if row.count(B) != half or row.count(W) != half:
            return False
        for c in range(n - 2):
            if row[c] == row[c + 1] == row[c + 2]:
                return False
        if row in row_set:
            return False
        row_set.add(row)

    col_set = set()
    for c in range(n):
        col = tuple(grid[r][c] for r in range(n))
        if col.count(B) != half or col.count(W) != half:
            return False
        for r in range(n - 2):
            if col[r] == col[r + 1] == col[r + 2]:
                return False
        if col in col_set:
            return False
        col_set.add(col)

    return True

def search(grid, row_domains, col_domains):
    grid = [row[:] for row in grid]
    row_domains = copy_domains(row_domains)
    col_domains = copy_domains(col_domains)

    if not propagate(grid, row_domains, col_domains):
        return None

    if is_solved(grid):
        return grid

    n = len(grid)

    # Choose the most constrained unresolved structure:
    # prefer a row/column domain with smallest size > 1; otherwise a cell with two possibilities.
    best_kind = None
    best_idx = None
    best_size = 10**9

    for r in range(n):
        sz = len(row_domains[r])
        if 1 < sz < best_size:
            best_size = sz
            best_kind = 'row'
            best_idx = r

    for c in range(n):
        sz = len(col_domains[c])
        if 1 < sz < best_size:
            best_size = sz
            best_kind = 'col'
            best_idx = c

    if best_kind == 'row':
        r = best_idx
        # Order candidates to favor those consistent with current column tightness.
        candidates = sorted(row_domains[r], key=lambda line: line_score_row(line, r, col_domains))
        for line in candidates:
            new_grid = [row[:] for row in grid]
            new_row_domains = copy_domains(row_domains)
            new_col_domains = copy_domains(col_domains)
            new_grid[r] = list(line)
            new_row_domains[r] = [line]
            result = search(new_grid, new_row_domains, new_col_domains)
            if result is not None:
                return result
        return None

    if best_kind == 'col':
        c = best_idx
        candidates = sorted(col_domains[c], key=lambda line: line_score_col(line, c, row_domains))
        for line in candidates:
            new_grid = [row[:] for row in grid]
            for r in range(n):
                new_grid[r][c] = line[r]
            new_row_domains = copy_domains(row_domains)
            new_col_domains = copy_domains(col_domains)
            new_col_domains[c] = [line]
            result = search(new_grid, new_row_domains, new_col_domains)
            if result is not None:
                return result
        return None

    # Fallback: pick a cell with two possibilities.
    row_forced = derive_forced_cells(row_domains, n)
    col_forced = derive_forced_cells(col_domains, n)
    best_cell = None
    best_cell_opts = None
    for r in range(n):
        for c in range(n):
            if grid[r][c] != U:
                continue
            opts = set()
            for line in row_domains[r]:
                opts.add(line[c])
            allowed_by_col = set(line[r] for line in col_domains[c])
            opts &= allowed_by_col
            if not opts:
                return None
            if best_cell is None or len(opts) < len(best_cell_opts):
                best_cell = (r, c)
                best_cell_opts = opts
                if len(opts) == 1:
                    break
        if best_cell_opts is not None and len(best_cell_opts) == 1:
            break

    if best_cell is None:
        return grid if is_solved(grid) else None

    r, c = best_cell
    for v in sorted(best_cell_opts):
        new_grid = [row[:] for row in grid]
        new_grid[r][c] = v
        result = search(new_grid, row_domains, col_domains)
        if result is not None:
            return result
    return None

def line_score_row(line, r, col_domains):
    score = 0
    for c, v in enumerate(line):
        count = 0
        for col_line in col_domains[c]:
            if col_line[r] == v:
                count += 1
        score += count
    return score

def line_score_col(line, c, row_domains):
    score = 0
    for r, v in enumerate(line):
        count = 0
        for row_line in row_domains[r]:
            if row_line[c] == v:
                count += 1
        score += count
    return score

