# Kropki Latin square solver with strong propagation and small, targeted search.
# The solver is generalized for any N x N observation in the stated format.

def solve(observation):
    data = observation['data']
    n = len(data)
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def is_single(mask):
        return mask and (mask & (mask - 1)) == 0

    def mask_to_val(mask):
        return mask.bit_length()

    # Precompute consecutive relation masks per value and support aggregation per domain mask.
    consec_of_val = [0] * (n + 1)
    for v in range(1, n + 1):
        m = 0
        if v > 1:
            m |= bit(v - 1)
        if v < n:
            m |= bit(v + 1)
        consec_of_val[v] = m

    support_consec = [0] * (1 << n)
    support_nonconsec = [0] * (1 << n)
    for mask in range(1 << n):
        sc = 0
        for v in range(1, n + 1):
            if mask & bit(v):
                sc |= consec_of_val[v]
        support_consec[mask] = sc
        support_nonconsec[mask] = full & ~sc

    # Build adjacency map: every orthogonally adjacent pair is either dotted (consecutive) or non-dotted (not consecutive).
    dotted = set()
    for r_or_y, c_or_x in observation['adjacent']:
        if int(r_or_y) == r_or_y:  # horizontal gap (row, col+0.5)
            r = int(r_or_y)
            c = int(c_or_x - 0.5)
            a = r * n + c
            b = r * n + (c + 1)
        else:  # vertical gap (row+0.5, col)
            r = int(r_or_y - 0.5)
            c = int(c_or_x)
            a = r * n + c
            b = (r + 1) * n + c
        if a > b:
            a, b = b, a
        dotted.add((a, b))

    neighbors = [[] for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            i = r * n + c
            if c + 1 < n:
                j = r * n + (c + 1)
                rel = 1 if (min(i, j), max(i, j)) in dotted else 0
                neighbors[i].append((j, rel))
                neighbors[j].append((i, rel))
            if r + 1 < n:
                j = (r + 1) * n + c
                rel = 1 if (min(i, j), max(i, j)) in dotted else 0
                neighbors[i].append((j, rel))
                neighbors[j].append((i, rel))

    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]
    groups = rows + cols
    cell_groups = [[] for _ in range(n * n)]
    for gi, grp in enumerate(groups):
        for idx in grp:
            cell_groups[idx].append(gi)

    # Initial domains.
    domains = [full] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                domains[r * n + c] = bit(v)

    def propagate(domains):
        # Repeatedly enforce:
        # 1) row/col assigned exclusion
        # 2) row/col hidden singles
        # 3) binary Kropki arc consistency
        changed = True
        while changed:
            changed = False

            # Latin exclusion by assigned values in groups.
            for grp in groups:
                fixed = 0
                for i in grp:
                    m = domains[i]
                    if is_single(m):
                        if fixed & m:
                            return None
                        fixed |= m
                for i in grp:
                    m = domains[i]
                    if not is_single(m):
                        nm = m & ~fixed
                        if nm == 0:
                            return None
                        if nm != m:
                            domains[i] = nm
                            changed = True

            # Hidden singles in groups.
            for grp in groups:
                for v in range(1, n + 1):
                    b = bit(v)
                    places = []
                    for i in grp:
                        if domains[i] & b:
                            places.append(i)
                            if len(places) > 1:
                                break
                    if not places:
                        return None
                    if len(places) == 1:
                        i = places[0]
                        if domains[i] != b:
                            domains[i] = b
                            changed = True

            # Binary adjacency consistency.
            for i in range(n * n):
                mi = domains[i]
                for j, rel in neighbors[i]:
                    mj = domains[j]
                    if rel == 1:
                        allowed_j = support_consec[mi]
                        n_j = mj & allowed_j
                        if n_j == 0:
                            return None
                        if n_j != mj:
                            domains[j] = n_j
                            changed = True
                    else:
                        allowed_j = support_nonconsec[mi]
                        n_j = mj & allowed_j
                        if n_j == 0:
                            return None
                        if n_j != mj:
                            domains[j] = n_j
                            changed = True

            # Hall-like check for groups: for each value must appear somewhere, and union size sanity.
            # Lightweight but useful: if a subset of k digits can only go in <k cells => impossible.
            # Implemented by bucketizing exact domain masks.
            for grp in groups:
                # Missing value check already partly covered, but keep fast exact version here.
                union = 0
                for i in grp:
                    union |= domains[i]
                if union != full:
                    return None

                mask_cells = {}
                for i in grp:
                    m = domains[i]
                    if not is_single(m):
                        mask_cells[m] = mask_cells.get(m, 0) + 1
                # If a domain mask with popcount k occurs more than k times, no issue.
                # But if cells covered by a union mask are fewer than needed, we catch only exact-mask naked sets here.
                for m, cnt in mask_cells.items():
                    if m.bit_count() < cnt:
                        return None
                    if m.bit_count() == cnt:
                        # Naked set: remove from others.
                        for i in grp:
                            if domains[i] != m and (domains[i] & m):
                                nm = domains[i] & ~m
                                if nm == 0:
                                    return None
                                if nm != domains[i]:
                                    domains[i] = nm
                                    changed = True

        return domains

    def solved(domains):
        return all(is_single(m) for m in domains)

    def select_cell(domains):
        # MRV with degree tie-break and impact score from constraints.
        best = None
        best_key = None
        for i, m in enumerate(domains):
            bc = m.bit_count()
            if bc > 1:
                degree = len(neighbors[i]) + 2 * (n - 1)
                key = (bc, -degree)
                if best_key is None or key < best_key:
                    best_key = key
                    best = i
        return best

    def order_values(i, domains):
        # Least-constraining value using row/col and kropki neighbors.
        vals = []
        m = domains[i]
        r, c = divmod(i, n)
        peers = set(rows[r] + cols[c])
        peers.discard(i)
        for v in range(1, n + 1):
            b = bit(v)
            if m & b:
                score = 0
                for p in peers:
                    if domains[p] & b:
                        score += 1
                for j, rel in neighbors[i]:
                    if rel == 1:
                        score += (domains[j] & consec_of_val[v]).bit_count()
                    else:
                        score += (domains[j] & (full & ~consec_of_val[v])).bit_count()
                vals.append((score, v))
        vals.sort(reverse=True)
        return [v for _, v in vals]

    def dfs(domains):
        domains = propagate(domains[:])
        if domains is None:
            return None
        if solved(domains):
            return domains

        i = select_cell(domains)
        for v in order_values(i, domains):
            nd = domains[:]
            nd[i] = bit(v)
            res = dfs(nd)
            if res is not None:
                return res
        return None

    result = dfs(domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(mask_to_val(result[r * n + c]))
        grid.append(row)
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

