# Nonogram solver with strong line-domain propagation and minimal branching.
# Grid cells use:
#   1  -> black
#   0  -> white / non-black
#  -1  -> unknown

from functools import lru_cache

BLACK = 1
WHITE = 0
UNKNOWN = -1


def generate_line_patterns(length, clues):
    clues = tuple(clues)

    @lru_cache(None)
    def rec(pos, idx):
        if idx == len(clues):
            return [tuple([WHITE] * (length - pos))]
        run = clues[idx]
        remaining_runs = clues[idx + 1:]
        min_tail = sum(remaining_runs) + max(0, len(remaining_runs) - 1)
        out = []
        max_start = length - (run + min_tail)
        for start in range(pos, max_start + 1):
            prefix = [WHITE] * (start - pos) + [BLACK] * run
            next_pos = start + run
            if idx < len(clues) - 1:
                prefix.append(WHITE)
                next_pos += 1
            for tail in rec(next_pos, idx + 1):
                out.append(tuple(prefix) + tail)
        return out

    if not clues:
        return [tuple([WHITE] * length)]
    return rec(0, 0)


def compatible(pattern, current_line):
    for a, b in zip(pattern, current_line):
        if b != UNKNOWN and a != b:
            return False
    return True


def intersect_patterns(patterns):
    if not patterns:
        return None
    length = len(patterns[0])
    result = []
    for i in range(length):
        v = patterns[0][i]
        same = True
        for p in patterns[1:]:
            if p[i] != v:
                same = False
                break
        result.append(v if same else UNKNOWN)
    return result


def line_runs_from_pattern(pattern):
    runs = []
    c = 0
    for v in pattern:
        if v == BLACK:
            c += 1
        elif c:
            runs.append(c)
            c = 0
    if c:
        runs.append(c)
    return runs


def validate_complete_grid(grid, row_clues, col_clues):
    h = len(grid)
    w = len(grid[0])
    for r in range(h):
        if line_runs_from_pattern(grid[r]) != row_clues[r]:
            return False
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if line_runs_from_pattern(col) != col_clues[c]:
            return False
    return True


def propagate(grid, row_domains, col_domains):
    h = len(grid)
    w = len(grid[0])

    changed = True
    while changed:
        changed = False

        # Filter row domains and force cells from row intersections.
        for r in range(h):
            current = grid[r]
            new_domain = [p for p in row_domains[r] if compatible(p, current)]
            if not new_domain:
                return None
            if len(new_domain) != len(row_domains[r]):
                row_domains[r] = new_domain
                changed = True
            forced = intersect_patterns(new_domain)
            for c, v in enumerate(forced):
                if v != UNKNOWN and grid[r][c] == UNKNOWN:
                    grid[r][c] = v
                    changed = True
                elif v != UNKNOWN and grid[r][c] != v:
                    return None

        # Filter column domains and force cells from column intersections.
        for c in range(w):
            current = [grid[r][c] for r in range(h)]
            new_domain = [p for p in col_domains[c] if compatible(p, current)]
            if not new_domain:
                return None
            if len(new_domain) != len(col_domains[c]):
                col_domains[c] = new_domain
                changed = True
            forced = intersect_patterns(new_domain)
            for r, v in enumerate(forced):
                if v != UNKNOWN and grid[r][c] == UNKNOWN:
                    grid[r][c] = v
                    changed = True
                elif v != UNKNOWN and grid[r][c] != v:
                    return None

    return grid, row_domains, col_domains


def choose_branch_line(row_domains, col_domains):
    best = None
    best_kind = None
    best_idx = None

    for i, d in enumerate(row_domains):
        n = len(d)
        if 1 < n and (best is None or n < best):
            best = n
            best_kind = 'row'
            best_idx = i

    for i, d in enumerate(col_domains):
        n = len(d)
        if 1 < n and (best is None or n < best):
            best = n
            best_kind = 'col'
            best_idx = i

    return best_kind, best_idx


def clone_state(grid, row_domains, col_domains):
    return [row[:] for row in grid], [d[:] for d in row_domains], [d[:] for d in col_domains]


def search(grid, row_domains, col_domains, row_clues, col_clues):
    state = propagate(grid, row_domains, col_domains)
    if state is None:
        return None
    grid, row_domains, col_domains = state

    complete = True
    for row in grid:
        for v in row:
            if v == UNKNOWN:
                complete = False
                break
        if not complete:
            break

    if complete:
        return grid if validate_complete_grid(grid, row_clues, col_clues) else None

    kind, idx = choose_branch_line(row_domains, col_domains)
    if kind is None:
        return None

    if kind == 'row':
        # Prefer patterns that maximize immediate information.
        domain = row_domains[idx]
        scored = []
        for p in domain:
            score = 0
            for c, v in enumerate(p):
                if grid[idx][c] == UNKNOWN:
                    score += 1
            scored.append((-score, p))
        scored.sort()
        for _, pattern in scored:
            ng, nr, nc = clone_state(grid, row_domains, col_domains)
            nr[idx] = [pattern]
            for c, v in enumerate(pattern):
                if ng[idx][c] != UNKNOWN and ng[idx][c] != v:
                    break
                ng[idx][c] = v
            else:
                ans = search(ng, nr, nc, row_clues, col_clues)
                if ans is not None:
                    return ans
    else:
        domain = col_domains[idx]
        scored = []
        for p in domain:
            score = 0
            for r, v in enumerate(p):
                if grid[r][idx] == UNKNOWN:
                    score += 1
            scored.append((-score, p))
        scored.sort()
        for _, pattern in scored:
            ng, nr, nc = clone_state(grid, row_domains, col_domains)
            nc[idx] = [pattern]
            ok = True
            for r, v in enumerate(pattern):
                if ng[r][idx] != UNKNOWN and ng[r][idx] != v:
                    ok = False
                    break
                ng[r][idx] = v
            if ok:
                ans = search(ng, nr, nc, row_clues, col_clues)
                if ans is not None:
                    return ans

    return None


def solve(observation):
    row_clues = observation['row_black_runs']
    col_clues = observation['col_black_runs']
    h = len(row_clues)
    w = len(col_clues)

    row_domains = [generate_line_patterns(w, clues) for clues in row_clues]
    col_domains = [generate_line_patterns(h, clues) for clues in col_clues]

    # Early infeasibility checks.
    if any(len(d) == 0 for d in row_domains) or any(len(d) == 0 for d in col_domains):
        return "No Solution"

    grid = [[UNKNOWN] * w for _ in range(h)]
    ans = search(grid, row_domains, col_domains, row_clues, col_clues)
    if ans is None:
        return "No Solution"

    rendered = [['B' if cell == BLACK else None for cell in row] for row in ans]
    return repr(rendered)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 2, None, 3, 3, 3, None, 2, None], [None, 5, None, 4, None, 3, None, 2, None, None], [3, 5, 2, None, None, None, 3, 2, None, None], [None, None, 2, 2, 3, None, None, 2, 2, 2], [None, 4, 5, None, 4, None, None, None, 2, None], [None, 4, 5, None, None, None, 3, None, 3, 3], [None, None, 6, 6, None, 4, None, 3, 3, None], [None, 6, 6, None, None, 5, 2, 2, 3, None], [None, None, None, 7, None, None, None, 0, 3, None], [3, 5, 4, None, None, 4, 2, 0, None, None]]}

from collections import deque, defaultdict

def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0
    nvars = h * w

    def vid(r, c):
        return r * w + c

    def rc(v):
        return divmod(v, w)

    # Build exact-sum constraints from numbered cells.
    constraints = []
    var_to_constraints = [[] for _ in range(nvars)]
    numbered_positions = []

    for r in range(h):
        for c in range(w):
            val = data[r][c]
            if val is None:
                continue
            cells = []
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    cells.append(vid(rr, cc))
            idx = len(constraints)
            constraints.append({
                "target": val,
                "vars": tuple(cells),
                "set": frozenset(cells),
            })
            numbered_positions.append((r, c))
            for v in cells:
                var_to_constraints[v].append(idx)

    # Precompute subset relations between constraint variable sets.
    # This is a strong "human-like" overlap rule:
    # if A subset B then sum(B\A) = target(B) - target(A), enabling extra forcing.
    subset_pairs = [[] for _ in range(len(constraints))]
    for i in range(len(constraints)):
        si = constraints[i]["set"]
        for j in range(len(constraints)):
            if i == j:
                continue
            sj = constraints[j]["set"]
            if si.issubset(sj):
                diff = tuple(sorted(sj - si))
                subset_pairs[i].append((j, diff))

    # Variable ordering score: number of nearby clues.
    var_static_score = [len(var_to_constraints[v]) for v in range(nvars)]

    def clone_state(assign, con):
        return assign[:], [x[:] for x in con]

    def init_state():
        # assign[v] = -1 unknown, 0 white, 1 black
        assign = [-1] * nvars
        # con[i] = [remaining_target, unknown_count, sum_assigned_black]
        # remaining_target is target - assigned_black among vars in constraint
        con = []
        for c in constraints:
            con.append([c["target"], len(c["vars"]), 0])
        return assign, con

    def set_var(assign, con, queue_vars, queue_cons, v, value):
        cur = assign[v]
        if cur == value:
            return True
        if cur != -1:
            return False
        assign[v] = value
        queue_vars.append(v)
        for ci in var_to_constraints[v]:
            row = con[ci]
            row[1] -= 1
            if value == 1:
                row[0] -= 1
                row[2] += 1
            queue_cons.append(ci)
        return True

    def force_from_constraint(assign, con, queue_vars, queue_cons, ci):
        rem, unk, _ = con[ci]
        if rem < 0 or rem > unk:
            return False
        if unk == 0:
            return rem == 0
        vars_ = constraints[ci]["vars"]
        if rem == 0 or rem == unk:
            value = 1 if rem == unk else 0
            for v in vars_:
                if assign[v] == -1:
                    if not set_var(assign, con, queue_vars, queue_cons, v, value):
                        return False
        return True

    def force_from_subset(assign, con, queue_vars, queue_cons, small_i, big_i, diff_vars):
        # Active residual relation:
        # residual(big) - residual(small) = blacks in diff + blacks in (small_known_black difference cancels via residuals)
        rem_s, unk_s, _ = con[small_i]
        rem_b, unk_b, _ = con[big_i]
        delta = rem_b - rem_s
        # Count only currently unknown vars in the set difference.
        active = [v for v in diff_vars if assign[v] == -1]
        known_black = sum(1 for v in diff_vars if assign[v] == 1)
        delta -= known_black
        # Now sum(active) == delta
        if delta < 0 or delta > len(active):
            return False
        if not active:
            return delta == 0
        if delta == 0 or delta == len(active):
            value = 1 if delta == len(active) else 0
            for v in active:
                if not set_var(assign, con, queue_vars, queue_cons, v, value):
                    return False
        return True

    def propagate(assign, con, initial_vars=None, initial_cons=None):
        queue_vars = deque(initial_vars or [])
        queue_cons = deque(initial_cons or range(len(constraints)))
        in_qc = [False] * len(constraints)
        for ci in queue_cons:
            in_qc[ci] = True

        while queue_cons or queue_vars:
            while queue_cons:
                ci = queue_cons.popleft()
                in_qc[ci] = False
                if not force_from_constraint(assign, con, queue_vars, queue_cons, ci):
                    return False
                # Overlap/subset deductions involving this constraint.
                for big_i, diff in subset_pairs[ci]:
                    if not force_from_subset(assign, con, queue_vars, queue_cons, ci, big_i, diff):
                        return False
                    if not in_qc[big_i]:
                        queue_cons.append(big_i)
                        in_qc[big_i] = True
                # Also if current is the larger set in some relation, re-check smaller ones.
                for small_i in range(len(constraints)):
                    if small_i == ci:
                        continue
                    if any(bi == ci for bi, _ in subset_pairs[small_i]):
                        for bi, diff in subset_pairs[small_i]:
                            if bi == ci:
                                if not force_from_subset(assign, con, queue_vars, queue_cons, small_i, ci, diff):
                                    return False
                                if not in_qc[small_i]:
                                    queue_cons.append(small_i)
                                    in_qc[small_i] = True
                                break
            while queue_vars:
                v = queue_vars.popleft()
                for ci in var_to_constraints[v]:
                    if not in_qc[ci]:
                        queue_cons.append(ci)
                        in_qc[ci] = True

        return True

    def unresolved_components(assign):
        # Build components of unknown variables connected through constraints.
        unknowns = [v for v in range(nvars) if assign[v] == -1 and var_to_constraints[v]]
        seen = set()
        comps = []
        for start in unknowns:
            if start in seen:
                continue
            q = deque([start])
            seen.add(start)
            comp_vars = set()
            comp_cons = set()
            while q:
                v = q.popleft()
                comp_vars.add(v)
                for ci in var_to_constraints[v]:
                    comp_cons.add(ci)
                    for u in constraints[ci]["vars"]:
                        if assign[u] == -1 and var_to_constraints[u] and u not in seen:
                            seen.add(u)
                            q.append(u)
            comps.append((comp_vars, comp_cons))
        return comps

    def choose_branch_var(assign, con):
        # Most constrained unknown variable:
        # maximize nearby clue count and pressure from tight constraints.
        best_v = None
        best_key = None
        for v in range(nvars):
            if assign[v] != -1:
                continue
            cids = var_to_constraints[v]
            if not cids:
                # unconstrained cells can safely be set white first
                key = (-1, -1, -1)
            else:
                tight = 0
                span = 0
                for ci in cids:
                    rem, unk, _ = con[ci]
                    tight += min(rem, unk - rem)
                    span += unk
                key = (len(cids), -tight, -span)
            if best_key is None or key > best_key:
                best_key = key
                best_v = v
        return best_v

    def preferred_values(v, assign, con):
        # Bias by local clues: try value that best satisfies nearby residual densities.
        score_black = 0.0
        score_white = 0.0
        cids = var_to_constraints[v]
        if not cids:
            return (0, 1)
        for ci in cids:
            rem, unk, _ = con[ci]
            if unk <= 0:
                continue
            p_black = rem / unk
            score_black += p_black
            score_white += 1.0 - p_black
        return (1, 0) if score_black >= score_white else (0, 1)

    def finalize_grid(assign):
        # Any cell not forced by clues can be white.
        out = []
        for r in range(h):
            row = []
            for c in range(w):
                v = vid(r, c)
                val = assign[v]
                if val == 1:
                    row.append('B')
                else:
                    row.append(None)
            out.append(row)
        return out

    def search(assign, con):
        if not propagate(assign, con):
            return None

        # Any unconstrained unknown cells can be fixed to white immediately.
        for v in range(nvars):
            if assign[v] == -1 and not var_to_constraints[v]:
                assign[v] = 0

        if all(v != -1 for v in assign):
            return assign

        # Decompose by connected components and solve smallest first.
        comps = unresolved_components(assign)
        if comps:
            comps.sort(key=lambda x: (len(x[0]), len(x[1])))
        # Pick a variable from the smallest/most constrained component.
        branch_v = None
        if comps:
            comp_vars, _ = comps[0]
            best_key = None
            for v in comp_vars:
                cids = var_to_constraints[v]
                tight = 0
                span = 0
                for ci in cids:
                    rem, unk, _ = con[ci]
                    tight += min(rem, unk - rem)
                    span += unk
                key = (len(cids), -tight, -span, var_static_score[v])
                if best_key is None or key > best_key:
                    best_key = key
                    branch_v = v
        if branch_v is None:
            branch_v = choose_branch_var(assign, con)
        if branch_v is None:
            return assign

        for value in preferred_values(branch_v, assign, con):
            assign2, con2 = clone_state(assign, con)
            if set_var(assign2, con2, deque(), deque(), branch_v, value):
                res = search(assign2, con2)
                if res is not None:
                    return res
        return None

    assign, con = init_state()
    result = search(assign, con)
    if result is None:
        return "No Solution"
    return repr(finalize_grid(result))

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 1], [0, 0, 0, 1, 1], [2, 0, 1, 1, 1], [2, 0, 1, 1, 1], [3, 3, 3, 3, 3]], 'row_stitch_counts': [2, 3, 3, 3, 3], 'col_stitch_counts': [4, 3, 2, 2, 3]}

from copy import deepcopy


def normalize_stitch(a, b):
    return (a, b) if a <= b else (b, a)


def build_model(observation):
    region = observation["region"]
    n = len(region)

    border_candidates = []
    stitch_to_idx = {}
    stitches = []

    def get_stitch_idx(h1, h2):
        s = normalize_stitch(h1, h2)
        if s not in stitch_to_idx:
            stitch_to_idx[s] = len(stitches)
            stitches.append(s)
        return stitch_to_idx[s]

    # Human-like abstraction:
    # For each border between different regions, exactly one stitch must be chosen.
    # A horizontal cell-border (between left/right neighboring cells) can be realized
    # by a stitch either on the hole-row above it or on the hole-row below it.
    # A vertical cell-border (between upper/lower neighboring cells) can be realized
    # by a stitch either on the hole-column left of it or on the hole-column right of it.
    for r in range(n):
        for c in range(n - 1):
            if region[r][c] != region[r][c + 1]:
                cand = []
                if 0 <= r < n and 0 <= c < n - 1:
                    cand.append(get_stitch_idx((r, c), (r, c + 1)))
                if 0 <= r + 1 < n and 0 <= c < n - 1:
                    cand.append(get_stitch_idx((r + 1, c), (r + 1, c + 1)))
                cand = sorted(set(cand))
                if not cand:
                    return None
                border_candidates.append(tuple(cand))

    for r in range(n - 1):
        for c in range(n):
            if region[r][c] != region[r + 1][c]:
                cand = []
                if 0 <= r < n - 1 and 0 <= c < n:
                    cand.append(get_stitch_idx((r, c), (r + 1, c)))
                if 0 <= r < n - 1 and 0 <= c + 1 < n:
                    cand.append(get_stitch_idx((r, c + 1), (r + 1, c + 1)))
                cand = sorted(set(cand))
                if not cand:
                    return None
                border_candidates.append(tuple(cand))

    hole_incident = {(r, c): [] for r in range(n) for c in range(n)}
    for i, (h1, h2) in enumerate(stitches):
        hole_incident[h1].append(i)
        hole_incident[h2].append(i)

    return {
        "n": n,
        "region": region,
        "row_counts": observation["row_stitch_counts"],
        "col_counts": observation["col_stitch_counts"],
        "stitches": stitches,
        "border_candidates": border_candidates,
        "hole_incident": hole_incident,
    }


class State:
    def __init__(self, model):
        self.model = model
        self.var = [-1] * len(model["stitches"])  # -1 unknown, 0 false, 1 true
        self.hole = {h: -1 for h in model["hole_incident"]}  # -1 unknown, 0 unused, 1 used

    def clone(self):
        s = State(self.model)
        s.var = self.var[:]
        s.hole = self.hole.copy()
        return s


def set_hole(state, hole, val, queue):
    cur = state.hole[hole]
    if cur == val:
        return True
    if cur != -1 and cur != val:
        return False
    state.hole[hole] = val
    queue.append(("hole", hole))
    return True


def set_var(state, idx, val, queue):
    cur = state.var[idx]
    if cur == val:
        return True
    if cur != -1 and cur != val:
        return False
    state.var[idx] = val
    queue.append(("var", idx))
    return True


def propagate(state):
    model = state.model
    n = model["n"]
    queue = []

    for i, v in enumerate(state.var):
        if v != -1:
            queue.append(("var", i))
    for h, v in state.hole.items():
        if v != -1:
            queue.append(("hole", h))

    changed = True
    while changed:
        changed = False

        while queue:
            typ, obj = queue.pop()

            if typ == "var":
                i = obj
                v = state.var[i]
                h1, h2 = model["stitches"][i]

                if v == 1:
                    # Stitch chosen => both endpoint holes used and no sharing.
                    if not set_hole(state, h1, 1, queue):
                        return False
                    if not set_hole(state, h2, 1, queue):
                        return False
                    for j in model["hole_incident"][h1]:
                        if j != i and not set_var(state, j, 0, queue):
                            return False
                    for j in model["hole_incident"][h2]:
                        if j != i and not set_var(state, j, 0, queue):
                            return False
                elif v == 0:
                    # Maybe this forces a hole unused if no remaining incident stitch.
                    for h in (h1, h2):
                        inc = model["hole_incident"][h]
                        vals = [state.var[j] for j in inc]
                        if 1 in vals:
                            if not set_hole(state, h, 1, queue):
                                return False
                        elif all(x == 0 for x in vals):
                            if not set_hole(state, h, 0, queue):
                                return False
                        elif state.hole[h] == 1:
                            undec = [j for j in inc if state.var[j] == -1]
                            if len(undec) == 0:
                                return False
                            if len(undec) == 1:
                                if not set_var(state, undec[0], 1, queue):
                                    return False

            else:
                h = obj
                hv = state.hole[h]
                inc = model["hole_incident"][h]
                vals = [state.var[j] for j in inc]

                if hv == 0:
                    for j in inc:
                        if not set_var(state, j, 0, queue):
                            return False
                elif hv == 1:
                    if 1 not in vals:
                        undec = [j for j in inc if state.var[j] == -1]
                        if len(undec) == 0:
                            return False
                        if len(undec) == 1:
                            if not set_var(state, undec[0], 1, queue):
                                return False

        # Border exact-one constraints
        for cand in model["border_candidates"]:
            ones = sum(1 for i in cand if state.var[i] == 1)
            undec = [i for i in cand if state.var[i] == -1]
            if ones > 1:
                return False
            if ones == 0 and not undec:
                return False
            if ones == 1:
                for i in undec:
                    if not set_var(state, i, 0, queue):
                        return False
                        # queue non-empty means more propagation
                if undec:
                    changed = True
            elif len(undec) == 1:
                if not set_var(state, undec[0], 1, queue):
                    return False
                changed = True

        # Hole local consistency
        for h, inc in model["hole_incident"].items():
            vals = [state.var[j] for j in inc]
            ones = sum(1 for x in vals if x == 1)
            undec = [j for j in inc if state.var[j] == -1]

            if ones > 1:
                return False
            if ones == 1:
                if state.hole[h] == 0:
                    return False
                if state.hole[h] != 1:
                    if not set_hole(state, h, 1, queue):
                        return False
                    changed = True
                for j in undec:
                    if not set_var(state, j, 0, queue):
                        return False
                    changed = True
            else:
                if not undec:
                    if state.hole[h] == 1:
                        return False
                    if state.hole[h] != 0:
                        if not set_hole(state, h, 0, queue):
                            return False
                        changed = True
                else:
                    if state.hole[h] == 0:
                        for j in undec:
                            if not set_var(state, j, 0, queue):
                                return False
                            changed = True
                    elif state.hole[h] == 1 and len(undec) == 1:
                        if not set_var(state, undec[0], 1, queue):
                            return False
                        changed = True

        # Row/column clue propagation on used holes
        for r in range(n):
            holes = [(r, c) for c in range(n)]
            vals = [state.hole[h] for h in holes]
            used = sum(1 for x in vals if x == 1)
            unk = [h for h in holes if state.hole[h] == -1]
            target = model["row_counts"][r]
            if used > target:
                return False
            if used + len(unk) < target:
                return False
            if used == target:
                for h in unk:
                    if not set_hole(state, h, 0, queue):
                        return False
                    changed = True
            elif used + len(unk) == target:
                for h in unk:
                    if not set_hole(state, h, 1, queue):
                        return False
                    changed = True

        for c in range(n):
            holes = [(r, c) for r in range(n)]
            vals = [state.hole[h] for h in holes]
            used = sum(1 for x in vals if x == 1)
            unk = [h for h in holes if state.hole[h] == -1]
            target = model["col_counts"][c]
            if used > target:
                return False
            if used + len(unk) < target:
                return False
            if used == target:
                for h in unk:
                    if not set_hole(state, h, 0, queue):
                        return False
                    changed = True
            elif used + len(unk) == target:
                for h in unk:
                    if not set_hole(state, h, 1, queue):
                        return False
                    changed = True

    return True


def is_solved(state):
    model = state.model

    if any(v == -1 for v in state.var):
        return False
    if any(v == -1 for v in state.hole.values()):
        return False

    for cand in model["border_candidates"]:
        if sum(state.var[i] for i in cand) != 1:
            return False

    n = model["n"]
    for r in range(n):
        if sum(state.hole[(r, c)] for c in range(n)) != model["row_counts"][r]:
            return False
    for c in range(n):
        if sum(state.hole[(r, c)] for r in range(n)) != model["col_counts"][c]:
            return False

    return True


def choose_branch(state):
    model = state.model

    # Most human-like branching:
    # 1) unresolved border with 2 candidates
    # 2) used-hole ambiguity with few incident stitches
    # 3) remaining stitch
    best = None

    for cand in model["border_candidates"]:
        ones = sum(1 for i in cand if state.var[i] == 1)
        undec = [i for i in cand if state.var[i] == -1]
        if ones == 0 and len(undec) >= 2:
            score = (0, len(undec))
            if best is None or score < best[0]:
                best = (score, ("border", undec))

    if best is not None:
        return best[1]

    for h, inc in model["hole_incident"].items():
        if state.hole[h] == -1:
            undec = [i for i in inc if state.var[i] == -1]
            if undec:
                score = (1, len(undec))
                if best is None or score < best[0]:
                    best = (score, ("hole", h, undec))

    if best is not None:
        return best[1]

    for i, v in enumerate(state.var):
        if v == -1:
            return ("var", i)

    return None


def search(state):
    if not propagate(state):
        return None
    if is_solved(state):
        return state

    branch = choose_branch(state)
    if branch is None:
        return None

    if branch[0] == "border":
        undec = branch[1]
        # Try each candidate stitch for this border; force others off.
        for chosen in undec:
            ns = state.clone()
            q = []
            ok = set_var(ns, chosen, 1, q)
            for i in undec:
                if i != chosen:
                    ok = ok and set_var(ns, i, 0, q)
            if ok:
                res = search(ns)
                if res is not None:
                    return res
        return None

    if branch[0] == "hole":
        h, undec = branch[1], branch[2]
        # Prefer setting hole by choosing one supporting stitch first, then try unused.
        for chosen in undec:
            ns = state.clone()
            q = []
            if set_hole(ns, h, 1, q) and set_var(ns, chosen, 1, q):
                res = search(ns)
                if res is not None:
                    return res
        ns = state.clone()
        q = []
        if set_hole(ns, h, 0, q):
            res = search(ns)
            if res is not None:
                return res
        return None

    if branch[0] == "var":
        i = branch[1]
        for val in (1, 0):
            ns = state.clone()
            q = []
            if set_var(ns, i, val, q):
                res = search(ns)
                if res is not None:
                    return res
        return None

    return None


def solve(observation):
    model = build_model(observation)
    if model is None:
        return "No Solution"

    state = State(model)
    result = search(state)
    if result is None:
        return "No Solution"

    answer = []
    for i, v in enumerate(result.var):
        if v == 1:
            h1, h2 = model["stitches"][i]
            answer.append([h1, h2])
    answer.sort()
    return str(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

