# General Latin / Jigsaw Sudoku solver for NxN with symbols 1..N.
# Emphasis:
# - strong propagation
# - human-like deductions first
# - tightly pruned search only when necessary

from copy import deepcopy

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(r) != n for r in data) or any(len(r) != n for r in region):
        return "No Solution"

    digits = tuple(range(1, n + 1))
    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def bits_to_values(mask):
        vals = []
        v = 1
        while mask:
            if mask & 1:
                vals.append(v)
            mask >>= 1
            v += 1
        return vals

    def popcount(x):
        return x.bit_count()

    # Build units
    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]

    region_ids = sorted({region[r][c] for r in range(n) for c in range(n)})
    if len(region_ids) != n:
        return "No Solution"

    reg_map = {rid: [] for rid in region_ids}
    for r in range(n):
        for c in range(n):
            reg_map[region[r][c]].append((r, c))

    if any(len(cells) != n for cells in reg_map.values()):
        return "No Solution"

    regs = [reg_map[rid] for rid in region_ids]

    # Cell -> units
    cell_units = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            reg_index = region_ids.index(rid)
            cell_units[(r, c)] = (r, c, reg_index)

    # Peers
    peers = {}
    for r in range(n):
        for c in range(n):
            rr, cc, rg = cell_units[(r, c)]
            s = set(rows[rr]) | set(cols[cc]) | set(regs[rg])
            s.discard((r, c))
            peers[(r, c)] = tuple(s)

    # Domains
    domains = [[full_mask for _ in range(n)] for _ in range(n)]

    def assign(dom, r, c, v):
        m = bit(v)
        if not (dom[r][c] & m):
            return False
        if dom[r][c] == m:
            return True
        dom[r][c] = m
        return True

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                if not assign(domains, r, c, v):
                    return "No Solution"

    unit_list = rows + cols + regs

    def unit_masks(dom, unit):
        used = 0
        for r, c in unit:
            if popcount(dom[r][c]) == 1:
                used |= dom[r][c]
        return used

    def eliminate_solved_from_peers(dom):
        changed = False
        queue = [(r, c) for r in range(n) for c in range(n) if popcount(dom[r][c]) == 1]
        seen = set()
        while queue:
            r, c = queue.pop()
            if (r, c, dom[r][c]) in seen:
                continue
            seen.add((r, c, dom[r][c]))
            m = dom[r][c]
            for pr, pc in peers[(r, c)]:
                old = dom[pr][pc]
                if old & m:
                    new = old & ~m
                    if new == 0:
                        return False, changed
                    if new != old:
                        dom[pr][pc] = new
                        changed = True
                        if popcount(new) == 1:
                            queue.append((pr, pc))
        return True, changed

    def contradiction(dom):
        # Empty cell domains
        for r in range(n):
            for c in range(n):
                if dom[r][c] == 0:
                    return True
        # Duplicate solved values in a unit or impossible value placement
        for unit in unit_list:
            seen = 0
            avail = 0
            for r, c in unit:
                m = dom[r][c]
                if popcount(m) == 1:
                    if seen & m:
                        return True
                    seen |= m
                avail |= m
            if avail != full_mask:
                return True
        return False

    def hidden_singles(dom):
        changed = False
        for unit in unit_list:
            places = [0] * (n + 1)
            lastpos = [None] * (n + 1)
            for r, c in unit:
                m = dom[r][c]
                for v in bits_to_values(m):
                    places[v] += 1
                    lastpos[v] = (r, c)
            for v in digits:
                if places[v] == 0:
                    return False, changed
                if places[v] == 1:
                    r, c = lastpos[v]
                    m = bit(v)
                    if dom[r][c] != m:
                        dom[r][c] = m
                        changed = True
        return True, changed

    def naked_subsets(dom):
        changed = False
        # If k cells in a unit share exactly k candidates, remove them from others.
        for unit in unit_list:
            buckets = {}
            for r, c in unit:
                m = dom[r][c]
                pc = popcount(m)
                if 2 <= pc <= 4:
                    buckets.setdefault(m, []).append((r, c))
            for m, cells in buckets.items():
                k = popcount(m)
                if len(cells) == k:
                    for r, c in unit:
                        if (r, c) not in cells:
                            old = dom[r][c]
                            new = old & ~m
                            if new == 0:
                                return False, changed
                            if new != old:
                                dom[r][c] = new
                                changed = True
        return True, changed

    def intersection_removal(dom):
        changed = False
        # Row-region and col-region interactions
        for reg_index, reg_cells in enumerate(regs):
            for v in digits:
                m = bit(v)
                poss = [(r, c) for r, c in reg_cells if dom[r][c] & m]
                if not poss:
                    return False, changed
                rows_used = {r for r, _ in poss}
                cols_used = {c for _, c in poss}
                if len(rows_used) == 1:
                    rr = next(iter(rows_used))
                    for r, c in rows[rr]:
                        if region[r][c] != region_ids[reg_index] and (dom[r][c] & m):
                            new = dom[r][c] & ~m
                            if new == 0:
                                return False, changed
                            if new != dom[r][c]:
                                dom[r][c] = new
                                changed = True
                if len(cols_used) == 1:
                    cc = next(iter(cols_used))
                    for r, c in cols[cc]:
                        if region[r][c] != region_ids[reg_index] and (dom[r][c] & m):
                            new = dom[r][c] & ~m
                            if new == 0:
                                return False, changed
                            if new != dom[r][c]:
                                dom[r][c] = new
                                changed = True

        for r in range(n):
            for v in digits:
                m = bit(v)
                poss = [(rr, cc) for rr, cc in rows[r] if dom[rr][cc] & m]
                regs_used = {region[rr][cc] for rr, cc in poss}
                if len(regs_used) == 1 and poss:
                    rid = next(iter(regs_used))
                    for rr, cc in reg_map[rid]:
                        if rr != r and (dom[rr][cc] & m):
                            new = dom[rr][cc] & ~m
                            if new == 0:
                                return False, changed
                            if new != dom[rr][cc]:
                                dom[rr][cc] = new
                                changed = True
        for c in range(n):
            for v in digits:
                m = bit(v)
                poss = [(rr, cc) for rr, cc in cols[c] if dom[rr][cc] & m]
                regs_used = {region[rr][cc] for rr, cc in poss}
                if len(regs_used) == 1 and poss:
                    rid = next(iter(regs_used))
                    for rr, cc in reg_map[rid]:
                        if cc != c and (dom[rr][cc] & m):
                            new = dom[rr][cc] & ~m
                            if new == 0:
                                return False, changed
                            if new != dom[rr][cc]:
                                dom[rr][cc] = new
                                changed = True
        return True, changed

    def propagate(dom):
        while True:
            if contradiction(dom):
                return False

            any_change = False

            ok, ch = eliminate_solved_from_peers(dom)
            if not ok:
                return False
            any_change |= ch

            ok, ch = hidden_singles(dom)
            if not ok:
                return False
            any_change |= ch

            ok, ch = naked_subsets(dom)
            if not ok:
                return False
            any_change |= ch

            ok, ch = intersection_removal(dom)
            if not ok:
                return False
            any_change |= ch

            if contradiction(dom):
                return False

            if not any_change:
                return True

    def solved(dom):
        return all(popcount(dom[r][c]) == 1 for r in range(n) for c in range(n))

    def choose_branch_cell(dom):
        # Minimum remaining values, tie-break by most constrained neighborhood
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                pc = popcount(dom[r][c])
                if pc > 1:
                    peer_unsolved = sum(1 for pr, pc2 in peers[(r, c)] if popcount(dom[pr][pc2]) > 1)
                    key = (pc, -peer_unsolved)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def value_order(dom, r, c):
        # Least-constraining-value ordering
        opts = bits_to_values(dom[r][c])
        scored = []
        for v in opts:
            m = bit(v)
            impact = 0
            for pr, pc in peers[(r, c)]:
                if dom[pr][pc] & m:
                    impact += 1
            scored.append((impact, v))
        scored.sort()
        return [v for _, v in scored]

    def search(dom, depth=0):
        if not propagate(dom):
            return None
        if solved(dom):
            return dom

        cell = choose_branch_cell(dom)
        if cell is None:
            return dom
        r, c = cell

        for v in value_order(dom, r, c):
            nd = [row[:] for row in dom]
            nd[r][c] = bit(v)
            res = search(nd, depth + 1)
            if res is not None:
                return res
        return None

    result = search([row[:] for row in domains])
    if result is None:
        return "No Solution"

    grid = [[bits_to_values(result[r][c])[0] for c in range(n)] for r in range(n)]
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

