# Generalized solver for diagonal-loop puzzles ("Gokigen Naname"-style):
# - Each cell contains exactly one diagonal: '/' or '\'
# - Numbered dots require exactly that many incident diagonal endpoints
# - The chosen diagonals must form no cycle
#
# The solver combines:
# 1) exact-count propagation on each clue dot
# 2) immediate cycle-prevention using rollback DSU
# 3) informed branching on the most constrained/impactful undecided cell

class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.stack = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def connected(self, a, b):
        return self.find(a) == self.find(b)

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.stack.append((rb, self.parent[rb], ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        return True

    def snapshot(self):
        return len(self.stack)

    def rollback(self, snap):
        while len(self.stack) > snap:
            rb, old_parent_rb, ra, old_size_ra = self.stack.pop()
            self.parent[rb] = old_parent_rb
            self.size[ra] = old_size_ra


class Solver:
    SLASH = 1       # '/'
    BACKSLASH = 2   # '\'

    def __init__(self, observation):
        self.data = observation['data']
        self.Rp = len(self.data)
        self.Cp = len(self.data[0])
        self.NR = self.Rp - 1
        self.NC = self.Cp - 1
        self.num_cells = self.NR * self.NC
        self.num_dots = self.Rp * self.Cp

        self.domains = [self.SLASH | self.BACKSLASH for _ in range(self.num_cells)]
        self.trail = []
        self.dsu = RollbackDSU(self.num_dots)

        # For each cell, endpoints for each orientation.
        self.cell_edges = [None] * self.num_cells
        # For each dot, list of (cell_idx, touch_mask) where touch_mask is the orientation that touches the dot.
        self.dot_incidents = [[] for _ in range(self.num_dots)]
        # Clue dots only.
        self.clue_dots = []

        for r in range(self.NR):
            for c in range(self.NC):
                idx = self.cell_index(r, c)
                # '/' connects (r, c+1) to (r+1, c)
                e_slash = (self.dot_index(r, c + 1), self.dot_index(r + 1, c))
                # '\' connects (r, c) to (r+1, c+1)
                e_back = (self.dot_index(r, c), self.dot_index(r + 1, c + 1))
                self.cell_edges[idx] = {
                    self.SLASH: e_slash,
                    self.BACKSLASH: e_back,
                }

                # Dot incidences
                self.dot_incidents[self.dot_index(r, c + 1)].append((idx, self.SLASH))
                self.dot_incidents[self.dot_index(r + 1, c)].append((idx, self.SLASH))
                self.dot_incidents[self.dot_index(r, c)].append((idx, self.BACKSLASH))
                self.dot_incidents[self.dot_index(r + 1, c + 1)].append((idx, self.BACKSLASH))

        for r in range(self.Rp):
            for c in range(self.Cp):
                if self.data[r][c] is not None:
                    self.clue_dots.append(self.dot_index(r, c))

        self.cell_scores = self._build_cell_scores()

    def dot_index(self, r, c):
        return r * self.Cp + c

    def cell_index(self, r, c):
        return r * self.NC + c

    def rc_from_cell(self, idx):
        return divmod(idx, self.NC)

    def is_singleton(self, mask):
        return mask == self.SLASH or mask == self.BACKSLASH

    def singleton_value(self, mask):
        return mask

    def _build_cell_scores(self):
        scores = [0] * self.num_cells
        for idx in range(self.num_cells):
            score = 0
            for orient in (self.SLASH, self.BACKSLASH):
                a, b = self.cell_edges[idx][orient]
                for d in (a, b):
                    rr, cc = divmod(d, self.Cp)
                    clue = self.data[rr][cc]
                    if clue is not None:
                        score += 4
                        score += abs(2 - clue)
            scores[idx] = score
        return scores

    def push_domain(self, cell, new_mask):
        old = self.domains[cell]
        if old == new_mask:
            return True
        if new_mask == 0:
            return False
        old_single = self.is_singleton(old)
        new_single = self.is_singleton(new_mask)
        self.trail.append((cell, old))
        self.domains[cell] = new_mask

        if (not old_single) and new_single:
            orient = self.singleton_value(new_mask)
            a, b = self.cell_edges[cell][orient]
            if self.dsu.connected(a, b):
                return False
            self.dsu.union(a, b)
        return True

    def force_orientation(self, cell, orient):
        if not (self.domains[cell] & orient):
            return False
        return self.push_domain(cell, orient)

    def forbid_orientation(self, cell, orient):
        if not (self.domains[cell] & orient):
            return True
        return self.push_domain(cell, self.domains[cell] & ~orient)

    def snapshot(self):
        return (len(self.trail), self.dsu.snapshot())

    def rollback(self, snap):
        trail_len, dsu_snap = snap
        while len(self.trail) > trail_len:
            cell, old = self.trail.pop()
            self.domains[cell] = old
        self.dsu.rollback(dsu_snap)

    def propagate(self):
        while True:
            changed_before = len(self.trail)

            # Rule 1: No cycle may be completed. If one orientation would connect
            # two already-connected dots, that orientation is impossible.
            for cell in range(self.num_cells):
                mask = self.domains[cell]
                if self.is_singleton(mask):
                    continue
                for orient in (self.SLASH, self.BACKSLASH):
                    if mask & orient:
                        a, b = self.cell_edges[cell][orient]
                        if self.dsu.connected(a, b):
                            if not self.forbid_orientation(cell, orient):
                                return False

            # Rule 2: Exact clue accounting at each numbered dot.
            for d in self.clue_dots:
                rr, cc = divmod(d, self.Cp)
                clue = self.data[rr][cc]

                assigned_touch = 0
                possible_touch = 0
                undecided = []

                for cell, touch_orient in self.dot_incidents[d]:
                    mask = self.domains[cell]
                    if self.is_singleton(mask):
                        if mask == touch_orient:
                            assigned_touch += 1
                            possible_touch += 1
                    else:
                        if mask & touch_orient:
                            possible_touch += 1
                        undecided.append((cell, touch_orient, mask))

                if assigned_touch > clue or possible_touch < clue:
                    return False

                need_more = clue - assigned_touch
                avail_more = possible_touch - assigned_touch

                # If clue is already satisfied, nobody else may touch.
                if need_more == 0:
                    for cell, touch_orient, mask in undecided:
                        if mask & touch_orient:
                            if not self.forbid_orientation(cell, touch_orient):
                                return False

                # If all possible touches are required, force them all.
                if need_more == avail_more:
                    for cell, touch_orient, mask in undecided:
                        if mask & touch_orient:
                            if not self.force_orientation(cell, touch_orient):
                                return False

            if len(self.trail) == changed_before:
                break
        return True

    def solved(self):
        return all(self.is_singleton(m) for m in self.domains)

    def choose_branch_cell(self):
        best = None
        best_key = None
        for cell in range(self.num_cells):
            mask = self.domains[cell]
            if self.is_singleton(mask):
                continue

            # Both orientations usually present; compute a stronger heuristic.
            slash_edge = self.cell_edges[cell][self.SLASH]
            back_edge = self.cell_edges[cell][self.BACKSLASH]

            slash_blocked = 1 if self.dsu.connected(*slash_edge) else 0
            back_blocked = 1 if self.dsu.connected(*back_edge) else 0

            # Higher score => branch earlier.
            score = self.cell_scores[cell] + 10 * (slash_blocked + back_blocked)
            # Smaller key is better, so negate score.
            key = (-score, cell)

            if best is None or key < best_key:
                best = cell
                best_key = key
        return best

    def orientation_order(self, cell):
        # Prefer orientations that satisfy more nearby clue pressure and are less cycle-risky.
        vals = []
        for orient in (self.SLASH, self.BACKSLASH):
            if not (self.domains[cell] & orient):
                continue
            a, b = self.cell_edges[cell][orient]
            score = 0
            for d in (a, b):
                rr, cc = divmod(d, self.Cp)
                clue = self.data[rr][cc]
                if clue is not None:
                    # Prefer using endpoints at larger clues.
                    score += clue + 1
            if self.dsu.connected(a, b):
                score -= 1000
            vals.append((-score, orient))
        vals.sort()
        return [orient for _, orient in vals]

    def search(self):
        if not self.propagate():
            return False
        if self.solved():
            return True

        cell = self.choose_branch_cell()
        if cell is None:
            return False

        for orient in self.orientation_order(cell):
            snap = self.snapshot()
            if self.force_orientation(cell, orient) and self.search():
                return True
            self.rollback(snap)

        return False

    def extract_answer(self):
        grid = []
        for r in range(self.NR):
            row = []
            for c in range(self.NC):
                mask = self.domains[self.cell_index(r, c)]
                if mask == self.SLASH:
                    row.append('/')
                elif mask == self.BACKSLASH:
                    row.append('\\')
                else:
                    row.append('?')
            grid.append(row)
        return grid


def solve(observation):
    solver = Solver(observation)
    if solver.search():
        return solver.extract_answer()
    return "No Solution"


