def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(r) != n for r in data) or any(len(r) != n for r in region):
        return "No Solution"

    full = (1 << n) - 1

    def bit_count(x):
        return x.bit_count()

    def digit_to_bit(d):
        return 1 << (d - 1)

    def mask_to_digits(mask):
        d = 1
        while mask:
            lb = mask & -mask
            yield lb.bit_length()
            mask ^= lb
            d += 1

    # Build units
    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]

    region_cells = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            region_cells.setdefault(rid, []).append(r * n + c)
    if len(region_cells) != n or any(len(cells) != n for cells in region_cells.values()):
        return "No Solution"

    regs = [region_cells[rid] for rid in sorted(region_cells)]
    units = rows + cols + regs
    cell_units = [[] for _ in range(n * n)]
    for ui, unit in enumerate(units):
        for cell in unit:
            cell_units[cell].append(ui)

    peers = []
    for cell in range(n * n):
        s = set()
        for ui in cell_units[cell]:
            s.update(units[ui])
        s.discard(cell)
        peers.append(tuple(s))

    row_of = [i // n for i in range(n * n)]
    col_of = [i % n for i in range(n * n)]
    reg_index = {}
    for ridx, unit in enumerate(regs):
        for cell in unit:
            reg_index[cell] = ridx

    masks = [full] * (n * n)
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                masks[r * n + c] = digit_to_bit(v)

    def assign(masks, cell, bit):
        cur = masks[cell]
        if cur == bit:
            return True
        if not (cur & bit):
            return False
        masks[cell] = bit
        return True

    def propagate(masks):
        changed = True
        while changed:
            changed = False

            # 1) Basic elimination from solved cells
            solved = [i for i, m in enumerate(masks) if m and (m & (m - 1)) == 0]
            for cell in solved:
                bit = masks[cell]
                for p in peers[cell]:
                    pm = masks[p]
                    if pm & bit:
                        nm = pm & ~bit
                        if nm == 0:
                            return False
                        if nm != pm:
                            masks[p] = nm
                            changed = True

            # 2) Unit checks + hidden singles
            for unit in units:
                seen_singles = 0
                loc = [0] * n
                count = [0] * n
                for cell in unit:
                    m = masks[cell]
                    if m == 0:
                        return False
                    if (m & (m - 1)) == 0:
                        if seen_singles & m:
                            return False
                        seen_singles |= m
                    mm = m
                    while mm:
                        lb = mm & -mm
                        d = lb.bit_length() - 1
                        count[d] += 1
                        loc[d] = cell
                        mm ^= lb
                if bit_count(seen_singles) != sum(1 for cell in unit if (masks[cell] & (masks[cell] - 1)) == 0):
                    return False
                for d in range(n):
                    if count[d] == 0:
                        return False
                    if count[d] == 1:
                        bit = 1 << d
                        cell = loc[d]
                        if masks[cell] != bit:
                            masks[cell] = bit
                            changed = True

            # 3) Locked candidates: region -> row/col, and row/col -> region
            # region -> row/col
            for ridx, unit in enumerate(regs):
                for d in range(n):
                    bit = 1 << d
                    cells = [cell for cell in unit if masks[cell] & bit]
                    if not cells:
                        return False
                    rows_used = {row_of[cell] for cell in cells}
                    cols_used = {col_of[cell] for cell in cells}
                    if len(rows_used) == 1:
                        rr = next(iter(rows_used))
                        for cell in rows[rr]:
                            if reg_index[cell] != ridx and (masks[cell] & bit):
                                nm = masks[cell] & ~bit
                                if nm == 0:
                                    return False
                                masks[cell] = nm
                                changed = True
                    if len(cols_used) == 1:
                        cc = next(iter(cols_used))
                        for cell in cols[cc]:
                            if reg_index[cell] != ridx and (masks[cell] & bit):
                                nm = masks[cell] & ~bit
                                if nm == 0:
                                    return False
                                masks[cell] = nm
                                changed = True

            # row/col -> region
            for unit_group in (rows, cols):
                for uidx, unit in enumerate(unit_group):
                    for d in range(n):
                        bit = 1 << d
                        cells = [cell for cell in unit if masks[cell] & bit]
                        if not cells:
                            return False
                        regs_used = {reg_index[cell] for cell in cells}
                        if len(regs_used) == 1:
                            ridx = next(iter(regs_used))
                            for cell in regs[ridx]:
                                if cell not in unit and (masks[cell] & bit):
                                    nm = masks[cell] & ~bit
                                    if nm == 0:
                                        return False
                                    masks[cell] = nm
                                    changed = True

            # 4) Naked pairs/triples/quads by exact mask repetition
            for unit in units:
                freq = {}
                for cell in unit:
                    m = masks[cell]
                    bc = bit_count(m)
                    if 2 <= bc <= 4:
                        freq.setdefault(m, []).append(cell)
                for m, cells in freq.items():
                    k = bit_count(m)
                    if len(cells) == k:
                        for cell in unit:
                            if cell not in cells and (masks[cell] & m):
                                nm = masks[cell] & ~m
                                if nm == 0:
                                    return False
                                masks[cell] = nm
                                changed = True

            # 5) Contradiction check
            for m in masks:
                if m == 0:
                    return False

        return True

    def solved(masks):
        return all(m and (m & (m - 1)) == 0 for m in masks)

    def choose_cell(masks):
        best = -1
        best_count = n + 1
        best_score = -1
        for i, m in enumerate(masks):
            bc = bit_count(m)
            if 1 < bc < best_count:
                # More constrained peers first
                score = sum(bit_count(masks[p]) for p in peers[i] if bit_count(masks[p]) > 1)
                best = i
                best_count = bc
                best_score = score
            elif 1 < bc == best_count:
                score = sum(bit_count(masks[p]) for p in peers[i] if bit_count(masks[p]) > 1)
                if score > best_score:
                    best = i
                    best_score = score
        return best

    def candidate_order(masks, cell):
        # Least-constraining value ordering
        opts = []
        m = masks[cell]
        while m:
            bit = m & -m
            impact = 0
            for p in peers[cell]:
                if masks[p] & bit:
                    impact += 1
            opts.append((impact, bit))
            m ^= bit
        opts.sort()
        return [bit for _, bit in opts]

    def search(masks):
        if not propagate(masks):
            return None
        if solved(masks):
            return masks

        cell = choose_cell(masks)
        if cell < 0:
            return None

        for bit in candidate_order(masks, cell):
            nm = masks[:]
            if assign(nm, cell, bit):
                res = search(nm)
                if res is not None:
                    return res
        return None

    result = search(masks)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            m = result[r * n + c]
            if m == 0 or (m & (m - 1)) != 0:
                return "No Solution"
            row.append(m.bit_length())
        grid.append(row)
    return str(grid)


