from copy import deepcopy

def solve(observation):
    data = observation["data"]
    unit = observation["unit"]

    if "x" in unit:
        br, bc = map(int, unit.split("x"))
    else:
        br = bc = int(unit)

    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"
    if br * bc != n:
        return "No Solution"

    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def single_value(mask):
        return mask.bit_length()

    def iter_values(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length()
            mask ^= lsb

    cells = [(r, c) for r in range(n) for c in range(n)]

    row_units = [[(r, c) for c in range(n)] for r in range(n)]
    col_units = [[(r, c) for r in range(n)] for c in range(n)]
    box_units = []
    for r0 in range(0, n, br):
        for c0 in range(0, n, bc):
            box_units.append([(r, c) for r in range(r0, r0 + br) for c in range(c0, c0 + bc)])
    units = row_units + col_units + box_units

    cell_units = {}
    box_index = {}
    bi = 0
    for r0 in range(0, n, br):
        for c0 in range(0, n, bc):
            for r in range(r0, r0 + br):
                for c in range(c0, c0 + bc):
                    box_index[(r, c)] = bi
            bi += 1

    for r in range(n):
        for c in range(n):
            cell_units[(r, c)] = [row_units[r], col_units[c], box_units[box_index[(r, c)]]]

    peers = {}
    for r in range(n):
        for c in range(n):
            s = set()
            for u in cell_units[(r, c)]:
                s.update(u)
            s.discard((r, c))
            peers[(r, c)] = tuple(s)

    def initial_state():
        masks = [[full for _ in range(n)] for _ in range(n)]
        for r in range(n):
            for c in range(n):
                v = data[r][c]
                if v is not None:
                    if not (1 <= v <= n):
                        return None
                    masks[r][c] = bit(v)
        return masks

    def assign(masks, r, c, value_mask):
        current = masks[r][c]
        if current == value_mask:
            return True
        if not (current & value_mask):
            return False
        masks[r][c] = value_mask
        return True

    def eliminate_mask(masks, r, c, remove_mask):
        current = masks[r][c]
        new = current & ~remove_mask
        if new == current:
            return True, False
        if new == 0:
            return False, False
        masks[r][c] = new
        return True, True

    def propagate(masks):
        changed = True
        while changed:
            changed = False

            # Peer elimination from solved cells
            solved = [(r, c, masks[r][c]) for r in range(n) for c in range(n) if popcount(masks[r][c]) == 1]
            for r, c, m in solved:
                for pr, pc in peers[(r, c)]:
                    ok, did = eliminate_mask(masks, pr, pc, m)
                    if not ok:
                        return False
                    changed |= did

            # Unit validation + hidden singles
            for unit_cells in units:
                seen = 0
                for r, c in unit_cells:
                    m = masks[r][c]
                    if popcount(m) == 1:
                        if seen & m:
                            return False
                        seen |= m

                for d in range(1, n + 1):
                    dm = bit(d)
                    places = []
                    for r, c in unit_cells:
                        if masks[r][c] & dm:
                            places.append((r, c))
                    if not places:
                        return False
                    if len(places) == 1:
                        r, c = places[0]
                        if masks[r][c] != dm:
                            if not assign(masks, r, c, dm):
                                return False
                            changed = True

            # Locked candidates: box -> row/col
            for bcells in box_units:
                for d in range(1, n + 1):
                    dm = bit(d)
                    places = [(r, c) for r, c in bcells if masks[r][c] & dm]
                    if len(places) <= 1:
                        continue
                    rows = {r for r, _ in places}
                    cols = {c for _, c in places}
                    if len(rows) == 1:
                        rr = next(iter(rows))
                        for r, c in row_units[rr]:
                            if (r, c) not in bcells:
                                ok, did = eliminate_mask(masks, r, c, dm)
                                if not ok:
                                    return False
                                changed |= did
                    if len(cols) == 1:
                        cc = next(iter(cols))
                        for r, c in col_units[cc]:
                            if (r, c) not in bcells:
                                ok, did = eliminate_mask(masks, r, c, dm)
                                if not ok:
                                    return False
                                changed |= did

            # Locked candidates: row/col -> box
            for r in range(n):
                unit_cells = row_units[r]
                for d in range(1, n + 1):
                    dm = bit(d)
                    places = [(rr, cc) for rr, cc in unit_cells if masks[rr][cc] & dm]
                    if len(places) <= 1:
                        continue
                    boxes = {box_index[p] for p in places}
                    if len(boxes) == 1:
                        b = next(iter(boxes))
                        for rr, cc in box_units[b]:
                            if rr != r:
                                ok, did = eliminate_mask(masks, rr, cc, dm)
                                if not ok:
                                    return False
                                changed |= did

            for c in range(n):
                unit_cells = col_units[c]
                for d in range(1, n + 1):
                    dm = bit(d)
                    places = [(rr, cc) for rr, cc in unit_cells if masks[rr][cc] & dm]
                    if len(places) <= 1:
                        continue
                    boxes = {box_index[p] for p in places}
                    if len(boxes) == 1:
                        b = next(iter(boxes))
                        for rr, cc in box_units[b]:
                            if cc != c:
                                ok, did = eliminate_mask(masks, rr, cc, dm)
                                if not ok:
                                    return False
                                changed |= did

            # Naked pairs
            for unit_cells in units:
                pair_locs = {}
                for r, c in unit_cells:
                    m = masks[r][c]
                    if popcount(m) == 2:
                        pair_locs.setdefault(m, []).append((r, c))
                for pm, locs in pair_locs.items():
                    if len(locs) == 2:
                        for r, c in unit_cells:
                            if (r, c) not in locs:
                                ok, did = eliminate_mask(masks, r, c, pm)
                                if not ok:
                                    return False
                                changed |= did

            # Optional compact subset rule for triples when unit is small enough
            for unit_cells in units:
                unsolved = [(r, c, masks[r][c]) for r, c in unit_cells if 2 <= popcount(masks[r][c]) <= 3]
                k = len(unsolved)
                if k >= 3:
                    for i in range(k):
                        for j in range(i + 1, k):
                            for t in range(j + 1, k):
                                combo = [unsolved[i], unsolved[j], unsolved[t]]
                                union = combo[0][2] | combo[1][2] | combo[2][2]
                                if popcount(union) == 3:
                                    locs = {(combo[0][0], combo[0][1]), (combo[1][0], combo[1][1]), (combo[2][0], combo[2][1])}
                                    for r, c in unit_cells:
                                        if (r, c) not in locs:
                                            ok, did = eliminate_mask(masks, r, c, union)
                                            if not ok:
                                                return False
                                            changed |= did

            # Final contradiction scan
            for r in range(n):
                for c in range(n):
                    if masks[r][c] == 0:
                        return False

        return True

    def is_solved(masks):
        return all(popcount(masks[r][c]) == 1 for r in range(n) for c in range(n))

    def select_branch_cell(masks):
        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                m = masks[r][c]
                cnt = popcount(m)
                if cnt > 1:
                    impact = 0
                    for pr, pc in peers[(r, c)]:
                        impact += popcount(masks[pr][pc])
                    score = (cnt, -impact)
                    if best is None or score < best_score:
                        best = (r, c)
                        best_score = score
        return best

    def value_order(masks, r, c):
        # Least-constraining value
        vals = []
        for v in iter_values(masks[r][c]):
            vm = bit(v)
            pressure = 0
            for pr, pc in peers[(r, c)]:
                if masks[pr][pc] & vm:
                    pressure += 1
            vals.append((pressure, v))
        vals.sort()
        return [v for _, v in vals]

    def search(masks):
        if not propagate(masks):
            return None
        if is_solved(masks):
            return masks

        cell = select_branch_cell(masks)
        if cell is None:
            return None
        r, c = cell

        for v in value_order(masks, r, c):
            new_masks = [row[:] for row in masks]
            if assign(new_masks, r, c, bit(v)):
                result = search(new_masks)
                if result is not None:
                    return result
        return None

    masks = initial_state()
    if masks is None:
        return "No Solution"

    result = search(masks)
    if result is None:
        return "No Solution"

    solved_grid = [[single_value(result[r][c]) for c in range(n)] for r in range(n)]
    return str(solved_grid)


