# General irregular Latin/Sudoku solver with strong propagation.
# It models human-style deduction:
# - direct singles
# - hidden singles in row/column/region
# - locked-set style elimination via naked subsets in each house
# - fish-free but strong MRV branching only when logic stalls

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(r) != n for r in data) or any(len(r) != n for r in region):
        return "No Solution"

    symbols = list(range(1, n + 1))
    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def mask_to_values(mask):
        out = []
        while mask:
            b = mask & -mask
            out.append(b.bit_length())
            mask ^= b
        return out

    def popcount(x):
        return x.bit_count()

    # Validate and normalize region ids
    region_cells = {}
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            region_cells.setdefault(rid, []).append((r, c))

    # Regions should partition into n groups of size n for a valid puzzle.
    # If IDs are not 0..n-1, remap them; if sizes are inconsistent, still attempt solve.
    ids = sorted(region_cells)
    id_map = {rid: i for i, rid in enumerate(ids)}
    region2 = [[id_map[region[r][c]] for c in range(n)] for r in range(n)]
    region = region2
    region_cells = {id_map[rid]: cells for rid, cells in region_cells.items()}

    rows = [[(r, c) for c in range(n)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(n)]
    regs = [region_cells[i] for i in range(len(region_cells))]

    if len(regs) != n:
        return "No Solution"
    if any(len(cells) != n for cells in regs):
        return "No Solution"

    houses = rows + cols + regs

    peers = [[set() for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            rid = region[r][c]
            s = set(rows[r]) | set(cols[c]) | set(regs[rid])
            s.discard((r, c))
            peers[r][c] = s

    board = [[0] * n for _ in range(n)]
    cand = [[full_mask] * n for _ in range(n)]

    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n

    def assign_initial(r, c, v):
        if not (1 <= v <= n):
            return False
        b = bit(v)
        rid = region[r][c]
        if row_used[r] & b or col_used[c] & b or reg_used[rid] & b:
            return False
        board[r][c] = v
        row_used[r] |= b
        col_used[c] |= b
        reg_used[rid] |= b
        cand[r][c] = b
        return True

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not assign_initial(r, c, v):
                    return "No Solution"

    for r in range(n):
        for c in range(n):
            if board[r][c] == 0:
                used = row_used[r] | col_used[c] | reg_used[region[r][c]]
                cand[r][c] = full_mask & ~used
                if cand[r][c] == 0:
                    return "No Solution"

    def clone_state():
        return (
            [row[:] for row in board],
            [row[:] for row in cand],
            row_used[:],
            col_used[:],
            reg_used[:],
        )

    def restore_state(state):
        nonlocal board, cand, row_used, col_used, reg_used
        board, cand, row_used, col_used, reg_used = state

    def place(r, c, v, queue):
        current = board[r][c]
        b = bit(v)
        rid = region[r][c]

        if current == v:
            return True
        if current != 0:
            return False
        if not (cand[r][c] & b):
            return False
        if row_used[r] & b or col_used[c] & b or reg_used[rid] & b:
            return False

        board[r][c] = v
        cand[r][c] = b
        row_used[r] |= b
        col_used[c] |= b
        reg_used[rid] |= b

        for rr, cc in peers[r][c]:
            if board[rr][cc] == 0 and (cand[rr][cc] & b):
                cand[rr][cc] &= ~b
                if cand[rr][cc] == 0:
                    return False
                if cand[rr][cc] & (cand[rr][cc] - 1) == 0:
                    queue.append((rr, cc))
        return True

    def propagate_singles(queue):
        while queue:
            r, c = queue.pop()
            if board[r][c] != 0:
                continue
            m = cand[r][c]
            if m == 0:
                return False
            if m & (m - 1):
                continue
            v = m.bit_length()
            if not place(r, c, v, queue):
                return False
        return True

    def hidden_singles(queue):
        changed = False
        for house in houses:
            missing_mask = full_mask
            for r, c in house:
                if board[r][c]:
                    missing_mask &= ~bit(board[r][c])
            mm = missing_mask
            while mm:
                b = mm & -mm
                mm ^= b
                pos = None
                count = 0
                for r, c in house:
                    if board[r][c] == 0 and (cand[r][c] & b):
                        count += 1
                        pos = (r, c)
                        if count > 1:
                            break
                if count == 0:
                    return None
                if count == 1:
                    rr, cc = pos
                    if board[rr][cc] == 0:
                        cand[rr][cc] = b
                        queue.append((rr, cc))
                        changed = True
        return changed

    def naked_subsets():
        changed = False
        for house in houses:
            slots = [(r, c) for r, c in house if board[r][c] == 0]
            groups = {}
            for r, c in slots:
                m = cand[r][c]
                k = popcount(m)
                if 2 <= k <= 4:
                    groups.setdefault(m, []).append((r, c))
            for m, cells in groups.items():
                k = popcount(m)
                if len(cells) == k:
                    for r, c in slots:
                        if (r, c) not in cells:
                            nm = cand[r][c] & ~m
                            if nm != cand[r][c]:
                                if nm == 0:
                                    return None
                                cand[r][c] = nm
                                changed = True
        return changed

    def house_consistent():
        for r in range(n):
            seen = 0
            for c in range(n):
                v = board[r][c]
                if v:
                    b = bit(v)
                    if seen & b:
                        return False
                    seen |= b
        for c in range(n):
            seen = 0
            for r in range(n):
                v = board[r][c]
                if v:
                    b = bit(v)
                    if seen & b:
                        return False
                    seen |= b
        for rid in range(n):
            seen = 0
            for r, c in regs[rid]:
                v = board[r][c]
                if v:
                    b = bit(v)
                    if seen & b:
                        return False
                    seen |= b
        for r in range(n):
            for c in range(n):
                if board[r][c] == 0 and cand[r][c] == 0:
                    return False
        return True

    def logical_closure():
        while True:
            progress = False

            queue = []
            for r in range(n):
                for c in range(n):
                    if board[r][c] == 0 and cand[r][c] & (cand[r][c] - 1) == 0:
                        queue.append((r, c))
            if queue:
                if not propagate_singles(queue):
                    return False
                progress = True

            res = hidden_singles([])
            if res is None:
                return False
            if res:
                queue = []
                for r in range(n):
                    for c in range(n):
                        if board[r][c] == 0 and cand[r][c] & (cand[r][c] - 1) == 0:
                            queue.append((r, c))
                if not propagate_singles(queue):
                    return False
                progress = True

            res = naked_subsets()
            if res is None:
                return False
            if res:
                progress = True

            # Recompute impossible states quickly
            if not house_consistent():
                return False

            if not progress:
                break
        return True

    def solved():
        for r in range(n):
            for c in range(n):
                if board[r][c] == 0:
                    return False
        return True

    def choose_cell():
        best = None
        best_len = n + 1
        best_degree = -1
        for r in range(n):
            for c in range(n):
                if board[r][c] == 0:
                    m = cand[r][c]
                    k = popcount(m)
                    if k < best_len:
                        degree = sum(1 for rr, cc in peers[r][c] if board[rr][cc] == 0)
                        best = (r, c)
                        best_len = k
                        best_degree = degree
                    elif k == best_len:
                        degree = sum(1 for rr, cc in peers[r][c] if board[rr][cc] == 0)
                        if degree > best_degree:
                            best = (r, c)
                            best_degree = degree
        return best

    def search():
        if not logical_closure():
            return False
        if solved():
            return True

        pos = choose_cell()
        if pos is None:
            return False
        r, c = pos

        # Least-constraining value ordering
        options = []
        for v in mask_to_values(cand[r][c]):
            b = bit(v)
            impact = 0
            for rr, cc in peers[r][c]:
                if board[rr][cc] == 0 and (cand[rr][cc] & b):
                    impact += 1
            options.append((impact, v))
        options.sort()

        snapshot = clone_state()
        for _, v in options:
            queue = []
            if place(r, c, v, queue) and propagate_singles(queue) and search():
                return True
            restore_state(snapshot)
            snapshot = clone_state()
        return False

    if not search():
        return "No Solution"
    return board

