from collections import deque
from itertools import combinations
from math import comb

def solve(observation):
    data = observation['data']
    if not data or not data[0]:
        return repr([])

    R, C = len(data), len(data[0])
    N = R * C

    def idx(r, c):
        return r * C + c

    def rc(i):
        return divmod(i, C)

    def bits(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    # Build exact-sum constraints from numbered cells.
    constraints = []
    touches = [[] for _ in range(N)]
    for r in range(R):
        for c in range(C):
            v = data[r][c]
            if v is None:
                continue
            mask = 0
            for rr in range(max(0, r - 1), min(R, r + 2)):
                for cc in range(max(0, c - 1), min(C, c + 2)):
                    mask |= 1 << idx(rr, cc)
            ci = len(constraints)
            constraints.append((mask, int(v)))
            for x in bits(mask):
                touches[x].append(ci)

    M = len(constraints)
    base_masks = [m for m, _ in constraints]
    base_needs = [k for _, k in constraints]

    # Variables not appearing in any clue can be chosen arbitrarily; prefer white.
    constrained_mask = 0
    for m in base_masks:
        constrained_mask |= m

    def clone_state(assign, needs, masks):
        return assign[:], needs[:], masks[:]

    def assign_var(assign, needs, masks, queue, v, val):
        cur = assign[v]
        if cur != -1:
            return cur == val
        assign[v] = val
        bit = 1 << v
        for ci in touches[v]:
            if masks[ci] & bit:
                masks[ci] ^= bit
                if val:
                    needs[ci] -= 1
                queue.append(ci)
        return True

    def propagate(assign, needs, masks):
        queue = deque(range(M))
        while True:
            while queue:
                ci = queue.popleft()
                m = masks[ci]
                n = m.bit_count()
                k = needs[ci]

                if k < 0 or k > n:
                    return False

                if n == 0:
                    if k != 0:
                        return False
                    continue

                if k == 0 or k == n:
                    forced = 1 if k == n else 0
                    for v in list(bits(m)):
                        if not assign_var(assign, needs, masks, queue, v, forced):
                            return False

            changed = False

            # Human-like overlap deduction:
            # If unknown set A is a subset of unknown set B, then B\A has an exact remaining count.
            for i in range(M):
                mi = masks[i]
                if needs[i] < 0 or needs[i] > mi.bit_count():
                    return False
                for j in range(i + 1, M):
                    mj = masks[j]
                    if needs[j] < 0 or needs[j] > mj.bit_count():
                        return False

                    if mi == mj:
                        if needs[i] != needs[j]:
                            return False
                        continue

                    # mi subset mj
                    if mi and (mi & ~mj) == 0:
                        diff = mj ^ mi
                        dneed = needs[j] - needs[i]
                        dn = diff.bit_count()
                        if dneed < 0 or dneed > dn:
                            return False
                        if diff and (dneed == 0 or dneed == dn):
                            forced = 1 if dneed == dn else 0
                            q2 = deque()
                            for v in list(bits(diff)):
                                if not assign_var(assign, needs, masks, q2, v, forced):
                                    return False
                            if q2:
                                queue.extend(q2)
                                changed = True

                    # mj subset mi
                    if mj and (mj & ~mi) == 0:
                        diff = mi ^ mj
                        dneed = needs[i] - needs[j]
                        dn = diff.bit_count()
                        if dneed < 0 or dneed > dn:
                            return False
                        if diff and (dneed == 0 or dneed == dn):
                            forced = 1 if dneed == dn else 0
                            q2 = deque()
                            for v in list(bits(diff)):
                                if not assign_var(assign, needs, masks, q2, v, forced):
                                    return False
                            if q2:
                                queue.extend(q2)
                                changed = True

            if not changed:
                break

        return True

    def choose_branch(assign, needs, masks):
        # Prefer branching on the tightest unresolved exact-sum constraint.
        best = None
        best_score = None

        for ci in range(M):
            m = masks[ci]
            n = m.bit_count()
            k = needs[ci]
            if n <= 1:
                continue
            # Smaller number of patterns is stronger.
            score = comb(n, k)
            # Tie-break by smaller neighborhood.
            key = (score, n)
            if best_score is None or key < best_score:
                best_score = key
                best = ('constraint', ci, score)

        if best is not None and best[2] <= 24:
            return best

        # Fallback: choose a variable participating in the most informative constraints.
        best_v = None
        best_key = None
        for v in range(N):
            if assign[v] != -1 or not (constrained_mask & (1 << v)):
                continue
            local = []
            ratio_num = 0.0
            ratio_den = 0
            for ci in touches[v]:
                n = masks[ci].bit_count()
                if n == 0:
                    continue
                k = needs[ci]
                local.append((comb(n, k), n))
                ratio_num += k / n
                ratio_den += 1
            if not local:
                continue
            local.sort()
            avg_ratio = ratio_num / ratio_den if ratio_den else 0.5
            # More constrained first, then bias toward nontrivial probabilities.
            key = (local[0], len(local), abs(avg_ratio - 0.5))
            if best_key is None or key < best_key:
                best_key = key
                best_v = v

        if best_v is not None:
            return ('var', best_v)

        return None

    def branch_order_for_var(v, needs, masks):
        # Estimate black likelihood from touching constraints.
        total = 0.0
        cnt = 0
        for ci in touches[v]:
            n = masks[ci].bit_count()
            if n > 0:
                total += needs[ci] / n
                cnt += 1
        p = total / cnt if cnt else 0.0
        return [1, 0] if p >= 0.5 else [0, 1]

    def dfs(assign, needs, masks):
        if not propagate(assign, needs, masks):
            return None

        branch = choose_branch(assign, needs, masks)
        if branch is None:
            # Any unconstrained leftovers can be white.
            for v in range(N):
                if assign[v] == -1:
                    assign[v] = 0
            # Final verification.
            for ci, (full_mask, target) in enumerate(constraints):
                s = 0
                for v in bits(full_mask):
                    s += assign[v]
                if s != target:
                    return None
            return assign

        if branch[0] == 'constraint':
            _, ci, _ = branch
            m = masks[ci]
            k = needs[ci]
            vars_ = list(bits(m))

            # Order patterns to try more likely ones first.
            weights = []
            for v in vars_:
                total = 0.0
                cnt = 0
                for cj in touches[v]:
                    n = masks[cj].bit_count()
                    if n > 0:
                        total += needs[cj] / n
                        cnt += 1
                weights.append((total / cnt if cnt else 0.5, v))
            weights.sort(reverse=True)
            ordered_vars = [v for _, v in weights]

            for black_set in combinations(ordered_vars, k):
                black_set = set(black_set)
                a2, n2, m2 = clone_state(assign, needs, masks)
                q = deque()
                ok = True
                for v in ordered_vars:
                    val = 1 if v in black_set else 0
                    if not assign_var(a2, n2, m2, q, v, val):
                        ok = False
                        break
                if not ok:
                    continue
                res = dfs(a2, n2, m2)
                if res is not None:
                    return res
            return None

        _, v = branch
        for val in branch_order_for_var(v, needs, masks):
            a2, n2, m2 = clone_state(assign, needs, masks)
            q = deque()
            if assign_var(a2, n2, m2, q, v, val):
                res = dfs(a2, n2, m2)
                if res is not None:
                    return res
        return None

    assign = [-1] * N
    needs = base_needs[:]
    masks = base_masks[:]

    sol = dfs(assign, needs, masks)
    if sol is None:
        return "No Solution"

    out = []
    for r in range(R):
        row = []
        for c in range(C):
            row.append('B' if sol[idx(r, c)] == 1 else None)
        out.append(row)
    return repr(out)

if __name__ == "__main__":
    print(solve(OBSERVATION))

