# Weighted black-cell puzzle solver.
# Assumption from the puzzle format:
# - Row weights are 1..R from top to bottom.
# - Column weights are 1..C from left to right.
# Observation only carries row/column target sums.

from collections import deque

def bit_iter(mask, n):
    i = 0
    while i < n:
        if (mask >> i) & 1:
            yield i
        i += 1

def mask_to_grid(row_masks, r, c):
    grid = []
    for i in range(r):
        row = []
        m = row_masks[i]
        for j in range(c):
            row.append('B' if ((m >> j) & 1) else None)
        grid.append(row)
    return grid

def precompute_patterns(length, weights, targets):
    by_target = {}
    full = 1 << length
    subset_weight = [0] * full
    for mask in range(1, full):
        lsb = mask & -mask
        idx = lsb.bit_length() - 1
        subset_weight[mask] = subset_weight[mask ^ lsb] + weights[idx]
    wanted = set(targets)
    for t in wanted:
        by_target[t] = tuple(mask for mask in range(full) if subset_weight[mask] == t)
    return by_target, subset_weight

def domain_supports(domains, universe_bits):
    any1 = 0
    any0 = universe_bits
    for m in domains:
        any1 |= m
        any0 &= m
    return any1, any0

def force_filter_domains(domains, idx, value):
    # value: 1 -> cell must be black, 0 -> must be white
    changed = False
    keep = []
    bit = 1 << idx
    if value:
        for m in domains:
            if m & bit:
                keep.append(m)
    else:
        for m in domains:
            if not (m & bit):
                keep.append(m)
    if not keep:
        return None, None
    if len(keep) != len(domains):
        changed = True
    return tuple(keep), changed

def propagate(row_domains, col_domains, r, c):
    # AC-like propagation between row-pattern domains and column-pattern domains.
    row_domains = list(row_domains)
    col_domains = list(col_domains)

    q = deque()
    inq = set()
    for i in range(r):
        q.append(('r', i))
        inq.add(('r', i))
    for j in range(c):
        q.append(('c', j))
        inq.add(('c', j))

    while q:
        kind, idx = q.popleft()
        inq.discard((kind, idx))

        if kind == 'r':
            dom = row_domains[idx]
            if not dom:
                return None
            any1, any0 = domain_supports(dom, (1 << c) - 1)
            # For each cell in this row:
            # if row forces 1/0, filter column domains;
            # else use column forced values to filter row domain.
            for j in range(c):
                bit = 1 << j
                row_forces_1 = (any0 & bit) != 0
                row_forces_0 = (any1 & bit) == 0

                cdom = col_domains[j]
                if not cdom:
                    return None
                c_any1, c_any0 = domain_supports(cdom, (1 << r) - 1)
                cbit = 1 << idx
                col_forces_1 = (c_any0 & cbit) != 0
                col_forces_0 = (c_any1 & cbit) == 0

                if row_forces_1:
                    nd, changed = force_filter_domains(cdom, idx, 1)
                    if nd is None:
                        return None
                    if changed:
                        col_domains[j] = nd
                        if ('c', j) not in inq:
                            q.append(('c', j))
                            inq.add(('c', j))
                elif row_forces_0:
                    nd, changed = force_filter_domains(cdom, idx, 0)
                    if nd is None:
                        return None
                    if changed:
                        col_domains[j] = nd
                        if ('c', j) not in inq:
                            q.append(('c', j))
                            inq.add(('c', j))
                elif col_forces_1:
                    nd, changed = force_filter_domains(dom, j, 1)
                    if nd is None:
                        return None
                    if changed:
                        row_domains[idx] = nd
                        dom = nd
                        any1, any0 = domain_supports(dom, (1 << c) - 1)
                        if ('r', idx) not in inq:
                            q.append(('r', idx))
                            inq.add(('r', idx))
                elif col_forces_0:
                    nd, changed = force_filter_domains(dom, j, 0)
                    if nd is None:
                        return None
                    if changed:
                        row_domains[idx] = nd
                        dom = nd
                        any1, any0 = domain_supports(dom, (1 << c) - 1)
                        if ('r', idx) not in inq:
                            q.append(('r', idx))
                            inq.add(('r', idx))

        else:
            dom = col_domains[idx]
            if not dom:
                return None
            any1, any0 = domain_supports(dom, (1 << r) - 1)
            for i in range(r):
                bit = 1 << i
                col_forces_1 = (any0 & bit) != 0
                col_forces_0 = (any1 & bit) == 0

                rdom = row_domains[i]
                if not rdom:
                    return None
                r_any1, r_any0 = domain_supports(rdom, (1 << c) - 1)
                rbit = 1 << idx
                row_forces_1 = (r_any0 & rbit) != 0
                row_forces_0 = (r_any1 & rbit) == 0

                if col_forces_1:
                    nd, changed = force_filter_domains(rdom, idx, 1)
                    if nd is None:
                        return None
                    if changed:
                        row_domains[i] = nd
                        if ('r', i) not in inq:
                            q.append(('r', i))
                            inq.add(('r', i))
                elif col_forces_0:
                    nd, changed = force_filter_domains(rdom, idx, 0)
                    if nd is None:
                        return None
                    if changed:
                        row_domains[i] = nd
                        if ('r', i) not in inq:
                            q.append(('r', i))
                            inq.add(('r', i))
                elif row_forces_1:
                    nd, changed = force_filter_domains(dom, i, 1)
                    if nd is None:
                        return None
                    if changed:
                        col_domains[idx] = nd
                        dom = nd
                        any1, any0 = domain_supports(dom, (1 << r) - 1)
                        if ('c', idx) not in inq:
                            q.append(('c', idx))
                            inq.add(('c', idx))
                elif row_forces_0:
                    nd, changed = force_filter_domains(dom, i, 0)
                    if nd is None:
                        return None
                    if changed:
                        col_domains[idx] = nd
                        dom = nd
                        any1, any0 = domain_supports(dom, (1 << r) - 1)
                        if ('c', idx) not in inq:
                            q.append(('c', idx))
                            inq.add(('c', idx))

    return tuple(row_domains), tuple(col_domains)

def choose_branch(row_domains, col_domains):
    # Most-constrained-first, preferring rows/cols with smallest domain > 1.
    best = None

    for i, dom in enumerate(row_domains):
        k = len(dom)
        if k > 1:
            score = (k, 0, i)  # rows before cols on ties
            if best is None or score < best[:3]:
                best = (k, 0, i, 'r')

    for j, dom in enumerate(col_domains):
        k = len(dom)
        if k > 1:
            score = (k, 1, j)
            if best is None or score < best[:3]:
                best = (k, 1, j, 'c')

    return None if best is None else (best[3], best[2])

def is_solved(row_domains, col_domains):
    return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)

def verify(row_masks, row_sum, col_sum):
    r = len(row_sum)
    c = len(col_sum)
    col_weights = list(range(1, c + 1))
    row_weights = list(range(1, r + 1))

    for i in range(r):
        s = 0
        m = row_masks[i]
        for j in range(c):
            if (m >> j) & 1:
                s += col_weights[j]
        if s != row_sum[i]:
            return False

    for j in range(c):
        s = 0
        for i in range(r):
            if (row_masks[i] >> j) & 1:
                s += row_weights[i]
        if s != col_sum[j]:
            return False
    return True

def search(row_domains, col_domains, row_sum, col_sum):
    state = propagate(row_domains, col_domains, len(row_domains), len(col_domains))
    if state is None:
        return None
    row_domains, col_domains = state

    if is_solved(row_domains, col_domains):
        row_masks = [d[0] for d in row_domains]
        if verify(row_masks, row_sum, col_sum):
            return row_masks
        return None

    branch = choose_branch(row_domains, col_domains)
    if branch is None:
        return None

    kind, idx = branch
    if kind == 'r':
        # Try patterns with stronger constraint impact first.
        options = sorted(row_domains[idx], key=lambda m: (bin(m).count("1"), m))
        for m in options:
            new_rows = list(row_domains)
            new_rows[idx] = (m,)
            res = search(tuple(new_rows), col_domains, row_sum, col_sum)
            if res is not None:
                return res
    else:
        options = sorted(col_domains[idx], key=lambda m: (bin(m).count("1"), m))
        for m in options:
            new_cols = list(col_domains)
            new_cols[idx] = (m,)
            res = search(row_domains, tuple(new_cols), row_sum, col_sum)
            if res is not None:
                return res
    return None

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    r = len(row_sum)
    c = len(col_sum)

    row_weights = list(range(1, r + 1))
    col_weights = list(range(1, c + 1))

    # Human-like candidate generation:
    # each row is any subset of columns whose column-weights sum to the row target,
    # each column is any subset of rows whose row-weights sum to the column target.
    row_patterns_by_target, _ = precompute_patterns(c, col_weights, row_sum)
    col_patterns_by_target, _ = precompute_patterns(r, row_weights, col_sum)

    row_domains = []
    for t in row_sum:
        pats = row_patterns_by_target.get(t, ())
        if not pats:
            return "No Solution"
        row_domains.append(tuple(pats))

    col_domains = []
    for t in col_sum:
        pats = col_patterns_by_target.get(t, ())
        if not pats:
            return "No Solution"
        col_domains.append(tuple(pats))

    result = search(tuple(row_domains), tuple(col_domains), row_sum, col_sum)
    if result is None:
        return "No Solution"
    return repr(mask_to_grid(result, r, c))

if __name__ == "__main__":
    print(solve(OBSERVATION))

