from copy import deepcopy

# 0 -> W, 1 -> B

def _parse_constraints(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0])

    horiz = {}
    for k, v in observation.get('horizontal', {}).items():
        r, c = eval(k, {"__builtins__": {}})
        r = int(r)
        c_left = int(c - 0.5)
        horiz[(r, c_left)] = v

    vert = {}
    for k, v in observation.get('vertical', {}).items():
        r, c = eval(k, {"__builtins__": {}})
        r_top = int(r - 0.5)
        c = int(c)
        vert[(r_top, c)] = v

    fixed = [[None] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            if data[i][j] == 'W':
                fixed[i][j] = 0
            elif data[i][j] == 'B':
                fixed[i][j] = 1
    return n, m, fixed, horiz, vert


def _generate_line_patterns(length):
    half = length // 2
    out = []

    def rec(pos, prev1, prev2, ones, arr):
        if ones > half:
            return
        zeros = pos - ones
        if zeros > half:
            return
        remain = length - pos
        if ones + remain < half or zeros + remain < half:
            return
        if pos == length:
            if ones == half:
                out.append(tuple(arr))
            return
        for bit in (0, 1):
            if pos >= 2 and prev1 == prev2 == bit:
                continue
            arr.append(bit)
            rec(pos + 1, prev2, bit, ones + bit, arr)
            arr.pop()

    rec(0, None, None, 0, [])
    return out


def _line_ok_with_fixed_and_adj(line, fixed_line, adj_constraints):
    for idx, v in enumerate(fixed_line):
        if v is not None and line[idx] != v:
            return False
    for c, typ in adj_constraints.items():
        if typ == '=' and line[c] != line[c + 1]:
            return False
        if typ == 'x' and line[c] == line[c + 1]:
            return False
    return True


def _build_initial_candidates(observation):
    n, m, fixed, horiz, vert = _parse_constraints(observation)
    if n % 2 or m % 2:
        return None

    row_patterns = _generate_line_patterns(m)
    col_patterns = _generate_line_patterns(n)

    row_adjs = [{} for _ in range(n)]
    for (r, c), typ in horiz.items():
        row_adjs[r][c] = typ

    col_adjs = [{} for _ in range(m)]
    for (r, c), typ in vert.items():
        col_adjs[c][r] = typ

    row_fixed = [fixed[i][:] for i in range(n)]
    col_fixed = [[fixed[i][j] for i in range(n)] for j in range(m)]

    row_cands = []
    for i in range(n):
        cands = [p for p in row_patterns if _line_ok_with_fixed_and_adj(p, row_fixed[i], row_adjs[i])]
        if not cands:
            return None
        row_cands.append(cands)

    col_cands = []
    for j in range(m):
        cands = [p for p in col_patterns if _line_ok_with_fixed_and_adj(p, col_fixed[j], col_adjs[j])]
        if not cands:
            return None
        col_cands.append(cands)

    return {
        'n': n,
        'm': m,
        'fixed': fixed,
        'row_cands': row_cands,
        'col_cands': col_cands,
    }


def _allowed_values_from_patterns(patterns, idx):
    vals = 0
    for p in patterns:
        vals |= (1 << p[idx])
        if vals == 0b11:
            break
    return vals


def _propagate(state):
    n, m = state['n'], state['m']
    row_cands = state['row_cands']
    col_cands = state['col_cands']

    changed = True
    while changed:
        changed = False

        cell_mask = [[0 for _ in range(m)] for _ in range(n)]

        for i in range(n):
            rc = row_cands[i]
            if not rc:
                return False
            for j in range(m):
                cell_mask[i][j] |= _allowed_values_from_patterns(rc, j)

        for j in range(m):
            cc = col_cands[j]
            if not cc:
                return False
            for i in range(n):
                cm = _allowed_values_from_patterns(cc, i)
                if cell_mask[i][j] == 0:
                    cell_mask[i][j] = cm
                else:
                    cell_mask[i][j] &= cm
                if cell_mask[i][j] == 0:
                    return False

        for i in range(n):
            old_len = len(row_cands[i])
            new_cands = []
            for p in row_cands[i]:
                ok = True
                for j in range(m):
                    if not ((1 << p[j]) & cell_mask[i][j]):
                        ok = False
                        break
                if ok:
                    new_cands.append(p)
            if not new_cands:
                return False
            if len(new_cands) != old_len:
                row_cands[i] = new_cands
                changed = True

        for j in range(m):
            old_len = len(col_cands[j])
            new_cands = []
            for p in col_cands[j]:
                ok = True
                for i in range(n):
                    if not ((1 << p[i]) & cell_mask[i][j]):
                        ok = False
                        break
                if ok:
                    new_cands.append(p)
            if not new_cands:
                return False
            if len(new_cands) != old_len:
                col_cands[j] = new_cands
                changed = True

        # Fast local Takuzu-style deductions from partial domains:
        # - no three consecutive equal
        # - balance counts
        if _apply_local_deductions_via_domains(state):
            changed = True

    return True


def _current_domains(state):
    n, m = state['n'], state['m']
    domains = [[{0, 1} for _ in range(m)] for _ in range(n)]
    for i in range(n):
        for j in range(m):
            vals = set(p[j] for p in state['row_cands'][i]) & set(p[i] for p in state['col_cands'][j])
            if not vals:
                return None
            domains[i][j] = vals
    return domains


def _apply_local_deductions_via_domains(state):
    n, m = state['n'], state['m']
    changed = False

    while True:
        domains = _current_domains(state)
        if domains is None:
            return False

        forced = []

        # Row local rules
        for i in range(n):
            # no three consecutive same
            for j in range(m - 2):
                a, b, c = domains[i][j], domains[i][j + 1], domains[i][j + 2]
                sa = next(iter(a)) if len(a) == 1 else None
                sb = next(iter(b)) if len(b) == 1 else None
                sc = next(iter(c)) if len(c) == 1 else None
                if sa is not None and sb is not None and sa == sb and sc is None:
                    forced.append((i, j + 2, 1 - sa))
                if sb is not None and sc is not None and sb == sc and sa is None:
                    forced.append((i, j, 1 - sb))
                if sa is not None and sc is not None and sa == sc and sb is None:
                    forced.append((i, j + 1, 1 - sa))

            # count balance
            known_ones = sum(1 for j in range(m) if domains[i][j] == {1})
            known_zeros = sum(1 for j in range(m) if domains[i][j] == {0})
            half = m // 2
            if known_ones > half or known_zeros > half:
                return True
            if known_ones == half:
                for j in range(m):
                    if domains[i][j] != {0}:
                        forced.append((i, j, 0))
            if known_zeros == half:
                for j in range(m):
                    if domains[i][j] != {1}:
                        forced.append((i, j, 1))

        # Column local rules
        for j in range(m):
            for i in range(n - 2):
                a, b, c = domains[i][j], domains[i + 1][j], domains[i + 2][j]
                sa = next(iter(a)) if len(a) == 1 else None
                sb = next(iter(b)) if len(b) == 1 else None
                sc = next(iter(c)) if len(c) == 1 else None
                if sa is not None and sb is not None and sa == sb and sc is None:
                    forced.append((i + 2, j, 1 - sa))
                if sb is not None and sc is not None and sb == sc and sa is None:
                    forced.append((i, j, 1 - sb))
                if sa is not None and sc is not None and sa == sc and sb is None:
                    forced.append((i + 1, j, 1 - sa))

            known_ones = sum(1 for i in range(n) if domains[i][j] == {1})
            known_zeros = sum(1 for i in range(n) if domains[i][j] == {0})
            half = n // 2
            if known_ones > half or known_zeros > half:
                return True
            if known_ones == half:
                for i in range(n):
                    if domains[i][j] != {0}:
                        forced.append((i, j, 0))
            if known_zeros == half:
                for i in range(n):
                    if domains[i][j] != {1}:
                        forced.append((i, j, 1))

        # Apply forced values by filtering row/col candidates
        unique_forced = {}
        for i, j, v in forced:
            if (i, j) in unique_forced and unique_forced[(i, j)] != v:
                return True
            unique_forced[(i, j)] = v

        if not unique_forced:
            return changed

        any_change = False

        for (i, j), v in unique_forced.items():
            new_row = [p for p in state['row_cands'][i] if p[j] == v]
            new_col = [p for p in state['col_cands'][j] if p[i] == v]
            if not new_row or not new_col:
                return True
            if len(new_row) != len(state['row_cands'][i]):
                state['row_cands'][i] = new_row
                any_change = True
            if len(new_col) != len(state['col_cands'][j]):
                state['col_cands'][j] = new_col
                any_change = True

        changed = changed or any_change
        if not any_change:
            return changed
        if not _propagate(state):
            return True


def _is_solved(state):
    return all(len(c) == 1 for c in state['row_cands']) and all(len(c) == 1 for c in state['col_cands'])


def _select_branch(state):
    n, m = state['n'], state['m']
    best = None

    for i in range(n):
        k = len(state['row_cands'][i])
        if 1 < k and (best is None or k < best[0]):
            best = (k, 'row', i)

    for j in range(m):
        k = len(state['col_cands'][j])
        if 1 < k and (best is None or k < best[0]):
            best = (k, 'col', j)

    return best


def _state_to_grid(state):
    n, m = state['n'], state['m']
    grid = [[None] * m for _ in range(n)]
    for i in range(n):
        row = state['row_cands'][i][0]
        for j in range(m):
            grid[i][j] = 'B' if row[j] == 1 else 'W'
    return grid


def _search(state):
    if not _propagate(state):
        return None
    if _is_solved(state):
        return state

    branch = _select_branch(state)
    if branch is None:
        return None

    _, kind, idx = branch

    if kind == 'row':
        candidates = list(state['row_cands'][idx])
        # Prefer patterns that maximize agreement with constrained columns
        candidates.sort(key=lambda p: sum(len([q for q in state['col_cands'][j] if q[idx] == p[j]]) for j in range(state['m'])))
        for p in candidates:
            nxt = {
                'n': state['n'],
                'm': state['m'],
                'fixed': state['fixed'],
                'row_cands': [list(x) for x in state['row_cands']],
                'col_cands': [list(x) for x in state['col_cands']],
            }
            nxt['row_cands'][idx] = [p]
            res = _search(nxt)
            if res is not None:
                return res
    else:
        candidates = list(state['col_cands'][idx])
        candidates.sort(key=lambda p: sum(len([q for q in state['row_cands'][i] if q[idx] == p[i]]) for i in range(state['n'])))
        for p in candidates:
            nxt = {
                'n': state['n'],
                'm': state['m'],
                'fixed': state['fixed'],
                'row_cands': [list(x) for x in state['row_cands']],
                'col_cands': [list(x) for x in state['col_cands']],
            }
            nxt['col_cands'][idx] = [p]
            res = _search(nxt)
            if res is not None:
                return res

    return None


def solve(observation):
    state = _build_initial_candidates(observation)
    if state is None:
        return "No Solution"
    res = _search(state)
    if res is None:
        return "No Solution"
    return _state_to_grid(res)


