# Generalized solver for Latin-square + consecutive / non-consecutive orthogonal adjacency constraints.
# The implementation emphasizes human-like deduction:
# - row/column elimination
# - hidden singles in rows/columns
# - strong local propagation on adjacent/non-adjacent consecutive constraints
# - MRV-guided backtracking only after propagation stalls

from collections import deque

def solve(observation):
    data = observation["data"]
    dots = observation["adjacent"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    full_mask = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def single_value(mask):
        return mask.bit_length()

    def mask_to_values(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length()
            mask ^= lsb

    # Precompute row/col units and peers
    cell_count = n * n
    rows = [[r * n + c for c in range(n)] for r in range(n)]
    cols = [[r * n + c for r in range(n)] for c in range(n)]

    row_of = [i // n for i in range(cell_count)]
    col_of = [i % n for i in range(cell_count)]

    # Dotted edges are "consecutive"; all other orth-adjacent pairs are "non-consecutive"
    dotted = set()
    for a, b in dots:
        if int(a) == a:  # horizontal gap: (row, col+0.5)
            r = int(a)
            c = int(b - 0.5)
            if 0 <= r < n and 0 <= c < n - 1:
                i = r * n + c
                j = r * n + (c + 1)
                dotted.add((min(i, j), max(i, j)))
        else:  # vertical gap: (row+0.5, col)
            r = int(a - 0.5)
            c = int(b)
            if 0 <= r < n - 1 and 0 <= c < n:
                i = r * n + c
                j = (r + 1) * n + c
                dotted.add((min(i, j), max(i, j)))

    adj_edges = []
    neigh = [[] for _ in range(cell_count)]
    for r in range(n):
        for c in range(n):
            i = r * n + c
            if c + 1 < n:
                j = r * n + (c + 1)
                kind = 1 if (min(i, j), max(i, j)) in dotted else 0
                adj_edges.append((i, j, kind))
                neigh[i].append((j, kind))
                neigh[j].append((i, kind))
            if r + 1 < n:
                j = (r + 1) * n + c
                kind = 1 if (min(i, j), max(i, j)) in dotted else 0
                adj_edges.append((i, j, kind))
                neigh[i].append((j, kind))
                neigh[j].append((i, kind))

    # Support masks for adjacency constraints
    cons_partner = [0] * (n + 1)
    noncons_partner = [0] * (n + 1)
    for v in range(1, n + 1):
        m = 0
        if v > 1:
            m |= bit(v - 1)
        if v < n:
            m |= bit(v + 1)
        cons_partner[v] = m
        noncons_partner[v] = full_mask ^ m

    max_mask = 1 << n
    support_cons = [0] * max_mask
    support_noncons = [0] * max_mask
    for m in range(max_mask):
        sc = 0
        sn = 0
        mm = m
        while mm:
            lsb = mm & -mm
            v = lsb.bit_length()
            sc |= cons_partner[v]
            sn |= noncons_partner[v]
            mm ^= lsb
        support_cons[m] = sc
        support_noncons[m] = sn

    # Initial domains
    domains = [full_mask] * cell_count
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                if not (1 <= v <= n):
                    return "No Solution"
                domains[r * n + c] = bit(v)

    # Fast consistency check for givens against row/col duplicates
    for unit in rows + cols:
        seen = 0
        for i in unit:
            if domains[i] & (domains[i] - 1) == 0:
                if seen & domains[i]:
                    return "No Solution"
                seen |= domains[i]

    def propagate(dom):
        changed = True
        while changed:
            changed = False

            # Row/column elimination and hidden singles
            for unit in rows + cols:
                fixed = 0
                for i in unit:
                    d = dom[i]
                    if d == 0:
                        return None
                    if d & (d - 1) == 0:
                        if fixed & d:
                            return None
                        fixed |= d

                # Remove fixed digits from unfixed cells
                for i in unit:
                    d = dom[i]
                    if d & (d - 1):
                        nd = d & ~fixed
                        if nd == 0:
                            return None
                        if nd != d:
                            dom[i] = nd
                            changed = True

                # Hidden singles
                for v in range(1, n + 1):
                    vb = bit(v)
                    spots = []
                    for i in unit:
                        if dom[i] & vb:
                            spots.append(i)
                    if not spots:
                        return None
                    if len(spots) == 1 and dom[spots[0]] != vb:
                        dom[spots[0]] = vb
                        changed = True

            # Adjacency arc consistency
            for i, j, kind in adj_edges:
                di = dom[i]
                dj = dom[j]
                if kind:
                    ndi = di & support_cons[dj]
                    ndj = dj & support_cons[di]
                else:
                    ndi = di & support_noncons[dj]
                    ndj = dj & support_noncons[di]
                if ndi == 0 or ndj == 0:
                    return None
                if ndi != di:
                    dom[i] = ndi
                    changed = True
                if ndj != dj:
                    dom[j] = ndj
                    changed = True

            # Re-check solved duplicates after adjacency-induced assignments
            for unit in rows + cols:
                seen = 0
                for i in unit:
                    d = dom[i]
                    if d == 0:
                        return None
                    if d & (d - 1) == 0:
                        if seen & d:
                            return None
                        seen |= d

        return dom

    def solved(dom):
        return all(d and (d & (d - 1) == 0) for d in dom)

    def select_cell(dom):
        best_i = -1
        best_len = n + 1
        best_score = -1
        for i, d in enumerate(dom):
            pc = popcount(d)
            if 1 < pc < best_len:
                # Tie-break by degree toward already constrained neighborhood
                score = 0
                for j, kind in neigh[i]:
                    pj = popcount(dom[j])
                    score += (n + 1 - pj) + (2 if kind else 1)
                best_i = i
                best_len = pc
                best_score = score
            elif 1 < pc == best_len:
                score = 0
                for j, kind in neigh[i]:
                    pj = popcount(dom[j])
                    score += (n + 1 - pj) + (2 if kind else 1)
                if score > best_score:
                    best_i = i
                    best_score = score
        return best_i

    def order_values(dom, i):
        # Least-constraining-value heuristic using row/col/neighbor compatibility.
        vals = []
        r = row_of[i]
        c = col_of[i]
        for v in mask_to_values(dom[i]):
            vb = bit(v)
            score = 0

            # Preserve options in row/col peers
            for j in rows[r]:
                if j != i and (dom[j] & vb):
                    score += 1
            for j in cols[c]:
                if j != i and (dom[j] & vb):
                    score += 1

            # Preserve adjacency supports
            for j, kind in neigh[i]:
                dj = dom[j]
                if kind:
                    score += popcount(dj & cons_partner[v]) * 3
                else:
                    score += popcount(dj & noncons_partner[v]) * 2

            vals.append((score, vb))
        vals.sort(reverse=True)
        return [vb for _, vb in vals]

    def search(dom):
        dom = propagate(dom[:])
        if dom is None:
            return None
        if solved(dom):
            return dom

        i = select_cell(dom)
        if i < 0:
            return None

        for vb in order_values(dom, i):
            ndom = dom[:]
            ndom[i] = vb
            res = search(ndom)
            if res is not None:
                return res
        return None

    result = search(domains)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(single_value(result[r * n + c]))
        grid.append(row)
    return str(grid)

