from functools import lru_cache

UNKNOWN = -1
WHITE = 0
BLACK = 1


def generate_patterns(length, clues):
    clues = tuple(clues)

    @lru_cache(None)
    def rec(pos, idx):
        if idx == len(clues):
            return [tuple([WHITE] * (length - pos))]
        run = clues[idx]
        remaining_runs = clues[idx + 1:]
        min_tail = sum(remaining_runs) + max(0, len(remaining_runs))
        max_start = length - run - min_tail
        out = []
        for start in range(pos, max_start + 1):
            prefix = [WHITE] * (start - pos) + [BLACK] * run
            next_pos = start + run
            if idx < len(clues) - 1:
                prefix.append(WHITE)
                next_pos += 1
            for suffix in rec(next_pos, idx + 1):
                out.append(tuple(prefix) + suffix)
        return out

    if not clues:
        return [tuple([WHITE] * length)]
    return rec(0, 0)


def pattern_fits(pattern, line):
    for a, b in zip(pattern, line):
        if b != UNKNOWN and a != b:
            return False
    return True


def line_consensus(patterns):
    if not patterns:
        return None
    n = len(patterns[0])
    result = [patterns[0][i] for i in range(n)]
    for p in patterns[1:]:
        for i in range(n):
            if result[i] != p[i]:
                result[i] = UNKNOWN
    return result


def transpose(grid):
    return [list(col) for col in zip(*grid)]


def propagate(grid, row_domains, col_domains):
    h = len(grid)
    w = len(grid[0])

    changed = True
    while changed:
        changed = False

        # Filter row domains against current grid and write forced cells.
        for r in range(h):
            line = grid[r]
            new_domain = [p for p in row_domains[r] if pattern_fits(p, line)]
            if not new_domain:
                return None
            if len(new_domain) != len(row_domains[r]):
                row_domains[r] = new_domain
                changed = True
            consensus = line_consensus(new_domain)
            for c, v in enumerate(consensus):
                if v != UNKNOWN and grid[r][c] == UNKNOWN:
                    grid[r][c] = v
                    changed = True

        # Filter column domains against current grid and write forced cells.
        for c in range(w):
            line = [grid[r][c] for r in range(h)]
            new_domain = [p for p in col_domains[c] if pattern_fits(p, line)]
            if not new_domain:
                return None
            if len(new_domain) != len(col_domains[c]):
                col_domains[c] = new_domain
                changed = True
            consensus = line_consensus(new_domain)
            for r, v in enumerate(consensus):
                if v != UNKNOWN and grid[r][c] == UNKNOWN:
                    grid[r][c] = v
                    changed = True

    # Final consistency check.
    for r in range(h):
        if not any(pattern_fits(p, grid[r]) for p in row_domains[r]):
            return None
    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if not any(pattern_fits(p, col) for p in col_domains[c]):
            return None

    return grid, row_domains, col_domains


def is_solved(grid):
    return all(cell != UNKNOWN for row in grid for cell in row)


def clone_state(grid, row_domains, col_domains):
    return (
        [row[:] for row in grid],
        [dom[:] for dom in row_domains],
        [dom[:] for dom in col_domains],
    )


def choose_branch(grid, row_domains, col_domains):
    h = len(grid)
    w = len(grid[0])

    best = None

    # Prefer the most constrained unresolved line domain, mirroring human focus.
    for r in range(h):
        if any(v == UNKNOWN for v in grid[r]):
            k = len(row_domains[r])
            if k > 1:
                score = (k, 0, r)
                if best is None or score < best[0]:
                    best = (score, ("row", r))

    for c in range(w):
        col = [grid[r][c] for r in range(h)]
        if any(v == UNKNOWN for v in col):
            k = len(col_domains[c])
            if k > 1:
                score = (k, 1, c)
                if best is None or score < best[0]:
                    best = (score, ("col", c))

    if best is not None:
        return best[1]

    # Fallback: choose the cell with strongest bias from row/col domains.
    best_cell = None
    for r in range(h):
        for c in range(w):
            if grid[r][c] != UNKNOWN:
                continue
            row_black = sum(1 for p in row_domains[r] if p[c] == BLACK)
            row_total = len(row_domains[r])
            col_black = sum(1 for p in col_domains[c] if p[r] == BLACK)
            col_total = len(col_domains[c])
            black_weight = row_black * col_black
            white_weight = (row_total - row_black) * (col_total - col_black)
            ambiguity = min(black_weight, white_weight)
            score = (ambiguity, -(black_weight + white_weight), r, c)
            if best_cell is None or score < best_cell[0]:
                best_cell = (score, ("cell", r, c))
    return best_cell[1] if best_cell else None


def search(grid, row_domains, col_domains):
    state = propagate(grid, row_domains, col_domains)
    if state is None:
        return None
    grid, row_domains, col_domains = state

    if is_solved(grid):
        return grid

    branch = choose_branch(grid, row_domains, col_domains)
    if branch is None:
        return None

    kind = branch[0]

    if kind == "row":
        r = branch[1]
        # Try the row patterns directly; this is usually powerful after propagation.
        for p in row_domains[r]:
            new_grid, new_rows, new_cols = clone_state(grid, row_domains, col_domains)
            ok = True
            for c, v in enumerate(p):
                if new_grid[r][c] != UNKNOWN and new_grid[r][c] != v:
                    ok = False
                    break
                new_grid[r][c] = v
            if not ok:
                continue
            new_rows[r] = [p]
            ans = search(new_grid, new_rows, new_cols)
            if ans is not None:
                return ans
        return None

    if kind == "col":
        c = branch[1]
        for p in col_domains[c]:
            new_grid, new_rows, new_cols = clone_state(grid, row_domains, col_domains)
            ok = True
            for r, v in enumerate(p):
                if new_grid[r][c] != UNKNOWN and new_grid[r][c] != v:
                    ok = False
                    break
                new_grid[r][c] = v
            if not ok:
                continue
            new_cols[c] = [p]
            ans = search(new_grid, new_rows, new_cols)
            if ans is not None:
                return ans
        return None

    # Cell fallback branch.
    _, r, c = branch
    row_black = sum(1 for p in row_domains[r] if p[c] == BLACK)
    row_total = len(row_domains[r])
    col_black = sum(1 for p in col_domains[c] if p[r] == BLACK)
    col_total = len(col_domains[c])

    # Prefer the more likely value first for faster convergence.
    black_score = row_black * col_black
    white_score = (row_total - row_black) * (col_total - col_black)
    values = [BLACK, WHITE] if black_score >= white_score else [WHITE, BLACK]

    for v in values:
        new_grid, new_rows, new_cols = clone_state(grid, row_domains, col_domains)
        new_grid[r][c] = v
        ans = search(new_grid, new_rows, new_cols)
        if ans is not None:
            return ans
    return None


def solve(observation):
    row_clues = observation["row_black_runs"]
    col_clues = observation["col_black_runs"]
    h = len(row_clues)
    w = len(col_clues)

    row_domains = [generate_patterns(w, clues) for clues in row_clues]
    col_domains = [generate_patterns(h, clues) for clues in col_clues]
    grid = [[UNKNOWN] * w for _ in range(h)]

    solution = search(grid, row_domains, col_domains)
    if solution is None:
        return "No Solution"

    answer = []
    for r in range(h):
        answer.append(["B" if solution[r][c] == BLACK else None for c in range(w)])
    return repr(answer)


