from collections import defaultdict

# General solver framework for the stitch puzzle.
#
# Interpretation implemented:
# - Each hole is identified by a grid coordinate (r, c) on an N x N hole grid.
# - A stitch connects two orthogonally adjacent holes.
# - Region data is used to derive required inter-region adjacencies.
# - For each pair of orthogonally adjacent cells belonging to different regions,
#   there must be exactly one stitch connecting the corresponding adjacent holes.
# - No two stitches may share a hole.
# - Row/column clues count used holes in each hole-row / hole-column.
#
# This implementation is generalized and aggressively validates forced structure.
# If the observation describes a consistent forced instance, the result is immediate.
# If the forced structure contradicts degree or clue constraints, "No Solution" is returned.


def normalize_stitch(a, b):
    return [a, b] if a <= b else [b, a]


def derive_forced_stitches(region):
    n = len(region)
    stitches = []
    used = set()

    # Horizontal cell adjacencies -> horizontal stitch between corresponding holes.
    for r in range(n):
        for c in range(n - 1):
            if region[r][c] != region[r][c + 1]:
                a = (r, c)
                b = (r, c + 1)
                st = tuple(map(tuple, normalize_stitch(a, b)))
                if st not in used:
                    used.add(st)
                    stitches.append([a, b])

    # Vertical cell adjacencies -> vertical stitch between corresponding holes.
    for r in range(n - 1):
        for c in range(n):
            if region[r][c] != region[r + 1][c]:
                a = (r, c)
                b = (r + 1, c)
                st = tuple(map(tuple, normalize_stitch(a, b)))
                if st not in used:
                    used.add(st)
                    stitches.append([a, b])

    return stitches


def hole_usage_counts(stitches, n):
    row_counts = [0] * n
    col_counts = [0] * n
    degree = defaultdict(int)

    for a, b in stitches:
        for r, c in (a, b):
            degree[(r, c)] += 1
            row_counts[r] += 1
            col_counts[c] += 1

    return row_counts, col_counts, degree


def validate_structure(stitches, n):
    for a, b in stitches:
        (r1, c1), (r2, c2) = a, b
        if abs(r1 - r2) + abs(c1 - c2) != 1:
            return False
        if not (0 <= r1 < n and 0 <= c1 < n and 0 <= r2 < n and 0 <= c2 < n):
            return False
    return True


def solve(observation):
    region = observation["region"]
    target_row = observation["row_stitch_counts"]
    target_col = observation["col_stitch_counts"]

    n = len(region)
    if n == 0 or any(len(row) != n for row in region):
        return "No Solution"
    if len(target_row) != n or len(target_col) != n:
        return "No Solution"

    # Forced deduction from region boundaries.
    stitches = derive_forced_stitches(region)

    # Basic structural validation.
    if not validate_structure(stitches, n):
        return "No Solution"

    # Rule 3: no two stitches can share a hole.
    row_counts, col_counts, degree = hole_usage_counts(stitches, n)
    if any(v > 1 for v in degree.values()):
        return "No Solution"

    # Rule 4: exact row/column clue satisfaction.
    if row_counts != target_row or col_counts != target_col:
        return "No Solution"

    return str(stitches)


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [1, 7, 2, 9], 'col_sum': [3, 9, 4, 6]}

from itertools import combinations

# Puzzle model:
# - Row weights are 1..R
# - Column weights are 1..C
# - A black cell at (r, c) contributes (c+1) to row r sum and (r+1) to column c sum

def bit_positions(mask, n):
    while mask:
        lsb = mask & -mask
        yield lsb.bit_length() - 1
        mask ^= lsb

def subset_masks_by_weight_sum(weights, target):
    n = len(weights)
    out = []
    for mask in range(1 << n):
        s = 0
        m = mask
        i = 0
        while m:
            if m & 1:
                s += weights[i]
            i += 1
            m >>= 1
        if s == target:
            out.append(mask)
    return out

def domain_cell_flags_row(domain, c):
    has0 = False
    has1 = False
    bit = 1 << c
    for m in domain:
        if m & bit:
            has1 = True
        else:
            has0 = True
        if has0 and has1:
            return 3
    return (1 if has0 else 0) | (2 if has1 else 0)

def domain_cell_flags_col(domain, r):
    has0 = False
    has1 = False
    bit = 1 << r
    for m in domain:
        if m & bit:
            has1 = True
        else:
            has0 = True
        if has0 and has1:
            return 3
    return (1 if has0 else 0) | (2 if has1 else 0)

def filter_row_domain(domain, c, allowed_black):
    bit = 1 << c
    if allowed_black:
        return [m for m in domain if m & bit]
    return [m for m in domain if not (m & bit)]

def filter_col_domain(domain, r, allowed_black):
    bit = 1 << r
    if allowed_black:
        return [m for m in domain if m & bit]
    return [m for m in domain if not (m & bit)]

def propagate(row_domains, col_domains, R, C):
    # Arc-consistency between row and column domains through each cell.
    changed = True
    while changed:
        changed = False

        # Fast fail.
        for d in row_domains:
            if not d:
                return None
        for d in col_domains:
            if not d:
                return None

        # Cell-wise consistency.
        for r in range(R):
            rd = row_domains[r]
            for c in range(C):
                rf = domain_cell_flags_row(rd, c)
                cf = domain_cell_flags_col(col_domains[c], r)
                # bit 0 => white possible, bit 1 => black possible
                both = rf & cf
                if both == 0:
                    return None

                # If one side allows a status the other doesn't, prune both.
                if rf != both:
                    new_rd = []
                    bit = 1 << c
                    keep_black = bool(both & 2)
                    keep_white = bool(both & 1)
                    for m in rd:
                        if m & bit:
                            if keep_black:
                                new_rd.append(m)
                        else:
                            if keep_white:
                                new_rd.append(m)
                    if len(new_rd) != len(rd):
                        if not new_rd:
                            return None
                        row_domains[r] = new_rd
                        rd = new_rd
                        changed = True

                cd = col_domains[c]
                if cf != both:
                    new_cd = []
                    bit = 1 << r
                    keep_black = bool(both & 2)
                    keep_white = bool(both & 1)
                    for m in cd:
                        if m & bit:
                            if keep_black:
                                new_cd.append(m)
                        else:
                            if keep_white:
                                new_cd.append(m)
                    if len(new_cd) != len(cd):
                        if not new_cd:
                            return None
                        col_domains[c] = new_cd
                        changed = True

        # Re-check empties after pruning.
        for d in row_domains:
            if not d:
                return None
        for d in col_domains:
            if not d:
                return None

    return row_domains, col_domains

def solved(row_domains, col_domains):
    return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)

def choose_branch(row_domains, col_domains):
    best_kind = None
    best_idx = None
    best_size = 10**9

    for i, d in enumerate(row_domains):
        ld = len(d)
        if 1 < ld < best_size:
            best_kind = 'row'
            best_idx = i
            best_size = ld

    for j, d in enumerate(col_domains):
        ld = len(d)
        if 1 < ld < best_size:
            best_kind = 'col'
            best_idx = j
            best_size = ld

    return best_kind, best_idx

def search(row_domains, col_domains, R, C):
    state = propagate([d[:] for d in row_domains], [d[:] for d in col_domains], R, C)
    if state is None:
        return None
    row_domains, col_domains = state

    if solved(row_domains, col_domains):
        return row_domains, col_domains

    kind, idx = choose_branch(row_domains, col_domains)
    if kind is None:
        return None

    if kind == 'row':
        # Prefer candidates with more forced agreement with current column domains.
        candidates = row_domains[idx][:]
        scored = []
        for m in candidates:
            score = 0
            for c in range(C):
                cf = domain_cell_flags_col(col_domains[c], idx)
                bit = 1 << c
                if m & bit:
                    if cf == 2:
                        score += 2
                    elif cf == 3:
                        score += 1
                else:
                    if cf == 1:
                        score += 2
                    elif cf == 3:
                        score += 1
            scored.append((score, m))
        scored.sort(reverse=True)

        for _, m in scored:
            new_rows = [d[:] for d in row_domains]
            new_cols = [d[:] for d in col_domains]
            new_rows[idx] = [m]
            res = search(new_rows, new_cols, R, C)
            if res is not None:
                return res
    else:
        candidates = col_domains[idx][:]
        scored = []
        for m in candidates:
            score = 0
            for r in range(R):
                rf = domain_cell_flags_row(row_domains[r], idx)
                bit = 1 << r
                if m & bit:
                    if rf == 2:
                        score += 2
                    elif rf == 3:
                        score += 1
                else:
                    if rf == 1:
                        score += 2
                    elif rf == 3:
                        score += 1
            scored.append((score, m))
        scored.sort(reverse=True)

        for _, m in scored:
            new_rows = [d[:] for d in row_domains]
            new_cols = [d[:] for d in col_domains]
            new_cols[idx] = [m]
            res = search(new_rows, new_cols, R, C)
            if res is not None:
                return res

    return None

def build_answer(row_domains, R, C):
    grid = []
    for r in range(R):
        m = row_domains[r][0]
        row = []
        for c in range(C):
            row.append('B' if (m >> c) & 1 else None)
        grid.append(row)
    return grid

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    R = len(row_sum)
    C = len(col_sum)

    row_weights = list(range(1, R + 1))
    col_weights = list(range(1, C + 1))

    # Initial domains from independent row/column arithmetic.
    row_domains = [subset_masks_by_weight_sum(col_weights, tgt) for tgt in row_sum]
    col_domains = [subset_masks_by_weight_sum(row_weights, tgt) for tgt in col_sum]

    # Immediate impossibility check.
    if any(not d for d in row_domains) or any(not d for d in col_domains):
        return "No Solution"

    # Global checksum consistency:
    # sum(row targets) must equal sum over black cells of col weights
    # and sum(col targets) must equal sum over black cells of row weights;
    # these are not the same quantity in general, so no equality check here.

    result = search(row_domains, col_domains, R, C)
    if result is None:
        return "No Solution"

    final_rows, final_cols = result

    # Final cross-check.
    grid = build_answer(final_rows, R, C)
    for r in range(R):
        if sum((c + 1) for c in range(C) if grid[r][c] == 'B') != row_sum[r]:
            return "No Solution"
    for c in range(C):
        if sum((r + 1) for r in range(R) if grid[r][c] == 'B') != col_sum[c]:
            return "No Solution"

    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'B', 'B', 'W', 'W', None], [None, None, None, None, None, None], [None, None, None, None, None, None], [None, None, None, None, None, None], [None, None, None, None, None, None], [None, 'W', 'W', 'B', 'B', None]], 'horizontal': {'(1, 2.5)': '='}, 'vertical': {'(0.5, 5)': 'x', '(2.5, 2)': 'x', '(2.5, 4)': '=', '(2.5, 5)': '=', '(3.5, 0)': 'x', '(4.5, 0)': 'x'}}

from copy import deepcopy

B, W, U = 1, 0, -1


def parse_key(key):
    a, b = key.strip()[1:-1].split(',')
    x = float(a.strip())
    y = float(b.strip())
    if x.is_integer():
        x = int(x)
    if y.is_integer():
        y = int(y)
    return x, y


def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(r) != n for r in data):
        return "No Solution"
    if n % 2 != 0:
        return "No Solution"

    target = n // 2
    grid = [[U] * n for _ in range(n)]

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v == 'B':
                grid[r][c] = B
            elif v == 'W':
                grid[r][c] = W

    horiz = {}
    for k, v in observation.get('horizontal', {}).items():
        r, ch = parse_key(k)
        if not isinstance(r, int):
            return "No Solution"
        c = int(ch - 0.5)
        if not (0 <= r < n and 0 <= c < n - 1):
            return "No Solution"
        horiz[(r, c)] = v

    vert = {}
    for k, v in observation.get('vertical', {}).items():
        rh, c = parse_key(k)
        r = int(rh - 0.5)
        if not isinstance(c, int):
            return "No Solution"
        if not (0 <= r < n - 1 and 0 <= c < n):
            return "No Solution"
        vert[(r, c)] = v

    neighbors = [[[] for _ in range(n)] for _ in range(n)]
    for (r, c), rel in horiz.items():
        neighbors[r][c].append((r, c + 1, rel))
        neighbors[r][c + 1].append((r, c, rel))
    for (r, c), rel in vert.items():
        neighbors[r][c].append((r + 1, c, rel))
        neighbors[r + 1][c].append((r, c, rel))

    row_known = [0] * n
    row_b = [0] * n
    col_known = [0] * n
    col_b = [0] * n

    for r in range(n):
        for c in range(n):
            if grid[r][c] != U:
                row_known[r] += 1
                col_known[c] += 1
                if grid[r][c] == B:
                    row_b[r] += 1
                    col_b[c] += 1

    trail = []

    def row_w_count(r):
        return row_known[r] - row_b[r]

    def col_w_count(c):
        return col_known[c] - col_b[c]

    def assign(r, c, val):
        cur = grid[r][c]
        if cur == val:
            return True
        if cur != U:
            return False

        if val == B:
            if row_b[r] + 1 > target or col_b[c] + 1 > target:
                return False
        else:
            if row_w_count(r) + 1 > target or col_w_count(c) + 1 > target:
                return False

        grid[r][c] = val
        row_known[r] += 1
        col_known[c] += 1
        if val == B:
            row_b[r] += 1
            col_b[c] += 1
        trail.append((r, c, val))

        for nr, nc, rel in neighbors[r][c]:
            need = val if rel == '=' else 1 - val
            other = grid[nr][nc]
            if other == U:
                if not assign(nr, nc, need):
                    return False
            elif other != need:
                return False

        if not check_local_after_assignment(r, c):
            return False
        return True

    def undo(mark):
        while len(trail) > mark:
            r, c, val = trail.pop()
            grid[r][c] = U
            row_known[r] -= 1
            col_known[c] -= 1
            if val == B:
                row_b[r] -= 1
                col_b[c] -= 1

    def check_line_triplets(vals):
        m = len(vals)
        for i in range(m - 2):
            a, b, c = vals[i], vals[i + 1], vals[i + 2]
            if a != U and a == b == c:
                return False
        return True

    def line_prefix_feasible(vals):
        bcnt = sum(v == B for v in vals if v != U)
        wcnt = sum(v == W for v in vals if v != U)
        unk = sum(v == U for v in vals)
        if bcnt > target or wcnt > target:
            return False
        if bcnt + unk < target or wcnt + unk < target:
            return False
        return True

    def check_row(r):
        vals = grid[r]
        if not check_line_triplets(vals):
            return False
        if not line_prefix_feasible(vals):
            return False
        if row_known[r] == n:
            for rr in range(n):
                if rr != r and row_known[rr] == n and grid[rr] == vals:
                    return False
        return True

    def check_col(c):
        vals = [grid[r][c] for r in range(n)]
        if not check_line_triplets(vals):
            return False
        if not line_prefix_feasible(vals):
            return False
        if col_known[c] == n:
            for cc in range(n):
                if cc != c and col_known[cc] == n:
                    same = True
                    for r in range(n):
                        if grid[r][cc] != vals[r]:
                            same = False
                            break
                    if same:
                        return False
        return True

    def check_local_after_assignment(r, c):
        return check_row(r) and check_col(c)

    def pair_from_rule(a, b, same):
        if a != U and b != U:
            return a == b if same else a != b
        return True

    def global_consistency():
        for r in range(n):
            if not check_row(r):
                return False
        for c in range(n):
            if not check_col(c):
                return False
        for (r, c), rel in horiz.items():
            if not pair_from_rule(grid[r][c], grid[r][c + 1], rel == '='):
                return False
        for (r, c), rel in vert.items():
            if not pair_from_rule(grid[r][c], grid[r + 1][c], rel == '='):
                return False
        return True

    def force_by_triplets_line(get_cell, idxs):
        changed = False
        for i in range(len(idxs) - 2):
            a = get_cell(idxs[i])
            b = get_cell(idxs[i + 1])
            c = get_cell(idxs[i + 2])

            if a != U and a == b and c == U:
                if not set_cell(idxs[i + 2], 1 - a):
                    return None
                changed = True
            if b != U and b == c and a == U:
                if not set_cell(idxs[i], 1 - b):
                    return None
                changed = True
            if a != U and c != U and a == c and b == U:
                if not set_cell(idxs[i + 1], 1 - a):
                    return None
                changed = True
        return changed

    def set_cell(pos, val):
        r, c = pos
        return assign(r, c, val)

    def apply_balance():
        changed = False
        for r in range(n):
            if row_b[r] == target:
                for c in range(n):
                    if grid[r][c] == U:
                        if not assign(r, c, W):
                            return None
                        changed = True
            elif row_w_count(r) == target:
                for c in range(n):
                    if grid[r][c] == U:
                        if not assign(r, c, B):
                            return None
                        changed = True

        for c in range(n):
            if col_b[c] == target:
                for r in range(n):
                    if grid[r][c] == U:
                        if not assign(r, c, W):
                            return None
                        changed = True
            elif col_w_count(c) == target:
                for r in range(n):
                    if grid[r][c] == U:
                        if not assign(r, c, B):
                            return None
                        changed = True
        return changed

    def apply_triplets():
        changed = False
        for r in range(n):
            res = force_by_triplets_line(lambda c: grid[r][c], [(r, c) for c in range(n)])
            if res is None:
                return None
            changed |= res
        for c in range(n):
            res = force_by_triplets_line(lambda r: grid[r][c], [(r, c) for r in range(n)])
            if res is None:
                return None
            changed |= res
        return changed

    def line_state_row(r):
        return tuple(grid[r])

    def line_state_col(c):
        return tuple(grid[r][c] for r in range(n))

    def complete_line_no_dup():
        changed = False
        # Human-like uniqueness rule:
        # if an incomplete row can match a complete row only by one choice in one or more cells,
        # force opposites to avoid equality; same for columns.
        complete_rows = [line_state_row(r) for r in range(n) if row_known[r] == n]
        for r in range(n):
            if row_known[r] == n:
                continue
            vals = line_state_row(r)
            for full in complete_rows:
                possible = True
                diff_unknowns = []
                for c in range(n):
                    if vals[c] == U:
                        diff_unknowns.append((c, full[c]))
                    elif vals[c] != full[c]:
                        possible = False
                        break
                if possible and diff_unknowns:
                    if len(diff_unknowns) == 1:
                        c, v = diff_unknowns[0]
                        if not assign(r, c, 1 - v):
                            return None
                        changed = True

        complete_cols = [line_state_col(c) for c in range(n) if col_known[c] == n]
        for c in range(n):
            if col_known[c] == n:
                continue
            vals = line_state_col(c)
            for full in complete_cols:
                possible = True
                diff_unknowns = []
                for r in range(n):
                    if vals[r] == U:
                        diff_unknowns.append((r, full[r]))
                    elif vals[r] != full[r]:
                        possible = False
                        break
                if possible and diff_unknowns:
                    if len(diff_unknowns) == 1:
                        r, v = diff_unknowns[0]
                        if not assign(r, c, 1 - v):
                            return None
                        changed = True
        return changed

    def propagate():
        while True:
            if not global_consistency():
                return False
            changed = False
            for fn in (apply_balance, apply_triplets, complete_line_no_dup):
                res = fn()
                if res is None:
                    return False
                changed |= res
            if not changed:
                return True

    def unresolved_score(r, c):
        score = len(neighbors[r][c]) * 4
        score += (n - row_known[r]) + (n - col_known[c])
        # proximity to existing cells in triplets
        for dc in (-2, -1, 1, 2):
            cc = c + dc
            if 0 <= cc < n and grid[r][cc] != U:
                score += 1
        for dr in (-2, -1, 1, 2):
            rr = r + dr
            if 0 <= rr < n and grid[rr][c] != U:
                score += 1
        return score

    def choose_cell():
        best = None
        best_score = -1
        for r in range(n):
            for c in range(n):
                if grid[r][c] == U:
                    s = unresolved_score(r, c)
                    if s > best_score:
                        best_score = s
                        best = (r, c)
        return best

    def value_order(r, c):
        # Prefer value helping row/col balancing.
        need_b = (target - row_b[r]) + (target - col_b[c])
        need_w = (target - row_w_count(r)) + (target - col_w_count(c))
        vals = [B, W] if need_b >= need_w else [W, B]
        # Try values implied by neighbors first.
        forced = []
        for nr, nc, rel in neighbors[r][c]:
            v = grid[nr][nc]
            if v != U:
                forced_val = v if rel == '=' else 1 - v
                if forced_val not in forced:
                    forced.append(forced_val)
        ordered = forced + [v for v in vals if v not in forced]
        return ordered

    def search():
        if not propagate():
            return False
        pos = choose_cell()
        if pos is None:
            return True
        r, c = pos
        mark = len(trail)
        for val in value_order(r, c):
            if assign(r, c, val):
                if search():
                    return True
            undo(mark)
        return False

    if not global_consistency():
        return "No Solution"

    for r in range(n):
        for c in range(n):
            if grid[r][c] != U:
                v = grid[r][c]
                grid[r][c] = U
                row_known[r] -= 1
                col_known[c] -= 1
                if v == B:
                    row_b[r] -= 1
                    col_b[c] -= 1
                if not assign(r, c, v):
                    return "No Solution"

    if not search():
        return "No Solution"

    out = [['B' if grid[r][c] == B else 'W' for c in range(n)] for r in range(n)]
    return out


