# Generalized solver for diagonal puzzles ("Gokigen Naname"-style):
# - put exactly one diagonal in each cell
# - each numbered dot has exactly that many incident diagonal segments
# - no closed loop is allowed
#
# The solver combines:
# 1) local clue propagation (human-style count forcing),
# 2) immediate anti-loop filtering using rollback DSU,
# 3) selective branching on the most constrained cell,
# 4) lightweight speculative testing to force values before deeper search.

from typing import List, Tuple, Optional


SLASH = 1      # '/'
BACK = 2       # '\'
BOTH = 3


class RollbackDSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n
        self.stack = []

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def connected(self, a: int, b: int) -> bool:
        return self.find(a) == self.find(b)

    def snapshot(self) -> int:
        return len(self.stack)

    def union(self, a: int, b: int) -> bool:
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            self.stack.append((-1, -1, -1))
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.stack.append((rb, self.parent[rb], self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        return True

    def rollback(self, snap: int) -> None:
        while len(self.stack) > snap:
            rb, old_parent, old_size_ra = self.stack.pop()
            if rb == -1:
                continue
            ra = self.parent[rb]
            self.parent[rb] = old_parent
            self.size[ra] = old_size_ra


def solve(observation):
    data = observation["data"]
    m = len(data)
    n = m - 1
    if n <= 0 or any(len(row) != m for row in data):
        return "No Solution"

    cell_count = n * n
    dot_count = (n + 1) * (n + 1)

    def cell_idx(r: int, c: int) -> int:
        return r * n + c

    def dot_idx(r: int, c: int) -> int:
        return r * (n + 1) + c

    # Endpoints for each cell orientation.
    # '/'  connects (r, c+1) -- (r+1, c)
    # '\' connects (r, c)   -- (r+1, c+1)
    cell_endpoints = [None] * cell_count
    for r in range(n):
        for c in range(n):
            i = cell_idx(r, c)
            cell_endpoints[i] = {
                SLASH: (dot_idx(r, c + 1), dot_idx(r + 1, c)),
                BACK: (dot_idx(r, c), dot_idx(r + 1, c + 1)),
            }

    # For each clue dot, store incident cells and which orientation contributes to that dot.
    clues = []
    dot_to_clue = {}
    cell_to_clues = [[] for _ in range(cell_count)]

    for r in range(n + 1):
        for c in range(n + 1):
            req = data[r][c]
            if req is None:
                continue
            inc = []

            # NW cell -> contributes with '\'
            if r > 0 and c > 0:
                i = cell_idx(r - 1, c - 1)
                inc.append((i, BACK))
                cell_to_clues[i].append(len(clues))
            # NE cell -> contributes with '/'
            if r > 0 and c < n:
                i = cell_idx(r - 1, c)
                inc.append((i, SLASH))
                cell_to_clues[i].append(len(clues))
            # SW cell -> contributes with '/'
            if r < n and c > 0:
                i = cell_idx(r, c - 1)
                inc.append((i, SLASH))
                cell_to_clues[i].append(len(clues))
            # SE cell -> contributes with '\'
            if r < n and c < n:
                i = cell_idx(r, c)
                inc.append((i, BACK))
                cell_to_clues[i].append(len(clues))

            clues.append((req, inc))
            dot_to_clue[(r, c)] = len(clues) - 1

    # Quick sanity: clue cannot exceed incident cells.
    for req, inc in clues:
        if req < 0 or req > len(inc):
            return "No Solution"

    domains = [BOTH] * cell_count
    dsu = RollbackDSU(dot_count)
    trail = []

    def snapshot():
        return (len(trail), dsu.snapshot())

    def rollback(snap):
        trail_len, dsu_snap = snap
        while len(trail) > trail_len:
            typ, idx, old = trail.pop()
            if typ == "d":
                domains[idx] = old
        dsu.rollback(dsu_snap)

    def assigned_value(mask: int) -> int:
        return mask if mask in (SLASH, BACK) else 0

    def orientation_char(mask: int) -> str:
        return "/" if mask == SLASH else "\\"

    def orientation_possible_by_loop(i: int, val: int) -> bool:
        a, b = cell_endpoints[i][val]
        return not dsu.connected(a, b)

    def force_cell(i: int, val: int) -> bool:
        cur = domains[i]
        if cur == val:
            return True
        if (cur & val) == 0:
            return False
        if cur != BOTH:
            return False

        # Anti-loop check before committing.
        a, b = cell_endpoints[i][val]
        if dsu.connected(a, b):
            return False

        trail.append(("d", i, cur))
        domains[i] = val
        dsu.union(a, b)
        return True

    def forbid_value(i: int, val: int) -> bool:
        cur = domains[i]
        if (cur & val) == 0:
            return True
        if cur == val:
            return False
        new_mask = cur ^ val
        trail.append(("d", i, cur))
        domains[i] = new_mask
        if new_mask in (SLASH, BACK):
            a, b = cell_endpoints[i][new_mask]
            if dsu.connected(a, b):
                return False
            dsu.union(a, b)
        return True

    def propagate() -> bool:
        changed = True
        while changed:
            changed = False

            # Rule A: if an orientation would immediately close a loop, forbid it.
            for i in range(cell_count):
                cur = domains[i]
                if cur == BOTH:
                    slash_ok = orientation_possible_by_loop(i, SLASH)
                    back_ok = orientation_possible_by_loop(i, BACK)
                    if not slash_ok and not back_ok:
                        return False
                    if not slash_ok:
                        if not force_cell(i, BACK):
                            return False
                        changed = True
                    elif not back_ok:
                        if not force_cell(i, SLASH):
                            return False
                        changed = True

            # Rule B: clue count propagation.
            for clue_idx, (req, inc) in enumerate(clues):
                forced_on = 0
                forced_off = 0
                can_on = 0
                can_off = 0

                undecided_on = []
                undecided_off = []

                for i, contrib_val in inc:
                    cur = domains[i]
                    if cur == BOTH:
                        can_on += 1
                        can_off += 1
                        undecided_on.append((i, contrib_val))
                        undecided_off.append((i, SLASH if contrib_val == BACK else BACK))
                    elif cur == contrib_val:
                        forced_on += 1
                        can_on += 1
                    else:
                        forced_off += 1
                        can_off += 1

                total = len(inc)

                if forced_on > req:
                    return False
                if can_on < req:
                    return False
                if forced_off > total - req:
                    return False
                if can_off < total - req:
                    return False

                # If enough ON are already fixed, rest must be OFF.
                if forced_on == req:
                    for i, off_val in undecided_off:
                        if domains[i] == BOTH:
                            if not force_cell(i, off_val):
                                return False
                            changed = True

                # If every possible ON is needed, they all must be ON.
                if can_on == req:
                    for i, on_val in undecided_on:
                        if domains[i] == BOTH:
                            if not force_cell(i, on_val):
                                return False
                            changed = True

                # Symmetric OFF forcing.
                if forced_off == total - req:
                    for i, on_val in undecided_on:
                        if domains[i] == BOTH:
                            if not force_cell(i, on_val):
                                return False
                            changed = True

                if can_off == total - req:
                    for i, off_val in undecided_off:
                        if domains[i] == BOTH:
                            if not force_cell(i, off_val):
                                return False
                            changed = True

        return True

    def is_complete() -> bool:
        return all(d in (SLASH, BACK) for d in domains)

    def cell_score(i: int) -> int:
        # Higher score = more constrained / more useful branching target.
        r, c = divmod(i, n)
        score = 0
        # Adjacent clues
        for rr, cc in ((r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)):
            if 0 <= rr <= n and 0 <= cc <= n:
                req = data[rr][cc]
                if req is not None:
                    score += 4
                    # Stronger clues are usually more restrictive.
                    score += abs(2 * req - 4)
        # Anti-loop sensitivity
        if domains[i] == BOTH:
            if not orientation_possible_by_loop(i, SLASH):
                score += 10
            if not orientation_possible_by_loop(i, BACK):
                score += 10
        return score

    def choose_branch_cell() -> Optional[int]:
        best = None
        best_score = -1
        for i in range(cell_count):
            if domains[i] == BOTH:
                s = cell_score(i)
                if s > best_score:
                    best_score = s
                    best = i
        return best

    def try_value(i: int, val: int) -> bool:
        snap = snapshot()
        ok = force_cell(i, val) and propagate()
        rollback(snap)
        return ok

    def search() -> bool:
        if not propagate():
            return False
        if is_complete():
            return True

        i = choose_branch_cell()
        if i is None:
            return False

        # Lightweight speculative deduction:
        slash_ok = try_value(i, SLASH)
        back_ok = try_value(i, BACK)

        if not slash_ok and not back_ok:
            return False
        if slash_ok and not back_ok:
            return force_cell(i, SLASH) and search()
        if back_ok and not slash_ok:
            return force_cell(i, BACK) and search()

        # Branch ordering: prefer the value that touches "tighter" clues first.
        r, c = divmod(i, n)

        def val_preference(val: int) -> int:
            pref = 0
            # Each of the 4 corner dots may be affected.
            corners = []
            if val == BACK:
                corners = [(r, c), (r + 1, c + 1)]
            else:
                corners = [(r, c + 1), (r + 1, c)]
            for rr, cc in corners:
                req = data[rr][cc]
                if req is not None:
                    pref += 3 + abs(2 * req - 4)
            return pref

        vals = [SLASH, BACK]
        vals.sort(key=val_preference, reverse=True)

        for val in vals:
            snap = snapshot()
            if force_cell(i, val) and search():
                return True
            rollback(snap)
        return False

    if not search():
        return "No Solution"

    board = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(orientation_char(domains[cell_idx(r, c)]))
        board.append(row)
    return str(board)


