# Slant puzzle solver:
# - exactly one slash in each cell
# - numbered dots count incident diagonal endpoints
# - no closed loops

MASK_BS = 1  # '\'
MASK_FS = 2  # '/'

def solve(observation):
    data = observation["data"]
    n1 = len(data)
    if n1 == 0 or any(len(row) != n1 for row in data):
        return "No Solution"
    n = n1 - 1

    def dot_id(r, c):
        return r * (n + 1) + c

    cell_count = n * n

    # Cell endpoint map:
    # value 0 => '\' ; value 1 => '/'
    endpoints = []
    cell_corners = []
    for r in range(n):
        for c in range(n):
            bs = (dot_id(r, c), dot_id(r + 1, c + 1))
            fs = (dot_id(r, c + 1), dot_id(r + 1, c))
            endpoints.append((bs, fs))
            cell_corners.append([
                (r, c),
                (r, c + 1),
                (r + 1, c),
                (r + 1, c + 1),
            ])

    # For each clue dot, list incidences: (var_idx, contrib_if_bs, contrib_if_fs)
    clue_incidences = {}
    var_to_clues = [[] for _ in range(cell_count)]

    for r in range(n + 1):
        for c in range(n + 1):
            if data[r][c] is None:
                continue
            inc = []
            # (r-1,c-1) with '\'
            if r > 0 and c > 0:
                idx = (r - 1) * n + (c - 1)
                inc.append((idx, 1, 0))
                var_to_clues[idx].append((r, c))
            # (r-1,c) with '/'
            if r > 0 and c < n:
                idx = (r - 1) * n + c
                inc.append((idx, 0, 1))
                var_to_clues[idx].append((r, c))
            # (r,c-1) with '/'
            if r < n and c > 0:
                idx = r * n + (c - 1)
                inc.append((idx, 0, 1))
                var_to_clues[idx].append((r, c))
            # (r,c) with '\'
            if r < n and c < n:
                idx = r * n + c
                inc.append((idx, 1, 0))
                var_to_clues[idx].append((r, c))
            clue_incidences[(r, c)] = inc

    all_clues = list(clue_incidences.keys())

    class DSU:
        __slots__ = ("p", "sz")
        def __init__(self, m):
            self.p = list(range(m))
            self.sz = [1] * m
        def find(self, x):
            p = self.p
            while p[x] != x:
                p[x] = p[p[x]]
                x = p[x]
            return x
        def union(self, a, b):
            pa = self.find(a)
            pb = self.find(b)
            if pa == pb:
                return False
            if self.sz[pa] < self.sz[pb]:
                pa, pb = pb, pa
            self.p[pb] = pa
            self.sz[pa] += self.sz[pb]
            return True

    def mask_values(mask):
        if mask == MASK_BS:
            return (0,)
        if mask == MASK_FS:
            return (1,)
        return (0, 1)

    def assigned_value(mask):
        if mask == MASK_BS:
            return 0
        if mask == MASK_FS:
            return 1
        return None

    def build_dsu(domains):
        dsu = DSU((n + 1) * (n + 1))
        for idx, mask in enumerate(domains):
            val = assigned_value(mask)
            if val is None:
                continue
            a, b = endpoints[idx][val]
            if dsu.find(a) == dsu.find(b):
                return None
            dsu.union(a, b)
        return dsu

    def propagate(domains):
        domains = domains[:]
        while True:
            changed = False

            dsu = build_dsu(domains)
            if dsu is None:
                return None

            # No-loop pruning: if an undecided orientation would connect already-connected dots, forbid it.
            for idx, mask in enumerate(domains):
                if mask == 0:
                    return None
                if mask in (MASK_BS, MASK_FS):
                    continue
                newmask = mask
                a0, b0 = endpoints[idx][0]
                if dsu.find(a0) == dsu.find(b0):
                    newmask &= ~MASK_BS
                a1, b1 = endpoints[idx][1]
                if dsu.find(a1) == dsu.find(b1):
                    newmask &= ~MASK_FS
                if newmask == 0:
                    return None
                if newmask != mask:
                    domains[idx] = newmask
                    changed = True

            # Clue propagation with exact local consistency on each incident variable.
            for rc in all_clues:
                target = data[rc[0]][rc[1]]
                inc = clue_incidences[rc]

                mins = []
                maxs = []
                for idx, c0, c1 in inc:
                    mask = domains[idx]
                    vals = mask_values(mask)
                    contribs = [c0 if v == 0 else c1 for v in vals]
                    mins.append(min(contribs))
                    maxs.append(max(contribs))

                total_min = sum(mins)
                total_max = sum(maxs)
                if target < total_min or target > total_max:
                    return None

                # Try each value in each variable against remaining min/max.
                for pos, (idx, c0, c1) in enumerate(inc):
                    mask = domains[idx]
                    if mask == 0:
                        return None
                    allowed = []
                    for v in mask_values(mask):
                        cv = c0 if v == 0 else c1
                        other_min = total_min - mins[pos]
                        other_max = total_max - maxs[pos]
                        if other_min + cv <= target <= other_max + cv:
                            allowed.append(v)
                    if not allowed:
                        return None
                    newmask = (MASK_BS if 0 in allowed else 0) | (MASK_FS if 1 in allowed else 0)
                    if newmask != mask:
                        domains[idx] = newmask
                        changed = True

            if not changed:
                return domains

    def complete(domains):
        return all(mask in (MASK_BS, MASK_FS) for mask in domains)

    def variable_score(domains, idx):
        # Human-like: favor cells touching more/stronger clues.
        score = 0
        seen = set()
        for rc in var_to_clues[idx]:
            if rc in seen:
                continue
            seen.add(rc)
            k = data[rc[0]][rc[1]]
            deg = len(clue_incidences[rc])
            score += 10 + deg + abs(2 * k - deg)
        return score

    def choose_var(domains):
        best = None
        best_score = None
        for idx, mask in enumerate(domains):
            if mask == 3:
                score = variable_score(domains, idx)
                if best is None or score > best_score:
                    best = idx
                    best_score = score
        return best

    def value_order(domains, idx):
        # Prefer the orientation that better matches nearby tight clues.
        scores = []
        for v in (0, 1):
            bit = MASK_BS if v == 0 else MASK_FS
            if not (domains[idx] & bit):
                continue
            s = 0
            for rc in set(var_to_clues[idx]):
                target = data[rc[0]][rc[1]]
                inc = clue_incidences[rc]
                tmin = tmax = 0
                for j, c0, c1 in inc:
                    if j == idx:
                        cv = c0 if v == 0 else c1
                        tmin += cv
                        tmax += cv
                    else:
                        mask = domains[j]
                        vals = mask_values(mask)
                        contribs = [c0 if vv == 0 else c1 for vv in vals]
                        tmin += min(contribs)
                        tmax += max(contribs)
                if tmin <= target <= tmax:
                    s += 5
                    if tmin == target or tmax == target:
                        s += 3
            scores.append((s, v))
        scores.sort(reverse=True)
        return [v for _, v in scores]

    def dfs(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if complete(domains):
            return domains

        idx = choose_var(domains)
        if idx is None:
            return domains

        for v in value_order(domains, idx):
            new_domains = domains[:]
            new_domains[idx] = MASK_BS if v == 0 else MASK_FS
            res = dfs(new_domains)
            if res is not None:
                return res
        return None

    start = [MASK_BS | MASK_FS] * cell_count
    result = dfs(start)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(n):
        row = []
        for c in range(n):
            idx = r * n + c
            row.append("\\" if result[idx] == MASK_BS else "/")
        grid.append(row)
    return grid

