from functools import lru_cache

# Weighted black-cell puzzle solver.
# A row chooses a subset of columns whose column-weights sum to the row target.
# A column chooses a subset of rows whose row-weights sum to the column target.
# The chosen row/column subsets must agree on every cell.

def _subset_masks(weights, target):
    n = len(weights)
    suffix = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix[i] = suffix[i + 1] + weights[i]

    out = []

    def dfs(i, rem, mask):
        if rem < 0:
            return
        if rem > suffix[i]:
            return
        if i == n:
            if rem == 0:
                out.append(mask)
            return
        # Exclude
        dfs(i + 1, rem, mask)
        # Include
        w = weights[i]
        if rem >= w:
            dfs(i + 1, rem - w, mask | (1 << i))

    dfs(0, target, 0)
    return out


def _bit_values_present(domain, bit):
    has0 = False
    has1 = False
    for mask in domain:
        if (mask >> bit) & 1:
            has1 = True
        else:
            has0 = True
        if has0 and has1:
            break
    return has0, has1


def _filter_domain_by_bit(domain, bit, allow0, allow1):
    new_domain = set()
    for mask in domain:
        b = (mask >> bit) & 1
        if (b == 0 and allow0) or (b == 1 and allow1):
            new_domain.add(mask)
    return new_domain


def _propagate(row_domains, col_domains, n_rows, n_cols):
    # Repeated cell-wise agreement propagation until fixpoint.
    changed = True
    while changed:
        changed = False

        # Early contradiction checks
        for d in row_domains:
            if not d:
                return None
        for d in col_domains:
            if not d:
                return None

        for i in range(n_rows):
            for j in range(n_cols):
                r0, r1 = _bit_values_present(row_domains[i], j)
                c0, c1 = _bit_values_present(col_domains[j], i)

                allow0 = r0 and c0
                allow1 = r1 and c1

                if not allow0 and not allow1:
                    return None

                new_r = _filter_domain_by_bit(row_domains[i], j, allow0, allow1)
                if not new_r:
                    return None
                if len(new_r) != len(row_domains[i]):
                    row_domains[i] = new_r
                    changed = True

                new_c = _filter_domain_by_bit(col_domains[j], i, allow0, allow1)
                if not new_c:
                    return None
                if len(new_c) != len(col_domains[j]):
                    col_domains[j] = new_c
                    changed = True

    return row_domains, col_domains


def _is_solved(row_domains, col_domains):
    return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)


def _choose_branch(row_domains, col_domains):
    # Human-like heuristic: branch on the most constrained unresolved line.
    best_kind = None
    best_idx = None
    best_size = 10**9

    for i, d in enumerate(row_domains):
        s = len(d)
        if 1 < s < best_size:
            best_kind = "row"
            best_idx = i
            best_size = s

    for j, d in enumerate(col_domains):
        s = len(d)
        if 1 < s < best_size:
            best_kind = "col"
            best_idx = j
            best_size = s

    return best_kind, best_idx


def _domain_sort_key(mask):
    # Prefer more informative masks first: balanced by popcount then numeric order.
    return (abs((mask.bit_count() * 2) - 64), mask.bit_count(), mask)


def _search(row_domains, col_domains, n_rows, n_cols):
    state = _propagate(row_domains, col_domains, n_rows, n_cols)
    if state is None:
        return None
    row_domains, col_domains = state

    if _is_solved(row_domains, col_domains):
        return row_domains, col_domains

    kind, idx = _choose_branch(row_domains, col_domains)
    if kind is None:
        return None

    if kind == "row":
        options = sorted(row_domains[idx], key=_domain_sort_key)
        for mask in options:
            new_row_domains = [set(d) for d in row_domains]
            new_col_domains = [set(d) for d in col_domains]
            new_row_domains[idx] = {mask}
            result = _search(new_row_domains, new_col_domains, n_rows, n_cols)
            if result is not None:
                return result
    else:
        options = sorted(col_domains[idx], key=_domain_sort_key)
        for mask in options:
            new_row_domains = [set(d) for d in row_domains]
            new_col_domains = [set(d) for d in col_domains]
            new_col_domains[idx] = {mask}
            result = _search(new_row_domains, new_col_domains, n_rows, n_cols)
            if result is not None:
                return result

    return None


def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    row_weights = observation.get('row_weights', list(range(1, len(row_sum) + 1)))
    col_weights = observation.get('col_weights', list(range(1, len(col_sum) + 1)))

    n_rows = len(row_sum)
    n_cols = len(col_sum)

    if len(row_weights) != n_rows or len(col_weights) != n_cols:
        return "No Solution"

    total_row_targets = sum(row_sum)
    total_col_targets = sum(col_sum)
    total_black_weighted_by_cols = total_row_targets
    total_black_weighted_by_rows = total_col_targets

    # Necessary global consistency:
    # sum over black cells of column-weights must equal row targets total
    # sum over black cells of row-weights must equal column targets total
    # No direct equality required between these two, so nothing else here.

    row_domains = []
    for target in row_sum:
        masks = _subset_masks(col_weights, target)
        if not masks:
            return "No Solution"
        row_domains.append(set(masks))

    col_domains = []
    for target in col_sum:
        masks = _subset_masks(row_weights, target)
        if not masks:
            return "No Solution"
        col_domains.append(set(masks))

    result = _search(row_domains, col_domains, n_rows, n_cols)
    if result is None:
        return "No Solution"

    row_domains, col_domains = result
    row_masks = [next(iter(d)) for d in row_domains]

    grid = []
    for i in range(n_rows):
        row = []
        mask = row_masks[i]
        for j in range(n_cols):
            row.append('B' if ((mask >> j) & 1) else None)
        grid.append(row)

    # Final verification
    for i in range(n_rows):
        s = sum(col_weights[j] for j in range(n_cols) if grid[i][j] == 'B')
        if s != row_sum[i]:
            return "No Solution"
    for j in range(n_cols):
        s = sum(row_weights[i] for i in range(n_rows) if grid[i][j] == 'B')
        if s != col_sum[j]:
            return "No Solution"

    return repr(grid)


