# General solver for Latin-consecutive-dot puzzles:
# - values 1..N
# - each row/col is a permutation
# - dotted orthogonal neighbors must be consecutive
# - undotted orthogonal neighbors must not be consecutive

ALL = None
BIT_TO_VAL = None
VAL_TO_BIT = None

def popcount(x):
    return x.bit_count()

def mask_values(mask, n):
    vals = []
    v = 1
    while mask:
        b = mask & -mask
        vals.append(BIT_TO_VAL[b])
        mask ^= b
        v += 1
    return vals

def iter_bits(mask):
    while mask:
        b = mask & -mask
        yield b
        mask ^= b

def single_value(mask):
    return BIT_TO_VAL[mask] if mask and (mask & (mask - 1)) == 0 else None

def build_adjacency(n, adjacent_list):
    pos = set()
    for a, b in adjacent_list:
        pos.add((a, b))
    nbrs = [[[] for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if c + 1 < n:
                dotted = (float(r), c + 0.5) in pos
                nbrs[r][c].append((r, c + 1, dotted))
                nbrs[r][c + 1].append((r, c, dotted))
            if r + 1 < n:
                dotted = (r + 0.5, float(c)) in pos
                nbrs[r][c].append((r + 1, c, dotted))
                nbrs[r + 1][c].append((r, c, dotted))
    return nbrs

def support_filter(mask_a, mask_b, consec):
    out = 0
    mb = mask_b
    if consec:
        for ba in iter_bits(mask_a):
            v = BIT_TO_VAL[ba]
            sup = 0
            if v > 1:
                sup |= VAL_TO_BIT[v - 1]
            if v < len(VAL_TO_BIT) - 1:
                sup |= VAL_TO_BIT[v + 1]
            if mb & sup:
                out |= ba
    else:
        # Keep a if b has any value non-consecutive to a.
        # Only impossible if mask_b is subset of {v-1, v+1}.
        for ba in iter_bits(mask_a):
            v = BIT_TO_VAL[ba]
            bad = 0
            if v > 1:
                bad |= VAL_TO_BIT[v - 1]
            if v < len(VAL_TO_BIT) - 1:
                bad |= VAL_TO_BIT[v + 1]
            if mb & ~bad:
                out |= ba
    return out

def maximum_matching(candidates_masks, n):
    # candidates_masks: list of length n, each a mask over values 1..n
    # returns match_val_to_cell (1..n indexed) or None if impossible
    match_val_to_cell = [-1] * (n + 1)

    order = sorted(range(n), key=lambda i: popcount(candidates_masks[i]))

    def dfs(cell, seen):
        m = candidates_masks[cell]
        for b in iter_bits(m):
            v = BIT_TO_VAL[b]
            if seen[v]:
                continue
            seen[v] = True
            if match_val_to_cell[v] == -1 or dfs(match_val_to_cell[v], seen):
                match_val_to_cell[v] = cell
                return True
        return False

    for cell in order:
        seen = [False] * (n + 1)
        if not dfs(cell, seen):
            return None
    return match_val_to_cell

def feasible_group(candidates_masks, n):
    return maximum_matching(candidates_masks, n) is not None

def essential_edges_group(candidates_masks, n):
    # Returns per cell a mask of values that appear in at least one perfect matching.
    # Uses "remove candidate and recheck feasibility" pruning.
    if maximum_matching(candidates_masks, n) is None:
        return None
    possible = [0] * n
    for i in range(n):
        m = candidates_masks[i]
        for b in iter_bits(m):
            trial = list(candidates_masks)
            trial[i] &= ~b
            if trial[i] and maximum_matching(trial, n) is not None:
                possible[i] |= b
            else:
                possible[i] |= b
        # stronger value removal is done outside via per-candidate feasibility checks below
    # Refine by checking each candidate directly
    for i in range(n):
        keep = 0
        for b in iter_bits(candidates_masks[i]):
            trial = list(candidates_masks)
            trial[i] = b
            if maximum_matching(trial, n) is not None:
                keep |= b
        possible[i] = keep
    return possible

def propagate(domains, row_used, col_used, nbrs, n):
    changed = True
    while changed:
        changed = False

        # Enforce row/col used sets against domains
        for r in range(n):
            used = row_used[r]
            for c in range(n):
                m = domains[r][c]
                nm = m & ~used if popcount(m) > 1 else m
                if nm != m:
                    if nm == 0:
                        return False
                    domains[r][c] = nm
                    changed = True

        for c in range(n):
            used = col_used[c]
            for r in range(n):
                m = domains[r][c]
                nm = m & ~used if popcount(m) > 1 else m
                if nm != m:
                    if nm == 0:
                        return False
                    domains[r][c] = nm
                    changed = True

        # Binary adjacency constraints (AC-style)
        for r in range(n):
            for c in range(n):
                ma = domains[r][c]
                for rr, cc, consec in nbrs[r][c]:
                    if (rr, cc) < (r, c):
                        continue
                    mb = domains[rr][cc]
                    na = support_filter(ma, mb, consec)
                    nb = support_filter(mb, ma, consec)
                    if na == 0 or nb == 0:
                        return False
                    if na != ma:
                        domains[r][c] = na
                        ma = na
                        changed = True
                    if nb != mb:
                        domains[rr][cc] = nb
                        changed = True

        # Fix singles and update used masks
        for r in range(n):
            for c in range(n):
                m = domains[r][c]
                v = single_value(m)
                if v is not None:
                    b = m
                    if row_used[r] & b and not (domains[r][c] == b):
                        return False
                    if col_used[c] & b and not (domains[r][c] == b):
                        return False
                    if not (row_used[r] & b):
                        row_used[r] |= b
                        changed = True
                    if not (col_used[c] & b):
                        col_used[c] |= b
                        changed = True

        # Contradictions: duplicate fixed values in row/col prevented by used logic + elimination,
        # but verify no other fixed duplicates remain.
        for r in range(n):
            seen = 0
            for c in range(n):
                m = domains[r][c]
                if single_value(m) is not None:
                    if seen & m:
                        return False
                    seen |= m
        for c in range(n):
            seen = 0
            for r in range(n):
                m = domains[r][c]
                if single_value(m) is not None:
                    if seen & m:
                        return False
                    seen |= m

        # Hidden singles + matching-based pruning in rows
        for r in range(n):
            masks = [domains[r][c] for c in range(n)]
            union = 0
            for m in masks:
                if m == 0:
                    return False
                union |= m
            if union != ALL:
                return False
            for v in range(1, n + 1):
                b = VAL_TO_BIT[v]
                places = [c for c in range(n) if domains[r][c] & b]
                if not places:
                    return False
                if len(places) == 1 and domains[r][places[0]] != b:
                    domains[r][places[0]] = b
                    changed = True
            refined = essential_edges_group([domains[r][c] for c in range(n)], n)
            if refined is None:
                return False
            for c in range(n):
                nm = domains[r][c] & refined[c]
                if nm == 0:
                    return False
                if nm != domains[r][c]:
                    domains[r][c] = nm
                    changed = True

        # Hidden singles + matching-based pruning in cols
        for c in range(n):
            masks = [domains[r][c] for r in range(n)]
            union = 0
            for m in masks:
                if m == 0:
                    return False
                union |= m
            if union != ALL:
                return False
            for v in range(1, n + 1):
                b = VAL_TO_BIT[v]
                places = [r for r in range(n) if domains[r][c] & b]
                if not places:
                    return False
                if len(places) == 1 and domains[places[0]][c] != b:
                    domains[places[0]][c] = b
                    changed = True
            refined = essential_edges_group([domains[r][c] for r in range(n)], n)
            if refined is None:
                return False
            for r in range(n):
                nm = domains[r][c] & refined[r]
                if nm == 0:
                    return False
                if nm != domains[r][c]:
                    domains[r][c] = nm
                    changed = True

    return True

def solved(domains, n):
    for r in range(n):
        for c in range(n):
            if single_value(domains[r][c]) is None:
                return False
    return True

def choose_branch_cell(domains, nbrs, n):
    best = None
    best_key = None
    for r in range(n):
        for c in range(n):
            m = domains[r][c]
            pc = popcount(m)
            if pc <= 1:
                continue
            # Higher adjacency pressure first
            degree = len(nbrs[r][c])
            key = (pc, -degree)
            if best_key is None or key < best_key:
                best_key = key
                best = (r, c)
    return best

def order_values(mask, r, c, domains, nbrs, n):
    vals = []
    for b in iter_bits(mask):
        score = 0
        v = BIT_TO_VAL[b]
        for rr, cc, consec in nbrs[r][c]:
            nm = domains[rr][cc]
            if consec:
                sup = 0
                if v > 1:
                    sup |= VAL_TO_BIT[v - 1]
                if v < n:
                    sup |= VAL_TO_BIT[v + 1]
                score += popcount(nm & sup)
            else:
                bad = 0
                if v > 1:
                    bad |= VAL_TO_BIT[v - 1]
                if v < n:
                    bad |= VAL_TO_BIT[v + 1]
                score += popcount(nm & ~bad)
        vals.append((score, b))
    vals.sort()
    return [b for _, b in vals]

def clone_state(domains, row_used, col_used):
    return [row[:] for row in domains], row_used[:], col_used[:]

def search(domains, row_used, col_used, nbrs, n):
    if not propagate(domains, row_used, col_used, nbrs, n):
        return None
    if solved(domains, n):
        return domains

    cell = choose_branch_cell(domains, nbrs, n)
    if cell is None:
        return None
    r, c = cell
    for b in order_values(domains[r][c], r, c, domains, nbrs, n):
        nd, nru, ncu = clone_state(domains, row_used, col_used)
        nd[r][c] = b
        res = search(nd, nru, ncu, nbrs, n)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    n = len(data)

    global ALL, BIT_TO_VAL, VAL_TO_BIT
    ALL = (1 << n) - 1
    BIT_TO_VAL = {}
    VAL_TO_BIT = [0] * (n + 1)
    for v in range(1, n + 1):
        b = 1 << (v - 1)
        BIT_TO_VAL[b] = v
        VAL_TO_BIT[v] = b

    nbrs = build_adjacency(n, observation['adjacent'])

    domains = [[ALL for _ in range(n)] for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n

    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is not None:
                b = VAL_TO_BIT[v]
                domains[r][c] = b

    result = search(domains, row_used, col_used, nbrs, n)
    if result is None:
        return "No Solution"

    grid = [[single_value(result[r][c]) for c in range(n)] for r in range(n)]
    return str(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 0, 0, 0, 1], [2, 2, 0, 0, 3, 1], [2, 3, 3, 3, 3, 1], [2, 2, 3, 3, 3, 1], [4, 2, 3, 3, 3, 1], [4, 4, 4, 4, 4, 1]]}

from collections import defaultdict, deque
from itertools import combinations

# Canonical tetromino classes, with reflection counted as same type.
_BASE_SHAPES = {
    "I": {(0, 0), (1, 0), (2, 0), (3, 0)},
    "L": {(0, 0), (1, 0), (2, 0), (2, 1)},
    "T": {(0, 0), (0, 1), (0, 2), (1, 1)},
    "S": {(0, 1), (0, 2), (1, 0), (1, 1)},
}

def _normalize(shape):
    min_r = min(r for r, c in shape)
    min_c = min(c for r, c in shape)
    return frozenset((r - min_r, c - min_c) for r, c in shape)

def _transforms(shape):
    pts = list(shape)
    out = set()
    for refl in (1, -1):
        for rot in range(4):
            transformed = []
            for r, c in pts:
                x, y = r, c * refl
                for _ in range(rot):
                    x, y = y, -x
                transformed.append((x, y))
            out.add(_normalize(transformed))
    return out

_SHAPE_CLASS = {}
for name, shape in _BASE_SHAPES.items():
    for t in _transforms(shape):
        _SHAPE_CLASS[t] = name

def classify_tetromino(cells):
    norm = _normalize(cells)
    return _SHAPE_CLASS.get(norm)

def neighbors4(r, c, n, m):
    if r > 0:
        yield r - 1, c
    if r + 1 < n:
        yield r + 1, c
    if c > 0:
        yield r, c - 1
    if c + 1 < m:
        yield r, c + 1

def connected(cells, n, m):
    cells = set(cells)
    start = next(iter(cells))
    q = [start]
    seen = {start}
    while q:
        r, c = q.pop()
        for nr, nc in neighbors4(r, c, n, m):
            if (nr, nc) in cells and (nr, nc) not in seen:
                seen.add((nr, nc))
                q.append((nr, nc))
    return len(seen) == len(cells)

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0

    # Region extraction.
    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[grid[r][c]].append((r, c))
    region_ids = sorted(regions)
    ridx = {rid: i for i, rid in enumerate(region_ids)}
    R = len(region_ids)

    # Region adjacency.
    region_adj = [set() for _ in range(R)]
    for r in range(n):
        for c in range(m):
            a = ridx[grid[r][c]]
            for nr, nc in ((r + 1, c), (r, c + 1)):
                if nr < n and nc < m:
                    b = ridx[grid[nr][nc]]
                    if a != b:
                        region_adj[a].add(b)
                        region_adj[b].add(a)

    # Enumerate all legal per-region tetromino placements.
    all_cells_set = set((r, c) for r in range(n) for c in range(m))
    region_candidates = []
    cell_to_region = {}
    for i, rid in enumerate(region_ids):
        for cell in regions[rid]:
            cell_to_region[cell] = i

    # 2x2 blocks.
    blocks = []
    cell_to_blocks = defaultdict(list)
    for r in range(n - 1):
        for c in range(m - 1):
            blk = ((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1))
            bid = len(blocks)
            blocks.append(blk)
            for cell in blk:
                cell_to_blocks[cell].append(bid)

    for rid in region_ids:
        cells = regions[rid]
        cand_list = []
        for comb in combinations(cells, 4):
            comb_set = set(comb)
            if not connected(comb_set, n, m):
                continue
            # O forbidden and all allowed tetrominoes classified here.
            typ = classify_tetromino(comb_set)
            if typ is None:
                continue
            # Local 2x2 full shaded forbidden.
            bad = False
            for bid in set(b for cell in comb_set for b in cell_to_blocks[cell]):
                if all(cell in comb_set for cell in blocks[bid]):
                    bad = True
                    break
            if bad:
                continue

            # Precompute touch cells to support connectivity reasoning.
            frontier = set()
            for r, c in comb_set:
                for nr, nc in neighbors4(r, c, n, m):
                    if (nr, nc) not in comb_set:
                        frontier.add((nr, nc))

            cand_list.append({
                "cells": frozenset(comb_set),
                "type": typ,
                "frontier": frozenset(frontier),
            })

        if not cand_list:
            return "No Solution"
        region_candidates.append(cand_list)

    # Pairwise compatibility between adjacent regions:
    # - different tetromino types
    # - no 2x2 fully shaded using their chosen cells alone
    pair_ok = {}
    for a in range(R):
        for b in region_adj[a]:
            if a < b:
                ok = [[True] * len(region_candidates[b]) for _ in range(len(region_candidates[a]))]
                for ia, ca in enumerate(region_candidates[a]):
                    A = ca["cells"]
                    for ib, cb in enumerate(region_candidates[b]):
                        if ca["type"] == cb["type"]:
                            ok[ia][ib] = False
                            continue
                        union = A | cb["cells"]
                        bad = False
                        relevant = set(b for cell in union for b in cell_to_blocks[cell])
                        for bid in relevant:
                            if all(cell in union for cell in blocks[bid]):
                                bad = True
                                break
                        if bad:
                            ok[ia][ib] = False
                pair_ok[(a, b)] = ok

    # For each region pair, whether candidate pair has at least one orthogonal contact.
    touch_ok = {}
    for a in range(R):
        for b in range(a + 1, R):
            mat = [[False] * len(region_candidates[b]) for _ in range(len(region_candidates[a]))]
            for ia, ca in enumerate(region_candidates[a]):
                A = ca["cells"]
                for ib, cb in enumerate(region_candidates[b]):
                    found = False
                    for r, c in A:
                        for nr, nc in neighbors4(r, c, n, m):
                            if (nr, nc) in cb["cells"]:
                                found = True
                                break
                        if found:
                            break
                    mat[ia][ib] = found
            touch_ok[(a, b)] = mat

    # Region-level possible connectivity graph ignoring final choices.
    can_ever_touch = [[False] * R for _ in range(R)]
    for a in range(R):
        for b in range(a + 1, R):
            possible = False
            mat = touch_ok[(a, b)]
            for row in mat:
                if any(row):
                    possible = True
                    break
            can_ever_touch[a][b] = can_ever_touch[b][a] = possible

    # Helpful indexing for fast 2x2 pruning.
    block_region_cells = []
    for blk in blocks:
        entries = []
        for cell in blk:
            entries.append((cell_to_region[cell], cell))
        block_region_cells.append(entries)

    domains = [set(range(len(region_candidates[i]))) for i in range(R)]
    assigned = [None] * R

    def pair_compatible(a, ia, b, ib):
        if a < b:
            return pair_ok.get((a, b), [[True]])[ia][ib] if b in region_adj[a] else True
        return pair_ok.get((b, a), [[True]])[ib][ia] if a in region_adj[b] else True

    def pair_touch(a, ia, b, ib):
        if a < b:
            return touch_ok[(a, b)][ia][ib]
        return touch_ok[(b, a)][ib][ia]

    def enforce_arc(domains, assigned):
        changed = True
        while changed:
            changed = False

            # Neighbor type / local pair consistency.
            for a in range(R):
                if not domains[a]:
                    return False
                for b in region_adj[a]:
                    new_da = set()
                    for ia in domains[a]:
                        good = False
                        for ib in domains[b]:
                            if pair_compatible(a, ia, b, ib):
                                good = True
                                break
                        if good:
                            new_da.add(ia)
                    if new_da != domains[a]:
                        domains[a] = new_da
                        changed = True
                        if not domains[a]:
                            return False

            # If a region is singleton, record assignment.
            for i in range(R):
                if len(domains[i]) == 1:
                    v = next(iter(domains[i]))
                    if assigned[i] is None:
                        assigned[i] = v
                        changed = True

            # 2x2 block reasoning:
            # If 3 cells in a block are already forced shaded by singleton choices,
            # remove candidates that shade the 4th.
            forced_shaded = {}
            for i in range(R):
                if assigned[i] is not None:
                    forced_shaded[i] = region_candidates[i][assigned[i]]["cells"]

            for bid, blk in enumerate(block_region_cells):
                shaded_now = 0
                undecided = []
                for reg, cell in blk:
                    if reg in forced_shaded:
                        if cell in forced_shaded[reg]:
                            shaded_now += 1
                    else:
                        undecided.append((reg, cell))

                if shaded_now == 4:
                    return False
                if shaded_now == 3 and len(undecided) == 1:
                    reg, cell = undecided[0]
                    nd = {ix for ix in domains[reg] if cell not in region_candidates[reg][ix]["cells"]}
                    if nd != domains[reg]:
                        domains[reg] = nd
                        changed = True
                        if not domains[reg]:
                            return False

            # Connectivity feasibility:
            # Every assigned component must still have some way to touch another assigned/unassigned region,
            # unless everything is already one component and all regions assigned.
            assigned_regions = [i for i in range(R) if assigned[i] is not None]
            if assigned_regions:
                # Build graph among assigned regions via actual touching chosen candidates.
                comp_id = {}
                comp_count = 0
                for start in assigned_regions:
                    if start in comp_id:
                        continue
                    q = [start]
                    comp_id[start] = comp_count
                    while q:
                        x = q.pop()
                        ix = assigned[x]
                        for y in assigned_regions:
                            if y not in comp_id:
                                iy = assigned[y]
                                if pair_touch(x, ix, y, iy):
                                    comp_id[y] = comp_count
                                    q.append(y)
                    comp_count += 1

                if comp_count > 1 or len(assigned_regions) < R:
                    # Each component must have at least one possible external touch.
                    comp_has_escape = [False] * comp_count

                    # To assigned regions in another component.
                    for a in assigned_regions:
                        ia = assigned[a]
                        ca = comp_id[a]
                        for b in assigned_regions:
                            if comp_id[b] != ca:
                                ib = assigned[b]
                                if pair_touch(a, ia, b, ib):
                                    comp_has_escape[ca] = True

                    # To unassigned regions by some remaining candidate.
                    for a in assigned_regions:
                        ia = assigned[a]
                        ca = comp_id[a]
                        for b in range(R):
                            if assigned[b] is None:
                                for ib in domains[b]:
                                    if pair_touch(a, ia, b, ib):
                                        comp_has_escape[ca] = True
                                        break

                    if not all(comp_has_escape):
                        return False

        return True

    def choose_region(domains, assigned):
        # Human-like: branch on most constrained region.
        best = None
        best_key = None
        for i in range(R):
            if assigned[i] is None:
                # Secondary score: how constrained by adjacent singleton/degree.
                score = sum(1 for j in region_adj[i] if assigned[j] is not None)
                key = (len(domains[i]), -score, -len(region_adj[i]))
                if best is None or key < best_key:
                    best = i
                    best_key = key
        return best

    def final_check(assigned):
        # Build final shaded set.
        shaded = {}
        for i in range(R):
            cand = region_candidates[i][assigned[i]]
            for cell in cand["cells"]:
                shaded[cell] = cand["type"]

        # No 2x2 full shaded.
        for blk in blocks:
            if all(cell in shaded for cell in blk):
                return None

        # Whole-grid connectivity.
        cells = set(shaded)
        if len(cells) != 4 * R:
            return None
        start = next(iter(cells))
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for nr, nc in neighbors4(r, c, n, m):
                if (nr, nc) in cells and (nr, nc) not in seen:
                    seen.add((nr, nc))
                    q.append((nr, nc))
        if len(seen) != len(cells):
            return None

        out = [[None] * m for _ in range(n)]
        for (r, c), t in shaded.items():
            out[r][c] = t
        return out

    def search(domains, assigned):
        if not enforce_arc(domains, assigned):
            return None
        if all(assigned[i] is not None for i in range(R)):
            return final_check(assigned)

        r = choose_region(domains, assigned)

        # Branch ordering: prefer candidates that touch more regions, improving connectivity.
        options = list(domains[r])
        options.sort(
            key=lambda ix: (
                -sum(
                    1
                    for j in range(R)
                    if j != r and any(pair_touch(r, ix, j, jy) for jy in domains[j])
                ),
                region_candidates[r][ix]["type"],
            )
        )

        for ix in options:
            ndom = [set(d) for d in domains]
            nass = assigned[:]
            ndom[r] = {ix}
            nass[r] = ix
            res = search(ndom, nass)
            if res is not None:
                return res
        return None

    result = search(domains, assigned)
    return repr(result) if result is not None else "No Solution"


