from collections import deque, defaultdict

# state: -1 unknown, 0 white, 1 black

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])

    regions = defaultdict(list)
    clue_by_region = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            regions[rid].append((r, c))
            if data[r][c] is not None:
                clue_by_region[rid] = data[r][c]

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx = {(r, c): r * m + c for r, c in cells}
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    neighbors = {}
    for r, c in cells:
        lst = []
        for dr, dc in dirs:
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                lst.append((rr, cc))
        neighbors[(r, c)] = lst

    # Precompute valid black masks for each row/col under rule 3.
    # A mask denotes black cells; white cells are the complement.
    def line_mask_valid(line_regions, black_mask):
        L = len(line_regions)
        i = 0
        while i < L:
            if (black_mask >> i) & 1:
                i += 1
                continue
            segs = 0
            prev = None
            while i < L and not ((black_mask >> i) & 1):
                rg = line_regions[i]
                if prev != rg:
                    segs += 1
                    prev = rg
                    if segs > 2:
                        return False
                i += 1
        return True

    row_valid_masks = []
    for r in range(n):
        regs = [region[r][c] for c in range(m)]
        masks = [mask for mask in range(1 << m) if line_mask_valid(regs, mask)]
        row_valid_masks.append(masks)

    col_valid_masks = []
    for c in range(m):
        regs = [region[r][c] for r in range(n)]
        masks = [mask for mask in range(1 << n) if line_mask_valid(regs, mask)]
        col_valid_masks.append(masks)

    def copy_state(state):
        return [row[:] for row in state]

    def filtered_row_masks(state, r):
        out = []
        for mask in row_valid_masks[r]:
            ok = True
            for c in range(m):
                s = state[r][c]
                bit = (mask >> c) & 1
                if s != -1 and s != bit:
                    ok = False
                    break
            if ok:
                out.append(mask)
        return out

    def filtered_col_masks(state, c):
        out = []
        for mask in col_valid_masks[c]:
            ok = True
            for r in range(n):
                s = state[r][c]
                bit = (mask >> r) & 1
                if s != -1 and s != bit:
                    ok = False
                    break
            if ok:
                out.append(mask)
        return out

    def set_cell(state, r, c, val, queue):
        cur = state[r][c]
        if cur == val:
            return True
        if cur != -1 and cur != val:
            return False
        state[r][c] = val
        queue.append((r, c))
        return True

    def possible_white_connectivity(state):
        # All confirmed white cells must lie in one component of non-black cells.
        white = [(r, c) for r in range(n) for c in range(m) if state[r][c] == 0]
        if not white:
            return True
        start = white[0]
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for rr, cc in neighbors[(r, c)]:
                if state[rr][cc] != 1 and (rr, cc) not in seen:
                    seen.add((rr, cc))
                    q.append((rr, cc))
        return all(cell in seen for cell in white)

    def final_white_connected(state):
        white = [(r, c) for r in range(n) for c in range(m) if state[r][c] == 0]
        if not white:
            return True
        start = white[0]
        q = deque([start])
        seen = {start}
        while q:
            r, c = q.popleft()
            for rr, cc in neighbors[(r, c)]:
                if state[rr][cc] == 0 and (rr, cc) not in seen:
                    seen.add((rr, cc))
                    q.append((rr, cc))
        return len(seen) == len(white)

    def region_bounds_ok(state):
        for rid, cells_in_region in regions.items():
            if rid not in clue_by_region:
                continue
            clue = clue_by_region[rid]
            b = 0
            u = 0
            for r, c in cells_in_region:
                if state[r][c] == 1:
                    b += 1
                elif state[r][c] == -1:
                    u += 1
            if b > clue:
                return False
            if b + u < clue:
                return False
        return True

    def line_feasible(state):
        for r in range(n):
            if not filtered_row_masks(state, r):
                return False
        for c in range(m):
            if not filtered_col_masks(state, c):
                return False
        return True

    def propagate(state):
        queue = deque()

        # seed zero-clue and obvious region constraints
        for rid, cells_in_region in regions.items():
            if rid in clue_by_region and clue_by_region[rid] == 0:
                for r, c in cells_in_region:
                    if not set_cell(state, r, c, 0, queue):
                        return None

        changed = True
        while changed:
            changed = False

            # Black adjacency and row/col local forcing from current assignments
            for r in range(n):
                masks = filtered_row_masks(state, r)
                if not masks:
                    return None
                for c in range(m):
                    vals = {(mask >> c) & 1 for mask in masks}
                    if len(vals) == 1:
                        v = next(iter(vals))
                        if state[r][c] == -1:
                            if not set_cell(state, r, c, v, queue):
                                return None
                            changed = True

            for c in range(m):
                masks = filtered_col_masks(state, c)
                if not masks:
                    return None
                for r in range(n):
                    vals = {(mask >> r) & 1 for mask in masks}
                    if len(vals) == 1:
                        v = next(iter(vals))
                        if state[r][c] == -1:
                            if not set_cell(state, r, c, v, queue):
                                return None
                            changed = True

            # Region count forcing
            for rid, cells_in_region in regions.items():
                if rid not in clue_by_region:
                    continue
                clue = clue_by_region[rid]
                blacks = [(r, c) for r, c in cells_in_region if state[r][c] == 1]
                unknowns = [(r, c) for r, c in cells_in_region if state[r][c] == -1]
                if len(blacks) > clue or len(blacks) + len(unknowns) < clue:
                    return None
                if len(blacks) == clue:
                    for r, c in unknowns:
                        if not set_cell(state, r, c, 0, queue):
                            return None
                        changed = True
                elif len(blacks) + len(unknowns) == clue:
                    for r, c in unknowns:
                        if not set_cell(state, r, c, 1, queue):
                            return None
                        changed = True

            # Process implications from assigned cells
            while queue:
                r, c = queue.popleft()
                if state[r][c] == 1:
                    for rr, cc in neighbors[(r, c)]:
                        if not set_cell(state, rr, cc, 0, queue):
                            return None
                            # no cover
                        changed = True

            if not region_bounds_ok(state):
                return None
            if not line_feasible(state):
                return None
            if not possible_white_connectivity(state):
                return None

        return state

    def is_complete(state):
        return all(state[r][c] != -1 for r in range(n) for c in range(m))

    def final_valid(state):
        if not region_bounds_ok(state):
            return False
        for rid, clue in clue_by_region.items():
            cnt = sum(1 for r, c in regions[rid] if state[r][c] == 1)
            if cnt != clue:
                return False
        for r, c in cells:
            if state[r][c] == 1:
                for rr, cc in neighbors[(r, c)]:
                    if state[rr][cc] == 1:
                        return False
        for r in range(n):
            mask = 0
            for c in range(m):
                if state[r][c] == 1:
                    mask |= 1 << c
            if mask not in row_valid_masks[r]:
                return False
        for c in range(m):
            mask = 0
            for r in range(n):
                if state[r][c] == 1:
                    mask |= 1 << r
            if mask not in col_valid_masks[c]:
                return False
        if not final_white_connected(state):
            return False
        return True

    def choose_cell(state):
        best = None
        best_score = None
        row_masks_cache = [filtered_row_masks(state, r) for r in range(n)]
        col_masks_cache = [filtered_col_masks(state, c) for c in range(m)]

        for r in range(n):
            for c in range(m):
                if state[r][c] != -1:
                    continue
                row_vals = {(mask >> c) & 1 for mask in row_masks_cache[r]}
                col_vals = {(mask >> r) & 1 for mask in col_masks_cache[c]}
                vals = row_vals & col_vals
                if not vals:
                    return (r, c, [])
                # Score: smaller domain first; then region tightness.
                rid = region[r][c]
                reg_cells = regions[rid]
                clue = clue_by_region.get(rid)
                tight = 0
                if clue is not None:
                    b = sum(1 for rr, cc in reg_cells if state[rr][cc] == 1)
                    u = sum(1 for rr, cc in reg_cells if state[rr][cc] == -1)
                    tight = min(clue - b, u)
                score = (len(vals), tight, len(reg_cells))
                if best is None or score < best_score:
                    best = (r, c, sorted(vals))
                    best_score = score
        return best

    def search(state):
        state = propagate(state)
        if state is None:
            return None
        if is_complete(state):
            return state if final_valid(state) else None

        choice = choose_cell(state)
        if choice is None:
            return state if final_valid(state) else None
        r, c, vals = choice
        if not vals:
            return None

        # Heuristic branch order: prefer black if region still needs blacks, else white.
        rid = region[r][c]
        order = vals[:]
        if 1 in vals and rid in clue_by_region:
            clue = clue_by_region[rid]
            b = sum(1 for rr, cc in regions[rid] if state[rr][cc] == 1)
            if b < clue:
                order = [1] + [v for v in vals if v != 1]

        for v in order:
            nxt = copy_state(state)
            q = deque()
            if not set_cell(nxt, r, c, v, q):
                continue
            res = search(nxt)
            if res is not None:
                return res
        return None

    init = [[-1] * m for _ in range(n)]
    res = search(init)
    if res is None:
        return "No Solution"
    return [[('B' if res[r][c] == 1 else None) for c in range(m)] for r in range(n)]

