# Generalized solver skeleton for a stitch-placement puzzle.
# The implementation uses a strong propagation/search framework on a natural
# graph interpretation:
# - Holes are indexed by the given N x N grid.
# - A stitch is an undirected edge between orthogonally adjacent holes.
# - Only edges between different region IDs are candidates.
# - No two stitches share a hole, so selected edges form a matching.
# - Row/column clues count used holes.
#
# This is a generalized exact solver for that interpretation and includes
# human-like deductions:
# - row/column saturation
# - row/column impossibility checks
# - forced hole states from local edge domains
# - edge forcing/exclusion from clue bounds
# - MRV branching with consistency pruning
#
# If the supplied observation does not match this exact formalization,
# the solver safely returns "No Solution".

from collections import defaultdict

def solve(observation):
    region = observation["region"]
    row_target = observation["row_stitch_counts"]
    col_target = observation["col_stitch_counts"]
    n = len(region)
    if n == 0:
        return []

    # Candidate stitch edges: orthogonally adjacent holes whose cells belong
    # to different regions.
    edges = []
    edge_of_hole = [[] for _ in range(n * n)]

    def hid(r, c):
        return r * n + c

    for r in range(n):
        for c in range(n):
            if c + 1 < n and region[r][c] != region[r][c + 1]:
                u, v = hid(r, c), hid(r, c + 1)
                idx = len(edges)
                edges.append((u, v))
                edge_of_hole[u].append(idx)
                edge_of_hole[v].append(idx)
            if r + 1 < n and region[r][c] != region[r + 1][c]:
                u, v = hid(r, c), hid(r + 1, c)
                idx = len(edges)
                edges.append((u, v))
                edge_of_hole[u].append(idx)
                edge_of_hole[v].append(idx)

    m = len(edges)

    # Edge state: -1 unknown, 0 forbidden, 1 selected.
    edge_state = [-1] * m

    # Hole state: -1 unknown, 0 unused, 1 used.
    hole_state = [-1] * (n * n)

    row_used = [0] * n
    col_used = [0] * n
    row_unknown = [n] * n
    col_unknown = [n] * n

    # For fast local reasoning, track count of selected/available incident edges.
    inc_selected = [0] * (n * n)
    inc_unknown = [len(edge_of_hole[h]) for h in range(n * n)]

    # Trail for reversible updates.
    trail = []

    def mark():
        return len(trail)

    def undo(k):
        while len(trail) > k:
            kind, data = trail.pop()
            if kind == "edge":
                i, old = data
                edge_state[i] = old
            elif kind == "hole":
                h, old = data
                hole_state[h] = old
            elif kind == "row_used":
                r, old = data
                row_used[r] = old
            elif kind == "col_used":
                c, old = data
                col_used[c] = old
            elif kind == "row_unknown":
                r, old = data
                row_unknown[r] = old
            elif kind == "col_unknown":
                c, old = data
                col_unknown[c] = old
            elif kind == "inc_selected":
                h, old = data
                inc_selected[h] = old
            elif kind == "inc_unknown":
                h, old = data
                inc_unknown[h] = old

    def set_hole(h, val):
        old = hole_state[h]
        if old == val:
            return True
        if old != -1 and old != val:
            return False
        trail.append(("hole", (h, old)))
        hole_state[h] = val

        r, c = divmod(h, n)
        trail.append(("row_unknown", (r, row_unknown[r])))
        row_unknown[r] -= 1
        trail.append(("col_unknown", (c, col_unknown[c])))
        col_unknown[c] -= 1
        if val == 1:
            trail.append(("row_used", (r, row_used[r])))
            row_used[r] += 1
            trail.append(("col_used", (c, col_used[c])))
            col_used[c] += 1
        return True

    def set_edge(i, val):
        old = edge_state[i]
        if old == val:
            return True
        if old != -1 and old != val:
            return False
        trail.append(("edge", (i, old)))
        edge_state[i] = val
        u, v = edges[i]

        # One unknown incident edge disappears from both endpoints.
        trail.append(("inc_unknown", (u, inc_unknown[u])))
        inc_unknown[u] -= 1
        trail.append(("inc_unknown", (v, inc_unknown[v])))
        inc_unknown[v] -= 1

        if val == 1:
            trail.append(("inc_selected", (u, inc_selected[u])))
            inc_selected[u] += 1
            trail.append(("inc_selected", (v, inc_selected[v])))
            inc_selected[v] += 1
            if not set_hole(u, 1):
                return False
            if not set_hole(v, 1):
                return False
        return True

    def forbid_all_incident(h):
        for ei in edge_of_hole[h]:
            if edge_state[ei] == -1:
                if not set_edge(ei, 0):
                    return False
        return True

    def force_unique_incident(h):
        cand = [ei for ei in edge_of_hole[h] if edge_state[ei] == -1]
        if len(cand) != 1:
            return False
        return set_edge(cand[0], 1)

    def row_bounds_ok(r):
        return row_used[r] <= row_target[r] and row_used[r] + row_unknown[r] >= row_target[r]

    def col_bounds_ok(c):
        return col_used[c] <= col_target[c] and col_used[c] + col_unknown[c] >= col_target[c]

    def global_bounds_ok():
        for r in range(n):
            if not row_bounds_ok(r):
                return False
        for c in range(n):
            if not col_bounds_ok(c):
                return False
        return True

    def propagate():
        changed = True
        while changed:
            changed = False

            if not global_bounds_ok():
                return False

            # Hole-local deductions.
            for h in range(n * n):
                # At most one selected incident edge.
                if inc_selected[h] > 1:
                    return False

                hs = hole_state[h]
                avail = inc_selected[h] + inc_unknown[h]

                if hs == 0:
                    if inc_selected[h] != 0:
                        return False
                    if not forbid_all_incident(h):
                        return False
                    changed = True
                    continue

                if hs == 1:
                    if inc_selected[h] == 0 and inc_unknown[h] == 0:
                        return False
                    if inc_selected[h] == 1:
                        if not forbid_all_incident(h):
                            return False
                        changed = True
                    elif inc_selected[h] == 0:
                        if inc_unknown[h] == 0:
                            return False
                        if inc_unknown[h] == 1:
                            if not force_unique_incident(h):
                                return False
                            changed = True
                    continue

                # hs unknown
                if avail == 0:
                    if not set_hole(h, 0):
                        return False
                    changed = True
                    continue

                if inc_selected[h] == 1:
                    if not set_hole(h, 1):
                        return False
                    if not forbid_all_incident(h):
                        return False
                    changed = True
                    continue

                if inc_selected[h] > 1:
                    return False

            # Row/column saturation deductions.
            for r in range(n):
                if row_used[r] == row_target[r]:
                    for c in range(n):
                        h = hid(r, c)
                        if hole_state[h] == -1:
                            if not set_hole(h, 0):
                                return False
                            changed = True
                elif row_used[r] + row_unknown[r] == row_target[r]:
                    for c in range(n):
                        h = hid(r, c)
                        if hole_state[h] == -1:
                            if not set_hole(h, 1):
                                return False
                            changed = True

            for c in range(n):
                if col_used[c] == col_target[c]:
                    for r in range(n):
                        h = hid(r, c)
                        if hole_state[h] == -1:
                            if not set_hole(h, 0):
                                return False
                            changed = True
                elif col_used[c] + col_unknown[c] == col_target[c]:
                    for r in range(n):
                        h = hid(r, c)
                        if hole_state[h] == -1:
                            if not set_hole(h, 1):
                                return False
                            changed = True

            # Edge deductions from endpoint hole states.
            for i, (u, v) in enumerate(edges):
                if edge_state[i] != -1:
                    continue
                hu, hv = hole_state[u], hole_state[v]

                if hu == 0 or hv == 0:
                    if not set_edge(i, 0):
                        return False
                    changed = True
                    continue
                if hu == 1 and hv == 1:
                    # If either endpoint already has a selected edge elsewhere, this edge is impossible.
                    if inc_selected[u] == 1 or inc_selected[v] == 1:
                        if not set_edge(i, 0):
                            return False
                        changed = True
                        continue

            if not global_bounds_ok():
                return False

        return True

    def complete():
        return all(hs != -1 for hs in hole_state) and all(es != -1 for es in edge_state)

    def choose_branch():
        # Prefer a most constrained unresolved hole, then unresolved edge.
        best_h = None
        best_score = None
        for h in range(n * n):
            if hole_state[h] == -1:
                deg = inc_unknown[h]
                r, c = divmod(h, n)
                slack = min(row_target[r] - row_used[r], col_target[c] - col_used[c])
                score = (deg, slack)
                if best_score is None or score < best_score:
                    best_score = score
                    best_h = h
        if best_h is not None:
            r, c = divmod(best_h, n)
            need1 = (row_target[r] - row_used[r]) + (col_target[c] - col_used[c])
            # Heuristic value ordering.
            vals = [1, 0] if need1 > 0 else [0, 1]
            return ("hole", best_h, vals)

        best_e = None
        best_e_score = None
        for i, (u, v) in enumerate(edges):
            if edge_state[i] == -1:
                score = (inc_unknown[u] + inc_unknown[v],)
                if best_e_score is None or score < best_e_score:
                    best_e_score = score
                    best_e = i
        if best_e is not None:
            return ("edge", best_e, [1, 0])

        return None

    def search():
        if not propagate():
            return None
        if complete():
            if all(row_used[r] == row_target[r] for r in range(n)) and all(col_used[c] == col_target[c] for c in range(n)):
                return extract_solution()
            return None

        choice = choose_branch()
        if choice is None:
            return None

        typ, idx, values = choice
        for val in values:
            k = mark()
            ok = set_hole(idx, val) if typ == "hole" else set_edge(idx, val)
            if ok:
                ans = search()
                if ans is not None:
                    return ans
            undo(k)
        return None

    def extract_solution():
        out = []
        for i, st in enumerate(edge_state):
            if st == 1:
                u, v = edges[i]
                ur, uc = divmod(u, n)
                vr, vc = divmod(v, n)
                out.append([(ur, uc), (vr, vc)])
        return out

    ans = search()
    return ans if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

