from collections import deque, defaultdict
from itertools import combinations

UNKNOWN = -1
WHITE = 0
BLACK = 1

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx = {(r, c): r * m + c for r, c in cells}

    neighbors = {}
    for r, c in cells:
        adj = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                adj.append((rr, cc))
        neighbors[(r, c)] = adj

    regions = defaultdict(list)
    for r, c in cells:
        regions[region[r][c]].append((r, c))
    region_ids = sorted(regions)

    region_clue = {}
    for rid in region_ids:
        clue = None
        for r, c in regions[rid]:
            if data[r][c] is not None:
                clue = data[r][c]
                break
        region_clue[rid] = clue

    # Precompute valid internal black placements for numbered regions only.
    region_patterns = {}
    for rid in region_ids:
        clue = region_clue[rid]
        if clue is None:
            continue
        rcells = regions[rid]
        if clue < 0 or clue > len(rcells):
            return "No Solution"
        valid = []
        for comb in combinations(rcells, clue):
            s = set(comb)
            ok = True
            for cell in comb:
                for nb in neighbors[cell]:
                    if nb in s:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                valid.append(tuple(sorted(comb)))
        if not valid:
            return "No Solution"
        region_patterns[rid] = valid

    # Row/column white-line rule helper.
    def white_segment_regions_ok(state):
        # Confirmed-white consecutive segments may not already span > 2 regions.
        for r in range(n):
            c = 0
            while c < m:
                if state[r][c] != WHITE:
                    c += 1
                    continue
                regs = set()
                while c < m and state[r][c] == WHITE:
                    regs.add(region[r][c])
                    if len(regs) > 2:
                        return False
                    c += 1
        for c in range(m):
            r = 0
            while r < n:
                if state[r][c] != WHITE:
                    r += 1
                    continue
                regs = set()
                while r < n and state[r][c] == WHITE:
                    regs.add(region[r][c])
                    if len(regs) > 2:
                        return False
                    r += 1
        return True

    def final_line_rule(state):
        for r in range(n):
            c = 0
            while c < m:
                if state[r][c] == BLACK:
                    c += 1
                    continue
                regs = set()
                while c < m and state[r][c] != BLACK:
                    regs.add(region[r][c])
                    c += 1
                if len(regs) > 2:
                    return False
        for c in range(m):
            r = 0
            while r < n:
                if state[r][c] == BLACK:
                    r += 1
                    continue
                regs = set()
                while r < n and state[r][c] != BLACK:
                    regs.add(region[r][c])
                    r += 1
                if len(regs) > 2:
                    return False
        return True

    def set_cell(state, r, c, val):
        cur = state[r][c]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False
        state[r][c] = val
        return True

    def available_white_connectivity_ok(state):
        # All confirmed white cells must lie in one component of the graph of non-black cells.
        nonblack = [(r, c) for r, c in cells if state[r][c] != BLACK]
        if not nonblack:
            return False
        white_cells = [(r, c) for r, c in cells if state[r][c] == WHITE]
        if not white_cells:
            return True

        start = white_cells[0]
        q = deque([start])
        seen = {start}
        while q:
            u = q.popleft()
            for v in neighbors[u]:
                if state[v[0]][v[1]] != BLACK and v not in seen:
                    seen.add(v)
                    q.append(v)
        for w in white_cells:
            if w not in seen:
                return False
        return True

    def final_white_connected(state):
        whites = [(r, c) for r, c in cells if state[r][c] == WHITE]
        if not whites:
            return False
        start = whites[0]
        q = deque([start])
        seen = {start}
        while q:
            u = q.popleft()
            for v in neighbors[u]:
                if state[v[0]][v[1]] == WHITE and v not in seen:
                    seen.add(v)
                    q.append(v)
        return len(seen) == len(whites)

    def no_black_adjacency(state):
        for r, c in cells:
            if state[r][c] == BLACK:
                for rr, cc in neighbors[(r, c)]:
                    if state[rr][cc] == BLACK:
                        return False
        return True

    def region_count_bounds_ok(state):
        for rid in region_ids:
            clue = region_clue[rid]
            if clue is None:
                continue
            b = 0
            u = 0
            for r, c in regions[rid]:
                if state[r][c] == BLACK:
                    b += 1
                elif state[r][c] == UNKNOWN:
                    u += 1
            if b > clue or b + u < clue:
                return False
        return True

    def propagate(state):
        changed = True
        while changed:
            changed = False

            # Basic black adjacency forcing.
            for r, c in cells:
                if state[r][c] == BLACK:
                    for rr, cc in neighbors[(r, c)]:
                        if state[rr][cc] == BLACK:
                            return None
                        if state[rr][cc] == UNKNOWN:
                            if not set_cell(state, rr, cc, WHITE):
                                return None
                            changed = True

            # Region simple count propagation.
            for rid in region_ids:
                clue = region_clue[rid]
                if clue is None:
                    continue
                rcells = regions[rid]
                blacks = [cell for cell in rcells if state[cell[0]][cell[1]] == BLACK]
                unknowns = [cell for cell in rcells if state[cell[0]][cell[1]] == UNKNOWN]
                if len(blacks) > clue or len(blacks) + len(unknowns) < clue:
                    return None
                if len(blacks) == clue:
                    for r, c in unknowns:
                        if not set_cell(state, r, c, WHITE):
                            return None
                        changed = True
                elif len(blacks) + len(unknowns) == clue:
                    for r, c in unknowns:
                        if not set_cell(state, r, c, BLACK):
                            return None
                        changed = True

            # Pattern-based propagation for numbered regions.
            for rid, patterns in region_patterns.items():
                valid = []
                rcells = regions[rid]
                for pat in patterns:
                    pset = set(pat)
                    ok = True

                    # Inside region assignment consistency.
                    for r, c in rcells:
                        st = state[r][c]
                        if st == BLACK and (r, c) not in pset:
                            ok = False
                            break
                        if st == WHITE and (r, c) in pset:
                            ok = False
                            break
                    if not ok:
                        continue

                    # External adjacency to existing black cells.
                    for r, c in pat:
                        for rr, cc in neighbors[(r, c)]:
                            if region[rr][cc] != rid and state[rr][cc] == BLACK:
                                ok = False
                                break
                        if not ok:
                            break

                    if ok:
                        valid.append(pset)

                if not valid:
                    return None

                # If a cell is black in all valid patterns, force black.
                # If in none, force white.
                for r, c in rcells:
                    in_count = sum((r, c) in v for v in valid)
                    if in_count == len(valid):
                        if not set_cell(state, r, c, BLACK):
                            return None
                        changed = True
                    elif in_count == 0:
                        if not set_cell(state, r, c, WHITE):
                            return None
                        changed = True

            if not no_black_adjacency(state):
                return None
            if not region_count_bounds_ok(state):
                return None
            if not white_segment_regions_ok(state):
                return None
            if not available_white_connectivity_ok(state):
                return None

        return state

    def is_solved(state):
        for r, c in cells:
            if state[r][c] == UNKNOWN:
                return False
        if not no_black_adjacency(state):
            return False
        if not region_count_bounds_ok(state):
            return False
        for rid in region_ids:
            clue = region_clue[rid]
            if clue is None:
                continue
            if sum(state[r][c] == BLACK for r, c in regions[rid]) != clue:
                return False
        if not final_line_rule(state):
            return False
        if not final_white_connected(state):
            return False
        return True

    def score_cell(state, cell):
        r, c = cell
        s = 0
        rid = region[r][c]
        if region_clue[rid] is not None:
            s += 10
        for rr, cc in neighbors[(r, c)]:
            if state[rr][cc] != UNKNOWN:
                s += 2
            if region_clue[region[rr][cc]] is not None:
                s += 1
        return -s

    def choose_branch_cell(state):
        # Prefer unknown in numbered regions / constrained neighborhood.
        candidates = [(r, c) for r, c in cells if state[r][c] == UNKNOWN]
        candidates.sort(key=lambda cell: score_cell(state, cell))
        if not candidates:
            return None
        return candidates[0]

    def deep_copy_state(state):
        return [row[:] for row in state]

    def search(state):
        state = propagate(state)
        if state is None:
            return None
        if is_solved(state):
            return state

        cell = choose_branch_cell(state)
        if cell is None:
            return None
        r, c = cell

        # Branch order: try the more plausible value first.
        # In numbered regions with remaining quota, black is often more informative.
        rid = region[r][c]
        values = [BLACK, WHITE] if region_clue[rid] is not None else [WHITE, BLACK]

        for val in values:
            nxt = deep_copy_state(state)
            if set_cell(nxt, r, c, val):
                ans = search(nxt)
                if ans is not None:
                    return ans
        return None

    init = [[UNKNOWN] * m for _ in range(n)]
    result = search(init)
    if result is None:
        return "No Solution"
    return [['B' if result[r][c] == BLACK else None for c in range(m)] for r in range(n)]

if __name__ == "__main__":
    print(solve(OBSERVATION))

