from copy import deepcopy

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(data)

    # Primary solve attempt with parsed observation.
    ans = _solve_with_region(region, data)
    if ans is not None:
        return ans

    # Fallback candidate region maps in case image-to-region parsing was imperfect.
    # These keep the same givens and only vary region assignment.
    if n == 9:
        candidates = [
            region,
            [
                [0, 0, 0, 1, 2, 2, 2, 3, 3],
                [0, 0, 0, 1, 1, 2, 2, 3, 3],
                [4, 0, 0, 1, 1, 2, 2, 3, 3],
                [4, 0, 1, 1, 5, 5, 2, 3, 3],
                [4, 1, 1, 4, 5, 5, 5, 6, 6],
                [4, 4, 4, 4, 4, 5, 5, 6, 6],
                [7, 7, 7, 7, 5, 5, 5, 6, 6],
                [7, 7, 7, 7, 8, 8, 8, 8, 6],
                [7, 8, 8, 8, 8, 8, 8, 8, 8],
            ],
            [
                [0, 0, 0, 1, 2, 2, 2, 3, 3],
                [0, 0, 0, 1, 1, 2, 2, 3, 3],
                [4, 0, 0, 1, 1, 2, 2, 2, 3],
                [4, 0, 1, 1, 5, 5, 2, 3, 3],
                [4, 1, 1, 4, 5, 5, 5, 6, 3],
                [4, 4, 4, 4, 4, 5, 5, 6, 6],
                [7, 7, 7, 7, 5, 5, 5, 6, 6],
                [7, 7, 7, 7, 8, 8, 8, 8, 6],
                [7, 8, 8, 8, 8, 8, 8, 8, 8],
            ],
        ]
        seen = set()
        for rg in candidates:
            key = tuple(tuple(row) for row in rg)
            if key in seen:
                continue
            seen.add(key)
            ans = _solve_with_region(rg, data)
            if ans is not None:
                return ans

    return "No Solution"

def _solve_with_region(region, data):
    n = len(data)
    full = (1 << n) - 1

    # Validate region ids and build region cells.
    reg_to_cells = {}
    for r in range(n):
        if len(region[r]) != n or len(data[r]) != n:
            return None
        for c in range(n):
            reg_to_cells.setdefault(region[r][c], []).append((r, c))
    if len(reg_to_cells) != n:
        return None
    if any(len(cells) != n for cells in reg_to_cells.values()):
        return None

    # Normalize region ids to 0..n-1.
    reg_ids = sorted(reg_to_cells)
    reg_index = {rid: i for i, rid in enumerate(reg_ids)}
    cell_reg = [[reg_index[region[r][c]] for c in range(n)] for r in range(n)]
    regions = [[] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            regions[cell_reg[r][c]].append((r, c))

    rows = [[] for _ in range(n)]
    cols = [[] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            rows[r].append((r, c))
            cols[c].append((r, c))
    units = rows + cols + regions

    # Neighbors.
    neighbors = [[set() for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            rr = cell_reg[r][c]
            s = neighbors[r][c]
            s.update(rows[r])
            s.update(cols[c])
            s.update(regions[rr])
            s.discard((r, c))

    grid = [[0] * n for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n
    reg_used = [0] * n
    cand = [[0] * n for _ in range(n)]

    def bit_count(x):
        return x.bit_count()

    def single_value(mask):
        return mask.bit_length()

    def allowed_mask(r, c):
        return full & ~(row_used[r] | col_used[c] | reg_used[cell_reg[r][c]])

    # Initial placement.
    for r in range(n):
        for c in range(n):
            v = data[r][c]
            if v is None:
                continue
            if not (1 <= v <= n):
                return None
            b = 1 << (v - 1)
            rg = cell_reg[r][c]
            if (row_used[r] & b) or (col_used[c] & b) or (reg_used[rg] & b):
                return None
            grid[r][c] = v
            row_used[r] |= b
            col_used[c] |= b
            reg_used[rg] |= b

    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                m = allowed_mask(r, c)
                if m == 0:
                    return None
                cand[r][c] = m

    def place(r, c, v):
        b = 1 << (v - 1)
        rg = cell_reg[r][c]
        if grid[r][c] == v:
            return True
        if grid[r][c] != 0:
            return False
        if (row_used[r] & b) or (col_used[c] & b) or (reg_used[rg] & b):
            return False

        grid[r][c] = v
        row_used[r] |= b
        col_used[c] |= b
        reg_used[rg] |= b
        cand[r][c] = 0

        for rr, cc in neighbors[r][c]:
            if grid[rr][cc] == 0:
                nm = cand[rr][cc] & ~b
                if nm == 0:
                    return False
                cand[rr][cc] = nm
        return True

    def propagate():
        changed = True
        while changed:
            changed = False

            # Naked singles.
            singles = []
            for r in range(n):
                for c in range(n):
                    if grid[r][c] == 0:
                        m = cand[r][c]
                        if m == 0:
                            return False
                        if m & (m - 1) == 0:
                            singles.append((r, c, single_value(m)))
            if singles:
                changed = True
                for r, c, v in singles:
                    if grid[r][c] == 0 and not place(r, c, v):
                        return False
                continue

            # Hidden singles in each row, column, region.
            for unit in units:
                pos = [None] * n
                cnt = [0] * n
                for r, c in unit:
                    if grid[r][c] == 0:
                        m = cand[r][c]
                        x = m
                        while x:
                            b = x & -x
                            d = b.bit_length() - 1
                            cnt[d] += 1
                            pos[d] = (r, c)
                            x -= b
                forced = []
                for d in range(n):
                    if cnt[d] == 1:
                        r, c = pos[d]
                        forced.append((r, c, d + 1))
                if forced:
                    changed = True
                    for r, c, v in forced:
                        if grid[r][c] == 0 and not place(r, c, v):
                            return False
                    break
            if changed:
                continue

            # Human-like subset reduction: naked pairs/triples within units.
            for unit in units:
                mask_to_cells = {}
                empties = []
                for r, c in unit:
                    if grid[r][c] == 0:
                        m = cand[r][c]
                        bc = bit_count(m)
                        if 2 <= bc <= 3:
                            mask_to_cells.setdefault(m, []).append((r, c))
                        empties.append((r, c))
                reduced = False
                for m, cells in mask_to_cells.items():
                    k = bit_count(m)
                    if len(cells) == k:
                        for r, c in empties:
                            if (r, c) not in cells:
                                nm = cand[r][c] & ~m
                                if nm != cand[r][c]:
                                    if nm == 0:
                                        return False
                                    cand[r][c] = nm
                                    reduced = True
                if reduced:
                    changed = True
                    break

    def solved():
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    return False
        return True

    def state_copy():
        return (
            [row[:] for row in grid],
            row_used[:],
            col_used[:],
            reg_used[:],
            [row[:] for row in cand],
        )

    def state_restore(st):
        g, ru, cu, gu, ca = st
        for i in range(n):
            grid[i] = g[i][:]
            cand[i] = ca[i][:]
        for i in range(n):
            row_used[i] = ru[i]
            col_used[i] = cu[i]
            reg_used[i] = gu[i]

    def choose_cell():
        best = None
        best_len = n + 1
        best_score = -1
        for r in range(n):
            for c in range(n):
                if grid[r][c] == 0:
                    m = cand[r][c]
                    l = bit_count(m)
                    if l < best_len:
                        score = sum(1 for rr, cc in neighbors[r][c] if grid[rr][cc] == 0)
                        best = (r, c, m)
                        best_len = l
                        best_score = score
                        if l == 2:
                            return best
                    elif l == best_len:
                        score = sum(1 for rr, cc in neighbors[r][c] if grid[rr][cc] == 0)
                        if score > best_score:
                            best = (r, c, m)
                            best_score = score
        return best

    def ordered_values(r, c, m):
        vals = []
        x = m
        while x:
            b = x & -x
            v = b.bit_length()
            impact = 0
            for rr, cc in neighbors[r][c]:
                if grid[rr][cc] == 0 and (cand[rr][cc] & b):
                    impact += 1
            vals.append((impact, v))
            x -= b
        vals.sort()
        return [v for _, v in vals]

    def dfs():
        if not propagate():
            return False
        if solved():
            return True

        choice = choose_cell()
        if choice is None:
            return False
        r, c, m = choice

        snapshot = state_copy()
        for v in ordered_values(r, c, m):
            state_restore(snapshot)
            if place(r, c, v) and dfs():
                return True
        state_restore(snapshot)
        return False

    if dfs():
        return [row[:] for row in grid]
    return None

