# Weighted black-cell puzzle solver.
# General rule assumed from the puzzle family:
# - Column weights are 1..n from left to right.
# - Row weights are 1..m from top to bottom.
# - A black cell at (r, c) contributes (c+1) to row r's total and (r+1) to column c's total.

from collections import deque

def bits(mask, n):
    i = 0
    while mask:
        if mask & 1:
            yield i
        mask >>= 1
        i += 1

def popcount(x):
    return x.bit_count()

def subset_sums_by_target(weights):
    n = len(weights)
    out = {}
    for mask in range(1 << n):
        s = 0
        mm = mask
        i = 0
        while mm:
            if mm & 1:
                s += weights[i]
            mm >>= 1
            i += 1
        out.setdefault(s, []).append(mask)
    return out

def domain_cell_bounds(patterns, width):
    if not patterns:
        return None, None
    all1 = (1 << width) - 1
    must1 = all1
    may1 = 0
    for p in patterns:
        must1 &= p
        may1 |= p
    return must1, may1

def filter_patterns_by_cell(patterns, col, val):
    bit = 1 << col
    if val:
        return [p for p in patterns if p & bit]
    return [p for p in patterns if not (p & bit)]

def transpose_cell_support_row_to_col(row_patterns, m, n):
    row_must = [0] * m
    row_may = [0] * m
    for r in range(m):
        must1, may1 = domain_cell_bounds(row_patterns[r], n)
        row_must[r] = must1
        row_may[r] = may1
    col_must = [0] * n
    col_may = [0] * n
    for c in range(n):
        cmust = 0
        cmay = 0
        bit = 1 << c
        for r in range(m):
            if row_must[r] & bit:
                cmust |= 1 << r
            if row_may[r] & bit:
                cmay |= 1 << r
        col_must[c] = cmust
        col_may[c] = cmay
    return col_must, col_may

def transpose_cell_support_col_to_row(col_patterns, m, n):
    col_must = [0] * n
    col_may = [0] * n
    for c in range(n):
        must1, may1 = domain_cell_bounds(col_patterns[c], m)
        col_must[c] = must1
        col_may[c] = may1
    row_must = [0] * m
    row_may = [0] * m
    for r in range(m):
        rmust = 0
        rmay = 0
        bit = 1 << r
        for c in range(n):
            if col_must[c] & bit:
                rmust |= 1 << c
            if col_may[c] & bit:
                rmay |= 1 << c
        row_must[r] = rmust
        row_may[r] = rmay
    return row_must, row_may

def narrow_patterns_by_bounds(patterns, must_mask, may_mask):
    return [p for p in patterns if (p & must_mask) == must_mask and (p | may_mask) == may_mask]

def enforce_arc_consistency(row_patterns, col_patterns, m, n):
    # Human-like repeated deductions:
    # 1) derive forced/possible black cells from row candidates
    # 2) prune column candidates that violate those cell possibilities
    # 3) derive forced/possible cells from column candidates
    # 4) prune row candidates likewise
    # Repeat to fixpoint.
    changed = True
    while changed:
        changed = False

        # Row -> Column
        col_must_from_rows, col_may_from_rows = transpose_cell_support_row_to_col(row_patterns, m, n)
        for c in range(n):
            before = len(col_patterns[c])
            col_patterns[c] = narrow_patterns_by_bounds(
                col_patterns[c], col_must_from_rows[c], col_may_from_rows[c]
            )
            if not col_patterns[c]:
                return None
            if len(col_patterns[c]) != before:
                changed = True

        # Column -> Row
        row_must_from_cols, row_may_from_cols = transpose_cell_support_col_to_row(col_patterns, m, n)
        for r in range(m):
            before = len(row_patterns[r])
            row_patterns[r] = narrow_patterns_by_bounds(
                row_patterns[r], row_must_from_cols[r], row_may_from_cols[r]
            )
            if not row_patterns[r]:
                return None
            if len(row_patterns[r]) != before:
                changed = True

    return row_patterns, col_patterns

def select_branch(row_patterns, col_patterns):
    # Choose the most constrained unresolved row/column.
    best = None

    for r, pats in enumerate(row_patterns):
        lp = len(pats)
        if 1 < lp and (best is None or lp < best[0]):
            best = (lp, 'r', r)

    for c, pats in enumerate(col_patterns):
        lp = len(pats)
        if 1 < lp and (best is None or lp < best[0]):
            best = (lp, 'c', c)

    return best

def verify_solution(row_masks, col_masks, row_sum, col_sum):
    m = len(row_sum)
    n = len(col_sum)

    for r in range(m):
        s = 0
        mask = row_masks[r]
        c = 0
        while mask:
            if mask & 1:
                s += c + 1
            mask >>= 1
            c += 1
        if s != row_sum[r]:
            return False

    for c in range(n):
        s = 0
        mask = col_masks[c]
        r = 0
        while mask:
            if mask & 1:
                s += r + 1
            mask >>= 1
            r += 1
        if s != col_sum[c]:
            return False

    for r in range(m):
        for c in range(n):
            a = (row_masks[r] >> c) & 1
            b = (col_masks[c] >> r) & 1
            if a != b:
                return False

    return True

def search(row_patterns, col_patterns, m, n, row_sum, col_sum):
    ac = enforce_arc_consistency(
        [list(p) for p in row_patterns],
        [list(p) for p in col_patterns],
        m, n
    )
    if ac is None:
        return None
    row_patterns, col_patterns = ac

    if all(len(p) == 1 for p in row_patterns) and all(len(p) == 1 for p in col_patterns):
        row_masks = [p[0] for p in row_patterns]
        col_masks = [p[0] for p in col_patterns]
        if verify_solution(row_masks, col_masks, row_sum, col_sum):
            return row_masks
        return None

    choice = select_branch(row_patterns, col_patterns)
    if choice is None:
        return None

    _, kind, idx = choice

    if kind == 'r':
        candidates = row_patterns[idx]
        # Try patterns that are more constrained first: larger popcount often propagates harder.
        candidates = sorted(candidates, key=lambda x: (popcount(x), x))
        for pat in candidates:
            new_rows = [list(p) for p in row_patterns]
            new_cols = [list(p) for p in col_patterns]
            new_rows[idx] = [pat]
            res = search(new_rows, new_cols, m, n, row_sum, col_sum)
            if res is not None:
                return res
    else:
        candidates = col_patterns[idx]
        candidates = sorted(candidates, key=lambda x: (popcount(x), x))
        for pat in candidates:
            new_rows = [list(p) for p in row_patterns]
            new_cols = [list(p) for p in col_patterns]
            new_cols[idx] = [pat]
            res = search(new_rows, new_cols, m, n, row_sum, col_sum)
            if res is not None:
                return res

    return None

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    m = len(row_sum)
    n = len(col_sum)

    row_weights = list(range(1, m + 1))
    col_weights = list(range(1, n + 1))

    # Generate all feasible row and column patterns by weighted subset sum.
    row_subset_map = subset_sums_by_target(col_weights)
    col_subset_map = subset_sums_by_target(row_weights)

    row_patterns = []
    for target in row_sum:
        pats = row_subset_map.get(target, [])
        if not pats:
            return "No Solution"
        row_patterns.append(list(pats))

    col_patterns = []
    for target in col_sum:
        pats = col_subset_map.get(target, [])
        if not pats:
            return "No Solution"
        col_patterns.append(list(pats))

    result = search(row_patterns, col_patterns, m, n, row_sum, col_sum)
    if result is None:
        return "No Solution"

    grid = []
    for r in range(m):
        row = []
        mask = result[r]
        for c in range(n):
            row.append('B' if (mask >> c) & 1 else None)
        grid.append(row)
    return str(grid)

