from itertools import combinations

def solve(observation):
    grid = [row[:] for row in observation['data']]
    br, bc = _parse_unit(observation['unit'])
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"
    if br * bc != n:
        return "No Solution"

    digits = set(range(1, n + 1))
    rows = [set() for _ in range(n)]
    cols = [set() for _ in range(n)]
    boxes = [set() for _ in range(n)]

    cell_to_box = [[(r // br) * (n // bc) + (c // bc) for c in range(n)] for r in range(n)]

    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            if v is None:
                continue
            if not isinstance(v, int) or not (1 <= v <= n):
                return "No Solution"
            b = cell_to_box[r][c]
            if v in rows[r] or v in cols[c] or v in boxes[b]:
                return "No Solution"
            rows[r].add(v)
            cols[c].add(v)
            boxes[b].add(v)

    peers = {}
    units_of_cell = {}
    row_units = [[(r, c) for c in range(n)] for r in range(n)]
    col_units = [[(r, c) for r in range(n)] for c in range(n)]
    box_units = []
    for rb in range(0, n, br):
        for cb in range(0, n, bc):
            box_units.append([(r, c) for r in range(rb, rb + br) for c in range(cb, cb + bc)])
    all_units = row_units + col_units + box_units

    for r in range(n):
        for c in range(n):
            b = cell_to_box[r][c]
            u = [row_units[r], col_units[c], box_units[b]]
            units_of_cell[(r, c)] = u
            s = set(u[0]) | set(u[1]) | set(u[2])
            s.discard((r, c))
            peers[(r, c)] = tuple(s)

    cand = [[0] * n for _ in range(n)]
    full_mask = (1 << n) - 1

    def val_mask(v):
        return 1 << (v - 1)

    def bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length()
            mask ^= lsb

    def bit_count(mask):
        return mask.bit_count()

    def candidate_mask(r, c):
        used = rows[r] | cols[c] | boxes[cell_to_box[r][c]]
        mask = 0
        for v in digits - used:
            mask |= val_mask(v)
        return mask

    for r in range(n):
        for c in range(n):
            if grid[r][c] is None:
                m = candidate_mask(r, c)
                if m == 0:
                    return "No Solution"
                cand[r][c] = m
            else:
                cand[r][c] = val_mask(grid[r][c])

    def assign(r, c, v):
        old = grid[r][c]
        if old == v:
            return True
        if old is not None:
            return False
        b = cell_to_box[r][c]
        if v in rows[r] or v in cols[c] or v in boxes[b]:
            return False
        grid[r][c] = v
        rows[r].add(v)
        cols[c].add(v)
        boxes[b].add(v)
        cand[r][c] = val_mask(v)
        vm = val_mask(v)
        for pr, pc in peers[(r, c)]:
            if grid[pr][pc] is None and (cand[pr][pc] & vm):
                cand[pr][pc] &= ~vm
                if cand[pr][pc] == 0:
                    return False
        return True

    def eliminate_mask(cells, mask):
        changed = False
        inv = ~mask
        for r, c in cells:
            if grid[r][c] is None:
                newm = cand[r][c] & inv
                if newm != cand[r][c]:
                    cand[r][c] = newm
                    if newm == 0:
                        return None
                    changed = True
        return changed

    def apply_naked_subsets(unit_cells, size):
        changed = False
        unsolved = [(r, c) for r, c in unit_cells if grid[r][c] is None]
        if len(unsolved) <= size:
            return False
        groups = {}
        for rc in unsolved:
            m = cand[rc[0]][rc[1]]
            bc = bit_count(m)
            if 2 <= bc <= size:
                groups.setdefault(m, []).append(rc)
        for m, cells in groups.items():
            if bit_count(m) == size and len(cells) == size:
                others = [rc for rc in unsolved if rc not in cells]
                res = eliminate_mask(others, m)
                if res is None:
                    return None
                changed |= res
        return changed

    def apply_hidden_subsets(unit_cells, size):
        changed = False
        unsolved = [(r, c) for r, c in unit_cells if grid[r][c] is None]
        if len(unsolved) <= size:
            return False
        digit_places = {}
        for d in range(1, n + 1):
            vm = val_mask(d)
            places = [rc for rc in unsolved if cand[rc[0]][rc[1]] & vm]
            if 1 <= len(places) <= size:
                digit_places[d] = tuple(places)
        buckets = {}
        for d, places in digit_places.items():
            buckets.setdefault(places, 0)
            buckets[places] |= val_mask(d)
        for places, dmask in buckets.items():
            if len(places) == size and bit_count(dmask) == size:
                for r, c in places:
                    newm = cand[r][c] & dmask
                    if newm == 0:
                        return None
                    if newm != cand[r][c]:
                        cand[r][c] = newm
                        changed = True
        return changed

    def hidden_singles():
        changed = False
        for unit in all_units:
            counts = [0] * (n + 1)
            last = [None] * (n + 1)
            for r, c in unit:
                if grid[r][c] is None:
                    m = cand[r][c]
                    for d in bits(m):
                        counts[d] += 1
                        last[d] = (r, c)
            for d in range(1, n + 1):
                if counts[d] == 1:
                    r, c = last[d]
                    if grid[r][c] is None:
                        if not assign(r, c, d):
                            return None
                        changed = True
        return changed

    def naked_singles():
        changed = False
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    m = cand[r][c]
                    if m == 0:
                        return None
                    if m & (m - 1) == 0:
                        if not assign(r, c, m.bit_length()):
                            return None
                        changed = True
        return changed

    def locked_candidates():
        changed = False
        for b_idx, unit in enumerate(box_units):
            for d in range(1, n + 1):
                vm = val_mask(d)
                cells = [(r, c) for r, c in unit if grid[r][c] is None and (cand[r][c] & vm)]
                if len(cells) <= 1:
                    continue
                rs = {r for r, _ in cells}
                cs = {c for _, c in cells}
                if len(rs) == 1:
                    r = next(iter(rs))
                    others = [(rr, cc) for rr, cc in row_units[r] if cell_to_box[rr][cc] != b_idx]
                    res = eliminate_mask(others, vm)
                    if res is None:
                        return None
                    changed |= res
                if len(cs) == 1:
                    c = next(iter(cs))
                    others = [(rr, cc) for rr, cc in col_units[c] if cell_to_box[rr][cc] != b_idx]
                    res = eliminate_mask(others, vm)
                    if res is None:
                        return None
                    changed |= res

        for r in range(n):
            for d in range(1, n + 1):
                vm = val_mask(d)
                cells = [(rr, cc) for rr, cc in row_units[r] if grid[rr][cc] is None and (cand[rr][cc] & vm)]
                if len(cells) <= 1:
                    continue
                bs = {cell_to_box[rr][cc] for rr, cc in cells}
                if len(bs) == 1:
                    b = next(iter(bs))
                    others = [rc for rc in box_units[b] if rc[0] != r]
                    res = eliminate_mask(others, vm)
                    if res is None:
                        return None
                    changed |= res

        for c in range(n):
            for d in range(1, n + 1):
                vm = val_mask(d)
                cells = [(rr, cc) for rr, cc in col_units[c] if grid[rr][cc] is None and (cand[rr][cc] & vm)]
                if len(cells) <= 1:
                    continue
                bs = {cell_to_box[rr][cc] for rr, cc in cells}
                if len(bs) == 1:
                    b = next(iter(bs))
                    others = [rc for rc in box_units[b] if rc[1] != c]
                    res = eliminate_mask(others, vm)
                    if res is None:
                        return None
                    changed |= res
        return changed

    def consistency_check():
        for r in range(n):
            if len(rows[r]) != len(set(rows[r])):
                return False
            for d in range(1, n + 1):
                if d not in rows[r]:
                    if not any(grid[r][c] is None and (cand[r][c] & val_mask(d)) for c in range(n)):
                        return False
        for c in range(n):
            for d in range(1, n + 1):
                if d not in cols[c]:
                    if not any(grid[r][c] is None and (cand[r][c] & val_mask(d)) for r in range(n)):
                        return False
        for b, unit in enumerate(box_units):
            for d in range(1, n + 1):
                if d not in boxes[b]:
                    if not any(grid[r][c] is None and (cand[r][c] & val_mask(d)) for r, c in unit):
                        return False
        return True

    def propagate():
        while True:
            progress = False

            res = naked_singles()
            if res is None:
                return False
            progress |= res

            res = hidden_singles()
            if res is None:
                return False
            progress |= res

            res = locked_candidates()
            if res is None:
                return False
            progress |= res

            for unit in all_units:
                for size in (2, 3):
                    res = apply_naked_subsets(unit, size)
                    if res is None:
                        return False
                    progress |= res
                for size in (2, 3):
                    res = apply_hidden_subsets(unit, size)
                    if res is None:
                        return False
                    progress |= res

            res = naked_singles()
            if res is None:
                return False
            progress |= res

            if not consistency_check():
                return False

            if not progress:
                return True

    def solved():
        return all(grid[r][c] is not None for r in range(n) for c in range(n))

    def snapshot():
        return (
            [row[:] for row in grid],
            [s.copy() for s in rows],
            [s.copy() for s in cols],
            [s.copy() for s in boxes],
            [row[:] for row in cand],
        )

    def restore(state):
        g, rs, cs, bs, cd = state
        for i in range(n):
            grid[i] = g[i][:]
            rows[i] = rs[i].copy()
            cols[i] = cs[i].copy()
            boxes[i] = bs[i].copy()
            cand[i] = cd[i][:]

    def choose_branch_cell():
        best = None
        best_count = n + 1
        best_score = None
        for r in range(n):
            for c in range(n):
                if grid[r][c] is None:
                    m = cand[r][c]
                    bc_ = bit_count(m)
                    if bc_ < best_count:
                        score = sum(1 for pr, pc in peers[(r, c)] if grid[pr][pc] is None)
                        best = (r, c)
                        best_count = bc_
                        best_score = score
                    elif bc_ == best_count and bc_ > 1:
                        score = sum(1 for pr, pc in peers[(r, c)] if grid[pr][pc] is None)
                        if best_score is None or score > best_score:
                            best = (r, c)
                            best_score = score
        return best

    def ordered_values(r, c):
        vals = list(bits(cand[r][c]))
        impact = []
        for v in vals:
            vm = val_mask(v)
            score = 0
            for pr, pc in peers[(r, c)]:
                if grid[pr][pc] is None and (cand[pr][pc] & vm):
                    score += 1
            impact.append((score, v))
        impact.sort()
        return [v for _, v in impact]

    def search():
        if not propagate():
            return False
        if solved():
            return True

        cell = choose_branch_cell()
        if cell is None:
            return False
        r, c = cell
        values = ordered_values(r, c)
        state = snapshot()
        for v in values:
            restore(state)
            if assign(r, c, v) and search():
                return True
        restore(state)
        return False

    if not search():
        return "No Solution"
    return grid

def _parse_unit(unit):
    if isinstance(unit, str):
        parts = unit.lower().split('x')
        if len(parts) == 1:
            v = int(parts[0])
            return v, v
        if len(parts) == 2:
            return int(parts[0]), int(parts[1])
    raise ValueError("Invalid unit")

