from itertools import product

B, W = "B", "W"


def parse_constraints(d):
    out = {}
    for k, v in d.items():
        a, b = eval(k, {}, {})
        out[(float(a), float(b))] = v
    return out


def generate_line_patterns(length, eq_positions, neq_positions):
    half = length // 2
    vals = (B, W)
    patterns = []

    def rec(i, cur, cb, cw):
        if cb > half or cw > half:
            return
        if i >= 2 and cur[i - 1] == cur[i - 2]:
            forced = W if cur[i - 1] == B else B
            if i in eq_positions:
                if cur[i - 1] != forced:
                    return
            if i in neq_positions:
                if cur[i - 1] == forced:
                    return
            if forced == B:
                if cb + 1 > half:
                    return
                rec(i + 1, cur + [B], cb + 1, cw)
            else:
                if cw + 1 > half:
                    return
                rec(i + 1, cur + [W], cb, cw + 1)
            return

        candidates = vals
        if i in eq_positions:
            candidates = (cur[i - 1],)
        elif i in neq_positions:
            candidates = (W if cur[i - 1] == B else B,) if i > 0 else vals

        for x in candidates:
            if i >= 2 and cur[i - 1] == cur[i - 2] == x:
                continue
            if x == B:
                rec(i + 1, cur + [x], cb + 1, cw)
            else:
                rec(i + 1, cur + [x], cb, cw + 1)

    rec(0, [], 0, 0)
    for p in patterns[:]:
        pass

    # The recursion above forgot to append completed patterns; keep structure human-like and explicit.
    patterns = []

    def rec2(i, cur, cb, cw):
        if cb > half or cw > half:
            return
        rem = length - i
        if cb + rem < half or cw + rem < half:
            return
        if i == length:
            if cb == cw == half:
                patterns.append(tuple(cur))
            return

        candidates = vals
        if i > 0:
            if i in eq_positions:
                candidates = (cur[i - 1],)
            elif i in neq_positions:
                candidates = (W if cur[i - 1] == B else B,)

        for x in candidates:
            if i >= 2 and cur[i - 1] == cur[i - 2] == x:
                continue
            if x == B:
                rec2(i + 1, cur + [x], cb + 1, cw)
            else:
                rec2(i + 1, cur + [x], cb, cw + 1)

    rec2(0, [], 0, 0)
    return patterns


def solve(observation):
    data = [row[:] for row in observation["data"]]
    H = len(data)
    Wd = len(data[0]) if H else 0

    if H % 2 or Wd % 2:
        return "No Solution"

    hcons = parse_constraints(observation.get("horizontal", {}))
    vcons = parse_constraints(observation.get("vertical", {}))

    row_eq = {r: set() for r in range(H)}
    row_neq = {r: set() for r in range(H)}
    for (r, c), typ in hcons.items():
        rr = int(r)
        cc = int(c + 0.5)
        if typ == "=":
            row_eq[rr].add(cc)
        else:
            row_neq[rr].add(cc)

    col_eq = {c: set() for c in range(Wd)}
    col_neq = {c: set() for c in range(Wd)}
    for (r, c), typ in vcons.items():
        rr = int(r + 0.5)
        cc = int(c)
        if typ == "=":
            col_eq[cc].add(rr)
        else:
            col_neq[cc].add(rr)

    all_row_patterns = [
        generate_line_patterns(Wd, row_eq[r], row_neq[r]) for r in range(H)
    ]
    all_col_patterns = [
        generate_line_patterns(H, col_eq[c], col_neq[c]) for c in range(Wd)
    ]

    row_poss = []
    for r in range(H):
        fixed = data[r]
        poss = []
        for p in all_row_patterns[r]:
            ok = True
            for c, v in enumerate(fixed):
                if v is not None and p[c] != v:
                    ok = False
                    break
            if ok:
                poss.append(p)
        if not poss:
            return "No Solution"
        row_poss.append(poss)

    col_poss = []
    for c in range(Wd):
        poss = []
        for p in all_col_patterns[c]:
            ok = True
            for r in range(H):
                v = data[r][c]
                if v is not None and p[r] != v:
                    ok = False
                    break
            if ok:
                poss.append(p)
        if not poss:
            return "No Solution"
        col_poss.append(poss)

    def allowed_from_patterns(patterns, idx):
        s = set()
        for p in patterns:
            s.add(p[idx])
            if len(s) == 2:
                break
        return s

    def propagate(rp, cp):
        changed = True
        while changed:
            changed = False

            cell_allowed = [[None] * Wd for _ in range(H)]
            for r in range(H):
                for c in range(Wd):
                    a = allowed_from_patterns(rp[r], c)
                    b = allowed_from_patterns(cp[c], r)
                    inter = a & b
                    if not inter:
                        return None
                    cell_allowed[r][c] = inter

            for r in range(H):
                new = [p for p in rp[r] if all(p[c] in cell_allowed[r][c] for c in range(Wd))]
                if not new:
                    return None
                if len(new) != len(rp[r]):
                    rp[r] = new
                    changed = True

            for c in range(Wd):
                new = [p for p in cp[c] if all(p[r] in cell_allowed[r][c] for r in range(H))]
                if not new:
                    return None
                if len(new) != len(cp[c]):
                    cp[c] = new
                    changed = True

        return rp, cp

    def build_grid(rp, cp):
        grid = [[None] * Wd for _ in range(H)]
        for r in range(H):
            if len(rp[r]) != 1:
                return None
            grid[r] = list(rp[r][0])
        for c in range(Wd):
            if len(cp[c]) != 1:
                return None
            col = cp[c][0]
            for r in range(H):
                if grid[r][c] != col[r]:
                    return None
        return grid

    def search(rp, cp):
        state = propagate([x[:] for x in rp], [x[:] for x in cp])
        if state is None:
            return None
        rp, cp = state

        grid = build_grid(rp, cp)
        if grid is not None:
            return grid

        best_kind = None
        best_idx = None
        best_len = 10**9

        for r in range(H):
            l = len(rp[r])
            if 1 < l < best_len:
                best_len = l
                best_kind = "row"
                best_idx = r
        for c in range(Wd):
            l = len(cp[c])
            if 1 < l < best_len:
                best_len = l
                best_kind = "col"
                best_idx = c

        if best_kind is None:
            return None

        if best_kind == "row":
            r = best_idx
            for p in rp[r]:
                nrp = [x[:] for x in rp]
                ncp = [x[:] for x in cp]
                nrp[r] = [p]
                res = search(nrp, ncp)
                if res is not None:
                    return res
        else:
            c = best_idx
            for p in cp[c]:
                nrp = [x[:] for x in rp]
                ncp = [x[:] for x in cp]
                ncp[c] = [p]
                res = search(nrp, ncp)
                if res is not None:
                    return res

        return None

    ans = search(row_poss, col_poss)
    return ans if ans is not None else "No Solution"


