def _bit(mask, i):
    return (mask >> i) & 1


def _generate_patterns(length, weights, target):
    patterns = []
    # DFS subset generation with pruning; mirrors human subset-sum reasoning.
    suffix = [0] * (length + 1)
    for i in range(length - 1, -1, -1):
        suffix[i] = suffix[i + 1] + weights[i]

    def dfs(i, current_sum, mask):
        if current_sum > target:
            return
        if current_sum + suffix[i] < target:
            return
        if i == length:
            if current_sum == target:
                patterns.append(mask)
            return
        # Exclude
        dfs(i + 1, current_sum, mask)
        # Include
        dfs(i + 1, current_sum + weights[i], mask | (1 << i))

    dfs(0, 0, 0)
    return patterns


def _domain_bit_status(domain, index):
    any0 = False
    any1 = False
    bit = 1 << index
    for m in domain:
        if m & bit:
            any1 = True
        else:
            any0 = True
        if any0 and any1:
            return 2  # both possible
    if any1:
        return 1
    return 0


def _filter_domain_by_cell(domain, index, allowed0, allowed1):
    bit = 1 << index
    new_domain = []
    changed = False
    for m in domain:
        v = 1 if (m & bit) else 0
        if (v == 0 and allowed0) or (v == 1 and allowed1):
            new_domain.append(m)
        else:
            changed = True
    return new_domain, changed


def _propagate(row_domains, col_domains, nrows, ncols):
    # Arc-consistency on every cell.
    q = deque()
    for r in range(nrows):
        q.append(("row", r))
    for c in range(ncols):
        q.append(("col", c))

    inq_row = [True] * nrows
    inq_col = [True] * ncols

    while q:
        typ, idx = q.popleft()
        if typ == "row":
            inq_row[idx] = False
            r = idx
            if not row_domains[r]:
                return False
            for c in range(ncols):
                rs = _domain_bit_status(row_domains[r], c)
                cs = _domain_bit_status(col_domains[c], r)

                allowed0 = (rs in (0, 2)) and (cs in (0, 2))
                allowed1 = (rs in (1, 2)) and (cs in (1, 2))
                if not allowed0 and not allowed1:
                    return False

                new_row, ch1 = _filter_domain_by_cell(row_domains[r], c, allowed0, allowed1)
                if not new_row:
                    return False
                if ch1:
                    row_domains[r] = new_row
                    if not inq_row[r]:
                        q.append(("row", r))
                        inq_row[r] = True
                    if not inq_col[c]:
                        q.append(("col", c))
                        inq_col[c] = True

                new_col, ch2 = _filter_domain_by_cell(col_domains[c], r, allowed0, allowed1)
                if not new_col:
                    return False
                if ch2:
                    col_domains[c] = new_col
                    if not inq_col[c]:
                        q.append(("col", c))
                        inq_col[c] = True
                    if not inq_row[r]:
                        q.append(("row", r))
                        inq_row[r] = True
        else:
            inq_col[idx] = False
            c = idx
            if not col_domains[c]:
                return False
            for r in range(nrows):
                rs = _domain_bit_status(row_domains[r], c)
                cs = _domain_bit_status(col_domains[c], r)

                allowed0 = (rs in (0, 2)) and (cs in (0, 2))
                allowed1 = (rs in (1, 2)) and (cs in (1, 2))
                if not allowed0 and not allowed1:
                    return False

                new_row, ch1 = _filter_domain_by_cell(row_domains[r], c, allowed0, allowed1)
                if not new_row:
                    return False
                if ch1:
                    row_domains[r] = new_row
                    if not inq_row[r]:
                        q.append(("row", r))
                        inq_row[r] = True
                    if not inq_col[c]:
                        q.append(("col", c))
                        inq_col[c] = True

                new_col, ch2 = _filter_domain_by_cell(col_domains[c], r, allowed0, allowed1)
                if not new_col:
                    return False
                if ch2:
                    col_domains[c] = new_col
                    if not inq_col[c]:
                        q.append(("col", c))
                        inq_col[c] = True
                    if not inq_row[r]:
                        q.append(("row", r))
                        inq_row[r] = True

    return True


def _is_solved(row_domains, col_domains):
    return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)


def _choose_branch(row_domains, col_domains):
    best = None

    for r, d in enumerate(row_domains):
        if 1 < len(d) and (best is None or len(d) < best[2]):
            best = ("row", r, len(d))
    for c, d in enumerate(col_domains):
        if 1 < len(d) and (best is None or len(d) < best[2]):
            best = ("col", c, len(d))
    return best


def _search(row_domains, col_domains, nrows, ncols):
    if not _propagate(row_domains, col_domains, nrows, ncols):
        return None
    if _is_solved(row_domains, col_domains):
        return row_domains, col_domains

    choice = _choose_branch(row_domains, col_domains)
    if choice is None:
        return row_domains, col_domains

    typ, idx, _ = choice
    domain = row_domains[idx] if typ == "row" else col_domains[idx]

    # Heuristic: try masks with more constrained-looking interaction first.
    ordered = sorted(domain, key=lambda m: bin(m).count("1"))

    for mask in ordered:
        new_row_domains = [d[:] for d in row_domains]
        new_col_domains = [d[:] for d in col_domains]
        if typ == "row":
            new_row_domains[idx] = [mask]
        else:
            new_col_domains[idx] = [mask]
        result = _search(new_row_domains, new_col_domains, nrows, ncols)
        if result is not None:
            return result
    return None


def solve(observation):
    row_sum = observation["row_sum"]
    col_sum = observation["col_sum"]
    nrows = len(row_sum)
    ncols = len(col_sum)

    # These puzzles use sequential row/column weights as displayed around the grid.
    row_weights = list(range(1, nrows + 1))
    col_weights = list(range(1, ncols + 1))

    # Fast global consistency check.
    if sum(row_sum) != sum(col_sum):
        return "No Solution"

    row_domains = []
    for target in row_sum:
        pats = _generate_patterns(ncols, col_weights, target)
        if not pats:
            return "No Solution"
        row_domains.append(pats)

    col_domains = []
    for target in col_sum:
        pats = _generate_patterns(nrows, row_weights, target)
        if not pats:
            return "No Solution"
        col_domains.append(pats)

    result = _search(row_domains, col_domains, nrows, ncols)
    if result is None:
        return "No Solution"

    solved_rows, solved_cols = result
    grid = []
    for r in range(nrows):
        mask = solved_rows[r][0]
        row = []
        for c in range(ncols):
            row.append('B' if _bit(mask, c) else None)
        grid.append(row)

    # Final safety verification.
    for r in range(nrows):
        if sum((c + 1) for c in range(ncols) if grid[r][c] == 'B') != row_sum[r]:
            return "No Solution"
    for c in range(ncols):
        if sum((r + 1) for r in range(nrows) if grid[r][c] == 'B') != col_sum[c]:
            return "No Solution"

    return repr(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

