from collections import defaultdict, deque

# Canonical tetromino families under rotation/reflection.
def _transforms(cells):
    pts = list(cells)
    out = []
    for rx, ry in (
        lambda x, y: (x, y),
        lambda x, y: (x, -y),
        lambda x, y: (-x, y),
        lambda x, y: (-x, -y),
        lambda x, y: (y, x),
        lambda x, y: (y, -x),
        lambda x, y: (-y, x),
        lambda x, y: (-y, -x),
    ):
        t = [(rx(x, y)[0], rx(x, y)[1]) for x, y in pts]
        minx = min(x for x, y in t)
        miny = min(y for x, y in t)
        t = tuple(sorted((x - minx, y - miny) for x, y in t))
        out.append(t)
    return set(out)

def _canon(cells):
    return min(_transforms(cells))

BASE_SHAPES = {
    'I': {(0, 0), (1, 0), (2, 0), (3, 0)},
    'L': {(0, 0), (1, 0), (2, 0), (2, 1)},
    'T': {(0, 0), (0, 1), (0, 2), (1, 1)},
    'S': {(0, 1), (0, 2), (1, 0), (1, 1)},
}
CANON_TO_TYPE = {}
for k, v in BASE_SHAPES.items():
    for t in _transforms(v):
        CANON_TO_TYPE[t] = k

def tet_type(cells):
    return CANON_TO_TYPE.get(_canon(cells))

def neighbors4(cell, n, m):
    r, c = cell
    if r > 0:
        yield (r - 1, c)
    if r + 1 < n:
        yield (r + 1, c)
    if c > 0:
        yield (r, c - 1)
    if c + 1 < m:
        yield (r, c + 1)

def connected(cells, n, m):
    if not cells:
        return True
    start = next(iter(cells))
    q = [start]
    seen = {start}
    while q:
        u = q.pop()
        for v in neighbors4(u, n, m):
            if v in cells and v not in seen:
                seen.add(v)
                q.append(v)
    return len(seen) == len(cells)

def enumerate_region_candidates(region_cells, n, m):
    region_set = set(region_cells)
    cells = sorted(region_cells)
    out = []
    seen = set()

    def expand(chosen, frontier):
        if len(chosen) == 4:
            s = frozenset(chosen)
            if s in seen:
                return
            seen.add(s)
            typ = tet_type({(r, c) for r, c in chosen})
            if typ is not None:
                out.append((s, typ))
            return
        # Human-like growth: connected 4-cell polyomino inside region only.
        for cell in sorted(frontier):
            new_chosen = set(chosen)
            new_chosen.add(cell)
            new_frontier = set(frontier)
            new_frontier.discard(cell)
            for nb in neighbors4(cell, n, m):
                if nb in region_set and nb not in new_chosen:
                    new_frontier.add(nb)
            expand(new_chosen, new_frontier)

    for start in cells:
        frontier = {nb for nb in neighbors4(start, n, m) if nb in region_set}
        expand({start}, frontier)
    return out

def all_2x2_blocks(n, m):
    for r in range(n - 1):
        for c in range(m - 1):
            yield ((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1))

def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n else 0

    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[grid[r][c]].append((r, c))
    region_ids = sorted(regions)

    # Region adjacency by orthogonal touching.
    region_adj = {rid: set() for rid in region_ids}
    for r in range(n):
        for c in range(m):
            a = grid[r][c]
            for nr, nc in neighbors4((r, c), n, m):
                b = grid[nr][nc]
                if a != b:
                    region_adj[a].add(b)

    # Enumerate legal tetromino placements in each region.
    domains = {}
    for rid in region_ids:
        cands = enumerate_region_candidates(regions[rid], n, m)
        if not cands:
            return "No Solution"
        domains[rid] = [{'cells': s, 'type': t} for s, t in cands]

    blocks2 = list(all_2x2_blocks(n, m))
    cell_to_regions = {}
    for rid, cells in regions.items():
        for cell in cells:
            cell_to_regions[cell] = rid

    # Precompute region/type support counts for fast propagation.
    def domain_types(dom):
        return {x['type'] for x in dom}

    def possible_shaded_from_domains(cur_domains):
        out = set()
        for rid in region_ids:
            for cand in cur_domains[rid]:
                out |= cand['cells']
        return out

    def assigned_cells(assign):
        out = set()
        for rid, cand in assign.items():
            out |= cand['cells']
        return out

    def consistent_2x2(assign_cells_set, cur_domains):
        # Immediate contradiction on assigned cells.
        for b in blocks2:
            if all(x in assign_cells_set for x in b):
                return False
        # Feasibility: for any block, not all four can be forced shaded.
        possible = possible_shaded_from_domains(cur_domains)
        for b in blocks2:
            if all(x in possible for x in b):
                # If every cell belongs to an assigned-shaded or every still-possible region choice forces it later.
                forced = True
                for x in b:
                    rid = cell_to_regions[x]
                    if x not in assign_cells_set:
                        if any(x not in cand['cells'] for cand in cur_domains[rid]):
                            forced = False
                            break
                if forced:
                    return False
        return True

    def connectivity_feasible(assign, cur_domains):
        fixed = assigned_cells(assign)
        if not fixed:
            return True
        possible = possible_shaded_from_domains(cur_domains)
        # All fixed shaded cells must lie in one component of the possible graph.
        start = next(iter(fixed))
        q = deque([start])
        seen = {start}
        while q:
            u = q.popleft()
            for v in neighbors4(u, n, m):
                if v in possible and v not in seen:
                    seen.add(v)
                    q.append(v)
        return fixed <= seen

    def filter_domains(assign, cur_domains):
        changed = True
        while changed:
            changed = False

            # Remove candidates conflicting with assigned neighbor types, assigned cells, 2x2.
            fixed_cells = assigned_cells(assign)
            for rid in region_ids:
                old = cur_domains[rid]
                new = []
                forbidden_types = {assign[nb]['type'] for nb in region_adj[rid] if nb in assign}
                for cand in old:
                    if rid in assign and cand is not assign[rid]:
                        continue
                    if cand['type'] in forbidden_types:
                        continue

                    # 2x2 check against already assigned cells.
                    bad = False
                    cs = cand['cells']
                    for b in blocks2:
                        cnt = 0
                        for x in b:
                            if x in cs:
                                cnt += 1
                            elif x in fixed_cells and cell_to_regions[x] != rid:
                                cnt += 1
                        if cnt == 4:
                            bad = True
                            break
                    if bad:
                        continue
                    new.append(cand)

                if not new:
                    return None, None
                if len(new) != len(old):
                    cur_domains[rid] = new
                    changed = True

            # Neighboring regions cannot share a tetromino type.
            type_sets = {rid: domain_types(cur_domains[rid]) for rid in region_ids}
            for rid in region_ids:
                if len(cur_domains[rid]) == 1 and rid not in assign:
                    assign[rid] = cur_domains[rid][0]
                    changed = True

            # Type-only propagation.
            for rid in region_ids:
                for nb in region_adj[rid]:
                    if rid < nb and len(type_sets[rid]) == 1 and len(type_sets[nb]) > 0:
                        t = next(iter(type_sets[rid]))
                        filtered = [c for c in cur_domains[nb] if c['type'] != t]
                        if not filtered:
                            return None, None
                        if len(filtered) != len(cur_domains[nb]):
                            cur_domains[nb] = filtered
                            changed = True
                    if rid < nb and len(type_sets[nb]) == 1 and len(type_sets[rid]) > 0:
                        t = next(iter(type_sets[nb]))
                        filtered = [c for c in cur_domains[rid] if c['type'] != t]
                        if not filtered:
                            return None, None
                        if len(filtered) != len(cur_domains[rid]):
                            cur_domains[rid] = filtered
                            changed = True

            if not consistent_2x2(assigned_cells(assign), cur_domains):
                return None, None
            if not connectivity_feasible(assign, cur_domains):
                return None, None

        return assign, cur_domains

    def choose_region(cur_domains, assign):
        # Human-like: pick most constrained region, tie-break by type diversity then adjacency pressure.
        best = None
        key = None
        for rid in region_ids:
            if rid in assign and len(cur_domains[rid]) == 1:
                continue
            k = (
                len(cur_domains[rid]),
                len(domain_types(cur_domains[rid])),
                -len(region_adj[rid]),
                -len(regions[rid]),
            )
            if key is None or k < key:
                key = k
                best = rid
        return best

    def search(assign, cur_domains):
        assign = dict(assign)
        cur_domains = {rid: list(v) for rid, v in cur_domains.items()}
        res = filter_domains(assign, cur_domains)
        if res == (None, None):
            return None
        assign, cur_domains = res

        if all(len(cur_domains[rid]) == 1 for rid in region_ids):
            final_assign = {rid: cur_domains[rid][0] for rid in region_ids}
            shaded = assigned_cells(final_assign)
            if not connected(shaded, n, m):
                return None
            for b in blocks2:
                if all(x in shaded for x in b):
                    return None
            # Build answer grid.
            ans = [[None for _ in range(m)] for _ in range(n)]
            for rid, cand in final_assign.items():
                t = cand['type']
                for r, c in cand['cells']:
                    ans[r][c] = t
            return ans

        rid = choose_region(cur_domains, assign)
        if rid is None:
            return None

        # Value ordering: prefer candidates that touch current shaded network and restrict neighbors.
        fixed = assigned_cells(assign)
        def score(c):
            touch = 0
            for cell in c['cells']:
                for nb in neighbors4(cell, n, m):
                    if nb in fixed:
                        touch = 1
                        break
                if touch:
                    break
            return (
                -touch,
                sum(1 for nb in region_adj[rid] for cc in cur_domains[nb] if cc['type'] == c['type']),
                0,
            )

        for cand in sorted(cur_domains[rid], key=score):
            new_assign = dict(assign)
            new_assign[rid] = cand
            new_domains = {k: list(v) for k, v in cur_domains.items()}
            new_domains[rid] = [cand]
            ans = search(new_assign, new_domains)
            if ans is not None:
                return ans
        return None

    ans = search({}, domains)
    if ans is None:
        return "No Solution"
    return repr(ans)

