from collections import deque, defaultdict

BLACK = 1
WHITE = 0
UNKNOWN = -1


def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])

    regions = defaultdict(list)
    clue_of_region = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            regions[rid].append((r, c))
            if data[r][c] is not None:
                clue_of_region[rid] = data[r][c]

    neighbors = {}
    for r in range(n):
        for c in range(m):
            adj = []
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    adj.append((rr, cc))
            neighbors[(r, c)] = adj

    row_regions = [[region[r][c] for c in range(m)] for r in range(n)]
    col_regions = [[region[r][c] for r in range(n)] for c in range(m)]

    def copy_state(state):
        return [row[:] for row in state]

    def line_feasible(cells, regs):
        # DP state:
        # last_black: 1 if previous chosen cell is black else 0
        # seg_count: number of region blocks in current white segment (0 if previous is black or start)
        # last_reg: last region id in current white segment, -1 when seg_count == 0
        cur = {(0, 0, -1)}
        for v, rg in zip(cells, regs):
            nxt = set()
            for last_black, seg_count, last_reg in cur:
                if v != WHITE:
                    if not last_black:
                        nxt.add((1, 0, -1))
                if v != BLACK:
                    if last_black or seg_count == 0:
                        nxt.add((0, 1, rg))
                    else:
                        new_count = seg_count + (0 if rg == last_reg else 1)
                        if new_count <= 2:
                            nxt.add((0, new_count, rg))
            if not nxt:
                return False
            cur = nxt
        return True

    def all_lines_feasible(state):
        for r in range(n):
            if not line_feasible(state[r], row_regions[r]):
                return False
        for c in range(m):
            col = [state[r][c] for r in range(n)]
            if not line_feasible(col, col_regions[c]):
                return False
        return True

    def white_connectivity_possible(state):
        # All fixed whites must lie in one component of cells that are not fixed black.
        nonblack = [(r, c) for r in range(n) for c in range(m) if state[r][c] != BLACK]
        if not nonblack:
            return False
        whites = [(r, c) for r in range(n) for c in range(m) if state[r][c] == WHITE]
        start = whites[0] if whites else nonblack[0]

        seen = {start}
        dq = deque([start])
        while dq:
            cell = dq.popleft()
            for nb in neighbors[cell]:
                rr, cc = nb
                if state[rr][cc] != BLACK and nb not in seen:
                    seen.add(nb)
                    dq.append(nb)

        for w in whites:
            if w not in seen:
                return False

        # Also every not-black cell must still be connectable to the main white area in principle.
        # If there are multiple non-black components already, impossible because unknowns cannot bridge through black.
        return len(seen) == len(nonblack)

    def region_bounds_ok(state):
        for rid, cells in regions.items():
            if rid in clue_of_region:
                target = clue_of_region[rid]
                b = 0
                u = 0
                for r, c in cells:
                    if state[r][c] == BLACK:
                        b += 1
                    elif state[r][c] == UNKNOWN:
                        u += 1
                if b > target or b + u < target:
                    return False
        return True

    def no_black_adjacency_ok(state):
        for r in range(n):
            for c in range(m):
                if state[r][c] == BLACK:
                    for rr, cc in neighbors[(r, c)]:
                        if state[rr][cc] == BLACK:
                            return False
        return True

    def valid_partial(state):
        return (
            region_bounds_ok(state)
            and no_black_adjacency_ok(state)
            and all_lines_feasible(state)
            and white_connectivity_possible(state)
        )

    def assign(state, r, c, val):
        cur = state[r][c]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        state[r][c] = val
        return True

    def propagate_basic(state):
        changed = True
        while changed:
            changed = False

            # Rule 1: black cells force orthogonal neighbors white.
            for r in range(n):
                for c in range(m):
                    if state[r][c] == BLACK:
                        for rr, cc in neighbors[(r, c)]:
                            if state[rr][cc] == BLACK:
                                return None
                            if state[rr][cc] == UNKNOWN:
                                state[rr][cc] = WHITE
                                changed = True

            # Rule 2: numbered region exact-count propagation.
            for rid, cells in regions.items():
                if rid not in clue_of_region:
                    continue
                target = clue_of_region[rid]
                blacks = []
                unknowns = []
                for r, c in cells:
                    if state[r][c] == BLACK:
                        blacks.append((r, c))
                    elif state[r][c] == UNKNOWN:
                        unknowns.append((r, c))
                b = len(blacks)
                u = len(unknowns)
                if b > target or b + u < target:
                    return None
                if b == target:
                    for r, c in unknowns:
                        state[r][c] = WHITE
                        changed = True
                elif b + u == target:
                    for r, c in unknowns:
                        state[r][c] = BLACK
                        changed = True

            # Fast contradiction checks after deterministic steps.
            if not valid_partial(state):
                return None

        return state

    def propagate(state):
        state = propagate_basic(state)
        if state is None:
            return None

        # Trial-based logical forcing:
        # if one color immediately leads to contradiction under propagation, force the other.
        progress = True
        while progress:
            progress = False
            unknown_cells = [(r, c) for r in range(n) for c in range(m) if state[r][c] == UNKNOWN]
            for r, c in unknown_cells:
                results = {}
                for val in (BLACK, WHITE):
                    trial = copy_state(state)
                    trial[r][c] = val
                    trial = propagate_basic(trial)
                    results[val] = trial is not None

                if not results[BLACK] and not results[WHITE]:
                    return None
                if results[BLACK] and not results[WHITE]:
                    state[r][c] = BLACK
                    state = propagate_basic(state)
                    if state is None:
                        return None
                    progress = True
                    break
                if results[WHITE] and not results[BLACK]:
                    state[r][c] = WHITE
                    state = propagate_basic(state)
                    if state is None:
                        return None
                    progress = True
                    break

            if progress:
                continue

            # Region-focused subset forcing:
            # In numbered regions, if exactly k blacks remain to place, try candidate cells.
            for rid, cells in regions.items():
                if rid not in clue_of_region:
                    continue
                target = clue_of_region[rid]
                blacks = sum(1 for r, c in cells if state[r][c] == BLACK)
                unknowns = [(r, c) for r, c in cells if state[r][c] == UNKNOWN]
                need = target - blacks
                if 0 < need < len(unknowns):
                    # If a cell cannot be black, force white; if enough such eliminations happen, basic propagation handles it.
                    for r, c in unknowns:
                        trial = copy_state(state)
                        trial[r][c] = BLACK
                        if propagate_basic(trial) is None:
                            state[r][c] = WHITE
                            state = propagate_basic(state)
                            if state is None:
                                return None
                            progress = True
                            break
                    if progress:
                        break

        return state

    def is_complete(state):
        for r in range(n):
            for c in range(m):
                if state[r][c] == UNKNOWN:
                    return False
        return True

    def valid_final(state):
        if not valid_partial(state):
            return False
        # All numbered region counts exact.
        for rid, target in clue_of_region.items():
            cnt = sum(1 for r, c in regions[rid] if state[r][c] == BLACK)
            if cnt != target:
                return False
        return True

    def choose_branch_cell(state):
        # Heuristic: prefer cells in numbered regions closest to deciding the region,
        # then cells most constrained by black adjacency.
        best = None
        best_key = None
        for r in range(n):
            for c in range(m):
                if state[r][c] != UNKNOWN:
                    continue
                rid = region[r][c]
                if rid in clue_of_region:
                    target = clue_of_region[rid]
                    cells = regions[rid]
                    b = sum(1 for rr, cc in cells if state[rr][cc] == BLACK)
                    u = sum(1 for rr, cc in cells if state[rr][cc] == UNKNOWN)
                    need = target - b
                    region_score = min(abs(need), abs(u - need))
                else:
                    region_score = 10**6
                black_nb = sum(1 for rr, cc in neighbors[(r, c)] if state[rr][cc] == BLACK)
                unk_nb = sum(1 for rr, cc in neighbors[(r, c)] if state[rr][cc] == UNKNOWN)
                key = (region_score, -black_nb, -unk_nb)
                if best_key is None or key < best_key:
                    best_key = key
                    best = (r, c)
        return best

    def branch_order(state, r, c):
        rid = region[r][c]
        # Prefer black first if region still needs many blacks and local adjacency allows.
        if rid in clue_of_region:
            target = clue_of_region[rid]
            cells = regions[rid]
            b = sum(1 for rr, cc in cells if state[rr][cc] == BLACK)
            u = sum(1 for rr, cc in cells if state[rr][cc] == UNKNOWN)
            need = target - b
            if need > 0 and need >= u / 2:
                return (BLACK, WHITE)
        return (WHITE, BLACK)

    def dfs(state):
        state = propagate(state)
        if state is None:
            return None
        if is_complete(state):
            return state if valid_final(state) else None

        r, c = choose_branch_cell(state)
        for val in branch_order(state, r, c):
            trial = copy_state(state)
            if not assign(trial, r, c, val):
                continue
            ans = dfs(trial)
            if ans is not None:
                return ans
        return None

    initial = [[UNKNOWN] * m for _ in range(n)]
    solution = dfs(initial)
    if solution is None:
        return "No Solution"
    return [['B' if solution[r][c] == BLACK else None for c in range(m)] for r in range(n)]


