from copy import deepcopy

def parse_unit(unit):
    if 'x' in unit:
        a, b = unit.split('x')
        return int(a), int(b)
    k = int(unit)
    return k, k

def bit_count(x):
    return x.bit_count()

def lowbit_index(mask):
    return (mask & -mask).bit_length() - 1

def iter_bits(mask):
    while mask:
        b = mask & -mask
        yield b
        mask ^= b

def mask_to_values(mask, n):
    out = []
    while mask:
        b = mask & -mask
        out.append(b.bit_length())
        mask ^= b
    return out

class SudokuSolver:
    def __init__(self, grid, box_r, box_c):
        self.grid = [row[:] for row in grid]
        self.box_r = box_r
        self.box_c = box_c
        self.n = len(grid)
        self.full = (1 << self.n) - 1

        self.rows = [0] * self.n
        self.cols = [0] * self.n
        self.boxes = [0] * self.n
        self.cands = [[0] * self.n for _ in range(self.n)]

        self.units = []
        self.cell_units = [[[] for _ in range(self.n)] for _ in range(self.n)]
        self.peers = [[None] * self.n for _ in range(self.n)]

        self._build_units()
        if not self._init_masks():
            self.valid = False
            return
        self.valid = True
        if not self._init_candidates():
            self.valid = False

    def _box_index(self, r, c):
        return (r // self.box_r) * (self.n // self.box_c) + (c // self.box_c)

    def _build_units(self):
        n = self.n
        # rows
        for r in range(n):
            unit = [(r, c) for c in range(n)]
            idx = len(self.units)
            self.units.append(unit)
            for rr, cc in unit:
                self.cell_units[rr][cc].append(idx)
        # cols
        for c in range(n):
            unit = [(r, c) for r in range(n)]
            idx = len(self.units)
            self.units.append(unit)
            for rr, cc in unit:
                self.cell_units[rr][cc].append(idx)
        # boxes
        for br in range(0, n, self.box_r):
            for bc in range(0, n, self.box_c):
                unit = []
                for r in range(br, br + self.box_r):
                    for c in range(bc, bc + self.box_c):
                        unit.append((r, c))
                idx = len(self.units)
                self.units.append(unit)
                for rr, cc in unit:
                    self.cell_units[rr][cc].append(idx)

        for r in range(n):
            for c in range(n):
                s = set()
                for ui in self.cell_units[r][c]:
                    s.update(self.units[ui])
                s.discard((r, c))
                self.peers[r][c] = tuple(s)

    def _init_masks(self):
        for r in range(self.n):
            for c in range(self.n):
                v = self.grid[r][c]
                if v is None:
                    continue
                bit = 1 << (v - 1)
                b = self._box_index(r, c)
                if (self.rows[r] & bit) or (self.cols[c] & bit) or (self.boxes[b] & bit):
                    return False
                self.rows[r] |= bit
                self.cols[c] |= bit
                self.boxes[b] |= bit
        return True

    def _init_candidates(self):
        for r in range(self.n):
            for c in range(self.n):
                if self.grid[r][c] is None:
                    mask = self.full & ~(self.rows[r] | self.cols[c] | self.boxes[self._box_index(r, c)])
                    if mask == 0:
                        return False
                    self.cands[r][c] = mask
                else:
                    self.cands[r][c] = 1 << (self.grid[r][c] - 1)
        return True

    def clone(self):
        other = object.__new__(SudokuSolver)
        other.grid = [row[:] for row in self.grid]
        other.box_r = self.box_r
        other.box_c = self.box_c
        other.n = self.n
        other.full = self.full
        other.rows = self.rows[:]
        other.cols = self.cols[:]
        other.boxes = self.boxes[:]
        other.cands = [row[:] for row in self.cands]
        other.units = self.units
        other.cell_units = self.cell_units
        other.peers = self.peers
        other.valid = self.valid
        return other

    def solved(self):
        for r in range(self.n):
            for c in range(self.n):
                if self.grid[r][c] is None:
                    return False
        return True

    def assign(self, r, c, bit):
        v = bit.bit_length()
        cur = self.grid[r][c]
        if cur is not None:
            return cur == v
        if not (self.cands[r][c] & bit):
            return False

        self.grid[r][c] = v
        self.cands[r][c] = bit
        self.rows[r] |= bit
        self.cols[c] |= bit
        b = self._box_index(r, c)
        self.boxes[b] |= bit

        for rr, cc in self.peers[r][c]:
            if self.grid[rr][cc] is None and (self.cands[rr][cc] & bit):
                self.cands[rr][cc] &= ~bit
                if self.cands[rr][cc] == 0:
                    return False
        return True

    def find_hidden_singles(self):
        actions = []
        for unit in self.units:
            pos = [None] * self.n
            cnt = [0] * self.n
            for r, c in unit:
                if self.grid[r][c] is None:
                    mask = self.cands[r][c]
                    for bit in iter_bits(mask):
                        d = bit.bit_length() - 1
                        cnt[d] += 1
                        pos[d] = (r, c, bit)
            for d in range(self.n):
                if cnt[d] == 1:
                    actions.append(pos[d])
        return actions

    def apply_naked_subsets_unit(self, unit, subset_size):
        # Human-like naked pairs/triples/quads:
        # if k cells in a unit share only k candidates among them, remove from others.
        changed = False
        freq = {}
        cells = []
        for r, c in unit:
            if self.grid[r][c] is None:
                mask = self.cands[r][c]
                bc = bit_count(mask)
                if 2 <= bc <= subset_size:
                    freq.setdefault(mask, []).append((r, c))
                    cells.append((r, c, mask))
        for mask, poss in list(freq.items()):
            if bit_count(mask) == subset_size and len(poss) == subset_size:
                for r, c in unit:
                    if self.grid[r][c] is None and (r, c) not in [(x, y) for x, y in poss]:
                        newmask = self.cands[r][c] & ~mask
                        if newmask != self.cands[r][c]:
                            if newmask == 0:
                                return False, True
                            self.cands[r][c] = newmask
                            changed = True

        # generalized combination by union, still bounded and small for efficiency
        candidates = [(r, c, m) for r, c, m in cells if bit_count(m) <= subset_size]
        L = len(candidates)
        if L >= subset_size + 1 and subset_size >= 2:
            import itertools
            for comb in itertools.combinations(candidates, subset_size):
                union = 0
                coords = []
                for r, c, m in comb:
                    union |= m
                    coords.append((r, c))
                if bit_count(union) == subset_size:
                    coord_set = set(coords)
                    for r, c in unit:
                        if self.grid[r][c] is None and (r, c) not in coord_set:
                            newmask = self.cands[r][c] & ~union
                            if newmask != self.cands[r][c]:
                                if newmask == 0:
                                    return False, True
                                self.cands[r][c] = newmask
                                changed = True
        return True, changed

    def apply_locked_candidates(self):
        # Box-line interaction:
        # if all candidates for a digit in a box lie on one row/col, eliminate from that row/col outside the box.
        changed = False
        n_box_cols = self.n // self.box_c
        for bidx in range(self.n):
            br = (bidx // n_box_cols) * self.box_r
            bc = (bidx % n_box_cols) * self.box_c
            cells = [(r, c) for r in range(br, br + self.box_r) for c in range(bc, bc + self.box_c) if self.grid[r][c] is None]
            if not cells:
                continue
            for d in range(self.n):
                bit = 1 << d
                pos = [(r, c) for r, c in cells if self.cands[r][c] & bit]
                if len(pos) <= 1:
                    continue
                rows = {r for r, _ in pos}
                cols = {c for _, c in pos}
                if len(rows) == 1:
                    row = next(iter(rows))
                    for c in range(self.n):
                        if not (bc <= c < bc + self.box_c) and self.grid[row][c] is None and (self.cands[row][c] & bit):
                            self.cands[row][c] &= ~bit
                            if self.cands[row][c] == 0:
                                return False, True
                            changed = True
                if len(cols) == 1:
                    col = next(iter(cols))
                    for r in range(self.n):
                        if not (br <= r < br + self.box_r) and self.grid[r][col] is None and (self.cands[r][col] & bit):
                            self.cands[r][col] &= ~bit
                            if self.cands[r][col] == 0:
                                return False, True
                            changed = True
        return True, changed

    def propagate(self):
        # Repeated human-like deductions:
        # 1) naked singles
        # 2) hidden singles
        # 3) locked candidates
        # 4) naked pairs/triples
        while True:
            progress = False

            # Naked singles
            singles = []
            for r in range(self.n):
                for c in range(self.n):
                    if self.grid[r][c] is None:
                        mask = self.cands[r][c]
                        if bit_count(mask) == 1:
                            singles.append((r, c, mask))
            if singles:
                for r, c, bit in singles:
                    if self.grid[r][c] is None:
                        if not self.assign(r, c, bit):
                            return False
                        progress = True
                if progress:
                    continue

            # Hidden singles
            hs = self.find_hidden_singles()
            if hs:
                for r, c, bit in hs:
                    if self.grid[r][c] is None:
                        if not self.assign(r, c, bit):
                            return False
                        progress = True
                if progress:
                    continue

            # Locked candidates
            ok, ch = self.apply_locked_candidates()
            if not ok:
                return False
            if ch:
                progress = True
                continue

            # Naked pairs/triples
            for subset_size in (2, 3):
                any_change = False
                for unit in self.units:
                    ok, ch = self.apply_naked_subsets_unit(unit, subset_size)
                    if not ok:
                        return False
                    if ch:
                        any_change = True
                if any_change:
                    progress = True
                    break
            if progress:
                continue

            # Sanity: any unit missing a place for a digit => contradiction
            for unit in self.units:
                placed = 0
                for r, c in unit:
                    if self.grid[r][c] is not None:
                        placed |= 1 << (self.grid[r][c] - 1)
                missing = self.full & ~placed
                for bit in iter_bits(missing):
                    found = False
                    for r, c in unit:
                        if self.grid[r][c] is None and (self.cands[r][c] & bit):
                            found = True
                            break
                    if not found:
                        return False

            return True

    def choose_branch_cell(self):
        # Minimum remaining values, tie-break by peer pressure.
        best = None
        best_key = None
        for r in range(self.n):
            for c in range(self.n):
                if self.grid[r][c] is None:
                    mask = self.cands[r][c]
                    cnt = bit_count(mask)
                    if cnt <= 1:
                        continue
                    impact = 0
                    for rr, cc in self.peers[r][c]:
                        if self.grid[rr][cc] is None:
                            impact += bit_count(self.cands[rr][cc])
                    key = (cnt, -impact)
                    if best_key is None or key < best_key:
                        best_key = key
                        best = (r, c)
        return best

    def search(self):
        if not self.propagate():
            return None
        if self.solved():
            return [row[:] for row in self.grid]

        cell = self.choose_branch_cell()
        if cell is None:
            return [row[:] for row in self.grid] if self.solved() else None

        r, c = cell
        mask = self.cands[r][c]

        # Least-constraining value order.
        options = []
        for bit in iter_bits(mask):
            score = 0
            for rr, cc in self.peers[r][c]:
                if self.grid[rr][cc] is None and (self.cands[rr][cc] & bit):
                    score += 1
            options.append((score, bit))
        options.sort()

        for _, bit in options:
            nxt = self.clone()
            if nxt.assign(r, c, bit):
                ans = nxt.search()
                if ans is not None:
                    return ans
        return None

def solve(observation):
    grid = observation['data']
    box_r, box_c = parse_unit(observation['unit'])
    n = len(grid)
    if n == 0 or any(len(row) != n for row in grid):
        return "No Solution"
    if box_r * box_c != n:
        return "No Solution"

    solver = SudokuSolver(grid, box_r, box_c)
    if not solver.valid:
        return "No Solution"
    ans = solver.search()
    return str(ans) if ans is not None else "No Solution"

