from collections import defaultdict, deque
from functools import lru_cache

BLACK = 1
WHITE = 0
UNKNOWN = -1

def solve(observation):
    region = observation['region']
    data = observation['data']
    n = len(region)
    m = len(region[0])

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx_of = {(r, c): r * m + c for r, c in cells}
    rc_of = {idx_of[(r, c)]: (r, c) for r, c in cells}

    neighbors = [[] for _ in range(n * m)]
    for r, c in cells:
        i = idx_of[(r, c)]
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                neighbors[i].append(idx_of[(rr, cc)])

    region_cells = defaultdict(list)
    for r, c in cells:
        region_cells[region[r][c]].append(idx_of[(r, c)])

    region_clue = {}
    for rid, lst in region_cells.items():
        clue = None
        for i in lst:
            r, c = rc_of[i]
            if data[r][c] is not None:
                if clue is not None and clue != data[r][c]:
                    return "No Solution"
                clue = data[r][c]
        if clue is None:
            return "No Solution"
        region_clue[rid] = clue

    rows = [[idx_of[(r, c)] for c in range(m)] for r in range(n)]
    cols = [[idx_of[(r, c)] for r in range(n)] for c in range(m)]

    line_regions = {}
    for line in rows + cols:
        line_regions[tuple(line)] = [region[rc_of[i][0]][rc_of[i][1]] for i in line]

    region_of_idx = [0] * (n * m)
    for i in range(n * m):
        r, c = rc_of[i]
        region_of_idx[i] = region[r][c]

    def initial_state():
        st = [UNKNOWN] * (n * m)
        return st

    def black_counts(state):
        b = defaultdict(int)
        u = defaultdict(int)
        for i, v in enumerate(state):
            rid = region_of_idx[i]
            if v == BLACK:
                b[rid] += 1
            elif v == UNKNOWN:
                u[rid] += 1
        return b, u

    def white_connectivity_possible(state):
        nonblack = [i for i, v in enumerate(state) if v != BLACK]
        whites = [i for i, v in enumerate(state) if v == WHITE]
        if not whites:
            return True
        allowed = set(nonblack)
        start = whites[0]
        q = deque([start])
        seen = {start}
        while q:
            x = q.popleft()
            for y in neighbors[x]:
                if y in allowed and y not in seen:
                    seen.add(y)
                    q.append(y)
        return all(w in seen for w in whites)

    def white_connected_final(state):
        whites = [i for i, v in enumerate(state) if v == WHITE]
        if not whites:
            return True
        allowed = set(whites)
        start = whites[0]
        q = deque([start])
        seen = {start}
        while q:
            x = q.popleft()
            for y in neighbors[x]:
                if y in allowed and y not in seen:
                    seen.add(y)
                    q.append(y)
        return len(seen) == len(whites)

    def can_black_now(state, i, bcount=None):
        if state[i] == WHITE:
            return False
        for nb in neighbors[i]:
            if state[nb] == BLACK:
                return False
        rid = region_of_idx[i]
        if bcount is None:
            bcount, _ = black_counts(state)
        if bcount[rid] >= region_clue[rid]:
            return False
        return True

    def line_choices(state, line):
        regs = line_regions[tuple(line)]
        allowed = []
        bcount, _ = black_counts(state)
        for i in line:
            opts = []
            if state[i] == BLACK:
                opts = [BLACK]
            elif state[i] == WHITE:
                opts = [WHITE]
            else:
                opts = [WHITE]
                if can_black_now(state, i, bcount):
                    opts.append(BLACK)
            if not opts:
                return None
            allowed.append(tuple(opts))

        feasible_at = [set() for _ in line]

        @lru_cache(None)
        def dfs(pos, seg_count, last_reg):
            if pos == len(line):
                return True
            ok = False
            rid = regs[pos]
            for color in allowed[pos]:
                if color == BLACK:
                    if dfs(pos + 1, 0, -1):
                        feasible_at[pos].add(BLACK)
                        ok = True
                else:
                    if seg_count == 0:
                        ncount, nlast = 1, rid
                    else:
                        ncount = seg_count + (1 if rid != last_reg else 0)
                        nlast = rid
                    if ncount <= 2 and dfs(pos + 1, ncount, nlast):
                        feasible_at[pos].add(WHITE)
                        ok = True
            return ok

        if not dfs(0, 0, -1):
            return None
        return feasible_at

    def assign(state, i, val):
        cur = state[i]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        state[i] = val
        return True

    def propagate(state):
        while True:
            changed = False
            bcount, ucount = black_counts(state)

            # Region arithmetic.
            for rid, lst in region_cells.items():
                need = region_clue[rid]
                b = bcount[rid]
                u = ucount[rid]
                if b > need or b + u < need:
                    return None
                if need == b:
                    for i in lst:
                        if state[i] == UNKNOWN:
                            state[i] = WHITE
                            changed = True
                elif b + u == need:
                    for i in lst:
                        if state[i] == UNKNOWN:
                            if not can_black_now(state, i, bcount):
                                return None
                            state[i] = BLACK
                            changed = True

            # Black adjacency.
            for i, v in enumerate(state):
                if v == BLACK:
                    for nb in neighbors[i]:
                        if state[nb] == BLACK:
                            return None
                        if state[nb] == UNKNOWN:
                            state[nb] = WHITE
                            changed = True

            # Region candidate pruning from adjacency/max.
            bcount, ucount = black_counts(state)
            for rid, lst in region_cells.items():
                need = region_clue[rid] - bcount[rid]
                cand = []
                for i in lst:
                    if state[i] == UNKNOWN:
                        if can_black_now(state, i, bcount):
                            cand.append(i)
                        else:
                            state[i] = WHITE
                            changed = True
                if need < 0 or need > len(cand):
                    return None
                if need == 0:
                    for i in cand:
                        if state[i] == UNKNOWN:
                            state[i] = WHITE
                            changed = True
                elif need == len(cand):
                    for i in cand:
                        if state[i] == UNKNOWN:
                            state[i] = BLACK
                            changed = True

            # Heyawake line rule by line DP.
            for line in rows + cols:
                choices = line_choices(state, line)
                if choices is None:
                    return None
                for pos, i in enumerate(line):
                    if state[i] == UNKNOWN:
                        if BLACK not in choices[pos] and WHITE not in choices[pos]:
                            return None
                        if BLACK not in choices[pos]:
                            state[i] = WHITE
                            changed = True
                        elif WHITE not in choices[pos]:
                            state[i] = BLACK
                            changed = True

            # Connectivity necessary condition.
            if not white_connectivity_possible(state):
                return None

            # Final exact checks.
            if all(v != UNKNOWN for v in state):
                bcount, _ = black_counts(state)
                for rid in region_cells:
                    if bcount[rid] != region_clue[rid]:
                        return None
                if not white_connected_final(state):
                    return None
                # Recheck line rule with fixed state.
                for line in rows + cols:
                    if line_choices(state, line) is None:
                        return None

            if not changed:
                return state

    def heuristic_cell(state):
        bcount, _ = black_counts(state)
        best = None
        best_score = None
        row_choice_cache = {}
        col_choice_cache = {}

        for i, v in enumerate(state):
            if v != UNKNOWN:
                continue
            r, c = rc_of[i]
            row = tuple(rows[r])
            col = tuple(cols[c])
            if row not in row_choice_cache:
                row_choice_cache[row] = line_choices(state, list(row))
            if col not in col_choice_cache:
                col_choice_cache[col] = line_choices(state, list(col))
            rch = row_choice_cache[row]
            cch = col_choice_cache[col]
            if rch is None or cch is None:
                return i, [BLACK, WHITE]
            rp = rch[c]
            cp = cch[r]
            opts = []
            if BLACK in rp and BLACK in cp and can_black_now(state, i, bcount):
                opts.append(BLACK)
            if WHITE in rp and WHITE in cp:
                opts.append(WHITE)
            if not opts:
                return i, []
            score = len(opts)

            rid = region_of_idx[i]
            need = region_clue[rid] - bcount[rid]
            unknowns_in_region = sum(1 for j in region_cells[rid] if state[j] == UNKNOWN)
            tie = abs((need / max(unknowns_in_region, 1)) - 0.5)
            key = (score, -tie, len(neighbors[i]))
            if best is None or key < best_score:
                best = (i, opts)
                best_score = key
                if score == 1:
                    break
        return best

    def search(state):
        state = propagate(state)
        if state is None:
            return None
        if all(v != UNKNOWN for v in state):
            return state

        choice = heuristic_cell(state)
        if choice is None:
            return None
        i, opts = choice
        if not opts:
            return None

        # Prefer black first when more constrained by region count.
        opts = sorted(opts, reverse=True)
        for val in opts:
            nxt = state[:]
            if not assign(nxt, i, val):
                continue
            res = search(nxt)
            if res is not None:
                return res
        return None

    sol = search(initial_state())
    if sol is None:
        return "No Solution"

    out = []
    for r in range(n):
        row_out = []
        for c in range(m):
            v = sol[idx_of[(r, c)]]
            row_out.append('B' if v == BLACK else None)
        out.append(row_out)
    return out

if __name__ == "__main__":
    print(solve(OBSERVATION))

