# Slitherlink solver:
# - aggressive local propagation from clue sums and vertex parity/degree
# - subloop pruning
# - heuristic branching on the most constrained edge
# - returns ordered loop dot coordinates or "No Solution"

from collections import defaultdict, deque

UNKNOWN = -1
OFF = 0
ON = 1


class Slitherlink:
    def __init__(self, clues):
        self.clues = clues
        self.n = len(clues)
        self.edge_u = []
        self.edge_v = []
        self.edge_kind = []  # 'h' or 'v'
        self.edge_pos = []   # (r,c) in its own grid
        self.h_id = [[None] * self.n for _ in range(self.n + 1)]
        self.v_id = [[None] * (self.n + 1) for _ in range(self.n)]

        # Build edges
        eid = 0
        for r in range(self.n + 1):
            for c in range(self.n):
                self.h_id[r][c] = eid
                self.edge_u.append((r, c))
                self.edge_v.append((r, c + 1))
                self.edge_kind.append('h')
                self.edge_pos.append((r, c))
                eid += 1
        for r in range(self.n):
            for c in range(self.n + 1):
                self.v_id[r][c] = eid
                self.edge_u.append((r, c))
                self.edge_v.append((r + 1, c))
                self.edge_kind.append('v')
                self.edge_pos.append((r, c))
                eid += 1
        self.E = eid

        # Incident edges per vertex
        self.vertex_edges = defaultdict(list)
        for e in range(self.E):
            self.vertex_edges[self.edge_u[e]].append(e)
            self.vertex_edges[self.edge_v[e]].append(e)

        # Cell edges: top, right, bottom, left
        self.cell_edges = [[None] * self.n for _ in range(self.n)]
        self.edge_cells = [[] for _ in range(self.E)]
        for r in range(self.n):
            for c in range(self.n):
                edges = [
                    self.h_id[r][c],
                    self.v_id[r][c + 1],
                    self.h_id[r + 1][c],
                    self.v_id[r][c],
                ]
                self.cell_edges[r][c] = edges
                for e in edges:
                    self.edge_cells[e].append((r, c))

        self.vertices = [(r, c) for r in range(self.n + 1) for c in range(self.n + 1)]

    def new_state(self):
        return [UNKNOWN] * self.E

    def assign(self, state, e, val, changed):
        cur = state[e]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False
        state[e] = val
        changed.append(e)
        return True

    def propagate(self, state):
        changed = []
        while True:
            progress = False

            # Cell-based propagation
            for r in range(self.n):
                row = self.clues[r]
                for c in range(self.n):
                    clue = row[c]
                    if clue is None:
                        continue
                    edges = self.cell_edges[r][c]
                    on = off = 0
                    unk = []
                    for e in edges:
                        if state[e] == ON:
                            on += 1
                        elif state[e] == OFF:
                            off += 1
                        else:
                            unk.append(e)
                    if on > clue or on + len(unk) < clue:
                        return False, changed
                    need = clue - on
                    if need == 0:
                        for e in unk:
                            if not self.assign(state, e, OFF, changed):
                                return False, changed
                            progress = True
                    elif need == len(unk):
                        for e in unk:
                            if not self.assign(state, e, ON, changed):
                                return False, changed
                            progress = True

            # Vertex-based propagation: final degree must be 0 or 2
            for v in self.vertices:
                inc = self.vertex_edges[v]
                on = 0
                unk = []
                for e in inc:
                    if state[e] == ON:
                        on += 1
                    elif state[e] == UNKNOWN:
                        unk.append(e)

                if on > 2:
                    return False, changed
                if on == 2:
                    for e in unk:
                        if not self.assign(state, e, OFF, changed):
                            return False, changed
                        progress = True
                elif on == 1:
                    if len(unk) == 0:
                        return False, changed
                    if len(unk) == 1:
                        if not self.assign(state, unk[0], ON, changed):
                            return False, changed
                        progress = True
                else:  # on == 0
                    if len(unk) == 1:
                        if not self.assign(state, unk[0], OFF, changed):
                            return False, changed
                        progress = True

            # Subloop pruning
            if not self.check_partial_loops(state):
                return False, changed

            if not progress:
                break

        return True, changed

    def check_partial_loops(self, state):
        # Build graph of ON edges
        adj = defaultdict(list)
        on_edges = []
        for e, val in enumerate(state):
            if val == ON:
                u = self.edge_u[e]
                v = self.edge_v[e]
                adj[u].append((v, e))
                adj[v].append((u, e))
                on_edges.append(e)

        if not on_edges:
            return True

        seen_v = set()
        components = []
        for v in adj:
            if v in seen_v:
                continue
            stack = [v]
            seen_v.add(v)
            verts = []
            edge_count2 = 0
            while stack:
                x = stack.pop()
                verts.append(x)
                edge_count2 += len(adj[x])
                for y, _ in adj[x]:
                    if y not in seen_v:
                        seen_v.add(y)
                        stack.append(y)
            edges = edge_count2 // 2
            is_cycle = all(len(adj[x]) == 2 for x in verts)
            components.append((verts, edges, is_cycle))

        cycle_count = sum(1 for _, _, cyc in components if cyc)
        if cycle_count == 0:
            return True
        if cycle_count >= 2:
            return False
        # One cycle exists: it must be the only ON-edge component.
        if len(components) > 1:
            return False
        return True

    def is_complete(self, state):
        return all(v != UNKNOWN for v in state)

    def final_check(self, state):
        # All clues exact
        for r in range(self.n):
            for c in range(self.n):
                clue = self.clues[r][c]
                if clue is None:
                    continue
                s = sum(1 for e in self.cell_edges[r][c] if state[e] == ON)
                if s != clue:
                    return False

        # Vertex degree 0 or 2, and at least one loop edge
        adj = defaultdict(list)
        on_count = 0
        for e, val in enumerate(state):
            if val == ON:
                on_count += 1
                u = self.edge_u[e]
                v = self.edge_v[e]
                adj[u].append((v, e))
                adj[v].append((u, e))
        if on_count == 0:
            return False

        used_vertices = [v for v in adj]
        for v in used_vertices:
            if len(adj[v]) != 2:
                return False

        # Single connected loop
        start = used_vertices[0]
        seen = set([start])
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for y, _ in adj[x]:
                if y not in seen:
                    seen.add(y)
                    dq.append(y)
        if len(seen) != len(used_vertices):
            return False
        return True

    def edge_score(self, state, e):
        if state[e] != UNKNOWN:
            return -1
        score = 0
        # Prefer edges next to clues
        for r, c in self.edge_cells[e]:
            clue = self.clues[r][c]
            if clue is not None:
                edges = self.cell_edges[r][c]
                known = sum(1 for x in edges if state[x] != UNKNOWN)
                score += 10 + known
                on = sum(1 for x in edges if state[x] == ON)
                score += abs((clue * 2) - 4)  # slight bias for 0/3, then 1/2
                score += min(on, clue)
        # Prefer edges adjacent to busy vertices
        for v in (self.edge_u[e], self.edge_v[e]):
            inc = self.vertex_edges[v]
            known = sum(1 for x in inc if state[x] != UNKNOWN)
            on = sum(1 for x in inc if state[x] == ON)
            score += 3 * known + 2 * on
        return score

    def pick_edge(self, state):
        best = None
        best_score = -1
        for e in range(self.E):
            s = self.edge_score(state, e)
            if s > best_score:
                best_score = s
                best = e
        return best

    def branch_order(self, state, e):
        # Try value ordering based on clue pressure and endpoint degrees.
        want_on = 0
        want_off = 0
        for r, c in self.edge_cells[e]:
            clue = self.clues[r][c]
            if clue is None:
                continue
            edges = self.cell_edges[r][c]
            on = sum(1 for x in edges if state[x] == ON)
            unk = sum(1 for x in edges if state[x] == UNKNOWN)
            need = clue - on
            if need == unk:
                want_on += 3
            elif need == 0:
                want_off += 3
            elif need > 0:
                want_on += 1
            else:
                want_off += 1
        for v in (self.edge_u[e], self.edge_v[e]):
            inc = self.vertex_edges[v]
            on = sum(1 for x in inc if state[x] == ON)
            unk = sum(1 for x in inc if state[x] == UNKNOWN)
            if on == 1 and unk == 1:
                want_on += 4
            if on == 0 and unk == 1:
                want_off += 4
            if on == 2:
                want_off += 5
        return [ON, OFF] if want_on >= want_off else [OFF, ON]

    def search(self, state):
        ok, _ = self.propagate(state)
        if not ok:
            return None

        if self.is_complete(state):
            return state if self.final_check(state) else None

        e = self.pick_edge(state)
        if e is None:
            return state if self.final_check(state) else None

        for val in self.branch_order(state, e):
            new_state = state[:]
            changed = []
            if not self.assign(new_state, e, val, changed):
                continue
            res = self.search(new_state)
            if res is not None:
                return res
        return None

    def loop_coordinates(self, state):
        adj = defaultdict(list)
        for e, val in enumerate(state):
            if val == ON:
                u = self.edge_u[e]
                v = self.edge_v[e]
                adj[u].append(v)
                adj[v].append(u)

        if not adj:
            return []

        start = min(adj.keys())
        loop = [start]
        prev = None
        cur = start
        while True:
            nbrs = adj[cur]
            if len(nbrs) != 2:
                return []
            if prev is None:
                nxt = min(nbrs)
            else:
                nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]
            loop.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
        return loop


def solve(observation):
    clues = observation["data"]
    solver = Slitherlink(clues)
    result = solver.search(solver.new_state())
    if result is None:
        return "No Solution"
    return str(solver.loop_coordinates(result))


