# Generalized Sudoku solver using human-like deduction plus tightly pruned search.
# Supports rectangular subgrids such as 3x3, 3x4, 4x4.

from collections import defaultdict

def parse_unit(unit):
    if isinstance(unit, int):
        return unit, unit
    if "x" in unit:
        a, b = unit.lower().split("x")
        return int(a), int(b)
    v = int(unit)
    return v, v

def bit_count(x):
    return x.bit_count()

def digits_from_mask(mask, n):
    d = 1
    while mask:
        b = mask & -mask
        yield (b.bit_length())
        mask ^= b
        d += 1

def mask_to_list(mask, n):
    return [i for i in range(1, n + 1) if mask & (1 << (i - 1))]

def single_value(mask):
    return mask.bit_length()

def solve(observation):
    data = observation["data"]
    br, bc = parse_unit(observation["unit"])
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"
    if br * bc != n:
        return "No Solution"

    all_mask = (1 << n) - 1
    cells = [(r, c) for r in range(n) for c in range(n)]

    row_units = [[(r, c) for c in range(n)] for r in range(n)]
    col_units = [[(r, c) for r in range(n)] for c in range(n)]
    box_units = []
    for r0 in range(0, n, br):
        for c0 in range(0, n, bc):
            box_units.append([(r, c) for r in range(r0, r0 + br) for c in range(c0, c0 + bc)])
    units = row_units + col_units + box_units

    cell_units = {cell: [] for cell in cells}
    for u in units:
        for cell in u:
            cell_units[cell].append(u)

    peers = {}
    for cell in cells:
        s = set()
        for u in cell_units[cell]:
            s.update(u)
        s.discard(cell)
        peers[cell] = tuple(s)

    box_index = {}
    idx = 0
    for r0 in range(0, n, br):
        for c0 in range(0, n, bc):
            for r in range(r0, r0 + br):
                for c in range(c0, c0 + bc):
                    box_index[(r, c)] = idx
            idx += 1

    def init_state():
        cand = {(r, c): all_mask for r in range(n) for c in range(n)}
        for r in range(n):
            for c in range(n):
                v = data[r][c]
                if v is not None:
                    if not (1 <= v <= n):
                        return None
                    if not assign(cand, (r, c), 1 << (v - 1)):
                        return None
        return cand

    def assign(cand, cell, val_mask):
        cur = cand[cell]
        if cur == val_mask:
            return True
        if not (cur & val_mask):
            return False
        other = cur & ~val_mask
        while other:
            b = other & -other
            other ^= b
            if not eliminate(cand, cell, b):
                return False
        return True

    def eliminate(cand, cell, bit):
        cur = cand[cell]
        if not (cur & bit):
            return True
        cur ^= bit
        cand[cell] = cur
        if cur == 0:
            return False
        if (cur & (cur - 1)) == 0:
            lone = cur
            for p in peers[cell]:
                if not eliminate(cand, p, lone):
                    return False
        for unit in cell_units[cell]:
            places = []
            for ucell in unit:
                if cand[ucell] & bit:
                    places.append(ucell)
            if not places:
                return False
            if len(places) == 1:
                if not assign(cand, places[0], bit):
                    return False
        return True

    def solved(cand):
        return all((m & (m - 1)) == 0 for m in cand.values())

    def propagate(cand):
        while True:
            snapshot = tuple(cand[cell] for cell in cells)

            if not apply_hidden_singles(cand):
                return False
            if not apply_locked_candidates(cand):
                return False
            if not apply_naked_subsets(cand, 2):
                return False
            if not apply_naked_subsets(cand, 3):
                return False

            if tuple(cand[cell] for cell in cells) == snapshot:
                return True

    def apply_hidden_singles(cand):
        for unit in units:
            pos = defaultdict(list)
            for cell in unit:
                mask = cand[cell]
                x = mask
                while x:
                    b = x & -x
                    pos[b].append(cell)
                    x ^= b
            for b, locs in pos.items():
                if len(locs) == 1:
                    if not assign(cand, locs[0], b):
                        return False
        return True

    def apply_locked_candidates(cand):
        for bidx, box in enumerate(box_units):
            digit_cells = defaultdict(list)
            for cell in box:
                mask = cand[cell]
                x = mask
                while x:
                    b = x & -x
                    digit_cells[b].append(cell)
                    x ^= b
            for bit, locs in digit_cells.items():
                if len(locs) <= 1:
                    continue
                rows = {r for r, _ in locs}
                cols = {c for _, c in locs}
                if len(rows) == 1:
                    row = next(iter(rows))
                    for cell in row_units[row]:
                        if box_index[cell] != bidx and (cand[cell] & bit):
                            if not eliminate(cand, cell, bit):
                                return False
                if len(cols) == 1:
                    col = next(iter(cols))
                    for cell in col_units[col]:
                        if box_index[cell] != bidx and (cand[cell] & bit):
                            if not eliminate(cand, cell, bit):
                                return False

        for unit in row_units + col_units:
            digit_cells = defaultdict(list)
            for cell in unit:
                mask = cand[cell]
                x = mask
                while x:
                    b = x & -x
                    digit_cells[b].append(cell)
                    x ^= b
            for bit, locs in digit_cells.items():
                if len(locs) <= 1:
                    continue
                boxes = {box_index[cell] for cell in locs}
                if len(boxes) == 1:
                    bidx = next(iter(boxes))
                    for cell in box_units[bidx]:
                        if cell not in locs and (cand[cell] & bit):
                            if not eliminate(cand, cell, bit):
                                return False
        return True

    def apply_naked_subsets(cand, subset_size):
        for unit in units:
            groups = defaultdict(list)
            for cell in unit:
                mask = cand[cell]
                if bit_count(mask) == subset_size:
                    groups[mask].append(cell)
            for mask, locs in groups.items():
                if len(locs) == subset_size:
                    for cell in unit:
                        if cell not in locs and (cand[cell] & mask):
                            x = cand[cell] & mask
                            while x:
                                b = x & -x
                                x ^= b
                                if not eliminate(cand, cell, b):
                                    return False
        return True

    def contradiction(cand):
        for unit in units:
            union = 0
            for cell in unit:
                if cand[cell] == 0:
                    return True
                union |= cand[cell]
            if union != all_mask:
                return True
        return False

    def choose_branch_cell(cand):
        best_cell = None
        best_len = n + 1
        best_score = -1
        for cell in cells:
            mask = cand[cell]
            cnt = bit_count(mask)
            if cnt > 1:
                score = sum(1 for p in peers[cell] if bit_count(cand[p]) > 1)
                if cnt < best_len or (cnt == best_len and score > best_score):
                    best_len = cnt
                    best_score = score
                    best_cell = cell
        return best_cell

    def search(cand):
        if cand is None:
            return None
        if not propagate(cand):
            return None
        if contradiction(cand):
            return None
        if solved(cand):
            return cand

        cell = choose_branch_cell(cand)
        if cell is None:
            return None

        mask = cand[cell]
        # Least-constraining-value ordering: try values that eliminate fewer possibilities from peers.
        options = []
        x = mask
        while x:
            b = x & -x
            x ^= b
            impact = sum(1 for p in peers[cell] if cand[p] & b)
            options.append((impact, b))
        options.sort()

        for _, bit in options:
            nxt = cand.copy()
            if assign(nxt, cell, bit):
                out = search(nxt)
                if out is not None:
                    return out
        return None

    cand = init_state()
    result = search(cand)
    if result is None:
        return "No Solution"

    solved_grid = []
    for r in range(n):
        row = []
        for c in range(n):
            row.append(single_value(result[(r, c)]))
        solved_grid.append(row)
    return str(solved_grid)

