from collections import defaultdict, deque

# Tetromino canonical shape classes.
# Coordinates are relative; rotations/reflections are generated automatically.
BASE_SHAPES = {
    "I": [(0, 0), (0, 1), (0, 2), (0, 3)],
    "L": [(0, 0), (1, 0), (2, 0), (2, 1)],
    "T": [(0, 0), (0, 1), (0, 2), (1, 1)],
    "S": [(0, 1), (0, 2), (1, 0), (1, 1)],
}

def normalize(shape):
    min_r = min(r for r, c in shape)
    min_c = min(c for r, c in shape)
    pts = sorted((r - min_r, c - min_c) for r, c in shape)
    return tuple(pts)

def transforms(shape):
    pts = shape
    out = set()
    for reflect in (False, True):
        cur = [(-r, c) if reflect else (r, c) for r, c in pts]
        for _ in range(4):
            cur = [(c, -r) for r, c in cur]
            out.add(normalize(cur))
    return sorted(out)

TETROMINOES = {k: transforms(v) for k, v in BASE_SHAPES.items()}

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0
    cells = [(r, c) for r in range(n) for c in range(m)]
    idx_of = {(r, c): r * m + c for r, c in cells}

    # Region extraction.
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            region_cells[grid[r][c]].append((r, c))
    region_ids = sorted(region_cells)
    R = len(region_ids)
    reg_index = {rid: i for i, rid in enumerate(region_ids)}
    reg_cells = [region_cells[rid] for rid in region_ids]
    cell_region = {}
    for i, rcells in enumerate(reg_cells):
        for cell in rcells:
            cell_region[cell] = i

    # Region adjacency graph.
    reg_adj = [set() for _ in range(R)]
    for r in range(n):
        for c in range(m):
            a = reg_index[grid[r][c]]
            for dr, dc in ((1, 0), (0, 1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    b = reg_index[grid[rr][cc]]
                    if a != b:
                        reg_adj[a].add(b)
                        reg_adj[b].add(a)

    # Enumerate all in-region tetromino placements.
    placements = [[] for _ in range(R)]
    placements_by_type = [defaultdict(list) for _ in range(R)]
    all_cells_set = [set(rcells) for rcells in reg_cells]

    for ri, rcells in enumerate(reg_cells):
        region_set = all_cells_set[ri]
        seen = set()
        for tname, variants in TETROMINOES.items():
            for var in variants:
                max_r = max(r for r, c in var)
                max_c = max(c for r, c in var)
                for ar, ac in rcells:
                    # Anchor normalized shape at one of the region cells.
                    translated = tuple(sorted((ar + r, ac + c) for r, c in var))
                    if translated in seen:
                        continue
                    if all((rr, cc) in region_set for rr, cc in translated):
                        seen.add(translated)
                        mask = 0
                        cell_idxs = []
                        for cell in translated:
                            k = idx_of[cell]
                            mask |= 1 << k
                            cell_idxs.append(k)
                        p = {
                            "type": tname,
                            "cells": translated,
                            "cell_idxs": tuple(sorted(cell_idxs)),
                            "mask": mask,
                        }
                        placements[ri].append(p)
                        placements_by_type[ri][tname].append(len(placements[ri]) - 1)

    # Basic feasibility.
    for ri in range(R):
        if not placements[ri]:
            return "No Solution"

    # Precompute 2x2 windows.
    windows = []
    cell_to_windows = defaultdict(list)
    for r in range(n - 1):
        for c in range(m - 1):
            w = (idx_of[(r, c)], idx_of[(r + 1, c)], idx_of[(r, c + 1)], idx_of[(r + 1, c + 1)])
            wi = len(windows)
            windows.append(w)
            for x in w:
                cell_to_windows[x].append(wi)

    # Human-like region summaries: possible types, forced cells, possible cells.
    def possible_types(domains, ri):
        return {placements[ri][pi]["type"] for pi in domains[ri]}

    def forced_mask(domains, ri):
        it = iter(domains[ri])
        try:
            first = next(it)
        except StopIteration:
            return None
        mask = placements[ri][first]["mask"]
        for pi in it:
            mask &= placements[ri][pi]["mask"]
        return mask

    def union_mask(domains, ri):
        mask = 0
        for pi in domains[ri]:
            mask |= placements[ri][pi]["mask"]
        return mask

    def full_union_mask(domains):
        mask = 0
        for ri in range(R):
            mask |= union_mask(domains, ri)
        return mask

    # Connectivity helpers.
    def bit_cells(mask):
        while mask:
            b = mask & -mask
            yield (b.bit_length() - 1)
            mask ^= b

    neigh = [[] for _ in range(n * m)]
    for r in range(n):
        for c in range(m):
            k = idx_of[(r, c)]
            if r > 0:
                neigh[k].append(idx_of[(r - 1, c)])
            if r + 1 < n:
                neigh[k].append(idx_of[(r + 1, c)])
            if c > 0:
                neigh[k].append(idx_of[(r, c - 1)])
            if c + 1 < m:
                neigh[k].append(idx_of[(r, c + 1)])

    def component_count(mask):
        seen = set()
        cnt = 0
        for start in bit_cells(mask):
            if start in seen:
                continue
            cnt += 1
            dq = [start]
            seen.add(start)
            while dq:
                x = dq.pop()
                for y in neigh[x]:
                    if (mask >> y) & 1 and y not in seen:
                        seen.add(y)
                        dq.append(y)
        return cnt

    def reachable_from_forced(forced, possible):
        if forced == 0:
            return True
        starts = list(bit_cells(forced))
        q = deque([starts[0]])
        seen = {starts[0]}
        while q:
            x = q.popleft()
            for y in neigh[x]:
                if ((possible >> y) & 1) and y not in seen:
                    seen.add(y)
                    q.append(y)
        return all(s in seen for s in starts)

    def placement_connects_existing(placement_mask, assigned_mask):
        if assigned_mask == 0:
            return True
        for x in bit_cells(placement_mask):
            for y in neigh[x]:
                if (assigned_mask >> y) & 1:
                    return True
        return False

    # Aggressive propagation.
    def propagate(domains):
        changed = True
        while changed:
            changed = False

            # Empty domain check.
            for ri in range(R):
                if not domains[ri]:
                    return None

            # Neighboring regions cannot share same tetromino type once forced.
            forced_types = {}
            for ri in range(R):
                tys = possible_types(domains, ri)
                if len(tys) == 1:
                    forced_types[ri] = next(iter(tys))

            for ri, t in forced_types.items():
                for rj in reg_adj[ri]:
                    new_dom = [pi for pi in domains[rj] if placements[rj][pi]["type"] != t]
                    if not new_dom:
                        return None
                    if len(new_dom) != len(domains[rj]):
                        domains[rj] = new_dom
                        changed = True

            # Type-support consistency: if a region can only use a type that all neighbors must avoid, filter them.
            for ri in range(R):
                tys = possible_types(domains, ri)
                if not tys:
                    return None
                if len(tys) == 1:
                    continue
                valid = []
                for pi in domains[ri]:
                    t = placements[ri][pi]["type"]
                    ok = True
                    for rj in reg_adj[ri]:
                        if all(placements[rj][pj]["type"] == t for pj in domains[rj]):
                            ok = False
                            break
                    if ok:
                        valid.append(pi)
                if not valid:
                    return None
                if len(valid) != len(domains[ri]):
                    domains[ri] = valid
                    changed = True

            # 2x2 full-shade pruning against assigned / forced information.
            forced_masks = [forced_mask(domains, ri) for ri in range(R)]
            union_masks = [union_mask(domains, ri) for ri in range(R)]
            global_forced = 0
            global_possible = 0
            for ri in range(R):
                global_forced |= forced_masks[ri]
                global_possible |= union_masks[ri]

            # Any forced 2x2 is impossible.
            for w in windows:
                if all((global_forced >> x) & 1 for x in w):
                    return None

            # If a placement immediately creates a forced 2x2 with already forced cells, remove it.
            for ri in range(R):
                others_forced = global_forced & ~union_masks[ri]
                new_dom = []
                for pi in domains[ri]:
                    pmask = placements[ri][pi]["mask"]
                    bad = False
                    for w in windows:
                        full = True
                        for x in w:
                            if not (((others_forced >> x) & 1) or ((pmask >> x) & 1 and ((union_masks[ri] >> x) & 1))):
                                full = False
                                break
                        if full:
                            bad = True
                            break
                    if not bad:
                        new_dom.append(pi)
                if not new_dom:
                    return None
                if len(new_dom) != len(domains[ri]):
                    domains[ri] = new_dom
                    changed = True

            # Global connectivity viability:
            # 1) all forced shaded cells must lie in one component inside the union of all possible shaded cells.
            forced_total = 0
            possible_total = 0
            for ri in range(R):
                forced_total |= forced_mask(domains, ri)
                possible_total |= union_mask(domains, ri)
            if not reachable_from_forced(forced_total, possible_total):
                return None

            # 2) number of forced components cannot exceed remaining flexible bridge count + 1.
            comp = component_count(forced_total)
            flexible = sum(1 for ri in range(R) if len(domains[ri]) > 1)
            if comp > flexible + 1:
                return None

            # 3) Once there is an assigned connected mass, future assigned placements should remain attachable.
            assigned_singletons = [ri for ri in range(R) if len(domains[ri]) == 1]
            assigned_mask = 0
            for ri in assigned_singletons:
                assigned_mask |= placements[ri][domains[ri][0]]["mask"]
            if assigned_mask:
                for ri in range(R):
                    if len(domains[ri]) > 1:
                        valid = [pi for pi in domains[ri] if placement_connects_existing(placements[ri][pi]["mask"], assigned_mask) or possible_total == placements[ri][pi]["mask"]]
                        if valid:
                            # Only apply when it does not wipe out all ways to connect later.
                            if len(valid) != len(domains[ri]):
                                domains[ri] = valid
                                changed = True

        return domains

    def choose_region(domains):
        # Human-like choice:
        # 1) fewest placements
        # 2) fewest possible types
        # 3) most constrained by neighbors
        best = None
        best_key = None
        for ri in range(R):
            if len(domains[ri]) <= 1:
                continue
            key = (len(domains[ri]), len(possible_types(domains, ri)), -len(reg_adj[ri]), -len(reg_cells[ri]))
            if best_key is None or key < best_key:
                best_key = key
                best = ri
        return best

    def order_values(domains, ri):
        # Least-constraining placement order.
        assigned_mask = 0
        for rj in range(R):
            if len(domains[rj]) == 1:
                assigned_mask |= placements[rj][domains[rj][0]]["mask"]

        def score(pi):
            p = placements[ri][pi]
            t = p["type"]
            hit = 0
            for rj in reg_adj[ri]:
                hit += sum(1 for pj in domains[rj] if placements[rj][pj]["type"] == t)
            conn_bonus = 0 if placement_connects_existing(p["mask"], assigned_mask) else 1
            return (conn_bonus, hit)

        return sorted(domains[ri], key=score)

    def is_complete(domains):
        return all(len(domains[ri]) == 1 for ri in range(R))

    def final_check(domains):
        shaded = 0
        answer = [[None for _ in range(m)] for _ in range(n)]
        for ri in range(R):
            p = placements[ri][domains[ri][0]]
            shaded |= p["mask"]
            for r, c in p["cells"]:
                answer[r][c] = p["type"]

        # Whole-grid connectivity.
        if shaded == 0 or component_count(shaded) != 1:
            return None

        # No full 2x2.
        for w in windows:
            if all((shaded >> x) & 1 for x in w):
                return None

        # Adjacent regions distinct type.
        reg_type = {}
        for ri in range(R):
            reg_type[ri] = placements[ri][domains[ri][0]]["type"]
        for ri in range(R):
            for rj in reg_adj[ri]:
                if ri < rj and reg_type[ri] == reg_type[rj]:
                    return None

        return answer

    def search(domains):
        domains = [list(d) for d in domains]
        domains = propagate(domains)
        if domains is None:
            return None
        if is_complete(domains):
            return final_check(domains)

        ri = choose_region(domains)
        if ri is None:
            return None

        for pi in order_values(domains, ri):
            nd = [list(d) for d in domains]
            nd[ri] = [pi]
            res = search(nd)
            if res is not None:
                return res
        return None

    initial_domains = [list(range(len(placements[ri]))) for ri in range(R)]
    solution = search(initial_domains)
    if solution is None:
        return "No Solution"
    return repr(solution)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'B', None, None, None, None, 'W', None], [None, 'B', None, None, None, None, 'W', None], [None, None, 'B', None, None, 'B', None, None], [None, None, None, None, None, None, None, None], [None, None, None, 'W', 'B', None, None, None], ['W', None, None, None, None, None, None, 'W'], [None, None, None, 'B', 'W', None, None, None], [None, 'W', None, None, None, None, 'B', None]], 'horizontal': {'(5.0,1.5)': '='}, 'vertical': {'(1.5,0.0)': 'x', '(0.5,4.0)': '=', '(2.5,6.0)': 'x', '(3.5,2.0)': '=', '(5.5,5.0)': '='}}

# B=1, W=2, unknown=3
B, W, U = 1, 2, 3

def parse_key(s):
    a, b = s.strip()[1:-1].split(',')
    return float(a), float(b)

def bit_to_char(v):
    return 'B' if v == B else 'W'

def popcount2(x):
    return (x & 1) + ((x >> 1) & 1)

def singleton_value(mask):
    return B if mask == B else W if mask == W else None

def other(v):
    return W if v == B else B

def generate_patterns(n):
    half = n // 2
    out = []

    def rec(i, prev1, prev2, cb, cw, arr):
        if cb > half or cw > half:
            return
        if i == n:
            if cb == half and cw == half:
                out.append(tuple(arr))
            return
        rem = n - i
        if cb + rem < half or cw + rem < half:
            return
        for v in (B, W):
            if i >= 2 and prev1 == prev2 == v:
                continue
            arr.append(v)
            rec(i + 1, v, prev1, cb + (v == B), cw + (v == W), arr)
            arr.pop()

    rec(0, 0, 0, 0, 0, [])
    return out

def build_relations(observation):
    h = {}
    v = {}
    for k, sym in observation['horizontal'].items():
        r, c = parse_key(k)
        h[(int(round(r)), int(round(c - 0.5)))] = sym
    for k, sym in observation['vertical'].items():
        r, c = parse_key(k)
        v[(int(round(r - 0.5)), int(round(c)))] = sym
    return h, v

def line_patterns_row(all_patterns, row_idx, domains, hrels):
    n = len(domains[0])
    row = domains[row_idx]
    pats = []
    for p in all_patterns:
        ok = True
        for c in range(n):
            if not (row[c] & p[c]):
                ok = False
                break
        if not ok:
            continue
        for c in range(n - 1):
            sym = hrels.get((row_idx, c))
            if sym == '=' and p[c] != p[c + 1]:
                ok = False
                break
            if sym == 'x' and p[c] == p[c + 1]:
                ok = False
                break
        if ok:
            pats.append(p)
    return pats

def line_patterns_col(all_patterns, col_idx, domains, vrels):
    n = len(domains)
    pats = []
    for p in all_patterns:
        ok = True
        for r in range(n):
            if not (domains[r][col_idx] & p[r]):
                ok = False
                break
        if not ok:
            continue
        for r in range(n - 1):
            sym = vrels.get((r, col_idx))
            if sym == '=' and p[r] != p[r + 1]:
                ok = False
                break
            if sym == 'x' and p[r] == p[r + 1]:
                ok = False
                break
        if ok:
            pats.append(p)
    return pats

def apply_local_rules(domains, hrels, vrels):
    n = len(domains)
    changed = True
    while changed:
        changed = False

        # direct same/diff propagation
        for r in range(n):
            for c in range(n - 1):
                sym = hrels.get((r, c))
                if not sym:
                    continue
                a, b = domains[r][c], domains[r][c + 1]
                if sym == '=':
                    na = a & b
                    nb = b & a
                else:
                    na = a & (other(B) if b == B else other(W) if b == W else U)
                    nb = b & (other(B) if a == B else other(W) if a == W else U)
                    if a == U and b == U:
                        na, nb = U, U
                    elif a in (B, W):
                        nb = b & other(a)
                    elif b in (B, W):
                        na = a & other(b)
                if na == 0 or nb == 0:
                    return False
                if na != a:
                    domains[r][c] = na
                    changed = True
                if nb != b:
                    domains[r][c + 1] = nb
                    changed = True

        for r in range(n - 1):
            for c in range(n):
                sym = vrels.get((r, c))
                if not sym:
                    continue
                a, b = domains[r][c], domains[r + 1][c]
                if sym == '=':
                    na = a & b
                    nb = b & a
                else:
                    na = a & (other(B) if b == B else other(W) if b == W else U)
                    nb = b & (other(B) if a == B else other(W) if a == W else U)
                    if a == U and b == U:
                        na, nb = U, U
                    elif a in (B, W):
                        nb = b & other(a)
                    elif b in (B, W):
                        na = a & other(b)
                if na == 0 or nb == 0:
                    return False
                if na != a:
                    domains[r][c] = na
                    changed = True
                if nb != b:
                    domains[r + 1][c] = nb
                    changed = True

        # no-three local deductions on rows
        for r in range(n):
            for c in range(n - 2):
                a, b, d = domains[r][c], domains[r][c + 1], domains[r][c + 2]
                va, vb, vd = singleton_value(a), singleton_value(b), singleton_value(d)
                if va and vb and va == vb:
                    nd = d & other(va)
                    if nd == 0:
                        return False
                    if nd != d:
                        domains[r][c + 2] = nd
                        changed = True
                if vb and vd and vb == vd:
                    na = a & other(vb)
                    if na == 0:
                        return False
                    if na != a:
                        domains[r][c] = na
                        changed = True
                if va and vd and va == vd:
                    nb = b & other(va)
                    if nb == 0:
                        return False
                    if nb != b:
                        domains[r][c + 1] = nb
                        changed = True

        # no-three local deductions on cols
        for c in range(n):
            for r in range(n - 2):
                a, b, d = domains[r][c], domains[r + 1][c], domains[r + 2][c]
                va, vb, vd = singleton_value(a), singleton_value(b), singleton_value(d)
                if va and vb and va == vb:
                    nd = d & other(va)
                    if nd == 0:
                        return False
                    if nd != d:
                        domains[r + 2][c] = nd
                        changed = True
                if vb and vd and vb == vd:
                    na = a & other(vb)
                    if na == 0:
                        return False
                    if na != a:
                        domains[r][c] = na
                        changed = True
                if va and vd and va == vd:
                    nb = b & other(va)
                    if nb == 0:
                        return False
                    if nb != b:
                        domains[r + 1][c] = nb
                        changed = True

        # quick count bounds
        half = n // 2
        for r in range(n):
            cnt_b = sum(domains[r][c] == B for c in range(n))
            cnt_w = sum(domains[r][c] == W for c in range(n))
            unk = [c for c in range(n) if domains[r][c] == U]
            if cnt_b > half or cnt_w > half:
                return False
            if cnt_b + len(unk) < half or cnt_w + len(unk) < half:
                return False
            if cnt_b == half:
                for c in unk:
                    domains[r][c] = W
                    changed = True
            if cnt_w == half:
                for c in unk:
                    domains[r][c] = B
                    changed = True

        for c in range(n):
            cnt_b = sum(domains[r][c] == B for r in range(n))
            cnt_w = sum(domains[r][c] == W for r in range(n))
            unk = [r for r in range(n) if domains[r][c] == U]
            if cnt_b > half or cnt_w > half:
                return False
            if cnt_b + len(unk) < half or cnt_w + len(unk) < half:
                return False
            if cnt_b == half:
                for r in unk:
                    domains[r][c] = W
                    changed = True
            if cnt_w == half:
                for r in unk:
                    domains[r][c] = B
                    changed = True

        for r in range(n):
            for c in range(n):
                if domains[r][c] == 0:
                    return False
    return True

def propagate(domains, hrels, vrels, all_patterns):
    n = len(domains)
    if not apply_local_rules(domains, hrels, vrels):
        return None, None

    row_pats = [None] * n
    col_pats = [None] * n

    changed = True
    while changed:
        changed = False

        for r in range(n):
            pats = line_patterns_row(all_patterns, r, domains, hrels)
            if not pats:
                return None, None
            row_pats[r] = pats
            for c in range(n):
                allowed = 0
                for p in pats:
                    allowed |= p[c]
                nd = domains[r][c] & allowed
                if nd == 0:
                    return None, None
                if nd != domains[r][c]:
                    domains[r][c] = nd
                    changed = True

        for c in range(n):
            pats = line_patterns_col(all_patterns, c, domains, vrels)
            if not pats:
                return None, None
            col_pats[c] = pats
            for r in range(n):
                allowed = 0
                for p in pats:
                    allowed |= p[r]
                nd = domains[r][c] & allowed
                if nd == 0:
                    return None, None
                if nd != domains[r][c]:
                    domains[r][c] = nd
                    changed = True

        if changed and not apply_local_rules(domains, hrels, vrels):
            return None, None

    # final consistency refresh
    for r in range(n):
        row_pats[r] = line_patterns_row(all_patterns, r, domains, hrels)
        if not row_pats[r]:
            return None, None
    for c in range(n):
        col_pats[c] = line_patterns_col(all_patterns, c, domains, vrels)
        if not col_pats[c]:
            return None, None

    return row_pats, col_pats

def is_solved(domains):
    return all(v in (B, W) for row in domains for v in row)

def clone_domains(domains):
    return [row[:] for row in domains]

def search(domains, hrels, vrels, all_patterns):
    line_info = propagate(domains, hrels, vrels, all_patterns)
    if line_info == (None, None):
        return None
    row_pats, col_pats = line_info

    if is_solved(domains):
        return domains

    n = len(domains)

    # choose strongest branch: smallest line pattern set or cell domain
    best = None

    for r in range(n):
        k = len(row_pats[r])
        if 1 < k and (best is None or k < best[0]):
            best = (k, 'row', r)
    for c in range(n):
        k = len(col_pats[c])
        if 1 < k and (best is None or k < best[0]):
            best = (k, 'col', c)

    # if no informative line, choose a binary cell
    if best is None or best[0] > 2:
        for r in range(n):
            for c in range(n):
                if domains[r][c] == U:
                    best = (2, 'cell', r, c)
                    break
            if best and best[1] == 'cell':
                break

    if best[1] == 'row':
        _, _, r = best
        for p in row_pats[r]:
            nd = clone_domains(domains)
            ok = True
            for c in range(n):
                v = nd[r][c] & p[c]
                if v == 0:
                    ok = False
                    break
                nd[r][c] = p[c]
            if ok:
                res = search(nd, hrels, vrels, all_patterns)
                if res is not None:
                    return res
    elif best[1] == 'col':
        _, _, c = best
        for p in col_pats[c]:
            nd = clone_domains(domains)
            ok = True
            for r in range(n):
                v = nd[r][c] & p[r]
                if v == 0:
                    ok = False
                    break
                nd[r][c] = p[r]
            if ok:
                res = search(nd, hrels, vrels, all_patterns)
                if res is not None:
                    return res
    else:
        _, _, r, c = best
        for v in (B, W):
            if domains[r][c] & v:
                nd = clone_domains(domains)
                nd[r][c] = v
                res = search(nd, hrels, vrels, all_patterns)
                if res is not None:
                    return res

    return None

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data) or n % 2:
        return "No Solution"

    hrels, vrels = build_relations(observation)
    domains = [[U] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if data[r][c] == 'B':
                domains[r][c] = B
            elif data[r][c] == 'W':
                domains[r][c] = W

    all_patterns = generate_patterns(n)
    res = search(domains, hrels, vrels, all_patterns)
    if res is None:
        return "No Solution"
    return [[bit_to_char(v) for v in row] for row in res]

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 0, 0, 0, 0, 1, 1], [0, 2, 2, 2, 2, 1, 1, 3], [4, 4, 5, 5, 2, 3, 3, 3], [4, 4, 5, 5, 2, 6, 7, 3], [8, 4, 5, 5, 6, 6, 7, 7], [8, 8, 8, 5, 6, 6, 7, 9], [8, 5, 5, 5, 5, 6, 9, 9], [8, 8, 8, 8, 5, 9, 9, 9]]}

from itertools import combinations

# General tetromino-region puzzle solver.
# The observation above is a parsed region-id grid.
# The solver itself is fully generalized for arbitrary region partitions.

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0
    if n == 0 or m == 0:
        return "No Solution"

    # ---------- basic indexing ----------
    def cid(r, c):
        return r * m + c

    def rc(i):
        return divmod(i, m)

    all_cells = list(range(n * m))

    # ---------- region extraction ----------
    region_cells = {}
    for r in range(n):
        for c in range(m):
            region_cells.setdefault(grid[r][c], []).append(cid(r, c))
    region_ids = sorted(region_cells)
    ridx_of = {rid: i for i, rid in enumerate(region_ids)}
    regions = [region_cells[rid] for rid in region_ids]
    R = len(regions)

    cell_region = [None] * (n * m)
    for i, cells in enumerate(regions):
        for x in cells:
            cell_region[x] = i

    # ---------- region adjacency ----------
    region_neighbors = [set() for _ in range(R)]
    for r in range(n):
        for c in range(m):
            a = ridx_of[grid[r][c]]
            if r + 1 < n:
                b = ridx_of[grid[r + 1][c]]
                if a != b:
                    region_neighbors[a].add(b)
                    region_neighbors[b].add(a)
            if c + 1 < m:
                b = ridx_of[grid[r][c + 1]]
                if a != b:
                    region_neighbors[a].add(b)
                    region_neighbors[b].add(a)

    # ---------- tetromino classification ----------
    def normalize(points):
        minr = min(r for r, c in points)
        minc = min(c for r, c in points)
        return tuple(sorted((r - minr, c - minc) for r, c in points))

    def transforms(points):
        pts = list(points)
        out = []
        for reflect in (0, 1):
            q = [(-r, c) if reflect else (r, c) for r, c in pts]
            for _ in range(4):
                q = [(c, -r) for r, c in q]
                out.append(normalize(q))
        return set(out)

    base_types = {
        "I": {(0, 0), (1, 0), (2, 0), (3, 0)},
        "L": {(0, 0), (1, 0), (2, 0), (2, 1)},
        "T": {(0, 0), (0, 1), (0, 2), (1, 1)},
        "S": {(0, 1), (0, 2), (1, 0), (1, 1)},
    }
    canon_to_type = {}
    for tname, pts in base_types.items():
        for form in transforms(pts):
            canon_to_type[form] = tname

    def is_connected4(cells4):
        cells4 = set(cells4)
        stack = [next(iter(cells4))]
        seen = {stack[0]}
        while stack:
            x = stack.pop()
            r, c = rc(x)
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= nr < n and 0 <= nc < m:
                    y = cid(nr, nc)
                    if y in cells4 and y not in seen:
                        seen.add(y)
                        stack.append(y)
        return len(seen) == 4

    def classify_tetromino(cells4):
        pts = [rc(x) for x in cells4]
        canon = normalize(pts)
        return canon_to_type.get(canon)

    # ---------- placements per region ----------
    placements = []
    for ri, cells in enumerate(regions):
        plist = []
        if len(cells) >= 4:
            for comb in combinations(cells, 4):
                if not is_connected4(comb):
                    continue
                tname = classify_tetromino(comb)
                if tname is None:
                    continue
                mask = 0
                for x in comb:
                    mask |= 1 << x
                plist.append((mask, tname))
        # dedupe identical masks/types if any
        uniq = {}
        for mask, tname in plist:
            uniq[(mask, tname)] = (mask, tname)
        plist = list(uniq.values())
        placements.append(plist)

    if any(len(plist) == 0 for plist in placements):
        return "No Solution"

    # ---------- bit helpers ----------
    type_bit = {"L": 1, "I": 2, "T": 4, "S": 8}

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield (b.bit_length() - 1)
            mask ^= b

    def popcount(x):
        return x.bit_count()

    # domain masks over placement indices
    init_domains = []
    placement_masks = []
    placement_types = []
    placement_type_bits = []
    region_cell_masks = []
    for plist in placements:
        region_cell_masks.append(sum(1 << x for x in []))
        pm = []
        pt = []
        pb = []
        for mask, tname in plist:
            pm.append(mask)
            pt.append(tname)
            pb.append(type_bit[tname])
        placement_masks.append(pm)
        placement_types.append(pt)
        placement_type_bits.append(pb)
        init_domains.append((1 << len(plist)) - 1)

    region_cell_masks = [sum(1 << x for x in regions[i]) for i in range(R)]

    # ---------- 2x2 block masks ----------
    blocks2 = []
    for r in range(n - 1):
        for c in range(m - 1):
            blocks2.append((1 << cid(r, c)) | (1 << cid(r + 1, c)) | (1 << cid(r, c + 1)) | (1 << cid(r + 1, c + 1)))

    # ---------- cell graph ----------
    nbr_mask = [0] * (n * m)
    for r in range(n):
        for c in range(m):
            x = cid(r, c)
            mask = 0
            for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                if 0 <= nr < n and 0 <= nc < m:
                    mask |= 1 << cid(nr, nc)
            nbr_mask[x] = mask

    # ---------- cached region-domain summaries ----------
    def region_union_intersection_types(ri, dmask):
        pm = placement_masks[ri]
        pb = placement_type_bits[ri]
        union = 0
        inter = (1 << (n * m)) - 1
        tset = 0
        first = True
        for pi in iter_bits(dmask):
            union |= pm[pi]
            if first:
                inter = pm[pi]
                first = False
            else:
                inter &= pm[pi]
            tset |= pb[pi]
        return union, inter, tset

    def components_of_mask(mask):
        comps = []
        unseen = mask
        while unseen:
            seed_bit = unseen & -unseen
            comp = 0
            frontier = seed_bit
            unseen ^= seed_bit
            while frontier:
                b = frontier & -frontier
                frontier ^= b
                i = b.bit_length() - 1
                comp |= b
                grow = nbr_mask[i] & unseen
                frontier |= grow
                unseen ^= grow
            comps.append(comp)
        return comps

    def one_bit_type_name(tbits):
        if tbits == 1:
            return "L"
        if tbits == 2:
            return "I"
        if tbits == 4:
            return "T"
        if tbits == 8:
            return "S"
        return None

    # ---------- propagation ----------
    def propagate(domains):
        domains = list(domains)
        while True:
            changed = False

            unions = [0] * R
            inters = [0] * R
            type_sets = [0] * R

            for ri in range(R):
                d = domains[ri]
                if d == 0:
                    return None
                unions[ri], inters[ri], type_sets[ri] = region_union_intersection_types(ri, d)
                if type_sets[ri] == 0:
                    return None

            # Adjacent regions cannot share tetromino type.
            for a in range(R):
                ta = type_sets[a]
                if ta & (ta - 1) == 0:
                    forbidden = ta
                    for b in region_neighbors[a]:
                        db = domains[b]
                        nd = db
                        for pi in iter_bits(db):
                            if placement_type_bits[b][pi] & forbidden:
                                nd &= ~(1 << pi)
                        if nd == 0:
                            return None
                        if nd != db:
                            domains[b] = nd
                            changed = True
                for b in region_neighbors[a]:
                    if a < b and (type_sets[a] & (type_sets[a] - 1) == 0) and type_sets[a] == type_sets[b] and (type_sets[b] & (type_sets[b] - 1) == 0):
                        return None

            if changed:
                continue

            # Forbid unavoidable 2x2 fully shaded blocks.
            forced_shaded = 0
            for ri in range(R):
                forced_shaded |= inters[ri]
            for blk in blocks2:
                if (forced_shaded & blk) == blk:
                    return None

            # Connectivity via possible-shaded components.
            possible = 0
            for u in unions:
                possible |= u
            comps = components_of_mask(possible)
            if not comps:
                return None

            forced_comps = []
            for comp in comps:
                if forced_shaded & comp:
                    forced_comps.append(comp)
            if len(forced_comps) > 1:
                return None

            if forced_comps:
                target_candidates = forced_comps
            else:
                target_candidates = comps

            feasible_targets = []
            for comp in target_candidates:
                ok = True
                for ri in range(R):
                    # region must have at least one placement wholly inside target component
                    found = False
                    d = domains[ri]
                    for pi in iter_bits(d):
                        if placement_masks[ri][pi] & ~comp == 0:
                            found = True
                            break
                    if not found:
                        ok = False
                        break
                if ok:
                    feasible_targets.append(comp)

            if not feasible_targets:
                return None

            if len(feasible_targets) == 1:
                comp = feasible_targets[0]
                for ri in range(R):
                    d = domains[ri]
                    nd = d
                    for pi in iter_bits(d):
                        if placement_masks[ri][pi] & ~comp:
                            nd &= ~(1 << pi)
                    if nd == 0:
                        return None
                    if nd != d:
                        domains[ri] = nd
                        changed = True
                if changed:
                    continue

            # Additional 2x2 propagation:
            # if a block has 3 forced shaded cells, the 4th cannot be shaded in any remaining placement.
            forced_shaded = 0
            for ri in range(R):
                _, inters[ri], _ = region_union_intersection_types(ri, domains[ri])
                forced_shaded |= inters[ri]

            cell_forced = [(forced_shaded >> i) & 1 for i in range(n * m)]
            for blk in blocks2:
                blk_cells = [i for i in iter_bits(blk)]
                cnt = sum(cell_forced[i] for i in blk_cells)
                if cnt == 4:
                    return None
                if cnt == 3:
                    for i in blk_cells:
                        if not cell_forced[i]:
                            ri = cell_region[i]
                            d = domains[ri]
                            nd = d
                            for pi in iter_bits(d):
                                if (placement_masks[ri][pi] >> i) & 1:
                                    nd &= ~(1 << pi)
                            if nd == 0:
                                return None
                            if nd != d:
                                domains[ri] = nd
                                changed = True
            if changed:
                continue

            # Region pair type support checking.
            for a in range(R):
                for b in region_neighbors[a]:
                    if a < b:
                        da = domains[a]
                        db = domains[b]
                        support_a = 0
                        support_b = 0
                        for pa in iter_bits(da):
                            ta = placement_type_bits[a][pa]
                            ok = False
                            for pb in iter_bits(db):
                                if placement_type_bits[b][pb] != ta:
                                    ok = True
                                    support_b |= (1 << pb)
                            if ok:
                                support_a |= (1 << pa)
                        if support_a == 0 or support_b == 0:
                            return None
                        if support_a != da:
                            domains[a] = support_a
                            changed = True
                        if support_b != db:
                            domains[b] = support_b
                            changed = True
            if changed:
                continue

            return tuple(domains)

    # ---------- choose branch ----------
    def select_region(domains):
        best = None
        best_key = None
        for ri in range(R):
            d = domains[ri]
            pc = popcount(d)
            if pc > 1:
                _, _, tset = region_union_intersection_types(ri, d)
                key = (pc, popcount(tset), len(regions[ri]))
                if best is None or key < best_key:
                    best = ri
                    best_key = key
        return best

    def order_candidates(domains, ri):
        d = domains[ri]
        counts_by_type = {"L": 0, "I": 0, "T": 0, "S": 0}
        for rj in range(R):
            for pj in iter_bits(domains[rj]):
                counts_by_type[placement_types[rj][pj]] += 1

        neigh_forbidden_pressure = 0
        for nb in region_neighbors[ri]:
            _, _, tset = region_union_intersection_types(nb, domains[nb])
            neigh_forbidden_pressure |= tset

        cand = []
        for pi in iter_bits(d):
            t = placement_types[ri][pi]
            # Prefer rarer types and more connecting placements.
            mask = placement_masks[ri][pi]
            contact = 0
            for x in iter_bits(mask):
                contact |= nbr_mask[x]
            score = (
                counts_by_type[t],
                0 if (type_bit[t] & neigh_forbidden_pressure) == 0 else 1,
                -popcount(contact),
            )
            cand.append((score, pi))
        cand.sort()
        return [pi for _, pi in cand]

    # ---------- final validation ----------
    def domains_to_answer(domains):
        chosen = []
        shaded = 0
        answer = [[None for _ in range(m)] for _ in range(n)]
        region_types_final = [None] * R
        for ri in range(R):
            d = domains[ri]
            if popcount(d) != 1:
                return None
            pi = next(iter_bits(d))
            mask = placement_masks[ri][pi]
            t = placement_types[ri][pi]
            chosen.append((ri, pi))
            region_types_final[ri] = t
            shaded |= mask
            for x in iter_bits(mask):
                r, c = rc(x)
                answer[r][c] = t

        # adjacency type check
        for a in range(R):
            for b in region_neighbors[a]:
                if a < b and region_types_final[a] == region_types_final[b]:
                    return None

        # connectivity check
        comps = components_of_mask(shaded)
        if len(comps) != 1:
            return None

        # no 2x2 full
        for blk in blocks2:
            if (shaded & blk) == blk:
                return None

        return answer

    # ---------- DFS with strong propagation ----------
    seen = set()

    def search(domains):
        domains = propagate(domains)
        if domains is None:
            return None
        if domains in seen:
            return None
        seen.add(domains)

        ri = select_region(domains)
        if ri is None:
            return domains_to_answer(domains)

        for pi in order_candidates(domains, ri):
            new_domains = list(domains)
            new_domains[ri] = 1 << pi
            ans = search(tuple(new_domains))
            if ans is not None:
                return ans
        return None

    ans = search(tuple(init_domains))
    return repr(ans) if ans is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None], [None, None, None, 'B3', 'B3', 'B2'], [None, None, 'W2', None, None, None], [None, 'W2', None, None, None, None], [None, None, None, None, None, 'W2'], ['B7', None, None, None, 'B2', None]]}

from copy import deepcopy

DIRS = {
    'U': (-1, 0),
    'D': (1, 0),
    'L': (0, -1),
    'R': (0, 1),
}
OPP = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}
PERP = {
    'U': ('L', 'R'),
    'D': ('L', 'R'),
    'L': ('U', 'D'),
    'R': ('U', 'D'),
}


def solve(observation):
    data = observation['data']
    n1 = len(data)
    m1 = len(data[0])
    if n1 != m1:
        return "No Solution"
    n = n1 - 1

    edges, edge_of, incident = build_graph(n)
    clues = []
    clue_pos = set()
    for r in range(n + 1):
        for c in range(n + 1):
            tok = data[r][c]
            if tok is not None:
                t = tok[0]
                k = int(tok[1:])
                clues.append((r, c, t, k))
                clue_pos.add((r, c))

    patterns = {}
    for r, c, t, k in clues:
        pats = generate_patterns(n, (r, c), t, k, edge_of)
        if not pats:
            return "No Solution"
        patterns[(r, c)] = pats

    state = {
        'n': n,
        'edges': {eid: -1 for eid in edges},
        'patterns': patterns,
        'incident': incident,
        'clues': clues,
        'clue_pos': clue_pos,
        'edge_of': edge_of,
        'edges_meta': edges,
    }

    if not propagate(state):
        return "No Solution"

    sol = search(state)
    if sol is None:
        return "No Solution"

    path = extract_loop(sol)
    return path if path else "No Solution"


def build_graph(n):
    edges = {}
    edge_of = {}
    incident = {(r, c): {} for r in range(n + 1) for c in range(n + 1)}
    eid = 0

    def add_edge(a, b):
        nonlocal eid
        key = tuple(sorted((a, b)))
        edge_of[key] = eid
        edges[eid] = key
        (r1, c1), (r2, c2) = a, b
        if r2 == r1 + 1:
            incident[a]['D'] = eid
            incident[b]['U'] = eid
        elif r2 == r1 - 1:
            incident[a]['U'] = eid
            incident[b]['D'] = eid
        elif c2 == c1 + 1:
            incident[a]['R'] = eid
            incident[b]['L'] = eid
        elif c2 == c1 - 1:
            incident[a]['L'] = eid
            incident[b]['R'] = eid
        eid += 1

    for r in range(n + 1):
        for c in range(n):
            add_edge((r, c), (r, c + 1))
    for r in range(n):
        for c in range(n + 1):
            add_edge((r, c), (r + 1, c))

    return edges, edge_of, incident


def edge_id(edge_of, a, b):
    return edge_of[tuple(sorted((a, b)))]


def move(pos, d, k=1):
    return (pos[0] + DIRS[d][0] * k, pos[1] + DIRS[d][1] * k)


def in_bounds(n, pos):
    return 0 <= pos[0] <= n and 0 <= pos[1] <= n


def generate_patterns(n, pos, t, k, edge_of):
    r, c = pos
    patterns = []

    if t == 'W':
        orient_sets = [('L', 'R'), ('U', 'D')]
    else:
        orient_sets = [('U', 'R'), ('R', 'D'), ('D', 'L'), ('L', 'U')]

    for d1, d2 in orient_sets:
        for l1 in range(1, k):
            l2 = k - l1
            if feasible_len(n, pos, d1, l1) and feasible_len(n, pos, d2, l2):
                cons = {}
                if not add_segment_constraints(n, pos, d1, l1, edge_of, cons):
                    continue
                if not add_segment_constraints(n, pos, d2, l2, edge_of, cons):
                    continue
                if t == 'W':
                    for offd in set('UDLR') - {d1, d2}:
                        e = incident_edge_at(pos, offd, n, edge_of)
                        if e is not None and not add_cons(cons, e, 0):
                            break
                    else:
                        patterns.append(cons)
                else:
                    for offd in set('UDLR') - {d1, d2}:
                        e = incident_edge_at(pos, offd, n, edge_of)
                        if e is not None and not add_cons(cons, e, 0):
                            break
                    else:
                        patterns.append(cons)

    uniq = []
    seen = set()
    for p in patterns:
        key = tuple(sorted(p.items()))
        if key not in seen:
            seen.add(key)
            uniq.append(p)
    return uniq


def feasible_len(n, pos, d, L):
    end = move(pos, d, L)
    return in_bounds(n, end)


def incident_edge_at(pos, d, n, edge_of):
    q = move(pos, d, 1)
    if not in_bounds(n, q):
        return None
    return edge_id(edge_of, pos, q)


def add_cons(cons, eid, val):
    old = cons.get(eid, val)
    if old != val:
        return False
    cons[eid] = val
    return True


def add_segment_constraints(n, pos, d, L, edge_of, cons):
    prev = pos
    for i in range(1, L + 1):
        cur = move(pos, d, i)
        e = edge_id(edge_of, prev, cur)
        if not add_cons(cons, e, 1):
            return False
        prev = cur

    for i in range(1, L):
        v = move(pos, d, i)
        e_back = incident_edge_at(v, OPP[d], n, edge_of)
        e_fwd = incident_edge_at(v, d, n, edge_of)
        if e_back is not None and not add_cons(cons, e_back, 1):
            return False
        if e_fwd is not None and not add_cons(cons, e_fwd, 1):
            return False
        for pd in PERP[d]:
            e = incident_edge_at(v, pd, n, edge_of)
            if e is not None and not add_cons(cons, e, 0):
                return False

    end = move(pos, d, L)
    e_straight = incident_edge_at(end, d, n, edge_of)
    if e_straight is not None and not add_cons(cons, e_straight, 0):
        return False
    return True


def set_edge(state, eid, val):
    cur = state['edges'][eid]
    if cur == val:
        return True
    if cur != -1 and cur != val:
        return False
    state['edges'][eid] = val
    return True


def vertex_target(state, v):
    return 2 if v in state['clue_pos'] else None


def propagate(state):
    changed = True
    while changed:
        changed = False

        for v, inc in state['incident'].items():
            vals = [(d, eid, state['edges'][eid]) for d, eid in inc.items()]
            on = sum(1 for _, _, s in vals if s == 1)
            unk = [eid for _, eid, s in vals if s == -1]

            if v in state['clue_pos']:
                if on > 2 or on + len(unk) < 2:
                    return False
                if on == 2:
                    for eid in unk:
                        if state['edges'][eid] == -1:
                            if not set_edge(state, eid, 0):
                                return False
                            changed = True
                if on + len(unk) == 2:
                    for eid in unk:
                        if state['edges'][eid] == -1:
                            if not set_edge(state, eid, 1):
                                return False
                            changed = True
            else:
                if on > 2:
                    return False
                if on == 2:
                    for eid in unk:
                        if state['edges'][eid] == -1:
                            if not set_edge(state, eid, 0):
                                return False
                            changed = True
                if on == 1 and len(unk) == 0:
                    return False
                if on == 1 and len(unk) == 1:
                    if not set_edge(state, unk[0], 1):
                        return False
                    changed = True

        for (r, c), pats in list(state['patterns'].items()):
            newp = []
            for p in pats:
                ok = True
                for eid, val in p.items():
                    cur = state['edges'][eid]
                    if cur != -1 and cur != val:
                        ok = False
                        break
                if ok:
                    newp.append(p)
            if not newp:
                return False
            if len(newp) != len(pats):
                state['patterns'][(r, c)] = newp
                changed = True

            common = {}
            first = newp[0]
            for eid, val in first.items():
                same = True
                for p in newp[1:]:
                    if p.get(eid, None) != val:
                        same = False
                        break
                if same:
                    common[eid] = val
            for eid, val in common.items():
                if state['edges'][eid] == -1:
                    if not set_edge(state, eid, val):
                        return False
                    changed = True

        if not local_shape_checks(state):
            return False
        if not partial_cycle_check(state):
            return False

    return True


def local_shape_checks(state):
    for r, c, t, k in state['clues']:
        inc = state['incident'][(r, c)]
        dirs_on = {d for d, eid in inc.items() if state['edges'][eid] == 1}
        dirs_off = {d for d, eid in inc.items() if state['edges'][eid] == 0}

        if t == 'W':
            if len(dirs_on) == 2:
                if not ((dirs_on == {'L', 'R'}) or (dirs_on == {'U', 'D'})):
                    return False
            if {'L', 'R'} <= dirs_off and {'U', 'D'} <= dirs_off:
                return False
        else:
            if len(dirs_on) == 2:
                if dirs_on in ({'L', 'R'}, {'U', 'D'}):
                    return False
            if ({'L', 'R'} <= dirs_off) or ({'U', 'D'} <= dirs_off):
                return False
    return True


def partial_cycle_check(state):
    adj = {}
    active_vertices = set()
    for eid, s in state['edges'].items():
        if s == 1:
            a, b = state['edges_meta'][eid]
            adj.setdefault(a, []).append(b)
            adj.setdefault(b, []).append(a)
            active_vertices.add(a)
            active_vertices.add(b)

    seen = set()
    for v in active_vertices:
        if v in seen:
            continue
        stack = [v]
        comp = set()
        while stack:
            x = stack.pop()
            if x in seen:
                continue
            seen.add(x)
            comp.add(x)
            for y in adj.get(x, []):
                if y not in seen:
                    stack.append(y)

        deg2 = all(len(adj.get(x, [])) == 2 for x in comp)
        if deg2:
            all_clues = all(pos in comp for pos in state['clue_pos'])
            all_assigned = all(s != -1 for s in state['edges'].values())
            if not (all_clues and all_assigned):
                return False
    return True


def choose_branch(state):
    best = None

    for pos, pats in state['patterns'].items():
        if len(pats) > 1:
            score = len(pats)
            cand = ('pattern', pos, score)
            if best is None or score < best[2]:
                best = cand

    if best is not None and best[2] <= 3:
        return best

    edge_scores = []
    for eid, s in state['edges'].items():
        if s == -1:
            a, b = state['edges_meta'][eid]
            score = 0
            if a in state['clue_pos']:
                score += 2
            if b in state['clue_pos']:
                score += 2
            for pos, pats in state['patterns'].items():
                vals = {p.get(eid, None) for p in pats}
                if 1 in vals and 0 in vals:
                    score += 1
            edge_scores.append((-(score), eid))
    if edge_scores:
        edge_scores.sort()
        return ('edge', edge_scores[0][1], None)

    if best is not None:
        return best
    return None


def search(state):
    if all(s != -1 for s in state['edges'].values()):
        if final_check(state):
            return state
        return None

    branch = choose_branch(state)
    if branch is None:
        return state if final_check(state) else None

    if branch[0] == 'pattern':
        pos = branch[1]
        pats = state['patterns'][pos]
        pats = sorted(pats, key=lambda p: -sum(1 for v in p.values() if v == 1))
        for chosen in pats:
            ns = deepcopy(state)
            ns['patterns'][pos] = [chosen]
            if propagate(ns):
                out = search(ns)
                if out is not None:
                    return out
    else:
        eid = branch[1]
        for val in (1, 0):
            ns = deepcopy(state)
            if set_edge(ns, eid, val) and propagate(ns):
                out = search(ns)
                if out is not None:
                    return out
    return None


def final_check(state):
    for v, inc in state['incident'].items():
        on = sum(1 for eid in inc.values() if state['edges'][eid] == 1)
        if v in state['clue_pos']:
            if on != 2:
                return False
        else:
            if on not in (0, 2):
                return False

    for (r, c), pats in state['patterns'].items():
        ok = False
        for p in pats:
            if all(state['edges'][eid] == val for eid, val in p.items()):
                ok = True
                break
        if not ok:
            return False

    adj = {}
    active_vertices = set()
    for eid, s in state['edges'].items():
        if s == 1:
            a, b = state['edges_meta'][eid]
            adj.setdefault(a, []).append(b)
            adj.setdefault(b, []).append(a)
            active_vertices.add(a)
            active_vertices.add(b)

    if not active_vertices:
        return False
    if any(len(adj[v]) != 2 for v in active_vertices):
        return False
    if not all(pos in active_vertices for pos in state['clue_pos']):
        return False

    start = next(iter(active_vertices))
    seen = set()
    stack = [start]
    while stack:
        x = stack.pop()
        if x in seen:
            continue
        seen.add(x)
        for y in adj.get(x, []):
            if y not in seen:
                stack.append(y)

    return seen == active_vertices


def extract_loop(state):
    adj = {}
    for eid, s in state['edges'].items():
        if s == 1:
            a, b = state['edges_meta'][eid]
            adj.setdefault(a, []).append(b)
            adj.setdefault(b, []).append(a)
    if not adj:
        return None

    start = min(adj)
    path = [start]
    prev = None
    cur = start
    while True:
        nxts = adj[cur]
        if prev is None:
            nxt = min(nxts)
        else:
            if len(nxts) != 2:
                return None
            nxt = nxts[0] if nxts[1] == prev else nxts[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break

    used = set()
    for i in range(len(path) - 1):
        used.add(tuple(sorted((path[i], path[i + 1]))))
    active = {
        tuple(sorted((a, b)))
        for a, nbrs in adj.items()
        for b in nbrs
        if a < b
    }
    if used != active:
        return None
    return path


