OBSERVATION = {'data': [[0, 1, 1, 1, 1, 2, 2, 2], [0, 0, 1, 3, 1, 2, 2, 2], [0, 1, 1, 3, 3, 3, 4, 2], [0, 0, 0, 5, 3, 6, 4, 2], [7, 7, 0, 5, 5, 6, 6, 2], [7, 0, 0, 5, 5, 5, 6, 2], [7, 7, 8, 8, 8, 6, 6, 2], [8, 8, 8, 8, 8, 6, 6, 6]]}

# Generalized LITS solver.
# It converts regions into candidate tetromino placements, applies deduction-heavy
# propagation, and then uses tightly-pruned search.

from collections import defaultdict, deque

# Base tetrominoes as coordinates
BASE_SHAPES = {
    'I': {(0, 0), (1, 0), (2, 0), (3, 0)},
    'L': {(0, 0), (1, 0), (2, 0), (2, 1)},
    'T': {(0, 0), (0, 1), (0, 2), (1, 1)},
    'S': {(0, 1), (0, 2), (1, 0), (1, 1)},
}


def norm_shape(cells):
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return frozenset((r - min_r, c - min_c) for r, c in cells)


def transforms(cells):
    pts = list(cells)
    out = set()
    for rf in (1, -1):
        for cf in (1, -1):
            for swap in (0, 1):
                cur = []
                for r, c in pts:
                    rr, cc = r * rf, c * cf
                    if swap:
                        rr, cc = cc, rr
                    cur.append((rr, cc))
                out.add(norm_shape(cur))
    return out


ORIENTED_BY_TYPE = {}
ALL_SHAPES_CANON = {}
for t, cells in BASE_SHAPES.items():
    ori = sorted(transforms(cells), key=lambda s: sorted(s))
    ORIENTED_BY_TYPE[t] = ori
    for s in ori:
        ALL_SHAPES_CANON[s] = t


def solve(observation):
    grid = observation['data']
    n = len(grid)
    m = len(grid[0]) if n else 0
    if n == 0 or m == 0:
        return "No Solution"

    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            region_cells[grid[r][c]].append((r, c))
    regions = sorted(region_cells)
    ridx = {rid: i for i, rid in enumerate(regions)}
    R = len(regions)

    # Region adjacency
    region_adj = [set() for _ in range(R)]
    for r in range(n):
        for c in range(m):
            a = ridx[grid[r][c]]
            if r + 1 < n and grid[r + 1][c] != grid[r][c]:
                b = ridx[grid[r + 1][c]]
                region_adj[a].add(b)
                region_adj[b].add(a)
            if c + 1 < m and grid[r][c + 1] != grid[r][c]:
                b = ridx[grid[r][c + 1]]
                region_adj[a].add(b)
                region_adj[b].add(a)

    # Cell indexing
    cell_id = {(r, c): r * m + c for r in range(n) for c in range(m)}
    id_cell = [(r, c) for r in range(n) for c in range(m)]

    # 4-neighbors for connectivity
    nbrs = [[] for _ in range(n * m)]
    for r in range(n):
        for c in range(m):
            u = cell_id[(r, c)]
            if r > 0:
                nbrs[u].append(cell_id[(r - 1, c)])
            if r + 1 < n:
                nbrs[u].append(cell_id[(r + 1, c)])
            if c > 0:
                nbrs[u].append(cell_id[(r, c - 1)])
            if c + 1 < m:
                nbrs[u].append(cell_id[(r, c + 1)])

    # 2x2 blocks
    blocks = []
    cell_to_blocks = [[] for _ in range(n * m)]
    for r in range(n - 1):
        for c in range(m - 1):
            b = [cell_id[(r, c)], cell_id[(r + 1, c)], cell_id[(r, c + 1)], cell_id[(r + 1, c + 1)]]
            bi = len(blocks)
            blocks.append(tuple(b))
            for u in b:
                cell_to_blocks[u].append(bi)

    # Generate candidates per region
    candidates = []
    cand_by_region = [[] for _ in range(R)]
    cell_to_region_cands = [defaultdict(list) for _ in range(R)]

    for rid in regions:
        i = ridx[rid]
        cells = set(region_cells[rid])
        seen = set()
        for t, orients in ORIENTED_BY_TYPE.items():
            for shape in orients:
                h = max(r for r, c in shape) + 1
                w = max(c for r, c in shape) + 1
                min_rr = min(r for r, c in cells)
                max_rr = max(r for r, c in cells)
                min_cc = min(c for r, c in cells)
                max_cc = max(c for r, c in cells)
                for br in range(min_rr - h + 1, max_rr + 1):
                    for bc in range(min_cc - w + 1, max_cc + 1):
                        placed = frozenset((br + r, bc + c) for r, c in shape)
                        if placed.issubset(cells) and placed not in seen:
                            seen.add(placed)
                            mask = frozenset(cell_id[x] for x in placed)
                            ci = len(candidates)
                            candidates.append({
                                'region': i,
                                'type': t,
                                'cells': mask,
                            })
                            cand_by_region[i].append(ci)
                            for u in mask:
                                cell_to_region_cands[i][u].append(ci)

    if any(not cand_by_region[i] for i in range(R)):
        return "No Solution"

    # Precompute candidate conflicts with 2x2 possibility only at candidate level later
    cand_type = [c['type'] for c in candidates]
    cand_region = [c['region'] for c in candidates]
    cand_cells = [c['cells'] for c in candidates]

    # Region-neighbor same-type conflicts by candidate
    same_type_neighbor_conflicts = [set() for _ in range(len(candidates))]
    for i in range(R):
        for j in region_adj[i]:
            if i < j:
                for a in cand_by_region[i]:
                    ta = cand_type[a]
                    for b in cand_by_region[j]:
                        if cand_type[b] == ta:
                            same_type_neighbor_conflicts[a].add(b)
                            same_type_neighbor_conflicts[b].add(a)

    # Initial domains
    domains = [set(lst) for lst in cand_by_region]
    assigned = [None] * R

    # Useful helpers
    def possible_cells(domains_local, assigned_local):
        out = set()
        for i in range(R):
            if assigned_local[i] is not None:
                out |= cand_cells[assigned_local[i]]
            else:
                for ci in domains_local[i]:
                    out |= cand_cells[ci]
        return out

    def definite_cells(assigned_local):
        out = set()
        for i in range(R):
            if assigned_local[i] is not None:
                out |= cand_cells[assigned_local[i]]
        return out

    def filter_region_by_local_constraints(i, domains_local, assigned_local):
        fixed = definite_cells(assigned_local)
        keep = set()
        for ci in domains_local[i]:
            cells = cand_cells[ci]
            ok = True

            # Same-type across adjacent regions
            t = cand_type[ci]
            for j in region_adj[i]:
                if assigned_local[j] is not None and cand_type[assigned_local[j]] == t:
                    ok = False
                    break
            if not ok:
                continue

            # 2x2 fully shaded with already fixed cells
            for u in cells:
                for bi in cell_to_blocks[u]:
                    block = blocks[bi]
                    cnt = 0
                    for v in block:
                        if v in fixed or v in cells:
                            cnt += 1
                    if cnt == 4:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                keep.add(ci)
        return keep

    def enforce_arc_type(domains_local, assigned_local):
        changed = True
        while changed:
            changed = False
            for i in range(R):
                if assigned_local[i] is not None:
                    continue
                new_dom = filter_region_by_local_constraints(i, domains_local, assigned_local)
                if not new_dom:
                    return False
                if new_dom != domains_local[i]:
                    domains_local[i] = new_dom
                    changed = True

            # Hidden-single by cell coverage inside a region:
            # if a cell belongs to all remaining candidates, it becomes forced shaded;
            # if a type is only possible in one way, still left as singleton naturally.
            # Also use pairwise contradiction on assigned-like propagation.
            progress = True
            while progress:
                progress = False
                for i in range(R):
                    if assigned_local[i] is not None:
                        continue
                    if len(domains_local[i]) == 1:
                        ci = next(iter(domains_local[i]))
                        assigned_local[i] = ci
                        domains_local[i] = {ci}
                        changed = True
                        progress = True
                if progress:
                    for i in range(R):
                        if assigned_local[i] is not None:
                            continue
                        new_dom = filter_region_by_local_constraints(i, domains_local, assigned_local)
                        if not new_dom:
                            return False
                        if new_dom != domains_local[i]:
                            domains_local[i] = new_dom
                            changed = True

            # Adjacency-type support pruning
            for i in range(R):
                if assigned_local[i] is not None:
                    continue
                remove = set()
                for ci in domains_local[i]:
                    t = cand_type[ci]
                    supported = True
                    for j in region_adj[i]:
                        if assigned_local[j] is not None:
                            if cand_type[assigned_local[j]] == t:
                                supported = False
                                break
                        else:
                            if not any(cand_type[cj] != t for cj in domains_local[j]):
                                supported = False
                                break
                    if not supported:
                        remove.add(ci)
                if remove:
                    nd = domains_local[i] - remove
                    if not nd:
                        return False
                    domains_local[i] = nd
                    changed = True

            # 2x2 "all four must become shaded" impossibility pruning
            fixed = definite_cells(assigned_local)
            poss = possible_cells(domains_local, assigned_local)
            for block in blocks:
                if all(v in fixed for v in block):
                    return False
                if all(v in poss for v in block):
                    # If three are fixed and fourth possible only, that fourth cannot remain forced-by-all.
                    if sum(v in fixed for v in block) == 3:
                        missing = next(v for v in block if v not in fixed)
                        rr = grid[id_cell[missing][0]][id_cell[missing][1]]
                        i = ridx[rr]
                        if assigned_local[i] is None:
                            nd = {ci for ci in domains_local[i] if missing not in cand_cells[ci]}
                            if nd:
                                domains_local[i] = nd
                                changed = True
                            else:
                                return False

            # Connectivity feasibility on possible shaded cells
            if not connectivity_feasible(domains_local, assigned_local):
                return False

        return True

    def connectivity_feasible(domains_local, assigned_local):
        fixed = definite_cells(assigned_local)
        if not fixed:
            return True
        poss = possible_cells(domains_local, assigned_local)
        start = next(iter(fixed))
        dq = deque([start])
        seen = {start}
        while dq:
            u = dq.popleft()
            for v in nbrs[u]:
                if v in poss and v not in seen:
                    seen.add(v)
                    dq.append(v)
        return fixed <= seen

    def final_connected(assigned_local):
        all_cells = definite_cells(assigned_local)
        if not all_cells:
            return False
        start = next(iter(all_cells))
        dq = deque([start])
        seen = {start}
        while dq:
            u = dq.popleft()
            for v in nbrs[u]:
                if v in all_cells and v not in seen:
                    seen.add(v)
                    dq.append(v)
        return seen == all_cells

    def no_full_2x2(assigned_local):
        fixed = definite_cells(assigned_local)
        for block in blocks:
            if all(v in fixed for v in block):
                return False
        return True

    def choose_region(domains_local, assigned_local):
        best = None
        best_key = None
        for i in range(R):
            if assigned_local[i] is None:
                dom = domains_local[i]
                # Human-like: smallest domain first; tie by strongest interaction
                impact = 0
                for ci in dom:
                    impact += len(cand_cells[ci])
                    impact += len(region_adj[i])
                key = (len(dom), -impact, i)
                if best_key is None or key < best_key:
                    best_key = key
                    best = i
        return best

    def search(domains_local, assigned_local):
        if not enforce_arc_type(domains_local, assigned_local):
            return None

        if all(a is not None for a in assigned_local):
            if no_full_2x2(assigned_local) and final_connected(assigned_local):
                return assigned_local
            return None

        i = choose_region(domains_local, assigned_local)
        if i is None:
            return None

        # Prefer candidates that maximize immediate compatibility and connectivity
        poss_all = possible_cells(domains_local, assigned_local)
        fixed = definite_cells(assigned_local)

        ordered = []
        for ci in domains_local[i]:
            score = 0
            cells = cand_cells[ci]
            t = cand_type[ci]

            # More contact with fixed cells is better for connectivity
            if fixed:
                for u in cells:
                    score += sum(1 for v in nbrs[u] if v in fixed) * 10

            # Fewer 2x2 risks
            risk = 0
            for u in cells:
                for bi in cell_to_blocks[u]:
                    block = blocks[bi]
                    if sum(v in fixed or v in cells for v in block) == 4:
                        risk += 100
            score -= risk

            # Favor candidates leaving neighbors type options
            for j in region_adj[i]:
                if assigned_local[j] is None:
                    score += sum(1 for cj in domains_local[j] if cand_type[cj] != t)
            ordered.append((-score, ci))
        ordered.sort()

        for _, ci in ordered:
            new_domains = [set(d) for d in domains_local]
            new_assigned = assigned_local[:]
            new_assigned[i] = ci
            new_domains[i] = {ci}

            # Immediate region-neighbor same-type pruning
            t = cand_type[ci]
            consistent = True
            for j in region_adj[i]:
                if new_assigned[j] is None:
                    nd = {cj for cj in new_domains[j] if cand_type[cj] != t}
                    if not nd:
                        consistent = False
                        break
                    new_domains[j] = nd
                elif cand_type[new_assigned[j]] == t:
                    consistent = False
                    break
            if not consistent:
                continue

            # Immediate 2x2 pruning for impacted regions
            fixed2 = definite_cells(new_assigned)
            bad = False
            for block in blocks:
                if all(v in fixed2 for v in block):
                    bad = True
                    break
            if bad:
                continue

            ans = search(new_domains, new_assigned)
            if ans is not None:
                return ans
        return None

    result = search(domains, assigned)
    if result is None:
        return "No Solution"

    out = [[None for _ in range(m)] for _ in range(n)]
    for ci in result:
        t = cand_type[ci]
        for u in cand_cells[ci]:
            r, c = id_cell[u]
            out[r][c] = t
    return repr(out)


