OBSERVATION = {'data': [['B3', None, None, 'B5', 'W2', None], [None, None, None, None, 'B3', None], ['B2', None, None, None, None, None], [None, None, None, None, None, None], [None, 'B2', None, 'B2', None, 'B2'], ['B3', None, None, None, None, None]]}

# Generalized solver for the described loop puzzle.
# It uses:
# - vertex-state CSP (empty / straight / turn)
# - arc consistency on every grid edge
# - clue-specific ray-length support filtering
# - backtracking with smallest-domain branching
# - final exact validation and loop extraction

DIRS = {
    'U': (-1, 0),
    'D': (1, 0),
    'L': (0, -1),
    'R': (0, 1),
}
OPP = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}

STATE_DIRS = [
    frozenset(),                 # 0: empty
    frozenset(('L', 'R')),       # 1: horizontal
    frozenset(('U', 'D')),       # 2: vertical
    frozenset(('U', 'R')),       # 3
    frozenset(('U', 'L')),       # 4
    frozenset(('D', 'R')),       # 5
    frozenset(('D', 'L')),       # 6
]

STRAIGHT_STATE_FOR_DIR = {
    'L': 1, 'R': 1,
    'U': 2, 'D': 2,
}

TURN_STATES_WITH_INCOMING = {
    'U': {5, 6},  # endpoint reached from above, incoming at endpoint is U? No: if traveling D, incoming uses U.
    'D': {3, 4},
    'L': {3, 5},
    'R': {4, 6},
}

def state_name(i):
    return ["E", "H", "V", "UR", "UL", "DR", "DL"][i]

def bit_count(x):
    return x.bit_count()

def iter_bits(mask):
    while mask:
        b = mask & -mask
        yield (b.bit_length() - 1)
        mask ^= b

ALL_STATES_MASK = (1 << len(STATE_DIRS)) - 1

def in_bounds(n, r, c):
    return 0 <= r <= n and 0 <= c <= n

def move(pos, d):
    r, c = pos
    dr, dc = DIRS[d]
    return r + dr, c + dc

def edge_positions(n):
    for r in range(n + 1):
        for c in range(n + 1):
            for d in ('R', 'D'):
                nr, nc = move((r, c), d)
                if in_bounds(n, nr, nc):
                    yield (r, c), d, (nr, nc)

def build_neighbors(n):
    nbrs = {}
    for r in range(n + 1):
        for c in range(n + 1):
            ds = {}
            for d in DIRS:
                nr, nc = move((r, c), d)
                if in_bounds(n, nr, nc):
                    ds[d] = (nr, nc)
            nbrs[(r, c)] = ds
    return nbrs

def parse_observation(observation):
    data = observation['data']
    n = len(data) - 1
    clues = {}
    for r in range(n + 1):
        for c in range(n + 1):
            tok = data[r][c]
            if tok is not None:
                clues[(r, c)] = (tok[0], int(tok[1:]))
    return n, clues

def initial_domains(n, clues, nbrs):
    domains = {}
    for r in range(n + 1):
        for c in range(n + 1):
            pos = (r, c)
            allowed = 0
            for s, dirs in enumerate(STATE_DIRS):
                ok = True
                for d in dirs:
                    if d not in nbrs[pos]:
                        ok = False
                        break
                if not ok:
                    continue
                if pos in clues:
                    kind, _ = clues[pos]
                    if kind == 'W':
                        if s not in (1, 2):
                            continue
                    else:
                        if s not in (3, 4, 5, 6):
                            continue
                allowed |= (1 << s)
            domains[pos] = allowed
    return domains

def compatible(mask_a, d, mask_b):
    opp = OPP[d]
    for sa in iter_bits(mask_a):
        a_on = d in STATE_DIRS[sa]
        found = False
        for sb in iter_bits(mask_b):
            b_on = opp in STATE_DIRS[sb]
            if a_on == b_on:
                found = True
                break
        if not found:
            return False
    return True

def filter_arc(domains, a, d, b):
    mask_a = domains[a]
    mask_b = domains[b]
    opp = OPP[d]
    new_mask = 0
    for sa in iter_bits(mask_a):
        a_on = d in STATE_DIRS[sa]
        for sb in iter_bits(mask_b):
            b_on = opp in STATE_DIRS[sb]
            if a_on == b_on:
                new_mask |= (1 << sa)
                break
    if new_mask != mask_a:
        domains[a] = new_mask
        return True
    return False

def ray_possible_lengths(n, domains, start, d):
    lengths = []
    pos = start
    t = 0
    while True:
        if d not in build_neighbors_cache[n][pos]:
            break
        pos = build_neighbors_cache[n][pos][d]
        t += 1

        good = True
        # Intermediate vertices must be straight along the same axis.
        temp = start
        for _ in range(1, t):
            temp = build_neighbors_cache[n][temp][d]
            needed_state = STRAIGHT_STATE_FOR_DIR[d]
            if not (domains[temp] & (1 << needed_state)):
                good = False
                break
        if not good:
            break

        incoming_at_endpoint = OPP[d]
        endpoint_mask = 0
        for s in TURN_STATES_WITH_INCOMING[incoming_at_endpoint]:
            endpoint_mask |= (1 << s)
        if domains[pos] & endpoint_mask:
            lengths.append(t)
    return lengths

def clue_state_supported(n, domains, pos, s, clue):
    dirs = tuple(STATE_DIRS[s])
    if len(dirs) != 2:
        return False
    kind, k = clue
    if kind == 'W':
        # Straight only.
        if s not in (1, 2):
            return False
    else:
        if s not in (3, 4, 5, 6):
            return False

    l1 = ray_possible_lengths(n, domains, pos, dirs[0])
    l2 = ray_possible_lengths(n, domains, pos, dirs[1])
    if not l1 or not l2:
        return False

    set2 = set(l2)
    for a in l1:
        if k - a in set2:
            return True
    return False

def filter_clue(domains, pos, clue, n):
    mask = domains[pos]
    new_mask = 0
    for s in iter_bits(mask):
        if clue_state_supported(n, domains, pos, s, clue):
            new_mask |= (1 << s)
    if new_mask != mask:
        domains[pos] = new_mask
        return True
    return False

def propagate(domains, n, clues):
    nbrs = build_neighbors_cache[n]
    changed = True
    while changed:
        changed = False

        # Edge arc consistency.
        for a in domains:
            for d, b in nbrs[a].items():
                if filter_arc(domains, a, d, b):
                    if domains[a] == 0:
                        return False
                    changed = True

        # Clue support filtering.
        for pos, clue in clues.items():
            if filter_clue(domains, pos, clue, n):
                if domains[pos] == 0:
                    return False
                changed = True

        # Local "must connect in pairs" consequence at each vertex:
        # already encoded by states; here we only check non-contradiction from neighbors.
        for pos, mask in domains.items():
            if mask == 0:
                return False

        # Optional early dead-cycle pruning on forced assignments.
        if not partial_cycle_check(domains, n, clues):
            return False

    return True

def partial_cycle_check(domains, n, clues):
    # Build graph of forced-on edges only.
    forced_adj = {}
    all_positions = list(domains.keys())
    for p in all_positions:
        forced_adj[p] = set()

    for a, d, b in edge_positions(n):
        ma = domains[a]
        mb = domains[b]

        a_all_on = all(d in STATE_DIRS[s] for s in iter_bits(ma))
        a_all_off = all(d not in STATE_DIRS[s] for s in iter_bits(ma))
        b_all_on = all(OPP[d] in STATE_DIRS[s] for s in iter_bits(mb))
        b_all_off = all(OPP[d] not in STATE_DIRS[s] for s in iter_bits(mb))

        if a_all_on and b_all_on:
            forced_adj[a].add(b)
            forced_adj[b].add(a)
        elif a_all_off and b_all_off:
            pass
        elif (a_all_on and b_all_off) or (a_all_off and b_all_on):
            return False

    # If a completed forced cycle exists and cannot grow, it must contain all clue vertices that are forced non-empty.
    seen = set()
    for p in all_positions:
        if p in seen or not forced_adj[p]:
            continue
        comp = []
        stack = [p]
        seen.add(p)
        while stack:
            x = stack.pop()
            comp.append(x)
            for y in forced_adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)

        closed = True
        for x in comp:
            deg_forced = len(forced_adj[x])
            if deg_forced not in (0, 2):
                closed = False
                break
            if deg_forced == 2:
                # Could still expand if some non-forced incident edge remains possible.
                possible_extra = 0
                for d, y in build_neighbors_cache[n][x].items():
                    mx = domains[x]
                    if any(d in STATE_DIRS[s] for s in iter_bits(mx)):
                        possible_extra += 1
                if possible_extra > 2:
                    closed = False
                    break
            else:
                closed = False
                break

        if closed:
            comp_set = set(comp)
            for clue_pos in clues:
                if clue_pos not in comp_set:
                    # If clue is forced non-empty outside this cycle, invalid.
                    if all(s != 0 for s in iter_bits(domains[clue_pos])):
                        return False
    return True

def choose_var(domains, clues):
    best = None
    best_key = None
    for pos, mask in domains.items():
        bc = bit_count(mask)
        if bc <= 1:
            continue
        clue_bonus = 0 if pos in clues else 1
        size = bc
        key = (clue_bonus, size, pos[0], pos[1])
        if best_key is None or key < best_key:
            best_key = key
            best = pos
    return best

def state_order(pos, mask, clues):
    vals = list(iter_bits(mask))
    if pos in clues:
        return vals
    # Prefer empty later; visited states first often helps connect clue structure.
    vals.sort(key=lambda s: (s == 0, s))
    return vals

def deep_copy_domains(domains):
    return dict(domains)

def search(domains, n, clues):
    if not propagate(domains, n, clues):
        return None
    var = choose_var(domains, clues)
    if var is None:
        if final_check(domains, n, clues):
            return domains
        return None

    mask = domains[var]
    for s in state_order(var, mask, clues):
        new_domains = deep_copy_domains(domains)
        new_domains[var] = (1 << s)
        res = search(new_domains, n, clues)
        if res is not None:
            return res
    return None

def chosen_state(domains, pos):
    mask = domains[pos]
    if bit_count(mask) != 1:
        return None
    return next(iter_bits(mask))

def build_selected_graph(domains, n):
    adj = {(r, c): set() for r in range(n + 1) for c in range(n + 1)}
    for a, d, b in edge_positions(n):
        sa = chosen_state(domains, a)
        sb = chosen_state(domains, b)
        if sa is None or sb is None:
            return None
        aon = d in STATE_DIRS[sa]
        bon = OPP[d] in STATE_DIRS[sb]
        if aon != bon:
            return None
        if aon:
            adj[a].add(b)
            adj[b].add(a)
    return adj

def actual_ray_length(selected, n, start, d):
    pos = start
    t = 0
    while d in build_neighbors_cache[n][pos]:
        nxt = build_neighbors_cache[n][pos][d]
        if nxt not in selected[pos]:
            return None
        pos = nxt
        t += 1
        st = selected_state_cache[pos]
        if st in (1, 2):
            needed = STRAIGHT_STATE_FOR_DIR[d]
            if st != needed:
                return None
            continue
        if st in (3, 4, 5, 6):
            incoming = OPP[d]
            if incoming in STATE_DIRS[st]:
                return t
            return None
        return None
    return None

def final_check(domains, n, clues):
    global selected_state_cache
    adj = build_selected_graph(domains, n)
    if adj is None:
        return False

    visited_vertices = [p for p, ns in adj.items() if ns]
    for p, ns in adj.items():
        deg = len(ns)
        if deg not in (0, 2):
            return False
        if p in clues and deg != 2:
            return False

    if not visited_vertices:
        return False

    # Single cycle.
    start = visited_vertices[0]
    seen = set()
    stack = [start]
    while stack:
        x = stack.pop()
        if x in seen:
            continue
        seen.add(x)
        stack.extend(adj[x] - seen)
    if len(seen) != len(visited_vertices):
        return False

    # Cache selected states for ray checks.
    selected_state_cache = {}
    for pos in domains:
        selected_state_cache[pos] = chosen_state(domains, pos)

    selected = adj
    for pos, (kind, k) in clues.items():
        s = selected_state_cache[pos]
        if kind == 'W' and s not in (1, 2):
            return False
        if kind == 'B' and s not in (3, 4, 5, 6):
            return False
        dirs = tuple(STATE_DIRS[s])
        a = actual_ray_length(selected, n, pos, dirs[0])
        b = actual_ray_length(selected, n, pos, dirs[1])
        if a is None or b is None or a + b != k:
            return False

    return True

def extract_loop(domains, n):
    adj = build_selected_graph(domains, n)
    start = None
    for p in sorted(adj):
        if adj[p]:
            start = p
            break
    if start is None:
        return []

    path = [start]
    prev = None
    cur = start
    while True:
        nbrs = sorted(adj[cur])
        nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
    return path

def solve(observation):
    n, clues = parse_observation(observation)
    global build_neighbors_cache
    build_neighbors_cache = {n: build_neighbors(n)}

    domains = initial_domains(n, clues, build_neighbors_cache[n])
    result = search(domains, n, clues)
    if result is None:
        return "No Solution"
    return extract_loop(result, n)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 1, 1, 1, 2], [0, 0, 0, 3, 3, 2], [0, 4, 0, 0, 3, 3], [4, 4, 5, 5, 7, 3], [4, 5, 5, 6, 7, 3], [4, 4, 5, 6, 7, 7]]}

from collections import defaultdict

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0

    cells = [(r, c) for r in range(n) for c in range(m)]
    cell_index = {rc: i for i, rc in enumerate(cells)}

    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            region_cells[grid[r][c]].append((r, c))
    regions = sorted(region_cells)
    ridx = {rid: i for i, rid in enumerate(regions)}
    R = len(regions)

    # Domino candidates: every orthogonally adjacent pair.
    dominos = []
    for r in range(n):
        for c in range(m):
            if r + 1 < n:
                dominos.append(((r, c), (r + 1, c)))
            if c + 1 < m:
                dominos.append(((r, c), (r, c + 1)))
    D = len(dominos)

    domino_cells_mask = [0] * D
    domino_region_contrib = [[0] * R for _ in range(D)]
    cell_to_dominos = defaultdict(list)
    region_touch_mask = [0] * R

    for i, (a, b) in enumerate(dominos):
        ai = cell_index[a]
        bi = cell_index[b]
        domino_cells_mask[i] = (1 << ai) | (1 << bi)

        ra = ridx[grid[a[0]][a[1]]]
        rb = ridx[grid[b[0]][b[1]]]
        domino_region_contrib[i][ra] += 1
        domino_region_contrib[i][rb] += 1

        for rr in range(R):
            if domino_region_contrib[i][rr]:
                region_touch_mask[rr] |= (1 << i)

        cell_to_dominos[a].append(i)
        cell_to_dominos[b].append(i)

    # Conflict graph: shared cell or orthogonal touching between different dominoes.
    cell_neighbors = {}
    for r in range(n):
        for c in range(m):
            s = set()
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    s.add((nr, nc))
            cell_neighbors[(r, c)] = s

    conflict = [0] * D
    domino_cell_sets = [set(d) for d in dominos]
    for i in range(D):
        ci = domino_cell_sets[i]
        touch_i = set(ci)
        for x in ci:
            touch_i |= cell_neighbors[x]
        for j in range(i + 1, D):
            cj = domino_cell_sets[j]
            if ci & cj:
                conflict[i] |= 1 << j
                conflict[j] |= 1 << i
            else:
                bad = False
                for x in cj:
                    if x in touch_i:
                        bad = True
                        break
                if bad:
                    conflict[i] |= 1 << j
                    conflict[j] |= 1 << i

    all_dominos_mask = (1 << D) - 1

    # Precompute region contribution classes.
    region_contrib1 = [0] * R
    region_contrib2 = [0] * R
    for r in range(R):
        m1 = 0
        m2 = 0
        for i in range(D):
            v = domino_region_contrib[i][r]
            if v == 1:
                m1 |= 1 << i
            elif v == 2:
                m2 |= 1 << i
        region_contrib1[r] = m1
        region_contrib2[r] = m2

    def bit_iter(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length() - 1
            mask ^= b

    def region_have(selected_mask):
        have = [0] * R
        sm = selected_mask
        while sm:
            b = sm & -sm
            i = b.bit_length() - 1
            sm ^= b
            contrib = domino_region_contrib[i]
            for r in range(R):
                if contrib[r]:
                    have[r] += contrib[r]
        return have

    def upper_region_capacity(active_mask, have):
        # Maximum additional cells per region available from currently active dominoes.
        cap = [0] * R
        am = active_mask
        while am:
            b = am & -am
            i = b.bit_length() - 1
            am ^= b
            contrib = domino_region_contrib[i]
            for r in range(R):
                if contrib[r]:
                    cap[r] += contrib[r]
        return [have[r] + cap[r] for r in range(R)]

    def feasible_patterns_for_region(r, selected_mask, banned_mask, have):
        rem = 2 - have[r]
        if rem < 0:
            return None
        active = all_dominos_mask & ~selected_mask & ~banned_mask
        cand = active & region_touch_mask[r]

        if rem == 0:
            return [0]

        patterns = []

        if rem == 1:
            singles = cand & region_contrib1[r]
            for i in bit_iter(singles):
                patterns.append(1 << i)

        elif rem == 2:
            singles = cand & region_contrib2[r]
            for i in bit_iter(singles):
                patterns.append(1 << i)

            ones = list(bit_iter(cand & region_contrib1[r]))
            L = len(ones)
            for a in range(L):
                i = ones[a]
                mi = 1 << i
                for b in range(a + 1, L):
                    j = ones[b]
                    if not (conflict[i] & (1 << j)):
                        patterns.append(mi | (1 << j))

        if not patterns:
            return []

        # Remove duplicates if any.
        out = []
        seen = set()
        for p in patterns:
            if p not in seen:
                seen.add(p)
                out.append(p)
        return out

    def propagate(selected_mask, banned_mask):
        while True:
            changed = False

            # Selecting a domino immediately bans all conflicting dominos.
            sm = selected_mask
            forced_ban = 0
            while sm:
                b = sm & -sm
                i = b.bit_length() - 1
                sm ^= b
                forced_ban |= conflict[i]
            new_banned = banned_mask | (forced_ban & ~selected_mask)
            if new_banned != banned_mask:
                if new_banned & selected_mask:
                    return None
                banned_mask = new_banned
                changed = True

            have = region_have(selected_mask)
            active_mask = all_dominos_mask & ~selected_mask & ~banned_mask

            # Basic region bounds.
            max_possible = upper_region_capacity(active_mask, have)
            for r in range(R):
                if have[r] > 2 or max_possible[r] < 2:
                    return None

            # Human-like region deductions.
            for r in range(R):
                pats = feasible_patterns_for_region(r, selected_mask, banned_mask, have)
                if pats is None or len(pats) == 0:
                    return None

                active_touch = active_mask & region_touch_mask[r]

                if len(pats) == 1:
                    p = pats[0]
                    add_sel = p & ~selected_mask
                    add_ban = active_touch & ~p
                    if add_sel:
                        if add_sel & banned_mask:
                            return None
                        selected_mask |= add_sel
                        changed = True
                    if add_ban:
                        banned_mask |= add_ban
                        changed = True
                    continue

                # Candidates absent from all feasible patterns can be banned.
                union_mask = 0
                inter_mask = None
                for p in pats:
                    union_mask |= p
                    inter_mask = p if inter_mask is None else (inter_mask & p)

                ban_mask = active_touch & ~union_mask
                sel_mask = 0 if inter_mask is None else (inter_mask & ~selected_mask)

                if ban_mask:
                    banned_mask |= ban_mask
                    changed = True
                if sel_mask:
                    if sel_mask & banned_mask:
                        return None
                    selected_mask |= sel_mask
                    changed = True

            if not changed:
                return selected_mask, banned_mask

    def score_branch_region(selected_mask, banned_mask):
        have = region_have(selected_mask)
        best = None
        best_pats = None
        for r in range(R):
            rem = 2 - have[r]
            if rem <= 0:
                continue
            pats = feasible_patterns_for_region(r, selected_mask, banned_mask, have)
            if not pats:
                return r, []
            if best is None or len(pats) < len(best_pats):
                best = r
                best_pats = pats
        return best, best_pats

    def dfs(selected_mask, banned_mask):
        state = propagate(selected_mask, banned_mask)
        if state is None:
            return None
        selected_mask, banned_mask = state

        have = region_have(selected_mask)
        if all(v == 2 for v in have):
            # Everything satisfied.
            return selected_mask

        r, pats = score_branch_region(selected_mask, banned_mask)
        if r is None:
            return selected_mask
        if not pats:
            return None

        # Prefer patterns that add more forced structure first.
        pats = sorted(pats, key=lambda p: (bin(p).count("1"), p))

        active_touch = (all_dominos_mask & ~selected_mask & ~banned_mask) & region_touch_mask[r]
        for p in pats:
            ns = selected_mask | p
            nb = banned_mask | (active_touch & ~p)
            ans = dfs(ns, nb)
            if ans is not None:
                return ans
        return None

    result = dfs(0, 0)
    if result is None:
        return "No Solution"

    out = [[None for _ in range(m)] for _ in range(n)]
    rm = result
    while rm:
        b = rm & -rm
        i = b.bit_length() - 1
        rm ^= b
        (r1, c1), (r2, c2) = dominos[i]
        out[r1][c1] = 'S'
        out[r2][c2] = 'S'
    return str(out)

