# General Slitherlink solver with aggressive deduction + guided search.
# It is designed to mimic human-style propagation:
# - cell saturation / exhaustion
# - vertex degree feasibility
# - prevention of premature subloops
# - speculative branching on the most constrained edge

from collections import deque

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    solver = SlitherlinkSolver(data)
    if not solver.solve():
        return "No Solution"
    loop = solver.extract_loop()
    if loop is None:
        return "No Solution"
    return str(loop)


class SlitherlinkSolver:
    def __init__(self, clues):
        self.clues = clues
        self.n = len(clues)

        # Edge indexing:
        # horizontal edges: (r, c) for r in [0..n], c in [0..n-1]
        # vertical edges:   (r, c) for r in [0..n-1], c in [0..n]
        self.h_base = 0
        self.h_count = (self.n + 1) * self.n
        self.v_base = self.h_count
        self.v_count = self.n * (self.n + 1)
        self.E = self.h_count + self.v_count
        self.V = (self.n + 1) * (self.n + 1)

        self.edge_state = [-1] * self.E  # -1 unknown, 0 off, 1 on

        self.edge_endpoints = [None] * self.E
        self.edge_cells = [None] * self.E
        self.edge_vertices = [[] for _ in range(self.V)]
        self.cells_edges = [[None] * self.n for _ in range(self.n)]

        self.vertex_deg_on = [0] * self.V
        self.vertex_deg_off = [0] * self.V
        self.vertex_unknown = [0] * self.V

        self.cell_on = [[0] * self.n for _ in range(self.n)]
        self.cell_off = [[0] * self.n for _ in range(self.n)]
        self.cell_unknown = [[4] * self.n for _ in range(self.n)]

        self._build_topology()
        self._initialize_counts()

    def vid(self, r, c):
        return r * (self.n + 1) + c

    def hid(self, r, c):
        return self.h_base + r * self.n + c

    def vid_edge(self, r, c):
        return self.v_base + r * (self.n + 1) + c

    def _build_topology(self):
        n = self.n

        for r in range(n + 1):
            for c in range(n):
                e = self.hid(r, c)
                v1 = self.vid(r, c)
                v2 = self.vid(r, c + 1)
                self.edge_endpoints[e] = (v1, v2)
                cells = []
                if r > 0:
                    cells.append((r - 1, c))
                if r < n:
                    cells.append((r, c))
                self.edge_cells[e] = cells
                self.edge_vertices[v1].append(e)
                self.edge_vertices[v2].append(e)

        for r in range(n):
            for c in range(n + 1):
                e = self.vid_edge(r, c)
                v1 = self.vid(r, c)
                v2 = self.vid(r + 1, c)
                self.edge_endpoints[e] = (v1, v2)
                cells = []
                if c > 0:
                    cells.append((r, c - 1))
                if c < n:
                    cells.append((r, c))
                self.edge_cells[e] = cells
                self.edge_vertices[v1].append(e)
                self.edge_vertices[v2].append(e)

        for r in range(n):
            for c in range(n):
                self.cells_edges[r][c] = [
                    self.hid(r, c),         # top
                    self.hid(r + 1, c),     # bottom
                    self.vid_edge(r, c),    # left
                    self.vid_edge(r, c + 1) # right
                ]

    def _initialize_counts(self):
        for v in range(self.V):
            self.vertex_unknown[v] = len(self.edge_vertices[v])

    def solve(self):
        if not self._initial_pattern_rules():
            return False
        if not self._propagate():
            return False
        return self._search()

    def _initial_pattern_rules(self):
        # Human-like immediate clue patterns.
        n = self.n

        # Diagonal 3s in a 2x2 force the shared corner "turn" behavior via two outer edges at the corner cells.
        # Consecutive adjacent 3s force the three outer parallel edges on and the shared middle edge on/off implications.
        # We keep this conservative and only add always-valid direct edge facts.

        for r in range(n):
            for c in range(n):
                clue = self.clues[r][c]
                if clue is None:
                    continue

                # Corner 3: the two border edges touching that corner-cell corner must be on.
                if clue == 3:
                    if r == 0 and c == 0:
                        if not self._assign(self.hid(0, 0), 1): return False
                        if not self._assign(self.vid_edge(0, 0), 1): return False
                    if r == 0 and c == n - 1:
                        if not self._assign(self.hid(0, c), 1): return False
                        if not self._assign(self.vid_edge(0, n), 1): return False
                    if r == n - 1 and c == 0:
                        if not self._assign(self.hid(n, 0), 1): return False
                        if not self._assign(self.vid_edge(r, 0), 1): return False
                    if r == n - 1 and c == n - 1:
                        if not self._assign(self.hid(n, c), 1): return False
                        if not self._assign(self.vid_edge(r, n), 1): return False

        # Adjacent 3s: shared side must be on; the two outer parallel sides must be on.
        for r in range(n):
            for c in range(n - 1):
                if self.clues[r][c] == 3 and self.clues[r][c + 1] == 3:
                    if not self._assign(self.vid_edge(r, c + 1), 1): return False
                    if not self._assign(self.hid(r, c), 1): return False
                    if not self._assign(self.hid(r + 1, c), 1): return False
                    if not self._assign(self.hid(r, c + 1), 1): return False
                    if not self._assign(self.hid(r + 1, c + 1), 1): return False

        for r in range(n - 1):
            for c in range(n):
                if self.clues[r][c] == 3 and self.clues[r + 1][c] == 3:
                    if not self._assign(self.hid(r + 1, c), 1): return False
                    if not self._assign(self.vid_edge(r, c), 1): return False
                    if not self._assign(self.vid_edge(r, c + 1), 1): return False
                    if not self._assign(self.vid_edge(r + 1, c), 1): return False
                    if not self._assign(self.vid_edge(r + 1, c + 1), 1): return False

        return True

    def _trail_mark(self):
        return len(self._trail)

    def _undo(self, mark):
        while len(self._trail) > mark:
            kind, payload = self._trail.pop()
            if kind == 'edge':
                e, old = payload
                self.edge_state[e] = old
            elif kind == 'vertex':
                v, on, off, unk = payload
                self.vertex_deg_on[v] = on
                self.vertex_deg_off[v] = off
                self.vertex_unknown[v] = unk
            elif kind == 'cell':
                r, c, on, off, unk = payload
                self.cell_on[r][c] = on
                self.cell_off[r][c] = off
                self.cell_unknown[r][c] = unk

    def _assign(self, e, val):
        cur = self.edge_state[e]
        if cur == val:
            return True
        if cur != -1:
            return False

        self._trail.append(('edge', (e, cur)))
        self.edge_state[e] = val

        v1, v2 = self.edge_endpoints[e]
        for v in (v1, v2):
            self._trail.append(('vertex', (v, self.vertex_deg_on[v], self.vertex_deg_off[v], self.vertex_unknown[v])))
            self.vertex_unknown[v] -= 1
            if val == 1:
                self.vertex_deg_on[v] += 1
            else:
                self.vertex_deg_off[v] += 1

        for r, c in self.edge_cells[e]:
            self._trail.append(('cell', (r, c, self.cell_on[r][c], self.cell_off[r][c], self.cell_unknown[r][c])))
            self.cell_unknown[r][c] -= 1
            if val == 1:
                self.cell_on[r][c] += 1
            else:
                self.cell_off[r][c] += 1

        return True

    def _propagate(self):
        # Use a fixed-point loop over all cells/vertices and subloop checks.
        changed = True
        while changed:
            changed = False

            # Cell deductions
            for r in range(self.n):
                for c in range(self.n):
                    clue = self.clues[r][c]
                    if clue is None:
                        continue

                    on = self.cell_on[r][c]
                    unk = self.cell_unknown[r][c]

                    if on > clue or on + unk < clue:
                        return False

                    if unk:
                        edges = self.cells_edges[r][c]
                        if on == clue:
                            for e in edges:
                                if self.edge_state[e] == -1:
                                    if not self._assign(e, 0):
                                        return False
                                    changed = True
                        elif on + unk == clue:
                            for e in edges:
                                if self.edge_state[e] == -1:
                                    if not self._assign(e, 1):
                                        return False
                                    changed = True

            # Vertex deductions
            for v in range(self.V):
                on = self.vertex_deg_on[v]
                unk = self.vertex_unknown[v]

                # Degree must end at 0 or 2
                feasible_add = []
                for add in range(unk + 1):
                    final_deg = on + add
                    if final_deg in (0, 2):
                        feasible_add.append(add)

                if not feasible_add:
                    return False

                if unk:
                    if feasible_add == [0]:
                        for e in self.edge_vertices[v]:
                            if self.edge_state[e] == -1:
                                if not self._assign(e, 0):
                                    return False
                                changed = True
                    elif feasible_add == [unk]:
                        for e in self.edge_vertices[v]:
                            if self.edge_state[e] == -1:
                                if not self._assign(e, 1):
                                    return False
                                changed = True
                    elif unk == 1:
                        lone = None
                        for e in self.edge_vertices[v]:
                            if self.edge_state[e] == -1:
                                lone = e
                                break
                        need_on = (2 in [on + a for a in feasible_add] and 0 not in [on + a for a in feasible_add])
                        need_off = (0 in [on + a for a in feasible_add] and 2 not in [on + a for a in feasible_add])
                        if lone is not None:
                            if need_on:
                                if not self._assign(lone, 1):
                                    return False
                                changed = True
                            elif need_off:
                                if not self._assign(lone, 0):
                                    return False
                                changed = True

                if on > 2:
                    return False
                if on == 1 and unk == 0:
                    return False

            # Prevent premature loops
            if not self._prevent_subloops():
                return False

            # Global sanity: no closed component unless final single loop
            if not self._global_component_sanity():
                return False

        return True

    def _build_on_components(self):
        parent = list(range(self.V))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[rb] = ra

        on_edges = []
        for e, st in enumerate(self.edge_state):
            if st == 1:
                v1, v2 = self.edge_endpoints[e]
                union(v1, v2)
                on_edges.append(e)

        comps = {}
        for e in on_edges:
            v1, _ = self.edge_endpoints[e]
            r = find(v1)
            comps.setdefault(r, []).append(e)

        verts_in_comp = {}
        for v in range(self.V):
            if self.vertex_deg_on[v] > 0:
                r = find(v)
                verts_in_comp.setdefault(r, []).append(v)

        return parent, find, comps, verts_in_comp

    def _prevent_subloops(self):
        parent, find, comps, verts_in_comp = self._build_on_components()

        active_roots = set(verts_in_comp.keys())
        total_active_vertices = sum(len(vs) for vs in verts_in_comp.values())

        for e, st in enumerate(self.edge_state):
            if st != -1:
                continue
            v1, v2 = self.edge_endpoints[e]

            if self.vertex_deg_on[v1] == 1 and self.vertex_deg_on[v2] == 1:
                # If endpoints already connected by existing on-path, turning this on creates a cycle.
                if find(v1) == find(v2):
                    root = find(v1)
                    comp_vertices = len(verts_in_comp.get(root, []))
                    # Allow only if this would be the final loop using all active structure and no other undecided on-path extensions exist.
                    # Conservative, human-like rule: forbid closing a subloop before puzzle completion.
                    if comp_vertices < total_active_vertices or not self._would_complete_entire_puzzle_with_edge(e):
                        if not self._assign(e, 0):
                            return False
        return True

    def _would_complete_entire_puzzle_with_edge(self, edge_to_turn_on):
        # Check whether setting this edge on could immediately complete a valid final loop.
        mark = len(self._trail)
        if not self._assign(edge_to_turn_on, 1):
            return False
        ok = self._all_constraints_satisfied_if_complete()
        self._undo(mark)
        return ok

    def _all_constraints_satisfied_if_complete(self):
        # Every undecided edge must be safely off if final loop already formed.
        # Strong condition used only for subloop-avoidance exception.
        for r in range(self.n):
            for c in range(self.n):
                clue = self.clues[r][c]
                if clue is not None and self.cell_on[r][c] != clue:
                    return False
        for v in range(self.V):
            if self.vertex_deg_on[v] not in (0, 2):
                return False
            if self.vertex_unknown[v] != 0:
                return False
        return self._is_single_loop_complete()

    def _global_component_sanity(self):
        parent, find, comps, verts_in_comp = self._build_on_components()

        # If there is a fully closed component (all degree-2) while other on-edges exist elsewhere, contradiction.
        closed_roots = []
        for root, vs in verts_in_comp.items():
            if vs and all(self.vertex_deg_on[v] == 2 for v in vs):
                closed_roots.append(root)

        if len(closed_roots) >= 2:
            return False
        if len(closed_roots) == 1 and len(verts_in_comp) > 1:
            return False

        # If all edges decided, must be exactly one loop or no solution.
        if all(st != -1 for st in self.edge_state):
            return self._is_single_loop_complete()

        return True

    def _is_single_loop_complete(self):
        # All on-edges must form exactly one cycle.
        on_edges = [e for e, st in enumerate(self.edge_state) if st == 1]
        if not on_edges:
            return False

        for v in range(self.V):
            if self.vertex_deg_on[v] not in (0, 2):
                return False

        adj = [[] for _ in range(self.V)]
        active_vertices = set()
        for e in on_edges:
            a, b = self.edge_endpoints[e]
            adj[a].append(b)
            adj[b].append(a)
            active_vertices.add(a)
            active_vertices.add(b)

        start = next(iter(active_vertices))
        seen = set([start])
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    dq.append(y)

        return seen == active_vertices

    def _search(self):
        if all(st != -1 for st in self.edge_state):
            return self._is_single_loop_complete()

        e = self._choose_branch_edge()
        if e is None:
            return False

        for val in self._branch_order(e):
            self._trail = []
            mark = self._trail_mark()
            if self._assign(e, val) and self._propagate() and self._search():
                return True
            self._undo(mark)

        return False

    def _choose_branch_edge(self):
        # Most constrained edge: maximize pressure from clue cells + vertices.
        best = None
        best_score = None

        for e, st in enumerate(self.edge_state):
            if st != -1:
                continue

            score = 0
            v1, v2 = self.edge_endpoints[e]

            for v in (v1, v2):
                on = self.vertex_deg_on[v]
                unk = self.vertex_unknown[v]
                # More constrained if degree is close to completion.
                if on == 1:
                    score += 6
                if unk <= 2:
                    score += 4
                score += 3 - min(3, unk)

            for r, c in self.edge_cells[e]:
                clue = self.clues[r][c]
                if clue is not None:
                    need = clue - self.cell_on[r][c]
                    unk = self.cell_unknown[r][c]
                    score += 8
                    score += 4 - min(4, unk)
                    score += abs(2 * need - unk)

            if best is None or score > best_score:
                best = e
                best_score = score

        return best

    def _branch_order(self, e):
        # Heuristic preferred value from local clue pressure and path extension.
        on_bias = 0
        off_bias = 0

        v1, v2 = self.edge_endpoints[e]
        for v in (v1, v2):
            if self.vertex_deg_on[v] == 1:
                on_bias += 3
            elif self.vertex_deg_on[v] == 2:
                off_bias += 5

        for r, c in self.edge_cells[e]:
            clue = self.clues[r][c]
            if clue is None:
                continue
            need = clue - self.cell_on[r][c]
            unk = self.cell_unknown[r][c]
            if need == 0:
                off_bias += 8
            elif need == unk:
                on_bias += 8
            elif need * 2 > unk:
                on_bias += 2
            else:
                off_bias += 1

        if on_bias >= off_bias:
            return (1, 0)
        return (0, 1)

    def extract_loop(self):
        if not self._is_single_loop_complete():
            return None

        adj = {}
        for e, st in enumerate(self.edge_state):
            if st == 1:
                a, b = self.edge_endpoints[e]
                adj.setdefault(a, []).append(b)
                adj.setdefault(b, []).append(a)

        if not adj:
            return None

        start = min(adj.keys())
        path = [start]
        prev = None
        cur = start

        while True:
            nbrs = adj[cur]
            if prev is None:
                nxt = min(nbrs)
            else:
                if len(nbrs) != 2:
                    return None
                nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]

            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break

            if len(path) > len(adj) + 2:
                return None

        return [self._vertex_to_coord(v) for v in path]

    def _vertex_to_coord(self, v):
        return (v // (self.n + 1), v % (self.n + 1))


