# General Slitherlink solver with strong propagation and restrained search.
# Returns an ordered list of loop-dot coordinates, or "No Solution".

from collections import deque

UNKNOWN = -1
OFF = 0
ON = 1

def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    # Edge indexing
    # Horizontal H[r][c]: between (r,c) and (r,c+1), r in 0..n, c in 0..n-1
    # Vertical   V[r][c]: between (r,c) and (r+1,c), r in 0..n-1, c in 0..n
    h_count = (n + 1) * n
    v_count = n * (n + 1)
    total_edges = h_count + v_count

    def h_id(r, c):
        return r * n + c

    def v_id(r, c):
        return h_count + r * (n + 1) + c

    def edge_endpoints(e):
        if e < h_count:
            r, c = divmod(e, n)
            return (r, c), (r, c + 1)
        x = e - h_count
        r, c = divmod(x, n + 1)
        return (r, c), (r + 1, c)

    def cell_edges(r, c):
        return (
            h_id(r, c),         # top
            h_id(r + 1, c),     # bottom
            v_id(r, c),         # left
            v_id(r, c + 1),     # right
        )

    # Incident edges at each vertex
    vertex_edges = {}
    for r in range(n + 1):
        for c in range(n + 1):
            lst = []
            if c > 0:
                lst.append(h_id(r, c - 1))
            if c < n:
                lst.append(h_id(r, c))
            if r > 0:
                lst.append(v_id(r - 1, c))
            if r < n:
                lst.append(v_id(r, c))
            vertex_edges[(r, c)] = tuple(lst)

    # Cells touching an edge
    edge_cells = [[] for _ in range(total_edges)]
    for r in range(n):
        for c in range(n):
            for e in cell_edges(r, c):
                edge_cells[e].append((r, c))
    edge_cells = [tuple(x) for x in edge_cells]

    # Vertices touching an edge
    edge_vertices = [edge_endpoints(e) for e in range(total_edges)]

    # State arrays
    vals = [UNKNOWN] * total_edges

    # Queue flags
    q = deque()
    inq_cell = [[False] * n for _ in range(n)]
    inq_vert = [[False] * (n + 1) for _ in range(n + 1)]

    # For reversible assignments
    trail = []
    marks = []

    # Counts per cell / vertex
    cell_on = [[0] * n for _ in range(n)]
    cell_unk = [[4] * n for _ in range(n)]
    vert_on = [[0] * (n + 1) for _ in range(n + 1)]
    vert_unk = [[len(vertex_edges[(r, c)]) for c in range(n + 1)] for r in range(n + 1)]

    # Initial enqueue
    def push_cell(r, c):
        if 0 <= r < n and 0 <= c < n and not inq_cell[r][c]:
            inq_cell[r][c] = True
            q.append(("c", r, c))

    def push_vert(r, c):
        if 0 <= r <= n and 0 <= c <= n and not inq_vert[r][c]:
            inq_vert[r][c] = True
            q.append(("v", r, c))

    for r in range(n):
        for c in range(n):
            push_cell(r, c)
    for r in range(n + 1):
        for c in range(n + 1):
            push_vert(r, c)

    def assign(e, v):
        cur = vals[e]
        if cur == v:
            return True
        if cur != UNKNOWN:
            return False
        vals[e] = v
        trail.append(e)

        for (cr, cc) in edge_cells[e]:
            cell_unk[cr][cc] -= 1
            if v == ON:
                cell_on[cr][cc] += 1
            push_cell(cr, cc)

        (r1, c1), (r2, c2) = edge_vertices[e]
        vert_unk[r1][c1] -= 1
        vert_unk[r2][c2] -= 1
        if v == ON:
            vert_on[r1][c1] += 1
            vert_on[r2][c2] += 1
        push_vert(r1, c1)
        push_vert(r2, c2)
        return True

    def mark():
        marks.append(len(trail))

    def undo():
        tgt = marks.pop()
        while len(trail) > tgt:
            e = trail.pop()
            v = vals[e]
            vals[e] = UNKNOWN
            for (cr, cc) in edge_cells[e]:
                cell_unk[cr][cc] += 1
                if v == ON:
                    cell_on[cr][cc] -= 1
                push_cell(cr, cc)
            (r1, c1), (r2, c2) = edge_vertices[e]
            vert_unk[r1][c1] += 1
            vert_unk[r2][c2] += 1
            if v == ON:
                vert_on[r1][c1] -= 1
                vert_on[r2][c2] -= 1
            push_vert(r1, c1)
            push_vert(r2, c2)

    def cell_pattern_rules(r, c):
        clue = data[r][c]
        if clue is None:
            return True
        top, bot, left, right = cell_edges(r, c)

        # Simple local mirror of common human deductions for clue 3 / 1 with constrained vertices.
        # These are entailed by the rules but help propagate earlier.
        # Corner-adjacent deductions are covered implicitly by cell+vertex propagation,
        # so only very safe direct implications are used here.

        # If clue is 3 and one edge is OFF, the other three are ON.
        # If clue is 1 and three edges are OFF, the last is ON.
        # These are already enforced by generic counts; no extra logic required.
        return True

    def propagate():
        while q:
            typ, a, b = q.popleft()
            if typ == "c":
                inq_cell[a][b] = False
                r, c = a, b
                clue = data[r][c]
                if clue is None:
                    continue

                on = cell_on[r][c]
                unk = cell_unk[r][c]
                if on > clue or on + unk < clue:
                    return False

                edges = cell_edges(r, c)
                if clue == on:
                    for e in edges:
                        if vals[e] == UNKNOWN and not assign(e, OFF):
                            return False
                elif clue == on + unk:
                    for e in edges:
                        if vals[e] == UNKNOWN and not assign(e, ON):
                            return False

                if not cell_pattern_rules(r, c):
                    return False

            else:
                inq_vert[a][b] = False
                r, c = a, b
                on = vert_on[r][c]
                unk = vert_unk[r][c]
                if on > 2:
                    return False
                if on == 1 and unk == 0:
                    return False
                if on == 2:
                    for e in vertex_edges[(r, c)]:
                        if vals[e] == UNKNOWN and not assign(e, OFF):
                            return False
                elif on == 1 and unk == 1:
                    for e in vertex_edges[(r, c)]:
                        if vals[e] == UNKNOWN and not assign(e, ON):
                            return False
                elif on == 0 and unk == 1:
                    for e in vertex_edges[(r, c)]:
                        if vals[e] == UNKNOWN and not assign(e, OFF):
                            return False

        # Global structural pruning on current ON graph:
        # 1) no closed subloop before all ON vertices are in a single cycle
        # 2) any path component has exactly two endpoints
        return global_prune()

    def global_prune():
        # Build ON graph over vertices
        adj = {}
        on_edges = []
        for e, v in enumerate(vals):
            if v == ON:
                u, w = edge_vertices[e]
                adj.setdefault(u, []).append(w)
                adj.setdefault(w, []).append(u)
                on_edges.append(e)

        if not on_edges:
            return True

        visited = set()
        comps = 0
        cycle_comps = 0

        for start in adj:
            if start in visited:
                continue
            comps += 1
            stack = [start]
            visited.add(start)
            verts = 0
            edge_sum_deg = 0
            deg1 = 0
            while stack:
                x = stack.pop()
                d = len(adj[x])
                verts += 1
                edge_sum_deg += d
                if d == 1:
                    deg1 += 1
                elif d != 2:
                    return False
                for y in adj[x]:
                    if y not in visited:
                        visited.add(y)
                        stack.append(y)
            edges = edge_sum_deg // 2
            if edges == verts:
                cycle_comps += 1
            else:
                if deg1 != 2:
                    return False

        if cycle_comps >= 2:
            return False

        # If one cycle exists, there must be no other ON component.
        if cycle_comps == 1 and comps > 1:
            return False

        # If a cycle exists while any undecided edge could still be ON via a clue/vertex,
        # search would handle it later; this prune is intentionally conservative.
        return True

    # Some immediate clue-driven initial assignments humans often spot.
    # 0-cells.
    for r in range(n):
        for c in range(n):
            clue = data[r][c]
            if clue == 0:
                for e in cell_edges(r, c):
                    if not assign(e, OFF):
                        return "No Solution"

    # Corner 3 rule.
    corners = [
        (0, 0, (h_id(0, 0), v_id(0, 0))),
        (0, n - 1, (h_id(0, n - 1), v_id(0, n))),
        (n - 1, 0, (h_id(n, 0), v_id(n - 1, 0))),
        (n - 1, n - 1, (h_id(n, n - 1), v_id(n - 1, n))),
    ]
    for r, c, edges in corners:
        if data[r][c] == 3:
            for e in edges:
                if not assign(e, ON):
                    return "No Solution"

    if not propagate():
        return "No Solution"

    def is_complete():
        return all(v != UNKNOWN for v in vals)

    def final_check():
        # All clues satisfied
        for r in range(n):
            for c in range(n):
                clue = data[r][c]
                if clue is None:
                    continue
                if cell_on[r][c] != clue:
                    return False

        # Vertex degrees 0 or 2
        deg2_vertices = 0
        for r in range(n + 1):
            for c in range(n + 1):
                if vert_unk[r][c] != 0:
                    return False
                d = vert_on[r][c]
                if d not in (0, 2):
                    return False
                if d == 2:
                    deg2_vertices += 1

        # Exactly one cycle if any ON edges exist
        on_edges = [e for e, v in enumerate(vals) if v == ON]
        if not on_edges:
            return False

        adj = {}
        for e in on_edges:
            u, w = edge_vertices[e]
            adj.setdefault(u, []).append(w)
            adj.setdefault(w, []).append(u)

        start = next(iter(adj))
        seen = set([start])
        stack = [start]
        while stack:
            x = stack.pop()
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        return len(seen) == len(adj)

    def edge_score(e):
        score = 0
        for r, c in edge_cells[e]:
            clue = data[r][c]
            if clue is not None:
                rem = cell_unk[r][c]
                need = clue - cell_on[r][c]
                score += 10 - abs(2 * need - rem)
                if clue in (0, 3):
                    score += 2
        for vr, vc in edge_vertices[e]:
            score += 4 - vert_unk[vr][vc]
            score += 2 * vert_on[vr][vc]
        return score

    def choose_edge():
        best = None
        best_score = -10**9
        for e, v in enumerate(vals):
            if v == UNKNOWN:
                s = edge_score(e)
                if s > best_score:
                    best_score = s
                    best = e
        return best

    def branch_order(e):
        # Prefer ON when edge sits in a "needs more ON" situation.
        bias = 0
        for r, c in edge_cells[e]:
            clue = data[r][c]
            if clue is not None:
                need = clue - cell_on[r][c]
                rem = cell_unk[r][c]
                if rem > 0 and need * 2 >= rem:
                    bias += 1
                else:
                    bias -= 1
        for vr, vc in edge_vertices[e]:
            if vert_on[vr][vc] == 1:
                bias += 2
            elif vert_on[vr][vc] == 2:
                bias -= 3
            elif vert_unk[vr][vc] == 1:
                bias -= 2
        return (ON, OFF) if bias >= 0 else (OFF, ON)

    def dfs():
        if is_complete():
            return final_check()

        e = choose_edge()
        if e is None:
            return False

        for v in branch_order(e):
            mark()
            if assign(e, v) and propagate() and dfs():
                return True
            undo()
        return False

    if not dfs():
        return "No Solution"

    # Extract ordered loop
    adj = {}
    for e, v in enumerate(vals):
        if v == ON:
            u, w = edge_vertices[e]
            adj.setdefault(u, []).append(w)
            adj.setdefault(w, []).append(u)

    if not adj:
        return "No Solution"

    start = min(adj)
    nbrs = adj[start]
    if len(nbrs) != 2:
        return "No Solution"

    path = [start]
    prev = None
    cur = start
    while True:
        nxts = adj[cur]
        if prev is None:
            nxt = min(nxts)
        else:
            nxt = nxts[0] if nxts[1] == prev else nxts[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break

    return str(path)

if __name__ == "__main__":
    print(solve(OBSERVATION))

