from itertools import combinations

# Weighted binary-grid solver.
# Row i has weight (i+1), column j has weight (j+1).
# A black cell at (i, j) contributes (j+1) to row i target and (i+1) to column j target.

def bit_positions(mask, n):
    while mask:
        lsb = mask & -mask
        yield lsb.bit_length() - 1
        mask ^= lsb

def subset_masks_by_sum(weights, target):
    n = len(weights)
    out = []
    def rec(idx, s, mask):
        if s == target:
            out.append(mask)
            return
        if s > target or idx == n:
            return
        rem = sum(weights[idx:])
        if s + rem < target:
            return
        rec(idx + 1, s, mask)
        rec(idx + 1, s + weights[idx], mask | (1 << idx))
    rec(0, 0, 0)
    return out

def transpose_masks(row_masks, n_rows, n_cols):
    col_masks = [0] * n_cols
    for r, mask in enumerate(row_masks):
        bit = 1
        for c in range(n_cols):
            if mask & bit:
                col_masks[c] |= (1 << r)
            bit <<= 1
    return col_masks

def compute_fixed_cells(row_domains, n_rows, n_cols):
    # returns (forced_black_masks_per_row, forced_white_masks_per_row)
    black = [0] * n_rows
    white = [0] * n_rows
    all_cols_mask = (1 << n_cols) - 1
    for r in range(n_rows):
        dom = row_domains[r]
        if not dom:
            return None, None
        inter = all_cols_mask
        union = 0
        for m in dom:
            inter &= m
            union |= m
        black[r] = inter
        white[r] = all_cols_mask ^ union
    return black, white

def filter_row_domains_by_cells(row_domains, forced_black, forced_white):
    changed = False
    new_domains = []
    for r, dom in enumerate(row_domains):
        fb = forced_black[r]
        fw = forced_white[r]
        nd = [m for m in dom if (m & fb) == fb and (m & fw) == 0]
        if not nd:
            return None, True
        if len(nd) != len(dom):
            changed = True
        new_domains.append(nd)
    return new_domains, changed

def filter_col_domains_by_cells(col_domains, forced_black_cols, forced_white_cols):
    changed = False
    new_domains = []
    for c, dom in enumerate(col_domains):
        fb = forced_black_cols[c]
        fw = forced_white_cols[c]
        nd = [m for m in dom if (m & fb) == fb and (m & fw) == 0]
        if not nd:
            return None, True
        if len(nd) != len(dom):
            changed = True
        new_domains.append(nd)
    return new_domains, changed

def row_forced_to_col_view(forced_masks_per_row, n_rows, n_cols):
    out = [0] * n_cols
    for r, mask in enumerate(forced_masks_per_row):
        for c in bit_positions(mask, n_cols):
            out[c] |= (1 << r)
    return out

def col_forced_to_row_view(forced_masks_per_col, n_rows, n_cols):
    out = [0] * n_rows
    for c, mask in enumerate(forced_masks_per_col):
        for r in bit_positions(mask, n_rows):
            out[r] |= (1 << c)
    return out

def compute_col_fixed(col_domains, n_rows, n_cols):
    black = [0] * n_cols
    white = [0] * n_cols
    all_rows_mask = (1 << n_rows) - 1
    for c in range(n_cols):
        dom = col_domains[c]
        if not dom:
            return None, None
        inter = all_rows_mask
        union = 0
        for m in dom:
            inter &= m
            union |= m
        black[c] = inter
        white[c] = all_rows_mask ^ union
    return black, white

def propagate(row_domains, col_domains, n_rows, n_cols):
    while True:
        changed = False

        rb, rw = compute_fixed_cells(row_domains, n_rows, n_cols)
        if rb is None:
            return None
        forced_black_cols = row_forced_to_col_view(rb, n_rows, n_cols)
        forced_white_cols = row_forced_to_col_view(rw, n_rows, n_cols)

        new_col_domains, ch = filter_col_domains_by_cells(col_domains, forced_black_cols, forced_white_cols)
        if new_col_domains is None:
            return None
        col_domains = new_col_domains
        changed |= ch

        cb, cw = compute_col_fixed(col_domains, n_rows, n_cols)
        if cb is None:
            return None
        forced_black_rows = col_forced_to_row_view(cb, n_rows, n_cols)
        forced_white_rows = col_forced_to_row_view(cw, n_rows, n_cols)

        new_row_domains, ch = filter_row_domains_by_cells(row_domains, forced_black_rows, forced_white_rows)
        if new_row_domains is None:
            return None
        row_domains = new_row_domains
        changed |= ch

        # Additional consistency: exact column candidate support from row domains
        # Build possible cell occupancy per column across row domains
        rb, rw = compute_fixed_cells(row_domains, n_rows, n_cols)
        if rb is None:
            return None
        forced_black_cols = row_forced_to_col_view(rb, n_rows, n_cols)
        forced_white_cols = row_forced_to_col_view(rw, n_rows, n_cols)
        new_col_domains, ch = filter_col_domains_by_cells(col_domains, forced_black_cols, forced_white_cols)
        if new_col_domains is None:
            return None
        col_domains = new_col_domains
        changed |= ch

        cb, cw = compute_col_fixed(col_domains, n_rows, n_cols)
        if cb is None:
            return None
        forced_black_rows = col_forced_to_row_view(cb, n_rows, n_cols)
        forced_white_rows = col_forced_to_row_view(cw, n_rows, n_cols)
        new_row_domains, ch = filter_row_domains_by_cells(row_domains, forced_black_rows, forced_white_rows)
        if new_row_domains is None:
            return None
        row_domains = new_row_domains
        changed |= ch

        # Pairwise support pruning: each row pattern must be extendable to every column domain, and vice versa.
        # This mirrors human cross-checking candidates against the opposite side clues.
        supports_ok = True

        allowed_by_col = []
        for c in range(n_cols):
            ones = 0
            zeros = 0
            for m in col_domains[c]:
                ones |= m
                zeros |= (~m) & ((1 << n_rows) - 1)
            allowed_by_col.append((ones, zeros))

        new_row_domains = []
        for r in range(n_rows):
            nd = []
            for m in row_domains[r]:
                ok = True
                for c in range(n_cols):
                    bit = 1 << c
                    if m & bit:
                        if not (allowed_by_col[c][0] & (1 << r)):
                            ok = False
                            break
                    else:
                        if not (allowed_by_col[c][1] & (1 << r)):
                            ok = False
                            break
                if ok:
                    nd.append(m)
            if not nd:
                supports_ok = False
                break
            changed |= (len(nd) != len(row_domains[r]))
            new_row_domains.append(nd)
        if not supports_ok:
            return None
        row_domains = new_row_domains

        allowed_by_row = []
        for r in range(n_rows):
            ones = 0
            zeros = 0
            for m in row_domains[r]:
                ones |= m
                zeros |= (~m) & ((1 << n_cols) - 1)
            allowed_by_row.append((ones, zeros))

        new_col_domains = []
        for c in range(n_cols):
            nd = []
            for m in col_domains[c]:
                ok = True
                for r in range(n_rows):
                    bit = 1 << r
                    if m & bit:
                        if not (allowed_by_row[r][0] & (1 << c)):
                            ok = False
                            break
                    else:
                        if not (allowed_by_row[r][1] & (1 << c)):
                            ok = False
                            break
                if ok:
                    nd.append(m)
            if not nd:
                return None
            changed |= (len(nd) != len(col_domains[c]))
            new_col_domains.append(nd)
        col_domains = new_col_domains

        if not changed:
            return row_domains, col_domains

def choose_branch(row_domains, col_domains):
    best = None
    # Prefer the smallest domain > 1, whether row or column.
    for i, dom in enumerate(row_domains):
        if 1 < len(dom) and (best is None or len(dom) < best[2]):
            best = ('row', i, len(dom))
    for j, dom in enumerate(col_domains):
        if 1 < len(dom) and (best is None or len(dom) < best[2]):
            best = ('col', j, len(dom))
    return best

def build_solution_from_rows(row_domains, n_rows, n_cols):
    row_masks = [dom[0] for dom in row_domains]
    grid = []
    for r in range(n_rows):
        row = []
        mask = row_masks[r]
        for c in range(n_cols):
            row.append('B' if (mask >> c) & 1 else None)
        grid.append(row)
    return grid

def consistent_final(row_domains, col_domains, n_rows, n_cols):
    if any(len(dom) != 1 for dom in row_domains):
        return False
    row_masks = [dom[0] for dom in row_domains]
    col_masks = transpose_masks(row_masks, n_rows, n_cols)
    for c in range(n_cols):
        if col_masks[c] not in set(col_domains[c]):
            return False
    return True

def search(row_domains, col_domains, n_rows, n_cols):
    state = propagate(row_domains, col_domains, n_rows, n_cols)
    if state is None:
        return None
    row_domains, col_domains = state

    if consistent_final(row_domains, col_domains, n_rows, n_cols):
        return build_solution_from_rows(row_domains, n_rows, n_cols)

    branch = choose_branch(row_domains, col_domains)
    if branch is None:
        return None

    kind, idx, _ = branch
    if kind == 'row':
        # Least-commitment ordering: try patterns that better match current column certainty.
        scored = []
        cb, cw = compute_col_fixed(col_domains, n_rows, n_cols)
        for m in row_domains[idx]:
            score = 0
            for c in range(n_cols):
                bit = 1 << c
                if m & bit:
                    if cb[c] & (1 << idx):
                        score += 2
                    if cw[c] & (1 << idx):
                        score -= 3
                else:
                    if cw[c] & (1 << idx):
                        score += 2
                    if cb[c] & (1 << idx):
                        score -= 3
            scored.append((-score, m))
        for _, chosen in sorted(scored):
            new_rows = [list(dom) for dom in row_domains]
            new_rows[idx] = [chosen]
            res = search(new_rows, [list(dom) for dom in col_domains], n_rows, n_cols)
            if res is not None:
                return res
    else:
        rb, rw = compute_fixed_cells(row_domains, n_rows, n_cols)
        scored = []
        for m in col_domains[idx]:
            score = 0
            for r in range(n_rows):
                bit = 1 << r
                if m & bit:
                    if rb[r] & (1 << idx):
                        score += 2
                    if rw[r] & (1 << idx):
                        score -= 3
                else:
                    if rw[r] & (1 << idx):
                        score += 2
                    if rb[r] & (1 << idx):
                        score -= 3
            scored.append((-score, m))
        for _, chosen in sorted(scored):
            new_cols = [list(dom) for dom in col_domains]
            new_cols[idx] = [chosen]
            res = search([list(dom) for dom in row_domains], new_cols, n_rows, n_cols)
            if res is not None:
                return res

    return None

def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    n_rows = len(row_sum)
    n_cols = len(col_sum)

    col_weights = list(range(1, n_cols + 1))
    row_weights = list(range(1, n_rows + 1))

    row_domains = [subset_masks_by_sum(col_weights, tgt) for tgt in row_sum]
    col_domains = [subset_masks_by_sum(row_weights, tgt) for tgt in col_sum]

    if any(len(dom) == 0 for dom in row_domains) or any(len(dom) == 0 for dom in col_domains):
        return "No Solution"

    result = search(row_domains, col_domains, n_rows, n_cols)
    if result is None:
        return "No Solution"
    return str(result)

