# General Slitherlink solver:
# - strong local propagation from clue and dot constraints
# - contradiction checks including premature small-loop prevention
# - informed branching on most constrained edge
# - final extraction of ordered loop coordinates

from collections import deque

UNKNOWN = -1
OFF = 0
ON = 1

def solve(observation):
    data = observation["data"]
    if not data or not data[0]:
        return "No Solution"

    solver = SlitherlinkSolver(data)
    ok = solver.search()
    if not ok:
        return "No Solution"
    loop = solver.extract_loop()
    return str(loop) if loop else "No Solution"


class SlitherlinkSolver:
    def __init__(self, clues):
        self.clues = clues
        self.R = len(clues)
        self.C = len(clues[0])

        # Horizontal edges: between (r,c) and (r,c+1), r in [0..R], c in [0..C-1]
        self.H = [[UNKNOWN] * self.C for _ in range(self.R + 1)]
        # Vertical edges: between (r,c) and (r+1,c), r in [0..R-1], c in [0..C]
        self.V = [[UNKNOWN] * (self.C + 1) for _ in range(self.R)]

        self.edge_ids = []
        self.edge_to_kind_idx = {}
        self.dot_edges = [[[] for _ in range(self.C + 1)] for _ in range(self.R + 1)]
        self.cell_edges = [[[] for _ in range(self.C)] for _ in range(self.R)]

        self._build_indexing()

    def _build_indexing(self):
        eid = 0
        for r in range(self.R + 1):
            for c in range(self.C):
                key = ('H', r, c)
                self.edge_ids.append(key)
                self.edge_to_kind_idx[key] = eid
                self.dot_edges[r][c].append(key)
                self.dot_edges[r][c + 1].append(key)
                if r > 0:
                    self.cell_edges[r - 1][c].append(key)
                if r < self.R:
                    self.cell_edges[r][c].append(key)
                eid += 1
        for r in range(self.R):
            for c in range(self.C + 1):
                key = ('V', r, c)
                self.edge_ids.append(key)
                self.edge_to_kind_idx[key] = eid
                self.dot_edges[r][c].append(key)
                self.dot_edges[r + 1][c].append(key)
                if c > 0:
                    self.cell_edges[r][c - 1].append(key)
                if c < self.C:
                    self.cell_edges[r][c].append(key)
                eid += 1

    def clone(self):
        s = SlitherlinkSolver(self.clues)
        s.H = [row[:] for row in self.H]
        s.V = [row[:] for row in self.V]
        return s

    def get_edge(self, edge):
        k, r, c = edge
        return self.H[r][c] if k == 'H' else self.V[r][c]

    def set_edge(self, edge, val, queue):
        cur = self.get_edge(edge)
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        k, r, c = edge
        if k == 'H':
            self.H[r][c] = val
        else:
            self.V[r][c] = val
        queue.append(('edge', edge))
        return True

    def incident_on_edges(self, r, c):
        res = []
        for e in self.dot_edges[r][c]:
            if self.get_edge(e) == ON:
                res.append(e)
        return res

    def unknown_incident_edges(self, r, c):
        res = []
        for e in self.dot_edges[r][c]:
            if self.get_edge(e) == UNKNOWN:
                res.append(e)
        return res

    def propagate(self):
        queue = deque()

        # Initialize all constraints
        for r in range(self.R):
            for c in range(self.C):
                if self.clues[r][c] is not None:
                    queue.append(('cell', (r, c)))
        for r in range(self.R + 1):
            for c in range(self.C + 1):
                queue.append(('dot', (r, c)))

        while queue:
            typ, obj = queue.popleft()
            if typ == 'cell':
                if not self._propagate_cell(obj[0], obj[1], queue):
                    return False
            elif typ == 'dot':
                if not self._propagate_dot(obj[0], obj[1], queue):
                    return False
            else:
                edge = obj
                # Changed edge affects adjacent cells and endpoint dots
                k, r, c = edge
                if k == 'H':
                    if r > 0 and self.clues[r - 1][c] is not None:
                        queue.append(('cell', (r - 1, c)))
                    if r < self.R and self.clues[r][c] is not None:
                        queue.append(('cell', (r, c)))
                    queue.append(('dot', (r, c)))
                    queue.append(('dot', (r, c + 1)))
                else:
                    if c > 0 and self.clues[r][c - 1] is not None:
                        queue.append(('cell', (r, c - 1)))
                    if c < self.C and self.clues[r][c] is not None:
                        queue.append(('cell', (r, c)))
                    queue.append(('dot', (r, c)))
                    queue.append(('dot', (r + 1, c)))

            if not self._global_checks():
                return False
        return True

    def _propagate_cell(self, r, c, queue):
        clue = self.clues[r][c]
        if clue is None:
            return True
        edges = self.cell_edges[r][c]
        vals = [self.get_edge(e) for e in edges]
        on = sum(v == ON for v in vals)
        unk = sum(v == UNKNOWN for v in vals)

        if on > clue:
            return False
        if on + unk < clue:
            return False

        if unk == 0:
            return on == clue

        if on == clue:
            for e in edges:
                if self.get_edge(e) == UNKNOWN and not self.set_edge(e, OFF, queue):
                    return False

        if on + unk == clue:
            for e in edges:
                if self.get_edge(e) == UNKNOWN and not self.set_edge(e, ON, queue):
                    return False

        # Human-like pattern: 0 and 4-edge completion are already covered above.
        # Strong local consistency: test each unknown edge both ways against the cell.
        for e in edges:
            if self.get_edge(e) != UNKNOWN:
                continue
            possible = []
            for trial in (OFF, ON):
                new_on = on + (1 if trial == ON else 0)
                new_unk = unk - 1
                if new_on <= clue <= new_on + new_unk:
                    possible.append(trial)
            if not possible:
                return False
            if len(possible) == 1:
                if not self.set_edge(e, possible[0], queue):
                    return False

        return True

    def _propagate_dot(self, r, c, queue):
        edges = self.dot_edges[r][c]
        vals = [self.get_edge(e) for e in edges]
        on = sum(v == ON for v in vals)
        unk = [e for e in edges if self.get_edge(e) == UNKNOWN]

        # Dot degree must be 0 or 2
        if on > 2:
            return False
        if on == 1 and not unk:
            return False
        if on == 0 and len(unk) == 1:
            if not self.set_edge(unk[0], OFF, queue):
                return False
        if on == 2:
            for e in unk:
                if not self.set_edge(e, OFF, queue):
                    return False
        if on == 1 and len(unk) == 1:
            if not self.set_edge(unk[0], ON, queue):
                return False
        if on == 0 and len(unk) == 2:
            # at a 2-edge corner/line situation, either both off or both on; not directly decidable
            pass

        # Strong local consistency per edge using dot-degree domain {0,2}
        on_count = on
        unk_count = len(unk)
        feasible_degrees = set()
        for add in range(unk_count + 1):
            deg = on_count + add
            if deg in (0, 2):
                feasible_degrees.add(add)
        if not feasible_degrees:
            return False

        for e in unk:
            can_on = False
            can_off = False
            others = unk_count - 1
            # if e is ON
            for add_others in range(others + 1):
                deg = on_count + 1 + add_others
                if deg in (0, 2):
                    can_on = True
                    break
            # if e is OFF
            for add_others in range(others + 1):
                deg = on_count + add_others
                if deg in (0, 2):
                    can_off = True
                    break
            if not can_on and not can_off:
                return False
            if can_on and not can_off:
                if not self.set_edge(e, ON, queue):
                    return False
            if can_off and not can_on:
                if not self.set_edge(e, OFF, queue):
                    return False

        return True

    def _global_checks(self):
        # Check no closed subloop before all ON edges are finalized into one full loop.
        if not self._check_no_premature_loop():
            return False

        # Each connected partial path component must be extendable.
        if not self._check_component_extendability():
            return False

        return True

    def _on_neighbors(self):
        g = {}
        for r in range(self.R + 1):
            for c in range(self.C + 1):
                g[(r, c)] = []
        for r in range(self.R + 1):
            for c in range(self.C):
                if self.H[r][c] == ON:
                    a = (r, c)
                    b = (r, c + 1)
                    g[a].append(b)
                    g[b].append(a)
        for r in range(self.R):
            for c in range(self.C + 1):
                if self.V[r][c] == ON:
                    a = (r, c)
                    b = (r + 1, c)
                    g[a].append(b)
                    g[b].append(a)
        return g

    def _check_no_premature_loop(self):
        g = self._on_neighbors()
        nonzero = [v for v, nbrs in g.items() if nbrs]
        if not nonzero:
            return True

        seen = set()
        for start in nonzero:
            if start in seen:
                continue
            stack = [start]
            comp = []
            edge_twice = 0
            while stack:
                u = stack.pop()
                if u in seen:
                    continue
                seen.add(u)
                comp.append(u)
                edge_twice += len(g[u])
                for v in g[u]:
                    if v not in seen:
                        stack.append(v)
            edges = edge_twice // 2
            verts = len(comp)
            degs = [len(g[v]) for v in comp]
            if all(d == 2 for d in degs):
                total_on = self.count_on_edges()
                if edges != total_on:
                    return False
        return True

    def _check_component_extendability(self):
        # For each ON-component, count endpoints (degree 1 vertices).
        # A component with all deg 2 is a closed loop; handled elsewhere.
        # A component with >2 odd degree impossible under dot rules, but local rules already catch.
        # Additional pruning: if a path component has 2 endpoints, each endpoint must have some non-OFF continuation
        g = self._on_neighbors()
        visited = set()
        for start, nbrs in g.items():
            if not nbrs or start in visited:
                continue
            stack = [start]
            comp = []
            while stack:
                u = stack.pop()
                if u in visited:
                    continue
                visited.add(u)
                comp.append(u)
                for v in g[u]:
                    if v not in visited:
                        stack.append(v)
            ends = [u for u in comp if len(g[u]) == 1]
            if len(ends) not in (0, 2):
                return False
            if len(ends) == 2:
                for r, c in ends:
                    if not any(self.get_edge(e) != OFF for e in self.dot_edges[r][c] if self.get_edge(e) != ON):
                        return False
        return True

    def count_on_edges(self):
        total = 0
        for r in range(self.R + 1):
            for c in range(self.C):
                total += self.H[r][c] == ON
        for r in range(self.R):
            for c in range(self.C + 1):
                total += self.V[r][c] == ON
        return total

    def is_solved(self):
        # All edges determined
        for r in range(self.R + 1):
            for c in range(self.C):
                if self.H[r][c] == UNKNOWN:
                    return False
        for r in range(self.R):
            for c in range(self.C + 1):
                if self.V[r][c] == UNKNOWN:
                    return False

        # Cell constraints
        for r in range(self.R):
            for c in range(self.C):
                clue = self.clues[r][c]
                if clue is None:
                    continue
                if sum(self.get_edge(e) == ON for e in self.cell_edges[r][c]) != clue:
                    return False

        # Dot constraints and single loop
        g = self._on_neighbors()
        nodes = [v for v, nbrs in g.items() if nbrs]
        if not nodes:
            return False
        if any(len(g[v]) != 2 for v in nodes):
            return False

        seen = set()
        stack = [nodes[0]]
        while stack:
            u = stack.pop()
            if u in seen:
                continue
            seen.add(u)
            for v in g[u]:
                if v not in seen:
                    stack.append(v)
        return len(seen) == len(nodes)

    def choose_branch_edge(self):
        # Most constrained unknown edge: score by adjacent clues and endpoint saturation.
        best = None
        best_score = None

        for edge in self.edge_ids:
            if self.get_edge(edge) != UNKNOWN:
                continue
            score = self._edge_score(edge)
            if best is None or score > best_score:
                best = edge
                best_score = score
        return best

    def _edge_score(self, edge):
        score = 0
        k, r, c = edge

        # Adjacent clues
        adj_cells = []
        if k == 'H':
            if r > 0:
                adj_cells.append((r - 1, c))
            if r < self.R:
                adj_cells.append((r, c))
            dots = [(r, c), (r, c + 1)]
        else:
            if c > 0:
                adj_cells.append((r, c - 1))
            if c < self.C:
                adj_cells.append((r, c))
            dots = [(r, c), (r + 1, c)]

        for rr, cc in adj_cells:
            clue = self.clues[rr][cc]
            if clue is not None:
                vals = [self.get_edge(e) for e in self.cell_edges[rr][cc]]
                on = sum(v == ON for v in vals)
                unk = sum(v == UNKNOWN for v in vals)
                score += 10
                score += abs(2 * clue - 4)
                score += 4 - unk
                score += min(abs(clue - on), abs((on + unk) - clue))

        for dr, dc in dots:
            vals = [self.get_edge(e) for e in self.dot_edges[dr][dc]]
            on = sum(v == ON for v in vals)
            unk = sum(v == UNKNOWN for v in vals)
            score += 6 - unk
            score += on * 2

        return score

    def branch_values(self, edge):
        # Prefer value by local pressure from clues.
        on_bias = 0
        off_bias = 0
        k, r, c = edge
        if k == 'H':
            adj = []
            if r > 0:
                adj.append((r - 1, c))
            if r < self.R:
                adj.append((r, c))
        else:
            adj = []
            if c > 0:
                adj.append((r, c - 1))
            if c < self.C:
                adj.append((r, c))
        for rr, cc in adj:
            clue = self.clues[rr][cc]
            if clue is None:
                continue
            vals = [self.get_edge(e) for e in self.cell_edges[rr][cc]]
            on = sum(v == ON for v in vals)
            unk = sum(v == UNKNOWN for v in vals)
            need = clue - on
            # If many remaining edges needed, favor ON; if clue already near met, favor OFF.
            on_bias += need
            off_bias += (unk - need)

        # Tiebreak from dots: avoid degree 1 dead-ends.
        dots = [(r, c), (r, c + 1)] if k == 'H' else [(r, c), (r + 1, c)]
        for dr, dc in dots:
            vals = [self.get_edge(e) for e in self.dot_edges[dr][dc]]
            on = sum(v == ON for v in vals)
            if on == 1:
                on_bias += 2
            if on == 2:
                off_bias += 3

        return (ON, OFF) if on_bias >= off_bias else (OFF, ON)

    def search(self):
        if not self.propagate():
            return False
        if self.is_solved():
            return True

        edge = self.choose_branch_edge()
        if edge is None:
            return False

        for val in self.branch_values(edge):
            child = self.clone()
            q = deque()
            if not child.set_edge(edge, val, q):
                continue
            if child.propagate() and child.search():
                self.H = child.H
                self.V = child.V
                return True
        return False

    def extract_loop(self):
        g = self._on_neighbors()
        nodes = [v for v, nbrs in g.items() if nbrs]
        if not nodes:
            return None

        start = min(nodes)
        nbrs = sorted(g[start])
        if not nbrs:
            return None

        path = [start]
        prev = None
        cur = start
        nxt = nbrs[0]

        while True:
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            candidates = g[cur]
            if len(candidates) != 2:
                return None
            if candidates[0] == prev:
                nxt = candidates[1]
            else:
                nxt = candidates[0]

            # safety
            if len(path) > self.count_on_edges() + 2:
                return None

        return path


