from copy import deepcopy

# General Takuzu-with-edge-constraints solver.
# Values are encoded as 1='B', 0='W' for fast pattern handling.

def parse_key(s):
    s = s.strip()
    if s[0] == '(' and s[-1] == ')':
        s = s[1:-1]
    a, b = s.split(',')
    return float(a), float(b)

def bits_to_row(bits):
    return ['B' if x else 'W' for x in bits]

def all_patterns(length):
    half = length // 2
    out = []
    for mask in range(1 << length):
        bits = tuple((mask >> i) & 1 for i in range(length))
        if sum(bits) != half:
            continue
        ok = True
        for i in range(length - 2):
            if bits[i] == bits[i + 1] == bits[i + 2]:
                ok = False
                break
        if ok:
            out.append(bits)
    return out

def row_constraints(observation):
    rows = len(observation['data'])
    cols = len(observation['data'][0])
    h = {}
    for k, v in observation.get('horizontal', {}).items():
        r, c = parse_key(k)
        rr = int(round(r))
        cc = int(round(c - 0.5))
        if 0 <= rr < rows and 0 <= cc < cols - 1:
            h.setdefault(rr, {})[cc] = v
    return h

def col_constraints(observation):
    rows = len(observation['data'])
    cols = len(observation['data'][0])
    vmap = {}
    for k, v in observation.get('vertical', {}).items():
        r, c = parse_key(k)
        rr = int(round(r - 0.5))
        cc = int(round(c))
        if 0 <= rr < rows - 1 and 0 <= cc < cols:
            vmap.setdefault(cc, {})[rr] = v
    return vmap

def cell_given(observation, r, c):
    x = observation['data'][r][c]
    if x is None:
        return None
    return 1 if x == 'B' else 0

def pattern_fits_row(bits, r, observation, hcons):
    for c, b in enumerate(bits):
        g = cell_given(observation, r, c)
        if g is not None and g != b:
            return False
    for c, rel in hcons.get(r, {}).items():
        if rel == '=' and bits[c] != bits[c + 1]:
            return False
        if rel == 'x' and bits[c] == bits[c + 1]:
            return False
    return True

def pattern_fits_col(bits, c, observation, vcons):
    for r, b in enumerate(bits):
        g = cell_given(observation, r, c)
        if g is not None and g != b:
            return False
    for r, rel in vcons.get(c, {}).items():
        if rel == '=' and bits[r] != bits[r + 1]:
            return False
        if rel == 'x' and bits[r] == bits[r + 1]:
            return False
    return True

def propagate(row_domains, col_domains):
    rows = len(row_domains)
    cols = len(col_domains)
    changed = True
    while changed:
        changed = False

        # Allowed values per cell from row/column domains.
        row_vals = [[set() for _ in range(cols)] for _ in range(rows)]
        col_vals = [[set() for _ in range(cols)] for _ in range(rows)]

        for r in range(rows):
            for pat in row_domains[r]:
                for c, b in enumerate(pat):
                    row_vals[r][c].add(b)

        for c in range(cols):
            for pat in col_domains[c]:
                for r, b in enumerate(pat):
                    col_vals[r][c].add(b)

        allowed = [[row_vals[r][c] & col_vals[r][c] for c in range(cols)] for r in range(rows)]
        for r in range(rows):
            for c in range(cols):
                if not allowed[r][c]:
                    return False, row_domains, col_domains

        # Filter rows.
        for r in range(rows):
            new_dom = [pat for pat in row_domains[r] if all(pat[c] in allowed[r][c] for c in range(cols))]
            if not new_dom:
                return False, row_domains, col_domains
            if len(new_dom) != len(row_domains[r]):
                row_domains[r] = new_dom
                changed = True

        # Filter cols.
        for c in range(cols):
            new_dom = [pat for pat in col_domains[c] if all(pat[r] in allowed[r][c] for r in range(rows))]
            if not new_dom:
                return False, row_domains, col_domains
            if len(new_dom) != len(col_domains[c]):
                col_domains[c] = new_dom
                changed = True

    return True, row_domains, col_domains

def solved(row_domains, col_domains):
    return all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains)

def choose_branch(row_domains, col_domains):
    best = None

    for r, dom in enumerate(row_domains):
        if 1 < len(dom) and (best is None or len(dom) < best[2]):
            best = ('row', r, len(dom))
    for c, dom in enumerate(col_domains):
        if 1 < len(dom) and (best is None or len(dom) < best[2]):
            best = ('col', c, len(dom))
    return best

def search(row_domains, col_domains):
    ok, row_domains, col_domains = propagate(row_domains, col_domains)
    if not ok:
        return None
    if solved(row_domains, col_domains):
        return row_domains, col_domains

    kind, idx, _ = choose_branch(row_domains, col_domains)

    if kind == 'row':
        domain = list(row_domains[idx])
        # Value ordering: prefer patterns that agree with current column-majority support.
        domain.sort()
        for pat in domain:
            rd = deepcopy(row_domains)
            cd = deepcopy(col_domains)
            rd[idx] = [pat]
            ans = search(rd, cd)
            if ans is not None:
                return ans
    else:
        domain = list(col_domains[idx])
        domain.sort()
        for pat in domain:
            rd = deepcopy(row_domains)
            cd = deepcopy(col_domains)
            cd[idx] = [pat]
            ans = search(rd, cd)
            if ans is not None:
                return ans

    return None

def solve(observation):
    grid = observation['data']
    rows = len(grid)
    cols = len(grid[0])

    if rows % 2 or cols % 2:
        return "No Solution"

    base_row_patterns = all_patterns(cols)
    base_col_patterns = all_patterns(rows)

    hcons = row_constraints(observation)
    vcons = col_constraints(observation)

    row_domains = []
    for r in range(rows):
        dom = [p for p in base_row_patterns if pattern_fits_row(p, r, observation, hcons)]
        if not dom:
            return "No Solution"
        row_domains.append(dom)

    col_domains = []
    for c in range(cols):
        dom = [p for p in base_col_patterns if pattern_fits_col(p, c, observation, vcons)]
        if not dom:
            return "No Solution"
        col_domains.append(dom)

    ans = search(row_domains, col_domains)
    if ans is None:
        return "No Solution"

    row_domains, _ = ans
    final_grid = [bits_to_row(dom[0]) for dom in row_domains]
    return str(final_grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'region': [[0, 0, 1, 1, 2, 2, 2, 2], [0, 0, 3, 3, 3, 4, 5, 6], [7, 8, 3, 3, 3, 9, 9, 6], [7, 8, 3, 3, 3, 9, 9, 6], [7, 10, 10, 11, 12, 9, 9, 6], [7, 10, 10, 11, 12, 9, 9, 6], [13, 13, 13, 11, 12, 14, 14, 6], [13, 13, 13, 15, 15, 16, 16, 16]], 'data': [[2, None, None, None, 0, None, None, None], [None, None, None, None, None, None, 1, None], [None, 0, None, None, None, 2, None, None], [None, None, None, None, None, None, None, None], [None, 1, None, 2, None, None, None, None], [None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None], [None, None, None, None, None, 0, None, None]]}

from collections import deque, defaultdict

UNDECIDED = -1
WHITE = 0
BLACK = 1


def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])
    size = n * m

    def idx(r, c):
        return r * m + c

    def rc(i):
        return divmod(i, m)

    cells = list(range(size))
    regions = defaultdict(list)
    clues = {}
    for r in range(n):
        for c in range(m):
            i = idx(r, c)
            rid = region[r][c]
            regions[rid].append(i)
            if data[r][c] is not None:
                clues[rid] = data[r][c]

    neigh = [[] for _ in range(size)]
    for r in range(n):
        for c in range(m):
            i = idx(r, c)
            if r > 0:
                neigh[i].append(idx(r - 1, c))
            if r + 1 < n:
                neigh[i].append(idx(r + 1, c))
            if c > 0:
                neigh[i].append(idx(r, c - 1))
            if c + 1 < m:
                neigh[i].append(idx(r, c + 1))

    # Precompute triple-region line constraints:
    # for every row/col, any run crossing 3 consecutive region-blocks must contain a black.
    intervals = []
    for r in range(n):
        blocks = []
        start = 0
        while start < m:
            rid = region[r][start]
            end = start
            while end + 1 < m and region[r][end + 1] == rid:
                end += 1
            blocks.append((start, end))
            start = end + 1
        for k in range(len(blocks) - 2):
            a = blocks[k][0]
            b = blocks[k + 2][1]
            interval = [idx(r, c) for c in range(a, b + 1)]
            intervals.append(tuple(interval))

    for c in range(m):
        blocks = []
        start = 0
        while start < n:
            rid = region[start][c]
            end = start
            while end + 1 < n and region[end + 1][c] == rid:
                end += 1
            blocks.append((start, end))
            start = end + 1
        for k in range(len(blocks) - 2):
            a = blocks[k][0]
            b = blocks[k + 2][1]
            interval = [idx(r, c) for r in range(a, b + 1)]
            intervals.append(tuple(interval))

    # Precompute all internal non-touching black patterns for numbered regions.
    numbered_patterns = {}
    for rid, k in clues.items():
        reg_cells = regions[rid]
        L = len(reg_cells)
        local_adj = [[False] * L for _ in range(L)]
        pos = {reg_cells[i]: i for i in range(L)}
        for i, a in enumerate(reg_cells):
            for b in neigh[a]:
                if b in pos:
                    local_adj[i][pos[b]] = True

        pats = []
        chosen = []

        def gen(start, need):
            if need == 0:
                mask = [0] * L
                for t in chosen:
                    mask[t] = 1
                pats.append(tuple(mask))
                return
            if start >= L:
                return
            if L - start < need:
                return
            # skip
            gen(start + 1, need)
            # take if not adjacent to chosen
            ok = True
            for t in chosen:
                if local_adj[start][t]:
                    ok = False
                    break
            if ok:
                chosen.append(start)
                gen(start + 1, need - 1)
                chosen.pop()

        gen(0, k)
        numbered_patterns[rid] = (reg_cells, pats)

    interval_of_cell = [[] for _ in range(size)]
    for q, inter in enumerate(intervals):
        for i in inter:
            interval_of_cell[i].append(q)

    def clone_state(state):
        return state[:]

    def assign(state, i, val, queue):
        cur = state[i]
        if cur == val:
            return True
        if cur != UNDECIDED:
            return False
        state[i] = val
        queue.append(i)
        return True

    def black_possible(state, i):
        if state[i] == BLACK:
            return True
        if state[i] != UNDECIDED:
            return False
        for j in neigh[i]:
            if state[j] == BLACK:
                return False
        return True

    def filter_region_patterns(state, rid):
        reg_cells, pats = numbered_patterns[rid]
        good = []
        for pat in pats:
            ok = True
            for t, cell in enumerate(reg_cells):
                want_black = pat[t] == 1
                s = state[cell]
                if want_black:
                    if s == WHITE:
                        ok = False
                        break
                    # external adjacency to known black
                    for nb in neigh[cell]:
                        if region[nb // m][nb % m] != rid and state[nb] == BLACK:
                            ok = False
                            break
                    if not ok:
                        break
                else:
                    if s == BLACK:
                        ok = False
                        break
            if ok:
                good.append(pat)
        return reg_cells, good

    def potential_white_components(state):
        # graph on cells not fixed black
        vis = [False] * size
        comps = []
        for i in cells:
            if state[i] == BLACK or vis[i]:
                continue
            comp = []
            dq = [i]
            vis[i] = True
            has_white = False
            while dq:
                x = dq.pop()
                comp.append(x)
                if state[x] == WHITE:
                    has_white = True
                for y in neigh[x]:
                    if state[y] != BLACK and not vis[y]:
                        vis[y] = True
                        dq.append(y)
            comps.append((comp, has_white))
        return comps

    def whites_connected_final_possible(state):
        comps = potential_white_components(state)
        white_comps = [comp for comp, has_white in comps if has_white]
        return len(white_comps) <= 1

    def force_connectivity_cells(state, queue):
        # If removing an undecided cell disconnects existing white cells, it must be white.
        white_cells = [i for i in cells if state[i] == WHITE]
        if len(white_cells) <= 1:
            return True
        nonblack = [i for i in cells if state[i] != BLACK]
        nonblack_set = set(nonblack)
        for v in nonblack:
            if state[v] != UNDECIDED:
                continue
            start = None
            for w in white_cells:
                if w != v:
                    start = w
                    break
            if start is None:
                continue
            seen = {start}
            dq = [start]
            while dq:
                x = dq.pop()
                for y in neigh[x]:
                    if y == v or y not in nonblack_set or y in seen:
                        continue
                    seen.add(y)
                    dq.append(y)
            bad = False
            for w in white_cells:
                if w != v and w not in seen:
                    bad = True
                    break
            if bad:
                if not assign(state, v, WHITE, queue):
                    return False
        return True

    def propagate(state):
        queue = deque(i for i in cells if state[i] != UNDECIDED)

        # Initial adjacency propagation from any preset black (normally none)
        while True:
            changed = False

            # Rule: black forbids orthogonal black neighbors.
            while queue:
                i = queue.popleft()
                if state[i] == BLACK:
                    for j in neigh[i]:
                        if not assign(state, j, WHITE, queue):
                            if state[j] != WHITE:
                                return None
                            continue
                        changed = True

            # Numbered region pattern filtering and forcing.
            for rid in clues:
                reg_cells, good = filter_region_patterns(state, rid)
                if not good:
                    return None
                for t, cell in enumerate(reg_cells):
                    all_black = all(p[t] == 1 for p in good)
                    all_white = all(p[t] == 0 for p in good)
                    if all_black:
                        if not black_possible(state, cell):
                            return None
                        if not assign(state, cell, BLACK, queue):
                            return None
                        changed = True
                    elif all_white:
                        if not assign(state, cell, WHITE, queue):
                            return None
                        changed = True

            # Line interval forcing: each interval must contain at least one black.
            for inter in intervals:
                has_black = any(state[i] == BLACK for i in inter)
                if has_black:
                    continue
                possibles = [i for i in inter if black_possible(state, i)]
                if not possibles:
                    return None
                if len(possibles) == 1:
                    if not assign(state, possibles[0], BLACK, queue):
                        return None
                    changed = True

            # Global possibility: all confirmed whites must still be connectable through non-black cells.
            if not whites_connected_final_possible(state):
                return None

            # Connectivity forcing.
            if not force_connectivity_cells(state, queue):
                return None
            if queue:
                changed = True

            if not changed:
                break

        return state

    def final_check(state):
        # Exact region counts
        for rid, k in clues.items():
            cnt = sum(1 for i in regions[rid] if state[i] == BLACK)
            if cnt != k:
                return False

        # Black adjacency
        for i in cells:
            if state[i] == BLACK:
                for j in neigh[i]:
                    if state[j] == BLACK:
                        return False

        # Line rule
        for inter in intervals:
            if all(state[i] != BLACK for i in inter):
                return False

        # White connectivity
        whites = [i for i in cells if state[i] != BLACK]
        if not whites:
            return False
        seen = {whites[0]}
        dq = [whites[0]]
        while dq:
            x = dq.pop()
            for y in neigh[x]:
                if state[y] != BLACK and y not in seen:
                    seen.add(y)
                    dq.append(y)
        return len(seen) == len(whites)

    def choose_branch_cell(state):
        best = None
        best_score = None
        for i in cells:
            if state[i] != UNDECIDED:
                continue
            score = 0
            rid = region[i // m][i % m]
            if rid in clues:
                reg_cells, good = filter_region_patterns(state, rid)
                # More constrained regions -> higher score
                score += 100 - len(good)
                black_freq = sum(1 for p in good if p[reg_cells.index(i)] == 1)
                score += min(black_freq, len(good) - black_freq)
            score += 5 * len(interval_of_cell[i])
            # fewer black options nearby means more constrained
            blocked = sum(1 for j in neigh[i] if state[j] == BLACK)
            score += 20 * blocked
            if best is None or score > best_score:
                best = i
                best_score = score
        return best

    def branch_values(state, i):
        vals = []
        if black_possible(state, i):
            vals.append(BLACK)
        vals.append(WHITE)
        rid = region[i // m][i % m]
        # Small heuristic: if interval pressure or region needs blacks, try BLACK first.
        if rid in clues:
            reg = regions[rid]
            k = clues[rid]
            fixed_black = sum(1 for x in reg if state[x] == BLACK)
            undec = sum(1 for x in reg if state[x] == UNDECIDED)
            if k - fixed_black <= undec // 2 and BLACK in vals:
                return vals
        black_need = 0
        for q in interval_of_cell[i]:
            inter = intervals[q]
            if not any(state[x] == BLACK for x in inter):
                black_need += 1
        if black_need == 0:
            return [WHITE] + ([BLACK] if BLACK in vals else [])
        return vals

    def dfs(state):
        state = propagate(state)
        if state is None:
            return None
        if all(v != UNDECIDED for v in state):
            return state if final_check(state) else None

        i = choose_branch_cell(state)
        for val in branch_values(state, i):
            new_state = clone_state(state)
            q = deque()
            if val == BLACK and not black_possible(new_state, i):
                continue
            if not assign(new_state, i, val, q):
                continue
            # seed queue for immediate local propagation
            while q:
                x = q.popleft()
                if new_state[x] == BLACK:
                    for y in neigh[x]:
                        if not assign(new_state, y, WHITE, q):
                            if new_state[y] != WHITE:
                                break
            ans = dfs(new_state)
            if ans is not None:
                return ans
        return None

    init = [UNDECIDED] * size
    sol = dfs(init)
    if sol is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            row.append('B' if sol[idx(r, c)] == BLACK else None)
        out.append(row)
    return str(out)


