    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 'W', None, None], [None, 'B', None, None, 'W', None], [None, 'W', None, None, None, None], [None, None, None, None, 'W', 'B'], ['W', 'B', 'W', None, None, 'W'], [None, None, None, None, None, None]]}

from collections import deque

# Directions encoded as bits on a vertex:
# U=1, R=2, D=4, L=8
U, R, D, L = 1, 2, 4, 8
DIRS = [U, R, D, L]
OPP = {U: D, D: U, L: R, R: L}
DRC = {U: (-1, 0), R: (0, 1), D: (1, 0), L: (0, -1)}

EMPTY = 0
STRAIGHT_V = U | D
STRAIGHT_H = L | R
TURN_UR = U | R
TURN_RD = R | D
TURN_DL = D | L
TURN_LU = L | U

ALL_PATTERNS = [EMPTY, STRAIGHT_V, STRAIGHT_H, TURN_UR, TURN_RD, TURN_DL, TURN_LU]
TURN_PATTERNS = {TURN_UR, TURN_RD, TURN_DL, TURN_LU}
STRAIGHT_PATTERNS = {STRAIGHT_V, STRAIGHT_H}

def bitcount(x):
    return (x & 1) + ((x >> 1) & 1) + ((x >> 2) & 1) + ((x >> 3) & 1)

def has_dir(mask, d):
    return (mask & d) != 0

def is_turn(mask):
    return mask in TURN_PATTERNS

def is_straight(mask):
    return mask in STRAIGHT_PATTERNS

def allowed_base_patterns(clue, avail_mask):
    pats = []
    for p in ALL_PATTERNS:
        if p & ~avail_mask:
            continue
        if p != 0 and bitcount(p) != 2:
            continue
        if clue == 'W':
            if p not in STRAIGHT_PATTERNS:
                continue
        elif clue == 'B':
            if p not in TURN_PATTERNS:
                continue
        pats.append(p)
    return set(pats)

class Solver:
    def __init__(self, observation):
        self.grid = observation['data']
        self.n = len(self.grid)
        self.verts = [(r, c) for r in range(self.n) for c in range(self.n)]
        self.idx = {rc: i for i, rc in enumerate(self.verts)}
        self.nei = {}
        self.avail_mask = {}
        for r, c in self.verts:
            m = 0
            if r > 0: m |= U
            if c < self.n - 1: m |= R
            if r < self.n - 1: m |= D
            if c > 0: m |= L
            self.avail_mask[(r, c)] = m
            ns = {}
            for d, (dr, dc) in DRC.items():
                rr, cc = r + dr, c + dc
                ns[d] = (rr, cc) if 0 <= rr < self.n and 0 <= cc < self.n else None
            self.nei[(r, c)] = ns

    def initial_domains(self):
        domains = {}
        for r, c in self.verts:
            clue = self.grid[r][c]
            domains[(r, c)] = allowed_base_patterns(clue, self.avail_mask[(r, c)])
            if not domains[(r, c)]:
                return None
        return domains

    def edge_possible(self, domains, v, d):
        w = self.nei[v][d]
        if w is None:
            return {False}
        vals = set()
        for pv in domains[v]:
            need = has_dir(pv, d)
            ok = False
            for pw in domains[w]:
                if has_dir(pw, OPP[d]) == need:
                    ok = True
                    break
            if ok:
                vals.add(need)
        return vals

    def pattern_supported_by_edges(self, domains, v, p):
        for d in DIRS:
            w = self.nei[v][d]
            want = has_dir(p, d)
            if w is None:
                if want:
                    return False
                continue
            found = False
            for q in domains[w]:
                if has_dir(q, OPP[d]) == want:
                    found = True
                    break
            if not found:
                return False
        return True

    def white_pattern_supported(self, domains, v, p):
        if p == STRAIGHT_H:
            left = self.nei[v][L]
            right = self.nei[v][R]
            if left is None or right is None:
                return False
            left_turn = any(has_dir(q, R) and is_turn(q) for q in domains[left])
            right_turn = any(has_dir(q, L) and is_turn(q) for q in domains[right])
            return left_turn or right_turn
        if p == STRAIGHT_V:
            up = self.nei[v][U]
            down = self.nei[v][D]
            if up is None or down is None:
                return False
            up_turn = any(has_dir(q, D) and is_turn(q) for q in domains[up])
            down_turn = any(has_dir(q, U) and is_turn(q) for q in domains[down])
            return up_turn or down_turn
        return False

    def black_pattern_supported(self, domains, v, p):
        if p == TURN_UR:
            a = self.nei[v][U]
            b = self.nei[v][R]
            if a is None or b is None:
                return False
            ok_a = any(q == STRAIGHT_V for q in domains[a])
            ok_b = any(q == STRAIGHT_H for q in domains[b])
            return ok_a and ok_b
        if p == TURN_RD:
            a = self.nei[v][R]
            b = self.nei[v][D]
            if a is None or b is None:
                return False
            ok_a = any(q == STRAIGHT_H for q in domains[a])
            ok_b = any(q == STRAIGHT_V for q in domains[b])
            return ok_a and ok_b
        if p == TURN_DL:
            a = self.nei[v][D]
            b = self.nei[v][L]
            if a is None or b is None:
                return False
            ok_a = any(q == STRAIGHT_V for q in domains[a])
            ok_b = any(q == STRAIGHT_H for q in domains[b])
            return ok_a and ok_b
        if p == TURN_LU:
            a = self.nei[v][L]
            b = self.nei[v][U]
            if a is None or b is None:
                return False
            ok_a = any(q == STRAIGHT_H for q in domains[a])
            ok_b = any(q == STRAIGHT_V for q in domains[b])
            return ok_a and ok_b
        return False

    def local_supported(self, domains, v, p):
        if not self.pattern_supported_by_edges(domains, v, p):
            return False
        clue = self.grid[v[0]][v[1]]
        if clue == 'W':
            return self.white_pattern_supported(domains, v, p)
        if clue == 'B':
            return self.black_pattern_supported(domains, v, p)
        return True

    def propagate(self, domains):
        q = deque(self.verts)
        inq = set(self.verts)
        while q:
            v = q.popleft()
            inq.discard(v)
            old = domains[v]
            new = {p for p in old if self.local_supported(domains, v, p)}
            if not new:
                return None
            if new != old:
                domains[v] = new
                for d in DIRS:
                    w = self.nei[v][d]
                    if w is not None and w not in inq:
                        q.append(w)
                        inq.add(w)
                if v not in inq:
                    q.append(v)
                    inq.add(v)
        if not self.global_prune(domains):
            return None
        return domains

    def forced_edges(self, domains):
        forced_on = set()
        forced_off = set()
        for v in self.verts:
            for d in (R, D):
                w = self.nei[v][d]
                if w is None:
                    continue
                vals = self.edge_possible(domains, v, d)
                e = (v, w)
                if vals == {True}:
                    forced_on.add(e)
                elif vals == {False}:
                    forced_off.add(e)
        return forced_on, forced_off

    def global_prune(self, domains):
        forced_on, _ = self.forced_edges(domains)

        # A clue must still be able to connect via the forced/potential graph.
        # Also reject any already-completed smaller cycle made solely of fixed singleton vertices.
        deg_forced = {v: 0 for v in self.verts}
        adj_forced = {v: [] for v in self.verts}
        for a, b in forced_on:
            deg_forced[a] += 1
            deg_forced[b] += 1
            adj_forced[a].append(b)
            adj_forced[b].append(a)

        # Impossible forced degree > 2
        for v in self.verts:
            if deg_forced[v] > 2:
                return False

        # Completed subtour check on singleton non-empty vertices.
        fixed_nonempty = {v for v in self.verts if len(domains[v]) == 1 and next(iter(domains[v])) != EMPTY}
        seen = set()
        for v in fixed_nonempty:
            if v in seen:
                continue
            comp = []
            stack = [v]
            seen.add(v)
            while stack:
                x = stack.pop()
                comp.append(x)
                for y in adj_forced[x]:
                    if y in fixed_nonempty and y not in seen:
                        seen.add(y)
                        stack.append(y)
            # If every vertex in this component is fixed non-empty and has forced degree 2,
            # then it is already a closed cycle. This is only allowed if it could be the final loop.
            if comp and all(deg_forced[x] == 2 for x in comp):
                all_required = {v2 for v2 in self.verts if self.grid[v2[0]][v2[1]] is not None}
                loop_set = set(comp)
                # Final loop only if every non-empty fixed vertex is in it and every clue is in it
                any_other_possible = any(
                    v2 not in loop_set and any(p != EMPTY for p in domains[v2])
                    for v2 in self.verts
                )
                if all_required - loop_set or any_other_possible:
                    return False

        # Potential reachability among all clue vertices through potentially used edges.
        clue_vertices = [v for v in self.verts if self.grid[v[0]][v[1]] is not None]
        if clue_vertices:
            start = clue_vertices[0]
            seen = {start}
            stack = [start]
            while stack:
                v = stack.pop()
                for d in DIRS:
                    w = self.nei[v][d]
                    if w is None:
                        continue
                    vals = self.edge_possible(domains, v, d)
                    if True in vals and w not in seen:
                        seen.add(w)
                        stack.append(w)
            for cv in clue_vertices:
                if cv not in seen:
                    return False

        return True

    def choose_branch_vertex(self, domains):
        best = None
        best_key = None
        for v in self.verts:
            if len(domains[v]) > 1:
                # Prefer clue vertices, then smaller domain, then more constrained potential degree
                clue = self.grid[v[0]][v[1]]
                pot_edges = sum(True in self.edge_possible(domains, v, d) for d in DIRS if self.nei[v][d] is not None)
                key = (0 if clue is not None else 1, len(domains[v]), pot_edges)
                if best is None or key < best_key:
                    best = v
                    best_key = key
        return best

    def order_patterns(self, v, pats):
        clue = self.grid[v[0]][v[1]]
        pats = list(pats)
        # Human-like preference: clues first already handled; for non-clue prefer non-empty before empty.
        if clue is None:
            pats.sort(key=lambda p: (p == EMPTY, 0 if p in STRAIGHT_PATTERNS else 1))
        else:
            pats.sort(key=lambda p: 0 if p in STRAIGHT_PATTERNS else 1)
        return pats

    def build_solution_path(self, domains):
        patt = {v: next(iter(domains[v])) for v in self.verts}
        used = {v for v, p in patt.items() if p != EMPTY}
        if not used:
            return None

        adj = {v: [] for v in used}
        for v in used:
            p = patt[v]
            for d in DIRS:
                if has_dir(p, d):
                    w = self.nei[v][d]
                    if w not in used:
                        return None
                    if not has_dir(patt[w], OPP[d]):
                        return None
                    adj[v].append(w)

        for v in used:
            if len(adj[v]) != 2:
                return None

        # Single cycle covering all used vertices
        start = min(used)
        path = [start]
        prev = None
        cur = start
        while True:
            ns = adj[cur]
            nxt = ns[0] if ns[0] != prev else ns[1]
            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break
            if len(path) > len(used) + 1:
                return None

        if len(path) != len(used) + 1:
            return None
        if set(path[:-1]) != used:
            return None

        # Ensure every clue is used
        for v in self.verts:
            clue = self.grid[v[0]][v[1]]
            if clue is not None and v not in used:
                return None

        return path

    def search(self, domains):
        domains = {v: set(ps) for v, ps in domains.items()}
        domains = self.propagate(domains)
        if domains is None:
            return None

        if all(len(domains[v]) == 1 for v in self.verts):
            return self.build_solution_path(domains)

        v = self.choose_branch_vertex(domains)
        if v is None:
            return None

        for p in self.order_patterns(v, domains[v]):
            new_domains = {x: set(domains[x]) for x in self.verts}
            new_domains[v] = {p}
            ans = self.search(new_domains)
            if ans is not None:
                return ans
        return None

def solve(observation):
    solver = Solver(observation)
    domains = solver.initial_domains()
    if domains is None:
        return "No Solution"
    ans = solver.search(domains)
    return str(ans) if ans is not None else "No Solution"

