# Black-cell sum puzzle solver.
# General model used here:
# - Grid size is len(row_sum) x len(col_sum)
# - Row weights are 0..R-1 (top to bottom)
# - Column weights are 0..C-1 (left to right)
# - A black cell at (r, c) contributes:
#     * column weight c to row r's target
#     * row weight r to column c's target
#
# The solver is designed around human-like deduction:
# 1. Enumerate all feasible row patterns and column patterns.
# 2. Repeatedly propagate consistency between row/column pattern sets.
# 3. If unresolved, branch on the most constrained row/column pattern domain.
#
# This avoids naive cell-by-cell brute force and instead searches over
# highly pruned subset-sum-compatible line patterns.

from collections import defaultdict


def generate_masks_by_target(weights):
    n = len(weights)
    groups = defaultdict(list)
    # Enumerate all masks once; efficient for typical puzzle sizes.
    for mask in range(1 << n):
        s = 0
        m = mask
        i = 0
        while m:
            if m & 1:
                s += weights[i]
            i += 1
            m >>= 1
        groups[s].append(mask)
    return groups


def bit_supported(patterns, bit_index):
    has0 = False
    has1 = False
    b = 1 << bit_index
    for m in patterns:
        if m & b:
            has1 = True
        else:
            has0 = True
        if has0 and has1:
            return 3
    if has1:
        return 2
    if has0:
        return 1
    return 0


def filter_patterns_against_support(patterns, bit_to_supported_value):
    # bit_to_supported_value[bit] is:
    #   1 => only 0 supported
    #   2 => only 1 supported
    #   3 => both supported
    changed = False
    kept = []
    for m in patterns:
        ok = True
        for bit, sup in bit_to_supported_value.items():
            v = 2 if (m >> bit) & 1 else 1
            if not (sup & v):
                ok = False
                break
        if ok:
            kept.append(m)
    if len(kept) != len(patterns):
        changed = True
    return kept, changed


def propagate(row_poss, col_poss, R, C):
    # Constraint propagation until fixpoint.
    while True:
        changed = False

        # Precompute support status for each row-bit and col-bit.
        row_support = [[0] * C for _ in range(R)]
        col_support = [[0] * R for _ in range(C)]

        for r in range(R):
            pats = row_poss[r]
            if not pats:
                return None
            for c in range(C):
                row_support[r][c] = bit_supported(pats, c)

        for c in range(C):
            pats = col_poss[c]
            if not pats:
                return None
            for r in range(R):
                col_support[c][r] = bit_supported(pats, r)

        # Cross-filter using cell agreements.
        for r in range(R):
            restrictions = {}
            for c in range(C):
                allowed = row_support[r][c] & col_support[c][r]
                if allowed == 0:
                    return None
                if allowed != 3:
                    restrictions[c] = allowed
            if restrictions:
                new_pats, ch = filter_patterns_against_support(row_poss[r], restrictions)
                if not new_pats:
                    return None
                if ch:
                    row_poss[r] = new_pats
                    changed = True

        for c in range(C):
            restrictions = {}
            for r in range(R):
                allowed = row_support[r][c] & col_support[c][r]
                if allowed == 0:
                    return None
                if allowed != 3:
                    restrictions[r] = allowed
            if restrictions:
                new_pats, ch = filter_patterns_against_support(col_poss[c], restrictions)
                if not new_pats:
                    return None
                if ch:
                    col_poss[c] = new_pats
                    changed = True

        if not changed:
            return row_poss, col_poss


def is_solved(row_poss, col_poss):
    return all(len(p) == 1 for p in row_poss) and all(len(p) == 1 for p in col_poss)


def choose_branch(row_poss, col_poss):
    best_kind = None
    best_idx = None
    best_size = 10**9

    for i, pats in enumerate(row_poss):
        lp = len(pats)
        if 1 < lp < best_size:
            best_size = lp
            best_kind = "row"
            best_idx = i

    for i, pats in enumerate(col_poss):
        lp = len(pats)
        if 1 < lp < best_size:
            best_size = lp
            best_kind = "col"
            best_idx = i

    return best_kind, best_idx


def search(row_poss, col_poss, R, C):
    state = propagate(row_poss, col_poss, R, C)
    if state is None:
        return None
    row_poss, col_poss = state

    if is_solved(row_poss, col_poss):
        return row_poss, col_poss

    kind, idx = choose_branch(row_poss, col_poss)
    if kind is None:
        return None

    if kind == "row":
        candidates = sorted(
            row_poss[idx],
            key=lambda m: bin(m).count("1")
        )
        for mask in candidates:
            new_row = [p[:] for p in row_poss]
            new_col = [p[:] for p in col_poss]
            new_row[idx] = [mask]
            res = search(new_row, new_col, R, C)
            if res is not None:
                return res
    else:
        candidates = sorted(
            col_poss[idx],
            key=lambda m: bin(m).count("1")
        )
        for mask in candidates:
            new_row = [p[:] for p in row_poss]
            new_col = [p[:] for p in col_poss]
            new_col[idx] = [mask]
            res = search(new_row, new_col, R, C)
            if res is not None:
                return res

    return None


def build_answer(row_poss, R, C):
    grid = []
    for r in range(R):
        mask = row_poss[r][0]
        row = []
        for c in range(C):
            row.append('B' if ((mask >> c) & 1) else None)
        grid.append(row)
    return grid


def solve(observation):
    row_sum = observation['row_sum']
    col_sum = observation['col_sum']
    R = len(row_sum)
    C = len(col_sum)

    row_weights = list(range(R))
    col_weights = list(range(C))

    row_groups = generate_masks_by_target(col_weights)
    col_groups = generate_masks_by_target(row_weights)

    row_poss = []
    for target in row_sum:
        pats = row_groups.get(target, [])
        if not pats:
            return "No Solution"
        row_poss.append(pats[:])

    col_poss = []
    for target in col_sum:
        pats = col_groups.get(target, [])
        if not pats:
            return "No Solution"
        col_poss.append(pats[:])

    res = search(row_poss, col_poss, R, C)
    if res is None:
        return "No Solution"

    row_poss, col_poss = res
    answer = build_answer(row_poss, R, C)
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

