# General solver for a numbered loop puzzle on lattice points.
# Clues live on vertices. White clues force straight passage; black clues force a turn.
# The clue number is the sum of lengths of the two straight runs extending from the clue
# until the path turns at each side.

from collections import deque

U, R, D, L = 1, 2, 4, 8
DIRS = [U, R, D, L]
DR = {U: -1, R: 0, D: 1, L: 0}
DC = {U: 0, R: 1, D: 0, L: -1}
OPP = {U: D, D: U, L: R, R: L}
PERP = {
    U: (L, R),
    D: (L, R),
    L: (U, D),
    R: (U, D),
}

STATE_MASKS = [
    0,          # empty
    U | D,      # vertical
    L | R,      # horizontal
    U | R,      # turn UR
    R | D,      # turn RD
    D | L,      # turn DL
    L | U,      # turn LU
]
MASK_TO_STATE = {m: i for i, m in enumerate(STATE_MASKS)}

STRAIGHT_STATES = {MASK_TO_STATE[U | D], MASK_TO_STATE[L | R]}
TURN_STATES = {
    MASK_TO_STATE[U | R],
    MASK_TO_STATE[R | D],
    MASK_TO_STATE[D | L],
    MASK_TO_STATE[L | U],
}
NONEMPTY_STATES = set(range(1, 7))

def state_has_dir(state, d):
    return bool(STATE_MASKS[state] & d)

def state_dirs(state):
    m = STATE_MASKS[state]
    return tuple(d for d in DIRS if m & d)

def in_bounds(n, r, c):
    return 0 <= r <= n and 0 <= c <= n

def neighbor_of(v, d):
    r, c = v
    return (r + DR[d], c + DC[d])

def compatible_along_edge(s1, d, s2):
    return state_has_dir(s1, d) == state_has_dir(s2, OPP[d])

def edge_possible(domains, v, d, n):
    w = neighbor_of(v, d)
    if not in_bounds(n, *w):
        return False
    for s1 in domains[v]:
        if state_has_dir(s1, d):
            for s2 in domains[w]:
                if state_has_dir(s2, OPP[d]):
                    return True
    return False

def edge_forced(domains, v, d, n):
    w = neighbor_of(v, d)
    if not in_bounds(n, *w):
        return False
    ok = False
    for s1 in domains[v]:
        for s2 in domains[w]:
            if compatible_along_edge(s1, d, s2):
                ok = True
                if not (state_has_dir(s1, d) and state_has_dir(s2, OPP[d])):
                    return False
    return ok

def initial_domains(observation):
    data = observation["data"]
    n = len(data) - 1
    domains = {}
    clues = []
    for r in range(n + 1):
        for c in range(n + 1):
            token = data[r][c]
            allowed = set(range(7))
            # boundary filtering
            bad_dirs = set()
            if r == 0:
                bad_dirs.add(U)
            if r == n:
                bad_dirs.add(D)
            if c == 0:
                bad_dirs.add(L)
            if c == n:
                bad_dirs.add(R)
            if bad_dirs:
                allowed = {s for s in allowed if not any(state_has_dir(s, d) for d in bad_dirs)}
            if token is not None:
                t = token[0]
                k = int(token[1:])
                clues.append(((r, c), t, k))
                allowed.discard(0)
                if t == "W":
                    allowed &= STRAIGHT_STATES
                else:
                    allowed &= TURN_STATES
            domains[(r, c)] = allowed
    return n, domains, clues

def apply_vertex_restrictions(domains, restrictions):
    for v, allowed in restrictions.items():
        nd = domains[v] & allowed
        if not nd:
            return False
        domains[v] = nd
    return True

def generate_patterns_for_clue(n, pos, clue_type, k):
    r, c = pos
    patterns = []

    if clue_type == "W":
        local_masks = [U | D, L | R]
    else:
        local_masks = [U | R, R | D, D | L, L | U]

    for local_mask in local_masks:
        dirs = [d for d in DIRS if local_mask & d]
        for a in range(1, k):
            b = k - a
            lens = [a, b]
            restrictions = {pos: {MASK_TO_STATE[local_mask]}}
            ok = True
            for d, length in zip(dirs, lens):
                prev = pos
                for step in range(1, length + 1):
                    cur = (prev[0] + DR[d], prev[1] + DC[d])
                    if not in_bounds(n, *cur):
                        ok = False
                        break
                    if step < length:
                        req_mask = U | D if d in (U, D) else L | R
                        allowed = {MASK_TO_STATE[req_mask]}
                    else:
                        allowed = set()
                        for pd in PERP[d]:
                            allowed.add(MASK_TO_STATE[OPP[d] | pd])
                    if cur in restrictions:
                        restrictions[cur] &= allowed
                    else:
                        restrictions[cur] = set(allowed)
                    if not restrictions[cur]:
                        ok = False
                        break
                    prev = cur
                if not ok:
                    break
            if ok:
                patterns.append(restrictions)

    # deduplicate patterns
    seen = set()
    out = []
    for pat in patterns:
        key = tuple(sorted((v, tuple(sorted(s))) for v, s in pat.items()))
        if key not in seen:
            seen.add(key)
            out.append(pat)
    return out

def revise_vertex_arc(domains, n, queue):
    while queue:
        v = queue.popleft()
        if not domains[v]:
            return False
        for d in DIRS:
            w = neighbor_of(v, d)
            if not in_bounds(n, *w):
                continue
            new_dom = set()
            for sv in domains[v]:
                if any(compatible_along_edge(sv, d, sw) for sw in domains[w]):
                    new_dom.add(sv)
            if new_dom != domains[v]:
                if not new_dom:
                    return False
                domains[v] = new_dom
                for d2 in DIRS:
                    u = neighbor_of(v, d2)
                    if in_bounds(n, *u):
                        queue.append(u)
    return True

def filter_pattern_domains(domains, pattern_domains):
    changed = True
    while changed:
        changed = False
        for i, plist in enumerate(pattern_domains):
            new_plist = []
            for pat in plist:
                good = True
                for v, allowed in pat.items():
                    if not (domains[v] & allowed):
                        good = False
                        break
                if good:
                    new_plist.append(pat)
            if not new_plist:
                return False
            if len(new_plist) != len(plist):
                pattern_domains[i] = new_plist
                changed = True

            common = {}
            first = pattern_domains[i][0]
            for v in first:
                inter = set(first[v])
                exists_in_all = True
                for pat in pattern_domains[i][1:]:
                    if v not in pat:
                        exists_in_all = False
                        break
                    inter &= pat[v]
                if exists_in_all and inter:
                    common[v] = inter
            if common:
                for v, allowed in common.items():
                    nd = domains[v] & allowed
                    if not nd:
                        return False
                    if nd != domains[v]:
                        domains[v] = nd
                        changed = True
    return True

def propagate(domains, pattern_domains, n):
    while True:
        snap = (
            tuple(sorted((v, tuple(sorted(domains[v]))) for v in domains)),
            tuple(len(p) for p in pattern_domains),
        )
        q = deque(domains.keys())
        if not revise_vertex_arc(domains, n, q):
            return False
        if not filter_pattern_domains(domains, pattern_domains):
            return False
        snap2 = (
            tuple(sorted((v, tuple(sorted(domains[v]))) for v in domains)),
            tuple(len(p) for p in pattern_domains),
        )
        if snap == snap2:
            break
    return True

def copy_domains(domains):
    return {k: set(v) for k, v in domains.items()}

def copy_pattern_domains(pattern_domains):
    return [list(p) for p in pattern_domains]

def choose_branch(domains, pattern_domains):
    best = None
    best_kind = None

    for i, plist in enumerate(pattern_domains):
        if 1 < len(plist) and (best is None or len(plist) < best):
            best = len(plist)
            best_kind = ("pattern", i)

    for v, dom in domains.items():
        if 1 < len(dom) and (best is None or len(dom) < best):
            best = len(dom)
            best_kind = ("vertex", v)

    return best_kind

def finalize_edges(domains, n):
    chosen = {v: next(iter(domains[v])) for v in domains}
    edges = set()
    for v, s in chosen.items():
        for d in state_dirs(s):
            w = neighbor_of(v, d)
            if in_bounds(n, *w) and state_has_dir(chosen[w], OPP[d]):
                e = tuple(sorted((v, w)))
                edges.add(e)
    return chosen, edges

def check_single_loop(chosen, edges, clue_info):
    nonempty = [v for v, s in chosen.items() if s != 0]
    if not nonempty:
        return False

    adj = {v: [] for v in nonempty}
    for a, b in edges:
        if chosen[a] == 0 or chosen[b] == 0:
            return False
        adj[a].append(b)
        adj[b].append(a)
    if any(len(adj[v]) != 2 for v in nonempty):
        return False

    start = nonempty[0]
    seen = set()
    stack = [start]
    while stack:
        v = stack.pop()
        if v in seen:
            continue
        seen.add(v)
        stack.extend(adj[v])
    if len(seen) != len(nonempty):
        return False

    # Verify clue semantics exactly.
    for pos, t, k in clue_info:
        s = chosen[pos]
        if t == "W" and s not in STRAIGHT_STATES:
            return False
        if t == "B" and s not in TURN_STATES:
            return False

        ds = state_dirs(s)
        total = 0
        for d in ds:
            prev = pos
            cur = neighbor_of(prev, d)
            length = 1
            while True:
                cs = chosen[cur]
                dirs = state_dirs(cs)
                if len(dirs) != 2:
                    return False
                incoming = OPP[d]
                if incoming not in dirs:
                    return False
                outgoing = dirs[0] if dirs[1] == incoming else dirs[1]
                if outgoing != d:
                    break
                prev = cur
                cur = neighbor_of(cur, d)
                length += 1
            total += length
        if total != k:
            return False
    return True

def build_loop_path(edges):
    adj = {}
    for a, b in edges:
        adj.setdefault(a, []).append(b)
        adj.setdefault(b, []).append(a)
    start = min(adj)
    path = [start]
    prev = None
    cur = start
    while True:
        nbrs = adj[cur]
        nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
    return path

def search(domains, pattern_domains, n, clue_info):
    if not propagate(domains, pattern_domains, n):
        return None

    branch = choose_branch(domains, pattern_domains)
    if branch is None:
        if any(len(domains[v]) != 1 for v in domains):
            return None
        chosen, edges = finalize_edges(domains, n)
        if check_single_loop(chosen, edges, clue_info):
            return build_loop_path(edges)
        return None

    kind, item = branch
    if kind == "pattern":
        i = item
        # Heuristic: try patterns imposing more restrictions first.
        order = sorted(pattern_domains[i], key=lambda p: -len(p))
        for pat in order:
            nd = copy_domains(domains)
            npd = copy_pattern_domains(pattern_domains)
            npd[i] = [pat]
            if not apply_vertex_restrictions(nd, pat):
                continue
            ans = search(nd, npd, n, clue_info)
            if ans is not None:
                return ans
    else:
        v = item
        # Prefer non-empty states first, then more constrained.
        vals = sorted(domains[v], key=lambda s: (s == 0, s))
        for s in vals:
            nd = copy_domains(domains)
            npd = copy_pattern_domains(pattern_domains)
            nd[v] = {s}
            ans = search(nd, npd, n, clue_info)
            if ans is not None:
                return ans
    return None

def solve(observation):
    n, domains, clues = initial_domains(observation)
    pattern_domains = []
    for pos, t, k in clues:
        pats = generate_patterns_for_clue(n, pos, t, k)
        if not pats:
            return "No Solution"
        # Apply local clue restrictions already represented in patterns.
        pattern_domains.append(pats)

    ans = search(domains, pattern_domains, n, clues)
    return ans if ans is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

