from itertools import product

B, W = 1, 0
MAP_IN = {'B': B, 'W': W, None: None}
MAP_OUT = {B: 'B', W: 'W'}


def parse_key(s):
    s = s.strip()
    if s[0] == '(' and s[-1] == ')':
        a, b = s[1:-1].split(',')
        return float(a.strip()), float(b.strip())
    raise ValueError(s)


def all_valid_lines(n):
    half = n // 2
    out = []

    def rec(i, line, cb, cw):
        if cb > half or cw > half:
            return
        if i >= 3 and line[i - 1] == line[i - 2] == line[i - 3]:
            return
        rem = n - i
        if cb + rem < half or cw + rem < half:
            return
        if i == n:
            if cb == half and cw == half:
                out.append(tuple(line))
            return
        line.append(0)
        rec(i + 1, line, cb, cw + 1)
        line.pop()
        line.append(1)
        rec(i + 1, line, cb + 1, cw)
        line.pop()

    rec(0, [], 0, 0)
    return out


def solve(observation):
    data = observation['data']
    n = len(data)
    m = len(data[0])
    if n != m or n % 2:
        return "No Solution"

    grid = [[MAP_IN[v] for v in row] for row in data]

    horiz = {}
    for k, v in observation.get('horizontal', {}).items():
        r, c = parse_key(k)
        horiz[(int(r), int(c - 0.5))] = v  # edge between (r,c) and (r,c+1)

    vert = {}
    for k, v in observation.get('vertical', {}).items():
        r, c = parse_key(k)
        vert[(int(r - 0.5), int(c))] = v  # edge between (r,c) and (r+1,c)

    base_lines = all_valid_lines(n)

    def row_pattern_ok(r, patt):
        for c in range(n):
            g = grid[r][c]
            if g is not None and patt[c] != g:
                return False
        for c in range(n - 1):
            rel = horiz.get((r, c))
            if rel is None:
                continue
            if rel == '=' and patt[c] != patt[c + 1]:
                return False
            if rel == 'x' and patt[c] == patt[c + 1]:
                return False
        return True

    def col_pattern_ok(c, patt):
        for r in range(n):
            g = grid[r][c]
            if g is not None and patt[r] != g:
                return False
        for r in range(n - 1):
            rel = vert.get((r, c))
            if rel is None:
                continue
            if rel == '=' and patt[r] != patt[r + 1]:
                return False
            if rel == 'x' and patt[r] == patt[r + 1]:
                return False
        return True

    row_cands = [set(p for p in base_lines if row_pattern_ok(r, p)) for r in range(n)]
    col_cands = [set(p for p in base_lines if col_pattern_ok(c, p)) for c in range(n)]

    def cell_domain(r, c, row_sets, col_sets):
        vals_r = {p[c] for p in row_sets[r]}
        vals_c = {p[r] for p in col_sets[c]}
        return vals_r & vals_c

    def assign_cell(r, c, val, row_sets, col_sets, g):
        if g[r][c] is not None:
            return g[r][c] == val
        g[r][c] = val
        nr = {p for p in row_sets[r] if p[c] == val}
        if not nr:
            return False
        row_sets[r] = nr
        nc = {p for p in col_sets[c] if p[r] == val}
        if not nc:
            return False
        col_sets[c] = nc
        return True

    def propagate(row_sets, col_sets, g):
        changed = True
        while changed:
            changed = False

            # Remove candidates inconsistent with current cross-domains.
            for r in range(n):
                allowed = row_sets[r]
                newset = set()
                for p in allowed:
                    ok = True
                    for c in range(n):
                        if not any(cp[r] == p[c] for cp in col_sets[c]):
                            ok = False
                            break
                    if ok:
                        newset.add(p)
                if not newset:
                    return False
                if newset != allowed:
                    row_sets[r] = newset
                    changed = True

            for c in range(n):
                allowed = col_sets[c]
                newset = set()
                for p in allowed:
                    ok = True
                    for r in range(n):
                        if not any(rp[c] == p[r] for rp in row_sets[r]):
                            ok = False
                            break
                    if ok:
                        newset.add(p)
                if not newset:
                    return False
                if newset != allowed:
                    col_sets[c] = newset
                    changed = True

            # Solved-line uniqueness.
            solved_rows = {next(iter(s)) for s in row_sets if len(s) == 1}
            for r in range(n):
                if len(row_sets[r]) > 1:
                    newset = {p for p in row_sets[r] if p not in solved_rows}
                    if not newset:
                        return False
                    if newset != row_sets[r]:
                        row_sets[r] = newset
                        changed = True

            solved_cols = {next(iter(s)) for s in col_sets if len(s) == 1}
            for c in range(n):
                if len(col_sets[c]) > 1:
                    newset = {p for p in col_sets[c] if p not in solved_cols}
                    if not newset:
                        return False
                    if newset != col_sets[c]:
                        col_sets[c] = newset
                        changed = True

            # Cell forcing from row/col candidate intersections.
            for r in range(n):
                for c in range(n):
                    dom = cell_domain(r, c, row_sets, col_sets)
                    if not dom:
                        return False
                    if len(dom) == 1:
                        v = next(iter(dom))
                        if g[r][c] is None:
                            if not assign_cell(r, c, v, row_sets, col_sets, g):
                                return False
                            changed = True

            # If row/col candidates all agree on a cell, assign it.
            for r in range(n):
                for c in range(n):
                    vals = {p[c] for p in row_sets[r]}
                    if len(vals) == 1:
                        v = next(iter(vals))
                        if g[r][c] is None:
                            if not assign_cell(r, c, v, row_sets, col_sets, g):
                                return False
                            changed = True

            for c in range(n):
                for r in range(n):
                    vals = {p[r] for p in col_sets[c]}
                    if len(vals) == 1:
                        v = next(iter(vals))
                        if g[r][c] is None:
                            if not assign_cell(r, c, v, row_sets, col_sets, g):
                                return False
                            changed = True

        return True

    def is_solved(row_sets, col_sets):
        return all(len(s) == 1 for s in row_sets) and all(len(s) == 1 for s in col_sets)

    def clone_state(row_sets, col_sets, g):
        return [set(s) for s in row_sets], [set(s) for s in col_sets], [row[:] for row in g]

    def search(row_sets, col_sets, g):
        if not propagate(row_sets, col_sets, g):
            return None
        if is_solved(row_sets, col_sets):
            sol = [[next(iter(row_sets[r]))[c] for c in range(n)] for r in range(n)]
            return sol

        best_kind = None
        best_idx = None
        best_size = 10**9

        for r in range(n):
            sz = len(row_sets[r])
            if 1 < sz < best_size:
                best_kind, best_idx, best_size = 'row', r, sz
        for c in range(n):
            sz = len(col_sets[c])
            if 1 < sz < best_size:
                best_kind, best_idx, best_size = 'col', c, sz

        if best_kind == 'row':
            r = best_idx
            # Prefer patterns that maximize immediate agreements with columns.
            options = sorted(
                row_sets[r],
                key=lambda p: sum(1 for c in range(n) if any(cp[r] == p[c] for cp in col_sets[c])),
                reverse=True,
            )
            for p in options:
                rs, cs, gg = clone_state(row_sets, col_sets, g)
                rs[r] = {p}
                ok = True
                for c in range(n):
                    gg[r][c] = p[c]
                    cs[c] = {cp for cp in cs[c] if cp[r] == p[c]}
                    if not cs[c]:
                        ok = False
                        break
                if ok:
                    ans = search(rs, cs, gg)
                    if ans is not None:
                        return ans
        else:
            c = best_idx
            options = sorted(
                col_sets[c],
                key=lambda p: sum(1 for r in range(n) if any(rp[c] == p[r] for rp in row_sets[r])),
                reverse=True,
            )
            for p in options:
                rs, cs, gg = clone_state(row_sets, col_sets, g)
                cs[c] = {p}
                ok = True
                for r in range(n):
                    gg[r][c] = p[r]
                    rs[r] = {rp for rp in rs[r] if rp[c] == p[r]}
                    if not rs[r]:
                        ok = False
                        break
                if ok:
                    ans = search(rs, cs, gg)
                    if ans is not None:
                        return ans
        return None

    sol = search(row_cands, col_cands, grid)
    if sol is None:
        return "No Solution"
    return [[MAP_OUT[v] for v in row] for row in sol]


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 'B2', 'B2', None, None, None], [None, None, None, None, None, None, None, None], [None, None, 'B2', None, None, None, None, None], [None, None, None, None, None, None, None, None], [None, 'W5', 'W2', None, None, None, None, None], ['W7', None, None, 'W2', None, 'B2', 'W2', 'W7'], [None, None, None, None, None, None, 'B3', None], [None, None, 'B6', None, None, None, None, None]]}

from collections import deque

# Pattern encoding at each dot:
# 0: empty
# 1: horizontal (L,R)
# 2: vertical   (U,D)
# 3: turn U,R
# 4: turn R,D
# 5: turn D,L
# 6: turn L,U
PATTERNS = {
    0: 0b0000,  # U,R,D,L
    1: 0b0101,  # R,L
    2: 0b1010,  # U,D
    3: 0b0011,  # U,R
    4: 0b0110,  # R,D
    5: 0b1100,  # D,L
    6: 0b1001,  # L,U
}
ALL_PATTERNS = tuple(PATTERNS.keys())

U, R, D, L = 0, 1, 2, 3
DR = [(-1, 0), (0, 1), (1, 0), (0, -1)]
OPP = [2, 3, 0, 1]
DIRBIT = [1 << U, 1 << R, 1 << D, 1 << L]

EMPTY_ONLY = 1 << 0
WHITE_MASK = (1 << 1) | (1 << 2)
BLACK_MASK = (1 << 3) | (1 << 4) | (1 << 5) | (1 << 6)
NONCLUE_MASK = sum(1 << p for p in ALL_PATTERNS)

def bit_count(x):
    return x.bit_count()

def singleton_pattern(mask):
    if mask and (mask & (mask - 1)) == 0:
        return mask.bit_length() - 1
    return None

def iter_patterns(mask):
    while mask:
        b = mask & -mask
        yield b.bit_length() - 1
        mask ^= b

def pattern_has_dir(p, d):
    return bool(PATTERNS[p] & DIRBIT[d])

def is_straight_pattern(p):
    return p in (1, 2)

def is_turn_pattern(p):
    return p in (3, 4, 5, 6)

def clue_info(token):
    if token is None:
        return None, None
    return token[0], int(token[1:])

def allowed_mask_for_token(token):
    if token is None:
        return NONCLUE_MASK
    c, _ = clue_info(token)
    return WHITE_MASK if c == 'W' else BLACK_MASK

def neighbor(r, c, d, nrows, ncols):
    rr, cc = r + DR[d][0], c + DR[d][1]
    if 0 <= rr < nrows and 0 <= cc < ncols:
        return rr, cc
    return None

def build_initial_domains(data):
    nrows = len(data)
    ncols = len(data[0])
    domains = [[allowed_mask_for_token(data[r][c]) for c in range(ncols)] for r in range(nrows)]

    # Border pruning: patterns cannot use edges outside the board.
    for r in range(nrows):
        for c in range(ncols):
            mask = domains[r][c]
            new_mask = 0
            for p in iter_patterns(mask):
                ok = True
                for d in range(4):
                    if pattern_has_dir(p, d):
                        nb = neighbor(r, c, d, nrows, ncols)
                        if nb is None:
                            ok = False
                            break
                if ok:
                    new_mask |= 1 << p
            domains[r][c] = new_mask
            if new_mask == 0:
                return None
    return domains

def compatible_on_edge(p1, p2, d):
    return pattern_has_dir(p1, d) == pattern_has_dir(p2, OPP[d])

def revise(domains, r1, c1, r2, c2, d):
    changed = False
    m1 = domains[r1][c1]
    m2 = domains[r2][c2]
    nm1 = 0
    pats2 = list(iter_patterns(m2))
    for p1 in iter_patterns(m1):
        if any(compatible_on_edge(p1, p2, d) for p2 in pats2):
            nm1 |= 1 << p1
    if nm1 != m1:
        domains[r1][c1] = nm1
        changed = True
    return changed

def enforce_ac3(domains):
    nrows = len(domains)
    ncols = len(domains[0])
    q = deque()
    for r in range(nrows):
        for c in range(ncols):
            for d in range(4):
                nb = neighbor(r, c, d, nrows, ncols)
                if nb is not None:
                    q.append((r, c, nb[0], nb[1], d))
    while q:
        r1, c1, r2, c2, d = q.popleft()
        if revise(domains, r1, c1, r2, c2, d):
            if domains[r1][c1] == 0:
                return False
            for d2 in range(4):
                nb = neighbor(r1, c1, d2, nrows, ncols)
                if nb is not None and not (nb[0] == r2 and nb[1] == c2):
                    q.append((nb[0], nb[1], r1, c1, OPP[d2]))
    return True

def incoming_turn_possible(mask, incoming_dir):
    # Vertex is reached traveling in direction incoming_dir from previous vertex to this one.
    # So this vertex must have the opposite edge on.
    for p in iter_patterns(mask):
        if pattern_has_dir(p, OPP[incoming_dir]) and not pattern_has_dir(p, incoming_dir) and is_turn_pattern(p):
            return True
    return False

def incoming_continue_possible(mask, incoming_dir):
    for p in iter_patterns(mask):
        if pattern_has_dir(p, OPP[incoming_dir]) and pattern_has_dir(p, incoming_dir) and is_straight_pattern(p):
            return True
    return False

def possible_segment_lengths(domains, r, c, d):
    # Lengths possible for a straight segment starting from (r,c) along d.
    nrows = len(domains)
    ncols = len(domains[0])
    rr, cc = r, c
    lengths = set()
    length = 0
    while True:
        nb = neighbor(rr, cc, d, nrows, ncols)
        if nb is None:
            break
        rr, cc = nb
        length += 1

        mask = domains[rr][cc]

        # Segment can stop here if this vertex can turn from the incoming direction.
        if incoming_turn_possible(mask, d):
            lengths.add(length)

        # To go farther, this vertex must be able to continue straight.
        if not incoming_continue_possible(mask, d):
            break

    return lengths

def pattern_dirs(p):
    return [d for d in range(4) if pattern_has_dir(p, d)]

def clue_pattern_feasible(domains, data, r, c, p):
    token = data[r][c]
    if token is None:
        return True
    typ, k = clue_info(token)
    dirs = pattern_dirs(p)
    if len(dirs) != 2:
        return False
    s1 = possible_segment_lengths(domains, r, c, dirs[0])
    s2 = possible_segment_lengths(domains, r, c, dirs[1])
    if not s1 or not s2:
        return False
    for a in s1:
        if (k - a) in s2:
            return True
    return False

def prune_by_clues(domains, data):
    nrows = len(domains)
    ncols = len(domains[0])
    changed = True
    while changed:
        changed = False
        for r in range(nrows):
            for c in range(ncols):
                if data[r][c] is None:
                    continue
                old = domains[r][c]
                new = 0
                for p in iter_patterns(old):
                    if clue_pattern_feasible(domains, data, r, c, p):
                        new |= 1 << p
                if new == 0:
                    return False
                if new != old:
                    domains[r][c] = new
                    changed = True
        if changed:
            if not enforce_ac3(domains):
                return False
    return True

def copy_domains(domains):
    return [row[:] for row in domains]

def all_singleton(domains):
    return all((m and (m & (m - 1)) == 0) for row in domains for m in row)

def choose_var(domains, data):
    nrows = len(domains)
    ncols = len(domains[0])
    best = None
    best_key = None
    for r in range(nrows):
        for c in range(ncols):
            m = domains[r][c]
            bc = bit_count(m)
            if bc <= 1:
                continue
            token = data[r][c]
            clue_priority = 0 if token is not None else 1
            # More constrained first, clues first, then higher neighbor interaction.
            neighbor_count = 0
            for d in range(4):
                if neighbor(r, c, d, nrows, ncols) is not None:
                    neighbor_count += 1
            key = (bc, clue_priority, -neighbor_count, r, c)
            if best_key is None or key < best_key:
                best_key = key
                best = (r, c)
    return best

def build_edges_from_assignment(assign):
    nrows = len(assign)
    ncols = len(assign[0])
    edges = set()
    for r in range(nrows):
        for c in range(ncols):
            p = assign[r][c]
            for d in range(4):
                if pattern_has_dir(p, d):
                    nb = neighbor(r, c, d, nrows, ncols)
                    if nb is not None:
                        a = (r, c)
                        b = nb
                        edges.add(tuple(sorted((a, b))))
    return edges

def graph_from_edges(edges):
    g = {}
    for a, b in edges:
        g.setdefault(a, []).append(b)
        g.setdefault(b, []).append(a)
    return g

def connected_cycle_check(assign, data):
    edges = build_edges_from_assignment(assign)
    if not edges:
        return False, None, None
    g = graph_from_edges(edges)

    # Every used vertex must have degree 2.
    for v, adj in g.items():
        if len(adj) != 2:
            return False, None, None

    # All clues must be used.
    nrows = len(assign)
    ncols = len(assign[0])
    clues = []
    for r in range(nrows):
        for c in range(ncols):
            if data[r][c] is not None:
                clues.append((r, c))
                if (r, c) not in g:
                    return False, None, None

    # Single connected component over used vertices.
    start = next(iter(g))
    seen = set()
    stack = [start]
    while stack:
        v = stack.pop()
        if v in seen:
            continue
        seen.add(v)
        stack.extend(g[v])
    if len(seen) != len(g):
        return False, None, None

    return True, g, edges

def segment_length_from(assign, start, d):
    # Count edges until first turn.
    nrows = len(assign)
    ncols = len(assign[0])
    r, c = start
    rr, cc = r, c
    length = 0
    while True:
        nb = neighbor(rr, cc, d, nrows, ncols)
        if nb is None:
            return None
        rr, cc = nb
        length += 1
        p = assign[rr][cc]
        if pattern_has_dir(p, d) and pattern_has_dir(p, OPP[d]) and is_straight_pattern(p):
            continue
        if pattern_has_dir(p, OPP[d]) and not pattern_has_dir(p, d) and is_turn_pattern(p):
            return length
        return None

def clue_lengths_valid(assign, data):
    nrows = len(assign)
    ncols = len(assign[0])
    for r in range(nrows):
        for c in range(ncols):
            token = data[r][c]
            if token is None:
                continue
            typ, k = clue_info(token)
            p = assign[r][c]
            if typ == 'W' and p not in (1, 2):
                return False
            if typ == 'B' and p not in (3, 4, 5, 6):
                return False
            dirs = pattern_dirs(p)
            if len(dirs) != 2:
                return False
            a = segment_length_from(assign, (r, c), dirs[0])
            b = segment_length_from(assign, (r, c), dirs[1])
            if a is None or b is None or a + b != k:
                return False
    return True

def extract_ordered_loop(assign):
    edges = build_edges_from_assignment(assign)
    g = graph_from_edges(edges)
    if not g:
        return []
    start = min(g)
    prev = None
    cur = start
    path = [start]
    while True:
        nbrs = g[cur]
        nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
    return path

def partial_small_loop_prune(domains, data):
    # Detect a fully fixed closed component that excludes some clue.
    nrows = len(domains)
    ncols = len(domains[0])
    fixed = [[singleton_pattern(domains[r][c]) for c in range(ncols)] for r in range(nrows)]
    g = {}
    used_vertices = set()
    for r in range(nrows):
        for c in range(ncols):
            p = fixed[r][c]
            if p is None or p == 0:
                continue
            used_vertices.add((r, c))
            for d in range(4):
                if pattern_has_dir(p, d):
                    nb = neighbor(r, c, d, nrows, ncols)
                    if nb is not None:
                        p2 = fixed[nb[0]][nb[1]]
                        if p2 is not None and pattern_has_dir(p2, OPP[d]):
                            g.setdefault((r, c), []).append(nb)
    seen = set()
    all_clues = {(r, c) for r in range(nrows) for c in range(ncols) if data[r][c] is not None}
    for v in list(g):
        if v in seen:
            continue
        comp = set()
        stack = [v]
        ok_cycle = True
        while stack:
            x = stack.pop()
            if x in comp:
                continue
            comp.add(x)
            seen.add(x)
            adj = g.get(x, [])
            if len(adj) != 2:
                ok_cycle = False
            for y in adj:
                stack.append(y)
        if ok_cycle:
            # Ensure no vertex in the component still has a non-singleton domain.
            if all(domains[r][c] and (domains[r][c] & (domains[r][c] - 1)) == 0 for (r, c) in comp):
                clues_in = comp & all_clues
                if clues_in and clues_in != all_clues:
                    return False
    return True

def propagate(domains, data):
    if not enforce_ac3(domains):
        return False
    if not prune_by_clues(domains, data):
        return False
    if not partial_small_loop_prune(domains, data):
        return False
    return True

def solve_domains(domains, data):
    if not propagate(domains, data):
        return None

    if all_singleton(domains):
        assign = [[singleton_pattern(domains[r][c]) for c in range(len(domains[0]))] for r in range(len(domains))]
        ok, _, _ = connected_cycle_check(assign, data)
        if not ok:
            return None
        if not clue_lengths_valid(assign, data):
            return None
        return assign

    r, c = choose_var(domains, data)
    opts = list(iter_patterns(domains[r][c]))

    # Value ordering: for clues, try patterns more likely to satisfy the clue first.
    token = data[r][c]
    if token is not None:
        scored = []
        for p in opts:
            dirs = pattern_dirs(p)
            score = 999999
            if len(dirs) == 2:
                s1 = possible_segment_lengths(domains, r, c, dirs[0])
                s2 = possible_segment_lengths(domains, r, c, dirs[1])
                _, k = clue_info(token)
                feasible_pairs = sum(1 for a in s1 if (k - a) in s2)
                score = -feasible_pairs
            scored.append((score, p))
        opts = [p for _, p in sorted(scored)]

    for p in opts:
        nd = copy_domains(domains)
        nd[r][c] = 1 << p
        res = solve_domains(nd, data)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    domains = build_initial_domains(data)
    if domains is None:
        return "No Solution"
    assign = solve_domains(domains, data)
    if assign is None:
        return "No Solution"
    return str(extract_ordered_loop(assign))

if __name__ == "__main__":
    print(solve(OBSERVATION))

