from collections import defaultdict, deque

UNKNOWN = -1
WHITE = 0
BLACK = 1

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])

    # Region metadata
    region_cells = defaultdict(list)
    region_clue = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            region_cells[rid].append((r, c))
            if data[r][c] is not None:
                region_clue[rid] = data[r][c]
    region_ids = sorted(region_cells)

    # Precompute line-valid masks for each row and column.
    # Mask bit 1 means BLACK, 0 means WHITE.
    row_valid_masks = []
    for r in range(n):
        ids = region[r]
        row_valid_masks.append(_generate_line_masks(ids))
    col_valid_masks = []
    for c in range(m):
        ids = [region[r][c] for r in range(n)]
        col_valid_masks.append(_generate_line_masks(ids))

    # Precompute cell neighbors
    nbrs = {}
    for r in range(n):
        for c in range(m):
            arr = []
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    arr.append((rr, cc))
            nbrs[(r, c)] = arr

    grid = [[UNKNOWN] * m for _ in range(n)]

    def clone_grid(g):
        return [row[:] for row in g]

    def compatible_row_masks(g, r):
        masks = []
        for mask in row_valid_masks[r]:
            ok = True
            for c in range(m):
                bit = (mask >> c) & 1
                v = g[r][c]
                if v != UNKNOWN and v != bit:
                    ok = False
                    break
            if ok:
                masks.append(mask)
        return masks

    def compatible_col_masks(g, c):
        masks = []
        for mask in col_valid_masks[c]:
            ok = True
            for r in range(n):
                bit = (mask >> r) & 1
                v = g[r][c]
                if v != UNKNOWN and v != bit:
                    ok = False
                    break
            if ok:
                masks.append(mask)
        return masks

    def assign(g, r, c, val, queue):
        cur = g[r][c]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        g[r][c] = val
        queue.append((r, c))
        return True

    def optimistic_white_connectivity(g):
        # All confirmed white cells must lie in one connected component
        # of cells that are not fixed black.
        available = [(r, c) for r in range(n) for c in range(m) if g[r][c] != BLACK]
        if not available:
            return False
        confirmed = [(r, c) for r in range(n) for c in range(m) if g[r][c] == WHITE]
        if not confirmed:
            return True
        start = confirmed[0]
        q = deque([start])
        seen = {start}
        while q:
            x = q.popleft()
            for y in nbrs[x]:
                if y not in seen and g[y[0]][y[1]] != BLACK:
                    seen.add(y)
                    q.append(y)
        return all(cell in seen for cell in confirmed)

    def final_white_connected(g):
        whites = [(r, c) for r in range(n) for c in range(m) if g[r][c] == WHITE]
        if not whites:
            return False
        start = whites[0]
        q = deque([start])
        seen = {start}
        while q:
            x = q.popleft()
            for y in nbrs[x]:
                if y not in seen and g[y[0]][y[1]] == WHITE:
                    seen.add(y)
                    q.append(y)
        return len(seen) == len(whites)

    def region_status(g, rid):
        black = 0
        unknown = 0
        for r, c in region_cells[rid]:
            if g[r][c] == BLACK:
                black += 1
            elif g[r][c] == UNKNOWN:
                unknown += 1
        return black, unknown

    def propagate(g):
        queue = deque((r, c) for r in range(n) for c in range(m) if g[r][c] != UNKNOWN)
        dirty_rows = set(range(n))
        dirty_cols = set(range(m))
        dirty_regions = set(region_ids)

        while True:
            changed = False

            while queue:
                r, c = queue.popleft()
                v = g[r][c]
                if v == BLACK:
                    for rr, cc in nbrs[(r, c)]:
                        if not assign(g, rr, cc, WHITE, queue):
                            return None
                        dirty_rows.add(rr)
                        dirty_cols.add(cc)
                        dirty_regions.add(region[rr][cc])
                    dirty_rows.add(r)
                    dirty_cols.add(c)
                    dirty_regions.add(region[r][c])

            # Region clue propagation
            while dirty_regions:
                rid = dirty_regions.pop()
                clue = region_clue.get(rid)
                if clue is None:
                    continue
                black, unknown = region_status(g, rid)
                if black > clue or black + unknown < clue:
                    return None
                if unknown == 0:
                    continue
                if black == clue:
                    for r, c in region_cells[rid]:
                        if g[r][c] == UNKNOWN:
                            if not assign(g, r, c, WHITE, queue):
                                return None
                            dirty_rows.add(r)
                            dirty_cols.add(c)
                            dirty_regions.add(rid)
                            changed = True
                elif black + unknown == clue:
                    for r, c in region_cells[rid]:
                        if g[r][c] == UNKNOWN:
                            if not assign(g, r, c, BLACK, queue):
                                return None
                            dirty_rows.add(r)
                            dirty_cols.add(c)
                            dirty_regions.add(rid)
                            changed = True

            # Row line propagation
            while dirty_rows:
                r = dirty_rows.pop()
                masks = compatible_row_masks(g, r)
                if not masks:
                    return None
                for c in range(m):
                    vals = {(mask >> c) & 1 for mask in masks}
                    if len(vals) == 1 and g[r][c] == UNKNOWN:
                        val = next(iter(vals))
                        if not assign(g, r, c, val, queue):
                            return None
                        dirty_cols.add(c)
                        dirty_regions.add(region[r][c])
                        changed = True

            # Column line propagation
            while dirty_cols:
                c = dirty_cols.pop()
                masks = compatible_col_masks(g, c)
                if not masks:
                    return None
                for r in range(n):
                    vals = {(mask >> r) & 1 for mask in masks}
                    if len(vals) == 1 and g[r][c] == UNKNOWN:
                        val = next(iter(vals))
                        if not assign(g, r, c, val, queue):
                            return None
                        dirty_rows.add(r)
                        dirty_regions.add(region[r][c])
                        changed = True

            # Global optimistic white connectivity
            if not optimistic_white_connectivity(g):
                return None

            # Re-check all clue regions cheaply after other deductions
            for rid in region_clue:
                black, unknown = region_status(g, rid)
                clue = region_clue[rid]
                if black > clue or black + unknown < clue:
                    return None

            if not queue and not dirty_rows and not dirty_cols and not dirty_regions:
                break
            if not changed and not queue and not dirty_rows and not dirty_cols and not dirty_regions:
                break

        return g

    def choose_branch_cell(g):
        best = None
        best_score = None

        row_masks_cache = {}
        col_masks_cache = {}

        for r in range(n):
            row_masks_cache[r] = compatible_row_masks(g, r)
        for c in range(m):
            col_masks_cache[c] = compatible_col_masks(g, c)

        for r in range(n):
            for c in range(m):
                if g[r][c] != UNKNOWN:
                    continue
                row_vals = {(mask >> c) & 1 for mask in row_masks_cache[r]}
                col_vals = {(mask >> r) & 1 for mask in col_masks_cache[c]}
                vals = row_vals & col_vals
                if not vals:
                    return (r, c, [])
                # Prefer highly constrained cells, then clue-region cells.
                rid = region[r][c]
                clue_bias = 0 if rid not in region_clue else 1
                score = (len(vals), len(row_masks_cache[r]) * len(col_masks_cache[c]), -clue_bias)
                if best_score is None or score < best_score:
                    best_score = score
                    best = (r, c, sorted(vals))
        return best

    def search(g):
        g = propagate(clone_grid(g))
        if g is None:
            return None

        complete = True
        for r in range(n):
            for c in range(m):
                if g[r][c] == UNKNOWN:
                    complete = False
                    break
            if not complete:
                break

        if complete:
            for rid, clue in region_clue.items():
                black, unknown = region_status(g, rid)
                if black != clue or unknown != 0:
                    return None
            if not final_white_connected(g):
                return None
            return g

        choice = choose_branch_cell(g)
        if choice is None:
            return None
        r, c, vals = choice
        if not vals:
            return None

        # Human-like guess ordering:
        # - if a clue region still needs blacks, try BLACK first there
        # - otherwise try the more restrictive color inferred from surroundings
        rid = region[r][c]
        order = vals[:]
        if rid in region_clue:
            black, unknown = region_status(g, rid)
            need = region_clue[rid] - black
            if need > 0 and BLACK in order:
                order = [BLACK] + [v for v in order if v != BLACK]
            elif WHITE in order:
                order = [WHITE] + [v for v in order if v != WHITE]

        for val in order:
            ng = clone_grid(g)
            ng[r][c] = val
            ans = search(ng)
            if ans is not None:
                return ans
        return None

    ans = search(grid)
    if ans is None:
        return "No Solution"
    out = [[('B' if ans[r][c] == BLACK else None) for c in range(m)] for r in range(n)]
    return repr(out)


def _generate_line_masks(region_ids):
    # Enumerate masks with:
    # 1) no adjacent black cells in the line
    # 2) each contiguous white segment passes through at most 2 distinct regions
    L = len(region_ids)
    res = []

    def rec(i, prev_black, seg_regions, mask):
        if i == L:
            res.append(mask)
            return

        # Try WHITE
        if not prev_black:
            pass
        new_seg = seg_regions
        rid = region_ids[i]
        if seg_regions is None:
            new_seg = (rid,)
            rec(i + 1, False, new_seg, mask)
        else:
            if rid in seg_regions:
                rec(i + 1, False, seg_regions, mask)
            elif len(seg_regions) < 2:
                rec(i + 1, False, seg_regions + (rid,), mask)

        # Try BLACK if previous not black
        if not prev_black:
            rec(i + 1, True, None, mask | (1 << i))

    rec(0, False, None, 0)
    return res


