from collections import defaultdict, deque

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0
    cells = [(r, c) for r in range(n) for c in range(m)]
    idx_of = {cell: i for i, cell in enumerate(cells)}
    region_of = {}
    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            reg = grid[r][c]
            region_of[(r, c)] = reg
            regions[reg].append((r, c))

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def nbrs(cell):
        r, c = cell
        for dr, dc in dirs:
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                yield (rr, cc)

    # Candidate dominoes: every orthogonally adjacent pair
    dominoes = []
    dom_index = {}
    for r in range(n):
        for c in range(m):
            if r + 1 < n:
                a, b = (r, c), (r + 1, c)
                dom_index[(a, b)] = len(dominoes)
                dominoes.append((a, b))
            if c + 1 < m:
                a, b = (r, c), (r, c + 1)
                dom_index[(a, b)] = len(dominoes)
                dominoes.append((a, b))

    D = len(dominoes)

    # Cell -> dominoes covering it
    cell_to_dominoes = defaultdict(set)
    # Region contributions per domino
    dom_reg_count = []
    for i, (a, b) in enumerate(dominoes):
        cell_to_dominoes[a].add(i)
        cell_to_dominoes[b].add(i)
        ra = region_of[a]
        rb = region_of[b]
        if ra == rb:
            dom_reg_count.append({ra: 2})
        else:
            dom_reg_count.append({ra: 1, rb: 1})

    # Conflict graph: overlap or orthogonal touching between different dominoes
    conflicts = [set() for _ in range(D)]
    dom_cells = []
    for a, b in dominoes:
        s = {a, b}
        dom_cells.append(s)

    touching_zone = []
    for i, (a, b) in enumerate(dominoes):
        zone = set([a, b])
        for x in (a, b):
            for y in nbrs(x):
                zone.add(y)
        touching_zone.append(zone)

    for i in range(D):
        ci = dom_cells[i]
        zi = touching_zone[i]
        for j in range(i + 1, D):
            cj = dom_cells[j]
            # Any overlap or orthogonal touching causes conflict
            if cj & zi or ci & touching_zone[j]:
                conflicts[i].add(j)
                conflicts[j].add(i)

    region_ids = sorted(regions)
    region_sizes = {reg: len(regions[reg]) for reg in region_ids}

    # Sanity: each region must be able to contain exactly 2 shaded cells
    for reg in region_ids:
        if region_sizes[reg] < 2:
            return "No Solution"

    # State
    AVAILABLE = 0
    SELECTED = 1
    REJECTED = 2

    class State:
        __slots__ = (
            "dom_status",
            "selected",
            "region_shaded",
            "forced_shaded",
            "forced_unshaded",
            "cell_selected_by",
            "available_cover_count",
        )

        def __init__(self):
            self.dom_status = [AVAILABLE] * D
            self.selected = set()
            self.region_shaded = {reg: 0 for reg in region_ids}
            self.forced_shaded = set()
            self.forced_unshaded = set()
            self.cell_selected_by = {}
            self.available_cover_count = {cell: len(cell_to_dominoes[cell]) for cell in cells}

        def clone(self):
            s = State.__new__(State)
            s.dom_status = self.dom_status[:]
            s.selected = set(self.selected)
            s.region_shaded = dict(self.region_shaded)
            s.forced_shaded = set(self.forced_shaded)
            s.forced_unshaded = set(self.forced_unshaded)
            s.cell_selected_by = dict(self.cell_selected_by)
            s.available_cover_count = dict(self.available_cover_count)
            return s

    def reject_domino(st, d, queue):
        if st.dom_status[d] == REJECTED:
            return True
        if st.dom_status[d] == SELECTED:
            return False
        st.dom_status[d] = REJECTED
        a, b = dominoes[d]
        st.available_cover_count[a] -= 1
        st.available_cover_count[b] -= 1
        queue.append(("cell_recheck", a))
        queue.append(("cell_recheck", b))
        queue.append(("region_recheck", region_of[a]))
        queue.append(("region_recheck", region_of[b]))
        return True

    def force_unshaded(st, cell, queue):
        if cell in st.forced_shaded:
            return False
        if cell in st.forced_unshaded:
            return True
        if cell in st.cell_selected_by:
            return False
        st.forced_unshaded.add(cell)
        for d in list(cell_to_dominoes[cell]):
            if not reject_domino(st, d, queue):
                return False
        queue.append(("region_recheck", region_of[cell]))
        return True

    def force_shaded(st, cell, queue):
        if cell in st.forced_unshaded:
            return False
        if cell in st.forced_shaded:
            return True
        st.forced_shaded.add(cell)
        queue.append(("cell_recheck", cell))
        queue.append(("region_recheck", region_of[cell]))
        return True

    def select_domino(st, d, queue):
        status = st.dom_status[d]
        if status == SELECTED:
            return True
        if status == REJECTED:
            return False

        a, b = dominoes[d]
        if a in st.forced_unshaded or b in st.forced_unshaded:
            return False
        if a in st.cell_selected_by or b in st.cell_selected_by:
            return False

        # Region quota check
        for reg, cnt in dom_reg_count[d].items():
            if st.region_shaded[reg] + cnt > 2:
                return False

        st.dom_status[d] = SELECTED
        st.selected.add(d)
        st.cell_selected_by[a] = d
        st.cell_selected_by[b] = d

        if not force_shaded(st, a, queue):
            return False
        if not force_shaded(st, b, queue):
            return False

        for reg, cnt in dom_reg_count[d].items():
            st.region_shaded[reg] += cnt

        # Reject all conflicting dominoes
        for x in conflicts[d]:
            if not reject_domino(st, x, queue):
                return False

        # Recheck affected regions/cells
        queue.append(("region_recheck", region_of[a]))
        queue.append(("region_recheck", region_of[b]))
        queue.append(("cell_recheck", a))
        queue.append(("cell_recheck", b))
        for x in touching_zone[d]:
            queue.append(("cell_recheck", x))
            queue.append(("region_recheck", region_of[x]))
        return True

    def possible_cover_dominoes(st, cell):
        return [d for d in cell_to_dominoes[cell] if st.dom_status[d] == AVAILABLE]

    def propagate(st):
        queue = deque()

        for cell in cells:
            queue.append(("cell_recheck", cell))
        for reg in region_ids:
            queue.append(("region_recheck", reg))

        while queue:
            typ, obj = queue.popleft()

            if typ == "cell_recheck":
                cell = obj

                if cell in st.cell_selected_by:
                    continue

                poss = possible_cover_dominoes(st, cell)
                k = len(poss)

                if cell in st.forced_shaded:
                    if k == 0:
                        return False
                    if k == 1:
                        if not select_domino(st, poss[0], queue):
                            return False
                        continue
                else:
                    if k == 0:
                        if not force_unshaded(st, cell, queue):
                            return False
                        continue

                if cell in st.forced_unshaded and k > 0:
                    # force_unshaded should already have rejected all covers
                    return False

            else:
                reg = obj
                shaded_now = st.region_shaded[reg]
                if shaded_now > 2:
                    return False

                reg_cells = regions[reg]
                possible_cells = []
                for cell in reg_cells:
                    if cell in st.cell_selected_by:
                        continue
                    if cell in st.forced_unshaded:
                        continue
                    if len(possible_cover_dominoes(st, cell)) > 0:
                        possible_cells.append(cell)

                max_shaded = shaded_now + len(possible_cells)
                if max_shaded < 2:
                    return False

                need = 2 - shaded_now
                if need < 0:
                    return False

                if need == 0:
                    for cell in reg_cells:
                        if cell not in st.cell_selected_by:
                            if not force_unshaded(st, cell, queue):
                                return False
                    continue

                if len(possible_cells) == need:
                    for cell in possible_cells:
                        if not force_shaded(st, cell, queue):
                            return False

                # If a forced shaded cell is the only possible remaining one for quota patterns,
                # the cell-level singleton rule will trigger selection when narrowed enough.

        # Final consistency checks
        for reg in region_ids:
            if st.region_shaded[reg] > 2:
                return False
            rem = 0
            for cell in regions[reg]:
                if cell in st.cell_selected_by:
                    continue
                if cell in st.forced_unshaded:
                    continue
                if len(possible_cover_dominoes(st, cell)) > 0:
                    rem += 1
            if st.region_shaded[reg] + rem < 2:
                return False

        for cell in cells:
            if cell in st.forced_shaded and cell not in st.cell_selected_by:
                poss = possible_cover_dominoes(st, cell)
                if not poss:
                    return False

        return True

    def solved(st):
        return all(st.region_shaded[reg] == 2 for reg in region_ids)

    def choose_branch(st):
        # Human-like branching:
        # 1) forced shaded cell with smallest number of covering dominoes
        best = None
        best_opts = None
        for cell in st.forced_shaded:
            if cell in st.cell_selected_by:
                continue
            opts = possible_cover_dominoes(st, cell)
            if len(opts) == 0:
                return ("dead", cell)
            if len(opts) > 1 and (best is None or len(opts) < len(best_opts)):
                best = ("cell", cell)
                best_opts = opts
        if best is not None:
            return best, best_opts

        # 2) region with smallest combinational freedom among still-possible cells
        best_reg = None
        best_cells = None
        best_score = None
        for reg in region_ids:
            need = 2 - st.region_shaded[reg]
            if need <= 0:
                continue
            cand_cells = []
            score = 0
            for cell in regions[reg]:
                if cell in st.cell_selected_by or cell in st.forced_unshaded:
                    continue
                opts = possible_cover_dominoes(st, cell)
                if opts:
                    cand_cells.append(cell)
                    score += len(opts)
            if len(cand_cells) < need:
                return ("dead", reg)
            key = (len(cand_cells), score, need)
            if best_score is None or key < best_score:
                best_score = key
                best_reg = reg
                best_cells = cand_cells
        if best_reg is not None:
            return ("region", best_reg), best_cells

        # 3) fallback: available domino with strongest impact
        best_d = None
        best_key = None
        for d in range(D):
            if st.dom_status[d] != AVAILABLE:
                continue
            a, b = dominoes[d]
            key = (
                len(conflicts[d]),
                sum(1 for reg, cnt in dom_reg_count[d].items() if st.region_shaded[reg] + cnt <= 2),
                -sum(dom_reg_count[d].values()),
            )
            if best_key is None or key > best_key:
                best_key = key
                best_d = d
        if best_d is not None:
            return ("domino", best_d), [best_d]

        return None

    def search(st):
        if not propagate(st):
            return None
        if solved(st):
            # Ensure every non-selected cell is unshaded-consistent
            ans = [[None for _ in range(m)] for _ in range(n)]
            for d in st.selected:
                a, b = dominoes[d]
                ans[a[0]][a[1]] = "S"
                ans[b[0]][b[1]] = "S"
            return ans

        choice = choose_branch(st)
        if choice is None:
            return None
        if choice[0] == "dead":
            return None

        kind, payload = choice

        if kind[0] == "cell":
            cell = kind[1]
            opts = payload
            for d in sorted(opts, key=lambda x: len(conflicts[x]), reverse=True):
                st2 = st.clone()
                q = deque()
                if select_domino(st2, d, q):
                    res = search(st2)
                    if res is not None:
                        return res
            return None

        if kind[0] == "region":
            reg = kind[1]
            cells_in_reg = payload
            need = 2 - st.region_shaded[reg]

            # Branch on a most constrained cell inside the region: shaded vs unshaded shape decisions
            cells_in_reg = sorted(cells_in_reg, key=lambda c: len(possible_cover_dominoes(st, c)))
            pivot = cells_in_reg[0]
            opts = possible_cover_dominoes(st, pivot)

            # Prefer trying ways that shade the pivot, because the region still needs cells.
            for d in sorted(opts, key=lambda x: len(conflicts[x]), reverse=True):
                st2 = st.clone()
                q = deque()
                if select_domino(st2, d, q):
                    res = search(st2)
                    if res is not None:
                        return res

            # If region has more candidate cells than needed, pivot may be unshaded.
            if len(cells_in_reg) > need:
                st2 = st.clone()
                q = deque()
                if force_unshaded(st2, pivot, q):
                    res = search(st2)
                    if res is not None:
                        return res
            return None

        if kind[0] == "domino":
            d = kind[1]

            st2 = st.clone()
            q = deque()
            if select_domino(st2, d, q):
                res = search(st2)
                if res is not None:
                    return res

            st3 = st.clone()
            q = deque()
            if reject_domino(st3, d, q):
                res = search(st3)
                if res is not None:
                    return res
            return None

        return None

    result = search(State())
    return "No Solution" if result is None else str(result)

