    print(solve(OBSERVATION))

OBSERVATION = {'tree': [[None, 'T', None, None, None, None], [None, None, 'T', None, None, None], [None, None, None, None, None, 'T'], [None, 'T', None, None, None, None], [None, None, None, 'T', None, None], [None, 'T', None, None, None, 'T']], 'row_tent_counts': [1, 2, 1, 0, 1, 2], 'col_tent_counts': [2, 1, 1, 1, 1, 1]}

from collections import defaultdict

def solve(observation):
    trees_grid = observation['tree']
    row_need = observation['row_tent_counts']
    col_need = observation['col_tent_counts']
    r = len(trees_grid)
    c = len(trees_grid[0]) if r else 0

    trees = []
    tree_index = {}
    for i in range(r):
        for j in range(c):
            if trees_grid[i][j] == 'T':
                tree_index[(i, j)] = len(trees)
                trees.append((i, j))

    if sum(row_need) != len(trees) or sum(col_need) != len(trees):
        return "No Solution"

    orth = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    king = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    def inside(x, y):
        return 0 <= x < r and 0 <= y < c

    # Candidate tent cells for each tree.
    domains0 = []
    cell_to_trees = defaultdict(list)
    for tid, (x, y) in enumerate(trees):
        dom = []
        for dx, dy in orth:
            nx, ny = x + dx, y + dy
            if inside(nx, ny) and trees_grid[nx][ny] is None:
                dom.append((nx, ny))
                cell_to_trees[(nx, ny)].append(tid)
        if not dom:
            return "No Solution"
        domains0.append(frozenset(dom))

    # Conflict map for tent cells: same cell or touching diagonally/orthogonally.
    all_cells = set(cell_to_trees.keys())
    conflict = {cell: set() for cell in all_cells}
    for x, y in all_cells:
        for dx, dy in king:
            nx, ny = x + dx, y + dy
            if (nx, ny) in all_cells:
                conflict[(x, y)].add((nx, ny))

    # Static maps for speed.
    row_cells = [set() for _ in range(r)]
    col_cells = [set() for _ in range(c)]
    for cell in all_cells:
        row_cells[cell[0]].add(cell)
        col_cells[cell[1]].add(cell)

    # Fast bipartite matching feasibility check: can each unassigned tree still get a distinct cell?
    def has_distinct_matching(domains, assigned):
        unassigned = [t for t in range(len(trees)) if assigned[t] is None]
        if not unassigned:
            return True

        # Compress available cells.
        cells = set()
        for t in unassigned:
            cells.update(domains[t])
        if len(cells) < len(unassigned):
            return False

        cell_list = list(cells)
        cid = {cell: i for i, cell in enumerate(cell_list)}
        adj = [[cid[cell] for cell in domains[t]] for t in unassigned]

        match_to_tree = [-1] * len(cell_list)

        def dfs(u, seen):
            for v in adj[u]:
                if seen[v]:
                    continue
                seen[v] = True
                if match_to_tree[v] == -1 or dfs(match_to_tree[v], seen):
                    match_to_tree[v] = u
                    return True
            return False

        for u in range(len(unassigned)):
            seen = [False] * len(cell_list)
            if not dfs(u, seen):
                return False
        return True

    def propagate(domains, assigned, row_count, col_count):
        domains = list(domains)
        assigned = list(assigned)
        row_count = list(row_count)
        col_count = list(col_count)

        changed = True
        while changed:
            changed = False

            # Basic overflow check.
            for i in range(r):
                if row_count[i] > row_need[i]:
                    return None
            for j in range(c):
                if col_count[j] > col_need[j]:
                    return None

            assigned_cells = {cell for cell in assigned if cell is not None}

            # Prune domains by assigned tents and row/col saturation.
            for t in range(len(trees)):
                if assigned[t] is not None:
                    continue
                new_dom = set()
                for cell in domains[t]:
                    x, y = cell
                    if row_count[x] >= row_need[x]:
                        continue
                    if col_count[y] >= col_need[y]:
                        continue
                    bad = False
                    for ac in assigned_cells:
                        if cell in conflict[ac]:
                            bad = True
                            break
                    if not bad:
                        new_dom.add(cell)
                if not new_dom:
                    return None
                if new_dom != set(domains[t]):
                    domains[t] = frozenset(new_dom)
                    changed = True

            # Row/column upper-bound feasibility using distinct possible cells.
            for i in range(r):
                possible = set()
                for t in range(len(trees)):
                    if assigned[t] is None:
                        possible.update(cell for cell in domains[t] if cell[0] == i)
                if row_count[i] > row_need[i]:
                    return None
                if row_count[i] + len(possible) < row_need[i]:
                    return None
                if row_count[i] == row_need[i] and possible:
                    for t in range(len(trees)):
                        if assigned[t] is None:
                            nd = {cell for cell in domains[t] if cell[0] != i}
                            if not nd:
                                return None
                            if nd != set(domains[t]):
                                domains[t] = frozenset(nd)
                                changed = True

            for j in range(c):
                possible = set()
                for t in range(len(trees)):
                    if assigned[t] is None:
                        possible.update(cell for cell in domains[t] if cell[1] == j)
                if col_count[j] > col_need[j]:
                    return None
                if col_count[j] + len(possible) < col_need[j]:
                    return None
                if col_count[j] == col_need[j] and possible:
                    for t in range(len(trees)):
                        if assigned[t] is None:
                            nd = {cell for cell in domains[t] if cell[1] != j}
                            if not nd:
                                return None
                            if nd != set(domains[t]):
                                domains[t] = frozenset(nd)
                                changed = True

            # Singleton tree domains => forced placements.
            forced = [t for t in range(len(trees)) if assigned[t] is None and len(domains[t]) == 1]
            if forced:
                for t in forced:
                    if assigned[t] is not None:
                        continue
                    cell = next(iter(domains[t]))
                    x, y = cell
                    if row_count[x] >= row_need[x] or col_count[y] >= col_need[y]:
                        return None

                    # Check touch conflict with prior assignments.
                    for ac in assigned_cells:
                        if cell in conflict[ac]:
                            return None

                    assigned[t] = cell
                    row_count[x] += 1
                    col_count[y] += 1
                    assigned_cells.add(cell)
                    changed = True

                    # Remove conflicting cells from every other domain.
                    for u in range(len(trees)):
                        if assigned[u] is None:
                            nd = set(domains[u]) - conflict[cell]
                            if not nd:
                                return None
                            if nd != set(domains[u]):
                                domains[u] = frozenset(nd)
                continue

            # Hidden single cell for a tree-free position:
            # if a candidate cell can only belong to one still-unassigned tree, and
            # that tree has no other cells in the required row/col after saturation,
            # it may become forced. Simpler useful form: a tree having a unique row/col survivor.
            for t in range(len(trees)):
                if assigned[t] is not None:
                    continue
                by_row = defaultdict(list)
                by_col = defaultdict(list)
                for cell in domains[t]:
                    by_row[cell[0]].append(cell)
                    by_col[cell[1]].append(cell)
                forced_cell = None
                for i in list(by_row):
                    if row_count[i] + 1 == row_need[i]:
                        # If this tree is the only way it can contribute to that row in its own domain.
                        if len(by_row[i]) == 1:
                            forced_cell = by_row[i][0]
                            break
                if forced_cell is None:
                    for j in list(by_col):
                        if col_count[j] + 1 == col_need[j]:
                            if len(by_col[j]) == 1:
                                forced_cell = by_col[j][0]
                                break
                if forced_cell is not None:
                    domains[t] = frozenset([forced_cell])
                    changed = True
                    break

            # Global distinct-cell matching feasibility.
            if not has_distinct_matching(domains, assigned):
                return None

        # Final exact bound checks.
        for i in range(r):
            if row_count[i] > row_need[i]:
                return None
            possible = set()
            for t in range(len(trees)):
                if assigned[t] is None:
                    possible.update(cell for cell in domains[t] if cell[0] == i)
            if row_count[i] + len(possible) < row_need[i]:
                return None

        for j in range(c):
            if col_count[j] > col_need[j]:
                return None
            possible = set()
            for t in range(len(trees)):
                if assigned[t] is None:
                    possible.update(cell for cell in domains[t] if cell[1] == j)
            if col_count[j] + len(possible) < col_need[j]:
                return None

        return tuple(domains), tuple(assigned), tuple(row_count), tuple(col_count)

    def value_score(cell, row_count, col_count):
        x, y = cell
        # Prefer rows/cols that are tighter, and cells that eliminate more nearby choices.
        row_slack = row_need[x] - row_count[x]
        col_slack = col_need[y] - col_count[y]
        return (row_slack + col_slack, -len(conflict[cell]), x, y)

    def choose_tree(domains, assigned, row_count, col_count):
        best = None
        best_key = None
        for t in range(len(trees)):
            if assigned[t] is not None:
                continue
            dom = domains[t]
            rows = len({x for x, _ in dom})
            cols = len({y for _, y in dom})
            pressure = sum((row_need[x] - row_count[x]) + (col_need[y] - col_count[y]) for x, y in dom)
            key = (len(dom), rows + cols, pressure)
            if best_key is None or key < best_key:
                best_key = key
                best = t
        return best

    def dfs(domains, assigned, row_count, col_count):
        state = propagate(domains, assigned, row_count, col_count)
        if state is None:
            return None
        domains, assigned, row_count, col_count = state

        if all(a is not None for a in assigned):
            if list(row_count) == row_need and list(col_count) == col_need:
                return assigned
            return None

        t = choose_tree(domains, assigned, row_count, col_count)
        candidates = sorted(domains[t], key=lambda cell: value_score(cell, row_count, col_count))

        for cell in candidates:
            x, y = cell
            new_domains = list(domains)
            new_assigned = list(assigned)
            new_row = list(row_count)
            new_col = list(col_count)

            new_assigned[t] = cell
            new_row[x] += 1
            new_col[y] += 1

            # Immediate local pruning after choosing a tent.
            bad = False
            for u in range(len(trees)):
                if u == t or new_assigned[u] is not None:
                    continue
                nd = set(new_domains[u]) - conflict[cell]
                if not nd:
                    bad = True
                    break
                new_domains[u] = frozenset(nd)
            if bad:
                continue

            res = dfs(tuple(new_domains), tuple(new_assigned), tuple(new_row), tuple(new_col))
            if res is not None:
                return res
        return None

    assigned = dfs(tuple(domains0), tuple([None] * len(trees)), tuple([0] * r), tuple([0] * c))
    if assigned is None:
        return "No Solution"

    answer = [[None for _ in range(c)] for _ in range(r)]
    for cell in assigned:
        x, y = cell
        answer[x][y] = 't'
    return str(answer)

if __name__ == "__main__":
    print(solve(OBSERVATION))

