from collections import defaultdict, deque

# Canonical tetromino bases
_BASES = {
    "I": {(0, 0), (0, 1), (0, 2), (0, 3)},
    "L": {(0, 0), (1, 0), (2, 0), (2, 1)},
    "T": {(0, 0), (0, 1), (0, 2), (1, 1)},
    "S": {(0, 1), (0, 2), (1, 0), (1, 1)},
}

def _normalize(shape):
    xs = [r for r, c in shape]
    ys = [c for r, c in shape]
    mr, mc = min(xs), min(ys)
    return tuple(sorted((r - mr, c - mc) for r, c in shape))

def _transforms(shape):
    pts = list(shape)
    out = set()
    for rf in (1, -1):
        for cf in (1, -1):
            s1 = [(rf * r, cf * c) for r, c in pts]
            for swap in (False, True):
                if swap:
                    s2 = [(c, r) for r, c in s1]
                else:
                    s2 = s1
                out.add(_normalize(s2))
    return out

_CANON = {}
for typ, shape in _BASES.items():
    for t in _transforms(shape):
        _CANON[t] = typ

def _classify(cells):
    return _CANON.get(_normalize(cells))

def _neighbors4(cell, n, m):
    r, c = cell
    if r > 0:
        yield (r - 1, c)
    if r + 1 < n:
        yield (r + 1, c)
    if c > 0:
        yield (r, c - 1)
    if c + 1 < m:
        yield (r, c + 1)

def _connected_subset_enum(region_cells, n, m):
    # Enumerate all connected 4-cell subsets inside a region.
    region = set(region_cells)
    cell_list = sorted(region)
    index = {cell: i for i, cell in enumerate(cell_list)}
    adj = {cell: [nb for nb in _neighbors4(cell, n, m) if nb in region] for cell in cell_list}

    seen = set()
    out = []

    for root in cell_list:
        root_i = index[root]
        stack = [(frozenset([root]), set(nb for nb in adj[root] if index[nb] > root_i))]
        while stack:
            chosen, frontier = stack.pop()
            if len(chosen) == 4:
                key = tuple(sorted(chosen))
                if key not in seen:
                    seen.add(key)
                    out.append(set(chosen))
                continue
            if not frontier:
                continue
            # Human-like: branch by frontier cells, but only allow cells >= root to avoid duplicates.
            f_list = sorted(frontier)
            for cell in f_list:
                new_chosen = set(chosen)
                new_chosen.add(cell)
                new_frontier = set(frontier)
                new_frontier.discard(cell)
                for nb in adj[cell]:
                    if nb not in new_chosen and index[nb] > root_i:
                        new_frontier.add(nb)
                stack.append((frozenset(new_chosen), new_frontier))
    return out

def _all_2x2_blocks(n, m):
    blocks = []
    for r in range(n - 1):
        for c in range(m - 1):
            blocks.append(((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)))
    return blocks

def _region_graph(grid):
    n, m = len(grid), len(grid[0])
    neigh = defaultdict(set)
    for r in range(n):
        for c in range(m):
            a = grid[r][c]
            if r + 1 < n:
                b = grid[r + 1][c]
                if a != b:
                    neigh[a].add(b)
                    neigh[b].add(a)
            if c + 1 < m:
                b = grid[r][c + 1]
                if a != b:
                    neigh[a].add(b)
                    neigh[b].add(a)
    return {k: set(v) for k, v in neigh.items()}

def _possible_graph_cells(assigned_cells, domains, placements_by_region):
    possible = set(assigned_cells)
    for rid, dom in domains.items():
        if dom is None:
            continue
        cells = set()
        for pidx in dom:
            cells |= placements_by_region[rid][pidx]["cells"]
        possible |= cells
    return possible

def _components(cells, n, m):
    cells = set(cells)
    comps = []
    seen = set()
    for start in list(cells):
        if start in seen:
            continue
        q = [start]
        seen.add(start)
        comp = {start}
        for x in q:
            for nb in _neighbors4(x, n, m):
                if nb in cells and nb not in seen:
                    seen.add(nb)
                    comp.add(nb)
                    q.append(nb)
        comps.append(comp)
    return comps

def _possible_connectivity_ok(n, m, assigned_regions, assigned_cells, domains, placements_by_region):
    # Strong but cheap prune:
    # 1) all already shaded cells must lie in a single component of the possible shaded universe.
    # 2) each unassigned region must still have at least one possible cell in that same component once one exists.
    possible = _possible_graph_cells(assigned_cells, domains, placements_by_region)
    if not possible:
        return False
    comps = _components(possible, n, m)
    comp_id = {}
    for i, comp in enumerate(comps):
        for cell in comp:
            comp_id[cell] = i
    if assigned_cells:
        ids = {comp_id[cell] for cell in assigned_cells}
        if len(ids) != 1:
            return False
        main = next(iter(ids))
        for rid, dom in domains.items():
            if dom is None:
                continue
            can_touch = False
            for pidx in dom:
                if any(comp_id[cell] == main for cell in placements_by_region[rid][pidx]["cells"]):
                    can_touch = True
                    break
            if not can_touch:
                return False
    return True

def _full_2x2_assigned_forbidden(blocks, selected_cells):
    s = selected_cells
    for b in blocks:
        if all(cell in s for cell in b):
            return True
    return False

def _forced_full_2x2_impossible(blocks, assigned_by_cell, domains, placements_by_region, cell_to_regions):
    # If a 2x2 block is not yet fully assigned, but every unassigned region covering a missing cell
    # is forced to include that cell in all remaining placements, then reject early.
    for b in blocks:
        must = True
        for cell in b:
            if cell in assigned_by_cell:
                if not assigned_by_cell[cell]:
                    must = False
                    break
                continue
            owners = cell_to_regions.get(cell, ())
            if not owners:
                must = False
                break
            rid = owners[0]
            dom = domains.get(rid)
            if dom is None:
                must = False
                break
            if not dom:
                return True
            if not all(cell in placements_by_region[rid][p]["cells"] for p in dom):
                must = False
                break
        if must:
            return True
    return False

def solve(observation):
    grid = observation["data"]
    n, m = len(grid), len(grid[0])

    # Build regions
    region_cells = defaultdict(list)
    for r in range(n):
        for c in range(m):
            region_cells[grid[r][c]].append((r, c))
    regions = sorted(region_cells)

    # Enumerate region placements
    placements_by_region = {}
    for rid in regions:
        cells = region_cells[rid]
        subs = _connected_subset_enum(cells, n, m)
        plist = []
        for sub in subs:
            typ = _classify(sub)
            if typ is None:
                continue
            # O tetromino excluded automatically by classifier.
            plist.append({
                "cells": frozenset(sub),
                "type": typ,
            })
        # Deduplicate exact cell sets
        uniq = {}
        for p in plist:
            uniq[(p["cells"], p["type"])] = p
        plist = list(uniq.values())
        if not plist:
            return "No Solution"
        placements_by_region[rid] = plist

    # Region adjacency for "same type forbidden"
    region_neigh = _region_graph(grid)
    for rid in regions:
        region_neigh.setdefault(rid, set())

    # Cell ownership by region
    cell_to_regions = {}
    for rid, cells in region_cells.items():
        for cell in cells:
            cell_to_regions[cell] = (rid,)

    blocks = _all_2x2_blocks(n, m)

    # Initial domains
    domains = {rid: list(range(len(placements_by_region[rid]))) for rid in regions}

    # Fast type lookup
    type_to_pidxs = {
        rid: defaultdict(list) for rid in regions
    }
    for rid in regions:
        for i, p in enumerate(placements_by_region[rid]):
            type_to_pidxs[rid][p["type"]].append(i)

    def clone_domains(dom):
        return {rid: (None if vals is None else vals[:]) for rid, vals in dom.items()}

    def propagate(domains, assigned_regions, selected_cells, assigned_by_cell):
        q = deque([rid for rid in regions if domains[rid] is not None and len(domains[rid]) == 1])
        inq = set(q)

        while q:
            rid = q.popleft()
            inq.discard(rid)
            if domains[rid] is None:
                continue
            if len(domains[rid]) != 1:
                continue

            pidx = domains[rid][0]
            p = placements_by_region[rid][pidx]

            # Commit assignment
            domains[rid] = None
            assigned_regions[rid] = pidx

            for cell in region_cells[rid]:
                shaded = cell in p["cells"]
                if cell in assigned_by_cell and assigned_by_cell[cell] != shaded:
                    return False
                assigned_by_cell[cell] = shaded
            selected_cells |= set(p["cells"])

            # Immediate 2x2 check
            if _full_2x2_assigned_forbidden(blocks, selected_cells):
                return False

            # Neighbor type filtering
            t = p["type"]
            for nb in region_neigh[rid]:
                if domains.get(nb) is None:
                    if assigned_regions[nb] is not None and placements_by_region[nb][assigned_regions[nb]]["type"] == t:
                        return False
                    continue
                old = domains[nb]
                new = [j for j in old if placements_by_region[nb][j]["type"] != t]
                if not new:
                    return False
                if len(new) != len(old):
                    domains[nb] = new
                    if len(new) == 1 and nb not in inq:
                        q.append(nb)
                        inq.add(nb)

            # Local consistency against already assigned regions
            for other, opidx in assigned_regions.items():
                if other == rid or opidx is None:
                    continue
                if other in region_neigh[rid]:
                    if placements_by_region[other][opidx]["type"] == t:
                        return False

            if _forced_full_2x2_impossible(blocks, assigned_by_cell, domains, placements_by_region, cell_to_regions):
                return False

            if not _possible_connectivity_ok(n, m, assigned_regions, selected_cells, domains, placements_by_region):
                return False

        # Also filter domains by assigned neighbor types and assigned-cell contradictions
        changed = True
        while changed:
            changed = False
            for rid in regions:
                if domains[rid] is None:
                    continue
                forbidden_types = {
                    placements_by_region[nb][assigned_regions[nb]]["type"]
                    for nb in region_neigh[rid]
                    if assigned_regions.get(nb) is not None
                }
                old = domains[rid]
                new = []
                for pidx in old:
                    p = placements_by_region[rid][pidx]
                    if p["type"] in forbidden_types:
                        continue
                    ok = True
                    for cell in region_cells[rid]:
                        shaded = cell in p["cells"]
                        if cell in assigned_by_cell and assigned_by_cell[cell] != shaded:
                            ok = False
                            break
                    if ok:
                        new.append(pidx)
                if not new:
                    return False
                if len(new) != len(old):
                    domains[rid] = new
                    changed = True
                    if len(new) == 1 and rid not in inq:
                        q.append(rid)
                        inq.add(rid)
            while q:
                rid = q.popleft()
                inq.discard(rid)
                if domains[rid] is not None and len(domains[rid]) == 1:
                    # recurse into singleton commits without recursive call
                    pidx = domains[rid][0]
                    p = placements_by_region[rid][pidx]
                    domains[rid] = None
                    assigned_regions[rid] = pidx
                    for cell in region_cells[rid]:
                        shaded = cell in p["cells"]
                        if cell in assigned_by_cell and assigned_by_cell[cell] != shaded:
                            return False
                        assigned_by_cell[cell] = shaded
                    selected_cells |= set(p["cells"])
                    if _full_2x2_assigned_forbidden(blocks, selected_cells):
                        return False
                    t = p["type"]
                    for nb in region_neigh[rid]:
                        if domains.get(nb) is None:
                            if assigned_regions[nb] is not None and placements_by_region[nb][assigned_regions[nb]]["type"] == t:
                                return False
                            continue
                        old = domains[nb]
                        new = [j for j in old if placements_by_region[nb][j]["type"] != t]
                        if not new:
                            return False
                        if len(new) != len(old):
                            domains[nb] = new
                            changed = True
                            if len(new) == 1 and nb not in inq:
                                q.append(nb)
                                inq.add(nb)
                    if _forced_full_2x2_impossible(blocks, assigned_by_cell, domains, placements_by_region, cell_to_regions):
                        return False
                    if not _possible_connectivity_ok(n, m, assigned_regions, selected_cells, domains, placements_by_region):
                        return False

        return True

    def choose_region(domains, assigned_regions):
        # Most constrained, then most interactive
        best = None
        best_key = None
        for rid in regions:
            if assigned_regions[rid] is not None:
                continue
            d = domains[rid]
            if d is None:
                continue
            type_count = len({placements_by_region[rid][p]["type"] for p in d})
            key = (len(d), type_count, -len(region_neigh[rid]), -len(region_cells[rid]))
            if best is None or key < best_key:
                best = rid
                best_key = key
        return best

    def value_order(rid, domains):
        # Prefer placements with more neighbor contacts to help connectivity, and rarer types first.
        type_freq = defaultdict(int)
        for pidx in domains[rid]:
            type_freq[placements_by_region[rid][pidx]["type"]] += 1

        scored = []
        for pidx in domains[rid]:
            p = placements_by_region[rid][pidx]
            touch = 0
            boundary = 0
            for cell in p["cells"]:
                for nb in _neighbors4(cell, n, m):
                    if nb not in p["cells"]:
                        boundary += 1
                        nrid = grid[nb[0]][nb[1]]
                        if nrid != rid:
                            touch += 1
            scored.append((type_freq[p["type"]], -touch, -boundary, pidx))
        scored.sort()
        return [pidx for _, _, _, pidx in scored]

    def final_connected(assigned_regions):
        cells = set()
        for rid, pidx in assigned_regions.items():
            if pidx is None:
                return False
            cells |= set(placements_by_region[rid][pidx]["cells"])
        if not cells:
            return False
        comp = _components(cells, n, m)
        return len(comp) == 1

    def dfs(domains, assigned_regions, selected_cells, assigned_by_cell):
        if all(assigned_regions[rid] is not None for rid in regions):
            if _full_2x2_assigned_forbidden(blocks, selected_cells):
                return None
            if not final_connected(assigned_regions):
                return None
            ans = [[None for _ in range(m)] for _ in range(n)]
            for rid, pidx in assigned_regions.items():
                p = placements_by_region[rid][pidx]
                for r, c in p["cells"]:
                    ans[r][c] = p["type"]
            return ans

        rid = choose_region(domains, assigned_regions)
        if rid is None:
            return None

        for pidx in value_order(rid, domains):
            nd = clone_domains(domains)
            na = dict(assigned_regions)
            ns = set(selected_cells)
            nc = dict(assigned_by_cell)
            nd[rid] = [pidx]
            if not propagate(nd, na, ns, nc):
                continue
            res = dfs(nd, na, ns, nc)
            if res is not None:
                return res
        return None

    assigned_regions = {rid: None for rid in regions}
    selected_cells = set()
    assigned_by_cell = {}

    if not propagate(domains, assigned_regions, selected_cells, assigned_by_cell):
        return "No Solution"

    ans = dfs(domains, assigned_regions, selected_cells, assigned_by_cell)
    return "No Solution" if ans is None else repr(ans)

