    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, None, None, None, None, None, 3], [1, 2, 1, None, 1, 2, None], [2, 3, None, 2, None, None, 2], [3, None, None, 2, None, None, None], [None, 2, None, None, 3, None, 2], [None, None, None, 3, None, None, 3], [None, 2, None, 3, 2, 2, None]]}

from collections import deque, defaultdict

# Slitherlink solver:
# - Edge states: -1 unknown, 0 off, 1 on
# - Core propagation mirrors human deductions:
#   * clue saturation / completion
#   * vertex degree must be 0 or 2
#   * simple no-small-loop pruning when a closed component appears too early
# - Search uses most-constrained undecided edge first.

UNKNOWN = -1
OFF = 0
ON = 1


class SlitherlinkSolver:
    def __init__(self, data):
        self.data = data
        self.n = len(data)

        self.h_count = (self.n + 1) * self.n
        self.v_count = self.n * (self.n + 1)
        self.edge_count = self.h_count + self.v_count

        # Edge indexing:
        # horizontal (r, c): 0 <= r <= n, 0 <= c < n
        # vertical   (r, c): 0 <= r < n, 0 <= c <= n
        self.cell_edges = []
        self.vertex_edges = [[] for _ in range((self.n + 1) * (self.n + 1))]
        self.edge_vertices = [None] * self.edge_count
        self.edge_cells = [[] for _ in range(self.edge_count)]

        self._build_structures()

    def h_id(self, r, c):
        return r * self.n + c

    def v_id(self, r, c):
        return self.h_count + r * (self.n + 1) + c

    def vid(self, r, c):
        return r * (self.n + 1) + c

    def _build_structures(self):
        n = self.n

        # Horizontal edges
        for r in range(n + 1):
            for c in range(n):
                eid = self.h_id(r, c)
                v1 = self.vid(r, c)
                v2 = self.vid(r, c + 1)
                self.edge_vertices[eid] = (v1, v2)
                self.vertex_edges[v1].append(eid)
                self.vertex_edges[v2].append(eid)

                if r > 0:
                    self.edge_cells[eid].append((r - 1, c))
                if r < n:
                    self.edge_cells[eid].append((r, c))

        # Vertical edges
        for r in range(n):
            for c in range(n + 1):
                eid = self.v_id(r, c)
                v1 = self.vid(r, c)
                v2 = self.vid(r + 1, c)
                self.edge_vertices[eid] = (v1, v2)
                self.vertex_edges[v1].append(eid)
                self.vertex_edges[v2].append(eid)

                if c > 0:
                    self.edge_cells[eid].append((r, c - 1))
                if c < n:
                    self.edge_cells[eid].append((r, c))

        # Cells
        for r in range(n):
            row = []
            for c in range(n):
                row.append((
                    self.h_id(r, c),       # top
                    self.h_id(r + 1, c),   # bottom
                    self.v_id(r, c),       # left
                    self.v_id(r, c + 1),   # right
                ))
            self.cell_edges.append(row)

    def initial_state(self):
        return [UNKNOWN] * self.edge_count

    def set_edge(self, state, eid, val, queue):
        cur = state[eid]
        if cur == val:
            return True
        if cur != UNKNOWN and cur != val:
            return False
        state[eid] = val
        queue.append(eid)
        return True

    def propagate(self, state):
        queue = deque(range(self.edge_count))

        while queue:
            changed_eid = queue.popleft()

            # Re-check adjacent clue cells
            for cell in self.edge_cells[changed_eid]:
                r, c = cell
                clue = self.data[r][c]
                if clue is None:
                    continue
                edges = self.cell_edges[r][c]
                on = 0
                off = 0
                unk = []
                for eid in edges:
                    s = state[eid]
                    if s == ON:
                        on += 1
                    elif s == OFF:
                        off += 1
                    else:
                        unk.append(eid)

                if on > clue:
                    return False
                if on + len(unk) < clue:
                    return False

                if on == clue:
                    for eid in unk:
                        if not self.set_edge(state, eid, OFF, queue):
                            return False
                elif on + len(unk) == clue:
                    for eid in unk:
                        if not self.set_edge(state, eid, ON, queue):
                            return False

            # Re-check adjacent vertices
            v1, v2 = self.edge_vertices[changed_eid]
            for v in (v1, v2):
                edges = self.vertex_edges[v]
                on = 0
                unk = []
                for eid in edges:
                    s = state[eid]
                    if s == ON:
                        on += 1
                    elif s == UNKNOWN:
                        unk.append(eid)

                if on > 2:
                    return False
                if on == 1 and not unk:
                    return False
                if on == 2:
                    for eid in unk:
                        if not self.set_edge(state, eid, OFF, queue):
                            return False
                elif on == 1 and len(unk) == 1:
                    if not self.set_edge(state, unk[0], ON, queue):
                        return False
                elif on == 0 and len(unk) == 1:
                    if not self.set_edge(state, unk[0], OFF, queue):
                        return False

            # Lightweight no-premature-subloop pruning
            if not self.no_premature_cycle(state):
                return False

        return True

    def no_premature_cycle(self, state):
        # If a closed ON-cycle exists while there are ON-edges outside it, reject.
        # If a closed ON-cycle exists and clue constraints are not all already satisfiable/final, reject.
        adj = defaultdict(list)
        on_edges = []
        for eid, s in enumerate(state):
            if s == ON:
                v1, v2 = self.edge_vertices[eid]
                adj[v1].append((v2, eid))
                adj[v2].append((v1, eid))
                on_edges.append(eid)

        if not on_edges:
            return True

        seen_v = set()
        seen_e = set()

        for start in list(adj.keys()):
            if start in seen_v:
                continue
            comp_vs = set()
            comp_es = set()
            stack = [start]
            while stack:
                v = stack.pop()
                if v in comp_vs:
                    continue
                comp_vs.add(v)
                seen_v.add(v)
                for nv, eid in adj[v]:
                    comp_es.add(eid)
                    if nv not in comp_vs:
                        stack.append(nv)

            # Closed component means every vertex in component has degree 2 in ON-graph
            closed = all(len(adj[v]) == 2 for v in comp_vs)
            if closed:
                if len(comp_es) != len(on_edges):
                    return False
                # Only one closed component exists among all ON-edges.
                # It is acceptable only if all clue counts are already exactly satisfied
                # and no unknown edge could be turned on at a used vertex.
                for r in range(self.n):
                    for c in range(self.n):
                        clue = self.data[r][c]
                        if clue is None:
                            continue
                        edges = self.cell_edges[r][c]
                        on = sum(state[eid] == ON for eid in edges)
                        unk = sum(state[eid] == UNKNOWN for eid in edges)
                        if on > clue or on + unk < clue:
                            return False
                        if unk and on != clue:
                            return False
                # Vertices on the loop must have no unknown incident edges left
                for v in comp_vs:
                    for eid in self.vertex_edges[v]:
                        if state[eid] == UNKNOWN:
                            return False

        return True

    def choose_edge(self, state):
        best = None
        best_score = -1

        for eid, s in enumerate(state):
            if s != UNKNOWN:
                continue
            score = 0

            for cell in self.edge_cells[eid]:
                r, c = cell
                clue = self.data[r][c]
                if clue is None:
                    continue
                edges = self.cell_edges[r][c]
                on = sum(state[x] == ON for x in edges)
                unk = sum(state[x] == UNKNOWN for x in edges)
                # More constrained clues first
                score += 10
                score += 4 - unk
                score += abs(clue - 2)

            v1, v2 = self.edge_vertices[eid]
            for v in (v1, v2):
                on = sum(state[x] == ON for x in self.vertex_edges[v])
                unk = sum(state[x] == UNKNOWN for x in self.vertex_edges[v])
                score += 3 * on + (4 - unk)

            if score > best_score:
                best_score = score
                best = eid

        return best

    def is_complete_valid(self, state):
        if any(s == UNKNOWN for s in state):
            return False

        # Clues
        for r in range(self.n):
            for c in range(self.n):
                clue = self.data[r][c]
                if clue is None:
                    continue
                if sum(state[eid] == ON for eid in self.cell_edges[r][c]) != clue:
                    return False

        # Degrees
        on_vertices = []
        for v in range((self.n + 1) * (self.n + 1)):
            deg = sum(state[eid] == ON for eid in self.vertex_edges[v])
            if deg not in (0, 2):
                return False
            if deg == 2:
                on_vertices.append(v)

        if not on_vertices:
            return False

        # Single loop connectivity
        start = on_vertices[0]
        seen = set()
        stack = [start]
        adj = defaultdict(list)
        on_edge_count = 0
        for eid, s in enumerate(state):
            if s == ON:
                on_edge_count += 1
                a, b = self.edge_vertices[eid]
                adj[a].append(b)
                adj[b].append(a)

        while stack:
            v = stack.pop()
            if v in seen:
                continue
            seen.add(v)
            for nv in adj[v]:
                if nv not in seen:
                    stack.append(nv)

        return all(v in seen for v in on_vertices)

    def search(self, state):
        if not self.propagate(state):
            return None

        if self.is_complete_valid(state):
            return state

        eid = self.choose_edge(state)
        if eid is None:
            return None

        # Value ordering: try ON first when supported by constraints
        order = [ON, OFF]
        for val in order:
            new_state = state[:]
            new_state[eid] = val
            res = self.search(new_state)
            if res is not None:
                return res
        return None

    def build_loop_path(self, state):
        adj = defaultdict(list)
        for eid, s in enumerate(state):
            if s == ON:
                a, b = self.edge_vertices[eid]
                adj[a].append(b)
                adj[b].append(a)

        if not adj:
            return []

        start = min(adj.keys())
        path = [start]
        prev = None
        cur = start

        while True:
            nbrs = adj[cur]
            if prev is None:
                nxt = nbrs[0]
            else:
                if len(nbrs) != 2:
                    return []
                nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]

            path.append(nxt)
            prev, cur = cur, nxt
            if cur == start:
                break

        return [self.vertex_to_coord(v) for v in path]

    def vertex_to_coord(self, v):
        return (v // (self.n + 1), v % (self.n + 1))


def solve(observation):
    data = observation["data"]
    solver = SlitherlinkSolver(data)
    state = solver.initial_state()
    result = solver.search(state)
    if result is None:
        return "No Solution"
    return str(solver.build_loop_path(result))


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None], [None, None, None, None], [None, None, None, None], [None, None, None, None]], 'horizontal': {'(0,1.5)': '<', '(0,2.5)': '>'}, 'vertical': {'(1.5,1)': 'v', '(2.5,0)': 'v', '(2.5,1)': 'v', '(2.5,3)': 'v'}}

from ast import literal_eval

# General Futoshiki solver using:
# - bitmask domains
# - aggressive propagation
# - all-different GAC by matching on every row/column
# - inequality arc filtering
# - MRV + degree-guided branching
#
# The image format uses stringified coordinates as keys.
# Horizontal symbols are unambiguous.
# Vertical '^'/'v' conventions can vary across sources/images,
# so solve() will try both consistent interpretations.

def solve(observation):
    data = observation["data"]
    n = len(data)
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def min_value(mask):
        return (mask & -mask).bit_length()

    def values(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    def coord_key_to_tuple(s):
        return literal_eval(s)

    # Build units and peers
    idx = lambda r, c: r * n + c
    rows = [[idx(r, c) for c in range(n)] for r in range(n)]
    cols = [[idx(r, c) for r in range(n)] for c in range(n)]
    units = rows + cols

    peers = [set() for _ in range(n * n)]
    for unit in units:
        for a in unit:
            for b in unit:
                if a != b:
                    peers[a].add(b)

    # Horizontal constraints are fixed.
    base_h_constraints = []
    for k, sym in observation.get("horizontal", {}).items():
        r, x = coord_key_to_tuple(k)
        c = int(x - 0.5)
        a = idx(int(r), c)
        b = idx(int(r), c + 1)
        base_h_constraints.append((a, b, sym))

    # Vertical constraints depend on convention:
    # interpretation A: '^' means upper > lower, 'v' means upper < lower
    # interpretation B: '^' means upper < lower, 'v' means upper > lower
    vertical_raw = []
    for k, sym in observation.get("vertical", {}).items():
        y, c = coord_key_to_tuple(k)
        r = int(y - 0.5)
        vertical_raw.append((idx(r, int(c)), idx(r + 1, int(c)), sym))

    def build_constraints(vmode):
        constraints = list(base_h_constraints)
        for a, b, sym in vertical_raw:
            if vmode == 0:
                rel = '<' if sym == 'v' else '>'
            else:
                rel = '>' if sym == 'v' else '<'
            constraints.append((a, b, rel))
        return constraints

    # Support masks for inequality filtering
    less_support = [0] * (full + 1)
    greater_support = [0] * (full + 1)
    for m in range(full + 1):
        ls = 0
        gs = 0
        for v in values(m):
            if v > 1:
                ls |= (1 << (v - 1)) - 1
            if v < n:
                gs |= full ^ ((1 << v) - 1)
        less_support[m] = ls
        greater_support[m] = gs

    def enforce_ineq_pair(ma, mb, rel):
        # rel is relation between A and B: A < B or A > B
        if rel == '<':
            na = ma & less_support[mb]
            nb = mb & greater_support[ma]
        else:
            na = ma & greater_support[mb]
            nb = mb & less_support[ma]
        return na, nb

    def matching_exists(cell_masks):
        # Bipartite perfect matching: cells -> values 1..n
        match_val = [None] * (n + 1)

        def dfs(i, seen):
            m = cell_masks[i]
            while m:
                b = m & -m
                v = b.bit_length()
                m ^= b
                if seen[v]:
                    continue
                seen[v] = True
                if match_val[v] is None or dfs(match_val[v], seen):
                    match_val[v] = i
                    return True
            return False

        for i in range(len(cell_masks)):
            seen = [False] * (n + 1)
            if not dfs(i, seen):
                return False
        return True

    def alldiff_gac(domains, unit):
        # Generalized arc consistency for all-different on a unit via matching tests.
        masks = [domains[i] for i in unit]
        if any(m == 0 for m in masks):
            return False, False
        # Quick Hall-like fail check: full matching must exist
        if not matching_exists(masks):
            return False, False

        changed = False
        for local_i, cell in enumerate(unit):
            m = domains[cell]
            new_m = m
            mm = m
            while mm:
                b = mm & -mm
                mm ^= b
                test_masks = masks[:]
                test_masks[local_i] = b
                if not matching_exists(test_masks):
                    new_m &= ~b
            if new_m == 0:
                return False, False
            if new_m != domains[cell]:
                domains[cell] = new_m
                masks[local_i] = new_m
                changed = True
        return True, changed

    def propagate(domains, constraints):
        changed = True
        while changed:
            changed = False

            # Fixed-value peer elimination
            fixed_cells = [i for i, m in enumerate(domains) if m and (m & (m - 1)) == 0]
            for i in fixed_cells:
                vmask = domains[i]
                for j in peers[i]:
                    if domains[j] & vmask:
                        nm = domains[j] & ~vmask
                        if nm == 0:
                            return False
                        if nm != domains[j]:
                            domains[j] = nm
                            changed = True

            # Inequality propagation
            for a, b, rel in constraints:
                na, nb = enforce_ineq_pair(domains[a], domains[b], rel)
                if na == 0 or nb == 0:
                    return False
                if na != domains[a]:
                    domains[a] = na
                    changed = True
                if nb != domains[b]:
                    domains[b] = nb
                    changed = True

            # All-different GAC on each row/column
            for unit in units:
                ok, ch = alldiff_gac(domains, unit)
                if not ok:
                    return False
                changed |= ch

            # Hidden singles
            for unit in units:
                for v in range(1, n + 1):
                    b = bit(v)
                    places = [cell for cell in unit if domains[cell] & b]
                    if not places:
                        return False
                    if len(places) == 1 and domains[places[0]] != b:
                        domains[places[0]] = b
                        changed = True

            # Duplicate fixed value contradiction in units
            for unit in units:
                seen = 0
                for cell in unit:
                    m = domains[cell]
                    if m & (m - 1) == 0:
                        if seen & m:
                            return False
                        seen |= m

            # Final inequality recheck after stronger reductions
            for a, b, rel in constraints:
                na, nb = enforce_ineq_pair(domains[a], domains[b], rel)
                if na == 0 or nb == 0:
                    return False
                if na != domains[a]:
                    domains[a] = na
                    changed = True
                if nb != domains[b]:
                    domains[b] = nb
                    changed = True

        return True

    def solved(domains):
        return all(m and (m & (m - 1)) == 0 for m in domains)

    def select_cell(domains, constraints_by_cell):
        best = None
        best_key = None
        for i, m in enumerate(domains):
            pc = popcount(m)
            if pc <= 1:
                continue
            key = (pc, -constraints_by_cell[i])
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def order_values(cell, domains, constraints_lookup):
        # Least-constraining value heuristic
        scored = []
        for v in values(domains[cell]):
            b = bit(v)
            score = 0
            for nb, rel, cell_is_left in constraints_lookup[cell]:
                other = domains[nb]
                if cell_is_left:
                    na, nbm = enforce_ineq_pair(b, other, rel)
                else:
                    nbm, na = enforce_ineq_pair(other, b, rel)
                score += popcount(other) - popcount(nbm)
            scored.append((score, b))
        scored.sort()
        return [b for _, b in scored]

    def search(domains, constraints, constraints_lookup, constraints_by_cell):
        if not propagate(domains, constraints):
            return None
        if solved(domains):
            return domains

        cell = select_cell(domains, constraints_by_cell)
        if cell is None:
            return None

        for vmask in order_values(cell, domains, constraints_lookup):
            new_domains = domains[:]
            new_domains[cell] = vmask
            result = search(new_domains, constraints, constraints_lookup, constraints_by_cell)
            if result is not None:
                return result
        return None

    # Try both vertical interpretations if necessary.
    for vmode in (0, 1):
        constraints = build_constraints(vmode)
        constraints_lookup = [[] for _ in range(n * n)]
        constraints_by_cell = [0] * (n * n)
        for a, b, rel in constraints:
            constraints_lookup[a].append((b, rel, True))
            constraints_lookup[b].append((a, rel, False))
            constraints_by_cell[a] += 1
            constraints_by_cell[b] += 1

        domains = [full] * (n * n)
        consistent = True
        for r in range(n):
            for c in range(n):
                val = data[r][c]
                if val is not None:
                    if not (1 <= val <= n):
                        consistent = False
                        break
                    domains[idx(r, c)] = bit(val)
            if not consistent:
                break
        if not consistent:
            continue

        result = search(domains, constraints, constraints_lookup, constraints_by_cell)
        if result is not None:
            grid = []
            for r in range(n):
                row = []
                for c in range(n):
                    row.append(min_value(result[idx(r, c)]))
                grid.append(row)
            return grid

    return "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, 1, 5], [None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None], [None, None, None, None, None]], 'horizontal': {'(0, 0.5)': '>', '(0, 1.5)': '>', '(1, 0.5)': '<', '(2, 1.5)': '<', '(2, 3.5)': '<', '(3, 0.5)': '<'}, 'vertical': {'(2.5, 3)': 'v', '(3.5, 4)': 'v'}}

from ast import literal_eval

def solve(observation):
    n = len(observation['data'])
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def popcount(x):
        return x.bit_count()

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    def values(mask):
        while mask:
            b = mask & -mask
            yield b.bit_length()
            mask ^= b

    # Build inequality list as directed constraints a < b
    lt_edges = []
    neighbors = [[[] for _ in range(n)] for _ in range(n)]

    for k, sym in observation.get('horizontal', {}).items():
        r, c05 = literal_eval(k)
        c = int(c05 - 0.5)
        a = (r, c)
        b = (r, c + 1)
        if sym == '<':
            lt_edges.append((a, b))
            neighbors[r][c].append((r, c + 1))
            neighbors[r][c + 1].append((r, c))
        elif sym == '>':
            lt_edges.append((b, a))
            neighbors[r][c].append((r, c + 1))
            neighbors[r][c + 1].append((r, c))
        else:
            return "No Solution"

    # Vertical convention can vary by source. Try both if needed.
    vertical_items = list(observation.get('vertical', {}).items())

    def build_vertical_edges(mode):
        # mode 0: '^' => top < bottom, 'v' => top > bottom
        # mode 1: '^' => top > bottom, 'v' => top < bottom
        edges = []
        local_neighbors = [[list(neighbors[r][c]) for c in range(n)] for r in range(n)]
        for k, sym in vertical_items:
            r05, c = literal_eval(k)
            r = int(r05 - 0.5)
            top = (r, c)
            bot = (r + 1, c)
            local_neighbors[r][c].append((r + 1, c))
            local_neighbors[r + 1][c].append((r, c))
            if mode == 0:
                if sym == '^':
                    edges.append((top, bot))
                elif sym == 'v':
                    edges.append((bot, top))
                else:
                    return None, None
            else:
                if sym == '^':
                    edges.append((bot, top))
                elif sym == 'v':
                    edges.append((top, bot))
                else:
                    return None, None
        return edges, local_neighbors

    def supports_lt(ma, mb):
        # prune a<b using min/max support, then exact support if needed
        if ma == 0 or mb == 0:
            return 0, 0, False
        min_b = min_val(mb)
        max_a = max_val(ma)
        na = ma & ((1 << (min_b - 1)) - 1)
        nb = mb & ~((1 << max_a) - 1)
        if na == 0 or nb == 0:
            return 0, 0, False

        # Exact support pruning
        # A value va in na is allowed iff some vb in nb has va < vb.
        # This means va < max(nb). Similarly vb > min(na).
        max_nb = max_val(nb)
        min_na = min_val(na)
        na2 = na & ((1 << (max_nb - 1)) - 1)
        nb2 = nb & ~((1 << min_na) - 1)
        if na2 == 0 or nb2 == 0:
            return 0, 0, False
        return na2, nb2, True

    def initial_domains():
        dom = [[full for _ in range(n)] for _ in range(n)]
        for r in range(n):
            for c in range(n):
                v = observation['data'][r][c]
                if v is not None:
                    if not (1 <= v <= n):
                        return None
                    dom[r][c] = bit(v)
        return dom

    def clone_domains(dom):
        return [row[:] for row in dom]

    def units():
        row_units = [[(r, c) for c in range(n)] for r in range(n)]
        col_units = [[(r, c) for r in range(n)] for c in range(n)]
        return row_units + col_units

    all_units = units()

    def assign_and_propagate(dom, edges):
        # Queue-based propagation of singles + inequalities + all-different
        changed = True
        while changed:
            changed = False

            # Row/column used-value elimination and contradiction checks
            for r in range(n):
                seen = 0
                for c in range(n):
                    m = dom[r][c]
                    if m == 0:
                        return None
                    if m & (m - 1) == 0:
                        if seen & m:
                            return None
                        seen |= m
                if seen:
                    for c in range(n):
                        m = dom[r][c]
                        if m & (m - 1):
                            nm = m & ~seen
                            if nm != m:
                                if nm == 0:
                                    return None
                                dom[r][c] = nm
                                changed = True

            for c in range(n):
                seen = 0
                for r in range(n):
                    m = dom[r][c]
                    if m == 0:
                        return None
                    if m & (m - 1) == 0:
                        if seen & m:
                            return None
                        seen |= m
                if seen:
                    for r in range(n):
                        m = dom[r][c]
                        if m & (m - 1):
                            nm = m & ~seen
                            if nm != m:
                                if nm == 0:
                                    return None
                                dom[r][c] = nm
                                changed = True

            # Hidden singles in every row/col
            for unit in all_units:
                counts = [0] * n
                lastpos = [None] * n
                for r, c in unit:
                    m = dom[r][c]
                    x = m
                    while x:
                        b = x & -x
                        idx = b.bit_length() - 1
                        counts[idx] += 1
                        lastpos[idx] = (r, c)
                        x ^= b
                for v_idx, cnt in enumerate(counts):
                    if cnt == 0:
                        return None
                    if cnt == 1:
                        r, c = lastpos[v_idx]
                        forced = 1 << v_idx
                        if dom[r][c] != forced:
                            if not (dom[r][c] & forced):
                                return None
                            dom[r][c] = forced
                            changed = True

            # Naked subsets in rows and columns
            for unit in all_units:
                freq = {}
                for r, c in unit:
                    m = dom[r][c]
                    pc = popcount(m)
                    if 2 <= pc <= 4:
                        freq[m] = freq.get(m, 0) + 1
                for m, cnt in freq.items():
                    if cnt == popcount(m):
                        for r, c in unit:
                            if dom[r][c] != m and (dom[r][c] & m):
                                nm = dom[r][c] & ~m
                                if nm == 0:
                                    return None
                                if nm != dom[r][c]:
                                    dom[r][c] = nm
                                    changed = True

            # Inequality pruning
            for (ra, ca), (rb, cb) in edges:
                na, nb, ok = supports_lt(dom[ra][ca], dom[rb][cb])
                if not ok:
                    return None
                if na != dom[ra][ca]:
                    dom[ra][ca] = na
                    changed = True
                if nb != dom[rb][cb]:
                    dom[rb][cb] = nb
                    changed = True

            # Strong Latin bounds: if a cell is singleton, remove from peers immediately
            # Already covered above, but this catches cascade efficiently after other deductions.
            # Also contradiction if duplicate singleton in row/col handled above.

        return dom

    def solved(dom):
        return all(dom[r][c] & (dom[r][c] - 1) == 0 for r in range(n) for c in range(n))

    def choose_cell(dom, local_neighbors):
        best = None
        best_key = None
        for r in range(n):
            for c in range(n):
                m = dom[r][c]
                pc = popcount(m)
                if pc > 1:
                    # Most constrained first, break ties by more inequality neighbors
                    key = (pc, -len(local_neighbors[r][c]))
                    if best is None or key < best_key:
                        best = (r, c)
                        best_key = key
        return best

    def order_values(mask, r, c, dom, edges):
        vals = list(values(mask))
        # Least-constraining order using peer impact
        scored = []
        for v in vals:
            b = bit(v)
            score = 0
            for cc in range(n):
                if cc != c and (dom[r][cc] & b):
                    score += 1
            for rr in range(n):
                if rr != r and (dom[rr][c] & b):
                    score += 1
            for (ra, ca), (rb, cb) in edges:
                if (ra, ca) == (r, c):
                    # assigning smaller side
                    if dom[rb][cb]:
                        score += sum(1 for w in values(dom[rb][cb]) if w <= v)
                elif (rb, cb) == (r, c):
                    # assigning larger side
                    if dom[ra][ca]:
                        score += sum(1 for w in values(dom[ra][ca]) if w >= v)
            scored.append((score, v))
        scored.sort()
        return [v for _, v in scored]

    def search(dom, edges, local_neighbors):
        dom = assign_and_propagate(dom, edges)
        if dom is None:
            return None
        if solved(dom):
            return [[min_val(dom[r][c]) for c in range(n)] for r in range(n)]

        r, c = choose_cell(dom, local_neighbors)
        m = dom[r][c]
        for v in order_values(m, r, c, dom, edges):
            nd = clone_domains(dom)
            nd[r][c] = bit(v)
            res = search(nd, edges, local_neighbors)
            if res is not None:
                return res
        return None

    base = initial_domains()
    if base is None:
        return "No Solution"

    # Try both vertical interpretations if vertical signs exist.
    modes = [0, 1] if vertical_items else [0]
    solutions = []
    for mode in modes:
        vedges, local_neighbors = build_vertical_edges(mode)
        if vedges is None:
            continue
        edges = lt_edges + vedges
        res = search(clone_domains(base), edges, local_neighbors)
        if res is not None:
            solutions.append(res)

    if not solutions:
        return "No Solution"

    # If both conventions coincidentally solve to same grid, return it; otherwise return first valid.
    first = solutions[0]
    if all(sol == first for sol in solutions[1:]):
        return str(first)
    return str(first)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [1, 17, 9, 20, 23, 10, 11], 'col_sum': [15, 13, 9, 22, 27, 9, 7]}

# Weighted binary grid solver.
# Row i has weight (i+1), column j has weight (j+1).
# A black cell at (i, j) contributes:
# - (j+1) to row i's target
# - (i+1) to column j's target
#
# The solver is generalized for any rectangular size implied by:
#   len(row_sum) rows, len(col_sum) columns
#
# Strategy:
# 1) Precompute all row patterns (bitmasks) satisfying each row target.
# 2) Repeatedly propagate column constraints using min/max weighted contributions.
# 3) Apply cell-level deduction:
#      for each (row, col), determine whether 0 and/or 1 remain feasible
#      with respect to the current domains of all other rows.
# 4) If unresolved, branch on the most constrained row domain.

from functools import lru_cache

def _bit(mask, j):
    return (mask >> j) & 1

def _generate_row_masks(c, target):
    col_weights = list(range(1, c + 1))
    total = c * (c + 1) // 2
    if target < 0 or target > total:
        return []

    masks = []

    def dfs(j, cur_sum, mask):
        if cur_sum > target:
            return
        if j == c:
            if cur_sum == target:
                masks.append(mask)
            return

        rem = sum(range(j + 2, c + 1))
        if cur_sum + rem < target:
            return

        dfs(j + 1, cur_sum, mask)
        dfs(j + 1, cur_sum + col_weights[j], mask | (1 << j))

    dfs(0, 0, 0)
    return masks

def _row_forced_bits(domain, c):
    if not domain:
        return None, None
    all1 = (1 << c) - 1
    any1 = 0
    for m in domain:
        all1 &= m
        any1 |= m
    forced1 = all1
    forced0 = ((1 << c) - 1) ^ any1
    return forced1, forced0

def _propagate(domains, row_sum, col_sum):
    r = len(row_sum)
    c = len(col_sum)
    row_weights = [i + 1 for i in range(r)]

    changed = True
    while changed:
        changed = False

        # Remove duplicate masks if any and fail early on empty domains.
        for i in range(r):
            if not domains[i]:
                return None

        # Per-row forced info.
        forced1 = [0] * r
        forced0 = [0] * r
        any1 = [0] * r
        for i in range(r):
            f1, f0 = _row_forced_bits(domains[i], c)
            if f1 is None:
                return None
            forced1[i] = f1
            forced0[i] = f0
            v = 0
            for m in domains[i]:
                v |= m
            any1[i] = v

        # Column aggregate min/max contribution.
        col_min = [0] * c
        col_max = [0] * c
        for j in range(c):
            bit = 1 << j
            mn = 0
            mx = 0
            for i in range(r):
                w = row_weights[i]
                if forced1[i] & bit:
                    mn += w
                    mx += w
                elif any1[i] & bit:
                    mx += w
            col_min[j] = mn
            col_max[j] = mx
            if not (mn <= col_sum[j] <= mx):
                return None

        # Cell-level feasibility filtering based on column residual intervals.
        for i in range(r):
            w = row_weights[i]
            new_domain = []
            for m in domains[i]:
                ok = True
                for j in range(c):
                    bit = 1 << j

                    # This row's contribution bounds to column j before fixing current mask bit.
                    row_min = w if (forced1[i] & bit) else 0
                    row_max = w if (any1[i] & bit) else 0

                    others_min = col_min[j] - row_min
                    others_max = col_max[j] - row_max

                    if m & bit:
                        # Require bit=1 feasible.
                        if not (others_min + w <= col_sum[j] <= others_max + w):
                            ok = False
                            break
                    else:
                        # Require bit=0 feasible.
                        if not (others_min <= col_sum[j] <= others_max):
                            ok = False
                            break
                if ok:
                    new_domain.append(m)

            if not new_domain:
                return None
            if len(new_domain) != len(domains[i]):
                domains[i] = new_domain
                changed = True

        # Stronger propagation: if a bit value is globally impossible in a column for a row,
        # remove all row masks using that bit value.
        # This is done using current domains after the previous filtering round.
        forced1 = [0] * r
        any1 = [0] * r
        for i in range(r):
            f1, _ = _row_forced_bits(domains[i], c)
            forced1[i] = f1
            v = 0
            for m in domains[i]:
                v |= m
            any1[i] = v

        col_min = [0] * c
        col_max = [0] * c
        for j in range(c):
            bit = 1 << j
            mn = 0
            mx = 0
            for i in range(r):
                w = row_weights[i]
                if forced1[i] & bit:
                    mn += w
                    mx += w
                elif any1[i] & bit:
                    mx += w
            col_min[j] = mn
            col_max[j] = mx
            if not (mn <= col_sum[j] <= mx):
                return None

        for i in range(r):
            w = row_weights[i]
            allowed0_mask = 0
            allowed1_mask = 0

            # Determine per-column whether current row may still be 0 or 1.
            may0 = [True] * c
            may1 = [True] * c
            for j in range(c):
                bit = 1 << j
                row_min = w if (forced1[i] & bit) else 0
                row_max = w if (any1[i] & bit) else 0
                others_min = col_min[j] - row_min
                others_max = col_max[j] - row_max
                may0[j] = (others_min <= col_sum[j] <= others_max)
                may1[j] = (others_min + w <= col_sum[j] <= others_max + w)
                if may0[j]:
                    allowed0_mask |= bit
                if may1[j]:
                    allowed1_mask |= bit
                if not may0[j] and not may1[j]:
                    return None

            new_domain = []
            for m in domains[i]:
                bad = False
                for j in range(c):
                    bit = 1 << j
                    if (m & bit) and not (allowed1_mask & bit):
                        bad = True
                        break
                    if not (m & bit) and not (allowed0_mask & bit):
                        bad = True
                        break
                if not bad:
                    new_domain.append(m)

            if not new_domain:
                return None
            if len(new_domain) != len(domains[i]):
                domains[i] = new_domain
                changed = True

    # Final exact column check if all rows fixed.
    if all(len(d) == 1 for d in domains):
        masks = [d[0] for d in domains]
        for j in range(c):
            s = 0
            for i in range(r):
                if _bit(masks[i], j):
                    s += i + 1
            if s != col_sum[j]:
                return None

    return domains

def _choose_branch_row(domains):
    best_i = None
    best_len = None
    for i, d in enumerate(domains):
        if len(d) > 1:
            ld = len(d)
            if best_len is None or ld < best_len:
                best_len = ld
                best_i = i
    return best_i

def _search(domains, row_sum, col_sum):
    domains = [list(d) for d in domains]
    domains = _propagate(domains, row_sum, col_sum)
    if domains is None:
        return None
    if all(len(d) == 1 for d in domains):
        return [d[0] for d in domains]

    i = _choose_branch_row(domains)
    if i is None:
        return None

    # Value ordering: masks that are more column-constraining first.
    # Prefer masks with more rare bits? Simpler heuristic: heavier weighted columns first.
    c = len(col_sum)
    def score(mask):
        return sum((j + 1) for j in range(c) if (mask >> j) & 1)

    for m in sorted(domains[i], key=score, reverse=True):
        new_domains = [list(d) for d in domains]
        new_domains[i] = [m]
        ans = _search(new_domains, row_sum, col_sum)
        if ans is not None:
            return ans
    return None

def solve(observation):
    row_sum = list(observation["row_sum"])
    col_sum = list(observation["col_sum"])
    r = len(row_sum)
    c = len(col_sum)

    # Global consistency: total weighted black contribution counted from rows and columns must match.
    if sum(row_sum) != sum(col_sum):
        return "No Solution"

    domains = []
    for target in row_sum:
        masks = _generate_row_masks(c, target)
        if not masks:
            return "No Solution"
        domains.append(masks)

    masks = _search(domains, row_sum, col_sum)
    if masks is None:
        return "No Solution"

    grid = []
    for i in range(r):
        row = []
        for j in range(c):
            row.append('B' if _bit(masks[i], j) else None)
        grid.append(row)
    return repr(grid)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], ['W', None, None, 'W', None, None, 'B', 'W'], ['W', None, None, 'W', None, None, 'W', 'W'], [None, None, None, 'W', 'B', 'W', None, None], [None, None, 'W', None, 'W', None, 'W', None], [None, None, 'W', None, None, None, None, None], [None, None, 'W', None, 'W', None, 'W', None], ['B', 'W', None, None, None, 'W', None, None]]}

# Generalized Masyu-on-dots solver.
# The loop runs along grid edges between adjacent dot coordinates.
# Each clue sits on a dot and constrains the local path shape through that dot.

U, R, D, L = 1, 2, 4, 8
DIRS = [U, R, D, L]
DRC = {
    U: (-1, 0),
    R: (0, 1),
    D: (1, 0),
    L: (0, -1),
}
OPP = {U: D, D: U, L: R, R: L}

EMPTY = 0
SH = L | R
SV = U | D
TUR = U | R
TRD = R | D
TDL = D | L
TLU = L | U

ALL_STATES = [EMPTY, SH, SV, TUR, TRD, TDL, TLU]
TURN_STATES = {TUR, TRD, TDL, TLU}
STRAIGHT_STATES = {SH, SV}

STATE_NAME = {
    EMPTY: "EMPTY",
    SH: "SH",
    SV: "SV",
    TUR: "TUR",
    TRD: "TRD",
    TDL: "TDL",
    TLU: "TLU",
}

# For a neighbor relative to current vertex, these are turn states that use the connecting edge.
TURN_WITH_EDGE = {
    L: {TUR, TRD},  # left neighbor uses its R edge
    R: {TLU, TDL},  # right neighbor uses its L edge
    U: {TRD, TDL},  # upper neighbor uses its D edge
    D: {TUR, TLU},  # lower neighbor uses its U edge
}

# For black circles: if the black cell turns toward a given neighbor,
# that neighbor must be straight in the corresponding orientation.
BLACK_NEIGHBOR_REQ = {
    TUR: {U: {SV}, R: {SH}},
    TRD: {R: {SH}, D: {SV}},
    TDL: {D: {SV}, L: {SH}},
    TLU: {L: {SH}, U: {SV}},
}


def popcount(x):
    return (x & 1) + ((x >> 1) & 1) + ((x >> 2) & 1) + ((x >> 3) & 1)


def has_dir(state, d):
    return (state & d) != 0


def state_uses_edge_toward(state, d):
    return has_dir(state, d)


def is_turn(state):
    return state in TURN_STATES


def is_straight(state):
    return state in STRAIGHT_STATES


def in_bounds(n, r, c):
    return 0 <= r < n and 0 <= c < n


def neighbors(n, r, c):
    out = []
    for d in DIRS:
        dr, dc = DRC[d]
        rr, cc = r + dr, c + dc
        if in_bounds(n, rr, cc):
            out.append((d, rr, cc))
    return out


def initial_domains(data):
    n = len(data)
    domains = [[None] * n for _ in range(n)]
    for r in range(n):
        for c in range(n):
            clue = data[r][c]
            if clue == 'W':
                dom = {SH, SV}
            elif clue == 'B':
                dom = {TUR, TRD, TDL, TLU}
            else:
                dom = set(ALL_STATES)
            domains[r][c] = dom
    return domains


def boundary_filter(domains, data):
    n = len(data)
    changed = False
    for r in range(n):
        for c in range(n):
            newdom = set()
            for s in domains[r][c]:
                ok = True
                for d in DIRS:
                    if has_dir(s, d):
                        dr, dc = DRC[d]
                        rr, cc = r + dr, c + dc
                        if not in_bounds(n, rr, cc):
                            ok = False
                            break
                if not ok:
                    continue
                clue = data[r][c]
                if clue == 'W':
                    # White must be straight and have neighbors on both ends.
                    if s == SH and not (c - 1 >= 0 and c + 1 < n):
                        continue
                    if s == SV and not (r - 1 >= 0 and r + 1 < n):
                        continue
                elif clue == 'B':
                    # Black must turn and both turn directions must have neighbors.
                    if popcount(s) != 2 or s in STRAIGHT_STATES or s == EMPTY:
                        continue
                newdom.add(s)
            if newdom != domains[r][c]:
                domains[r][c] = newdom
                changed = True
    return changed


def pair_supported(s1, s2, d_from_1_to_2):
    return state_uses_edge_toward(s1, d_from_1_to_2) == state_uses_edge_toward(s2, OPP[d_from_1_to_2])


def prune_edge_consistency(domains):
    n = len(domains)
    changed = False
    for r in range(n):
        for c in range(n):
            for d, rr, cc in neighbors(n, r, c):
                dom1 = domains[r][c]
                dom2 = domains[rr][cc]
                keep1 = set()
                for s1 in dom1:
                    ok = False
                    for s2 in dom2:
                        if pair_supported(s1, s2, d):
                            ok = True
                            break
                    if ok:
                        keep1.add(s1)
                if keep1 != dom1:
                    domains[r][c] = keep1
                    dom1 = keep1
                    changed = True
                keep2 = set()
                for s2 in dom2:
                    ok = False
                    for s1 in dom1:
                        if pair_supported(s1, s2, d):
                            ok = True
                            break
                    if ok:
                        keep2.add(s2)
                if keep2 != dom2:
                    domains[rr][cc] = keep2
                    changed = True
    return changed


def domain_has_state_using(dom, d):
    for s in dom:
        if has_dir(s, d):
            return True
    return False


def domain_intersects(dom, allowed):
    for s in dom:
        if s in allowed:
            return True
    return False


def local_state_viable(domains, data, r, c, s):
    n = len(domains)
    clue = data[r][c]

    # Basic edge support.
    for d in DIRS:
        dr, dc = DRC[d]
        rr, cc = r + dr, c + dc
        if has_dir(s, d):
            if not in_bounds(n, rr, cc):
                return False
            ndom = domains[rr][cc]
            if not any(pair_supported(s, t, d) for t in ndom):
                return False

    # Clue-specific deductions.
    if clue == 'W':
        if s == SH:
            if not in_bounds(n, r, c - 1) or not in_bounds(n, r, c + 1):
                return False
            left_dom = domains[r][c - 1]
            right_dom = domains[r][c + 1]
            # At least one adjacent path vertex must turn.
            if not (domain_intersects(left_dom, TURN_WITH_EDGE[L]) or domain_intersects(right_dom, TURN_WITH_EDGE[R])):
                return False
        elif s == SV:
            if not in_bounds(n, r - 1, c) or not in_bounds(n, r + 1, c):
                return False
            up_dom = domains[r - 1][c]
            down_dom = domains[r + 1][c]
            if not (domain_intersects(up_dom, TURN_WITH_EDGE[U]) or domain_intersects(down_dom, TURN_WITH_EDGE[D])):
                return False
        else:
            return False

    elif clue == 'B':
        reqs = BLACK_NEIGHBOR_REQ.get(s)
        if reqs is None:
            return False
        for d, allowed in reqs.items():
            dr, dc = DRC[d]
            rr, cc = r + dr, c + dc
            if not in_bounds(n, rr, cc):
                return False
            ndom = domains[rr][cc]
            if not domain_intersects(ndom, allowed):
                return False

    return True


def prune_local_clue_logic(domains, data):
    n = len(domains)
    changed = False
    for r in range(n):
        for c in range(n):
            dom = domains[r][c]
            keep = {s for s in dom if local_state_viable(domains, data, r, c, s)}
            if keep != dom:
                domains[r][c] = keep
                changed = True
    return changed


def forced_edge_info(domains, r, c, d):
    use_any = False
    use_all = True
    for s in domains[r][c]:
        if has_dir(s, d):
            use_any = True
        else:
            use_all = False
    return use_any, use_all


def prune_degree_pressure(domains):
    # Human-like degree pressure:
    # if a vertex cannot be empty due to incident forced-used edges, or cannot have degree 2 due to too few possible edges.
    n = len(domains)
    changed = False
    for r in range(n):
        for c in range(n):
            forced_used = 0
            possible_used = 0
            for d, rr, cc in neighbors(n, r, c):
                any_use, all_use = forced_edge_info(domains, r, c, d)
                if any_use:
                    possible_used += 1
                if all_use:
                    forced_used += 1

            keep = set()
            for s in domains[r][c]:
                deg = popcount(s)
                if deg == 0:
                    if forced_used > 0:
                        continue
                else:
                    if forced_used > deg:
                        continue
                    # All non-empty states here are degree 2; ensure enough possible edges remain.
                    if possible_used < 2:
                        continue
                keep.add(s)
            if keep != domains[r][c]:
                domains[r][c] = keep
                changed = True
    return changed


def propagate(domains, data):
    while True:
        if any(len(domains[r][c]) == 0 for r in range(len(domains)) for c in range(len(domains))):
            return False
        changed = False
        changed |= boundary_filter(domains, data)
        if any(len(domains[r][c]) == 0 for r in range(len(domains)) for c in range(len(domains))):
            return False
        changed |= prune_edge_consistency(domains)
        if any(len(domains[r][c]) == 0 for r in range(len(domains)) for c in range(len(domains))):
            return False
        changed |= prune_local_clue_logic(domains, data)
        if any(len(domains[r][c]) == 0 for r in range(len(domains)) for c in range(len(domains))):
            return False
        changed |= prune_degree_pressure(domains)
        if any(len(domains[r][c]) == 0 for r in range(len(domains)) for c in range(len(domains))):
            return False
        if not changed:
            break
    if violates_partial_loops(domains):
        return False
    return True


def copy_domains(domains):
    return [[set(cell) for cell in row] for row in domains]


def assigned_state(domains, r, c):
    if len(domains[r][c]) == 1:
        return next(iter(domains[r][c]))
    return None


def build_assigned_graph(domains):
    n = len(domains)
    g = {}
    used_vertices = set()
    for r in range(n):
        for c in range(n):
            s = assigned_state(domains, r, c)
            if s is None or s == EMPTY:
                continue
            used_vertices.add((r, c))
            g.setdefault((r, c), set())
            for d in DIRS:
                if has_dir(s, d):
                    rr, cc = r + DRC[d][0], c + DRC[d][1]
                    if in_bounds(n, rr, cc):
                        s2 = assigned_state(domains, rr, cc)
                        if s2 is not None and has_dir(s2, OPP[d]):
                            g[(r, c)].add((rr, cc))
    return g, used_vertices


def violates_partial_loops(domains):
    # Detect a fully assigned closed cycle before all non-empty assigned vertices are accounted for.
    # This is conservative and effective enough for pruning.
    g, used_vertices = build_assigned_graph(domains)
    if not used_vertices:
        return False

    seen = set()
    components = []
    for v in used_vertices:
        if v in seen:
            continue
        stack = [v]
        comp = set()
        seen.add(v)
        while stack:
            x = stack.pop()
            comp.add(x)
            for y in g.get(x, ()):
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        components.append(comp)

    # If any component is already a perfect cycle and there are other assigned non-empty vertices elsewhere,
    # then the final answer cannot be a single loop.
    total_assigned_nonempty = len(used_vertices)
    for comp in components:
        if all(len(g.get(v, ())) == 2 for v in comp):
            if len(comp) < total_assigned_nonempty:
                return True

    return False


def all_assigned(domains):
    n = len(domains)
    for r in range(n):
        for c in range(n):
            if len(domains[r][c]) != 1:
                return False
    return True


def final_single_loop(domains):
    n = len(domains)
    g = {}
    used_vertices = set()

    for r in range(n):
        for c in range(n):
            s = assigned_state(domains, r, c)
            if s is None:
                return False
            deg = popcount(s)
            if deg not in (0, 2):
                return False
            if s != EMPTY:
                used_vertices.add((r, c))
                g.setdefault((r, c), set())
                for d in DIRS:
                    if has_dir(s, d):
                        rr, cc = r + DRC[d][0], c + DRC[d][1]
                        if not in_bounds(n, rr, cc):
                            return False
                        s2 = assigned_state(domains, rr, cc)
                        if s2 is None or not has_dir(s2, OPP[d]):
                            return False
                        g[(r, c)].add((rr, cc))

    if not used_vertices:
        return False
    if not all(len(g[v]) == 2 for v in used_vertices):
        return False

    start = next(iter(used_vertices))
    stack = [start]
    seen = {start}
    while stack:
        v = stack.pop()
        for u in g[v]:
            if u not in seen:
                seen.add(u)
                stack.append(u)
    return seen == used_vertices


def choose_branch_cell(domains, data):
    # Strong heuristic:
    # 1) smallest domain > 1
    # 2) prioritize clue cells
    # 3) higher interaction = more assigned/constrained neighbors
    n = len(domains)
    best = None
    best_key = None
    for r in range(n):
        for c in range(n):
            m = len(domains[r][c])
            if m <= 1:
                continue
            clue_priority = 0 if data[r][c] is not None else 1
            interaction = 0
            for _, rr, cc in neighbors(n, r, c):
                interaction -= len(domains[rr][cc])
            key = (m, clue_priority, interaction, r, c)
            if best_key is None or key < best_key:
                best_key = key
                best = (r, c)
    return best


def ordered_domain_values(domains, data, r, c):
    dom = list(domains[r][c])
    clue = data[r][c]
    if clue == 'W':
        # Prefer orientation with stronger immediate forced support.
        def score(s):
            if s == SH:
                left_turn = 1 if c - 1 >= 0 and domain_intersects(domains[r][c - 1], TURN_WITH_EDGE[L]) else 0
                right_turn = 1 if c + 1 < len(domains) and domain_intersects(domains[r][c + 1], TURN_WITH_EDGE[R]) else 0
                return -(left_turn + right_turn)
            if s == SV:
                up_turn = 1 if r - 1 >= 0 and domain_intersects(domains[r - 1][c], TURN_WITH_EDGE[U]) else 0
                down_turn = 1 if r + 1 < len(domains) and domain_intersects(domains[r + 1][c], TURN_WITH_EDGE[D]) else 0
                return -(up_turn + down_turn)
            return 999
        dom.sort(key=score)
    elif clue == 'B':
        # Prefer the turn with strongest forced straight support.
        def score(s):
            total = 0
            for d, allowed in BLACK_NEIGHBOR_REQ[s].items():
                rr, cc = r + DRC[d][0], c + DRC[d][1]
                total += sum(1 for t in domains[rr][cc] if t in allowed)
            return total
        dom.sort(key=score)
    else:
        # Prefer non-empty before empty to complete the loop structure earlier.
        dom.sort(key=lambda s: (s == EMPTY, s))
    return dom


def extract_loop(domains):
    n = len(domains)
    g = {}
    used_vertices = set()
    for r in range(n):
        for c in range(n):
            s = assigned_state(domains, r, c)
            if s and s != EMPTY:
                used_vertices.add((r, c))
                g.setdefault((r, c), [])
                for d in DIRS:
                    if has_dir(s, d):
                        rr, cc = r + DRC[d][0], c + DRC[d][1]
                        if in_bounds(n, rr, cc) and has_dir(assigned_state(domains, rr, cc), OPP[d]):
                            g[(r, c)].append((rr, cc))
    if not used_vertices:
        return None

    start = min(used_vertices)
    path = [start]
    prev = None
    cur = start
    while True:
        nbrs = g[cur]
        nxt = nbrs[0] if nbrs[0] != prev else nbrs[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
        if len(path) > len(used_vertices) + 2:
            return None
    return path


def search(domains, data):
    if not propagate(domains, data):
        return None
    if all_assigned(domains):
        if final_single_loop(domains):
            return domains
        return None

    cell = choose_branch_cell(domains, data)
    if cell is None:
        return None
    r, c = cell

    for s in ordered_domain_values(domains, data, r, c):
        new_domains = copy_domains(domains)
        new_domains[r][c] = {s}
        result = search(new_domains, data)
        if result is not None:
            return result
    return None


def solve(observation):
    data = observation['data']
    domains = initial_domains(data)
    result = search(domains, data)
    if result is None:
        return "No Solution"
    loop = extract_loop(result)
    if loop is None:
        return "No Solution"
    return str(loop)


if __name__ == "__main__":
    print(solve(OBSERVATION))

