from collections import defaultdict, deque
from functools import lru_cache

B, W, U = 1, 0, -1

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx = {(r, c): r * m + c for r, c in cells}

    regions = defaultdict(list)
    clue_by_region = {}
    for r in range(n):
        for c in range(m):
            rg = region[r][c]
            regions[rg].append((r, c))
            if data[r][c] is not None:
                clue_by_region[rg] = data[r][c]

    orth = {}
    for r, c in cells:
        nb = []
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            rr, cc = r + dr, c + dc
            if 0 <= rr < n and 0 <= cc < m:
                nb.append((rr, cc))
        orth[(r, c)] = nb

    rows = [[(r, c) for c in range(m)] for r in range(n)]
    cols = [[(r, c) for r in range(n)] for c in range(m)]

    clue_patterns = {}
    for rg, target in clue_by_region.items():
        rcells = regions[rg]
        k = len(rcells)
        pos = {rcells[i]: i for i in range(k)}
        masks = []
        for mask in range(1 << k):
            if mask.bit_count() != target:
                continue
            ok = True
            for i, (r, c) in enumerate(rcells):
                if not (mask >> i) & 1:
                    continue
                for rr, cc in orth[(r, c)]:
                    j = pos.get((rr, cc))
                    if j is not None and j > i and ((mask >> j) & 1):
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                masks.append(mask)
        clue_patterns[rg] = masks

    def line_support(line, state):
        regs = [region[r][c] for r, c in line]
        fixed = [state[idx[(r, c)]] for r, c in line]
        L = len(line)

        @lru_cache(None)
        def dfs(i, prev_black, active, cnt, last_rg):
            if i == L:
                return True
            s = fixed[i]
            rg = regs[i]

            # choose white
            if s != B:
                if not active:
                    if dfs(i + 1, 0, 1, 1, rg):
                        return True
                else:
                    if rg == last_rg:
                        if dfs(i + 1, 0, 1, cnt, last_rg):
                            return True
                    elif cnt == 1:
                        if dfs(i + 1, 0, 1, 2, rg):
                            return True

            # choose black
            if s != W and not prev_black:
                if dfs(i + 1, 1, 0, 0, -1):
                    return True
            return False

        if not dfs(0, 0, 0, 0, -1):
            return None

        canB = [False] * L
        canW = [False] * L

        @lru_cache(None)
        def suffix(i, prev_black, active, cnt, last_rg):
            return dfs(i, prev_black, active, cnt, last_rg)

        def mark(i, prev_black, active, cnt, last_rg):
            if i == L:
                return
            s = fixed[i]
            rg = regs[i]

            if s != B:
                if not active:
                    ns = (i + 1, 0, 1, 1, rg)
                    if suffix(*ns):
                        canW[i] = True
                        mark(*ns)
                else:
                    if rg == last_rg:
                        ns = (i + 1, 0, 1, cnt, last_rg)
                        if suffix(*ns):
                            canW[i] = True
                            mark(*ns)
                    elif cnt == 1:
                        ns = (i + 1, 0, 1, 2, rg)
                        if suffix(*ns):
                            canW[i] = True
                            mark(*ns)

            if s != W and not prev_black:
                ns = (i + 1, 1, 0, 0, -1)
                if suffix(*ns):
                    canB[i] = True
                    mark(*ns)

        mark(0, 0, 0, 0, -1)
        return canB, canW

    def clue_region_support(rg, state):
        rcells = regions[rg]
        pats = clue_patterns[rg]
        valid = []
        for mask in pats:
            ok = True
            for i, cell in enumerate(rcells):
                s = state[idx[cell]]
                black = (mask >> i) & 1
                if s == B and not black:
                    ok = False
                    break
                if s == W and black:
                    ok = False
                    break
                if black:
                    for nb in orth[cell]:
                        if region[nb[0]][nb[1]] != rg and state[idx[nb]] == B:
                            ok = False
                            break
                if not ok:
                    break
            if ok:
                valid.append(mask)
        if not valid:
            return None
        canB = [False] * len(rcells)
        canW = [False] * len(rcells)
        for mask in valid:
            for i in range(len(rcells)):
                if (mask >> i) & 1:
                    canB[i] = True
                else:
                    canW[i] = True
        return rcells, canB, canW

    def white_connectivity_possible(state):
        allowed = [i for i, s in enumerate(state) if s != B]
        whites = [i for i, s in enumerate(state) if s == W]
        if not whites:
            return True
        start = whites[0]
        seen = {start}
        q = deque([start])
        while q:
            v = q.popleft()
            r, c = divmod(v, m)
            for rr, cc in orth[(r, c)]:
                j = idx[(rr, cc)]
                if state[j] != B and j not in seen:
                    seen.add(j)
                    q.append(j)
        return all(w in seen for w in whites)

    def final_check(state):
        for i, s in enumerate(state):
            if s == B:
                r, c = divmod(i, m)
                for rr, cc in orth[(r, c)]:
                    if state[idx[(rr, cc)]] == B:
                        return False

        for rg, target in clue_by_region.items():
            cnt = sum(state[idx[cell]] == B for cell in regions[rg])
            if cnt != target:
                return False

        for line in rows + cols:
            seen_regions = set()
            seg_regions = set()
            prev_black = True
            for cell in line:
                s = state[idx[cell]]
                if s == B:
                    prev_black = True
                    seg_regions = set()
                else:
                    rg = region[cell[0]][cell[1]]
                    if prev_black:
                        seg_regions = {rg}
                    else:
                        seg_regions.add(rg)
                    if len(seg_regions) > 2:
                        return False
                    prev_black = False
                    seen_regions.add(rg)

        whites = [i for i, s in enumerate(state) if s == W]
        if whites:
            start = whites[0]
            seen = {start}
            q = deque([start])
            while q:
                v = q.popleft()
                r, c = divmod(v, m)
                for rr, cc in orth[(r, c)]:
                    j = idx[(rr, cc)]
                    if state[j] == W and j not in seen:
                        seen.add(j)
                        q.append(j)
            if len(seen) != len(whites):
                return False
        return True

    def assign(state, p, val, queue):
        if state[p] == val:
            return True
        if state[p] != U:
            return False
        state[p] = val
        queue.append(p)
        return True

    def propagate(state):
        queue = deque(i for i, s in enumerate(state) if s != U)

        # initial direct clue count propagation loop needs repeated passes
        changed = True
        while changed:
            changed = False

            # black adjacency immediate
            while queue:
                p = queue.popleft()
                if state[p] != B:
                    continue
                r, c = divmod(p, m)
                for rr, cc in orth[(r, c)]:
                    q = idx[(rr, cc)]
                    if state[q] == B:
                        return None
                    if state[q] == U:
                        state[q] = W
                        queue.append(q)
                        changed = True

            # clue count min/max
            for rg, target in clue_by_region.items():
                rcells = regions[rg]
                blacks = [cell for cell in rcells if state[idx[cell]] == B]
                und = [cell for cell in rcells if state[idx[cell]] == U]
                if len(blacks) > target:
                    return None
                if len(blacks) + len(und) < target:
                    return None
                if len(blacks) == target:
                    for cell in und:
                        p = idx[cell]
                        state[p] = W
                        queue.append(p)
                        changed = True
                elif len(blacks) + len(und) == target:
                    for cell in und:
                        p = idx[cell]
                        state[p] = B
                        queue.append(p)
                        changed = True

            # line propagation
            for line in rows + cols:
                sup = line_support(line, state)
                if sup is None:
                    return None
                canB, canW = sup
                for i, cell in enumerate(line):
                    p = idx[cell]
                    if state[p] == U:
                        if not canB[i] and not canW[i]:
                            return None
                        if canB[i] and not canW[i]:
                            state[p] = B
                            queue.append(p)
                            changed = True
                        elif canW[i] and not canB[i]:
                            state[p] = W
                            queue.append(p)
                            changed = True

            # clue-region pattern propagation
            for rg in clue_by_region:
                sup = clue_region_support(rg, state)
                if sup is None:
                    return None
                rcells, canB, canW = sup
                for i, cell in enumerate(rcells):
                    p = idx[cell]
                    if state[p] == U:
                        if not canB[i] and not canW[i]:
                            return None
                        if canB[i] and not canW[i]:
                            state[p] = B
                            queue.append(p)
                            changed = True
                        elif canW[i] and not canB[i]:
                            state[p] = W
                            queue.append(p)
                            changed = True

            if not white_connectivity_possible(state):
                return None

        return state

    def choose_var(state):
        best = None
        best_score = None
        for p, s in enumerate(state):
            if s != U:
                continue
            r, c = divmod(p, m)
            score = 0
            rg = region[r][c]
            if rg in clue_by_region:
                score += 10
            score += sum(state[idx[nb]] != U for nb in orth[(r, c)])
            score += len(regions[rg]) <= 4
            if best is None or score > best_score:
                best = p
                best_score = score
        return best

    def search(state):
        state = propagate(state[:])
        if state is None:
            return None
        if all(s != U for s in state):
            return state if final_check(state) else None

        p = choose_var(state)
        r, c = divmod(p, m)

        # branch ordering: prefer black if clue pressure suggests it
        order = [B, W]
        rg = region[r][c]
        if rg in clue_by_region:
            target = clue_by_region[rg]
            cur_b = sum(state[idx[cell]] == B for cell in regions[rg])
            cur_u = sum(state[idx[cell]] == U for cell in regions[rg])
            if target == cur_b:
                order = [W, B]
            elif target - cur_b == cur_u:
                order = [B, W]

        for val in order:
            nxt = state[:]
            nxt[p] = val
            ans = search(nxt)
            if ans is not None:
                return ans
        return None

    init = [U] * (n * m)
    ans = search(init)
    if ans is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            row.append('B' if ans[idx[(r, c)]] == B else None)
        out.append(row)
    return repr(out)

