    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 0, 0, 1, 1, 1, 1], [0, 2, 2, 0, 3, 3, 1, 1], [0, 4, 4, 0, 3, 1, 1, 5], [4, 4, 4, 6, 3, 3, 1, 5], [4, 4, 4, 6, 7, 7, 1, 5], [4, 8, 8, 7, 7, 7, 9, 10], [4, 11, 12, 12, 9, 9, 9, 10], [11, 11, 11, 12, 13, 13, 13, 10]]}

from collections import defaultdict

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0

    cells = [(r, c) for r in range(n) for c in range(m)]
    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[grid[r][c]].append((r, c))
    region_ids = sorted(regions)

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def inside(r, c):
        return 0 <= r < n and 0 <= c < m

    neighbors = {}
    for r, c in cells:
        neighbors[(r, c)] = [(r + dr, c + dc) for dr, dc in dirs if inside(r + dr, c + dc)]

    # Candidate domino placements
    placements = []
    placement_by_cell = defaultdict(list)
    placement_regions = []
    placement_cells = []

    # Orthogonal non-touching: dominoes cannot overlap and cannot have any orthogonally adjacent cells
    # across distinct dominoes.
    for r in range(n):
        for c in range(m):
            for dr, dc in [(1, 0), (0, 1)]:
                r2, c2 = r + dr, c + dc
                if not inside(r2, c2):
                    continue
                a = (r, c)
                b = (r2, c2)
                idx = len(placements)
                dom = (a, b)
                placements.append(dom)
                placement_cells.append((a, b))
                contrib = defaultdict(int)
                contrib[grid[a[0]][a[1]]] += 1
                contrib[grid[b[0]][b[1]]] += 1
                placement_regions.append(dict(contrib))
                placement_by_cell[a].append(idx)
                placement_by_cell[b].append(idx)

    P = len(placements)

    # Conflict graph
    conflicts = [set() for _ in range(P)]
    cell_set_of = []
    forbidden_zone = []
    for i, (a, b) in enumerate(placements):
        s = {a, b}
        cell_set_of.append(s)
        z = set(s)
        for cell in s:
            z.update(neighbors[cell])
        forbidden_zone.append(z)

    for i in range(P):
        zi = forbidden_zone[i]
        si = cell_set_of[i]
        for j in range(i + 1, P):
            sj = cell_set_of[j]
            # overlap or orthogonal adjacency between domino cells
            bad = False
            if si & sj:
                bad = True
            else:
                for cell in sj:
                    if cell in zi:
                        bad = True
                        break
            if bad:
                conflicts[i].add(j)
                conflicts[j].add(i)

    all_placements = set(range(P))
    region_quota = {rid: 2 for rid in region_ids}

    # Useful maps for propagation
    region_to_placements = defaultdict(set)
    for p in range(P):
        for rid in placement_regions[p]:
            region_to_placements[rid].add(p)

    def region_remaining_cells(active):
        # Available cells in each region that can still be shaded by some active placement
        avail = defaultdict(set)
        for p in active:
            for cell in placement_cells[p]:
                avail[grid[cell[0]][cell[1]]].add(cell)
        return avail

    def propagate(active, chosen, rem):
        active = set(active)
        chosen = set(chosen)
        rem = dict(rem)

        changed = True
        while changed:
            changed = False

            # Remove placements that already exceed any remaining region quota
            to_remove = set()
            for p in active:
                for rid, cnt in placement_regions[p].items():
                    if cnt > rem[rid]:
                        to_remove.add(p)
                        break
            if to_remove:
                active -= to_remove
                changed = True

            # If a region is full, remove any placement touching it
            to_remove = set()
            for rid in region_ids:
                if rem[rid] == 0:
                    to_remove |= region_to_placements[rid] & active
            if to_remove:
                active -= to_remove
                changed = True

            # Basic capacity checks
            avail_cells = region_remaining_cells(active)
            for rid in region_ids:
                if rem[rid] < 0:
                    return None
                if len(avail_cells[rid]) < rem[rid]:
                    return None
                # Also total contribution capacity
                cap = 0
                for p in active:
                    cap += placement_regions[p].get(rid, 0)
                if cap < rem[rid]:
                    return None

            # Forced single-placement for isolated available cell
            # If a region still needs k cells and exactly k cells remain available, those cells must be shaded.
            # Any placement covering one of those forced cells becomes mandatory if it's the only active one for that cell.
            forced = set()
            for rid in region_ids:
                if rem[rid] == 0:
                    continue
                cells_av = avail_cells[rid]
                if len(cells_av) == rem[rid]:
                    for cell in cells_av:
                        plist = [p for p in placement_by_cell[cell] if p in active]
                        if not plist:
                            return None
                        if len(plist) == 1:
                            forced.add(plist[0])

            # If a region needs 2 and only one active placement can contribute 2 to it, force it if
            # no pair of 1-contribution placements exists.
            for rid in region_ids:
                if rem[rid] == 2:
                    twos = [p for p in active if placement_regions[p].get(rid, 0) == 2]
                    ones = [p for p in active if placement_regions[p].get(rid, 0) == 1]
                    pair_possible = False
                    if len(ones) >= 2:
                        for i in range(len(ones)):
                            p = ones[i]
                            for j in range(i + 1, len(ones)):
                                q = ones[j]
                                if q not in conflicts[p]:
                                    pair_possible = True
                                    break
                            if pair_possible:
                                break
                    if not pair_possible:
                        if len(twos) == 1:
                            forced.add(twos[0])
                        elif len(twos) == 0:
                            return None

            # Apply forced placements
            if forced:
                for p in list(forced):
                    if p not in active:
                        continue
                    # choose p
                    chosen.add(p)
                    active.remove(p)
                    for rid, cnt in placement_regions[p].items():
                        rem[rid] -= cnt
                        if rem[rid] < 0:
                            return None
                    # remove conflicts
                    active -= conflicts[p]
                changed = True

        return active, chosen, rem

    def is_complete(rem):
        return all(v == 0 for v in rem.values())

    def score_region(active, rem):
        # Human-like branching: focus on the region with least flexibility
        best = None
        for rid in region_ids:
            if rem[rid] == 0:
                continue
            rel = [p for p in active if placement_regions[p].get(rid, 0)]
            cells_av = set()
            for p in rel:
                for cell in placement_cells[p]:
                    if grid[cell[0]][cell[1]] == rid:
                        cells_av.add(cell)
            key = (len(cells_av), len(rel), rem[rid], rid)
            if best is None or key < best:
                best = key
        return best[-1] if best else None

    def candidate_branches_for_region(active, rid, rem):
        # Produce a compact set of meaningful branches for a constrained region.
        rel = [p for p in active if placement_regions[p].get(rid, 0)]
        if rem[rid] == 1:
            # Must use a crossing domino contributing exactly 1
            return [[p] for p in rel if placement_regions[p].get(rid, 0) == 1]
        elif rem[rid] == 2:
            branches = []
            twos = [p for p in rel if placement_regions[p].get(rid, 0) == 2]
            branches.extend([[p] for p in twos])
            ones = [p for p in rel if placement_regions[p].get(rid, 0) == 1]
            L = len(ones)
            for i in range(L):
                p = ones[i]
                for j in range(i + 1, L):
                    q = ones[j]
                    if q not in conflicts[p]:
                        branches.append([p, q])
            # Prefer fewer placements and stronger contributions
            branches.sort(key=lambda b: (len(b), sum(len(conflicts[p]) for p in b)))
            return branches
        return []

    def apply_branch(active, chosen, rem, branch):
        active = set(active)
        chosen = set(chosen)
        rem = dict(rem)
        for p in branch:
            if p not in active:
                if p in chosen:
                    continue
                return None
            chosen.add(p)
            active.remove(p)
            for rid, cnt in placement_regions[p].items():
                rem[rid] -= cnt
                if rem[rid] < 0:
                    return None
            active -= conflicts[p]
        return active, chosen, rem

    def search(active, chosen, rem):
        state = propagate(active, chosen, rem)
        if state is None:
            return None
        active, chosen, rem = state

        if is_complete(rem):
            return chosen

        rid = score_region(active, rem)
        if rid is None:
            return None

        branches = candidate_branches_for_region(active, rid, rem)
        if not branches:
            return None

        # Remove duplicate branch sets
        seen = set()
        uniq = []
        for b in branches:
            t = tuple(sorted(b))
            if t not in seen:
                seen.add(t)
                uniq.append(b)

        for branch in uniq:
            nxt = apply_branch(active, chosen, rem, branch)
            if nxt is None:
                continue
            result = search(*nxt)
            if result is not None:
                return result
        return None

    result = search(all_placements, set(), region_quota)
    if result is None:
        return "No Solution"

    ans = [[None for _ in range(m)] for _ in range(n)]
    for p in result:
        for r, c in placement_cells[p]:
            ans[r][c] = 'S'
    return str(ans)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'row_sum': [19, 19, 8, 11, 10, 7, 22, 3], 'col_sum': [11, 19, 7, 10, 24, 14, 7, 4]}

from functools import lru_cache

# Weighted binary-grid solver:
# - Row i has weight (i + 1)
# - Column j has weight (j + 1)
# - Black cells contribute column-weights to row sums and row-weights to column sums


def solve(observation):
    row_sum = observation["row_sum"]
    col_sum = observation["col_sum"]
    R = len(row_sum)
    C = len(col_sum)

    row_weights = list(range(1, R + 1))
    col_weights = list(range(1, C + 1))

    total_row_target = sum(row_sum)
    total_col_target = sum(col_sum)
    if total_row_target != total_col_target:
        return "No Solution"

    row_masks_by_target = build_masks_by_target(col_weights)
    col_masks_by_target = build_masks_by_target(row_weights)

    row_domains = []
    for t in row_sum:
        masks = row_masks_by_target.get(t, [])
        if not masks:
            return "No Solution"
        row_domains.append(masks[:])

    col_domains = []
    for t in col_sum:
        masks = col_masks_by_target.get(t, [])
        if not masks:
            return "No Solution"
        col_domains.append(masks[:])

    solved = search(row_domains, col_domains, R, C)
    if solved is None:
        return "No Solution"

    row_domains, col_domains = solved
    grid = domains_to_grid(row_domains, R, C)
    return repr(grid)


def build_masks_by_target(weights):
    n = len(weights)
    suffix_max = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        suffix_max[i] = suffix_max[i + 1] + weights[i]

    out = {}

    def dfs(idx, total, mask):
        if idx == n:
            out.setdefault(total, []).append(mask)
            return
        if total > suffix_max[0]:
            return

        # Skip current
        if total + suffix_max[idx + 1] >= total:
            dfs(idx + 1, total, mask)

        # Take current
        dfs(idx + 1, total + weights[idx], mask | (1 << idx))

    dfs(0, 0, 0)
    return out


def domain_union_and_intersection(domain):
    it = iter(domain)
    first = next(it)
    u = first
    inter = first
    for m in it:
        u |= m
        inter &= m
    return u, inter


def filter_domain_by_assignments(domain, assignments):
    # assignments: dict index -> 0/1
    filtered = []
    for m in domain:
        ok = True
        for idx, val in assignments.items():
            bit = (m >> idx) & 1
            if bit != val:
                ok = False
                break
        if ok:
            filtered.append(m)
    return filtered


def propagate(row_domains, col_domains, R, C):
    # Repeatedly apply line-domain filtering and cell-level deduction.
    while True:
        changed = False

        row_ui = [domain_union_and_intersection(d) for d in row_domains]
        col_ui = [domain_union_and_intersection(d) for d in col_domains]

        # Cell feasibility matrix induced by row/col domains.
        row_assignments = [dict() for _ in range(R)]
        col_assignments = [dict() for _ in range(C)]

        for i in range(R):
            row_union, row_inter = row_ui[i]
            for j in range(C):
                col_union, col_inter = col_ui[j]

                row_can_black = (row_union >> j) & 1
                row_can_white = ((~row_inter) >> j) & 1
                col_can_black = (col_union >> i) & 1
                col_can_white = ((~col_inter) >> i) & 1

                can_black = row_can_black and col_can_black
                can_white = row_can_white and col_can_white

                if not can_black and not can_white:
                    return None

                if can_black and not can_white:
                    row_assignments[i][j] = 1
                    col_assignments[j][i] = 1
                elif can_white and not can_black:
                    row_assignments[i][j] = 0
                    col_assignments[j][i] = 0

        # Filter row domains.
        for i in range(R):
            if row_assignments[i]:
                new_domain = filter_domain_by_assignments(row_domains[i], row_assignments[i])
                if not new_domain:
                    return None
                if len(new_domain) != len(row_domains[i]):
                    row_domains[i] = new_domain
                    changed = True

        # Filter column domains.
        for j in range(C):
            if col_assignments[j]:
                new_domain = filter_domain_by_assignments(col_domains[j], col_assignments[j])
                if not new_domain:
                    return None
                if len(new_domain) != len(col_domains[j]):
                    col_domains[j] = new_domain
                    changed = True

        # Additional target-consistency check via forced black counts is already embedded by domains.
        # Early solved check.
        if all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains):
            if fully_consistent(row_domains, col_domains, R, C):
                return row_domains, col_domains
            return None

        if not changed:
            # Stable fixpoint: still must be globally consistent with current domains.
            if not arc_consistent_snapshot(row_domains, col_domains, R, C):
                return None
            return row_domains, col_domains


def arc_consistent_snapshot(row_domains, col_domains, R, C):
    row_ui = [domain_union_and_intersection(d) for d in row_domains]
    col_ui = [domain_union_and_intersection(d) for d in col_domains]
    for i in range(R):
        row_union, row_inter = row_ui[i]
        for j in range(C):
            col_union, col_inter = col_ui[j]
            row_can_black = (row_union >> j) & 1
            row_can_white = ((~row_inter) >> j) & 1
            col_can_black = (col_union >> i) & 1
            col_can_white = ((~col_inter) >> i) & 1
            if not (row_can_black and col_can_black) and not (row_can_white and col_can_white):
                return False
    return True


def fully_consistent(row_domains, col_domains, R, C):
    # Verify the unique row masks and column masks describe the same grid.
    row_masks = [d[0] for d in row_domains]
    col_masks = [d[0] for d in col_domains]
    for i in range(R):
        rm = row_masks[i]
        for j in range(C):
            a = (rm >> j) & 1
            b = (col_masks[j] >> i) & 1
            if a != b:
                return False
    return True


def choose_branch_line(row_domains, col_domains):
    best = None
    # Prefer smallest non-singleton domain; tie-break by lower branching factor.
    for i, d in enumerate(row_domains):
        if 1 < len(d) and (best is None or len(d) < best[2]):
            best = ("row", i, len(d))
    for j, d in enumerate(col_domains):
        if 1 < len(d) and (best is None or len(d) < best[2]):
            best = ("col", j, len(d))
    return best


def search(row_domains, col_domains, R, C):
    propagated = propagate(
        [d[:] for d in row_domains],
        [d[:] for d in col_domains],
        R,
        C,
    )
    if propagated is None:
        return None

    row_domains, col_domains = propagated

    if all(len(d) == 1 for d in row_domains) and all(len(d) == 1 for d in col_domains):
        return row_domains, col_domains

    branch = choose_branch_line(row_domains, col_domains)
    if branch is None:
        return None

    kind, idx, _ = branch

    if kind == "row":
        # Order masks to try the most constrained-looking first:
        # masks with rarer column bits according to current column domains.
        ordered = order_row_masks(row_domains[idx], col_domains, R)
        for m in ordered:
            new_row = [d[:] for d in row_domains]
            new_col = [d[:] for d in col_domains]
            new_row[idx] = [m]
            result = search(new_row, new_col, R, C)
            if result is not None:
                return result
    else:
        ordered = order_col_masks(col_domains[idx], row_domains, C)
        for m in ordered:
            new_row = [d[:] for d in row_domains]
            new_col = [d[:] for d in col_domains]
            new_col[idx] = [m]
            result = search(new_row, new_col, R, C)
            if result is not None:
                return result

    return None


def order_row_masks(masks, col_domains, R):
    # Score masks by compatibility rarity with column domains.
    col_unions = [domain_union_and_intersection(d)[0] for d in col_domains]

    def score(mask):
        s = 0
        for j, cu in enumerate(col_unions):
            bit = (mask >> j) & 1
            # Prefer values already more restricted in the opposite line.
            if bit:
                s += bin(cu).count("1")
            else:
                s += R - bin(cu).count("1")
        return s

    return sorted(masks, key=score)


def order_col_masks(masks, row_domains, C):
    row_unions = [domain_union_and_intersection(d)[0] for d in row_domains]

    def score(mask):
        s = 0
        for i, ru in enumerate(row_unions):
            bit = (mask >> i) & 1
            if bit:
                s += bin(ru).count("1")
            else:
                s += C - bin(ru).count("1")
        return s

    return sorted(masks, key=score)


def domains_to_grid(row_domains, R, C):
    grid = []
    for i in range(R):
        mask = row_domains[i][0]
        row = []
        for j in range(C):
            row.append('B' if ((mask >> j) & 1) else None)
        grid.append(row)
    return grid


