# General Futoshiki solver using human-like deduction first, then tightly-pruned search.
# It supports arbitrary N x N grids, givens, and inequality constraints.

from collections import deque


def solve(observation):
    data = observation["data"]
    n = len(data)
    full = (1 << n) - 1

    def bit(v):
        return 1 << (v - 1)

    def mask_to_values(mask):
        vals = []
        x = mask
        while x:
            b = x & -x
            vals.append(b.bit_length())
            x -= b
        return vals

    def popcount(x):
        return x.bit_count()

    def min_val(mask):
        return (mask & -mask).bit_length()

    def max_val(mask):
        return mask.bit_length()

    # Parse inequalities into oriented constraints:
    # relation a < b means value(a) < value(b)
    less_than = []

    for k, sym in observation.get("horizontal", {}).items():
        row, c05 = k.strip("()").split(",")
        r = int(float(row))
        c = int(float(c05 - "0")) if False else None  # never executed; keeps parser simple
        c_left = int(float(c05) - 0.5)
        a = (r, c_left)
        b = (r, c_left + 1)
        if sym == "<":
            less_than.append((a, b))
        elif sym == ">":
            less_than.append((b, a))

    for k, sym in observation.get("vertical", {}).items():
        r05, col = k.strip("()").split(",")
        r_top = int(float(r05) - 0.5)
        c = int(float(col))
        a = (r_top, c)
        b = (r_top + 1, c)
        # By standard puzzle convention in these image-extracted tasks:
        # 'v' means top cell < bottom cell, '^' means top cell > bottom cell.
        if sym == "v":
            less_than.append((a, b))
        elif sym == "^":
            less_than.append((b, a))

    # Precompute adjacency for inequality propagation.
    lt_out = [[[] for _ in range(n)] for _ in range(n)]  # cell -> cells that must be greater
    lt_in = [[[] for _ in range(n)] for _ in range(n)]   # cell -> cells that must be smaller
    for (r1, c1), (r2, c2) in less_than:
        lt_out[r1][c1].append((r2, c2))
        lt_in[r2][c2].append((r1, c1))

    # Domains as bitmasks.
    domains = [[full for _ in range(n)] for _ in range(n)]
    row_used = [0] * n
    col_used = [0] * n

    # Apply givens.
    for r in range(n):
        for c in range(n):
            if data[r][c] is not None:
                v = data[r][c]
                if not (1 <= v <= n):
                    return "No Solution"
                domains[r][c] = bit(v)

    # Queue-based propagation.
    queue = deque((r, c) for r in range(n) for c in range(n))

    def assign(state_domains, state_row_used, state_col_used, r, c, vmask, q):
        cur = state_domains[r][c]
        if cur == vmask:
            return True
        if not (cur & vmask):
            return False
        state_domains[r][c] = vmask
        q.append((r, c))
        return True

    def remove_values(state_domains, r, c, rem_mask, q):
        cur = state_domains[r][c]
        new = cur & ~rem_mask
        if new == cur:
            return True
        if new == 0:
            return False
        state_domains[r][c] = new
        q.append((r, c))
        return True

    def enforce_ineq_pair(state_domains, a, b, q):
        ar, ac = a
        br, bc = b
        da = state_domains[ar][ac]
        db = state_domains[br][bc]

        # a < b
        # Remove from a any values >= max(db)
        # Remove from b any values <= min(da)
        max_b = max_val(db)
        min_a = min_val(da)

        rem_a = 0
        if max_b < n:
            rem_a = ((full >> max_b) << max_b)  # values > max_b
        rem_a |= bit(max_b) if max_b >= 1 else 0  # values == max_b also invalid for a < b

        rem_b = (1 << min_a) - 1  # values <= min_a

        # rem_a formula above removes >= max_b; make sure exact.
        # Since values are 1-based mapped to bits 0..n-1:
        # bits for values >= max_b are positions max_b-1 .. n-1 => full ^ ((1<<(max_b-1))-1)
        rem_a = full ^ ((1 << (max_b - 1)) - 1) if max_b >= 1 else full

        if not remove_values(state_domains, ar, ac, rem_a, q):
            return False
        if not remove_values(state_domains, br, bc, rem_b, q):
            return False
        return True

    def hidden_singles(state_domains, q):
        # Row hidden singles
        for r in range(n):
            count_pos = [0] * (n + 1)
            last_pos = [None] * (n + 1)
            for c in range(n):
                mask = state_domains[r][c]
                x = mask
                while x:
                    b = x & -x
                    v = b.bit_length()
                    count_pos[v] += 1
                    last_pos[v] = (r, c)
                    x -= b
            for v in range(1, n + 1):
                if count_pos[v] == 0:
                    return False
                if count_pos[v] == 1:
                    rr, cc = last_pos[v]
                    if not assign(state_domains, None, None, rr, cc, bit(v), q):
                        return False

        # Column hidden singles
        for c in range(n):
            count_pos = [0] * (n + 1)
            last_pos = [None] * (n + 1)
            for r in range(n):
                mask = state_domains[r][c]
                x = mask
                while x:
                    b = x & -x
                    v = b.bit_length()
                    count_pos[v] += 1
                    last_pos[v] = (r, c)
                    x -= b
            for v in range(1, n + 1):
                if count_pos[v] == 0:
                    return False
                if count_pos[v] == 1:
                    rr, cc = last_pos[v]
                    if not assign(state_domains, None, None, rr, cc, bit(v), q):
                        return False
        return True

    def naked_subsets(state_domains, q):
        # Small but powerful human-like rule for rows/cols.
        # If k cells in a unit share a union of exactly k values, remove those values elsewhere.
        # Implement for subset sizes 2..4.
        max_k = min(4, n - 1)

        def process_unit(cells):
            buckets = {}
            for r, c in cells:
                m = state_domains[r][c]
                pc = popcount(m)
                if 2 <= pc <= max_k:
                    buckets.setdefault(m, []).append((r, c))
            for m, poss in buckets.items():
                k = popcount(m)
                if len(poss) == k:
                    for r, c in cells:
                        if (r, c) not in poss:
                            if not remove_values(state_domains, r, c, m, q):
                                return False
            return True

        for r in range(n):
            if not process_unit([(r, c) for c in range(n)]):
                return False
        for c in range(n):
            if not process_unit([(r, c) for r in range(n)]):
                return False
        return True

    def propagate(state_domains):
        q = deque((r, c) for r in range(n) for c in range(n))

        while True:
            changed_in_round = False
            while q:
                r, c = q.popleft()
                mask = state_domains[r][c]
                if mask == 0:
                    return None

                # Latin rule: fixed values eliminate from peers.
                if mask & (mask - 1) == 0:
                    vmask = mask
                    for cc in range(n):
                        if cc != c:
                            if state_domains[r][cc] & vmask:
                                if not remove_values(state_domains, r, cc, vmask, q):
                                    return None
                    for rr in range(n):
                        if rr != r:
                            if state_domains[rr][c] & vmask:
                                if not remove_values(state_domains, rr, c, vmask, q):
                                    return None

                # If all other values used in row/col, force remainder by direct support checks.
                row_forbidden = 0
                for cc in range(n):
                    if cc != c and state_domains[r][cc] & (state_domains[r][cc] - 1) == 0:
                        row_forbidden |= state_domains[r][cc]
                col_forbidden = 0
                for rr in range(n):
                    if rr != r and state_domains[rr][c] & (state_domains[rr][c] - 1) == 0:
                        col_forbidden |= state_domains[rr][c]
                allowed = mask & ~row_forbidden & ~col_forbidden
                if allowed != mask:
                    if allowed == 0:
                        return None
                    state_domains[r][c] = allowed
                    mask = allowed
                    q.append((r, c))

                # Inequalities.
                for nb in lt_out[r][c]:
                    if not enforce_ineq_pair(state_domains, (r, c), nb, q):
                        return None
                for nb in lt_in[r][c]:
                    if not enforce_ineq_pair(state_domains, nb, (r, c), q):
                        return None

            # Global row/col uniqueness deductions.
            before_sig = tuple(tuple(state_domains[r][c] for c in range(n)) for r in range(n))
            if not hidden_singles(state_domains, q):
                return None
            if not naked_subsets(state_domains, q):
                return None
            after_sig = tuple(tuple(state_domains[r][c] for c in range(n)) for r in range(n))
            if before_sig == after_sig and not q:
                break
            changed_in_round = True

            if not changed_in_round and not q:
                break

        # Final contradiction checks.
        for r in range(n):
            seen_fixed = 0
            union = 0
            for c in range(n):
                m = state_domains[r][c]
                union |= m
                if m & (m - 1) == 0:
                    if seen_fixed & m:
                        return None
                    seen_fixed |= m
            if union != full:
                return None

        for c in range(n):
            seen_fixed = 0
            union = 0
            for r in range(n):
                m = state_domains[r][c]
                union |= m
                if m & (m - 1) == 0:
                    if seen_fixed & m:
                        return None
                    seen_fixed |= m
            if union != full:
                return None

        return state_domains

    def is_solved(state_domains):
        for r in range(n):
            for c in range(n):
                if state_domains[r][c] & (state_domains[r][c] - 1):
                    return False
        return True

    def score_cell(state_domains, r, c):
        # MRV + degree on row/col/ineq.
        m = state_domains[r][c]
        pc = popcount(m)
        deg = 0
        for cc in range(n):
            if cc != c and state_domains[r][cc] & (state_domains[r][cc] - 1):
                deg += 1
        for rr in range(n):
            if rr != r and state_domains[rr][c] & (state_domains[rr][c] - 1):
                deg += 1
        deg += len(lt_out[r][c]) + len(lt_in[r][c])
        return (pc, -deg)

    def order_values(state_domains, r, c):
        # Least-constraining-value order.
        vals = mask_to_values(state_domains[r][c])
        scored = []
        for v in vals:
            impact = 0
            b = bit(v)
            for cc in range(n):
                if cc != c and (state_domains[r][cc] & b):
                    impact += 1
            for rr in range(n):
                if rr != r and (state_domains[rr][c] & b):
                    impact += 1
            # Inequality-induced pressure
            for rr, cc in lt_out[r][c]:
                # if this cell = v, neighbor must be > v
                impact += popcount(state_domains[rr][cc] & ((1 << v) - 1))
            for rr, cc in lt_in[r][c]:
                # if neighbor < this cell, neighbor cannot be >= v
                impact += popcount(state_domains[rr][cc] & (full ^ ((1 << (v - 1)) - 1)))
            scored.append((impact, v))
        scored.sort()
        return [v for _, v in scored]

    def clone_domains(state_domains):
        return [row[:] for row in state_domains]

    def dfs(state_domains):
        state_domains = propagate(state_domains)
        if state_domains is None:
            return None
        if is_solved(state_domains):
            return state_domains

        best = None
        best_score = None
        for r in range(n):
            for c in range(n):
                if state_domains[r][c] & (state_domains[r][c] - 1):
                    sc = score_cell(state_domains, r, c)
                    if best is None or sc < best_score:
                        best = (r, c)
                        best_score = sc

        r, c = best
        for v in order_values(state_domains, r, c):
            new_domains = clone_domains(state_domains)
            new_domains[r][c] = bit(v)
            res = dfs(new_domains)
            if res is not None:
                return res
        return None

    solved = dfs(domains)
    if solved is None:
        return "No Solution"

    grid = [[min_val(solved[r][c]) for c in range(n)] for r in range(n)]
    return str(grid)


if __name__ == "__main__":
    print(solve(OBSERVATION))

