# Tents solver with strong propagation and bitmask-based search.
# It generalizes to arbitrary rectangular instances in the provided observation format.

def solve(observation):
    tree_grid = observation['tree']
    row_need = observation['row_tent_counts'][:]
    col_need = observation['col_tent_counts'][:]

    R = len(tree_grid)
    C = len(tree_grid[0]) if R else 0

    trees = []
    tree_index = {}
    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                tree_index[(r, c)] = len(trees)
                trees.append((r, c))

    # Valid candidate tent cells are empty cells adjacent to exactly one tree.
    cand_pos = []
    cand_tree = []
    tree_masks = [0] * len(trees)
    row_masks = [0] * R
    col_masks = [0] * C

    orth = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def inb(r, c):
        return 0 <= r < R and 0 <= c < C

    for r in range(R):
        for c in range(C):
            if tree_grid[r][c] == 'T':
                continue
            adj_trees = []
            for dr, dc in orth:
                rr, cc = r + dr, c + dc
                if inb(rr, cc) and tree_grid[rr][cc] == 'T':
                    adj_trees.append(tree_index[(rr, cc)])
            if len(adj_trees) == 1:
                t = adj_trees[0]
                i = len(cand_pos)
                cand_pos.append((r, c))
                cand_tree.append(t)
                bit = 1 << i
                tree_masks[t] |= bit
                row_masks[r] |= bit
                col_masks[c] |= bit

    n = len(cand_pos)
    if sum(row_need) != len(trees) or sum(col_need) != len(trees):
        return "No Solution"

    # Every tree must have at least one candidate.
    for tm in tree_masks:
        if tm == 0:
            return "No Solution"

    # Conflict mask: same tree or touching (including diagonal).
    conflict = [0] * n
    pos_to_idx = {cand_pos[i]: i for i in range(n)}

    for i, (r, c) in enumerate(cand_pos):
        mask = 0
        # Same-tree conflict.
        t = cand_tree[i]
        mask |= tree_masks[t]
        # Touching tents conflict.
        for rr in range(r - 1, r + 2):
            for cc in range(c - 1, c + 2):
                if (rr, cc) == (r, c):
                    continue
                j = pos_to_idx.get((rr, cc))
                if j is not None:
                    mask |= 1 << j
        mask &= ~(1 << i)
        conflict[i] = mask

    all_mask = (1 << n) - 1
    full_tree_mask = (1 << len(trees)) - 1

    # Precompute bit -> index for speed.
    bit_to_idx = {1 << i: i for i in range(n)}

    def popcount(x):
        return x.bit_count()

    def iter_bits(mask):
        while mask:
            b = mask & -mask
            yield bit_to_idx[b]
            mask ^= b

    def propagate(undecided, selected, assigned_trees, row_rem, col_rem):
        # Returns normalized state tuple or None on contradiction.
        while True:
            changed = False

            # Basic row/column feasibility and saturation forcing.
            for r in range(R):
                poss = popcount(undecided & row_masks[r])
                if row_rem[r] < 0 or row_rem[r] > poss:
                    return None
                if row_rem[r] == 0:
                    remmask = undecided & row_masks[r]
                    if remmask:
                        undecided &= ~remmask
                        changed = True
                elif row_rem[r] == poss:
                    selmask = undecided & row_masks[r]
                    while selmask:
                        b = selmask & -selmask
                        i = bit_to_idx[b]
                        # select i
                        if not (undecided & b):
                            selmask ^= b
                            continue
                        rr, cc = cand_pos[i]
                        tr = cand_tree[i]
                        undecided &= ~b
                        selected |= b
                        if assigned_trees & (1 << tr):
                            return None
                        assigned_trees |= 1 << tr
                        row_rem[rr] -= 1
                        col_rem[cc] -= 1
                        if row_rem[rr] < 0 or col_rem[cc] < 0:
                            return None
                        undecided &= ~conflict[i]
                        changed = True
                        selmask ^= b

            for c in range(C):
                poss = popcount(undecided & col_masks[c])
                if col_rem[c] < 0 or col_rem[c] > poss:
                    return None
                if col_rem[c] == 0:
                    remmask = undecided & col_masks[c]
                    if remmask:
                        undecided &= ~remmask
                        changed = True
                elif col_rem[c] == poss:
                    selmask = undecided & col_masks[c]
                    while selmask:
                        b = selmask & -selmask
                        i = bit_to_idx[b]
                        if not (undecided & b):
                            selmask ^= b
                            continue
                        rr, cc = cand_pos[i]
                        tr = cand_tree[i]
                        undecided &= ~b
                        selected |= b
                        if assigned_trees & (1 << tr):
                            return None
                        assigned_trees |= 1 << tr
                        row_rem[rr] -= 1
                        col_rem[cc] -= 1
                        if row_rem[rr] < 0 or col_rem[cc] < 0:
                            return None
                        undecided &= ~conflict[i]
                        changed = True
                        selmask ^= b

            # Tree-domain forcing.
            for t in range(len(trees)):
                tbit = 1 << t
                if assigned_trees & tbit:
                    continue
                dom = undecided & tree_masks[t]
                if dom == 0:
                    return None
                if dom & (dom - 1) == 0:
                    b = dom
                    i = bit_to_idx[b]
                    rr, cc = cand_pos[i]
                    undecided &= ~b
                    selected |= b
                    assigned_trees |= tbit
                    row_rem[rr] -= 1
                    col_rem[cc] -= 1
                    if row_rem[rr] < 0 or col_rem[cc] < 0:
                        return None
                    undecided &= ~conflict[i]
                    changed = True

            # Global completion checks.
            if assigned_trees == full_tree_mask:
                if any(v != 0 for v in row_rem) or any(v != 0 for v in col_rem):
                    return None
                return undecided, selected, assigned_trees, row_rem, col_rem

            # If all remaining row/col counts are zero, no unassigned trees may remain.
            if all(v == 0 for v in row_rem) and all(v == 0 for v in col_rem):
                return None

            # Feasibility: every unassigned tree must still have some candidate.
            for t in range(len(trees)):
                if not (assigned_trees & (1 << t)):
                    if (undecided & tree_masks[t]) == 0:
                        return None

            # Feasibility: each row/col must still have enough undecided candidates.
            for r in range(R):
                if row_rem[r] > popcount(undecided & row_masks[r]):
                    return None
            for c in range(C):
                if col_rem[c] > popcount(undecided & col_masks[c]):
                    return None

            if not changed:
                return undecided, selected, assigned_trees, row_rem, col_rem

    def branch_order_for_tree(dom):
        # Prefer candidates in tighter rows/cols and with more conflicts.
        items = []
        for i in iter_bits(dom):
            r, c = cand_pos[i]
            score = (
                popcount(conflict[i]),
                -row_need[r],
                -col_need[c],
            )
            items.append((score, i))
        items.sort(reverse=True)
        return [i for _, i in items]

    def search(undecided, selected, assigned_trees, row_rem, col_rem):
        state = propagate(undecided, selected, assigned_trees, row_rem[:], col_rem[:])
        if state is None:
            return None
        undecided, selected, assigned_trees, row_rem, col_rem = state

        if assigned_trees == full_tree_mask:
            ans = [[None for _ in range(C)] for _ in range(R)]
            for i in iter_bits(selected):
                r, c = cand_pos[i]
                ans[r][c] = 't'
            return ans

        # Choose the most constrained unassigned tree.
        best_t = -1
        best_dom = 0
        best_size = 10**9
        for t in range(len(trees)):
            if assigned_trees & (1 << t):
                continue
            dom = undecided & tree_masks[t]
            sz = popcount(dom)
            if sz < best_size:
                best_size = sz
                best_t = t
                best_dom = dom
                if sz == 2:
                    break

        if best_t == -1:
            return None

        for i in branch_order_for_tree(best_dom):
            b = 1 << i
            rr, cc = cand_pos[i]
            t = cand_tree[i]
            # Branch by selecting candidate i.
            res = search(
                (undecided & ~b) & ~conflict[i],
                selected | b,
                assigned_trees | (1 << t),
                row_rem[:rr] + [row_rem[rr] - 1] + row_rem[rr + 1:],
                col_rem[:cc] + [col_rem[cc] - 1] + col_rem[cc + 1:],
            )
            if res is not None:
                return res

        return None

    result = search(all_mask, 0, 0, row_need[:], col_need[:])
    if result is None:
        return "No Solution"
    return str(result)


