    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, 'B6', None, None, None, None, None, None], [None, None, None, None, 'B5', None, None, 'B8'], [None, None, None, None, None, None, None, None], ['W5', None, None, 'B3', None, 'W3', 'W5', None], [None, None, None, None, 'B4', None, None, None], [None, None, None, None, None, None, None, None], [None, 'B6', None, None, None, None, None, None], [None, None, None, None, None, None, None, None]]}

# Generalized solver for a single-loop dot-grid puzzle with numbered white/black clues.
# The loop uses unit edges between orthogonally adjacent dots.
# Each used dot has degree 2, unused dots degree 0.
# White clues must be straight-through; black clues must turn.
# The number on a clue equals the sum of the lengths of the two straight arms extending
# from that clue until the next turn on each side.

from copy import deepcopy

U, D, L, R = 1, 2, 4, 8
DIRS = [U, D, L, R]
DRC = {U: (-1, 0), D: (1, 0), L: (0, -1), R: (0, 1)}
OPP = {U: D, D: U, L: R, R: L}

EMPTY = 0
UD = U | D
LR = L | R
UL = U | L
UR = U | R
DL = D | L
DR = D | R

ALL_STATES = [EMPTY, UD, LR, UL, UR, DL, DR]
STRAIGHTS = {UD, LR}
TURNS = {UL, UR, DL, DR}

def popcount(x):
    return (x & 1) + ((x >> 1) & 1) + ((x >> 2) & 1) + ((x >> 3) & 1)

def is_straight(mask):
    return mask in STRAIGHTS

def is_turn(mask):
    return mask in TURNS

def state_dirs(mask):
    return [d for d in DIRS if mask & d]

def move(pos, d):
    r, c = pos
    dr, dc = DRC[d]
    return r + dr, c + dc

def in_bounds(n, r, c):
    return 0 <= r < n and 0 <= c < n

def clue_info(token):
    if token is None:
        return None
    return token[0], int(token[1:])

def allowed_states_for_cell(n, r, c, clue):
    states = []
    for s in ALL_STATES:
        ok = True
        if r == 0 and (s & U): ok = False
        if r == n - 1 and (s & D): ok = False
        if c == 0 and (s & L): ok = False
        if c == n - 1 and (s & R): ok = False
        if not ok:
            continue
        if clue is not None:
            t, _ = clue_info(clue)
            if s == EMPTY:
                continue
            if t == 'W' and not is_straight(s):
                continue
            if t == 'B' and not is_turn(s):
                continue
        states.append(s)
    return set(states)

def shared_edge_dir(a, b):
    ra, ca = a
    rb, cb = b
    if ra == rb:
        if ca + 1 == cb:
            return R
        if cb + 1 == ca:
            return L
    if ca == cb:
        if ra + 1 == rb:
            return D
        if rb + 1 == ra:
            return U
    return None

def compatible(sa, sb, d_ab):
    ea = bool(sa & d_ab)
    eb = bool(sb & OPP[d_ab])
    return ea == eb

def neighbor_positions(n, r, c):
    for d in DIRS:
        rr, cc = move((r, c), d)
        if in_bounds(n, rr, cc):
            yield d, rr, cc

def initial_domains(observation):
    data = observation['data']
    n = len(data)
    domains = {}
    for r in range(n):
        for c in range(n):
            domains[(r, c)] = allowed_states_for_cell(n, r, c, data[r][c])
    return domains

def propagate(domains, observation):
    data = observation['data']
    n = len(data)
    changed = True
    while changed:
        changed = False

        # Edge-based arc consistency
        for r in range(n):
            for c in range(n):
                a = (r, c)
                for d, rr, cc in neighbor_positions(n, r, c):
                    b = (rr, cc)
                    da = domains[a]
                    db = domains[b]
                    new_da = set()
                    for sa in da:
                        if any(compatible(sa, sb, d) for sb in db):
                            new_da.add(sa)
                    if not new_da:
                        return False
                    if new_da != da:
                        domains[a] = new_da
                        da = new_da
                        changed = True

        # For clues, enforce feasibility of numbered arm-length constraint by interval pruning.
        for r in range(n):
            for c in range(n):
                token = data[r][c]
                if token is None:
                    continue
                t, k = clue_info(token)
                pos = (r, c)
                feasible_states = set()
                for s in domains[pos]:
                    if t == 'W' and not is_straight(s):
                        continue
                    if t == 'B' and not is_turn(s):
                        continue
                    dirs = state_dirs(s)
                    if len(dirs) != 2:
                        continue
                    a = arm_interval(domains, observation, pos, dirs[0])
                    b = arm_interval(domains, observation, pos, dirs[1])
                    if a is None or b is None:
                        continue
                    minsum = a[0] + b[0]
                    maxsum = a[1] + b[1]
                    if minsum <= k <= maxsum:
                        feasible_states.add(s)
                if not feasible_states:
                    return False
                if feasible_states != domains[pos]:
                    domains[pos] = feasible_states
                    changed = True

        # Singleton state forces neighboring usage consistency more strongly.
        # Also reject impossible isolated clue situations.
        for r in range(n):
            for c in range(n):
                if not domains[(r, c)]:
                    return False

        # Prevent completed subloops before all clue cells are included and all used cells accounted for.
        if has_forbidden_closed_component(domains, observation):
            return False

    return True

def arm_interval(domains, observation, start, d):
    # Returns (min_length, max_length) of the straight arm from `start` leaving in direction d,
    # under current domains. The arm proceeds until it reaches a turn; the turn vertex is included.
    n = len(observation['data'])
    cur = start
    length = 0
    min_len = None
    while True:
        nxt = move(cur, d)
        if not in_bounds(n, nxt[0], nxt[1]):
            return None
        length += 1
        dom = domains[nxt]
        incoming = OPP[d]

        feasible = [s for s in dom if (s & incoming)]
        if not feasible:
            return None

        turn_possible = any(is_turn(s) and not (s & d) for s in feasible)
        cont_possible = any(is_straight(s) and (s & d) for s in feasible)

        if turn_possible and min_len is None:
            min_len = length

        if not cont_possible:
            if not turn_possible:
                return None
            return (min_len, length)

        cur = nxt
        # continue; max length obtained by delaying turn as much as possible

def has_forbidden_closed_component(domains, observation):
    # If a fully assigned cycle exists while some clue is not yet guaranteed inside that same finished loop,
    # reject. This is a lightweight but useful prune.
    single_used = {p: next(iter(dom)) for p, dom in domains.items() if len(dom) == 1 and next(iter(dom)) != EMPTY}
    if not single_used:
        return False

    adj = {}
    for p, s in single_used.items():
        nbrs = []
        for d in state_dirs(s):
            q = move(p, d)
            if q in single_used and (single_used[q] & OPP[d]):
                nbrs.append(q)
        adj[p] = nbrs

    visited = set()
    clue_positions = {(r, c) for r, row in enumerate(observation['data']) for c, tok in enumerate(row) if tok is not None}

    for p in adj:
        if p in visited:
            continue
        stack = [p]
        comp = []
        visited.add(p)
        while stack:
            x = stack.pop()
            comp.append(x)
            for y in adj.get(x, []):
                if y not in visited:
                    visited.add(y)
                    stack.append(y)
        if comp and all(len(adj.get(x, [])) == 2 for x in comp):
            # A closed assigned component exists.
            comp_set = set(comp)
            # If there exists any clue outside it that is not fixed empty/impossible, reject this premature loop.
            for q in clue_positions:
                if q not in comp_set:
                    return True
            # Also if some non-singleton variable could still be used, this is premature.
            for q, dom in domains.items():
                if q not in comp_set and any(s != EMPTY for s in dom):
                    return True
    return False

def select_var(domains, observation):
    data = observation['data']
    best = None
    best_key = None
    for p, dom in domains.items():
        if len(dom) <= 1:
            continue
        r, c = p
        clue = data[r][c] is not None
        nonempty_count = sum(1 for s in dom if s != EMPTY)
        # prioritize clues, then variables with fewer states, then fewer non-empty choices
        key = (0 if clue else 1, len(dom), nonempty_count, r + c)
        if best_key is None or key < best_key:
            best_key = key
            best = p
    return best

def state_priority(p, dom, observation):
    data = observation['data']
    r, c = p
    token = data[r][c]
    vals = list(dom)
    if token is not None:
        t, k = clue_info(token)
        scored = []
        for s in vals:
            dirs = state_dirs(s)
            if len(dirs) != 2:
                continue
            a = arm_interval_single_state_preview(observation, p, dirs[0])
            b = arm_interval_single_state_preview(observation, p, dirs[1])
            score = 0
            if a is not None and b is not None:
                score = abs((a + b) - k)
            scored.append((score, s))
        return [s for _, s in sorted(scored)]
    return sorted(vals, key=lambda s: (s == EMPTY, 0 if s in STRAIGHTS else 1, s))

def arm_interval_single_state_preview(observation, start, d):
    # Simple optimistic geometric lower bound from a fixed clue state:
    # shortest possible arm length is 1, unless impossible due to border.
    n = len(observation['data'])
    nxt = move(start, d)
    if not in_bounds(n, nxt[0], nxt[1]):
        return None
    return 2

def exact_arm_length(state_map, start, d):
    cur = start
    length = 0
    while True:
        nxt = move(cur, d)
        if nxt not in state_map:
            return None
        s = state_map[nxt]
        incoming = OPP[d]
        if not (s & incoming):
            return None
        length += 1
        if is_turn(s):
            return length
        if is_straight(s) and (s & d):
            cur = nxt
            continue
        return None

def final_check(domains, observation):
    if any(len(dom) != 1 for dom in domains.values()):
        return False
    state_map = {p: next(iter(dom)) for p, dom in domains.items()}
    used = [p for p, s in state_map.items() if s != EMPTY]
    if not used:
        return False

    # Degrees are intrinsic to states; verify matched adjacency
    for p, s in state_map.items():
        for d in DIRS:
            q = move(p, d)
            edge = bool(s & d)
            if q in state_map:
                if edge != bool(state_map[q] & OPP[d]):
                    return False
            else:
                if edge:
                    return False

    # Single loop
    start = used[0]
    seen = set()
    prev = None
    cur = start
    while True:
        seen.add(cur)
        s = state_map[cur]
        nbrs = [move(cur, d) for d in state_dirs(s)]
        if prev is None:
            nxt = nbrs[0]
        else:
            if len(nbrs) != 2:
                return False
            nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]
        prev, cur = cur, nxt
        if cur == start:
            break
        if cur in seen:
            return False
    if set(used) != seen:
        return False

    # Clue checks
    data = observation['data']
    for r in range(len(data)):
        for c in range(len(data)):
            tok = data[r][c]
            if tok is None:
                continue
            t, k = clue_info(tok)
            s = state_map[(r, c)]
            if t == 'W' and not is_straight(s):
                return False
            if t == 'B' and not is_turn(s):
                return False
            dirs = state_dirs(s)
            if len(dirs) != 2:
                return False
            a = exact_arm_length(state_map, (r, c), dirs[0])
            b = exact_arm_length(state_map, (r, c), dirs[1])
            if a is None or b is None or a + b != k:
                return False

    return True

def build_path(domains):
    state_map = {p: next(iter(dom)) for p, dom in domains.items()}
    used = sorted([p for p, s in state_map.items() if s != EMPTY])
    if not used:
        return []
    start = used[0]
    path = [start]
    prev = None
    cur = start
    while True:
        s = state_map[cur]
        nbrs = [move(cur, d) for d in state_dirs(s)]
        if prev is None:
            nxt = sorted(nbrs)[0]
        else:
            nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
    return path

def search(domains, observation, depth=0, limit=[0]):
    limit[0] += 1
    if limit[0] > 200000:
        return None

    if not propagate(domains, observation):
        return None

    if all(len(dom) == 1 for dom in domains.values()):
        if final_check(domains, observation):
            return domains
        return None

    p = select_var(domains, observation)
    if p is None:
        return None

    ordered = state_priority(p, domains[p], observation)
    for s in ordered:
        new_domains = {k: set(v) for k, v in domains.items()}
        new_domains[p] = {s}
        res = search(new_domains, observation, depth + 1, limit)
        if res is not None:
            return res
    return None

def solve(observation):
    domains = initial_domains(observation)
    res = search(domains, observation)
    if res is None:
        return "No Solution"
    return str(build_path(res))

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, 'W', None, None, None, 'W', None], ['W', None, None, None, 'W', None, None, 'W'], ['B', None, None, None, None, None, None, None], [None, None, None, None, 'W', None, None, 'B'], [None, 'W', None, 'B', None, None, None, None], [None, None, None, None, 'W', 'W', None, None], [None, None, None, 'B', 'W', None, None, 'W'], ['B', None, None, None, None, None, 'W', None]]}

from collections import deque

U, D, L, R = 1, 2, 4, 8
DIRS = [U, D, L, R]
DRC = {U: (-1, 0), D: (1, 0), L: (0, -1), R: (0, 1)}
OPP = {U: D, D: U, L: R, R: L}

VERT = U | D
HORZ = L | R
TURNS = [U | L, U | R, D | L, D | R]
STRAIGHTS = [VERT, HORZ]

def popcount(x):
    return (x & 1) + ((x >> 1) & 1) + ((x >> 2) & 1) + ((x >> 3) & 1)

def has_dir(mask, d):
    return (mask & d) != 0

def coord_in(n, r, c):
    return 0 <= r < n and 0 <= c < n

def neighbor_of(r, c, d):
    dr, dc = DRC[d]
    return r + dr, c + dc

def vertex_dirs(n, r, c):
    m = 0
    if r > 0:
        m |= U
    if r < n - 1:
        m |= D
    if c > 0:
        m |= L
    if c < n - 1:
        m |= R
    return m

def all_local_states(avail_mask):
    states = [0]
    for s in STRAIGHTS + TURNS:
        if (s & avail_mask) == s:
            states.append(s)
    return states

def initial_domains(data):
    n = len(data)
    domains = {}
    for r in range(n):
        for c in range(n):
            avail = vertex_dirs(n, r, c)
            clue = data[r][c]
            if clue is None:
                domains[(r, c)] = set(all_local_states(avail))
            elif clue == 'W':
                opts = set()
                if (VERT & avail) == VERT:
                    opts.add(VERT)
                if (HORZ & avail) == HORZ:
                    opts.add(HORZ)
                domains[(r, c)] = opts
            elif clue == 'B':
                opts = set()
                for s in TURNS:
                    if (s & avail) == s:
                        opts.add(s)
                domains[(r, c)] = opts
            else:
                raise ValueError("Unknown clue")
            if not domains[(r, c)]:
                return None
    return domains

def edge_possible_from_domain(domain, d):
    any_on = any(has_dir(s, d) for s in domain)
    any_off = any(not has_dir(s, d) for s in domain)
    if any_on and any_off:
        return None
    return any_on

def domain_filter_by_edge(domain, d, must_on):
    if must_on:
        return {s for s in domain if has_dir(s, d)}
    return {s for s in domain if not has_dir(s, d)}

def black_state_ok(domains, pos, s, n):
    r, c = pos
    for d in DIRS:
        if has_dir(s, d):
            nr, nc = neighbor_of(r, c, d)
            if not coord_in(n, nr, nc):
                return False
            ndom = domains[(nr, nc)]
            req = VERT if d in (U, D) else HORZ
            if req not in ndom:
                return False
    return True

def white_turn_possible(ndom, incoming_dir):
    # incoming_dir is the direction at the neighbor pointing toward the white cell
    # Turn means the neighbor uses incoming_dir and does not continue straight along the same axis.
    if incoming_dir == U:
        return any(has_dir(s, U) and not has_dir(s, D) for s in ndom)
    if incoming_dir == D:
        return any(has_dir(s, D) and not has_dir(s, U) for s in ndom)
    if incoming_dir == L:
        return any(has_dir(s, L) and not has_dir(s, R) for s in ndom)
    if incoming_dir == R:
        return any(has_dir(s, R) and not has_dir(s, L) for s in ndom)
    return False

def white_state_ok(domains, pos, s, n):
    r, c = pos
    if s == VERT:
        up = (r - 1, c)
        down = (r + 1, c)
        if not (coord_in(n, *up) and coord_in(n, *down)):
            return False
        udom = domains[up]
        ddom = domains[down]
        if not any(has_dir(t, D) for t in udom):
            return False
        if not any(has_dir(t, U) for t in ddom):
            return False
        if not (white_turn_possible(udom, D) or white_turn_possible(ddom, U)):
            return False
        return True
    if s == HORZ:
        left = (r, c - 1)
        right = (r, c + 1)
        if not (coord_in(n, *left) and coord_in(n, *right)):
            return False
        ldom = domains[left]
        rdom = domains[right]
        if not any(has_dir(t, R) for t in ldom):
            return False
        if not any(has_dir(t, L) for t in rdom):
            return False
        if not (white_turn_possible(ldom, R) or white_turn_possible(rdom, L)):
            return False
        return True
    return False

def clue_filter(domains, data):
    n = len(data)
    changed = False
    for pos, dom in list(domains.items()):
        clue = data[pos[0]][pos[1]]
        if clue == 'B':
            nd = {s for s in dom if black_state_ok(domains, pos, s, n)}
            if not nd:
                return None, True
            if nd != dom:
                domains[pos] = nd
                changed = True
        elif clue == 'W':
            nd = {s for s in dom if white_state_ok(domains, pos, s, n)}
            if not nd:
                return None, True
            if nd != dom:
                domains[pos] = nd
                changed = True
    return domains, changed

def arc_consistency(domains, data):
    n = len(data)
    changed_any = True
    while changed_any:
        changed_any = False

        # Shared-edge consistency
        for r in range(n):
            for c in range(n):
                pos = (r, c)
                dom = domains[pos]
                for d in DIRS:
                    nr, nc = neighbor_of(r, c, d)
                    if not coord_in(n, nr, nc):
                        continue
                    npos = (nr, nc)
                    ndom = domains[npos]
                    new_dom = set()
                    for s in dom:
                        need = has_dir(s, d)
                        if any(has_dir(t, OPP[d]) == need for t in ndom):
                            new_dom.add(s)
                    if not new_dom:
                        return None
                    if new_dom != dom:
                        domains[pos] = new_dom
                        dom = new_dom
                        changed_any = True

        # Clue semantics
        domains, clue_changed = clue_filter(domains, data)
        if domains is None:
            return None
        changed_any = changed_any or clue_changed

        # Degree 0/2 is already encoded in states, but force impossible local edge decisions
        # through singleton-neighbor propagation.
        for r in range(n):
            for c in range(n):
                pos = (r, c)
                dom = domains[pos]
                for d in DIRS:
                    nr, nc = neighbor_of(r, c, d)
                    if not coord_in(n, nr, nc):
                        continue
                    status = edge_possible_from_domain(dom, d)
                    if status is None:
                        continue
                    npos = (nr, nc)
                    ndom = domains[npos]
                    filtered = domain_filter_by_edge(ndom, OPP[d], status)
                    if not filtered:
                        return None
                    if filtered != ndom:
                        domains[npos] = filtered
                        changed_any = True

        if premature_cycle(domains, data):
            return None

    return domains

def infer_forced_edges(domains):
    forced_on = set()
    forced_off = set()
    for (r, c), dom in domains.items():
        for d in (D, R):
            nr, nc = neighbor_of(r, c, d)
            if (nr, nc) not in domains:
                continue
            a = edge_possible_from_domain(dom, d)
            b = edge_possible_from_domain(domains[(nr, nc)], OPP[d])
            if a is True and b is True:
                forced_on.add(((r, c), (nr, nc)))
            elif a is False and b is False:
                forced_off.add(((r, c), (nr, nc)))
    return forced_on, forced_off

def clue_vertices(data):
    n = len(data)
    return {(r, c) for r in range(n) for c in range(n) if data[r][c] in ('W', 'B')}

def vertices_maybe_in_loop(domains):
    return {pos for pos, dom in domains.items() if any(s != 0 for s in dom)}

def premature_cycle(domains, data):
    forced_on, _ = infer_forced_edges(domains)
    if not forced_on:
        return False

    adj = {pos: set() for pos in domains}
    for a, b in forced_on:
        adj[a].add(b)
        adj[b].add(a)

    maybe = vertices_maybe_in_loop(domains)
    required = clue_vertices(data)

    seen = set()
    for v in adj:
        if v in seen or not adj[v]:
            continue
        comp = set()
        stack = [v]
        seen.add(v)
        while stack:
            x = stack.pop()
            comp.add(x)
            for y in adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)

        degs = [len(adj[x]) for x in comp]
        if all(d == 2 for d in degs):
            # Forced closed cycle.
            if comp != maybe:
                # If anything outside can still be in loop, this is a premature small loop.
                outside_maybe = maybe - comp
                outside_required = required - comp
                if outside_maybe or outside_required:
                    return True
    return False

def is_solved(domains):
    return all(len(dom) == 1 for dom in domains.values())

def build_selected_edges(domains):
    edges = set()
    for (r, c), dom in domains.items():
        s = next(iter(dom))
        for d in (D, R):
            if has_dir(s, d):
                nr, nc = neighbor_of(r, c, d)
                edges.add(((r, c), (nr, nc)))
    return edges

def final_check(domains, data):
    n = len(data)
    for pos, dom in domains.items():
        if len(dom) != 1:
            return False
        s = next(iter(dom))
        clue = data[pos[0]][pos[1]]
        if clue in ('W', 'B') and s == 0:
            return False

    edges = build_selected_edges(domains)
    if not edges:
        return False

    adj = {}
    for a, b in edges:
        adj.setdefault(a, set()).add(b)
        adj.setdefault(b, set()).add(a)

    for v, neigh in adj.items():
        if len(neigh) != 2:
            return False

    # Every non-empty vertex must be in the single cycle, and empty vertices must be absent.
    used = {pos for pos, dom in domains.items() if next(iter(dom)) != 0}
    if set(adj) != used:
        return False

    start = next(iter(adj))
    seen = set()
    stack = [start]
    while stack:
        x = stack.pop()
        if x in seen:
            continue
        seen.add(x)
        stack.extend(adj[x] - seen)

    if seen != used:
        return False

    # Revalidate clue semantics on the final assignment.
    for pos in used:
        clue = data[pos[0]][pos[1]]
        s = next(iter(domains[pos]))
        if clue == 'B' and s not in TURNS:
            return False
        if clue == 'W' and s not in STRAIGHTS:
            return False
    return True

def choose_branch_vertex(domains, data):
    best = None
    best_key = None
    for pos, dom in domains.items():
        if len(dom) <= 1:
            continue
        clue = data[pos[0]][pos[1]]
        # Prefer clue vertices, then smallest domain.
        key = (0 if clue in ('W', 'B') else 1, len(dom))
        if best_key is None or key < best_key:
            best = pos
            best_key = key
    return best

def domain_order(pos, domains, data):
    dom = list(domains[pos])
    clue = data[pos[0]][pos[1]]
    # Human-like: prefer non-empty states on clues, and on ordinary vertices prefer states
    # that match stronger neighboring requirements.
    if clue == 'B':
        return sorted(dom, key=lambda s: (0, s))
    if clue == 'W':
        pref = [VERT, HORZ]
        return [s for s in pref if s in dom]
    return sorted(dom, key=lambda s: (s == 0, popcount(s), s))

def copy_domains(domains):
    return {k: set(v) for k, v in domains.items()}

def search(domains, data, depth=0):
    domains = arc_consistency(domains, data)
    if domains is None:
        return None
    if is_solved(domains):
        if final_check(domains, data):
            return domains
        return None

    pos = choose_branch_vertex(domains, data)
    if pos is None:
        return None

    for s in domain_order(pos, domains, data):
        nd = copy_domains(domains)
        nd[pos] = {s}
        res = search(nd, data, depth + 1)
        if res is not None:
            return res
    return None

def extract_loop_path(domains):
    edges = build_selected_edges(domains)
    adj = {}
    for a, b in edges:
        adj.setdefault(a, []).append(b)
        adj.setdefault(b, []).append(a)

    start = min(adj)
    path = [start]
    prev = None
    cur = start

    while True:
        nbrs = adj[cur]
        if prev is None:
            nxt = min(nbrs)
        else:
            nxt = nbrs[0] if nbrs[1] == prev else nbrs[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
    return path

def solve(observation):
    data = observation['data']
    domains = initial_domains(data)
    if domains is None:
        return "No Solution"
    res = search(domains, data)
    if res is None:
        return "No Solution"
    return extract_loop_path(res)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 1, 1, 1, 2, 2, 3, 3], [0, 0, 4, 1, 5, 2, 2, 2], [0, 0, 4, 6, 5, 5, 5, 2], [0, 0, 4, 7, 7, 5, 8, 9], [0, 0, 5, 5, 5, 5, 5, 9], [10, 10, 10, 11, 5, 5, 12, 12], [10, 10, 10, 11, 5, 5, 5, 12], [10, 10, 10, 10, 5, 5, 13, 13]]}

from collections import defaultdict

def solve(observation):
    data = observation["data"]
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    cells = [(r, c) for r in range(n) for c in range(n)]
    idx = {(r, c): r * n + c for r, c in cells}
    regions = defaultdict(list)
    for r in range(n):
        for c in range(n):
            regions[data[r][c]].append(idx[(r, c)])
    region_ids = sorted(regions)
    ridx = {rid: i for i, rid in enumerate(region_ids)}
    R = len(region_ids)

    # Orthogonal neighbors
    nbrs = [[] for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            u = idx[(r, c)]
            if r > 0:
                nbrs[u].append(idx[(r - 1, c)])
            if r + 1 < n:
                nbrs[u].append(idx[(r + 1, c)])
            if c > 0:
                nbrs[u].append(idx[(r, c - 1)])
            if c + 1 < n:
                nbrs[u].append(idx[(r, c + 1)])

    # Candidate dominoes
    dom_cells = []
    dom_regions = []
    dom_cellmask = []
    cell_to_doms = [0] * (n * n)
    region_to_doms = [0] * R

    def add_dom(a, b):
        i = len(dom_cells)
        dom_cells.append((a, b))
        ra = ridx[data[a // n][a % n]]
        rb = ridx[data[b // n][b % n]]
        contrib = {}
        contrib[ra] = contrib.get(ra, 0) + 1
        contrib[rb] = contrib.get(rb, 0) + 1
        dom_regions.append(contrib)
        mask = (1 << a) | (1 << b)
        dom_cellmask.append(mask)
        cell_to_doms[a] |= 1 << i
        cell_to_doms[b] |= 1 << i
        for rr in contrib:
            region_to_doms[rr] |= 1 << i

    for r in range(n):
        for c in range(n):
            u = idx[(r, c)]
            if c + 1 < n:
                add_dom(u, idx[(r, c + 1)])
            if r + 1 < n:
                add_dom(u, idx[(r + 1, c)])

    D = len(dom_cells)

    # Domino conflicts:
    # - overlap
    # - any orthogonal touch between cells belonging to different dominoes
    # Build cell-neighborhood masks to derive conflicts quickly.
    touch_mask = [0] * (n * n)
    for u in range(n * n):
        m = 1 << u
        for v in nbrs[u]:
            m |= 1 << v
        touch_mask[u] = m

    conflict = [0] * D
    for i, (a, b) in enumerate(dom_cells):
        touched = (touch_mask[a] | touch_mask[b])
        # Any domino using a touched cell conflicts, except itself.
        cm = 0
        x = touched
        while x:
            lsb = x & -x
            cell = lsb.bit_length() - 1
            cm |= cell_to_doms[cell]
            x ^= lsb
        cm &= ~(1 << i)
        conflict[i] = cm

    # Region support per cell
    region_cells = [[] for _ in range(R)]
    region_cell_support = [dict() for _ in range(R)]
    for rid, cells_in_region in regions.items():
        rr = ridx[rid]
        region_cells[rr] = list(cells_in_region)
        for u in cells_in_region:
            region_cell_support[rr][u] = cell_to_doms[u]

    full_dom_mask = (1 << D) - 1

    # Precompute contribution bitmasks by region/count pattern
    doms_contrib_1 = [0] * R
    doms_contrib_2 = [0] * R
    for i, contrib in enumerate(dom_regions):
        for rr, cnt in contrib.items():
            if cnt == 1:
                doms_contrib_1[rr] |= 1 << i
            else:
                doms_contrib_2[rr] |= 1 << i

    best = {"ans": None}

    def selected_counts_from_mask(sel_mask):
        cnt = [0] * R
        x = sel_mask
        while x:
            lsb = x & -x
            i = lsb.bit_length() - 1
            for rr, v in dom_regions[i].items():
                cnt[rr] += v
            x ^= lsb
        return cnt

    def coverable_cells_in_region(rr, undecided_mask, selected_mask):
        # Cells already shaded by selected dominoes in rr plus cells that can still be shaded.
        shaded = set()
        x = selected_mask & region_to_doms[rr]
        while x:
            lsb = x & -x
            i = lsb.bit_length() - 1
            a, b = dom_cells[i]
            if a in region_cell_support[rr]:
                shaded.add(a)
            if b in region_cell_support[rr]:
                shaded.add(b)
            x ^= lsb
        possible = set(shaded)
        for u in region_cells[rr]:
            if u in possible:
                continue
            if region_cell_support[rr][u] & undecided_mask:
                possible.add(u)
        return shaded, possible

    def force_include(dom_i, state):
        undecided, selected, rcnt = state
        bit = 1 << dom_i
        if not (undecided & bit):
            return None if not (selected & bit) else state
        # select it
        selected |= bit
        undecided &= ~bit
        # remove conflicts
        undecided &= ~conflict[dom_i]
        for rr, v in dom_regions[dom_i].items():
            rcnt[rr] += v
            if rcnt[rr] > 2:
                return None
        return (undecided, selected, rcnt)

    def force_exclude(dom_i, state):
        undecided, selected, rcnt = state
        bit = 1 << dom_i
        if undecided & bit:
            undecided &= ~bit
        return (undecided, selected, rcnt)

    def propagate(state):
        undecided, selected, rcnt = state
        changed = True
        while changed:
            changed = False

            # Region-based pruning and forcing
            for rr in range(R):
                if rcnt[rr] > 2:
                    return None

                shaded, possible = coverable_cells_in_region(rr, undecided, selected)
                max_possible = len(possible)
                if max_possible < 2:
                    return None

                if rcnt[rr] == 2:
                    # Exclude all undecided dominoes touching this region.
                    rem = undecided & region_to_doms[rr]
                    if rem:
                        x = rem
                        while x:
                            lsb = x & -x
                            i = lsb.bit_length() - 1
                            state2 = force_exclude(i, (undecided, selected, rcnt))
                            if state2 is None:
                                return None
                            undecided, selected, rcnt = state2
                            changed = True
                            x ^= lsb
                        continue

                need = 2 - rcnt[rr]
                if len(possible) < 2:
                    return None

                # If exactly need not-yet-selected cells remain possible in region, they are forced shaded.
                forced_cells = [u for u in possible if u not in shaded]
                if len(forced_cells) == need:
                    for u in forced_cells:
                        cand = region_cell_support[rr][u] & undecided
                        # Must be covered by one selected/undecided domino
                        if cand == 0:
                            return None
                        if cand & (cand - 1) == 0:
                            i = cand.bit_length() - 1
                            state2 = force_include(i, (undecided, selected, rcnt))
                            if state2 is None:
                                return None
                            undecided, selected, rcnt = state2
                            changed = True

                # Upper bound by distinct coverable cells
                if rcnt[rr] + sum(1 for u in region_cells[rr] if (u not in shaded and (region_cell_support[rr][u] & undecided))) < 2:
                    return None

                # If exactly enough contribution sources remain to reach 2 and a cell has unique support, force it.
                if need > 0:
                    for u in region_cells[rr]:
                        if u in shaded:
                            continue
                        cand = region_cell_support[rr][u] & undecided
                        # If this cell is the only way for some region to reach total, singleton support forces.
                        if cand and (cand & (cand - 1) == 0):
                            # Only force when removing this cell would make region impossible.
                            other_coverable = 0
                            for v in region_cells[rr]:
                                if v == u or v in shaded:
                                    continue
                                if region_cell_support[rr][v] & undecided:
                                    other_coverable += 1
                            if 1 + other_coverable < need:
                                i = cand.bit_length() - 1
                                state2 = force_include(i, (undecided, selected, rcnt))
                                if state2 is None:
                                    return None
                                undecided, selected, rcnt = state2
                                changed = True

            # Cell-level impossible isolation:
            # If a selected shaded cell would require another selected touching cell not in its domino, that is already prevented by conflicts.
            # If a cell can only be shaded by dominos all excluded, it's just unshaded; nothing to do.
            # However, if a region still needs cells and one cell has no support, prune via region checks above.

        return (undecided, selected, rcnt)

    def choose_branch(state):
        undecided, selected, rcnt = state

        # Prefer a region needing cells with a forced/near-forced cell support minimum
        best_item = None

        for rr in range(R):
            if rcnt[rr] >= 2:
                continue
            shaded, possible = coverable_cells_in_region(rr, undecided, selected)
            need = 2 - rcnt[rr]
            candidates = []
            for u in region_cells[rr]:
                if u in shaded:
                    continue
                cand = region_cell_support[rr][u] & undecided
                if cand:
                    candidates.append((cand.bit_count(), u, cand))
            if not candidates:
                return None
            candidates.sort()
            k, u, cand = candidates[0]
            score = (need, k, len(candidates))
            if best_item is None or score < best_item[0]:
                best_item = (score, ("cell", rr, u, cand))

        if best_item is not None:
            return best_item[1]

        # Fallback: choose undecided domino with largest total contribution to still-open regions
        x = undecided
        best = None
        while x:
            lsb = x & -x
            i = lsb.bit_length() - 1
            weight = 0
            for rr, v in dom_regions[i].items():
                if rcnt[rr] < 2:
                    weight += v
            key = (-weight, conflict[i].bit_count())
            if best is None or key < best[0]:
                best = (key, ("domino", i))
            x ^= lsb
        return best[1] if best else None

    def dfs(state):
        if best["ans"] is not None:
            return True

        state = propagate(state)
        if state is None:
            return False
        undecided, selected, rcnt = state

        if all(v == 2 for v in rcnt):
            best["ans"] = selected
            return True

        branch = choose_branch(state)
        if branch is None:
            return False

        kind = branch[0]
        if kind == "cell":
            _, rr, u, cand = branch
            # Branch by selecting one domino covering this constrained cell.
            options = []
            x = cand
            while x:
                lsb = x & -x
                i = lsb.bit_length() - 1
                options.append(i)
                x ^= lsb
            # Try higher region contribution first
            options.sort(key=lambda i: (-sum(v for _, v in dom_regions[i].items()), conflict[i].bit_count()))
            for i in options:
                rcnt2 = rcnt[:]
                st = force_include(i, (undecided, selected, rcnt2))
                if st is not None and dfs(st):
                    return True
            # If cell was not truly forced, exclusion branch may still exist.
            # But region-guided branching only on supported cells can over-force if not exact;
            # so add a fallback branch by excluding all those options one-by-one through generic branch later.
            # Exclude the smallest option and continue search.
            i = options[0]
            if dfs(force_exclude(i, (undecided, selected, rcnt[:]))):
                return True
            return False

        _, i = branch
        rcnt2 = rcnt[:]
        st = force_include(i, (undecided, selected, rcnt2))
        if st is not None and dfs(st):
            return True
        return dfs(force_exclude(i, (undecided, selected, rcnt[:])))

    init_state = (full_dom_mask, 0, [0] * R)
    dfs(init_state)

    if best["ans"] is None:
        return "No Solution"

    ans_grid = [[None for _ in range(n)] for _ in range(n)]
    sel = best["ans"]
    x = sel
    while x:
        lsb = x & -x
        i = lsb.bit_length() - 1
        a, b = dom_cells[i]
        ans_grid[a // n][a % n] = 'S'
        ans_grid[b // n][b % n] = 'S'
        x ^= lsb
    return str(ans_grid)

