OBSERVATION = {'region': [[0, 1, 2, 2, 2, 2, 3, 3, 4, 4], [0, 5, 5, 5, 6, 6, 3, 3, 4, 4], [0, 5, 5, 5, 7, 7, 3, 3, 8, 9], [0, 10, 11, 11, 7, 7, 12, 12, 8, 9], [0, 10, 11, 11, 7, 7, 12, 12, 8, 9], [0, 13, 13, 14, 14, 14, 14, 14, 14, 9], [0, 13, 13, 15, 15, 16, 17, 18, 18, 9], [0, 19, 19, 15, 15, 16, 17, 20, 20, 9], [0, 21, 22, 22, 22, 22, 17, 20, 20, 9], [0, 23, 23, 23, 23, 23, 23, 23, 23, 23]], 'data': [[1, None, 1, None, None, None, 1, None, None, None], [None, None, None, None, 0, None, None, None, None, None], [None, None, None, None, None, None, None, None, 0, 3], [None, None, None, None, None, None, 2, None, None, None], [None, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None], [None, None, None, 2, None, 0, None, None, None, None], [None, 1, None, None, None, None, None, None, None, None], [None, 1, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, None]]}

from collections import deque, defaultdict

BLACK = 1
WHITE = 0
UNKNOWN = -1

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx_of = {(r, c): r * m + c for r, c in cells}
    rc_of = {idx_of[(r, c)]: (r, c) for r, c in cells}

    neighbors = [[] for _ in range(n * m)]
    for r in range(n):
        for c in range(m):
            i = idx_of[(r, c)]
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    neighbors[i].append(idx_of[(rr, cc)])

    region_cells = defaultdict(list)
    region_clue = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            i = idx_of[(r, c)]
            region_cells[rid].append(i)
            if data[r][c] is not None:
                region_clue[rid] = data[r][c]

    # Heyawake "straight white line through at most 2 regions":
    # For each row/col, every minimal span covering 3 consecutive region blocks
    # must contain at least one black.
    triple_constraints = []
    triples_of_cell = [[] for _ in range(n * m)]

    def add_line_constraints(line_indices):
        blocks = []
        start = 0
        while start < len(line_indices):
            rid = region[rc_of[line_indices[start]][0]][rc_of[line_indices[start]][1]]
            end = start + 1
            while end < len(line_indices):
                rr, cc = rc_of[line_indices[end]]
                if region[rr][cc] != rid:
                    break
                end += 1
            blocks.append(line_indices[start:end])
            start = end
        for k in range(len(blocks) - 2):
            span = blocks[k] + blocks[k + 1] + blocks[k + 2]
            triple_constraints.append(span)

    for r in range(n):
        add_line_constraints([idx_of[(r, c)] for c in range(m)])
    for c in range(m):
        add_line_constraints([idx_of[(r, c)] for r in range(n)])

    for t_idx, span in enumerate(triple_constraints):
        for i in span:
            triples_of_cell[i].append(t_idx)

    triple_constraints = [tuple(span) for span in triple_constraints]

    state0 = [UNKNOWN] * (n * m)

    def clone_state(state):
        return state[:]

    def region_stats(state, rid):
        black = unknown = 0
        for i in region_cells[rid]:
            if state[i] == BLACK:
                black += 1
            elif state[i] == UNKNOWN:
                unknown += 1
        return black, unknown

    def possible_white_graph_components(state):
        allowed = [i for i, v in enumerate(state) if v != BLACK]
        allowed_set = set(allowed)
        comps = []
        seen = set()
        for s in allowed:
            if s in seen:
                continue
            comp = []
            dq = [s]
            seen.add(s)
            while dq:
                x = dq.pop()
                comp.append(x)
                for y in neighbors[x]:
                    if y in allowed_set and y not in seen:
                        seen.add(y)
                        dq.append(y)
            comps.append(comp)
        return comps

    def whites_connected_possible(state):
        req = [i for i, v in enumerate(state) if v == WHITE]
        if not req:
            return True
        allowed = set(i for i, v in enumerate(state) if v != BLACK)
        start = req[0]
        dq = [start]
        seen = {start}
        while dq:
            x = dq.pop()
            for y in neighbors[x]:
                if y in allowed and y not in seen:
                    seen.add(y)
                    dq.append(y)
        return all(i in seen for i in req)

    def final_white_connected(state):
        whites = [i for i, v in enumerate(state) if v == WHITE]
        if not whites:
            return True
        start = whites[0]
        dq = [start]
        seen = {start}
        while dq:
            x = dq.pop()
            for y in neighbors[x]:
                if state[y] == WHITE and y not in seen:
                    seen.add(y)
                    dq.append(y)
        return len(seen) == len(whites)

    def assign(state, i, value, queue):
        cur = state[i]
        if cur == value:
            return True
        if cur != UNKNOWN and cur != value:
            return False
        state[i] = value
        queue.append(i)
        return True

    def basic_propagate(state):
        queue = deque()

        # Seed queue with all fixed clues that may instantly constrain.
        for rid in region_clue:
            for i in region_cells[rid]:
                queue.append(i)

        changed = True
        while changed:
            changed = False

            while queue:
                i = queue.popleft()
                v = state[i]

                if v == BLACK:
                    for nb in neighbors[i]:
                        if not assign(state, nb, WHITE, queue):
                            return None
                        changed = True

                # Region constraints around this cell's region
                r, c = rc_of[i]
                rid = region[r][c]
                if rid in region_clue:
                    clue = region_clue[rid]
                    black, unknown = region_stats(state, rid)
                    if black > clue or black + unknown < clue:
                        return None
                    if black == clue:
                        for j in region_cells[rid]:
                            if state[j] == UNKNOWN:
                                if not assign(state, j, WHITE, queue):
                                    return None
                                changed = True
                    elif black + unknown == clue:
                        for j in region_cells[rid]:
                            if state[j] == UNKNOWN:
                                if not assign(state, j, BLACK, queue):
                                    return None
                                changed = True

                # Triple constraints involving this cell
                for t_idx in triples_of_cell[i]:
                    span = triple_constraints[t_idx]
                    blacks = 0
                    unknowns = []
                    for j in span:
                        if state[j] == BLACK:
                            blacks += 1
                            break
                        elif state[j] == UNKNOWN:
                            unknowns.append(j)
                    if blacks == 0:
                        if not unknowns:
                            return None
                        if len(unknowns) == 1:
                            if not assign(state, unknowns[0], BLACK, queue):
                                return None
                            changed = True

            # Global region checks
            for rid, clue in region_clue.items():
                black, unknown = region_stats(state, rid)
                if black > clue or black + unknown < clue:
                    return None
                if black == clue:
                    for j in region_cells[rid]:
                        if state[j] == UNKNOWN:
                            state[j] = WHITE
                            queue.append(j)
                            changed = True
                elif black + unknown == clue:
                    for j in region_cells[rid]:
                        if state[j] == UNKNOWN:
                            state[j] = BLACK
                            queue.append(j)
                            changed = True

            # Global triple checks
            for span in triple_constraints:
                any_black = False
                unknowns = []
                for j in span:
                    if state[j] == BLACK:
                        any_black = True
                        break
                    if state[j] == UNKNOWN:
                        unknowns.append(j)
                if not any_black:
                    if not unknowns:
                        return None
                    if len(unknowns) == 1:
                        state[unknowns[0]] = BLACK
                        queue.append(unknowns[0])
                        changed = True

            # White connectivity feasibility
            if not whites_connected_possible(state):
                return None

            # If there are required whites, any possible-white component not touching them
            # can still all become black, so no direct forcing here.

            # Forced whites by cut test: if making a cell black disconnects current required whites,
            # then that cell must be white.
            req = [i for i, v in enumerate(state) if v == WHITE]
            if len(req) >= 2:
                for i, v in enumerate(state):
                    if v != UNKNOWN:
                        continue
                    test = clone_state(state)
                    test[i] = BLACK
                    if not whites_connected_possible(test):
                        state[i] = WHITE
                        queue.append(i)
                        changed = True

        return state

    def check_complete(state):
        if any(v == UNKNOWN for v in state):
            return False
        for rid, clue in region_clue.items():
            if sum(1 for i in region_cells[rid] if state[i] == BLACK) != clue:
                return False
        for i, v in enumerate(state):
            if v == BLACK:
                for nb in neighbors[i]:
                    if state[nb] == BLACK:
                        return False
        for span in triple_constraints:
            if all(state[j] != BLACK for j in span):
                return False
        if not final_white_connected(state):
            return False
        return True

    def try_value(state, i, value):
        st = clone_state(state)
        st[i] = value
        return basic_propagate(st)

    def singleton_lookahead(state):
        changed = True
        while changed:
            changed = False
            unknowns = [i for i, v in enumerate(state) if v == UNKNOWN]
            if not unknowns:
                return state
            for i in unknowns:
                b = try_value(state, i, BLACK)
                w = try_value(state, i, WHITE)
                if b is None and w is None:
                    return None
                if b is None and state[i] == UNKNOWN:
                    state[i] = WHITE
                    state = basic_propagate(state)
                    if state is None:
                        return None
                    changed = True
                    break
                if w is None and state[i] == UNKNOWN:
                    state[i] = BLACK
                    state = basic_propagate(state)
                    if state is None:
                        return None
                    changed = True
                    break
        return state

    def score_cell(state, i):
        r, c = rc_of[i]
        rid = region[r][c]
        score = 0
        if rid in region_clue:
            clue = region_clue[rid]
            black, unknown = region_stats(state, rid)
            need = clue - black
            size = unknown
            score += 20 - abs(size - 2 * need)
        score += 3 * len(triples_of_cell[i])
        score += sum(1 for nb in neighbors[i] if state[nb] == BLACK) * 5
        score += sum(1 for nb in neighbors[i] if state[nb] == UNKNOWN)
        return score

    def branch_order(state, i):
        r, c = rc_of[i]
        rid = region[r][c]
        prefer_black = False
        if rid in region_clue:
            clue = region_clue[rid]
            black, unknown = region_stats(state, rid)
            need = clue - black
            if need > 0 and unknown > 0 and need * 2 >= unknown:
                prefer_black = True
        for t_idx in triples_of_cell[i]:
            span = triple_constraints[t_idx]
            if all(state[j] != BLACK for j in span if j != i):
                prefer_black = True
                break
        return (BLACK, WHITE) if prefer_black else (WHITE, BLACK)

    def search(state):
        state = basic_propagate(state)
        if state is None:
            return None
        state = singleton_lookahead(state)
        if state is None:
            return None
        if check_complete(state):
            return state

        unknowns = [i for i, v in enumerate(state) if v == UNKNOWN]
        if not unknowns:
            return None

        i = max(unknowns, key=lambda x: score_cell(state, x))
        for value in branch_order(state, i):
            nxt = clone_state(state)
            nxt[i] = value
            ans = search(nxt)
            if ans is not None:
                return ans
        return None

    result = search(state0)
    if result is None:
        return "No Solution"

    out = []
    for r in range(n):
        row = []
        for c in range(m):
            v = result[idx_of[(r, c)]]
            row.append('B' if v == BLACK else None)
        out.append(row)
    return out

if __name__ == "__main__":
    print(solve(OBSERVATION))

