# Generalized 1-star Star Battle solver for an N x N grid:
# - exactly 1 star in each row
# - exactly 1 star in each column
# - exactly 1 star in each region
# - stars cannot touch orthogonally or diagonally
#
# The solver is designed around human-like deduction plus tightly-pruned search:
# 1) maintain candidate masks
# 2) repeatedly apply forced placements (hidden singles in rows/cols/regions)
# 3) reject impossible states early
# 4) branch only on the most constrained unit

def solve(observation):
    data = observation['data']
    n = len(data)
    if n == 0 or any(len(row) != n for row in data):
        return "No Solution"

    # Normalize region labels to compact ids
    region_map = {}
    regions = [[None] * n for _ in range(n)]
    next_id = 0
    for r in range(n):
        for c in range(n):
            label = data[r][c]
            if label not in region_map:
                region_map[label] = next_id
                next_id += 1
            regions[r][c] = region_map[label]

    region_count = next_id
    if region_count != n:
        return "No Solution"

    cell_count = n * n
    all_mask = (1 << cell_count) - 1

    def idx(r, c):
        return r * n + c

    def bit(i):
        return 1 << i

    row_masks = [0] * n
    col_masks = [0] * n
    reg_masks = [0] * n
    cell_region = [0] * cell_count
    rc_of_idx = [None] * cell_count

    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            b = bit(i)
            row_masks[r] |= b
            col_masks[c] |= b
            g = regions[r][c]
            reg_masks[g] |= b
            cell_region[i] = g
            rc_of_idx[i] = (r, c)

    # Neighbor-touch mask for each cell (includes all adjacent cells; self handled separately elsewhere)
    touch_masks = [0] * cell_count
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            m = 0
            for dr in (-1, 0, 1):
                nr = r + dr
                if 0 <= nr < n:
                    for dc in (-1, 0, 1):
                        nc = c + dc
                        if 0 <= nc < n and not (dr == 0 and dc == 0):
                            m |= bit(idx(nr, nc))
            touch_masks[i] = m

    def iter_bits(mask):
        while mask:
            lsb = mask & -mask
            yield lsb.bit_length() - 1
            mask ^= lsb

    def popcount(x):
        return x.bit_count()

    # State:
    # forbidden: cells that cannot contain a star
    # used_rows/used_cols/used_regs: units already satisfied by a placed star
    # stars: placed star mask
    def place(stars, forbidden, used_rows, used_cols, used_regs, i):
        r, c = rc_of_idx[i]
        g = cell_region[i]
        b = bit(i)

        if forbidden & b:
            return None
        if (used_rows >> r) & 1:
            return None
        if (used_cols >> c) & 1:
            return None
        if (used_regs >> g) & 1:
            return None

        stars |= b
        used_rows |= 1 << r
        used_cols |= 1 << c
        used_regs |= 1 << g

        # Once a star is placed, all cells in same row/col/region and all touching cells are forbidden.
        forbidden |= row_masks[r] | col_masks[c] | reg_masks[g] | touch_masks[i] | b

        return stars, forbidden, used_rows, used_cols, used_regs

    def unit_candidates(mask, used_flag, unit_masks):
        # Returns list of candidate masks, one per unit.
        out = [0] * len(unit_masks)
        for u, um in enumerate(unit_masks):
            if (used_flag >> u) & 1:
                out[u] = 0
            else:
                out[u] = um & mask
        return out

    def propagate(stars, forbidden, used_rows, used_cols, used_regs):
        while True:
            changed = False
            available = all_mask & ~forbidden

            # Fast impossibility checks: every unsatisfied row/col/region must have at least one candidate.
            row_cands = unit_candidates(available, used_rows, row_masks)
            col_cands = unit_candidates(available, used_cols, col_masks)
            reg_cands = unit_candidates(available, used_regs, reg_masks)

            for r in range(n):
                if ((used_rows >> r) & 1) == 0 and row_cands[r] == 0:
                    return None
            for c in range(n):
                if ((used_cols >> c) & 1) == 0 and col_cands[c] == 0:
                    return None
            for g in range(n):
                if ((used_regs >> g) & 1) == 0 and reg_cands[g] == 0:
                    return None

            # Forced placements: hidden singles in any unit.
            forced = []

            for r in range(n):
                m = row_cands[r]
                if m and (m & (m - 1)) == 0:
                    forced.append(m.bit_length() - 1)

            for c in range(n):
                m = col_cands[c]
                if m and (m & (m - 1)) == 0:
                    forced.append(m.bit_length() - 1)

            for g in range(n):
                m = reg_cands[g]
                if m and (m & (m - 1)) == 0:
                    forced.append(m.bit_length() - 1)

            if forced:
                # Deduplicate while preserving deterministic order.
                seen = set()
                ordered_forced = []
                for i in forced:
                    if i not in seen:
                        seen.add(i)
                        ordered_forced.append(i)

                for i in ordered_forced:
                    state = place(stars, forbidden, used_rows, used_cols, used_regs, i)
                    if state is None:
                        return None
                    stars, forbidden, used_rows, used_cols, used_regs = state
                    changed = True

            # Global count consistency.
            placed = popcount(stars)
            remaining_rows = n - popcount(used_rows)
            remaining_cols = n - popcount(used_cols)
            remaining_regs = n - popcount(used_regs)
            if not (remaining_rows == remaining_cols == remaining_regs == n - placed):
                return None

            # Enough available cells must remain to place the rest.
            if popcount(available) < (n - placed):
                return None

            if not changed:
                return stars, forbidden, used_rows, used_cols, used_regs

    def choose_branch_unit(stars, forbidden, used_rows, used_cols, used_regs):
        available = all_mask & ~forbidden
        best_kind = None
        best_unit = None
        best_mask = 0
        best_size = 10**9

        # Select the most constrained unsatisfied row/col/region.
        for r in range(n):
            if ((used_rows >> r) & 1) == 0:
                m = row_masks[r] & available
                s = popcount(m)
                if 1 < s < best_size:
                    best_kind, best_unit, best_mask, best_size = 'row', r, m, s

        for c in range(n):
            if ((used_cols >> c) & 1) == 0:
                m = col_masks[c] & available
                s = popcount(m)
                if 1 < s < best_size:
                    best_kind, best_unit, best_mask, best_size = 'col', c, m, s

        for g in range(n):
            if ((used_regs >> g) & 1) == 0:
                m = reg_masks[g] & available
                s = popcount(m)
                if 1 < s < best_size:
                    best_kind, best_unit, best_mask, best_size = 'reg', g, m, s

        return best_kind, best_unit, best_mask

    def candidate_order(mask):
        # Prefer candidates that constrain the board the most.
        scored = []
        for i in iter_bits(mask):
            r, c = rc_of_idx[i]
            g = cell_region[i]
            score = popcount(row_masks[r] | col_masks[c] | reg_masks[g] | touch_masks[i] | bit(i))
            scored.append((-score, i))
        scored.sort()
        return [i for _, i in scored]

    def dfs(stars, forbidden, used_rows, used_cols, used_regs):
        state = propagate(stars, forbidden, used_rows, used_cols, used_regs)
        if state is None:
            return None
        stars, forbidden, used_rows, used_cols, used_regs = state

        if popcount(stars) == n:
            if used_rows == (1 << n) - 1 and used_cols == (1 << n) - 1 and used_regs == (1 << n) - 1:
                return stars
            return None

        kind, unit, mask = choose_branch_unit(stars, forbidden, used_rows, used_cols, used_regs)
        if kind is None or mask == 0:
            return None

        for i in candidate_order(mask):
            next_state = place(stars, forbidden, used_rows, used_cols, used_regs, i)
            if next_state is None:
                continue
            result = dfs(*next_state)
            if result is not None:
                return result
        return None

    result = dfs(0, 0, 0, 0, 0)
    if result is None:
        return "No Solution"

    answer = [[None for _ in range(n)] for _ in range(n)]
    for i in iter_bits(result):
        r, c = rc_of_idx[i]
        answer[r][c] = 'S'
    return repr(answer)


if __name__ == "__main__":
    print(solve(OBSERVATION))

