from collections import defaultdict, deque

def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0
    cells = [(r, c) for r in range(n) for c in range(m)]
    cell_index = {rc: i for i, rc in enumerate(cells)}

    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[grid[r][c]].append((r, c))
    region_ids = sorted(regions)
    region_pos = {rid: i for i, rid in enumerate(region_ids)}
    cell_region = {cell_index[(r, c)]: region_pos[grid[r][c]] for r, c in cells}

    def neighbors4(r, c):
        if r > 0:
            yield (r - 1, c)
        if r + 1 < n:
            yield (r + 1, c)
        if c > 0:
            yield (r, c - 1)
        if c + 1 < m:
            yield (r, c + 1)

    # All possible domino placements.
    placements = []
    placement_cells = []
    placement_regions = []
    cell_to_placements = defaultdict(list)

    for r in range(n):
        for c in range(m):
            if c + 1 < m:
                a = cell_index[(r, c)]
                b = cell_index[(r, c + 1)]
                pid = len(placements)
                placements.append(((r, c), (r, c + 1)))
                placement_cells.append((a, b))
                rs = tuple(sorted(set([cell_region[a], cell_region[b]])))
                placement_regions.append(rs)
                cell_to_placements[a].append(pid)
                cell_to_placements[b].append(pid)
            if r + 1 < n:
                a = cell_index[(r, c)]
                b = cell_index[(r + 1, c)]
                pid = len(placements)
                placements.append(((r, c), (r + 1, c)))
                placement_cells.append((a, b))
                rs = tuple(sorted(set([cell_region[a], cell_region[b]])))
                placement_regions.append(rs)
                cell_to_placements[a].append(pid)
                cell_to_placements[b].append(pid)

    P = len(placements)
    R = len(region_ids)

    # Incompatibility graph: two dominoes cannot overlap or touch orthogonally.
    cell_neighbors = [set() for _ in range(n * m)]
    for r, c in cells:
        i = cell_index[(r, c)]
        for nr, nc in neighbors4(r, c):
            cell_neighbors[i].add(cell_index[(nr, nc)])

    incompatible = [set() for _ in range(P)]
    covered_and_adj = []
    for pid, (a, b) in enumerate(placement_cells):
        s = {a, b}
        s |= cell_neighbors[a]
        s |= cell_neighbors[b]
        covered_and_adj.append(s)

    for i in range(P):
        ai, bi = placement_cells[i]
        ci = {ai, bi}
        adj_i = covered_and_adj[i]
        for j in range(i + 1, P):
            aj, bj = placement_cells[j]
            cj = {aj, bj}
            if ci & cj or cj & adj_i or ci & covered_and_adj[j]:
                incompatible[i].add(j)
                incompatible[j].add(i)

    # For each region, placements that touch it.
    region_touching = [set() for _ in range(R)]
    placement_region_contrib = [defaultdict(int) for _ in range(P)]
    for pid, (a, b) in enumerate(placement_cells):
        ra = cell_region[a]
        rb = cell_region[b]
        placement_region_contrib[pid][ra] += 1
        placement_region_contrib[pid][rb] += 1
        region_touching[ra].add(pid)
        region_touching[rb].add(pid)

    # Human-like local patterns for each region:
    # A region must see exactly 2 shaded cells, so the incident selected placements
    # are either one domino contributing 2 cells, or two compatible dominoes contributing 1 each.
    region_patterns = []
    region_pattern_sets = []
    for rix in range(R):
        pats = []
        touching = sorted(region_touching[rix])
        # Single-placement patterns.
        for p in touching:
            if placement_region_contrib[p].get(rix, 0) == 2:
                pats.append((p,))
        # Two-placement patterns.
        one_contrib = [p for p in touching if placement_region_contrib[p].get(rix, 0) == 1]
        L = len(one_contrib)
        for i in range(L):
            p = one_contrib[i]
            for j in range(i + 1, L):
                q = one_contrib[j]
                if q not in incompatible[p]:
                    pats.append((p, q))
        # Deduplicate.
        seen = set()
        clean = []
        for pat in pats:
            pat = tuple(sorted(pat))
            if pat not in seen:
                seen.add(pat)
                clean.append(pat)
        region_patterns.append(clean)
        region_pattern_sets.append([set(pat) for pat in clean])

    # Early impossibility.
    for pats in region_patterns:
        if not pats:
            return "No Solution"

    # For quick reverse lookup.
    placement_in_region_patterns = [defaultdict(set) for _ in range(R)]
    for rix in range(R):
        for pix, pat in enumerate(region_patterns[rix]):
            for p in pat:
                placement_in_region_patterns[rix][p].add(pix)

    # State:
    # placement_state[p] = 1 selected, -1 banned, 0 undecided
    # domain[r] = set of pattern indices currently allowed for region r
    initial_state = [0] * P
    initial_domain = [set(range(len(region_patterns[r]))) for r in range(R)]

    def propagate(state, domain):
        q_regions = deque(range(R))
        q_places = deque(range(P))
        in_qr = [True] * R
        in_qp = [True] * P

        def enqueue_region(r):
            if not in_qr[r]:
                in_qr[r] = True
                q_regions.append(r)

        def enqueue_place(p):
            if not in_qp[p]:
                in_qp[p] = True
                q_places.append(p)

        def ban(p):
            if state[p] == -1:
                return True
            if state[p] == 1:
                return False
            state[p] = -1
            enqueue_place(p)
            for r in placement_regions[p]:
                enqueue_region(r)
            return True

        def select(p):
            if state[p] == 1:
                return True
            if state[p] == -1:
                return False
            state[p] = 1
            enqueue_place(p)
            for r in placement_regions[p]:
                enqueue_region(r)
            return True

        while q_regions or q_places:
            while q_places:
                p = q_places.popleft()
                in_qp[p] = False
                if state[p] == 1:
                    for q in incompatible[p]:
                        if not ban(q):
                            return False
                    for r in placement_regions[p]:
                        # Every touched region must choose a pattern containing p.
                        rem = {pix for pix in domain[r] if p in region_pattern_sets[r][pix]}
                        if not rem:
                            return False
                        if rem != domain[r]:
                            domain[r] = rem
                            enqueue_region(r)
                elif state[p] == -1:
                    for r in placement_regions[p]:
                        rem = {pix for pix in domain[r] if p not in region_pattern_sets[r][pix]}
                        if not rem:
                            return False
                        if rem != domain[r]:
                            domain[r] = rem
                            enqueue_region(r)

            while q_regions:
                r = q_regions.popleft()
                in_qr[r] = False
                if not domain[r]:
                    return False

                pats = domain[r]
                touching = region_touching[r]
                if not touching:
                    return False

                # Filter patterns against current placement states.
                rem = set()
                for pix in pats:
                    pat = region_pattern_sets[r][pix]
                    ok = True
                    for p in pat:
                        if state[p] == -1:
                            ok = False
                            break
                    if not ok:
                        continue
                    # Any selected placement touching this region must be in the pattern.
                    for p in touching:
                        if state[p] == 1 and p not in pat:
                            ok = False
                            break
                    if ok:
                        rem.add(pix)
                if not rem:
                    return False
                if rem != pats:
                    domain[r] = rem
                    pats = rem

                # Intersection/union reasoning.
                pat_sets = [region_pattern_sets[r][pix] for pix in pats]
                inter = set(pat_sets[0]).copy()
                union = set()
                for s in pat_sets:
                    inter &= s
                    union |= s

                # Placements that every remaining pattern uses are forced.
                for p in inter:
                    if not select(p):
                        return False

                # Placements touching this region but absent from all patterns are impossible.
                for p in touching:
                    if p not in union:
                        if not ban(p):
                            return False

                # If domain is a singleton, that region is fully determined.
                if len(pats) == 1:
                    only = next(iter(pats))
                    pat = region_pattern_sets[r][only]
                    for p in pat:
                        if not select(p):
                            return False
                    for p in touching:
                        if p not in pat:
                            if not ban(p):
                                return False

        # Final consistency: every placement selected must be representable in all touched regions.
        for p in range(P):
            if state[p] == 1:
                for r in placement_regions[p]:
                    if not any(p in region_pattern_sets[r][pix] for pix in domain[r]):
                        return False
        return True

    def choose_branch(state, domain):
        # First prefer regions with smallest domain > 1.
        best_r = None
        best_size = 10**9
        for r in range(R):
            sz = len(domain[r])
            if 1 < sz < best_size:
                best_size = sz
                best_r = r
        if best_r is not None:
            # Order patterns by how many placements they force / ban locally.
            options = list(domain[best_r])
            touching = region_touching[best_r]
            def score(pix):
                pat = region_pattern_sets[best_r][pix]
                forced_select = sum(1 for p in pat if state[p] == 0)
                forced_ban = sum(1 for p in touching if p not in pat and state[p] == 0)
                return -(forced_select + forced_ban)
            options.sort(key=score)
            return ("region", best_r, options)

        # Otherwise branch on an undecided placement with high impact.
        best_p = None
        best_deg = -1
        for p in range(P):
            if state[p] == 0:
                deg = len(incompatible[p]) + 4 * len(placement_regions[p])
                if deg > best_deg:
                    best_deg = deg
                    best_p = p
        if best_p is not None:
            return ("placement", best_p, [1, -1])

        return None

    def solved(state, domain):
        return all(len(domain[r]) == 1 for r in range(R))

    def dfs(state, domain):
        if not propagate(state, domain):
            return None
        if solved(state, domain):
            # Materialize forced choices from singleton domains.
            final_selected = set()
            for r in range(R):
                pix = next(iter(domain[r]))
                final_selected |= region_pattern_sets[r][pix]
            # Validate pairwise compatibility.
            for p in final_selected:
                for q in final_selected:
                    if p != q and q in incompatible[p]:
                        return None
            # Validate exact 2 per region.
            count = [0] * R
            shaded_cells = set()
            for p in final_selected:
                a, b = placement_cells[p]
                shaded_cells.add(a)
                shaded_cells.add(b)
            for c in shaded_cells:
                count[cell_region[c]] += 1
            if any(v != 2 for v in count):
                return None
            ans = [[None for _ in range(m)] for _ in range(n)]
            for idx in shaded_cells:
                rr, cc = cells[idx]
                ans[rr][cc] = 'S'
            return ans

        branch = choose_branch(state, domain)
        if branch is None:
            return None

        kind, obj, options = branch
        if kind == "region":
            r = obj
            for pix in options:
                ns = state[:]
                nd = [d.copy() for d in domain]
                nd[r] = {pix}
                res = dfs(ns, nd)
                if res is not None:
                    return res
        else:
            p = obj
            for choice in options:
                ns = state[:]
                nd = [d.copy() for d in domain]
                ns[p] = choice
                res = dfs(ns, nd)
                if res is not None:
                    return res
        return None

    res = dfs(initial_state, initial_domain)
    return "No Solution" if res is None else str(res)

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[3, None, None, 3, None], [None, None, 1, None, None], [None, None, None, None, None], [None, 3, None, None, None], [None, None, None, None, None]]}

from collections import deque, defaultdict

# General Nurikabe solver using:
# - enumeration of all connected island placements for each clue
# - aggressive domain filtering and overlap propagation
# - final black-region validation (connected + no 2x2)
# This mirrors human solving at the island-shape / forced-cell level rather than blind cell-by-cell brute force.


def solve(observation):
    data = observation["data"]
    h = len(data)
    w = len(data[0]) if h else 0

    clues = []
    clue_pos_to_id = {}
    for r in range(h):
        for c in range(w):
            if data[r][c] is not None:
                clue_pos_to_id[(r, c)] = len(clues)
                clues.append((r, c, data[r][c]))

    if not clues:
        return "No Solution"

    all_cells = [(r, c) for r in range(h) for c in range(w)]
    all_cell_set = set(all_cells)
    clue_cells = set((r, c) for r, c, _ in clues)

    nbrs = {}
    for r in range(h):
        for c in range(w):
            x = []
            if r > 0:
                x.append((r - 1, c))
            if r + 1 < h:
                x.append((r + 1, c))
            if c > 0:
                x.append((r, c - 1))
            if c + 1 < w:
                x.append((r, c + 1))
            nbrs[(r, c)] = tuple(x)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # Allowed cells for each clue: cannot include other clues; distance bound helps a lot.
    allowed_by_clue = []
    for i, (rr, cc, size) in enumerate(clues):
        root = (rr, cc)
        allowed = set()
        for cell in all_cells:
            if cell != root and cell in clue_cells:
                continue
            if manhattan(root, cell) <= size - 1:
                allowed.add(cell)
        allowed_by_clue.append(allowed)

    def connected_component_size_within(start, allowed):
        q = [start]
        seen = {start}
        for x in q:
            for y in nbrs[x]:
                if y in allowed and y not in seen:
                    seen.add(y)
                    q.append(y)
        return len(seen)

    # Enumerate all connected placements for each clue.
    def enumerate_shapes(root, size, allowed):
        if size == 1:
            return [frozenset([root])]

        allowed = set(allowed)
        if root not in allowed:
            return []

        if connected_component_size_within(root, allowed) < size:
            return []

        results = set()
        seen_states = set()

        def rec(curr):
            curr_fs = frozenset(curr)
            if curr_fs in seen_states:
                return
            seen_states.add(curr_fs)

            if len(curr) == size:
                results.add(curr_fs)
                return

            # Frontier cells adjacent to current component.
            frontier = set()
            for cell in curr:
                for nb in nbrs[cell]:
                    if nb in allowed and nb not in curr:
                        frontier.add(nb)

            # Simple reachability prune: enough cells remain in current reachable envelope.
            reachable = set(curr)
            dq = deque(curr)
            while dq:
                x = dq.popleft()
                for y in nbrs[x]:
                    if y in allowed and y not in reachable:
                        reachable.add(y)
                        dq.append(y)
            if len(reachable) < size:
                return

            for add in sorted(frontier):
                new_curr = set(curr)
                new_curr.add(add)
                rec(new_curr)

        rec({root})
        return sorted(results, key=lambda s: (len(s), tuple(sorted(s))))

    placements = []
    cell_to_placements = defaultdict(list)  # (cell) -> list of (clue_id, placement_idx)
    for i, (r, c, size) in enumerate(clues):
        root = (r, c)
        plist = enumerate_shapes(root, size, allowed_by_clue[i])
        if not plist:
            return "No Solution"
        placements.append(plist)
        for pi, sh in enumerate(plist):
            for cell in sh:
                cell_to_placements[cell].append((i, pi))

    # Precompute overlap conflicts.
    conflict = []
    for i in range(len(clues)):
        row = []
        for pi, shp in enumerate(placements[i]):
            by_other = {}
            for j in range(len(clues)):
                if i == j:
                    continue
                bad = set()
                for pj, shp2 in enumerate(placements[j]):
                    if shp & shp2:
                        bad.add(pj)
                by_other[j] = bad
            row.append(by_other)
        conflict.append(row)

    def domains_copy(domains):
        return [set(x) for x in domains]

    def get_common_cells(domain_set, clue_id):
        plist = placements[clue_id]
        it = iter(domain_set)
        first = next(it, None)
        if first is None:
            return None
        common = set(plist[first])
        for pi in it:
            common &= plist[pi]
        return common

    def possible_owners_for_cell(domains, cell):
        owners = set()
        for cid, pi in cell_to_placements.get(cell, ()):
            if pi in domains[cid]:
                owners.add(cid)
        return owners

    def forced_data(domains):
        forced_white_owner = {}
        forced_black = set()
        maybe_white = set()

        for cid in range(len(clues)):
            common = get_common_cells(domains[cid], cid)
            if common is None:
                return None, None, None
            for cell in common:
                forced_white_owner[cell] = cid

        for cell in all_cells:
            owners = possible_owners_for_cell(domains, cell)
            if owners:
                maybe_white.add(cell)
            else:
                forced_black.add(cell)

        return forced_white_owner, forced_black, maybe_white

    def no_full_black_2x2(forced_black):
        for r in range(h - 1):
            for c in range(w - 1):
                block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
                if block <= forced_black:
                    return False
        return True

    def black_connectivity_possible(forced_white_owner, forced_black):
        # Cells not forced white are candidates for black.
        black_candidates = all_cell_set - set(forced_white_owner.keys())
        if not forced_black:
            return True
        start = next(iter(forced_black))
        seen = {start}
        dq = deque([start])
        while dq:
            x = dq.popleft()
            for y in nbrs[x]:
                if y in black_candidates and y not in seen:
                    seen.add(y)
                    dq.append(y)
        return forced_black <= seen

    def propagate(domains):
        domains = domains_copy(domains)

        changed = True
        while changed:
            changed = False

            # Empty-domain check.
            for cid in range(len(clues)):
                if not domains[cid]:
                    return None

            forced_white_owner, forced_black, maybe_white = forced_data(domains)
            if forced_white_owner is None:
                return None

            # Clue cells must stay in their own clue's mandatory set across all placements.
            for cid, (r, c, _) in enumerate(clues):
                if forced_white_owner.get((r, c), cid) != cid:
                    return None

            # Forced white ownership: a cell present in all placements of clue A cannot appear in any placement of other clues.
            for cell, owner in list(forced_white_owner.items()):
                for other in range(len(clues)):
                    if other == owner:
                        continue
                    bad = {pi for pi in domains[other] if cell in placements[other][pi]}
                    if bad:
                        domains[other] -= bad
                        changed = True
                        if not domains[other]:
                            return None

            # If a cell can be white only for one clue, and every remaining placement of that clue containing this cell
            # implies it, do a direct filtering. This is a useful human-style uniqueness squeeze.
            for cell in all_cells:
                owners = possible_owners_for_cell(domains, cell)
                if len(owners) == 1 and cell not in forced_black:
                    owner = next(iter(owners))
                    keep = {pi for pi in domains[owner] if cell in placements[owner][pi]}
                    if keep and keep != domains[owner]:
                        domains[owner] = keep
                        changed = True

            # Pairwise overlap elimination.
            for i in range(len(clues)):
                remove_i = set()
                for pi in domains[i]:
                    ok = True
                    for j in range(len(clues)):
                        if i == j:
                            continue
                        # Need some non-conflicting placement in j.
                        bad = conflict[i][pi][j]
                        if domains[j] <= bad:
                            ok = False
                            break
                    if not ok:
                        remove_i.add(pi)
                if remove_i:
                    domains[i] -= remove_i
                    changed = True
                    if not domains[i]:
                        return None

            forced_white_owner, forced_black, maybe_white = forced_data(domains)
            if forced_white_owner is None:
                return None

            if not no_full_black_2x2(forced_black):
                return None

            if not black_connectivity_possible(forced_white_owner, forced_black):
                return None

            # Local 2x2 prune:
            # if a placement would make a 2x2 all-black regardless of unresolved choices, remove it.
            for cid in range(len(clues)):
                remove = set()
                for pi in domains[cid]:
                    shp = placements[cid][pi]
                    # Temporary mandatory white includes this chosen shape plus other forced whites.
                    temp_white = set(forced_white_owner.keys()) | set(shp)
                    bad = False
                    for r in range(h - 1):
                        for c in range(w - 1):
                            block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
                            if block.isdisjoint(temp_white):
                                # Block could still be rescued by another unresolved clue placement using one of its cells.
                                rescue = False
                                for cell in block:
                                    for ocid, opi in cell_to_placements.get(cell, ()):
                                        if ocid == cid:
                                            continue
                                        if opi in domains[ocid]:
                                            rescue = True
                                            break
                                    if rescue:
                                        break
                                if not rescue:
                                    bad = True
                                    break
                        if bad:
                            break
                    if bad:
                        remove.add(pi)
                if remove:
                    domains[cid] -= remove
                    changed = True
                    if not domains[cid]:
                        return None

        return domains

    def final_check(domains):
        if any(len(d) != 1 for d in domains):
            return None

        chosen = []
        white = set()
        for cid in range(len(clues)):
            pi = next(iter(domains[cid]))
            shp = placements[cid][pi]
            chosen.append(shp)
            if white & shp:
                return None
            white |= shp

        # Every white island has exactly one clue by construction.
        # Check black 2x2.
        black = all_cell_set - white
        for r in range(h - 1):
            for c in range(w - 1):
                block = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
                if block <= black:
                    return None

        # Check black connectivity.
        if black:
            start = next(iter(black))
            seen = {start}
            dq = deque([start])
            while dq:
                x = dq.popleft()
                for y in nbrs[x]:
                    if y in black and y not in seen:
                        seen.add(y)
                        dq.append(y)
            if seen != black:
                return None

        grid = [[None for _ in range(w)] for _ in range(h)]
        for r, c in black:
            grid[r][c] = 'B'
        return grid

    def choose_branch_clue(domains):
        # Most constrained clue first, then shapes with largest forced overlap.
        best = None
        best_key = None
        for cid, d in enumerate(domains):
            if len(d) > 1:
                common = get_common_cells(d, cid)
                common_sz = len(common) if common is not None else 0
                key = (len(d), -common_sz)
                if best_key is None or key < best_key:
                    best_key = key
                    best = cid
        return best

    def placement_score(cid, pi, domains):
        shp = placements[cid][pi]
        score = 0
        for cell in shp:
            owners = possible_owners_for_cell(domains, cell)
            if len(owners) == 1:
                score += 3
            elif len(owners) == 2:
                score += 1
        # Prefer placements that constrain others by overlap.
        for j in range(len(clues)):
            if j == cid:
                continue
            score += len(conflict[cid][pi][j])
        return -score

    def search(domains, depth=0):
        domains = propagate(domains)
        if domains is None:
            return None

        res = final_check(domains)
        if res is not None:
            return res

        cid = choose_branch_clue(domains)
        if cid is None:
            return None

        options = sorted(domains[cid], key=lambda pi: placement_score(cid, pi, domains))
        for pi in options:
            new_domains = domains_copy(domains)
            new_domains[cid] = {pi}
            ans = search(new_domains, depth + 1)
            if ans is not None:
                return ans
        return None

    initial_domains = [set(range(len(placements[cid]))) for cid in range(len(clues))]
    result = search(initial_domains)
    return repr(result) if result is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [['B6', None, None, 'B7', None, None, None, None, 'B2', 'B2', None], [None, None, None, None, None, None, None, None, None, None, 'W2'], [None, None, None, None, 'W4', None, 'W3', None, 'B7', None, None], ['W5', 'W2', None, None, None, None, None, None, None, 'W2', None], [None, None, None, None, None, None, None, None, None, None, None], [None, None, None, None, None, None, None, None, None, 'B2', None], [None, 'B2', None, None, 'B3', 'B3', None, 'B5', None, None, None], [None, None, None, None, None, None, None, None, None, None, None], [None, 'B2', 'B4', None, None, None, 'B3', None, 'B7', None, None], ['W2', None, None, 'B3', None, None, None, None, None, 'B2', 'W2'], [None, None, 'B2', None, None, None, 'B2', 'B2', None, None, None]]}

from copy import deepcopy

DIRS = {
    'U': (-1, 0),
    'D': (1, 0),
    'L': (0, -1),
    'R': (0, 1),
}
OPP = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}
PERP = {
    'U': ('L', 'R'),
    'D': ('L', 'R'),
    'L': ('U', 'D'),
    'R': ('U', 'D'),
}

SHAPES = {
    'E': frozenset(),
    'H': frozenset({'L', 'R'}),
    'V': frozenset({'U', 'D'}),
    'UR': frozenset({'U', 'R'}),
    'UL': frozenset({'U', 'L'}),
    'DR': frozenset({'D', 'R'}),
    'DL': frozenset({'D', 'L'}),
}
TURN_SHAPES = {'UR', 'UL', 'DR', 'DL'}

def addp(p, d):
    dr, dc = DIRS[d]
    return (p[0] + dr, p[1] + dc)

def inb(n, p):
    return 0 <= p[0] <= n and 0 <= p[1] <= n

def edge_key(a, b):
    return (a, b) if a < b else (b, a)

def shape_name_from_dirs(ds):
    ds = frozenset(ds)
    for k, v in SHAPES.items():
        if v == ds:
            return k
    return None

def build_edges(n):
    edges = {}
    incid = {(r, c): {} for r in range(n + 1) for c in range(n + 1)}
    for r in range(n + 1):
        for c in range(n + 1):
            p = (r, c)
            for d in ('D', 'R'):
                q = addp(p, d)
                if inb(n, q):
                    e = edge_key(p, q)
                    edges[e] = -1
                    incid[p][d] = e
                    incid[q][OPP[d]] = e
    return edges, incid

def legal_shapes_for_vertex(n, p, clue):
    valid_dirs = {d for d in DIRS if inb(n, addp(p, d))}
    names = set()
    for name, ds in SHAPES.items():
        if ds <= valid_dirs:
            names.add(name)
    if clue is None:
        return names
    t = clue[0]
    if t == 'W':
        return {x for x in names if x in ('H', 'V')}
    return {x for x in names if x in TURN_SHAPES}

def ray_candidate(n, clue_pos, d, length):
    # Produces restrictions for one outgoing straight segment from clue.
    # The endpoint must be a turn vertex.
    cur = clue_pos
    verts = {}
    edges = {}
    for step in range(1, length + 1):
        nxt = addp(cur, d)
        if not inb(n, nxt):
            return None
        e = edge_key(cur, nxt)
        edges[e] = 1
        if step < length:
            # Interior must continue straight on this axis.
            exact = 'H' if d in ('L', 'R') else 'V'
            verts[nxt] = {exact}
        else:
            # Endpoint must turn, and must not continue further in same direction.
            req = OPP[d]
            possible = []
            for pd in PERP[d]:
                nm = shape_name_from_dirs({req, pd})
                if nm is not None:
                    possible.append(nm)
            verts[nxt] = set(possible)
            fwd = addp(nxt, d)
            if inb(n, fwd):
                edges[edge_key(nxt, fwd)] = 0
        cur = nxt
    return verts, edges

def merge_restrictions(basev, basee, addv, adde):
    v = {k: set(val) for k, val in basev.items()}
    e = dict(basee)
    for p, s in addv.items():
        if p in v:
            inter = v[p] & set(s)
            if not inter:
                return None
            v[p] = inter
        else:
            v[p] = set(s)
    for ed, val in adde.items():
        if ed in e and e[ed] != val:
            return None
        e[ed] = val
    return v, e

def generate_clue_candidates(n, pos, clue):
    t = clue[0]
    k = int(clue[1:])
    cands = []
    if t == 'W':
        orient_pairs = [('L', 'R', 'H'), ('U', 'D', 'V')]
    else:
        orient_pairs = [
            ('U', 'R', 'UR'),
            ('U', 'L', 'UL'),
            ('D', 'R', 'DR'),
            ('D', 'L', 'DL'),
        ]
    for a, b, sh in orient_pairs:
        basev = {pos: {sh}}
        basee = {}
        # clue exact shape implies absent other incident edges
        for d in DIRS:
            q = addp(pos, d)
            if inb(n, q):
                e = edge_key(pos, q)
                basee[e] = 1 if d in SHAPES[sh] else 0
        for la in range(1, k):
            lb = k - la
            ra = ray_candidate(n, pos, a, la)
            rb = ray_candidate(n, pos, b, lb)
            if ra is None or rb is None:
                continue
            merged = merge_restrictions(basev, basee, ra[0], ra[1])
            if merged is None:
                continue
            merged = merge_restrictions(merged[0], merged[1], rb[0], rb[1])
            if merged is None:
                continue
            cands.append({'verts': merged[0], 'edges': merged[1]})
    return cands

def clone_state(state):
    return {
        'edge': dict(state['edge']),
        'allowed': {p: set(v) for p, v in state['allowed'].items()},
        'cands': [list(lst) for lst in state['cands']],
    }

def apply_edge(state, e, val):
    cur = state['edge'][e]
    if cur == val:
        return True
    if cur != -1 and cur != val:
        return False
    state['edge'][e] = val
    return True

def apply_allowed(state, p, allowed_subset):
    newset = state['allowed'][p] & set(allowed_subset)
    if not newset:
        return False
    if newset != state['allowed'][p]:
        state['allowed'][p] = newset
    return True

def candidate_compatible(state, cand):
    for p, aset in cand['verts'].items():
        if not (state['allowed'][p] & aset):
            return False
    for e, val in cand['edges'].items():
        cur = state['edge'][e]
        if cur != -1 and cur != val:
            return False
    return True

def shape_consistent_with_edges(shape, incid, edge_state):
    ds = SHAPES[shape]
    for d, e in incid.items():
        val = edge_state[e]
        if val == -1:
            continue
        if (d in ds) != (val == 1):
            return False
    return True

def propagate_vertex(state, p, incid):
    allowed = {s for s in state['allowed'][p] if shape_consistent_with_edges(s, incid[p], state['edge'])}
    if not allowed:
        return False, False
    changed = allowed != state['allowed'][p]
    state['allowed'][p] = allowed

    # force edges by all remaining shapes
    for d, e in incid[p].items():
        all_have = all(d in SHAPES[s] for s in allowed)
        none_have = all(d not in SHAPES[s] for s in allowed)
        if all_have:
            if not apply_edge(state, e, 1):
                return False, False
            changed = True
        elif none_have:
            if not apply_edge(state, e, 0):
                return False, False
            changed = True

    # degree counts from edge state
    present = 0
    unk = 0
    for d, e in incid[p].items():
        v = state['edge'][e]
        if v == 1:
            present += 1
        elif v == -1:
            unk += 1
    if present > 2:
        return False, False
    # Non-empty shapes require degree 2; empty requires 0.
    if all(s == 'E' for s in allowed):
        for d, e in incid[p].items():
            if not apply_edge(state, e, 0):
                return False, False
            changed = True
    elif all(s != 'E' for s in allowed):
        if present + unk < 2:
            return False, False
        if present == 2:
            for d, e in incid[p].items():
                if state['edge'][e] == -1:
                    if not apply_edge(state, e, 0):
                        return False, False
                    changed = True
        elif present + unk == 2:
            for d, e in incid[p].items():
                if state['edge'][e] == -1:
                    if not apply_edge(state, e, 1):
                        return False, False
                    changed = True
    return True, changed

def prune_candidates_and_infer(state, clues):
    changed = False
    for i, pos in enumerate(clues):
        old = state['cands'][i]
        new = [c for c in old if candidate_compatible(state, c)]
        if not new:
            return False, False
        if len(new) != len(old):
            state['cands'][i] = new
            changed = True

        # Infer common restrictions across all remaining candidates
        common_v = {}
        common_e = {}
        verts_union_keys = set()
        edges_union_keys = set()
        for c in new:
            verts_union_keys |= set(c['verts'])
            edges_union_keys |= set(c['edges'])
        for p in verts_union_keys:
            inter = None
            for c in new:
                if p in c['verts']:
                    s = set(c['verts'][p])
                else:
                    s = set(state['allowed'][p])
                inter = s if inter is None else (inter & s)
            if inter is not None:
                common_v[p] = inter
        for e in edges_union_keys:
            vals = {c['edges'][e] for c in new if e in c['edges']}
            if len(vals) == 1 and sum(e in c['edges'] for c in new) == len(new):
                common_e[e] = next(iter(vals))

        for p, aset in common_v.items():
            before = set(state['allowed'][p])
            if not apply_allowed(state, p, aset):
                return False, False
            if state['allowed'][p] != before:
                changed = True
        for e, v in common_e.items():
            before = state['edge'][e]
            if not apply_edge(state, e, v):
                return False, False
            if state['edge'][e] != before:
                changed = True
    return True, changed

def detect_premature_cycle(state, incid, clue_positions):
    # If any connected component of present edges is a closed cycle but not the full loop, reject.
    adj = {}
    used_vertices = set()
    for e, v in state['edge'].items():
        if v == 1:
            a, b = e
            adj.setdefault(a, []).append(b)
            adj.setdefault(b, []).append(a)
            used_vertices.add(a)
            used_vertices.add(b)
    seen = set()
    for s in list(used_vertices):
        if s in seen:
            continue
        stack = [s]
        comp_v = set()
        comp_e = 0
        all_deg2 = True
        while stack:
            x = stack.pop()
            if x in comp_v:
                continue
            comp_v.add(x)
            seen.add(x)
            deg = len(adj.get(x, []))
            if deg != 2:
                all_deg2 = False
            for y in adj.get(x, []):
                comp_e += 1
                if y not in comp_v:
                    stack.append(y)
        comp_e //= 2
        if all_deg2 and comp_e == len(comp_v):
            # closed cycle component
            unresolved_elsewhere = False
            for pos in clue_positions:
                if pos not in comp_v:
                    unresolved_elsewhere = True
                    break
            if unresolved_elsewhere:
                return True
            # also if there is any undecided present/possible edge outside, this is premature
            for e, v in state['edge'].items():
                if v != 0:
                    if e[0] not in comp_v or e[1] not in comp_v:
                        return True
    return False

def propagate(state, incid, clues):
    while True:
        any_change = False
        ok, ch = prune_candidates_and_infer(state, clues)
        if not ok:
            return False
        any_change |= ch

        for p in state['allowed']:
            ok, ch = propagate_vertex(state, p, incid)
            if not ok:
                return False
            any_change |= ch

        ok, ch = prune_candidates_and_infer(state, clues)
        if not ok:
            return False
        any_change |= ch

        if detect_premature_cycle(state, incid, clues):
            return False

        if not any_change:
            return True

def final_check_and_extract(state, incid, clue_positions):
    # All edges determined and all vertices degree 0 or 2, one cycle containing all used vertices/clues.
    if any(v == -1 for v in state['edge'].values()):
        return None
    present_edges = [e for e, v in state['edge'].items() if v == 1]
    if not present_edges:
        return None

    used = set()
    adj = {}
    for a, b in present_edges:
        adj.setdefault(a, []).append(b)
        adj.setdefault(b, []).append(a)
        used.add(a)
        used.add(b)
    for p in used:
        if len(adj[p]) != 2:
            return None
    for cp in clue_positions:
        if cp not in used:
            return None

    start = min(used)
    path = [start]
    prev = None
    cur = start
    while True:
        nxts = adj[cur]
        nxt = nxts[0] if nxts[0] != prev else nxts[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
        if len(path) > len(present_edges) + 2:
            return None
    if len(path) != len(present_edges) + 1:
        return None
    if set(path[:-1]) != used:
        return None
    return path

def choose_branch(state, clues):
    best = None
    # Prefer clue with fewest candidates > 1
    for i, pos in enumerate(clues):
        m = len(state['cands'][i])
        if 1 < m and (best is None or m < best[0]):
            best = (m, 'clue', i)
    if best is not None:
        return best
    # Else branch on a vertex with fewest shapes > 1
    for p, s in state['allowed'].items():
        m = len(s)
        if 1 < m and (best is None or m < best[0]):
            best = (m, 'vert', p)
    if best is not None:
        return best
    # Else branch on an edge
    for e, v in state['edge'].items():
        if v == -1:
            return (2, 'edge', e)
    return None

def search(state, incid, clues):
    if not propagate(state, incid, clues):
        return None

    path = final_check_and_extract(state, incid, clues)
    if path is not None:
        return path

    br = choose_branch(state, clues)
    if br is None:
        return None

    _, kind, item = br

    if kind == 'clue':
        idx = item
        # Try candidates in order that impose more restrictions first
        cands = sorted(state['cands'][idx], key=lambda c: -(len(c['verts']) + len(c['edges'])))
        for cand in cands:
            ns = clone_state(state)
            ns['cands'][idx] = [cand]
            res = search(ns, incid, clues)
            if res is not None:
                return res
        return None

    if kind == 'vert':
        p = item
        for sh in sorted(state['allowed'][p], key=lambda x: (x == 'E', x)):
            ns = clone_state(state)
            ns['allowed'][p] = {sh}
            res = search(ns, incid, clues)
            if res is not None:
                return res
        return None

    e = item
    for val in (1, 0):
        ns = clone_state(state)
        ns['edge'][e] = val
        res = search(ns, incid, clues)
        if res is not None:
            return res
    return None

def solve(observation):
    data = observation['data']
    n = len(data) - 1
    edges, incid = build_edges(n)

    clues = []
    for r in range(n + 1):
        for c in range(n + 1):
            if data[r][c] is not None:
                clues.append((r, c))

    allowed = {}
    for r in range(n + 1):
        for c in range(n + 1):
            allowed[(r, c)] = legal_shapes_for_vertex(n, (r, c), data[r][c])

    cands = []
    for pos in clues:
        clue = data[pos[0]][pos[1]]
        cc = generate_clue_candidates(n, pos, clue)
        if not cc:
            return "No Solution"
        # Filter immediately by base legal shapes
        fcc = []
        for cand in cc:
            ok = True
            for p, aset in cand['verts'].items():
                if not (allowed[p] & aset):
                    ok = False
                    break
            if ok:
                fcc.append(cand)
        if not fcc:
            return "No Solution"
        cands.append(fcc)

    state = {
        'edge': edges,
        'allowed': allowed,
        'cands': cands,
    }
    ans = search(state, incid, clues)
    return repr(ans) if ans is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, None], [None, 'W', None, None, 'W', None, 'W', None], ['B', None, None, None, None, 'W', 'W', None], [None, None, 'W', None, None, None, 'W', None], [None, None, None, None, None, 'B', None, 'W'], [None, None, 'W', 'W', None, None, None, None], [None, 'W', None, None, None, None, None, None], [None, None, None, None, 'W', None, None, 'B']]}

# Generalized Masyu-on-vertices solver.
# The loop runs along edges between adjacent dots (grid vertices).
# Clues sit on vertices.

NORTH, EAST, SOUTH, WEST = 0, 1, 2, 3
DIRS = (NORTH, EAST, SOUTH, WEST)
DR = (-1, 0, 1, 0)
DC = (0, 1, 0, -1)
OPP = (SOUTH, WEST, NORTH, EAST)

MASK0 = 0
MASK_NS = (1 << NORTH) | (1 << SOUTH)
MASK_EW = (1 << EAST) | (1 << WEST)
MASK_NE = (1 << NORTH) | (1 << EAST)
MASK_NW = (1 << NORTH) | (1 << WEST)
MASK_SE = (1 << SOUTH) | (1 << EAST)
MASK_SW = (1 << SOUTH) | (1 << WEST)

ALL_PATTERNS = (MASK0, MASK_NS, MASK_EW, MASK_NE, MASK_NW, MASK_SE, MASK_SW)
WHITE_PATTERNS = (MASK_NS, MASK_EW)
BLACK_PATTERNS = (MASK_NE, MASK_NW, MASK_SE, MASK_SW)
TURN_PATTERNS = {MASK_NE, MASK_NW, MASK_SE, MASK_SW}
STRAIGHT_PATTERNS = {MASK_NS, MASK_EW}

def bit(mask, d):
    return (mask >> d) & 1

def is_turn(mask):
    return mask in TURN_PATTERNS

def is_straight(mask):
    return mask in STRAIGHT_PATTERNS

def idx_of(r, c, n):
    return r * n + c

def rc_of(i, n):
    return divmod(i, n)

def build_neighbors(n):
    nbrs = [[-1] * 4 for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            i = idx_of(r, c, n)
            for d in DIRS:
                rr, cc = r + DR[d], c + DC[d]
                if 0 <= rr < n and 0 <= cc < n:
                    nbrs[i][d] = idx_of(rr, cc, n)
    return nbrs

def initial_domains(data):
    n = len(data)
    nbrs = build_neighbors(n)
    doms = []
    clues = []
    for r in range(n):
        for c in range(n):
            clue = data[r][c]
            clues.append(clue)
            if clue == 'W':
                domain = set(WHITE_PATTERNS)
            elif clue == 'B':
                domain = set(BLACK_PATTERNS)
            else:
                domain = set(ALL_PATTERNS)
            i = idx_of(r, c, n)
            # Remove patterns using outside edges.
            bad = set()
            for p in domain:
                ok = True
                for d in DIRS:
                    if bit(p, d) and nbrs[i][d] == -1:
                        ok = False
                        break
                if not ok:
                    bad.add(p)
            domain -= bad
            doms.append(domain)
    return doms, clues, nbrs

def has_support(domain, opp_dir, need_include, need_turn=None, need_straight=None):
    for q in domain:
        if bit(q, opp_dir) != need_include:
            continue
        if need_turn is True and not is_turn(q):
            continue
        if need_straight is True and not is_straight(q):
            continue
        return True
    return False

def pattern_feasible(i, p, doms, clues, nbrs):
    clue = clues[i]

    # Basic edge-equality support.
    for d in DIRS:
        u = nbrs[i][d]
        inc = bit(p, d)
        if u == -1:
            if inc:
                return False
            continue
        if not has_support(doms[u], OPP[d], inc):
            return False

    # Black: turn here; both adjacent loop-neighbors must be straight and continue straight through.
    if clue == 'B':
        used_dirs = [d for d in DIRS if bit(p, d)]
        if len(used_dirs) != 2 or not is_turn(p):
            return False
        for d in used_dirs:
            u = nbrs[i][d]
            if u == -1:
                return False
            if not has_support(doms[u], OPP[d], 1, need_straight=True):
                return False

    # White: straight here; at least one adjacent loop-neighbor must be a turn.
    elif clue == 'W':
        if p == MASK_NS:
            u1 = nbrs[i][NORTH]
            u2 = nbrs[i][SOUTH]
            if u1 == -1 or u2 == -1:
                return False
            if not has_support(doms[u1], SOUTH, 1):
                return False
            if not has_support(doms[u2], NORTH, 1):
                return False
            if not (has_support(doms[u1], SOUTH, 1, need_turn=True) or
                    has_support(doms[u2], NORTH, 1, need_turn=True)):
                return False
        elif p == MASK_EW:
            u1 = nbrs[i][EAST]
            u2 = nbrs[i][WEST]
            if u1 == -1 or u2 == -1:
                return False
            if not has_support(doms[u1], WEST, 1):
                return False
            if not has_support(doms[u2], EAST, 1):
                return False
            if not (has_support(doms[u1], WEST, 1, need_turn=True) or
                    has_support(doms[u2], EAST, 1, need_turn=True)):
                return False
        else:
            return False

    return True

def required_edge_status(doms, i, d, nbrs):
    u = nbrs[i][d]
    if u == -1:
        return 0
    vals_i = {bit(p, d) for p in doms[i]}
    vals_u = {bit(q, OPP[d]) for q in doms[u]}
    vals = vals_i & vals_u
    if vals == {1}:
        return 1
    if vals == {0}:
        return 0
    return None

def prune_small_required_cycle(doms, clues, nbrs):
    nverts = len(doms)
    req_adj = [[] for _ in range(nverts)]
    any_req = False
    for i in range(nverts):
        for d in (EAST, SOUTH):
            u = nbrs[i][d]
            if u == -1:
                continue
            s = required_edge_status(doms, i, d, nbrs)
            if s == 1:
                req_adj[i].append(u)
                req_adj[u].append(i)
                any_req = True
    if not any_req:
        return True

    seen = [False] * nverts
    clue_idxs = {i for i, c in enumerate(clues) if c is not None}
    for i in range(nverts):
        if seen[i] or not req_adj[i]:
            continue
        stack = [i]
        comp = []
        seen[i] = True
        while stack:
            v = stack.pop()
            comp.append(v)
            for w in req_adj[v]:
                if not seen[w]:
                    seen[w] = True
                    stack.append(w)
        if all(len(req_adj[v]) == 2 for v in comp):
            comp_set = set(comp)
            # If this required component is already a closed cycle and some clue lies outside,
            # impossible to make a single loop through all clues.
            if any(ci not in comp_set for ci in clue_idxs):
                return False
    return True

def propagate(doms, clues, nbrs):
    changed = True
    while changed:
        changed = False
        for i in range(len(doms)):
            old = doms[i]
            new = {p for p in old if pattern_feasible(i, p, doms, clues, nbrs)}
            if not new:
                return False
            if new != old:
                doms[i] = new
                changed = True
        if not prune_small_required_cycle(doms, clues, nbrs):
            return False
    return True

def choose_var(doms, clues):
    best = None
    best_key = None
    for i, domain in enumerate(doms):
        if len(domain) <= 1:
            continue
        # Prefer clues, then smaller domains.
        priority = 0 if clues[i] is not None else 1
        key = (priority, len(domain))
        if best is None or key < best_key:
            best = i
            best_key = key
    return best

def clone_domains(doms):
    return [set(d) for d in doms]

def solved(doms):
    return all(len(d) == 1 for d in doms)

def build_active_graph(doms, nbrs):
    nverts = len(doms)
    adj = [[] for _ in range(nverts)]
    for i in range(nverts):
        p = next(iter(doms[i]))
        for d in (EAST, SOUTH):
            u = nbrs[i][d]
            if u == -1:
                continue
            q = next(iter(doms[u]))
            if bit(p, d) != bit(q, OPP[d]):
                return None
            if bit(p, d):
                adj[i].append(u)
                adj[u].append(i)
    return adj

def verify_solution(doms, clues, nbrs):
    for i, domain in enumerate(doms):
        if len(domain) != 1:
            return False
        p = next(iter(domain))
        clue = clues[i]
        deg = sum(bit(p, d) for d in DIRS)
        if deg not in (0, 2):
            return False
        if clue == 'W':
            if p not in WHITE_PATTERNS:
                return False
        elif clue == 'B':
            if p not in BLACK_PATTERNS:
                return False

    adj = build_active_graph(doms, nbrs)
    if adj is None:
        return False

    clue_idxs = [i for i, c in enumerate(clues) if c is not None]
    if not clue_idxs:
        return False

    # Every clue must be on the loop.
    for i in clue_idxs:
        if len(adj[i]) != 2:
            return False

    # All used vertices must form one single cycle.
    used = [i for i in range(len(adj)) if len(adj[i]) == 2]
    if not used:
        return False
    if any(len(adj[i]) not in (0, 2) for i in range(len(adj))):
        return False

    seen = set()
    stack = [used[0]]
    while stack:
        v = stack.pop()
        if v in seen:
            continue
        seen.add(v)
        for w in adj[v]:
            if w not in seen:
                stack.append(w)
    if set(used) != seen:
        return False
    if any(i not in seen for i in clue_idxs):
        return False
    return True

def extract_loop(doms, nbrs, n):
    adj = build_active_graph(doms, nbrs)
    used = [i for i in range(len(adj)) if len(adj[i]) == 2]
    if not used:
        return None
    start = min(used)
    path = [start]
    prev = None
    cur = start
    while True:
        nxts = adj[cur]
        if prev is None:
            nxt = min(nxts)
        else:
            nxt = nxts[0] if nxts[1] == prev else nxts[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break
        if len(path) > len(used) + 1:
            return None
    return [rc_of(i, n) for i in path]

def search(doms, clues, nbrs):
    if not propagate(doms, clues, nbrs):
        return None
    if solved(doms):
        if verify_solution(doms, clues, nbrs):
            return doms
        return None

    i = choose_var(doms, clues)
    if i is None:
        return None

    # Human-like branching: try more constrained clue-compatible options first.
    options = sorted(doms[i], key=lambda p: (0 if clues[i] is not None else 1, p))
    for p in options:
        nd = clone_domains(doms)
        nd[i] = {p}
        ans = search(nd, clues, nbrs)
        if ans is not None:
            return ans
    return None

def solve(observation):
    data = observation['data']
    n = len(data)
    doms, clues, nbrs = initial_domains(data)
    ans = search(doms, clues, nbrs)
    if ans is None:
        return "No Solution"
    loop = extract_loop(ans, nbrs, n)
    return loop if loop is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[0, 0, 0, 0, 1, 1, 1, 2, 3, 3], [4, 0, 0, 5, 6, 6, 1, 2, 2, 2], [4, 4, 5, 5, 6, 7, 2, 2, 2, 2], [4, 4, 5, 6, 6, 7, 8, 8, 2, 2], [9, 10, 10, 11, 7, 7, 12, 13, 13, 2], [9, 9, 9, 11, 11, 14, 12, 13, 13, 13], [9, 9, 9, 9, 11, 14, 15, 15, 16, 16], [17, 17, 17, 18, 14, 14, 15, 16, 16, 19], [20, 20, 17, 18, 21, 21, 15, 19, 19, 19], [20, 20, 17, 17, 21, 21, 21, 19, 19, 19]]}

from collections import defaultdict, deque

# Shading values
U = -1
N = 0
S = 1


def solve(observation):
    grid = observation["data"]
    n = len(grid)
    m = len(grid[0]) if n else 0

    regions = defaultdict(list)
    for r in range(n):
        for c in range(m):
            regions[grid[r][c]].append((r, c))
    region_ids = list(regions.keys())
    region_index = {rid: i for i, rid in enumerate(region_ids)}

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    neighbors = {}
    for r in range(n):
        for c in range(m):
            adj = []
            for dr, dc in dirs:
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    adj.append((rr, cc))
            neighbors[(r, c)] = adj

    # Pre-check: every region must have at least 2 cells
    for rid, cells in regions.items():
        if len(cells) < 2:
            return "No Solution"

    # Pre-check: every cell must be able to belong to some domino if shaded
    shade_possible = {}
    for r in range(n):
        for c in range(m):
            shade_possible[(r, c)] = len(neighbors[(r, c)]) > 0

    # State
    state = [[U] * m for _ in range(n)]
    shaded_in_region = [0] * len(region_ids)
    unknown_in_region = [len(regions[rid]) for rid in region_ids]

    def region_of(cell):
        return region_index[grid[cell[0]][cell[1]]]

    def clone_state(st, sir, uir):
        return [row[:] for row in st], sir[:], uir[:]

    def set_cell(st, sir, uir, cell, val, queue):
        r, c = cell
        cur = st[r][c]
        if cur == val:
            return True
        if cur != U and cur != val:
            return False
        st[r][c] = val
        idx = region_of(cell)
        uir[idx] -= 1
        if val == S:
            sir[idx] += 1
        queue.append(cell)
        return True

    def count_neighbor_vals(st, cell):
        s = 0
        u = 0
        ns = []
        us = []
        for nb in neighbors[cell]:
            vr = st[nb[0]][nb[1]]
            if vr == S:
                s += 1
                ns.append(nb)
            elif vr == U:
                u += 1
                us.append(nb)
        return s, u, ns, us

    def force_domino_closure(st, sir, uir, a, b, queue):
        # If a and b are shaded adjacent cells, they must be paired together.
        # Therefore all other orthogonal neighbors of each must be unshaded.
        for x in neighbors[a]:
            if x != b:
                if not set_cell(st, sir, uir, x, N, queue):
                    return False
        for x in neighbors[b]:
            if x != a:
                if not set_cell(st, sir, uir, x, N, queue):
                    return False
        return True

    def propagate(st, sir, uir):
        queue = deque()

        # Seed region-level obvious deductions
        for rid in region_ids:
            idx = region_index[rid]
            need = 2 - sir[idx]
            unk = uir[idx]
            if need < 0 or need > unk:
                return False
            if need == 0:
                for cell in regions[rid]:
                    if st[cell[0]][cell[1]] == U:
                        if not set_cell(st, sir, uir, cell, N, queue):
                            return False
            elif need == unk:
                for cell in regions[rid]:
                    if st[cell[0]][cell[1]] == U:
                        if not set_cell(st, sir, uir, cell, S, queue):
                            return False

        # Also mark impossible-to-shade cells unshaded
        for r in range(n):
            for c in range(m):
                if st[r][c] == U and not shade_possible[(r, c)]:
                    if not set_cell(st, sir, uir, (r, c), N, queue):
                        return False

        while True:
            changed = False

            # Process queued changed cells
            while queue:
                cell = queue.popleft()
                r, c = cell
                v = st[r][c]

                # Region bounds after any change
                idx = region_of(cell)
                need = 2 - sir[idx]
                unk = uir[idx]
                if need < 0 or need > unk:
                    return False

                if v == S:
                    s_cnt, u_cnt, s_nbs, u_nbs = count_neighbor_vals(st, cell)

                    # Shaded cell must have exactly one shaded neighbor eventually
                    if s_cnt > 1:
                        return False
                    if s_cnt == 0 and u_cnt == 0:
                        return False
                    if s_cnt == 1:
                        # Paired already: all other unknown neighbors become unshaded
                        partner = s_nbs[0]
                        if not force_domino_closure(st, sir, uir, cell, partner, queue):
                            return False
                    else:
                        # s_cnt == 0
                        if u_cnt == 1:
                            if not set_cell(st, sir, uir, u_nbs[0], S, queue):
                                return False

                elif v == N:
                    pass

            # Global region deductions
            for rid in region_ids:
                idx = region_index[rid]
                need = 2 - sir[idx]
                unk = uir[idx]
                if need < 0 or need > unk:
                    return False
                if need == 0:
                    for cell in regions[rid]:
                        if st[cell[0]][cell[1]] == U:
                            if not set_cell(st, sir, uir, cell, N, queue):
                                return False
                            changed = True
                elif need == unk:
                    for cell in regions[rid]:
                        if st[cell[0]][cell[1]] == U:
                            if not set_cell(st, sir, uir, cell, S, queue):
                                return False
                            changed = True

            # Cell-level local deductions
            for r in range(n):
                for c in range(m):
                    cell = (r, c)
                    if st[r][c] != U:
                        continue

                    idx = region_of(cell)
                    need = 2 - sir[idx]
                    if need == 0:
                        if not set_cell(st, sir, uir, cell, N, queue):
                            return False
                        changed = True
                        continue

                    s_cnt, u_cnt, s_nbs, u_nbs = count_neighbor_vals(st, cell)

                    # If shaded impossible, force unshaded
                    if s_cnt > 1:
                        if not set_cell(st, sir, uir, cell, N, queue):
                            return False
                        changed = True
                        continue

                    # If two neighboring shaded cells already adjacent to this unknown,
                    # it cannot be shaded because different dominoes can't touch.
                    if s_cnt >= 2:
                        if not set_cell(st, sir, uir, cell, N, queue):
                            return False
                        changed = True
                        continue

                    # If no way to get exactly one shaded neighbor, cell can't be shaded
                    can_be_shaded = False
                    if s_cnt == 1:
                        can_be_shaded = True
                    elif s_cnt == 0 and u_cnt >= 1:
                        can_be_shaded = True

                    if not can_be_shaded:
                        if not set_cell(st, sir, uir, cell, N, queue):
                            return False
                        changed = True
                        continue

                    # If a neighboring shaded cell has no other possible partner, this cell must be shaded
                    must_shade = False
                    for nb in s_nbs:
                        s2, u2, s_nbs2, u_nbs2 = count_neighbor_vals(st, nb)
                        if s2 == 0 and len(u_nbs2) == 1 and u_nbs2[0] == cell:
                            must_shade = True
                            break
                    if must_shade:
                        if not set_cell(st, sir, uir, cell, S, queue):
                            return False
                        changed = True
                        continue

            if queue:
                continue
            if not changed:
                break

        # Final consistency sweep
        for rid in region_ids:
            idx = region_index[rid]
            need = 2 - sir[idx]
            unk = uir[idx]
            if need < 0 or need > unk:
                return False

        for r in range(n):
            for c in range(m):
                if st[r][c] == S:
                    s_cnt, u_cnt, _, _ = count_neighbor_vals(st, (r, c))
                    if s_cnt > 1:
                        return False
                    if s_cnt == 0 and u_cnt == 0:
                        return False

        return True

    def is_solved(st, sir, uir):
        for idx in range(len(region_ids)):
            if sir[idx] != 2:
                return False
        for r in range(n):
            for c in range(m):
                if st[r][c] == U:
                    return False
        # Every shaded cell must have exactly one shaded neighbor
        for r in range(n):
            for c in range(m):
                if st[r][c] == S:
                    cnt = sum(1 for nb in neighbors[(r, c)] if st[nb[0]][nb[1]] == S)
                    if cnt != 1:
                        return False
        return True

    def score_cell(st, cell):
        idx = region_of(cell)
        need = 2 - shaded_in_region[idx]
        _, u_cnt, _, _ = count_neighbor_vals(st, cell)
        # Smaller scores are better
        return (need, u_cnt, len(neighbors[cell]))

    def choose_branch_cell(st, sir, uir):
        best = None
        best_key = None

        # First prefer regions with tightest remaining requirement
        for rid in region_ids:
            idx = region_index[rid]
            need = 2 - sir[idx]
            unk_cells = [cell for cell in regions[rid] if st[cell[0]][cell[1]] == U]
            if not unk_cells:
                continue
            if need <= 0:
                continue
            for cell in unk_cells:
                s_cnt, u_cnt, _, _ = count_neighbor_vals(st, cell)
                can_shade = (s_cnt == 1) or (s_cnt == 0 and u_cnt >= 1)
                key = (
                    need,
                    len(unk_cells),
                    0 if can_shade else 1,
                    u_cnt,
                )
                if best is None or key < best_key:
                    best = cell
                    best_key = key
        return best

    def dfs(st, sir, uir):
        if not propagate(st, sir, uir):
            return None
        if is_solved(st, sir, uir):
            return st

        cell = choose_branch_cell(st, sir, uir)
        if cell is None:
            return None

        r, c = cell
        s_cnt, u_cnt, _, _ = count_neighbor_vals(st, cell)
        can_shade = (s_cnt == 1) or (s_cnt == 0 and u_cnt >= 1)

        # Branch order:
        # If region still needs many shaded cells, try shaded first; otherwise unshaded first.
        idx = region_of(cell)
        need = 2 - sir[idx]
        branch_vals = [S, N] if can_shade and need > 0 else [N, S]

        for val in branch_vals:
            if val == S and not can_shade:
                continue
            st2, sir2, uir2 = clone_state(st, sir, uir)
            q = deque()
            if not set_cell(st2, sir2, uir2, cell, val, q):
                continue
            # Process immediate queue through propagate
            res = dfs(st2, sir2, uir2)
            if res is not None:
                return res
        return None

    result = dfs(state, shaded_in_region, unknown_in_region)
    if result is None:
        return "No Solution"

    answer = [[('S' if result[r][c] == S else None) for c in range(m)] for r in range(n)]
    return str(answer)


