# Generalized solver for loop-on-dots Masyu-style puzzles.
# The solver uses:
# - vertex pattern domains (degree-0 or degree-2 local states)
# - aggressive local propagation
# - clue-specific deductions for white/black circles
# - early cycle pruning
# - guided backtracking on the most constrained vertex

U, R, D, L = 1, 2, 4, 8
DIRS = [U, R, D, L]
DR = {U: -1, R: 0, D: 1, L: 0}
DC = {U: 0, R: 1, D: 0, L: -1}
OPP = {U: D, R: L, D: U, L: R}
MASKS_DEG2 = [U | R, R | D, D | L, L | U, U | D, L | R]
TURN_MASKS = {U | R, R | D, D | L, L | U}
STRAIGHT_MASKS = {U | D, L | R}

def bitcount(x):
    return (x & 1) + ((x >> 1) & 1) + ((x >> 2) & 1) + ((x >> 3) & 1)

def hasbit(mask, b):
    return (mask & b) != 0

def move(r, c, d):
    return r + DR[d], c + DC[d]

def inside(n, r, c):
    return 0 <= r < n and 0 <= c < n

def solve(observation):
    data = observation["data"]
    n = len(data)
    idx = lambda r, c: r * n + c
    rc = lambda i: (i // n, i % n)

    neighbors = [[] for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            i = idx(r, c)
            for d in DIRS:
                rr, cc = move(r, c, d)
                if inside(n, rr, cc):
                    neighbors[i].append((d, idx(rr, cc)))

    base_domains = []
    clues = set()
    for r in range(n):
        for c in range(n):
            clue = data[r][c]
            if clue == 'W':
                dom = {U | D, L | R}
                clues.add(idx(r, c))
            elif clue == 'B':
                dom = set(TURN_MASKS)
                clues.add(idx(r, c))
            else:
                dom = {0, U | R, R | D, D | L, L | U, U | D, L | R}
            # Remove patterns going out of bounds.
            valid = set()
            for m in dom:
                ok = True
                for d in DIRS:
                    if hasbit(m, d):
                        rr, cc = move(r, c, d)
                        if not inside(n, rr, cc):
                            ok = False
                            break
                if ok:
                    valid.add(m)
            base_domains.append(valid)

    def masks_with_bit(dom, b):
        return [m for m in dom if hasbit(m, b)]

    def masks_without_bit(dom, b):
        return [m for m in dom if not hasbit(m, b)]

    def compatible_edge_exists(dom_a, bit_a, dom_b, bit_b):
        return any(hasbit(m1, bit_a) for m1 in dom_a) and any(hasbit(m2, bit_b) for m2 in dom_b)

    def neighbor_turn_compatible(dom, incoming_bit):
        # Compatible masks at neighbor that use incoming_bit and TURN there.
        return [m for m in dom if hasbit(m, incoming_bit) and m in TURN_MASKS]

    def neighbor_straight_axis_compatible(dom, incoming_bit):
        # For black clue extension: neighbor must be straight through on same axis.
        if incoming_bit in (U, D):
            needed = U | D
        else:
            needed = L | R
        return [m for m in dom if m == needed and hasbit(m, incoming_bit)]

    def edge_status(domains, i, d, j):
        a_all = all(hasbit(m, d) for m in domains[i])
        a_none = all(not hasbit(m, d) for m in domains[i])
        b_all = all(hasbit(m, OPP[d]) for m in domains[j])
        b_none = all(not hasbit(m, OPP[d]) for m in domains[j])
        if a_all or b_all:
            return 1
        if a_none and b_none:
            return -1
        return 0

    def revise_vertex(domains, i):
        r, c = rc(i)
        clue = data[r][c]
        new_dom = set()

        for m in domains[i]:
            ok = True

            # Basic edge-consistency with neighbors / borders.
            for d in DIRS:
                rr, cc = move(r, c, d)
                if not inside(n, rr, cc):
                    if hasbit(m, d):
                        ok = False
                        break
                    continue
                j = idx(rr, cc)
                if hasbit(m, d):
                    if not any(hasbit(mm, OPP[d]) for mm in domains[j]):
                        ok = False
                        break
                else:
                    # If neighbor is forced to connect here, this mask is impossible.
                    if all(hasbit(mm, OPP[d]) for mm in domains[j]):
                        ok = False
                        break
            if not ok:
                continue

            # Clue-specific logical propagation.
            if clue == 'B':
                # Black turns here, and must go straight at both adjacent vertices.
                for d in DIRS:
                    if hasbit(m, d):
                        rr, cc = move(r, c, d)
                        if not inside(n, rr, cc):
                            ok = False
                            break
                        j = idx(rr, cc)
                        if not neighbor_straight_axis_compatible(domains[j], OPP[d]):
                            ok = False
                            break
                if not ok:
                    continue

            elif clue == 'W':
                # White goes straight here and at least one adjacent side must turn.
                if m == (L | R):
                    li = idx(r, c - 1) if c - 1 >= 0 else None
                    ri = idx(r, c + 1) if c + 1 < n else None
                    if li is None or ri is None:
                        ok = False
                    else:
                        left_turn = neighbor_turn_compatible(domains[li], R)
                        right_turn = neighbor_turn_compatible(domains[ri], L)
                        if not any(hasbit(mm, R) for mm in domains[li]):
                            ok = False
                        if not any(hasbit(mm, L) for mm in domains[ri]):
                            ok = False
                        if ok and not left_turn and not right_turn:
                            ok = False
                elif m == (U | D):
                    ui = idx(r - 1, c) if r - 1 >= 0 else None
                    di = idx(r + 1, c) if r + 1 < n else None
                    if ui is None or di is None:
                        ok = False
                    else:
                        up_turn = neighbor_turn_compatible(domains[ui], D)
                        down_turn = neighbor_turn_compatible(domains[di], U)
                        if not any(hasbit(mm, D) for mm in domains[ui]):
                            ok = False
                        if not any(hasbit(mm, U) for mm in domains[di]):
                            ok = False
                        if ok and not up_turn and not down_turn:
                            ok = False
                else:
                    ok = False

            if ok:
                new_dom.add(m)

        if not new_dom:
            return None, True
        changed = new_dom != domains[i]
        domains[i] = new_dom
        return changed, False

    def propagate(domains):
        changed = True
        while changed:
            changed = False
            for i in range(n * n):
                ch, bad = revise_vertex(domains, i)
                if bad:
                    return False
                if ch:
                    changed = True

            # Additional immediate edge forcing by contradiction:
            # If an edge is impossible from one side, remove all masks using it on the other side.
            local_changed = True
            while local_changed:
                local_changed = False
                for i in range(n * n):
                    r, c = rc(i)
                    for d in DIRS:
                        rr, cc = move(r, c, d)
                        if not inside(n, rr, cc):
                            continue
                        j = idx(rr, cc)
                        if i > j:
                            continue

                        i_has = any(hasbit(m, d) for m in domains[i])
                        j_has = any(hasbit(m, OPP[d]) for m in domains[j])
                        if i_has and not j_has:
                            nd = {m for m in domains[i] if not hasbit(m, d)}
                            if not nd:
                                return False
                            if nd != domains[i]:
                                domains[i] = nd
                                local_changed = True
                        if j_has and not i_has:
                            nd = {m for m in domains[j] if not hasbit(m, OPP[d])}
                            if not nd:
                                return False
                            if nd != domains[j]:
                                domains[j] = nd
                                local_changed = True
                if local_changed:
                    for i in range(n * n):
                        ch, bad = revise_vertex(domains, i)
                        if bad:
                            return False
                        if ch:
                            changed = True

            if premature_cycle(domains, clues, n):
                return False

        return True

    def forced_on_graph(domains):
        g = [[] for _ in range(n * n)]
        for i in range(n * n):
            r, c = rc(i)
            for d in DIRS:
                rr, cc = move(r, c, d)
                if not inside(n, rr, cc):
                    continue
                j = idx(rr, cc)
                if i < j:
                    st = edge_status(domains, i, d, j)
                    if st == 1:
                        g[i].append(j)
                        g[j].append(i)
        return g

    def premature_cycle(domains, clues_set, n_):
        g = forced_on_graph(domains)
        seen = set()
        maybe_nonzero = {i for i, dom in enumerate(domains) if any(m != 0 for m in dom)}
        for s in range(n_ * n_):
            if s in seen or not g[s]:
                continue
            stack = [s]
            comp = []
            seen.add(s)
            while stack:
                v = stack.pop()
                comp.append(v)
                for w in g[v]:
                    if w not in seen:
                        seen.add(w)
                        stack.append(w)
            deg2all = all(len(g[v]) == 2 for v in comp)
            if deg2all:
                edge_count = sum(len(g[v]) for v in comp) // 2
                if edge_count == len(comp):
                    comp_set = set(comp)
                    if not clues_set.issubset(comp_set):
                        return True
                    if comp_set != maybe_nonzero:
                        return True
        return False

    def choose_branch_vertex(domains):
        best = None
        best_key = None
        for i, dom in enumerate(domains):
            if len(dom) <= 1:
                continue
            # Prefer clue vertices, then smallest domain, then nonzero-rich.
            r, c = rc(i)
            clue = data[r][c]
            key = (0 if clue in ('W', 'B') else 1, len(dom), -sum(1 for m in dom if m != 0), i)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        return best

    def order_masks_for_branch(i, dom):
        r, c = rc(i)
        clue = data[r][c]
        vals = list(dom)
        if clue == 'B':
            return sorted(vals)
        if clue == 'W':
            return sorted(vals)
        # Try degree-2 masks before 0 to grow the loop structure and trigger deductions.
        vals.sort(key=lambda m: (m == 0, m))
        return vals

    def clone_domains(domains):
        return [set(d) for d in domains]

    def finalized_solution(domains):
        if any(len(dom) != 1 for dom in domains):
            return None
        masks = [next(iter(dom)) for dom in domains]

        # Every used edge must be matched.
        for i in range(n * n):
            r, c = rc(i)
            for d in DIRS:
                rr, cc = move(r, c, d)
                if not inside(n, rr, cc):
                    if hasbit(masks[i], d):
                        return None
                    continue
                j = idx(rr, cc)
                if hasbit(masks[i], d) != hasbit(masks[j], OPP[d]):
                    return None

        used = [i for i, m in enumerate(masks) if m != 0]
        if not used:
            return None
        if any(bitcount(masks[i]) not in (0, 2) for i in range(n * n)):
            return None
        if any(masks[i] == 0 for i in clues):
            return None

        # Single cycle check.
        start = min(used)
        prev = None
        cur = start
        path = [rc(start)]
        visited_edges = set()

        while True:
            exits = []
            for d in DIRS:
                if hasbit(masks[cur], d):
                    nr, nc = move(*rc(cur), d)
                    j = idx(nr, nc)
                    exits.append((d, j))
            if len(exits) != 2:
                return None

            nxt = None
            if prev is None:
                nxt = exits[0][1]
            else:
                for _, j in exits:
                    if j != prev:
                        nxt = j
                        break
            if nxt is None:
                return None

            e = tuple(sorted((cur, nxt)))
            if e in visited_edges:
                if nxt != start:
                    return None
                path.append(rc(start))
                break
            visited_edges.add(e)
            prev, cur = cur, nxt
            path.append(rc(cur))

        used_edge_count = sum(bitcount(m) for m in masks) // 2
        if len(visited_edges) != used_edge_count:
            return None
        used_set = set(used)
        if set(idx(r, c) for r, c in path[:-1]) != used_set:
            return None

        return path

    def dfs(domains):
        if not propagate(domains):
            return None

        sol = finalized_solution(domains)
        if sol is not None:
            return sol

        i = choose_branch_vertex(domains)
        if i is None:
            return None

        for m in order_masks_for_branch(i, domains[i]):
            new_domains = clone_domains(domains)
            new_domains[i] = {m}
            ans = dfs(new_domains)
            if ans is not None:
                return ans

        return None

    answer = dfs(clone_domains(base_domains))
    return answer if answer is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

