from collections import deque, defaultdict
from itertools import combinations

BLACK = 1
WHITE = 0
UNKNOWN = -1

def solve(observation):
    region = observation["region"]
    data = observation["data"]
    n = len(region)
    m = len(region[0])

    cells = [(r, c) for r in range(n) for c in range(m)]
    idx_of = {(r, c): r * m + c for r, c in cells}
    rc_of = {i: (i // m, i % m) for i in range(n * m)}

    neigh = [[] for _ in range(n * m)]
    for r in range(n):
        for c in range(m):
            i = idx_of[(r, c)]
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < m:
                    neigh[i].append(idx_of[(rr, cc)])

    regions = defaultdict(list)
    clue_by_region = {}
    for r in range(n):
        for c in range(m):
            rid = region[r][c]
            i = idx_of[(r, c)]
            regions[rid].append(i)
            if data[r][c] is not None:
                clue_by_region[rid] = data[r][c]

    region_ids = sorted(regions)
    region_of = [None] * (n * m)
    for rid, lst in regions.items():
        for i in lst:
            region_of[i] = rid

    # Precompute row/column 3-region windows for the "straight white line" rule.
    line_windows = []
    # Rows
    for r in range(n):
        blocks = []
        c = 0
        while c < m:
            rid = region[r][c]
            start = c
            while c + 1 < m and region[r][c + 1] == rid:
                c += 1
            end = c
            blocks.append((rid, start, end))
            c += 1
        for k in range(len(blocks) - 2):
            s = blocks[k][1]
            e = blocks[k + 2][2]
            window = [idx_of[(r, cc)] for cc in range(s, e + 1)]
            line_windows.append(tuple(window))
    # Columns
    for c in range(m):
        blocks = []
        r = 0
        while r < n:
            rid = region[r][c]
            start = r
            while r + 1 < n and region[r + 1][c] == rid:
                r += 1
            end = r
            blocks.append((rid, start, end))
            r += 1
        for k in range(len(blocks) - 2):
            s = blocks[k][1]
            e = blocks[k + 2][2]
            window = [idx_of[(rr, c)] for rr in range(s, e + 1)]
            line_windows.append(tuple(window))

    # For each cell, which windows contain it.
    windows_of_cell = [[] for _ in range(n * m)]
    for wi, win in enumerate(line_windows):
        for i in win:
            windows_of_cell[i].append(wi)

    # Precompute valid patterns for each numbered region:
    # exactly clue blacks, and no orth-adjacent blacks within region.
    region_patterns = {}
    for rid, clue in clue_by_region.items():
        lst = regions[rid]
        pos = {cell: k for k, cell in enumerate(lst)}
        internal_adj_masks = [0] * len(lst)
        for k, cell in enumerate(lst):
            mask = 0
            for nb in neigh[cell]:
                if nb in pos:
                    mask |= 1 << pos[nb]
            internal_adj_masks[k] = mask

        pats = []
        if clue < 0 or clue > len(lst):
            return "No Solution"
        for comb in combinations(range(len(lst)), clue):
            mask = 0
            ok = True
            for k in comb:
                if internal_adj_masks[k] & mask:
                    ok = False
                    break
                mask |= 1 << k
            if ok:
                pats.append(mask)
        if not pats:
            return "No Solution"
        region_patterns[rid] = (lst, pats)

    # Unknown regions have no count restriction, but black adjacency still applies.

    class State:
        __slots__ = (
            "cell", "black_count", "unknown_count",
            "changed_queue", "active_windows", "forced_whites"
        )

        def __init__(self):
            self.cell = [UNKNOWN] * (n * m)
            self.black_count = {rid: 0 for rid in clue_by_region}
            self.unknown_count = {rid: len(regions[rid]) for rid in clue_by_region}
            self.changed_queue = deque()
            self.active_windows = [None] * len(line_windows)
            self.forced_whites = set()

    def clone_state(st):
        ns = State()
        ns.cell = st.cell[:]
        ns.black_count = st.black_count.copy()
        ns.unknown_count = st.unknown_count.copy()
        ns.changed_queue = deque(st.changed_queue)
        ns.active_windows = st.active_windows[:]
        ns.forced_whites = set(st.forced_whites)
        return ns

    def assign(st, i, val):
        cur = st.cell[i]
        if cur == val:
            return True
        if cur != UNKNOWN:
            return False
        st.cell[i] = val
        rid = region_of[i]
        if rid in clue_by_region:
            st.unknown_count[rid] -= 1
            if val == BLACK:
                st.black_count[rid] += 1
        st.changed_queue.append(i)
        return True

    def init_state(st):
        for wi, win in enumerate(line_windows):
            st.active_windows[wi] = set(win)
        # immediate clue-0 / full-region deductions handled by propagate
        for rid, clue in clue_by_region.items():
            if clue == 0:
                for i in regions[rid]:
                    if not assign(st, i, WHITE):
                        return False
        return True

    def region_bounds_ok(st, rid):
        clue = clue_by_region[rid]
        b = st.black_count[rid]
        u = st.unknown_count[rid]
        return b <= clue <= b + u

    def possible_white_connectivity_ok(st):
        # All fixed white cells must belong to one component in graph of non-black cells.
        allowed = [i for i, v in enumerate(st.cell) if v != BLACK]
        if not allowed:
            return True
        allowed_set = set(allowed)
        fixed_whites = [i for i, v in enumerate(st.cell) if v == WHITE]
        start = fixed_whites[0] if fixed_whites else allowed[0]
        q = deque([start])
        seen = {start}
        while q:
            x = q.popleft()
            for y in neigh[x]:
                if y in allowed_set and y not in seen:
                    seen.add(y)
                    q.append(y)
        for i in fixed_whites:
            if i not in seen:
                return False
        return True

    def final_white_connected(st):
        whites = [i for i, v in enumerate(st.cell) if v != BLACK]
        if not whites:
            return True
        q = deque([whites[0]])
        seen = {whites[0]}
        white_set = set(whites)
        while q:
            x = q.popleft()
            for y in neigh[x]:
                if y in white_set and y not in seen:
                    seen.add(y)
                    q.append(y)
        return len(seen) == len(white_set)

    def apply_region_logic(st):
        progress = True
        while progress:
            progress = False
            for rid, clue in clue_by_region.items():
                if not region_bounds_ok(st, rid):
                    return False
                b = st.black_count[rid]
                u = st.unknown_count[rid]
                if b == clue:
                    for i in regions[rid]:
                        if st.cell[i] == UNKNOWN:
                            if not assign(st, i, WHITE):
                                return False
                            progress = True
                elif b + u == clue:
                    for i in regions[rid]:
                        if st.cell[i] == UNKNOWN:
                            if not assign(st, i, BLACK):
                                return False
                            progress = True

            # Pattern-based deduction in numbered regions.
            for rid, clue in clue_by_region.items():
                lst, pats = region_patterns[rid]
                valid = []
                for mask in pats:
                    ok = True
                    for k, i in enumerate(lst):
                        is_black = (mask >> k) & 1
                        v = st.cell[i]
                        if v == BLACK and not is_black:
                            ok = False
                            break
                        if v == WHITE and is_black:
                            ok = False
                            break
                        if is_black:
                            # external adjacency
                            for nb in neigh[i]:
                                if nb not in lst and st.cell[nb] == BLACK:
                                    ok = False
                                    break
                            if not ok:
                                break
                    if ok:
                        valid.append(mask)
                if not valid:
                    return False

                all_black = (1 << len(lst)) - 1
                some_black = 0
                for mask in valid:
                    some_black |= mask
                    all_black &= mask

                for k, i in enumerate(lst):
                    bit = 1 << k
                    if all_black & bit:
                        if st.cell[i] == UNKNOWN:
                            if not assign(st, i, BLACK):
                                return False
                            progress = True
                    elif not (some_black & bit):
                        if st.cell[i] == UNKNOWN:
                            if not assign(st, i, WHITE):
                                return False
                            progress = True
        return True

    def apply_black_adjacency(st):
        while st.changed_queue:
            i = st.changed_queue.popleft()
            if st.cell[i] == BLACK:
                for nb in neigh[i]:
                    if st.cell[nb] == BLACK:
                        return False
                    if st.cell[nb] == UNKNOWN:
                        if not assign(st, nb, WHITE):
                            return False
        return True

    def apply_line_rule(st):
        # Every 3-region window must contain at least one black eventually.
        progress = True
        while progress:
            progress = False
            for win in line_windows:
                has_black = False
                unknowns = []
                for i in win:
                    if st.cell[i] == BLACK:
                        has_black = True
                        break
                    if st.cell[i] == UNKNOWN:
                        unknowns.append(i)
                if has_black:
                    continue
                if not unknowns:
                    return False
                if len(unknowns) == 1:
                    if not assign(st, unknowns[0], BLACK):
                        return False
                    progress = True
        return True

    def propagate(st):
        while True:
            snapshot = (
                tuple(st.cell),
                tuple(sorted(st.black_count.items())),
                tuple(sorted(st.unknown_count.items())),
            )
            if not apply_black_adjacency(st):
                return False
            if not apply_region_logic(st):
                return False
            if not apply_line_rule(st):
                return False
            if not possible_white_connectivity_ok(st):
                return False
            newsnap = (
                tuple(st.cell),
                tuple(sorted(st.black_count.items())),
                tuple(sorted(st.unknown_count.items())),
            )
            if newsnap == snapshot:
                break
        return True

    def complete_ok(st):
        for rid in clue_by_region:
            if st.black_count[rid] != clue_by_region[rid]:
                return False
        # line rule final check: no all-white/unknown 3-region window, but at completion unknown absent
        for win in line_windows:
            if all(st.cell[i] != BLACK for i in win):
                return False
        if any(st.cell[i] == BLACK and any(st.cell[nb] == BLACK for nb in neigh[i]) for i in range(n * m)):
            return False
        if not final_white_connected(st):
            return False
        return True

    def choose_branch(st):
        # Prefer numbered region with fewest valid patterns > 1.
        best = None
        best_valid = None
        for rid, clue in clue_by_region.items():
            lst, pats = region_patterns[rid]
            valid = []
            for mask in pats:
                ok = True
                for k, i in enumerate(lst):
                    is_black = (mask >> k) & 1
                    v = st.cell[i]
                    if v == BLACK and not is_black:
                        ok = False
                        break
                    if v == WHITE and is_black:
                        ok = False
                        break
                    if is_black:
                        for nb in neigh[i]:
                            if nb not in lst and st.cell[nb] == BLACK:
                                ok = False
                                break
                        if not ok:
                            break
                if ok:
                    valid.append(mask)
            if len(valid) > 1 and (best is None or len(valid) < len(best_valid)):
                best = ("region", rid)
                best_valid = valid

        if best is not None:
            return best, best_valid

        # Else choose a cell with strongest local restriction.
        best_i = None
        best_score = None
        for i, v in enumerate(st.cell):
            if v != UNKNOWN:
                continue
            score = 0
            rid = region_of[i]
            if rid in clue_by_region:
                clue = clue_by_region[rid]
                rem = clue - st.black_count[rid]
                unk = st.unknown_count[rid]
                score += 10 - abs(2 * rem - unk)
            score += len(windows_of_cell[i]) * 3
            score += sum(1 for nb in neigh[i] if st.cell[nb] == BLACK) * 20
            if best_score is None or score > best_score:
                best_score = score
                best_i = i
        return ("cell", best_i), None

    def search(st):
        if not propagate(st):
            return None
        if all(v != UNKNOWN for v in st.cell):
            if complete_ok(st):
                return st
            return None

        branch, info = choose_branch(st)
        kind = branch[0]

        if kind == "region":
            rid = branch[1]
            lst, _ = region_patterns[rid]
            # Try most constrained patterns first.
            for mask in info:
                ns = clone_state(st)
                ok = True
                for k, i in enumerate(lst):
                    val = BLACK if ((mask >> k) & 1) else WHITE
                    if not assign(ns, i, val):
                        ok = False
                        break
                if ok:
                    res = search(ns)
                    if res is not None:
                        return res
            return None

        i = branch[1]
        # Value ordering: black first if plausible because it cuts line windows and adjacency.
        for val in (BLACK, WHITE):
            ns = clone_state(st)
            if assign(ns, i, val):
                res = search(ns)
                if res is not None:
                    return res
        return None

    st = State()
    if not init_state(st):
        return "No Solution"
    res = search(st)
    if res is None:
        return "No Solution"

    ans = []
    for r in range(n):
        row = []
        for c in range(m):
            v = res.cell[idx_of[(r, c)]]
            row.append('B' if v == BLACK else None)
        ans.append(row)
    return ans

