# General solver for the described single-loop numbered white/black circle puzzle.
# The model is vertex-state based:
#   each dot is one of:
#     EMPTY, H, V, NE, NW, SE, SW
#   meaning degree 0 or degree 2 with exact local shape.
#
# Numbered clue handling is human-like:
#   - white clue: loop must go straight through the clue
#   - black clue: loop must turn at the clue
#   - the clue number is the sum of the lengths of the two straight segments
#     extending from the clue along the loop until the next turns.
#
# For each clue we precompute all feasible "segment patterns" (orientation + split of k).
# Each pattern imposes allowed states on the clue itself, on all intermediate dots of the
# two straight rays, and on the two turning endpoints.
# Propagation then repeatedly:
#   1) enforces edge-consistency between adjacent vertex states
#   2) prunes incompatible clue patterns
#   3) tightens vertex domains using remaining clue-pattern support
#
# Search is guided by minimum remaining values on clue-pattern domains and then vertex domains.
# This is not blind brute force; most work is deduction/propagation.

from copy import deepcopy

DIRS = {
    'N': (-1, 0),
    'S': (1, 0),
    'W': (0, -1),
    'E': (0, 1),
}
OPP = {'N': 'S', 'S': 'N', 'W': 'E', 'E': 'W'}

STATE_DIRS = {
    'EMPTY': frozenset(),
    'H': frozenset(('W', 'E')),
    'V': frozenset(('N', 'S')),
    'NE': frozenset(('N', 'E')),
    'NW': frozenset(('N', 'W')),
    'SE': frozenset(('S', 'E')),
    'SW': frozenset(('S', 'W')),
}

ALL_STATES = tuple(STATE_DIRS.keys())
NONEMPTY_STATES = tuple(s for s in ALL_STATES if s != 'EMPTY')

# For endpoint constraints: arriving from direction d means the endpoint must include OPP? No:
# If a ray reaches an endpoint from the clue side, then at the endpoint the used edge points back toward the clue.
# Example: ray traveling left from clue ends at endpoint; at endpoint the used edge is E (back toward clue).
TURN_STATES_USING = {d: set() for d in DIRS}
STRAIGHT_STATE_FOR_AXIS = {
    'H': {'H'},
    'V': {'V'},
}
for st, ds in STATE_DIRS.items():
    if len(ds) == 2 and st not in ('H', 'V'):
        for d in ds:
            TURN_STATES_USING[d].add(st)


def in_bounds(nr, nc, n):
    return 0 <= nr <= n and 0 <= nc <= n


def move(pos, d, step=1):
    r, c = pos
    dr, dc = DIRS[d]
    return (r + dr * step, c + dc * step)


def parse_clues(observation):
    data = observation['data']
    n = len(data) - 1
    clues = []
    for r in range(n + 1):
        for c in range(n + 1):
            tok = data[r][c]
            if tok is not None:
                clues.append(((r, c), tok[0], int(tok[1:])))
    return n, clues


def basic_domain_for_token(tok):
    if tok is None:
        return set(ALL_STATES)
    if tok[0] == 'W':
        return {'H', 'V'}
    return {'NE', 'NW', 'SE', 'SW'}


def build_neighbors(n):
    nbrs = {}
    for r in range(n + 1):
        for c in range(n + 1):
            d = {}
            for k, (dr, dc) in DIRS.items():
                rr, cc = r + dr, c + dc
                if in_bounds(rr, cc, n):
                    d[k] = (rr, cc)
            nbrs[(r, c)] = d
    return nbrs


def generate_clue_patterns(pos, kind, k, n, token_map):
    r, c = pos
    patterns = []

    def add_pattern(reqs):
        # reqs: dict pos -> set(states)
        merged = {}
        for p, allowed in reqs.items():
            allowed = set(allowed)
            if not allowed:
                return
            if p in merged:
                merged[p] &= allowed
                if not merged[p]:
                    return
            else:
                merged[p] = allowed
            tok = token_map[p]
            if tok is not None:
                merged[p] &= basic_domain_for_token(tok)
                if not merged[p]:
                    return
        patterns.append(merged)

    if kind == 'W':
        # straight through; choose horizontal or vertical and positive lengths a,b with a+b=k
        for axis, d1, d2, clue_state, mid_state in (
            ('H', 'W', 'E', 'H', {'H'}),
            ('V', 'N', 'S', 'V', {'V'}),
        ):
            for a in range(1, k):
                b = k - a
                reqs = {pos: {clue_state}}
                ok = True

                # side 1
                for t in range(1, a):
                    p = move(pos, d1, t)
                    if not in_bounds(p[0], p[1], n):
                        ok = False
                        break
                    reqs[p] = set(mid_state)
                if not ok:
                    continue
                ep1 = move(pos, d1, a)
                if not in_bounds(ep1[0], ep1[1], n):
                    continue
                reqs[ep1] = set(TURN_STATES_USING[OPP[d1]])

                # side 2
                for t in range(1, b):
                    p = move(pos, d2, t)
                    if not in_bounds(p[0], p[1], n):
                        ok = False
                        break
                    if p in reqs:
                        reqs[p] &= mid_state
                    else:
                        reqs[p] = set(mid_state)
                    if not reqs[p]:
                        ok = False
                        break
                if not ok:
                    continue
                ep2 = move(pos, d2, b)
                if not in_bounds(ep2[0], ep2[1], n):
                    continue
                if ep2 in reqs:
                    reqs[ep2] &= TURN_STATES_USING[OPP[d2]]
                else:
                    reqs[ep2] = set(TURN_STATES_USING[OPP[d2]])
                if not reqs[ep2]:
                    continue

                add_pattern(reqs)

    else:
        # black clue: turn at clue. Four turn orientations.
        turns = [
            ('NE', 'N', 'E'),
            ('NW', 'N', 'W'),
            ('SE', 'S', 'E'),
            ('SW', 'S', 'W'),
        ]
        for clue_state, d1, d2 in turns:
            for a in range(1, k):
                b = k - a
                reqs = {pos: {clue_state}}
                ok = True

                # ray 1
                straight1 = {'V'} if d1 in ('N', 'S') else {'H'}
                for t in range(1, a):
                    p = move(pos, d1, t)
                    if not in_bounds(p[0], p[1], n):
                        ok = False
                        break
                    reqs[p] = set(straight1)
                if not ok:
                    continue
                ep1 = move(pos, d1, a)
                if not in_bounds(ep1[0], ep1[1], n):
                    continue
                reqs[ep1] = set(TURN_STATES_USING[OPP[d1]])

                # ray 2
                straight2 = {'V'} if d2 in ('N', 'S') else {'H'}
                for t in range(1, b):
                    p = move(pos, d2, t)
                    if not in_bounds(p[0], p[1], n):
                        ok = False
                        break
                    if p in reqs:
                        reqs[p] &= straight2
                    else:
                        reqs[p] = set(straight2)
                    if not reqs[p]:
                        ok = False
                        break
                if not ok:
                    continue
                ep2 = move(pos, d2, b)
                if not in_bounds(ep2[0], ep2[1], n):
                    continue
                if ep2 in reqs:
                    reqs[ep2] &= TURN_STATES_USING[OPP[d2]]
                else:
                    reqs[ep2] = set(TURN_STATES_USING[OPP[d2]])
                if not reqs[ep2]:
                    continue

                add_pattern(reqs)

    # Deduplicate patterns
    uniq = []
    seen = set()
    for p in patterns:
        key = tuple(sorted((q, tuple(sorted(v))) for q, v in p.items()))
        if key not in seen:
            seen.add(key)
            uniq.append(p)
    return uniq


def state_uses_dir(state, d):
    return d in STATE_DIRS[state]


def edge_supported_states(domain_a, domain_b, d):
    # support equality of edge use on both sides
    supported_a = set()
    opp = OPP[d]
    uses_b = {s for s in domain_b if state_uses_dir(s, opp)}
    not_b = domain_b - uses_b
    for sa in domain_a:
        if state_uses_dir(sa, d):
            if uses_b:
                supported_a.add(sa)
        else:
            if not_b:
                supported_a.add(sa)
    return supported_a


def forced_edges_from_singletons(domains, neighbors):
    edges = {}
    for p, dom in domains.items():
        if len(dom) != 1:
            continue
        st = next(iter(dom))
        for d, q in neighbors[p].items():
            key = tuple(sorted((p, q)))
            val = state_uses_dir(st, d)
            if key in edges and edges[key] != val:
                return None
            edges[key] = val
    return edges


def detect_bad_closed_component(domains, neighbors, clue_positions):
    # If singleton-forced "on" edges already form a closed cycle component that excludes some clue
    # or leaves room for more used vertices elsewhere, it is impossible.
    forced = forced_edges_from_singletons(domains, neighbors)
    if forced is None:
        return True
    on_edges = [e for e, v in forced.items() if v]
    if not on_edges:
        return False

    adj = {}
    for a, b in on_edges:
        adj.setdefault(a, []).append(b)
        adj.setdefault(b, []).append(a)

    seen = set()
    all_vertices = set(adj)
    clue_positions = set(clue_positions)

    for start in list(all_vertices):
        if start in seen:
            continue
        stack = [start]
        comp = set()
        edge_count = 0
        while stack:
            x = stack.pop()
            if x in comp:
                continue
            comp.add(x)
            for y in adj.get(x, ()):
                edge_count += 1
                if y not in comp:
                    stack.append(y)
        edge_count //= 2
        seen |= comp

        if comp and all(len(adj[v]) == 2 for v in comp):
            # Closed forced cycle.
            # Valid only if every non-empty-capable outside vertex is impossible and every clue is inside.
            if not clue_positions.issubset(comp):
                return True
            for p, dom in domains.items():
                if p not in comp and any(s != 'EMPTY' for s in dom):
                    return True
    return False


def propagate(domains, clue_patterns, neighbors, clue_positions):
    changed = True
    while changed:
        changed = False

        # Binary edge consistency
        for p, nbr_map in neighbors.items():
            dom_p = domains[p]
            new_dom_p = set(dom_p)
            for d, q in nbr_map.items():
                supported = edge_supported_states(new_dom_p, domains[q], d)
                if not supported:
                    return False
                if supported != new_dom_p:
                    new_dom_p = supported
            if new_dom_p != dom_p:
                domains[p] = new_dom_p
                changed = True

        # Symmetric pass can matter after reductions
        for p, nbr_map in neighbors.items():
            for d, q in nbr_map.items():
                supported_q = edge_supported_states(domains[q], domains[p], OPP[d])
                if not supported_q:
                    return False
                if supported_q != domains[q]:
                    domains[q] = supported_q
                    changed = True

        # Clue pattern filtering and support-based tightening
        for clue_pos, plist in clue_patterns.items():
            kept = []
            support = {}
            for pat in plist:
                ok = True
                for p, allowed in pat.items():
                    if not (domains[p] & allowed):
                        ok = False
                        break
                if ok:
                    kept.append(pat)
                    for p, allowed in pat.items():
                        support.setdefault(p, set()).update(allowed)
            if not kept:
                return False
            if len(kept) != len(plist):
                clue_patterns[clue_pos] = kept
                changed = True
            for p, allowed_union in support.items():
                nd = domains[p] & allowed_union
                if not nd:
                    return False
                if nd != domains[p]:
                    domains[p] = nd
                    changed = True

        # Basic clue cells cannot be empty
        for p in clue_positions:
            if 'EMPTY' in domains[p]:
                nd = set(domains[p])
                nd.remove('EMPTY')
                if not nd:
                    return False
                domains[p] = nd
                changed = True

        # Quick contradiction for forced premature closed cycle
        if detect_bad_closed_component(domains, neighbors, clue_positions):
            return False

    return True


def is_complete(domains, clue_patterns):
    return all(len(v) == 1 for v in domains.values()) and all(len(v) == 1 for v in clue_patterns.values())


def build_edge_graph(domains, neighbors):
    adj = {}
    for p, dom in domains.items():
        st = next(iter(dom))
        if st == 'EMPTY':
            continue
        for d, q in neighbors[p].items():
            if state_uses_dir(st, d):
                adj.setdefault(p, set()).add(q)
    # sanity symmetry
    for p, qs in list(adj.items()):
        for q in list(qs):
            if p not in adj.get(q, set()):
                return None
    return adj


def final_check(domains, clue_patterns, clue_positions, neighbors):
    if not is_complete(domains, clue_patterns):
        return False
    adj = build_edge_graph(domains, neighbors)
    if adj is None:
        return False

    used = set(adj.keys())
    if not clue_positions.issubset(used):
        return False

    # degree 2 on used vertices, 0 otherwise
    for p, dom in domains.items():
        st = next(iter(dom))
        deg = len(adj.get(p, ()))
        if st == 'EMPTY':
            if deg != 0:
                return False
        else:
            if deg != 2:
                return False

    # single connected loop
    if not used:
        return False
    start = next(iter(used))
    stack = [start]
    seen = set()
    while stack:
        x = stack.pop()
        if x in seen:
            continue
        seen.add(x)
        stack.extend(adj[x] - seen)
    if seen != used:
        return False

    return True


def extract_loop(domains, neighbors):
    adj = build_edge_graph(domains, neighbors)
    if not adj:
        return None
    start = min(adj)
    n1 = min(adj[start])
    path = [start]
    prev = start
    cur = n1
    while True:
        path.append(cur)
        nxts = list(adj[cur])
        if len(nxts) != 2:
            return None
        nxt = nxts[0] if nxts[1] == prev else nxts[1]
        prev, cur = cur, nxt
        if cur == start:
            path.append(start)
            break
    return path


def choose_branch(domains, clue_patterns):
    # Prefer clue-pattern branching because it reflects high-level human deductions
    best = None
    best_type = None
    for p, plist in clue_patterns.items():
        if 1 < len(plist) and (best is None or len(plist) < best):
            best = len(plist)
            best_type = ('clue', p)
    if best_type is not None:
        return best_type

    for p, dom in domains.items():
        if 1 < len(dom) and (best is None or len(dom) < best):
            best = len(dom)
            best_type = ('vertex', p)
    return best_type


def search(domains, clue_patterns, neighbors, clue_positions):
    if not propagate(domains, clue_patterns, neighbors, clue_positions):
        return None

    if final_check(domains, clue_patterns, clue_positions, neighbors):
        return domains, clue_patterns

    branch = choose_branch(domains, clue_patterns)
    if branch is None:
        return None

    typ, key = branch

    if typ == 'clue':
        # Least constraining / most specific first: patterns with more assigned positions first
        plist = clue_patterns[key]
        order = sorted(plist, key=lambda p: (-len(p), tuple(sorted(p.keys()))))
        for pat in order:
            nd = deepcopy(domains)
            np = deepcopy(clue_patterns)
            np[key] = [pat]
            res = search(nd, np, neighbors, clue_positions)
            if res is not None:
                return res
    else:
        dom = domains[key]
        # Value ordering: non-empty before empty, straights before turns on non-clue cells
        order = sorted(dom, key=lambda s: (s == 'EMPTY', s not in ('H', 'V'), s))
        for st in order:
            nd = deepcopy(domains)
            np = deepcopy(clue_patterns)
            nd[key] = {st}
            res = search(nd, np, neighbors, clue_positions)
            if res is not None:
                return res

    return None


def solve(observation):
    n, clues = parse_clues(observation)
    data = observation['data']
    token_map = {(r, c): data[r][c] for r in range(n + 1) for c in range(n + 1)}
    neighbors = build_neighbors(n)

    domains = {}
    for r in range(n + 1):
        for c in range(n + 1):
            domains[(r, c)] = basic_domain_for_token(data[r][c])

    clue_patterns = {}
    clue_positions = set()
    for pos, kind, k in clues:
        clue_positions.add(pos)
        pats = generate_clue_patterns(pos, kind, k, n, token_map)
        if not pats:
            return "No Solution"
        clue_patterns[pos] = pats

    res = search(domains, clue_patterns, neighbors, clue_positions)
    if res is None:
        return "No Solution"

    sol_domains, _ = res
    path = extract_loop(sol_domains, neighbors)
    return path if path is not None else "No Solution"


if __name__ == "__main__":
    print(solve(OBSERVATION))

