# General solver for a loop-on-dots puzzle with white/black numbered clue vertices.
# The solver is designed around:
# - vertex mode domains (unused / straight / turn variants)
# - clue-template enumeration (human-like "possible segment length decompositions")
# - aggressive propagation
# - bounded backtracking over clue templates, then edge completion
#
# Output: ordered closed loop path as a Python list of (row, col), or "No Solution".

from collections import defaultdict, deque

U, H, V, NE, NW, SE, SW = range(7)
ALL_MODES = (1 << 7) - 1

MODE_NAME = {
    U: "U",
    H: "H",
    V: "V",
    NE: "NE",
    NW: "NW",
    SE: "SE",
    SW: "SW",
}

DIRS = {
    "N": (-1, 0),
    "S": (1, 0),
    "W": (0, -1),
    "E": (0, 1),
}
OPP = {"N": "S", "S": "N", "W": "E", "E": "W"}

MODE_EDGES = {
    U: frozenset(),
    H: frozenset(("W", "E")),
    V: frozenset(("N", "S")),
    NE: frozenset(("N", "E")),
    NW: frozenset(("N", "W")),
    SE: frozenset(("S", "E")),
    SW: frozenset(("S", "W")),
}

EDGE_TO_MODES = {d: 0 for d in "NSEW"}
for m, es in MODE_EDGES.items():
    for d in "NSEW":
        if d in es:
            EDGE_TO_MODES[d] |= (1 << m)

TURN_MODES_WITH = {d: 0 for d in "NSEW"}
for m in (NE, NW, SE, SW):
    for d in MODE_EDGES[m]:
        TURN_MODES_WITH[d] |= (1 << m)

VERT_MASK = (1 << V)
HOR_MASK = (1 << H)
TURN_MASK = (1 << NE) | (1 << NW) | (1 << SE) | (1 << SW)
WHITE_MASK = HOR_MASK | VERT_MASK
BLACK_MASK = TURN_MASK

def bits(mask):
    while mask:
        b = mask & -mask
        yield (b.bit_length() - 1)
        mask -= b

def popcount(x):
    return x.bit_count()

def single_bit(mask):
    return mask and (mask & (mask - 1) == 0)

def bit_to_value(mask):
    return mask.bit_length() - 1

def edge_key(a, b):
    if a <= b:
        return (a, b)
    return (b, a)

def add_pos(pos, d, t=1):
    dr, dc = DIRS[d]
    return (pos[0] + dr * t, pos[1] + dc * t)

def in_bounds(pos, n):
    r, c = pos
    return 0 <= r <= n and 0 <= c <= n

def mode_mask_for_dirs(ds):
    out = 0
    s = frozenset(ds)
    for m, es in MODE_EDGES.items():
        if es == s:
            out |= (1 << m)
    return out

def endpoint_turn_mask(arrive_from_dir):
    # Endpoint receives path from opposite direction of outward ray.
    # Example outward E means endpoint must use W and turn => NW or SW.
    need = OPP[arrive_from_dir]
    return TURN_MODES_WITH[need]

class Template:
    __slots__ = ("req_modes", "req_edges", "clue_mode")
    def __init__(self, req_modes, req_edges, clue_mode):
        self.req_modes = req_modes      # dict vertex_id -> mask
        self.req_edges = req_edges      # tuple/list of edge_ids forced to 1
        self.clue_mode = clue_mode      # exact clue mode bit

class State:
    __slots__ = ("n", "vid_of", "pos_of", "edge_of", "edges", "mode_domains", "clue_domains", "applied_singletons")
    def __init__(self, n, vid_of, pos_of, edge_of, edges, mode_domains, clue_domains, applied_singletons):
        self.n = n
        self.vid_of = vid_of
        self.pos_of = pos_of
        self.edge_of = edge_of
        self.edges = edges              # list: -1 unknown, 0 absent, 1 present
        self.mode_domains = mode_domains
        self.clue_domains = clue_domains
        self.applied_singletons = applied_singletons

    def copy(self):
        return State(
            self.n,
            self.vid_of,
            self.pos_of,
            self.edge_of,
            self.edges[:],
            self.mode_domains[:],
            [d[:] for d in self.clue_domains],
            self.applied_singletons[:],
        )

def build_graph(n):
    vid_of = {}
    pos_of = []
    for r in range(n + 1):
        for c in range(n + 1):
            vid_of[(r, c)] = len(pos_of)
            pos_of.append((r, c))

    edge_of = {}
    edges = []
    for r in range(n + 1):
        for c in range(n):
            a = vid_of[(r, c)]
            b = vid_of[(r, c + 1)]
            edge_of[edge_key(a, b)] = len(edges)
            edges.append((a, b))
    for r in range(n):
        for c in range(n + 1):
            a = vid_of[(r, c)]
            b = vid_of[(r + 1, c)]
            edge_of[edge_key(a, b)] = len(edges)
            edges.append((a, b))
    return vid_of, pos_of, edge_of, edges

def incident_edges(state, vid):
    r, c = state.pos_of[vid]
    n = state.n
    out = {}
    if r > 0:
        out["N"] = state.edge_of[edge_key(vid, state.vid_of[(r - 1, c)])]
    if r < n:
        out["S"] = state.edge_of[edge_key(vid, state.vid_of[(r + 1, c)])]
    if c > 0:
        out["W"] = state.edge_of[edge_key(vid, state.vid_of[(r, c - 1)])]
    if c < n:
        out["E"] = state.edge_of[edge_key(vid, state.vid_of[(r, c + 1)])]
    return out

def set_edge(state, eid, val, queue):
    cur = state.edges[eid]
    if cur == val:
        return True
    if cur != -1 and cur != val:
        return False
    state.edges[eid] = val
    a, b = all_edges[eid]
    queue.append(("vertex", a))
    queue.append(("vertex", b))
    return True

def restrict_mode(state, vid, mask, queue):
    newmask = state.mode_domains[vid] & mask
    if newmask == 0:
        return False
    if newmask == state.mode_domains[vid]:
        return True
    state.mode_domains[vid] = newmask
    queue.append(("vertex", vid))
    return True

def template_consistent(state, template):
    for vid, mask in template.req_modes.items():
        if state.mode_domains[vid] & mask == 0:
            return False
    for eid in template.req_edges:
        if state.edges[eid] == 0:
            return False
    return True

def apply_template(state, template, queue):
    for vid, mask in template.req_modes.items():
        if not restrict_mode(state, vid, mask, queue):
            return False
    for eid in template.req_edges:
        if not set_edge(state, eid, 1, queue):
            return False
    return True

def propagate(state, clues, clue_templates, clue_vids, clue_type):
    queue = deque()
    for vid in range(len(state.mode_domains)):
        queue.append(("vertex", vid))
    for ci in range(len(clues)):
        queue.append(("clue", ci))

    while queue:
        typ, x = queue.popleft()

        if typ == "vertex":
            vid = x
            dom = state.mode_domains[vid]
            if dom == 0:
                return False

            inc = incident_edges(state, vid)

            # Remove impossible modes by current edge states and boundaries.
            newdom = 0
            for m in bits(dom):
                needed = MODE_EDGES[m]
                ok = True
                for d in "NSEW":
                    has_edge = d in inc
                    if d in needed:
                        if not has_edge:
                            ok = False
                            break
                        if state.edges[inc[d]] == 0:
                            ok = False
                            break
                    else:
                        if has_edge and state.edges[inc[d]] == 1:
                            ok = False
                            break
                if ok:
                    newdom |= (1 << m)
            if newdom == 0:
                return False
            if newdom != dom:
                state.mode_domains[vid] = newdom
                dom = newdom

            # If singleton mode, push edge consequences.
            if single_bit(dom):
                m = bit_to_value(dom)
                needed = MODE_EDGES[m]
                for d, eid in inc.items():
                    want = 1 if d in needed else 0
                    if not set_edge(state, eid, want, queue):
                        return False

            # Degree logic: clues cannot be unused; non-clues may be unused or degree 2.
            edge_vals = [state.edges[eid] for eid in inc.values()]
            forced1 = sum(v == 1 for v in edge_vals)
            unknown = sum(v == -1 for v in edge_vals)
            if forced1 > 2:
                return False
            if forced1 + unknown < 2 and not (state.mode_domains[vid] & (1 << U)):
                return False

            # If U impossible by any present edge, remove it.
            if forced1 > 0:
                if not restrict_mode(state, vid, ALL_MODES ^ (1 << U), queue):
                    return False

            # If degree-2 forced.
            dom = state.mode_domains[vid]
            allows_u = bool(dom & (1 << U))
            if not allows_u:
                if forced1 == 2:
                    for eid in inc.values():
                        if state.edges[eid] == -1:
                            if not set_edge(state, eid, 0, queue):
                                return False
                elif forced1 + unknown == 2:
                    for eid in inc.values():
                        if state.edges[eid] == -1:
                            if not set_edge(state, eid, 1, queue):
                                return False
            else:
                # If any edge forced1, U impossible; already handled. If all non-U modes impossible from edge counts, trim.
                pass

        else:
            ci = x
            dom = state.clue_domains[ci]
            if not dom:
                return False
            kept = []
            for tidx in dom:
                t = clue_templates[ci][tidx]
                if template_consistent(state, t):
                    kept.append(tidx)
            if not kept:
                return False
            if kept != dom:
                state.clue_domains[ci] = kept
                dom = kept

            if len(dom) == 1 and not state.applied_singletons[ci]:
                state.applied_singletons[ci] = True
                if not apply_template(state, clue_templates[ci][dom[0]], queue):
                    return False

            # Shared inference from all remaining templates: intersect required clue mode.
            mask = 0
            for tidx in dom:
                mask |= clue_templates[ci][tidx].clue_mode
            if not restrict_mode(state, clue_vids[ci], mask, queue):
                return False

    return True

def enumerate_templates(observation, vid_of, edge_of):
    data = observation["data"]
    n = len(data) - 1
    clues = []
    clue_vids = []
    clue_type = []
    clue_templates = []

    for r in range(n + 1):
        for c in range(n + 1):
            tok = data[r][c]
            if tok is None:
                continue
            t = tok[0]
            k = int(tok[1:])
            pos = (r, c)
            vid = vid_of[pos]
            clues.append((pos, t, k))
            clue_vids.append(vid)
            clue_type.append(t)

            templates = []

            def path_edges(start, d, length):
                out = []
                cur = start
                for _ in range(length):
                    nxt = add_pos(cur, d, 1)
                    a = vid_of[cur]
                    b = vid_of[nxt]
                    out.append(edge_of[edge_key(a, b)])
                    cur = nxt
                return out

            def ray_requirements(start, d, length, req_modes, req_edges):
                # intermediate straight vertices
                axis_mask = VERT_MASK if d in ("N", "S") else HOR_MASK
                for tlen in range(1, length):
                    p = add_pos(start, d, tlen)
                    v = vid_of[p]
                    req_modes[v] = req_modes.get(v, ALL_MODES) & axis_mask
                    if req_modes[v] == 0:
                        return False
                # endpoint turn vertex using incoming ray edge
                ep = add_pos(start, d, length)
                vep = vid_of[ep]
                epmask = endpoint_turn_mask(d)
                req_modes[vep] = req_modes.get(vep, ALL_MODES) & epmask
                if req_modes[vep] == 0:
                    return False
                req_edges.extend(path_edges(start, d, length))
                return True

            if t == "W":
                choices = [
                    (("N", "S"), VERT_MASK),
                    (("W", "E"), HOR_MASK),
                ]
                for dirs, cluemask in choices:
                    for a in range(1, k):
                        b = k - a
                        p1 = add_pos(pos, dirs[0], a)
                        p2 = add_pos(pos, dirs[1], b)
                        if not in_bounds(p1, n) or not in_bounds(p2, n):
                            continue
                        req_modes = {vid: cluemask}
                        req_edges = []
                        ok = ray_requirements(pos, dirs[0], a, req_modes, req_edges)
                        if ok:
                            ok = ray_requirements(pos, dirs[1], b, req_modes, req_edges)
                        if ok:
                            templates.append(Template(req_modes, tuple(dict.fromkeys(req_edges)), cluemask))
            else:
                choices = [
                    (("N", "E"), 1 << NE),
                    (("N", "W"), 1 << NW),
                    (("S", "E"), 1 << SE),
                    (("S", "W"), 1 << SW),
                ]
                for dirs, cluemask in choices:
                    for a in range(1, k):
                        b = k - a
                        p1 = add_pos(pos, dirs[0], a)
                        p2 = add_pos(pos, dirs[1], b)
                        if not in_bounds(p1, n) or not in_bounds(p2, n):
                            continue
                        req_modes = {vid: cluemask}
                        req_edges = []
                        ok = ray_requirements(pos, dirs[0], a, req_modes, req_edges)
                        if ok:
                            ok = ray_requirements(pos, dirs[1], b, req_modes, req_edges)
                        if ok:
                            templates.append(Template(req_modes, tuple(dict.fromkeys(req_edges)), cluemask))

            clue_templates.append(templates)

    return clues, clue_vids, clue_type, clue_templates

def select_clue_for_branch(state):
    best = None
    best_len = 10**9
    for ci, dom in enumerate(state.clue_domains):
        if 1 < len(dom) < best_len:
            best = ci
            best_len = len(dom)
    return best

def partial_cycle_prune(state, clue_vid_set):
    # Reject any fully-closed smaller cycle already formed.
    used_adj = defaultdict(list)
    used_vertices = set()
    for eid, val in enumerate(state.edges):
        if val != 1:
            continue
        a, b = all_edges[eid]
        used_adj[a].append(b)
        used_adj[b].append(a)
        used_vertices.add(a)
        used_vertices.add(b)

    seen = set()
    for s in used_vertices:
        if s in seen:
            continue
        comp = []
        stack = [s]
        seen.add(s)
        edge_count_twice = 0
        full_deg2 = True
        while stack:
            v = stack.pop()
            comp.append(v)
            deg = len(used_adj[v])
            edge_count_twice += deg
            if deg != 2:
                full_deg2 = False
            for w in used_adj[v]:
                if w not in seen:
                    seen.add(w)
                    stack.append(w)
        ecount = edge_count_twice // 2
        if full_deg2 and ecount == len(comp):
            # closed cycle found in forced edges
            # only acceptable if all clue vertices that must be on loop are in this component and no other undecided used edges exist
            if not clue_vid_set.issubset(set(comp)):
                return False
            # if there are unknown edges anywhere, premature full-cycle is bad
            if any(v == -1 for v in state.edges):
                return False
    return True

def search_clues(state, clues, clue_templates, clue_vids, clue_type):
    if not propagate(state, clues, clue_templates, clue_vids, clue_type):
        return None
    clue_vid_set = set(clue_vids)
    if not partial_cycle_prune(state, clue_vid_set):
        return None

    ci = select_clue_for_branch(state)
    if ci is None:
        return search_edges(state, clue_vid_set)

    # Heuristic: sort templates by number of currently forced edge agreements / requirements.
    order = []
    for tidx in state.clue_domains[ci]:
        t = clue_templates[ci][tidx]
        score = 0
        for eid in t.req_edges:
            if state.edges[eid] == 1:
                score += 2
            elif state.edges[eid] == -1:
                score += 1
        score += len(t.req_modes)
        order.append((-score, tidx))
    order.sort()

    for _, tidx in order:
        ns = state.copy()
        ns.clue_domains[ci] = [tidx]
        ns.applied_singletons[ci] = False
        ans = search_clues(ns, clues, clue_templates, clue_vids, clue_type)
        if ans is not None:
            return ans
    return None

def choose_unknown_edge(state):
    best_eid = None
    best_score = None
    for eid, val in enumerate(state.edges):
        if val != -1:
            continue
        a, b = all_edges[eid]
        score = popcount(state.mode_domains[a]) + popcount(state.mode_domains[b])
        if best_score is None or score < best_score:
            best_score = score
            best_eid = eid
    return best_eid

def final_check_and_extract(state, clue_vid_set):
    # Every vertex degree 0 or 2; clues degree 2.
    used_adj = defaultdict(list)
    used_vertices = set()
    for eid, val in enumerate(state.edges):
        if val != 1:
            continue
        a, b = all_edges[eid]
        used_adj[a].append(b)
        used_adj[b].append(a)
        used_vertices.add(a)
        used_vertices.add(b)

    for vid, dom in enumerate(state.mode_domains):
        deg = len(used_adj[vid])
        if deg not in (0, 2):
            return None
        if vid in clue_vid_set and deg != 2:
            return None

    if not clue_vid_set.issubset(used_vertices):
        return None
    if not used_vertices:
        return None

    # Single cycle connectivity
    start = next(iter(used_vertices))
    seen = set([start])
    dq = [start]
    while dq:
        v = dq.pop()
        for w in used_adj[v]:
            if w not in seen:
                seen.add(w)
                dq.append(w)
    if seen != used_vertices:
        return None

    # Extract ordered cycle
    path = [start]
    prev = None
    cur = start
    while True:
        nxts = used_adj[cur]
        if prev is None:
            nxt = nxts[0]
        else:
            nxt = nxts[0] if nxts[1] == prev else nxts[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break

    return [state.pos_of[v] for v in path]

def search_edges(state, clue_vid_set):
    if not propagate(state, clues_global, clue_templates_global, clue_vids_global, clue_type_global):
        return None
    if not partial_cycle_prune(state, clue_vid_set):
        return None

    eid = choose_unknown_edge(state)
    if eid is None:
        return final_check_and_extract(state, clue_vid_set)

    # Try 1 first: loop edges are sparse but clue templates often force positives.
    for val in (1, 0):
        ns = state.copy()
        q = deque()
        if set_edge(ns, eid, val, q):
            if search_edges(ns, clue_vid_set) is not None:
                return search_edges(ns, clue_vid_set)
    return None

def solve(observation):
    global all_edges, clues_global, clue_templates_global, clue_vids_global, clue_type_global

    data = observation["data"]
    n = len(data) - 1
    vid_of, pos_of, edge_of, all_edges = build_graph(n)

    clues, clue_vids, clue_type, clue_templates = enumerate_templates(observation, vid_of, edge_of)
    clues_global = clues
    clue_templates_global = clue_templates
    clue_vids_global = clue_vids
    clue_type_global = clue_type

    if any(len(ts) == 0 for ts in clue_templates):
        return "No Solution"

    num_vertices = (n + 1) * (n + 1)
    mode_domains = [ALL_MODES for _ in range(num_vertices)]

    clue_set = set(clue_vids)
    for vid in range(num_vertices):
        if vid in clue_set:
            continue
        # Non-clue vertices may be unused or any 2-edge mode.
        mode_domains[vid] = ALL_MODES

    # Restrict clue domains by clue color.
    for (pos, t, k), vid in zip(clues, clue_vids):
        if t == "W":
            mode_domains[vid] = WHITE_MASK
        else:
            mode_domains[vid] = BLACK_MASK

    state = State(
        n=n,
        vid_of=vid_of,
        pos_of=pos_of,
        edge_of=edge_of,
        edges=[-1] * len(all_edges),
        mode_domains=mode_domains,
        clue_domains=[list(range(len(ts))) for ts in clue_templates],
        applied_singletons=[False] * len(clues),
    )

    ans = search_clues(state, clues, clue_templates, clue_vids, clue_type)
    return ans if ans is not None else "No Solution"

if __name__ == "__main__":
    print(solve(OBSERVATION))

OBSERVATION = {'data': [[None, None, None, None, None, None, None, 'B', None, None], [None, 'W', None, None, None, None, 'B', None, None, 'W'], [None, None, None, None, None, None, None, None, None, None], ['W', None, None, 'B', None, None, 'W', None, 'W', None], [None, 'B', None, 'W', None, 'W', None, None, None, None], [None, None, 'B', None, None, None, 'W', 'W', None, 'W'], [None, 'W', None, None, None, 'W', None, 'W', None, None], [None, None, None, None, None, None, 'W', None, 'W', None], [None, None, None, None, 'B', None, 'W', 'W', None, None], ['B', None, None, None, None, None, None, None, None, None]]}

from collections import deque

# Masyu on dot-vertices:
# - Loop uses edges between orthogonally adjacent dots.
# - White clue: straight through clue, and at least one adjacent vertex along the loop is a turn.
# - Black clue: turn at clue, and both adjacent vertices along the loop are straight.

DIRS = {
    'U': (-1, 0),
    'D': (1, 0),
    'L': (0, -1),
    'R': (0, 1),
}
OPP = {'U': 'D', 'D': 'U', 'L': 'R', 'R': 'L'}
PERP = {
    'U': ('L', 'R'),
    'D': ('L', 'R'),
    'L': ('U', 'D'),
    'R': ('U', 'D'),
}


def solve(observation):
    data = observation['data']
    n = len(data)
    assert all(len(row) == n for row in data)

    # Edge indexing
    edge_id = {}
    edges = []
    incident = [[[] for _ in range(n)] for _ in range(n)]
    dir_edge = [[{} for _ in range(n)] for _ in range(n)]

    def add_edge(a, b):
        i = len(edges)
        edge_id[(a, b)] = i
        edge_id[(b, a)] = i
        edges.append((a, b))
        ar, ac = a
        br, bc = b
        incident[ar][ac].append(i)
        incident[br][bc].append(i)
        if br == ar - 1 and bc == ac:
            dir_edge[ar][ac]['U'] = i
            dir_edge[br][bc]['D'] = i
        elif br == ar + 1 and bc == ac:
            dir_edge[ar][ac]['D'] = i
            dir_edge[br][bc]['U'] = i
        elif br == ar and bc == ac - 1:
            dir_edge[ar][ac]['L'] = i
            dir_edge[br][bc]['R'] = i
        elif br == ar and bc == ac + 1:
            dir_edge[ar][ac]['R'] = i
            dir_edge[br][bc]['L'] = i

    for r in range(n):
        for c in range(n):
            if r + 1 < n:
                add_edge((r, c), (r + 1, c))
            if c + 1 < n:
                add_edge((r, c), (r, c + 1))

    clues = [(r, c) for r in range(n) for c in range(n) if data[r][c] in ('W', 'B')]
    clue_set = set(clues)

    def neighbor(v, d):
        r, c = v
        dr, dc = DIRS[d]
        nr, nc = r + dr, c + dc
        if 0 <= nr < n and 0 <= nc < n:
            return (nr, nc)
        return None

    def edge_from(v, d):
        r, c = v
        return dir_edge[r][c].get(d)

    # Pattern generation for clues
    # A pattern is a dict: edge_index -> 0/1.
    clue_patterns = {}

    def require(assign, e, val):
        if e is None:
            return False
        old = assign.get(e)
        if old is not None and old != val:
            return False
        assign[e] = val
        return True

    def apply_vertex_shape(assign, v, incoming_from, shape):
        # incoming_from is direction from this vertex to the previous vertex on path.
        # shape: 'S', 'L', 'R' where straight or turn to first/second perpendicular.
        if v is None:
            return None
        vin = OPP[incoming_from]  # edge actually used at v toward previous vertex
        if edge_from(v, vin) is None:
            return None
        if shape == 'S':
            dout = incoming_from
            on_dirs = {vin, dout}
            off_dirs = set(DIRS) - on_dirs
        elif shape == 'L':
            pd = PERP[incoming_from][0]
            on_dirs = {vin, pd}
            off_dirs = set(DIRS) - on_dirs
        elif shape == 'R':
            pd = PERP[incoming_from][1]
            on_dirs = {vin, pd}
            off_dirs = set(DIRS) - on_dirs
        else:
            return None
        out = dict(assign)
        for d in on_dirs:
            if not require(out, edge_from(v, d), 1):
                return None
        for d in off_dirs:
            e = edge_from(v, d)
            if e is not None and not require(out, e, 0):
                return None
        return out

    for v in clues:
        r, c = v
        typ = data[r][c]
        pats = []

        if typ == 'B':
            # Turn at clue, adjacent vertices on both sides straight.
            for d1, d2 in (('U', 'R'), ('R', 'D'), ('D', 'L'), ('L', 'U')):
                assign = {}
                ok = True
                on_dirs = {d1, d2}
                off_dirs = set(DIRS) - on_dirs
                for d in on_dirs:
                    ok &= require(assign, edge_from(v, d), 1)
                for d in off_dirs:
                    e = edge_from(v, d)
                    if e is not None:
                        ok &= require(assign, e, 0)
                if not ok:
                    continue
                v1 = neighbor(v, d1)
                v2 = neighbor(v, d2)
                assign = apply_vertex_shape(assign, v1, OPP[d1], 'S')
                if assign is None:
                    continue
                assign = apply_vertex_shape(assign, v2, OPP[d2], 'S')
                if assign is None:
                    continue
                pats.append(assign)

        else:  # White
            # Straight through clue. At least one adjacent vertex along path is a turn.
            for a, b in (('U', 'D'), ('L', 'R')):
                base = {}
                ok = True
                for d in (a, b):
                    ok &= require(base, edge_from(v, d), 1)
                for d in set(DIRS) - {a, b}:
                    e = edge_from(v, d)
                    if e is not None:
                        ok &= require(base, e, 0)
                if not ok:
                    continue
                options_a = ('S', 'L', 'R')
                options_b = ('S', 'L', 'R')
                for sa in options_a:
                    for sb in options_b:
                        if sa == 'S' and sb == 'S':
                            continue
                        assign = dict(base)
                        va = neighbor(v, a)
                        vb = neighbor(v, b)
                        assign = apply_vertex_shape(assign, va, OPP[a], sa)
                        if assign is None:
                            continue
                        assign = apply_vertex_shape(assign, vb, OPP[b], sb)
                        if assign is None:
                            continue
                        pats.append(assign)

        # Deduplicate patterns
        seen = set()
        dedup = []
        for p in pats:
            key = tuple(sorted(p.items()))
            if key not in seen:
                seen.add(key)
                dedup.append(p)
        clue_patterns[v] = dedup
        if not dedup:
            return "No Solution"

    all_edges = len(edges)
    initial_state = [-1] * all_edges  # -1 unknown, 0 off, 1 on

    def clone_domains(domains):
        return {k: list(v) for k, v in domains.items()}

    def set_edge(state, e, val, qv):
        cur = state[e]
        if cur == val:
            return True
        if cur != -1:
            return False
        state[e] = val
        a, b = edges[e]
        qv.append(a)
        qv.append(b)
        return True

    def filter_clue_domains(state, domains, qv):
        changed = True
        while changed:
            changed = False
            for v in clues:
                pats = domains[v]
                new_pats = []
                for p in pats:
                    ok = True
                    for e, val in p.items():
                        sv = state[e]
                        if sv != -1 and sv != val:
                            ok = False
                            break
                    if ok:
                        new_pats.append(p)
                if not new_pats:
                    return False
                if len(new_pats) != len(pats):
                    domains[v] = new_pats
                    changed = True
                # If all patterns agree on an edge, force it.
                forced = {}
                first = new_pats[0]
                for e in first:
                    val = first[e]
                    same = True
                    for p in new_pats[1:]:
                        if p.get(e) != val:
                            same = False
                            break
                    if same:
                        forced[e] = val
                for e, val in forced.items():
                    if not set_edge(state, e, val, qv):
                        return False
        return True

    def propagate_vertices(state, qv):
        while qv:
            r, c = qv.popleft()
            inc = incident[r][c]
            vals = [state[e] for e in inc]
            on = sum(v == 1 for v in vals)
            off = sum(v == 0 for v in vals)
            unk_edges = [e for e in inc if state[e] == -1]
            unk = len(unk_edges)

            clue = data[r][c] in ('W', 'B')
            if clue:
                # Exact degree 2
                if on > 2 or on + unk < 2:
                    return False
                if on == 2:
                    for e in unk_edges:
                        if not set_edge(state, e, 0, qv):
                            return False
                elif on + unk == 2:
                    for e in unk_edges:
                        if not set_edge(state, e, 1, qv):
                            return False
            else:
                # Degree 0 or 2
                if on > 2:
                    return False
                if on == 1 and unk == 0:
                    return False
                if on == 1 and unk == 1:
                    if not set_edge(state, unk_edges[0], 1, qv):
                        return False
                if on == 2:
                    for e in unk_edges:
                        if not set_edge(state, e, 0, qv):
                            return False
                if on == 0 and unk == 1:
                    if not set_edge(state, unk_edges[0], 0, qv):
                        return False
        return True

    def detect_premature_cycle(state):
        # Build graph of ON edges
        on_adj = {}
        on_vertices = set()
        for e, val in enumerate(state):
            if val == 1:
                a, b = edges[e]
                on_vertices.add(a)
                on_vertices.add(b)
                on_adj.setdefault(a, []).append(b)
                on_adj.setdefault(b, []).append(a)

        seen = set()
        comps = []
        for v in on_vertices:
            if v in seen:
                continue
            stack = [v]
            seen.add(v)
            comp = []
            cyc = True
            while stack:
                x = stack.pop()
                comp.append(x)
                if len(on_adj.get(x, [])) != 2:
                    cyc = False
                for y in on_adj.get(x, []):
                    if y not in seen:
                        seen.add(y)
                        stack.append(y)
            comps.append((comp, cyc))

        cycle_comps = [set(comp) for comp, cyc in comps if cyc]
        if not cycle_comps:
            return False

        # If any closed component exists before full completion, reject.
        # Allow only if there is exactly one closed component, all clue vertices are on it,
        # and all edges are assigned (final validation handles the rest).
        if len(cycle_comps) != 1:
            return True
        comp = cycle_comps[0]
        if not all(v in comp for v in clue_set):
            return True
        if any(v == -1 for v in state):
            return True
        return False

    def final_check(state):
        # All clues degree 2 and all non-clues degree 0 or 2 already enforced.
        # Need exactly one loop through all clues.
        if any(v == -1 for v in state):
            return False
        if detect_premature_cycle(state):
            return False

        on_adj = {}
        for e, val in enumerate(state):
            if val == 1:
                a, b = edges[e]
                on_adj.setdefault(a, []).append(b)
                on_adj.setdefault(b, []).append(a)

        if not on_adj:
            return False
        for v, ns in on_adj.items():
            if len(ns) != 2:
                return False

        start = next(iter(on_adj))
        seen = {start}
        stack = [start]
        while stack:
            x = stack.pop()
            for y in on_adj[x]:
                if y not in seen:
                    seen.add(y)
                    stack.append(y)
        if set(on_adj) != seen:
            return False
        if not all(v in seen for v in clue_set):
            return False
        return True

    def choose_branch(state, domains):
        # Prefer clue with smallest domain > 1
        best = None
        best_len = 10**9
        for v in clues:
            l = len(domains[v])
            if 1 < l < best_len:
                best_len = l
                best = ('clue', v)
        if best is not None:
            return best

        # Otherwise choose an unknown edge near a clue if possible
        clue_touch = set()
        for v in clues:
            r, c = v
            clue_touch.update(incident[r][c])
            for d in DIRS:
                nb = neighbor(v, d)
                if nb is not None:
                    clue_touch.update(incident[nb[0]][nb[1]])

        for e in clue_touch:
            if state[e] == -1:
                return ('edge', e)
        for e, val in enumerate(state):
            if val == -1:
                return ('edge', e)
        return None

    def propagate(state, domains):
        qv = deque(clues)
        if not filter_clue_domains(state, domains, qv):
            return False
        if not propagate_vertices(state, qv):
            return False
        while True:
            prev_unknown = state.count(-1)
            if not filter_clue_domains(state, domains, qv):
                return False
            if not propagate_vertices(state, qv):
                return False
            if detect_premature_cycle(state):
                return False
            if state.count(-1) == prev_unknown and not qv:
                break
        return True

    def search(state, domains):
        if not propagate(state, domains):
            return None
        if final_check(state):
            return state

        branch = choose_branch(state, domains)
        if branch is None:
            return None

        kind, obj = branch
        if kind == 'clue':
            v = obj
            # Try each pattern as a branch by restricting its domain to one pattern.
            pats = domains[v]
            for p in sorted(pats, key=lambda d: -sum(val == 1 for val in d.values())):
                ns = state[:]
                nd = clone_domains(domains)
                nd[v] = [p]
                res = search(ns, nd)
                if res is not None:
                    return res
            return None
        else:
            e = obj
            # Branch order heuristic: try ON first unless that quickly violates degree.
            for val in (1, 0):
                ns = state[:]
                nd = clone_domains(domains)
                qv = deque()
                if not set_edge(ns, e, val, qv):
                    continue
                if not propagate_vertices(ns, qv):
                    continue
                res = search(ns, nd)
                if res is not None:
                    return res
            return None

    domains = {v: list(ps) for v, ps in clue_patterns.items()}
    result = search(initial_state, domains)
    if result is None:
        return "No Solution"

    # Reconstruct ordered closed loop path
    on_adj = {}
    for e, val in enumerate(result):
        if val == 1:
            a, b = edges[e]
            on_adj.setdefault(a, []).append(b)
            on_adj.setdefault(b, []).append(a)

    start = min(on_adj)
    path = [start]
    prev = None
    cur = start
    while True:
        ns = on_adj[cur]
        nxt = ns[0] if ns[0] != prev else ns[1]
        path.append(nxt)
        prev, cur = cur, nxt
        if cur == start:
            break

    return path


if __name__ == "__main__":
    print(solve(OBSERVATION))
